{
  "name": "销售数据洞察专家 (Sales Insight Pro)",
  "description": "一个功能强大的销售数据分析应用，支持对出库单、客户、销售员、品类等多维度的交互式分析，并集成 Gemini AI 提供智能商业洞察。",
  "requestFramePermissions": []
}

export interface SalesRecord {
  id: string; // 出库单号
  month: string; // 月份
  date: string; // 业务日期
  customer: string; // 客户
  salesperson: string; // 销售员
  category: string; // 品类
  itemName: string; // 物料名称
  quantity: number; // 数量
  unitPrice: number; // 单价
  totalAmount: number; // 价税合计
}

export interface SalesSummary {
  totalSales: number;
  totalQuantity: number;
  orderCount: number;
  avgOrderValue: number;
  categoryDistribution: { name: string; value: number }[];
  salespersonPerformance: { name: string; value: number }[];
  monthlyTrend: { name: string; sales: number; quantity: number }[];
}

export interface FilterState {
  dateRange: [string, string];
  salesperson: string;
  category: string;
  customer: string;
}

import { SalesRecord } from './types';

// 生成模拟数据
const customers = ['阿里巴巴', '腾讯', '百度', '京东', '美团', '字节跳动', '华为', '小米'];
const salespeople = ['张三', '李四', '王五', '赵六', '钱七', '孙八'];
const categories = ['办公用品', '电子产品', '软件服务', '咨询费', '硬件设备'];
const items: Record<string, string[]> = {
  '办公用品': ['笔记本', '打印纸', '签字笔', '文件夹'],
  '电子产品': ['显示器', '键盘', '鼠标', '移动硬盘'],
  '软件服务': ['云服务器', 'SaaS订阅', '数据库授权'],
  '咨询费': ['战略咨询', '技术支持', 'IT架构设计'],
  '硬件设备': ['服务器集群', '网络交换机', '防火墙']
};

export const MOCK_SALES_DATA: SalesRecord[] = Array.from({ length: 150 }).map((_, i) => {
  const category = categories[Math.floor(Math.random() * categories.length)];
  const itemName = items[category][Math.floor(Math.random() * items[category].length)];
  const quantity = Math.floor(Math.random() * 50) + 1;
  const unitPrice = Math.floor(Math.random() * 2000) + 100;
  const totalAmount = quantity * unitPrice;
  const date = new Date(2024, Math.floor(Math.random() * 12), Math.floor(Math.random() * 28) + 1);

  return {
    id: `CK-${2024000 + i}`,
    month: `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`,
    date: date.toISOString().split('T')[0],
    customer: customers[Math.floor(Math.random() * customers.length)],
    salesperson: salespeople[Math.floor(Math.random() * salespeople.length)],
    category,
    itemName,
    quantity,
    unitPrice,
    totalAmount
  };
}).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

import { GoogleGenAI } from "@google/genai";
import { SalesSummary } from "../types";

export const getAIInsights = async (summary: SalesSummary) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    作为一名资深业务分析师，请根据以下销售数据摘要进行深入分析并提供3-5条行动建议。

    数据摘要：
    - 总销售额: ¥${summary.totalSales.toLocaleString()}
    - 总销售数量: ${summary.totalQuantity}
    - 订单总数: ${summary.orderCount}
    - 平均订单金额: ¥${summary.avgOrderValue.toFixed(2)}

    主要品类分布:
    ${summary.categoryDistribution.map(c => `${c.name}: ¥${c.value}`).join(', ')}

    顶尖销售员表现:
    ${summary.salespersonPerformance.map(s => `${s.name}: ¥${s.value}`).join(', ')}

    请使用中文回答，重点关注业绩瓶颈、增长机会和运营建议。
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini AI Error:", error);
    return "抱歉，AI 洞察生成失败，请检查网络连接或稍后再试。";
  }
};

import React from 'react';
import { SalesRecord } from '../types';

interface DataTableProps {
  data: SalesRecord[];
}

const DataTable: React.FC<DataTableProps> = ({ data }) => {
  return (
    <div className="overflow-x-auto bg-white rounded-xl shadow-sm border border-slate-200">
      <table className="min-w-full divide-y divide-slate-200">
        <thead className="bg-slate-50">
          <tr>
            {['出库单号', '月份', '日期', '客户', '销售员', '品类', '物料名称', '数量', '单价', '价税合计'].map((header) => (
              <th key={header} className="px-6 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider whitespace-nowrap">
                {header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody className="bg-white divide-y divide-slate-200">
          {data.slice(0, 50).map((record) => (
            <tr key={record.id} className="hover:bg-slate-50 transition-colors">
              <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-blue-600">{record.id}</td>
              <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">{record.month}</td>
              <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">{record.date}</td>
              <td className="px-6 py-4 whitespace-nowrap text-sm font-semibold text-slate-900">{record.customer}</td>
              <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">{record.salesperson}</td>
              <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">
                <span className="px-2 py-1 bg-slate-100 rounded-md text-slate-700 text-xs">{record.category}</span>
              </td>
              <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">{record.itemName}</td>
              <td className="px-6 py-4 whitespace-nowrap text-sm text-right text-slate-600 font-mono">{record.quantity}</td>
              <td className="px-6 py-4 whitespace-nowrap text-sm text-right text-slate-600 font-mono">¥{record.unitPrice.toLocaleString()}</td>
              <td className="px-6 py-4 whitespace-nowrap text-sm text-right font-bold text-slate-900 font-mono">¥{record.totalAmount.toLocaleString()}</td>
            </tr>
          ))}
        </tbody>
      </table>
      {data.length > 50 && (
        <div className="px-6 py-4 text-center text-sm text-slate-500 italic bg-slate-50">
          仅显示前 50 条记录（共 {data.length} 条）
        </div>
      )}
