        {/* Decorative background circle */}
        <div className="absolute -bottom-24 -right-24 w-64 h-64 bg-indigo-500/20 rounded-full blur-3xl"></div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { MOCK_SALES_DATA } from './constants';
import { FilterState, SalesSummary, SalesRecord } from './types';
import Dashboard from './components/Dashboard';
import DataTable from './components/DataTable';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'table'>('dashboard');
  const [filters, setFilters] = useState<FilterState>({
    dateRange: ['', ''],
    salesperson: '',
    category: '',
    customer: ''
  });

  // Unique values for filters
  const filterOptions = useMemo(() => ({
    salespeople: Array.from(new Set(MOCK_SALES_DATA.map(d => d.salesperson))),
    categories: Array.from(new Set(MOCK_SALES_DATA.map(d => d.category))),
    customers: Array.from(new Set(MOCK_SALES_DATA.map(d => d.customer)))
  }), []);

  // Filtered data
  const filteredData = useMemo(() => {
    return MOCK_SALES_DATA.filter(item => {
      const matchSalesperson = !filters.salesperson || item.salesperson === filters.salesperson;
      const matchCategory = !filters.category || item.category === filters.category;
      const matchCustomer = !filters.customer || item.customer === filters.customer;
      const matchDate = (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
                        (!filters.dateRange[1] || item.date <= filters.dateRange[1]);
      return matchSalesperson && matchCategory && matchCustomer && matchDate;
    });
  }, [filters]);

  // Derived Summary
  const summary: SalesSummary = useMemo(() => {
    const totalSales = filteredData.reduce((acc, cur) => acc + cur.totalAmount, 0);
    const totalQuantity = filteredData.reduce((acc, cur) => acc + cur.quantity, 0);
    const orderCount = filteredData.length;
    const avgOrderValue = orderCount > 0 ? totalSales / orderCount : 0;

    // Monthly Trend
    const monthlyMap = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const existing = monthlyMap.get(d.month) || { sales: 0, quantity: 0 };
      monthlyMap.set(d.month, {
        sales: existing.sales + d.totalAmount,
        quantity: existing.quantity + d.quantity
      });
    });
    const monthlyTrend = Array.from(monthlyMap.entries())
      .map(([name, val]) => ({ name, ...val }))
      .sort((a, b) => a.name.localeCompare(b.name));

    // Category Distribution
    const catMap = new Map<string, number>();
    filteredData.forEach(d => {
      catMap.set(d.category, (catMap.get(d.category) || 0) + d.totalAmount);
    });
    const categoryDistribution = Array.from(catMap.entries()).map(([name, value]) => ({ name, value }));

    // Salesperson Performance
    const spMap = new Map<string, number>();
    filteredData.forEach(d => {
      spMap.set(d.salesperson, (spMap.get(d.salesperson) || 0) + d.totalAmount);
    });
    const salespersonPerformance = Array.from(spMap.entries())
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value);

    return { totalSales, totalQuantity, orderCount, avgOrderValue, categoryDistribution, salespersonPerformance, monthlyTrend };
  }, [filteredData]);

  const resetFilters = () => setFilters({ dateRange: ['', ''], salesperson: '', category: '', customer: '' });

  return (
    <div className="min-h-screen bg-slate-50 pb-12">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white text-2xl font-bold">S</div>
            <div>
              <h1 className="text-xl font-bold text-slate-900">销售数据洞察专家</h1>
              <p className="text-xs text-slate-500 hidden sm:block">智能数据分析平台</p>
            </div>
          </div>
          <nav className="flex bg-slate-100 p-1 rounded-lg">
            <button 
              onClick={() => setActiveTab('dashboard')}
              className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${activeTab === 'dashboard' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-600 hover:text-slate-900'}`}
            >
              数据看板
            </button>
            <button 
              onClick={() => setActiveTab('table')}
              className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${activeTab === 'table' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-600 hover:text-slate-900'}`}
            >
              明细数据
            </button>
          </nav>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-8">
        {/* Filter Section */}
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 mb-8">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-sm font-bold text-slate-800 uppercase tracking-widest flex items-center">
              <span className="w-1.5 h-4 bg-blue-600 rounded-full mr-2"></span>
              筛选控制台
            </h2>
            <button 
              onClick={resetFilters}
              className="text-sm text-slate-400 hover:text-blue-600 flex items-center transition-colors"
            >
              <svg className="w-4 h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
              重置筛选
            </button>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            <div>
              <label className="block text-xs font-semibold text-slate-500 mb-2 uppercase">销售员</label>
              <select 
                value={filters.salesperson}
                onChange={(e) => setFilters({...filters, salesperson: e.target.value})}
                className="w-full bg-slate-50 border-transparent focus:ring-2 focus:ring-blue-500 focus:bg-white rounded-lg px-3 py-2 text-sm text-slate-900 outline-none transition-all cursor-pointer"
              >
                <option value="">全部销售员</option>
                {filterOptions.salespeople.map(s => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-500 mb-2 uppercase">品类</label>
              <select 
                value={filters.category}
                onChange={(e) => setFilters({...filters, category: e.target.value})}
                className="w-full bg-slate-50 border-transparent focus:ring-2 focus:ring-blue-500 focus:bg-white rounded-lg px-3 py-2 text-sm text-slate-900 outline-none transition-all cursor-pointer"
              >
                <option value="">全部品类</option>
                {filterOptions.categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-500 mb-2 uppercase">客户</label>
              <select 
                value={filters.customer}
                onChange={(e) => setFilters({...filters, customer: e.target.value})}
                className="w-full bg-slate-50 border-transparent focus:ring-2 focus:ring-blue-500 focus:bg-white rounded-lg px-3 py-2 text-sm text-slate-900 outline-none transition-all cursor-pointer"
              >
                <option value="">全部客户</option>
                {filterOptions.customers.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>

            <div className="flex gap-2">
              <div className="flex-1">
                <label className="block text-xs font-semibold text-slate-500 mb-2 uppercase">开始日期</label>
                <input 
                  type="date"
                  value={filters.dateRange[0]}
                  onChange={(e) => setFilters({...filters, dateRange: [e.target.value, filters.dateRange[1]]})}
                  className="w-full bg-slate-50 border-transparent focus:ring-2 focus:ring-blue-500 focus:bg-white rounded-lg px-3 py-2 text-sm text-slate-900 outline-none transition-all"
                />
              </div>
              <div className="flex-1">
                <label className="block text-xs font-semibold text-slate-500 mb-2 uppercase">结束日期</label>
                <input 
                  type="date"
                  value={filters.dateRange[1]}
                  onChange={(e) => setFilters({...filters, dateRange: [filters.dateRange[0], e.target.value]})}
