import React, { useState, useMemo, useEffect } from 'react';
import { FilterState, SalesSummary, SalesRecord } from './types';
import Dashboard from './components/Dashboard';
import DataTable from './components/DataTable';
import MultiSelect from './components/MultiSelect';
import { fetchSalesData } from './services/dataService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'table'>('dashboard');
  const [allData, setAllData] = useState<SalesRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filters, setFilters] = useState<FilterState>({
    months: [],
    dateRange: ['', ''],
    customers: [],
    salespeople: [],
    categories: [],
    itemNames: []
  });

  useEffect(() => {
    const loadData = async () => {
      try {
        setIsLoading(true);
        const data = await fetchSalesData();
        setAllData(data);
        setError(null);
      } catch (err) {
        setError('数据加载失败。请确保 Google 表格已公开共享且格式正确。');
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  // 严格从表格数据中提取筛选选项
  const baseOptions = useMemo(() => ({
    months: Array.from(new Set(allData.map(d => d.month))).filter(Boolean).sort().reverse(),
    salespeople: Array.from(new Set(allData.map(d => d.salesperson))).filter(Boolean).sort(),
    categories: Array.from(new Set(allData.map(d => d.category))).filter(Boolean).sort(),
    customers: Array.from(new Set(allData.map(d => d.customer))).filter(Boolean).sort()
  }), [allData]);

  // 物料名称级联逻辑：根据选中的品类动态展示对应的物料名称
  const availableItemNames = useMemo(() => {
    const filteredByCat = filters.categories.length > 0 
      ? allData.filter(d => filters.categories.includes(d.category))
      : allData;
    return Array.from(new Set(filteredByCat.map(d => d.itemName))).filter(Boolean).sort();
  }, [allData, filters.categories]);

  // 多选筛选过滤逻辑
  const filteredData = useMemo(() => {
    return allData.filter(item => {
      const matchMonth = filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
                        (!filters.dateRange[1] || item.date <= filters.dateRange[1]);

      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });
  }, [allData, filters]);

  const summary: SalesSummary = useMemo(() => {
    const totalSales = filteredData.reduce((acc, cur) => acc + cur.totalAmount, 0);
    const totalQuantity = filteredData.reduce((acc, cur) => acc + cur.quantity, 0);
    const orderCount = filteredData.length;
    const avgOrderValue = orderCount > 0 ? totalSales / orderCount : 0;

    const monthlyMap = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const existing = monthlyMap.get(d.month) || { sales: 0, quantity: 0 };
      monthlyMap.set(d.month, {
        sales: existing.sales + d.totalAmount,
        quantity: existing.quantity + d.quantity
      });
    });
    const monthlyTrend = Array.from(monthlyMap.entries())
      .map(([name, val]) => ({ name, ...val }))
      .sort((a, b) => a.name.localeCompare(b.name));

    const catMap = new Map<string, number>();
    filteredData.forEach(d => {
      catMap.set(d.category, (catMap.get(d.category) || 0) + d.totalAmount);
    });
    const categoryDistribution = Array.from(catMap.entries()).map(([name, value]) => ({ name, value }));

    const spMap = new Map<string, number>();
    filteredData.forEach(d => {
      spMap.set(d.salesperson, (spMap.get(d.salesperson) || 0) + d.totalAmount);
    });
    const salespersonPerformance = Array.from(spMap.entries())
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value);

    return { totalSales, totalQuantity, orderCount, avgOrderValue, categoryDistribution, salespersonPerformance, monthlyTrend };
  }, [filteredData]);

  const resetFilters = () => setFilters({
    months: [],
    dateRange: ['', ''],
    customers: [],
    salespeople: [],
    categories: [],
    itemNames: []
  });

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 p-4 text-center">
        <div className="bg-white p-8 rounded-2xl shadow-xl max-w-md">
          <div className="text-6xl mb-4">⚠️</div>
          <h2 className="text-2xl font-bold text-slate-900 mb-2">连接失败</h2>
          <p className="text-slate-500 mb-6">{error}</p>
          <button onClick={() => window.location.reload()} className="inline-block bg-blue-600 text-white px-6 py-2 rounded-lg font-bold hover:bg-blue-700 transition-colors">
            重试连接
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 pb-12">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white text-2xl font-bold shadow-lg shadow-blue-200">S</div>
            <div>
              <div className="flex items-center gap-2">
                <h1 className="text-xl font-bold text-slate-900">销售数据洞察专家</h1>
                <span className="hidden md:flex bg-green-100 text-green-700 text-[10px] px-2 py-0.5 rounded-full font-bold items-center">
                  <span className="w-1.5 h-1.5 bg-green-500 rounded-full mr-1 animate-pulse"></span>
                  LIVE: GOOGLE SHEETS
                </span>
              </div>
              <p className="text-xs text-slate-500 hidden sm:block">多维动态分析台</p>
            </div>
          </div>
          <nav className="flex bg-slate-100 p-1 rounded-lg">
            <button 
              onClick={() => setActiveTab('dashboard')}
              className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${activeTab === 'dashboard' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-600 hover:text-slate-900'}`}
            >
              数据看板
            </button>
            <button 
              onClick={() => setActiveTab('table')}
              className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${activeTab === 'table' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-600 hover:text-slate-900'}`}
            >
              明细数据
            </button>
          </nav>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-8">
        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20 space-y-4">
            <div className="w-12 h-12 border-4 border-blue-200 border-t-blue-600 rounded-full animate-spin"></div>
            <p className="text-slate-500 font-medium">从云端同步销售记录...</p>
          </div>
        ) : (
          <>
            {/* Multi-Select Filter Section */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 mb-8">
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-sm font-bold text-slate-800 uppercase tracking-widest flex items-center">
                  <span className="w-1.5 h-4 bg-blue-600 rounded-full mr-2"></span>
                  高级筛选中心
                </h2>
                <div className="flex items-center gap-4">
                  <span className="text-xs text-slate-400 font-medium">符合当前条件: {filteredData.length} 条</span>
                  <button onClick={resetFilters} className="text-xs text-blue-600 hover:text-blue-700 font-bold uppercase tracking-wider transition-colors">
                    重置筛选
                  </button>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                <MultiSelect 
                  label="月份"
                  options={baseOptions.months}
                  selectedValues={filters.months}
                  onChange={(v) => setFilters({...filters, months: v})}
                  placeholder="所有月份"
                />
                <MultiSelect 
                  label="客户"
                  options={baseOptions.customers}
                  selectedValues={filters.customers}
                  onChange={(v) => setFilters({...filters, customers: v})}
                  placeholder="所有客户"
                />
                <MultiSelect 
                  label="销售员"
                  options={baseOptions.salespeople}
                  selectedValues={filters.salespeople}
                  onChange={(v) => setFilters({...filters, salespeople: v})}
                  placeholder="所有销售员"
                />
                <MultiSelect 
                  label="品类"
                  options={baseOptions.categories}
                  selectedValues={filters.categories}
                  onChange={(v) => setFilters({...filters, categories: v, itemNames: []})}
                  placeholder="所有品类"
                />

                {/* Second row */}
                <div className="lg:col-span-2">
                  <MultiSelect 
                    label="物料名称"
                    options={availableItemNames}
                    selectedValues={filters.itemNames}
                    onChange={(v) => setFilters({...filters, itemNames: v})}
                    placeholder={filters.categories.length > 0 ? "在该品类下选择..." : "所有物料"}
                  />
                </div>

                <div className="lg:col-span-2 flex gap-3">
                  <div className="flex-1">
                    <label className="block text-xs font-semibold text-slate-400 mb-1.5 uppercase tracking-wider">业务日期 (起)</label>
                    <input 
                      type="date"
                      value={filters.dateRange[0]}
                      onChange={(e) => setFilters({...filters, dateRange: [e.target.value, filters.dateRange[1]]})}
                      className="w-full bg-slate-50 border border-slate-200 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 rounded-lg px-3 py-2 text-sm text-slate-900 outline-none transition-all"
                    />
                  </div>
                  <div className="flex-1">
                    <label className="block text-xs font-semibold text-slate-400 mb-1.5 uppercase tracking-wider">业务日期 (止)</label>
                    <input 
                      type="date"
                      value={filters.dateRange[1]}
                      onChange={(e) => setFilters({...filters, dateRange: [filters.dateRange[0], e.target.value]})}
                      className="w-full bg-slate-50 border border-slate-200 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 rounded-lg px-3 py-2 text-sm text-slate-900 outline-none transition-all"
                    />
                  </div>
                </div>
              </div>
            </section>

            {/* Content Area */}
            <div className="animate-in fade-in duration-500">
              {filteredData.length > 0 ? (
                activeTab === 'dashboard' ? (
                  <Dashboard summary={summary} />
                ) : (
                  <DataTable data={filteredData} />
                )
              ) : (
                <div className="flex flex-col items-center justify-center py-24 bg-white rounded-3xl border border-dashed border-slate-200 shadow-inner">
                  <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6">
                    <span className="text-4xl text-slate-300">🔎</span>
                  </div>
                  <h3 className="text-xl font-bold text-slate-800">未找到匹配的销售记录</h3>
                  <p className="text-slate-500 mt-2 max-w-xs text-center">当前筛选组合下没有数据。请尝试放宽筛选条件或重置所有过滤器。</p>
                  <button onClick={resetFilters} className="mt-8 bg-blue-600 text-white px-8 py-3 rounded-xl text-sm font-bold shadow-lg shadow-blue-200 hover:bg-blue-700 transition-all">
                    重置所有筛选器
                  </button>
                </div>
              )}
            </div>
          </>
        )}
      </main>

      <footer className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-16 pb-12 text-center">
        <div className="pt-8 border-t border-slate-200">
          <p className="text-slate-400 text-xs font-medium tracking-widest uppercase mb-2">Sales Insight Pro</p>
          <p className="text-slate-300 text-[10px]">数据源: Google Spreadsheet · 智能引擎: Gemini 3 Flash</p>
        </div>
      </footer>
    </div>
  );
};

