              )}
            </div>
          </>
        )}
      </main>

      <footer className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-16 pb-12 text-center">
        <div className="pt-8 border-t border-slate-200">
          <p className="text-slate-400 text-xs font-medium tracking-widest uppercase mb-2">Sales Insight Pro</p>
          <p className="text-slate-300 text-[10px]">数据源: Google Spreadsheet · 智能引擎: Gemini 3 Flash</p>
        </div>
      </footer>
    </div>
  );
};

