import React, { useState, useRef, useEffect, useMemo } from 'react';

interface MultiSelectProps {
  label: string;
  options: string[];
  counts?: Record<string, number>; // 新增：每个选项对应的匹配记录数
  selectedValues: string[];
  onChange: (values: string[]) => void;
  placeholder?: string;
}

const MultiSelect: React.FC<MultiSelectProps> = ({ label, options, counts, selectedValues, onChange, placeholder }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (!isOpen) setSearchTerm('');
  }, [isOpen]);

  const filteredOptions = useMemo(() => {
    return options.filter(opt => opt.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [options, searchTerm]);

  const toggleOption = (option: string) => {
    const newValues = selectedValues.includes(option)
      ? selectedValues.filter(v => v !== option)
      : [...selectedValues, option];
    onChange(newValues);
  };

  const toggleAllFiltered = () => {
    const filteredAndNotSelected = filteredOptions.filter(opt => !selectedValues.includes(opt));
    if (filteredAndNotSelected.length > 0) {
      onChange(Array.from(new Set([...selectedValues, ...filteredOptions])));
    } else {
      onChange(selectedValues.filter(v => !filteredOptions.includes(v)));
    }
  };

  const displayText = useMemo(() => {
    if (selectedValues.length === 0) return placeholder || `选择${label}`;
    if (selectedValues.length === options.length && options.length > 0) return '全部';
    if (selectedValues.length <= 2) return selectedValues.join(', ');
    return `已选 ${selectedValues.length} 项`;
  }, [selectedValues, options, label, placeholder]);

  return (
    <div className="relative" ref={containerRef}>
      <label className="block text-xs font-semibold text-slate-400 mb-1.5 uppercase tracking-wider">{label}</label>

      <button
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        className={`w-full flex items-center justify-between bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm transition-all hover:bg-white hover:border-blue-300 ${isOpen ? 'ring-2 ring-blue-500/10 border-blue-500 bg-white' : ''}`}
      >
        <span className={`truncate mr-2 ${selectedValues.length > 0 ? 'text-slate-900 font-medium' : 'text-slate-400'}`}>
          {displayText}
        </span>
        <svg className={`w-4 h-4 text-slate-400 flex-shrink-0 transition-transform ${isOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" />
        </svg>
      </button>

      {isOpen && (
        <div className="absolute z-50 w-full mt-2 bg-white border border-slate-200 rounded-xl shadow-xl overflow-hidden animate-in fade-in zoom-in duration-100 origin-top min-w-[200px]">
          <div className="p-2 border-b border-slate-100 bg-slate-50/50">
            <div className="relative mb-2">
              <input 
                type="text"
                autoFocus
                placeholder="快速搜索..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-white border border-slate-200 rounded-md pl-8 pr-3 py-1.5 text-xs outline-none focus:border-blue-500 transition-all"
              />
              <svg className="w-3.5 h-3.5 absolute left-2.5 top-2.5 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </div>

            <div className="flex justify-between items-center px-1">
              <button 
                type="button"
                onClick={toggleAllFiltered}
                className="text-[11px] font-bold text-blue-600 hover:text-blue-700"
              >
                {filteredOptions.length > 0 && filteredOptions.every(opt => selectedValues.includes(opt)) ? '取消全选' : '全选结果'}
              </button>
              <span className="text-[10px] font-bold text-slate-400 uppercase">
                {filteredOptions.length} 个选项
              </span>
            </div>
          </div>

          <div className="max-h-60 overflow-y-auto p-1 custom-scrollbar">
            {filteredOptions.map(option => {
              const isSelected = selectedValues.includes(option);
              const count = counts ? (counts[option] || 0) : null;

              return (
                <div 
                  key={option} 
                  onClick={() => toggleOption(option)}
                  className={`flex items-center justify-between px-3 py-2 rounded-lg cursor-pointer transition-all group ${isSelected ? 'bg-blue-50' : 'hover:bg-slate-50'}`}
                >
                  <div className="flex items-center min-w-0">
                    <div className={`w-4 h-4 border rounded mr-3 flex items-center justify-center transition-all ${isSelected ? 'bg-blue-600 border-blue-600' : 'border-slate-300 bg-white group-hover:border-blue-400'}`}>
                      {isSelected && (
                        <svg className="w-2.5 h-2.5 text-white" fill="currentColor" viewBox="0 0 20 20">
                          <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                        </svg>
                      )}
                    </div>
                    <span className={`text-sm truncate ${isSelected ? 'text-blue-900 font-semibold' : 'text-slate-600'}`}>
                      {option}
                    </span>
                  </div>
                  {count !== null && (
                    <span className={`text-[10px] ml-2 px-1.5 py-0.5 rounded-full font-mono ${isSelected ? 'bg-blue-100 text-blue-600' : 'bg-slate-100 text-slate-400'}`}>
                      {count}
                    </span>
                  )}
                </div>
              );
            })}

            {filteredOptions.length === 0 && (
              <div className="py-8 text-center text-xs text-slate-400 italic">
                没有找到匹配的选项
              </div>
            )}
          </div>

          <div className="px-3 py-2 bg-slate-50 border-t border-slate-100 text-[10px] text-slate-500 flex justify-between items-center">
             <span>已选: {selectedValues.length} 项</span>
             {selectedValues.length > 0 && (
               <button 
                type="button" 
                onClick={() => onChange([])}
                className="text-red-500 hover:text-red-600 font-bold"
               >
                清空选择
               </button>
             )}
          </div>
        </div>
      )}
    </div>
  );
};

export default MultiSelect;

import React, { useState, useMemo, useEffect } from 'react';
import { FilterState, SalesSummary, SalesRecord } from './types';
import Dashboard from './components/Dashboard';
import DataTable from './components/DataTable';
import MultiSelect from './components/MultiSelect';
import { fetchSalesData } from './services/dataService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'table'>('dashboard');
  const [allData, setAllData] = useState<SalesRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filters, setFilters] = useState<FilterState>({
    months: [],
    dateRange: ['', ''],
    customers: [],
    salespeople: [],
    categories: [],
    itemNames: []
  });

  useEffect(() => {
    const loadData = async () => {
      try {
        setIsLoading(true);
        const data = await fetchSalesData();
        setAllData(data);
        setError(null);
      } catch (err) {
        setError('数据加载失败。请确保 Google 表格已公开共享且格式正确。');
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  /**
   * 联动逻辑核心：计算指定维度在受到“除自己以外的所有其他筛选器”约束下的可用选项及其数量。
   * 这保证了用户在月份筛选器中总能看到所有匹配当前其他条件的月份，
   * 而在客户筛选器中能看到匹配当前选中月份的所有客户。
   */
  const getDynamicDimensionData = (dimension: keyof SalesRecord) => {
    // 1. 先根据除了当前 dimension 以外的所有筛选器过滤数据
    const filteredByOthers = allData.filter(item => {
      const matchMonth = dimension === 'month' || filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = dimension === 'salesperson' || filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = dimension === 'category' || filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = dimension === 'customer' || filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = dimension === 'itemName' || filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (
        (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
        (!filters.dateRange[1] || item.date <= filters.dateRange[1])
      );

      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });

    // 2. 统计每个选项出现的次数
    const counts: Record<string, number> = {};
    filteredByOthers.forEach(item => {
      const val = item[dimension] as string;
      if (val) counts[val] = (counts[val] || 0) + 1;
    });

    // 3. 返回排序后的选项列表和计数映射
    const options = Object.keys(counts).sort();
    if (dimension === 'month') options.reverse(); // 月份倒序

    return { options, counts };
  };

  // 动态计算所有维度的选项和计数
  const dynamicFilterData = useMemo(() => ({
    months: getDynamicDimensionData('month'),
    customers: getDynamicDimensionData('customer'),
    salespeople: getDynamicDimensionData('salesperson'),
    categories: getDynamicDimensionData('category'),
    itemNames: getDynamicDimensionData('itemName')
  }), [allData, filters]);

  // 最终应用所有筛选器后的数据
  const filteredData = useMemo(() => {
    return allData.filter(item => {
      const matchMonth = filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
                        (!filters.dateRange[1] || item.date <= filters.dateRange[1]);

      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });
  }, [allData, filters]);

  const summary: SalesSummary = useMemo(() => {
    const totalSales = filteredData.reduce((acc, cur) => acc + cur.totalAmount, 0);
    const totalQuantity = filteredData.reduce((acc, cur) => acc + cur.quantity, 0);
    const orderCount = filteredData.length;
    const avgOrderValue = orderCount > 0 ? totalSales / orderCount : 0;

    const monthlyMap = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const existing = monthlyMap.get(d.month) || { sales: 0, quantity: 0 };
      monthlyMap.set(d.month, {
        sales: existing.sales + d.totalAmount,
        quantity: existing.quantity + d.quantity
      });
    });
    const monthlyTrend = Array.from(monthlyMap.entries())
      .map(([name, val]) => ({ name, ...val }))
      .sort((a, b) => a.name.localeCompare(b.name));

    const catMap = new Map<string, number>();
    filteredData.forEach(d => {
      catMap.set(d.category, (catMap.get(d.category) || 0) + d.totalAmount);
    });
    const categoryDistribution = Array.from(catMap.entries()).map(([name, value]) => ({ name, value }));

    const spMap = new Map<string, number>();
    filteredData.forEach(d => {
      spMap.set(d.salesperson, (spMap.get(d.salesperson) || 0) + d.totalAmount);
    });
    const salespersonPerformance = Array.from(spMap.entries())
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value);

    return { totalSales, totalQuantity, orderCount, avgOrderValue, categoryDistribution, salespersonPerformance, monthlyTrend };
  }, [filteredData]);

  const resetFilters = () => setFilters({
    months: [],
    dateRange: ['', ''],
    customers: [],
    salespeople: [],
    categories: [],
    itemNames: []
  });

  if (error) {
