          title="总出库数量" 
          value={summary.totalQuantity.toLocaleString()} 
          sub="物料销售总数" 
          icon="📦" 
        />
        <KpiCard 
          title="出库单号" 
          value={`${summary.orderCount} 个单号`} 
          sub="点击单号查看详情" 
          icon="📑"
        >
          <div className="mt-auto max-h-32 overflow-y-auto pr-2 custom-scrollbar border-t border-slate-50 pt-2">
            <div className="flex flex-wrap gap-1.5">
              {summary.orderIds.map(id => (
                <button 
                  key={id} 
                  onClick={() => onSelectOrderId(id)}
                  className="inline-block px-1.5 py-0.5 bg-blue-50 text-blue-600 text-[10px] font-mono rounded border border-blue-100 hover:bg-blue-600 hover:text-white transition-colors"
                >
                  {id}
                </button>
              ))}
            </div>
          </div>
        </KpiCard>
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* 左侧合并趋势栏 */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">
              <span className="mr-2">📊</span> 销售趋势综合分析
            </h3>

            {/* 维度切换选框 */}
            <div className="flex bg-slate-100 p-1 rounded-lg self-start sm:self-auto">
              <button 
                onClick={() => setShowCfa(!showCfa)}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}
              >
                <div className={`w-2 h-2 rounded-full ${showCfa ? 'bg-blue-600' : 'bg-slate-300'}`}></div>
                金额 (CFA)
              </button>
              <button 
                onClick={() => setShowQuantity(!showQuantity)}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}
              >
                <div className={`w-2 h-2 rounded-full ${showQuantity ? 'bg-green-600' : 'bg-slate-300'}`}></div>
                数量
              </button>
            </div>
          </div>

          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={summary.monthlyTrend} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorQty" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />

                {/* 金额轴 (左) */}
                <YAxis 
                  yAxisId="left"
                  hide={!showCfa}
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#3b82f6', fontSize: 11}} 
                />

                {/* 数量轴 (右) */}
                <YAxis 
                  yAxisId="right"
                  orientation="right"
                  hide={!showQuantity}
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#10b981', fontSize: 11}} 
                />

                <Tooltip 
                  contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)'}}
                  formatter={(value: number, name: string) => {
                    if (name === 'sales') return [`${value.toLocaleString()} CFA`, '销售额'];
                    if (name === 'quantity') return [`${value.toLocaleString()}`, '销售数量'];
                    return [value, name];
                  }}
                />

                {showCfa && (
                  <Area 
                    yAxisId="left"
                    type="monotone" 
                    dataKey="sales" 
                    stroke="#3b82f6" 
                    strokeWidth={3} 
                    fillOpacity={1} 
                    fill="url(#colorSales)" 
                  />
                )}

                {showQuantity && (
                  <Area 
                    yAxisId="right"
                    type="monotone" 
                    dataKey="quantity" 
                    stroke="#10b981" 
                    strokeWidth={3} 
                    fillOpacity={1} 
                    fill="url(#colorQty)" 
                  />
                )}
              </AreaChart>
            </ResponsiveContainer>
          </div>

          <div className="mt-4 flex items-center justify-center gap-6 text-[10px] text-slate-400 font-bold uppercase tracking-widest">
            {showCfa && <div className="flex items-center gap-1.5"><span className="w-3 h-0.5 bg-blue-500"></span> 销售金额趋势</div>}
            {showQuantity && <div className="flex items-center gap-1.5"><span className="w-3 h-0.5 bg-green-500"></span> 销售数量趋势</div>}
          </div>
        </div>

        {/* 右侧分布栏 */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative overflow-hidden flex flex-col min-h-[580px]">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">
              <span className="mr-2">🧩</span> 品类销售占比
            </h3>
            <span className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">点击扇区查看物料详情</span>
          </div>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={summary.categoryDistribution}
                  cx="50%"
                  cy="50%"
                  innerRadius={80}
                  outerRadius={130}
                  paddingAngle={5}
                  dataKey="value"
                  onClick={onPieClick}
                  stroke="none"
                  style={{ cursor: 'pointer', outline: 'none' }}
                >
                  {summary.categoryDistribution.map((entry, index) => (
                    <RechartsCell 
                      key={`cell-${index}`} 
                      fill={COLORS[index % COLORS.length]} 
                      opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1}
                      stroke={selectedCategory === entry.name ? '#fff' : 'none'}
                      strokeWidth={2}
                    />
                  ))}
                </Pie>
                <Tooltip formatter={(value: number) => [`${value.toLocaleString()} CFA`, '金额']} />
                <Legend layout="horizontal" align="center" verticalAlign="bottom" iconType="circle" />
              </PieChart>
            </ResponsiveContainer>
          </div>

          {/* Drill-down Item Breakdown Overlay */}
          {selectedCategory && (
            <div className="absolute inset-0 bg-white/95 backdrop-blur-sm z-10 p-6 flex flex-col animate-in slide-in-from-right duration-300">
              <div className="flex items-center justify-between mb-4">
                <div>
                  <h4 className="text-sm font-bold text-slate-400 uppercase tracking-widest">物料构成钻取</h4>
                  <h3 className="text-xl font-bold text-slate-900">{selectedCategory}</h3>
                </div>
                <button 
                  onClick={() => setSelectedCategory(null)}
                  className="p-1.5 hover:bg-slate-100 rounded-full text-slate-400 hover:text-slate-600 transition-colors"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>

              <div className="flex-1 overflow-y-auto custom-scrollbar">
                <div className="space-y-4">
                  {itemBreakdown.map((item, idx) => {
                    const percentage = (item.value / (summary.categoryDistribution.find(c => c.name === selectedCategory)?.value || 1) * 100).toFixed(1);
                    return (
                      <div key={item.name} className="group">
                        <div className="flex justify-between text-xs mb-1">
                          <span className="font-semibold text-slate-700">{item.name}</span>
                          <span className="text-slate-400 font-mono">{item.value.toLocaleString()} CFA ({percentage}%)</span>
                        </div>
                        <div className="w-full bg-slate-100 h-1.5 rounded-full overflow-hidden">
                          <div 
                            className="bg-blue-600 h-full rounded-full transition-all duration-1000" 
                            style={{ width: `${percentage}%` }}
                          />
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center">
          <span className="mr-2">🏆</span> 销售员业绩排行 (CFA)
        </h3>
        <div className="h-[350px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical">
              <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={80} tick={{fill: '#475569', fontWeight: 500}} />
              <Tooltip cursor={{fill: '#f8fafc'}} formatter={(value: number) => [`${value.toLocaleString()} CFA`, '销售额']} />
              <Bar dataKey="value" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={24} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-indigo-900 text-white p-8 rounded-2xl shadow-xl overflow-hidden relative">
        <div className="relative z-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
            <div>
              <h3 className="text-xl font-bold flex items-center">
                <span className="mr-2">✨</span> Gemini 智能分析
              </h3>
              <p className="text-indigo-200 text-sm mt-1">让 AI 为您的销售数据提供专业的商业建议 (以 CFA 计价)</p>
            </div>
            <button 
              onClick={handleGetAIInsights}
              disabled={loading}
              className="bg-white text-indigo-900 px-6 py-2.5 rounded-full font-bold hover:bg-indigo-50 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center min-w-[140px]"
            >
              {loading ? (
                <>
                  <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-indigo-900" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  分析中...
                </>
              ) : '立即生成洞察'}
            </button>
          </div>

          {aiText ? (
            <div className="bg-indigo-800/50 p-6 rounded-xl border border-indigo-700 backdrop-blur-sm animate-fade-in whitespace-pre-wrap leading-relaxed text-indigo-50">
              {aiText}
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center py-12 border-2 border-dashed border-indigo-700 rounded-xl">
              <span className="text-4xl mb-4">💡</span>
              <p className="text-indigo-300">点击按钮，获取关于当前筛选数据的 AI 经营建议</p>
            </div>
          )}
        </div>
        <div className="absolute -bottom-24 -right-24 w-64 h-64 bg-indigo-500/20 rounded-full blur-3xl"></div>
      </div>
    </div>
  );
};

export default Dashboard;

export interface SalesRecord {
  id: string; // 出库单号
  month: string; // 月份
  date: string; // 业务日期
  customer: string; // 客户
  salesperson: string; // 销售员
  category: string; // 品类
  itemName: string; // 物料名称
  quantity: number; // 数量
  unitPrice: number; // 单价
  totalAmount: number; // 价税合计
}

export interface SalesSummary {
  totalSales: number;
  totalQuantity: number;
  orderCount: number;
  orderIds: string[]; // 具体的出库单号列表
  categoryDistribution: { name: string; value: number }[];
  categoryQuantityDistribution: { name: string; value: number }[];
  salespersonPerformance: { name: string; value: number }[];
  monthlyTrend: { name: string; sales: number; quantity: number }[];
}

export interface FilterState {
  months: string[];
  dateRange: [string, string];
  customers: string[];
  salespeople: string[];
  categories: string[];
  itemNames: string[];
}

import React, { useState, useMemo, useEffect } from 'react';
import { FilterState, SalesSummary, SalesRecord } from './types';
import Dashboard from './components/Dashboard';
import DataTable from './components/DataTable';
import MultiSelect from './components/MultiSelect';
import OrderDetailModal from './components/OrderDetailModal';
import { fetchSalesData } from './services/dataService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'table'>('dashboard');
  const [allData, setAllData] = useState<SalesRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedOrderId, setSelectedOrderId] = useState<string | null>(null);
  const [filters, setFilters] = useState<FilterState>({
    months: [],
    dateRange: ['', ''],
    customers: [],
    salespeople: [],
    categories: [],
    itemNames: []
  });

  // 当数据加载完成后，默认全选所有维度
  useEffect(() => {
    const loadData = async () => {
      try {
        setIsLoading(true);
        const data = await fetchSalesData();
        setAllData(data);

        // 提取所有唯一值进行初始化全选
        const uniqueMonths = Array.from(new Set(data.map(d => d.month))).sort().reverse();
        const uniqueCustomers = Array.from(new Set(data.map(d => d.customer))).sort();
        const uniqueSalespeople = Array.from(new Set(data.map(d => d.salesperson))).sort();
        const uniqueCategories = Array.from(new Set(data.map(d => d.category))).sort();
        const uniqueItems = Array.from(new Set(data.map(d => d.itemName))).sort();

        setFilters(prev => ({
          ...prev,
          months: uniqueMonths,
          customers: uniqueCustomers,
          salespeople: uniqueSalespeople,
          categories: uniqueCategories,
          itemNames: uniqueItems
        }));

        setError(null);
      } catch (err) {
        setError('数据加载失败。请确保 Google 表格已公开共享且格式正确。');
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  /**
   * 联动逻辑核心
   */
  const getDynamicDimensionData = (dimension: keyof SalesRecord) => {
    const filteredByOthers = allData.filter(item => {
      const matchMonth = dimension === 'month' || filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = dimension === 'salesperson' || filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = dimension === 'category' || filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = dimension === 'customer' || filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = dimension === 'itemName' || filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (
        (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
        (!filters.dateRange[1] || item.date <= filters.dateRange[1])
      );

      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });

    const counts: Record<string, number> = {};
    filteredByOthers.forEach(item => {
      const val = item[dimension] as string;
      if (val) counts[val] = (counts[val] || 0) + 1;
    });

    const options = Object.keys(counts).sort();
    if (dimension === 'month') options.reverse();

    return { options, counts };
  };

  const dynamicFilterData = useMemo(() => ({
    months: getDynamicDimensionData('month'),
    customers: getDynamicDimensionData('customer'),
    salespeople: getDynamicDimensionData('salesperson'),
    categories: getDynamicDimensionData('category'),
    itemNames: getDynamicDimensionData('itemName')
  }), [allData, filters]);

  const filteredData = useMemo(() => {
    return allData.filter(item => {
      const matchMonth = filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
                        (!filters.dateRange[1] || item.date <= filters.dateRange[1]);

      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });
  }, [allData, filters]);

  const summary: SalesSummary = useMemo(() => {
    const totalSales = filteredData.reduce((acc, cur) => acc + cur.totalAmount, 0);
    const totalQuantity = filteredData.reduce((acc, cur) => acc + cur.quantity, 0);

    const uniqueOrderIds = Array.from(new Set(filteredData.map(d => d.id))).sort();
    const orderCount = uniqueOrderIds.length;

    const monthlyMap = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const existing = monthlyMap.get(d.month) || { sales: 0, quantity: 0 };
      monthlyMap.set(d.month, {
        sales: existing.sales + d.totalAmount,
        quantity: existing.quantity + d.quantity
      });
    });
    const monthlyTrend = Array.from(monthlyMap.entries())
      .map(([name, val]) => ({ name, ...val }))
      .sort((a, b) => a.name.localeCompare(b.name));

    const catMap = new Map<string, number>();
    const catQtyMap = new Map<string, number>();
    filteredData.forEach(d => {
      catMap.set(d.category, (catMap.get(d.category) || 0) + d.totalAmount);
      catQtyMap.set(d.category, (catQtyMap.get(d.category) || 0) + d.quantity);
    });
    const categoryDistribution = Array.from(catMap.entries()).map(([name, value]) => ({ name, value }));
    const categoryQuantityDistribution = Array.from(catQtyMap.entries()).map(([name, value]) => ({ name, value }));

    const spMap = new Map<string, number>();
    filteredData.forEach(d => {
      spMap.set(d.salesperson, (spMap.get(d.salesperson) || 0) + d.totalAmount);
    });
    const salespersonPerformance = Array.from(spMap.entries())
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value);

    return { 
      totalSales, 
      totalQuantity, 
      orderCount, 
      orderIds: uniqueOrderIds, 
      categoryDistribution, 
      categoryQuantityDistribution,
      salespersonPerformance, 
      monthlyTrend 
    };
  }, [filteredData]);

  const resetFilters = () => setFilters({
    months: [],
    dateRange: ['', ''],
    customers: [],
    salespeople: [],
    categories: [],
    itemNames: []
  });

  // 获取特定单号下的所有记录
  const orderDetails = useMemo(() => {
    if (!selectedOrderId) return [];
    return allData.filter(d => d.id === selectedOrderId);
  }, [selectedOrderId, allData]);

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 p-4 text-center">
        <div className="bg-white p-8 rounded-2xl shadow-xl max-w-md">
          <div className="text-6xl mb-4">⚠️</div>
          <h2 className="text-2xl font-bold text-slate-900 mb-2">连接失败</h2>
          <p className="text-slate-500 mb-6">{error}</p>
          <button onClick={() => window.location.reload()} className="inline-block bg-blue-600 text-white px-6 py-2 rounded-lg font-bold hover:bg-blue-700 transition-colors">
            重试连接
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 pb-12">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white text-2xl font-bold shadow-lg shadow-blue-200">S</div>
            <div>
              <div className="flex items-center gap-2">
                <h1 className="text-xl font-bold text-slate-900">销售数据洞察专家</h1>
                <span className="hidden md:flex bg-green-100 text-green-700 text-[10px] px-2 py-0.5 rounded-full font-bold items-center">
                  <span className="w-1.5 h-1.5 bg-green-500 rounded-full mr-1 animate-pulse"></span>
                  LIVE: GOOGLE SHEETS
                </span>
              </div>
              <p className="text-xs text-slate-500 hidden sm:block">表格级 交互式联动面板 (CFA)</p>
            </div>
          </div>
          <nav className="flex bg-slate-100 p-1 rounded-lg">
            <button 
              onClick={() => setActiveTab('dashboard')}
              className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${activeTab === 'dashboard' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-600 hover:text-slate-900'}`}
            >
              数据看板
            </button>
            <button 
              onClick={() => setActiveTab('table')}
              className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${activeTab === 'table' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-600 hover:text-slate-900'}`}
            >
              明细数据
            </button>
          </nav>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-8">
        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20 space-y-4">
            <div className="w-12 h-12 border-4 border-blue-200 border-t-blue-600 rounded-full animate-spin"></div>
            <p className="text-slate-500 font-medium">同步云端表格数据中...</p>
          </div>
        ) : (
          <>
            <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 mb-8">
              <div className="flex items-center justify-between mb-6">
                <div className="flex items-center">
                  <span className="w-1.5 h-4 bg-blue-600 rounded-full mr-2"></span>
                  <h2 className="text-sm font-bold text-slate-800 uppercase tracking-widest">
                    高级筛选中心
                  </h2>
                  <span className="ml-4 px-2 py-0.5 bg-green-50 text-green-600 text-[10px] rounded font-bold border border-green-100">联动模式已开启</span>
                </div>
                <div className="flex items-center gap-4">
                  <span className="text-xs text-slate-400 font-medium font-mono">符合条件记录: {filteredData.length} 条</span>
                  <button onClick={resetFilters} className="text-xs text-blue-600 hover:text-blue-700 font-bold uppercase tracking-wider transition-colors">
                    重置所有
                  </button>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                <MultiSelect 
                  label="月份"
                  options={dynamicFilterData.months.options}
                  counts={dynamicFilterData.months.counts}
                  selectedValues={filters.months}
                  onChange={(v) => setFilters({...filters, months: v})}
                  placeholder="筛选月份"
                />
                <MultiSelect 
                  label="客户"
                  options={dynamicFilterData.customers.options}
                  counts={dynamicFilterData.customers.counts}
                  selectedValues={filters.customers}
                  onChange={(v) => setFilters({...filters, customers: v})}
                  placeholder="筛选客户"
                />
                <MultiSelect 
                  label="销售员"
                  options={dynamicFilterData.salespeople.options}
                  counts={dynamicFilterData.salespeople.counts}
                  selectedValues={filters.salespeople}
                  onChange={(v) => setFilters({...filters, salespeople: v})}
                  placeholder="筛选销售员"
                />
                <MultiSelect 
                  label="品类"
                  options={dynamicFilterData.categories.options}
                  counts={dynamicFilterData.categories.counts}
                  selectedValues={filters.categories}
                  onChange={(v) => setFilters({...filters, categories: v})}
                  placeholder="筛选品类"
                />

                <div className="lg:col-span-2">
                  <MultiSelect 
                    label="物料名称"
                    options={dynamicFilterData.itemNames.options}
                    counts={dynamicFilterData.itemNames.counts}
                    selectedValues={filters.itemNames}
                    onChange={(v) => setFilters({...filters, itemNames: v})}
                    placeholder="筛选具体物料"
                  />
                </div>

                <div className="lg:col-span-2 flex gap-3">
                  <div className="flex-1">
                    <label className="block text-xs font-semibold text-slate-400 mb-1.5 uppercase tracking-wider">业务日期 (起)</label>
                    <input 
                      type="date"
                      value={filters.dateRange[0]}
                      onChange={(e) => setFilters({...filters, dateRange: [e.target.value, filters.dateRange[1]]})}
                      className="w-full bg-slate-50 border border-slate-200 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 rounded-lg px-3 py-2 text-sm text-slate-900 outline-none transition-all"
                    />
                  </div>
                  <div className="flex-1">
                    <label className="block text-xs font-semibold text-slate-400 mb-1.5 uppercase tracking-wider">业务日期 (止)</label>
                    <input 
                      type="date"
                      value={filters.dateRange[1]}
                      onChange={(e) => setFilters({...filters, dateRange: [filters.dateRange[0], e.target.value]})}
                      className="w-full bg-slate-50 border border-slate-200 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 rounded-lg px-3 py-2 text-sm text-slate-900 outline-none transition-all"
                    />
                  </div>
                </div>
              </div>
            </section>

            <div className="animate-in fade-in duration-500">
              {filteredData.length > 0 ? (
                activeTab === 'dashboard' ? (
                  <Dashboard 
                    summary={summary} 
                    filteredData={filteredData} 
                    onSelectOrderId={setSelectedOrderId} 
                  />
                ) : (
                  <DataTable data={filteredData} onSelectOrderId={setSelectedOrderId} />
                )
              ) : (
                <div className="flex flex-col items-center justify-center py-24 bg-white rounded-3xl border border-dashed border-slate-200 shadow-inner">
                  <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6">
                    <span className="text-4xl text-slate-300">🔎</span>
                  </div>
                  <h3 className="text-xl font-bold text-slate-800">未找到匹配的销售记录</h3>
                  <p className="text-slate-500 mt-2 max-w-sm text-center">由于采用了多维联动逻辑，某些选项组合在数据集中可能不存在。请尝试重置部分筛选器以找回数据。</p>
                  <button onClick={resetFilters} className="mt-8 bg-blue-600 text-white px-8 py-3 rounded-xl text-sm font-bold shadow-lg shadow-blue-200 hover:bg-blue-700 transition-all">
                    清空并重置
                  </button>
                </div>
              )}
            </div>
          </>
        )}
      </main>

      {selectedOrderId && (
        <OrderDetailModal 
          orderId={selectedOrderId} 
          records={orderDetails} 
          onClose={() => setSelectedOrderId(null)} 
        />
      )}

      <footer className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-16 pb-12 text-center">
        <div className="pt-8 border-t border-slate-200">
          <p className="text-slate-400 text-xs font-medium tracking-widest uppercase mb-2">Sales Insight Pro</p>
          <p className="text-slate-300 text-[10px]">后端: Google Sheets · 引擎: Gemini 3 Flash · 计价单位: CFA</p>
        </div>
      </footer>
    </div>
  );
};

