    const insights = await getAIInsights(summary);
    setAiText(insights || '');
    setLoading(false);
  };

  const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow flex flex-col h-full">
      <div className="flex justify-between items-start mb-4">
        <div className="p-2 bg-blue-50 rounded-lg text-blue-600 text-xl">{icon}</div>
        <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">{title}</span>
      </div>
      <div className="text-2xl font-bold text-slate-900 mb-1">{value}</div>
      <div className="text-sm text-slate-500 mb-3">{sub}</div>
      {children}
    </div>
  );

  // 计算选中品类下的物料销售额和数量分布，以及原始记录
  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], records: [] };

    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const records: SalesRecord[] = [];

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        records.push(record);
        const existing = itemsMap.get(record.itemName) || { sales: 0, qty: 0 };
        itemsMap.set(record.itemName, {
          sales: existing.sales + record.totalAmount,
          qty: existing.qty + record.quantity
        });
      }
    });

    const items = Array.from(itemsMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => b.sales - a.sales);

    return { items, records: records.sort((a, b) => b.date.localeCompare(a.date)) };
  }, [selectedCategory, filteredData]);

  const onPieClick = (data: any) => {
    if (selectedCategory === data.name) {
      setSelectedCategory(null);
    } else {
      setSelectedCategory(data.name);
    }
  };

  return (
    <div className="space-y-8">
      {/* KPI Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KpiCard 
          title="总销售额" 
          value={`${summary.totalSales.toLocaleString()} CFA`} 
          sub="当前筛选总额" 
          icon="💰" 
        />
        <KpiCard 
          title="总出库数量" 
          value={summary.totalQuantity.toLocaleString()} 
          sub="物料销售总数" 
          icon="📦" 
        />
        <KpiCard 
          title="出库单号" 
          value={`${summary.orderCount} 个单号`} 
          sub="点击单号查看详情" 
          icon="📑"
        >
          <div className="mt-auto max-h-32 overflow-y-auto pr-2 custom-scrollbar border-t border-slate-50 pt-2">
            <div className="flex flex-wrap gap-1.5">
              {summary.orderIds.map(id => (
                <button 
                  key={id} 
                  onClick={() => onSelectOrderId(id)}
                  className="inline-block px-1.5 py-0.5 bg-blue-50 text-blue-600 text-[10px] font-mono rounded border border-blue-100 hover:bg-blue-600 hover:text-white transition-colors"
                >
                  {id}
                </button>
              ))}
            </div>
          </div>
        </KpiCard>
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* 左侧合并趋势栏 */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col min-h-[620px]">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">
              <span className="mr-2">📊</span> 销售趋势综合分析
            </h3>

            <div className="flex bg-slate-100 p-1 rounded-lg self-start sm:self-auto">
              <button 
                onClick={() => setShowCfa(!showCfa)}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}
              >
                <div className={`w-2 h-2 rounded-full ${showCfa ? 'bg-blue-600' : 'bg-slate-300'}`}></div>
                金额 (CFA)
              </button>
              <button 
                onClick={() => setShowQuantity(!showQuantity)}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}
              >
                <div className={`w-2 h-2 rounded-full ${showQuantity ? 'bg-green-600' : 'bg-slate-300'}`}></div>
                数量
              </button>
            </div>
          </div>

          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={summary.monthlyTrend} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorQty" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#3b82f6', fontSize: 11}} />
                <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 11}} />
                <Tooltip 
                  contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)'}}
                  formatter={(value: number, name: string) => {
                    if (name === 'sales') return [`${value.toLocaleString()} CFA`, '销售额'];
                    if (name === 'quantity') return [`${value.toLocaleString()}`, '销售数量'];
                    return [value, name];
                  }}
                />
                {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorSales)" />}
                {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" stroke="#10b981" strokeWidth={3} fillOpacity={1} fill="url(#colorQty)" />}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* 右侧品类分布栏 */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative overflow-hidden flex flex-col min-h-[620px]">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">
              <span className="mr-2">🧩</span> 品类多维分布
            </h3>
            <button 
              onClick={() => setShowSummaryTable(!showSummaryTable)}
              className="text-[10px] bg-slate-50 hover:bg-blue-50 text-slate-400 hover:text-blue-600 font-bold uppercase tracking-tighter px-2 py-1 rounded border border-slate-100 transition-all flex items-center gap-1"
            >
              {showSummaryTable ? '隐藏明细' : '📂 点击查看汇总明细'}
            </button>
          </div>

          <div className="flex-1 flex flex-col">
            {!showSummaryTable ? (
              <div className="flex-1 grid grid-rows-2 gap-4">
                <div className="relative">
                  <div className="absolute top-0 left-0 text-[10px] font-bold text-slate-400 uppercase">销售金额占比 (CFA)</div>
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie
                        data={summary.categoryDistribution}
                        cx="50%"
                        cy="55%"
                        innerRadius={50}
                        outerRadius={80}
                        paddingAngle={5}
                        dataKey="value"
                        onClick={onPieClick}
                        stroke="none"
                        style={{ cursor: 'pointer', outline: 'none' }}
                      >
                        {summary.categoryDistribution.map((entry, index) => (
                          <RechartsCell 
                            key={`cell-amt-${index}`} 
                            fill={COLORS[index % COLORS.length]} 
                            opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1}
                            stroke={selectedCategory === entry.name ? '#fff' : 'none'}
                            strokeWidth={2}
                          />
                        ))}
                      </Pie>
                      <Tooltip formatter={(value: number) => [`${value.toLocaleString()} CFA`, '金额']} />
                    </PieChart>
                  </ResponsiveContainer>
                </div>

                <div className="relative border-t border-slate-50 pt-4">
                  <div className="absolute top-4 left-0 text-[10px] font-bold text-slate-400 uppercase">销售数量占比</div>
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie
                        data={summary.categoryQuantityDistribution}
                        cx="50%"
                        cy="55%"
                        innerRadius={50}
                        outerRadius={80}
                        paddingAngle={5}
                        dataKey="value"
                        onClick={onPieClick}
                        stroke="none"
                        style={{ cursor: 'pointer', outline: 'none' }}
                      >
                        {summary.categoryQuantityDistribution.map((entry, index) => (
                          <RechartsCell 
                            key={`cell-qty-${index}`} 
                            fill={COLORS[index % COLORS.length]} 
                            opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1}
                            stroke={selectedCategory === entry.name ? '#fff' : 'none'}
                            strokeWidth={2}
                          />
                        ))}
                      </Pie>
                      <Tooltip formatter={(value: number) => [`${value.toLocaleString()}`, '数量']} />
                      <Legend layout="horizontal" align="center" verticalAlign="bottom" iconType="circle" />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              </div>
            ) : (
              <div className="flex-1 overflow-y-auto custom-scrollbar animate-in fade-in slide-in-from-bottom duration-300">
                <table className="min-w-full text-xs text-left">
                  <thead className="bg-slate-50 sticky top-0">
                    <tr>
                      <th className="px-3 py-2 text-slate-400 uppercase font-bold">品类名称</th>
                      <th className="px-3 py-2 text-slate-400 uppercase font-bold text-right">金额 (CFA)</th>
                      <th className="px-3 py-2 text-slate-400 uppercase font-bold text-right">数量</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {summary.categoryDistribution.map((cat, idx) => {
                      const qty = summary.categoryQuantityDistribution.find(q => q.name === cat.name)?.value || 0;
                      return (
                        <tr 
                          key={cat.name} 
                          onClick={() => setSelectedCategory(cat.name)}
                          className="hover:bg-blue-50 cursor-pointer transition-colors group"
                        >
                          <td className="px-3 py-3 flex items-center gap-2">
                            <span className="w-2 h-2 rounded-full" style={{ backgroundColor: COLORS[idx % COLORS.length] }}></span>
                            <span className="font-bold text-slate-700 group-hover:text-blue-600">{cat.name}</span>
                          </td>
                          <td className="px-3 py-3 text-right font-mono text-slate-600">{cat.value.toLocaleString()}</td>
                          <td className="px-3 py-3 text-right font-mono text-slate-600">{qty.toLocaleString()}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {/* Drill-down Item Breakdown Overlay */}
          {selectedCategory && (
            <div className="absolute inset-0 bg-white/98 backdrop-blur-md z-20 p-6 flex flex-col animate-in slide-in-from-right duration-300 shadow-2xl">
              <div className="flex items-center justify-between mb-6 border-b border-slate-100 pb-4">
                <div>
                  <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">Category Insights / 品类深度分析</h4>
                  <h3 className="text-2xl font-black text-slate-900">{selectedCategory}</h3>
                </div>
                <button 
                  onClick={() => setSelectedCategory(null)}
                  className="p-2 hover:bg-slate-100 rounded-full text-slate-400 hover:text-slate-600 transition-colors shadow-sm"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>

              <div className="flex-1 overflow-y-auto custom-scrollbar space-y-8 pr-2">
                {/* 1. 物料构成分析 */}
                <section>
                  <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <span className="w-1 h-3 bg-blue-600 rounded-full"></span> 核心物料贡献
                  </h5>
                  <div className="space-y-4">
                    {drillDownData.items.map((item, idx) => {
                      const totalAmt = summary.categoryDistribution.find(c => c.name === selectedCategory)?.value || 1;
                      const totalQty = summary.categoryQuantityDistribution.find(c => c.name === selectedCategory)?.value || 1;
                      const amtPercentage = (item.sales / totalAmt * 100).toFixed(1);
                      const qtyPercentage = (item.qty / totalQty * 100).toFixed(1);

                      return (
                        <div key={item.name} className="group bg-slate-50/50 p-4 rounded-xl border border-slate-100 hover:border-blue-200 transition-all">
                          <div className="flex justify-between text-sm mb-3">
                            <span className="font-bold text-slate-800">{item.name}</span>
                          </div>
                          <div className="grid grid-cols-2 gap-6">
                            <div>
                              <div className="flex justify-between text-[10px] mb-1.5">
                                <span className="text-slate-400 uppercase font-bold">金额贡献</span>
                                <span className="text-blue-600 font-mono font-bold">{item.sales.toLocaleString()} CFA ({amtPercentage}%)</span>
                              </div>
                              <div className="w-full bg-slate-200 h-1.5 rounded-full overflow-hidden">
                                <div className="bg-blue-600 h-full rounded-full" style={{ width: `${amtPercentage}%` }} />
                              </div>
                            </div>
                            <div>
                              <div className="flex justify-between text-[10px] mb-1.5">
                                <span className="text-slate-400 uppercase font-bold">数量贡献</span>
                                <span className="text-green-600 font-mono font-bold">{item.qty.toLocaleString()} ({qtyPercentage}%)</span>
                              </div>
                              <div className="w-full bg-slate-200 h-1.5 rounded-full overflow-hidden">
                                <div className="bg-green-600 h-full rounded-full" style={{ width: `${qtyPercentage}%` }} />
                              </div>
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </section>

                {/* 2. 明细记录表 */}
                <section>
                  <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <span className="w-1 h-3 bg-green-500 rounded-full"></span> 原始交易明细记录
                  </h5>
                  <div className="overflow-x-auto rounded-xl border border-slate-100 bg-white">
                    <table className="min-w-full text-[10px]">
                      <thead className="bg-slate-50 border-b border-slate-100">
                        <tr>
                          <th className="px-3 py-2 text-left font-bold text-slate-400">单号</th>
                          <th className="px-3 py-2 text-left font-bold text-slate-400">日期</th>
                          <th className="px-3 py-2 text-left font-bold text-slate-400">客户</th>
                          <th className="px-3 py-2 text-left font-bold text-slate-400">物料</th>
                          <th className="px-3 py-2 text-right font-bold text-slate-400">数量</th>
                          <th className="px-3 py-2 text-right font-bold text-slate-400">金额</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {drillDownData.records.slice(0, 30).map((r, i) => (
                          <tr key={i} className="hover:bg-slate-50 transition-colors">
                            <td className="px-3 py-2 text-blue-600 font-mono font-bold">
                              <button onClick={() => onSelectOrderId(r.id)}>{r.id}</button>
                            </td>
                            <td className="px-3 py-2 text-slate-500">{r.date}</td>
                            <td className="px-3 py-2 text-slate-900 font-medium truncate max-w-[80px]">{r.customer}</td>
                            <td className="px-3 py-2 text-slate-600 truncate max-w-[120px]">{r.itemName}</td>
                            <td className="px-3 py-2 text-right font-mono font-bold">{r.quantity}</td>
                            <td className="px-3 py-2 text-right font-mono text-slate-900">{r.totalAmount.toLocaleString()}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    {drillDownData.records.length > 30 && (
                      <div className="px-3 py-2 text-center text-[10px] text-slate-400 italic bg-slate-50">
                        仅展示最近 30 条记录（总计 {drillDownData.records.length} 条）
                      </div>
                    )}
                  </div>
                </section>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center">
          <span className="mr-2">🏆</span> 销售员业绩排行 (CFA)
        </h3>
        <div className="h-[350px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical">
              <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={80} tick={{fill: '#475569', fontWeight: 500}} />
              <Tooltip cursor={{fill: '#f8fafc'}} formatter={(value: number) => [`${value.toLocaleString()} CFA`, '销售额']} />
              <Bar dataKey="value" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={24} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-indigo-900 text-white p-8 rounded-2xl shadow-xl overflow-hidden relative">
        <div className="relative z-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
            <div>
              <h3 className="text-xl font-bold flex items-center">
                <span className="mr-2">✨</span> Gemini 智能分析
              </h3>
              <p className="text-indigo-200 text-sm mt-1">让 AI 为您的销售数据提供专业的商业建议 (以 CFA 计价)</p>
            </div>
            <button 
              onClick={handleGetAIInsights}
              disabled={loading}
              className="bg-white text-indigo-900 px-6 py-2.5 rounded-full font-bold hover:bg-indigo-50 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center min-w-[140px]"
            >
              {loading ? (
                <>
                  <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-indigo-900" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  分析中...
                </>
              ) : '立即生成洞察'}
            </button>
          </div>

          {aiText ? (
            <div className="bg-indigo-800/50 p-6 rounded-xl border border-indigo-700 backdrop-blur-sm animate-fade-in whitespace-pre-wrap leading-relaxed text-indigo-50">
              {aiText}
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center py-12 border-2 border-dashed border-indigo-700 rounded-xl">
              <span className="text-4xl mb-4">💡</span>
              <p className="text-indigo-300">点击按钮，获取关于当前筛选数据的 AI 经营建议</p>
            </div>
          )}
        </div>
        <div className="absolute -bottom-24 -right-24 w-64 h-64 bg-indigo-500/20 rounded-full blur-3xl"></div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell, AreaChart, Area, Legend, Cell as RechartsCell
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';
import { getAIInsights } from '../services/geminiService';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

// 扩展配色方案，确保品类区分度
const COLORS = [
  '#3b82f6', // 蓝色
  '#10b981', // 绿色
  '#f59e0b', // 橙色
  '#ef4444', // 红色
  '#8b5cf6', // 紫色
  '#06b6d4', // 青色
  '#f43f5e', // 玫瑰红
  '#84cc16', // 莱姆绿
  '#a855f7'  // 浅紫
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [aiText, setAiText] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [showSummaryTable, setShowSummaryTable] = useState(false);

  // 控制趋势图显示的维度
  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  const handleGetAIInsights = async () => {
    setLoading(true);
    const insights = await getAIInsights(summary);
    setAiText(insights || '');
    setLoading(false);
  };

  const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow flex flex-col h-full">
      <div className="flex justify-between items-start mb-4">
        <div className="p-2 bg-blue-50 rounded-lg text-blue-600 text-xl">{icon}</div>
        <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">{title}</span>
      </div>
      <div className="text-2xl font-bold text-slate-900 mb-1">{value}</div>
      <div className="text-sm text-slate-500 mb-3">{sub}</div>
      {children}
    </div>
  );

  // 计算选中品类下的物料销售额和数量分布，以及原始记录
  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], records: [] };

    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const records: SalesRecord[] = [];

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        records.push(record);
        const existing = itemsMap.get(record.itemName) || { sales: 0, qty: 0 };
        itemsMap.set(record.itemName, {
          sales: existing.sales + record.totalAmount,
          qty: existing.qty + record.quantity
        });
