                    <p className="text-[10px] text-emerald-600 opacity-70">导入历史销售记录</p>
                  </div>
                </div>
              </div>

              {localFileName && (
                <button 
                  onClick={handleSyncToCloud}
                  className="bg-indigo-600 text-white px-5 py-4 rounded-xl font-bold text-xs flex flex-col items-center gap-1 hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200 group"
                >
                  <svg className="w-5 h-5 group-hover:animate-bounce" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
                  <span>同步至云端</span>
                </button>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default FileSourceManager;

import React, { useState, useMemo, useEffect } from 'react';
import { FilterState, SalesSummary, SalesRecord } from './types';
import Dashboard from './components/Dashboard';
import DataTable from './components/DataTable';
import MultiSelect from './components/MultiSelect';
import OrderDetailModal from './components/OrderDetailModal';
import FileSourceManager from './components/FileSourceManager';
import { fetchSalesData } from './services/dataService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'table'>('dashboard');
  const [cloudData, setCloudData] = useState<SalesRecord[]>([]);
  const [localData, setLocalData] = useState<SalesRecord[]>([]);
  const [sourceType, setSourceType] = useState<'cloud' | 'local'>('cloud');
  const [localFileName, setLocalFileName] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedOrderId, setSelectedOrderId] = useState<string | null>(null);

  const [filters, setFilters] = useState<FilterState>({
    months: [],
    dateRange: ['', ''],
    customers: [],
    salespeople: [],
    categories: [],
    itemNames: []
  });

  const allData = sourceType === 'cloud' ? cloudData : localData;

  const loadCloudData = async () => {
    try {
      setIsLoading(true);
      const data = await fetchSalesData();
      setCloudData(data);
      initializeFilters(data);
      setError(null);
    } catch (err) {
      setError('数据加载失败。请确保 Google 表格已公开共享且格式正确。');
    } finally {
      setIsLoading(false);
    }
  };

  const initializeFilters = (data: SalesRecord[]) => {
    const uniqueMonths = Array.from(new Set(data.map(d => d.month))).sort().reverse();
    const uniqueCustomers = Array.from(new Set(data.map(d => d.customer))).sort();
    const uniqueSalespeople = Array.from(new Set(data.map(d => d.salesperson))).sort();
    const uniqueCategories = Array.from(new Set(data.map(d => d.category))).sort();
    const uniqueItems = Array.from(new Set(data.map(d => d.itemName))).sort();

    setFilters({
      months: uniqueMonths,
      dateRange: ['', ''],
      customers: uniqueCustomers,
      salespeople: uniqueSalespeople,
      categories: uniqueCategories,
      itemNames: uniqueItems
    });
  };

  useEffect(() => {
    loadCloudData();
  }, []);

  const handleFileUpload = (data: SalesRecord[], fileName: string) => {
    setLocalData(data);
    setLocalFileName(fileName);
    setSourceType('local');
    initializeFilters(data);
  };

  const handleSourceChange = (type: 'cloud' | 'local') => {
    setSourceType(type);
    if (type === 'cloud') {
      initializeFilters(cloudData);
    } else if (localData.length > 0) {
      initializeFilters(localData);
    }
  };

  const getDynamicDimensionData = (dimension: keyof SalesRecord) => {
    const filteredByOthers = allData.filter(item => {
      const matchMonth = dimension === 'month' || filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = dimension === 'salesperson' || filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = dimension === 'category' || filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = dimension === 'customer' || filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = dimension === 'itemName' || filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (
        (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
        (!filters.dateRange[1] || item.date <= filters.dateRange[1])
      );

      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });

    const counts: Record<string, number> = {};
    filteredByOthers.forEach(item => {
      const val = item[dimension] as string;
      if (val) counts[val] = (counts[val] || 0) + 1;
    });

    const options = Object.keys(counts).sort();
    if (dimension === 'month') options.reverse();

    return { options, counts };
  };

  const dynamicFilterData = useMemo(() => ({
    months: getDynamicDimensionData('month'),
    customers: getDynamicDimensionData('customer'),
    salespeople: getDynamicDimensionData('salesperson'),
    categories: getDynamicDimensionData('category'),
    itemNames: getDynamicDimensionData('itemName')
  }), [allData, filters]);

  const filteredData = useMemo(() => {
    return allData.filter(item => {
      const matchMonth = filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
                        (!filters.dateRange[1] || item.date <= filters.dateRange[1]);

      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });
  }, [allData, filters]);

  const summary: SalesSummary = useMemo(() => {
    const totalSales = filteredData.reduce((acc, cur) => acc + cur.totalAmount, 0);
    const totalQuantity = filteredData.reduce((acc, cur) => acc + cur.quantity, 0);

    const uniqueOrderIds = Array.from(new Set(filteredData.map(d => d.id))).sort();
    const orderCount = uniqueOrderIds.length;

    const monthlyMap = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const existing = monthlyMap.get(d.month) || { sales: 0, quantity: 0 };
      monthlyMap.set(d.month, {
        sales: existing.sales + d.totalAmount,
        quantity: existing.quantity + d.quantity
      });
    });
    const monthlyTrend = Array.from(monthlyMap.entries())
      .map(([name, val]) => ({ name, ...val }))
      .sort((a, b) => a.name.localeCompare(b.name));

    const catMap = new Map<string, number>();
    const catQtyMap = new Map<string, number>();
    filteredData.forEach(d => {
      catMap.set(d.category, (catMap.get(d.category) || 0) + d.totalAmount);
      catQtyMap.set(d.category, (catQtyMap.get(d.category) || 0) + d.quantity);
    });
    const categoryDistribution = Array.from(catMap.entries()).map(([name, value]) => ({ name, value }));
    const categoryQuantityDistribution = Array.from(catQtyMap.entries()).map(([name, value]) => ({ name, value }));

    const spMap = new Map<string, number>();
    filteredData.forEach(d => {
      spMap.set(d.salesperson, (spMap.get(d.salesperson) || 0) + d.totalAmount);
    });
    const salespersonPerformance = Array.from(spMap.entries())
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value);

    return { 
      totalSales, 
      totalQuantity, 
      orderCount, 
      orderIds: uniqueOrderIds, 
      categoryDistribution, 
      categoryQuantityDistribution,
      salespersonPerformance, 
      monthlyTrend 
    };
  }, [filteredData]);

  const resetFilters = () => initializeFilters(allData);

  const orderDetails = useMemo(() => {
    if (!selectedOrderId) return [];
    return allData.filter(d => d.id === selectedOrderId);
  }, [selectedOrderId, allData]);

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 p-4 text-center">
        <div className="bg-white p-8 rounded-2xl shadow-xl max-w-md text-center">
          <div className="text-6xl mb-4">⚠️</div>
          <h2 className="text-2xl font-bold text-slate-900 mb-2">连接失败</h2>
          <p className="text-slate-500 mb-6">{error}</p>
          <button onClick={() => window.location.reload()} className="inline-block bg-blue-600 text-white px-6 py-2 rounded-lg font-bold hover:bg-blue-700 transition-colors">
            重试连接
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 pb-12">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white text-2xl font-bold shadow-lg shadow-blue-200">S</div>
            <div>
              <div className="flex items-center gap-2">
                <h1 className="text-xl font-bold text-slate-900">销售数据洞察专家</h1>
                {sourceType === 'cloud' && (
                  <span className="hidden md:flex bg-green-100 text-green-700 text-[10px] px-2 py-0.5 rounded-full font-bold items-center">
                    <span className="w-1.5 h-1.5 bg-green-500 rounded-full mr-1 animate-pulse"></span>
                    LIVE: GOOGLE SHEETS
                  </span>
                )}
                {sourceType === 'local' && (
                  <span className="hidden md:flex bg-emerald-100 text-emerald-700 text-[10px] px-2 py-0.5 rounded-full font-bold items-center">
                    LOCAL: {localFileName?.toUpperCase()}
                  </span>
                )}
              </div>
              <p className="text-xs text-slate-500 hidden sm:block">多维交互式联动分析面板 (CFA)</p>
            </div>
          </div>
          <nav className="flex bg-slate-100 p-1 rounded-lg">
            <button 
              onClick={() => setActiveTab('dashboard')}
              className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${activeTab === 'dashboard' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-600 hover:text-slate-900'}`}
            >
              数据看板
            </button>
            <button 
              onClick={() => setActiveTab('table')}
              className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${activeTab === 'table' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-600 hover:text-slate-900'}`}
            >
              明细数据
            </button>
          </nav>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-8">
        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20 space-y-4">
            <div className="w-12 h-12 border-4 border-blue-200 border-t-blue-600 rounded-full animate-spin"></div>
            <p className="text-slate-500 font-medium">同步云端表格数据中...</p>
          </div>
        ) : (
          <>
            <FileSourceManager 
              sourceType={sourceType}
              localFileName={localFileName}
              localData={localData}
              onSourceChange={handleSourceChange}
              onFileUpload={handleFileUpload}
              onResetCloud={loadCloudData}
            />

            <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 mb-8">
              <div className="flex items-center justify-between mb-6">
                <div className="flex items-center">
                  <span className="w-1.5 h-4 bg-blue-600 rounded-full mr-2"></span>
                  <h2 className="text-sm font-bold text-slate-800 uppercase tracking-widest">
                    高级筛选中心
                  </h2>
                  <span className="ml-4 px-2 py-0.5 bg-green-50 text-green-600 text-[10px] rounded font-bold border border-green-100">维度联动已激活</span>
                </div>
                <div className="flex items-center gap-4">
                  <span className="text-xs text-slate-400 font-medium font-mono">符合条件记录: {filteredData.length} 条</span>
                  <button onClick={resetFilters} className="text-xs text-blue-600 hover:text-blue-700 font-bold uppercase tracking-wider transition-colors">
                    重置所有
                  </button>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                <MultiSelect 
                  label="月份"
                  options={dynamicFilterData.months.options}
                  counts={dynamicFilterData.months.counts}
                  selectedValues={filters.months}
                  onChange={(v) => setFilters({...filters, months: v})}
                  placeholder="筛选月份"
                />
                <MultiSelect 
                  label="客户"
                  options={dynamicFilterData.customers.options}
                  counts={dynamicFilterData.customers.counts}
                  selectedValues={filters.customers}
                  onChange={(v) => setFilters({...filters, customers: v})}
                  placeholder="筛选客户"
                />
                <MultiSelect 
                  label="销售员"
                  options={dynamicFilterData.salespeople.options}
                  counts={dynamicFilterData.salespeople.counts}
                  selectedValues={filters.salespeople}
                  onChange={(v) => setFilters({...filters, salespeople: v})}
                  placeholder="筛选销售员"
                />
                <MultiSelect 
                  label="品类"
                  options={dynamicFilterData.categories.options}
                  counts={dynamicFilterData.categories.counts}
                  selectedValues={filters.categories}
                  onChange={(v) => setFilters({...filters, categories: v})}
                  placeholder="筛选品类"
                />

                <div className="lg:col-span-2">
                  <MultiSelect 
                    label="物料名称"
                    options={dynamicFilterData.itemNames.options}
                    counts={dynamicFilterData.itemNames.counts}
                    selectedValues={filters.itemNames}
                    onChange={(v) => setFilters({...filters, itemNames: v})}
                    placeholder="筛选具体物料"
                  />
                </div>

                <div className="lg:col-span-2 flex gap-3">
                  <div className="flex-1">
                    <label className="block text-xs font-semibold text-slate-400 mb-1.5 uppercase tracking-wider">业务日期 (起)</label>
                    <input 
                      type="date"
                      value={filters.dateRange[0]}
                      onChange={(e) => setFilters({...filters, dateRange: [e.target.value, filters.dateRange[1]]})}
                      className="w-full bg-slate-50 border border-slate-200 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 rounded-lg px-3 py-2 text-sm text-slate-900 outline-none transition-all"
                    />
                  </div>
                  <div className="flex-1">
                    <label className="block text-xs font-semibold text-slate-400 mb-1.5 uppercase tracking-wider">业务日期 (止)</label>
                    <input 
                      type="date"
                      value={filters.dateRange[1]}
                      onChange={(e) => setFilters({...filters, dateRange: [filters.dateRange[0], e.target.value]})}
                      className="w-full bg-slate-50 border border-slate-200 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 rounded-lg px-3 py-2 text-sm text-slate-900 outline-none transition-all"
                    />
                  </div>
                </div>
              </div>
            </section>

            <div className="animate-in fade-in duration-500">
              {filteredData.length > 0 ? (
                activeTab === 'dashboard' ? (
                  <Dashboard 
                    summary={summary} 
                    filteredData={filteredData} 
                    onSelectOrderId={setSelectedOrderId} 
                  />
                ) : (
                  <DataTable data={filteredData} onSelectOrderId={setSelectedOrderId} />
                )
              ) : (
                <div className="flex flex-col items-center justify-center py-24 bg-white rounded-3xl border border-dashed border-slate-200 shadow-inner">
                  <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6">
                    <span className="text-4xl text-slate-300">🔎</span>
                  </div>
                  <h3 className="text-xl font-bold text-slate-800">未找到匹配的销售记录</h3>
                  <p className="text-slate-500 mt-2 max-w-sm text-center">由于采用了多维联动逻辑，某些选项组合在数据集中可能不存在。请尝试切换数据源或重置筛选器。</p>
                  <button onClick={resetFilters} className="mt-8 bg-blue-600 text-white px-8 py-3 rounded-xl text-sm font-bold shadow-lg shadow-blue-200 hover:bg-blue-700 transition-all">
                    清空并重置
                  </button>
                </div>
              )}
            </div>
          </>
        )}
      </main>

      {selectedOrderId && (
        <OrderDetailModal 
          orderId={selectedOrderId} 
          records={orderDetails} 
          onClose={() => setSelectedOrderId(null)} 
        />
      )}

      <footer className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-16 pb-12 text-center">
        <div className="pt-8 border-t border-slate-200">
          <p className="text-slate-400 text-xs font-medium tracking-widest uppercase mb-2">Sales Insight Pro</p>
          <p className="text-slate-300 text-[10px]">后端: Google Sheets + Local CSV · 引擎: Gemini 3 Flash · 计价单位: CFA</p>
        </div>
      </footer>
    </div>
  );
};

