import { SalesRecord } from '../types';

const SHEET_ID = '190CYOeWCVB68eCOszi7VwADf3N3jHwN7msmI1jmgzlg';
const GID = '1447308255';
const CSV_URL = `https://docs.google.com/spreadsheets/d/${SHEET_ID}/export?format=csv&gid=${GID}`;

/**
 * 将本地数据同步至用户部署的 Google Apps Script Web App
 * 地址: https://script.google.com/macros/s/AKfycbxAjMNShi09cF-1lMUt0BDRckFWTRBbXwmi7hbHPx8vtSu1q1AzGdh8ZCKGhiTc94l/exec
 */
export const syncToCloud = async (data: SalesRecord[]): Promise<boolean> => {
  const APPS_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbxAjMNShi09cF-1lMUt0BDRckFWTRBbXwmi7hbHPx8vtSu1q1AzGdh8ZCKGhiTc94l/exec';

  try {
    // 使用 fetch 发送到 Google Apps Script
    // 注意：由于 GAS 的跨域限制，使用 no-cors 模式是最稳健的选择。
    // 在 GAS 的 doPost(e) 中，应通过 JSON.parse(e.postData.contents) 来解析数据。
    await fetch(APPS_SCRIPT_URL, {
      method: 'POST',
      mode: 'no-cors', 
      headers: {
