import React, { useRef, useState } from 'react';
import { processCsvText, processExcelBuffer, syncToCloud } from '../services/dataService';
import { SalesRecord } from '../types';

interface FileSourceManagerProps {
  sourceType: 'cloud' | 'local';
  localFileName: string | null;
  localData: SalesRecord[];
  onSourceChange: (type: 'cloud' | 'local') => void;
  onFileUpload: (data: SalesRecord[], fileName: string) => void;
  onResetCloud: () => void;
}

const FileSourceManager: React.FC<FileSourceManagerProps> = ({ 
  sourceType, 
  localFileName, 
  localData,
  onSourceChange, 
  onFileUpload,
  onResetCloud 
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'uploading' | 'success'>('idle');

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const fileName = file.name.toLowerCase();
    const isExcel = fileName.endsWith('.xlsx') || fileName.endsWith('.xls');

    const reader = new FileReader();

    reader.onload = (event) => {
      try {
        let data: SalesRecord[] = [];
        if (isExcel) {
          const buffer = event.target?.result as ArrayBuffer;
          data = processExcelBuffer(buffer);
        } else {
          const text = event.target?.result as string;
          data = processCsvText(text);
        }

        if (data.length === 0) {
          throw new Error('未在文件中发现有效数据');
        }

        onFileUpload(data, file.name);
        setSyncStatus('idle');
      } catch (err) {
        console.error('Parsing error:', err);
        alert(`文件解析失败: ${err instanceof Error ? err.message : '未知错误'}。请确保表头顺序为：出库单号, 月份, 日期, 客户, 销售员, 品类, 物料名称, 数量, 单价, 价税合计。`);
      }
    };

    if (isExcel) {
      reader.readAsArrayBuffer(file);
    } else {
      reader.readAsText(file);
    }
  };

  const handleSyncToCloud = async () => {
    if (localData.length === 0) return;

    setIsSyncing(true);
    setSyncStatus('uploading');

    try {
      const success = await syncToCloud(localData);
      if (success) {
        setSyncStatus('success');
        setTimeout(() => {
          setIsSyncing(false);
        }, 2000);
      }
    } catch (err) {
      alert('同步失败，请检查网络或部署状态');
      setSyncStatus('idle');
      setIsSyncing(false);
    }
  };

  return (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 mb-8 animate-in fade-in duration-500 relative overflow-hidden">
      {/* 同步遮罩层 */}
      {isSyncing && (
        <div className="absolute inset-0 z-30 bg-white/95 backdrop-blur-sm flex flex-col items-center justify-center animate-in fade-in duration-300">
          <div className="relative w-16 h-16 mb-4">
            {syncStatus === 'uploading' ? (
              <>
                <div className="absolute inset-0 border-4 border-indigo-100 rounded-full"></div>
                <div className="absolute inset-0 border-4 border-indigo-600 rounded-full border-t-transparent animate-spin"></div>
              </>
            ) : (
              <div className="absolute inset-0 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 animate-in zoom-in">
                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" /></svg>
              </div>
            )}
          </div>
          <p className="text-sm font-bold text-slate-700">
            {syncStatus === 'uploading' ? '正在同步数据至 Google Sheets...' : '同步成功！数据已持久化'}
          </p>
          <p className="text-[10px] text-slate-400 mt-1">
            {syncStatus === 'uploading' ? '正在调用 Apps Script API 接口' : '你可以切换到实时云端视图查看更新'}
          </p>
        </div>
      )}

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="flex-1">
          <h2 className="text-sm font-bold text-slate-800 uppercase tracking-widest flex items-center gap-2 mb-2">
            <span className="w-1.5 h-4 bg-indigo-600 rounded-full"></span>
            数据源管理器
          </h2>
          <div className="flex gap-2">
            <button 
              onClick={() => onSourceChange('cloud')}
              className={`px-4 py-2 rounded-xl text-xs font-bold transition-all border ${sourceType === 'cloud' ? 'bg-indigo-50 border-indigo-200 text-indigo-700 shadow-sm' : 'bg-white border-slate-200 text-slate-400 hover:border-indigo-200 hover:text-indigo-500'}`}
            >
              🌐 实时云端 (Google Sheets)
            </button>
            <button 
              onClick={() => onSourceChange('local')}
              className={`px-4 py-2 rounded-xl text-xs font-bold transition-all border ${sourceType === 'local' ? 'bg-emerald-50 border-emerald-200 text-emerald-700 shadow-sm' : 'bg-white border-slate-200 text-slate-400 hover:border-emerald-200 hover:text-emerald-500'}`}
            >
              📁 本地文件上传
            </button>
          </div>
        </div>

        <div className="flex-[1.5]">
          {sourceType === 'cloud' ? (
            <div className="bg-slate-50 p-4 rounded-xl border border-dashed border-slate-200 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-indigo-100 rounded-full flex items-center justify-center text-indigo-600">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 15a4 4 0 004 4h9a5 5 0 10-.1-9.999 5.002 5.002 0 10-9.78 2.096A4.001 4.001 0 003 15z" /></svg>
                </div>
                <div>
                  <p className="text-xs font-bold text-slate-700">已连接至 Google 表格</p>
                  <p className="text-[10px] text-slate-400">实时同步最新销售数据记录</p>
                </div>
              </div>
              <button 
                onClick={onResetCloud}
                className="text-[10px] font-black text-indigo-600 hover:text-indigo-800 uppercase tracking-tighter"
              >
                强制刷新数据
              </button>
            </div>
          ) : (
            <div className="flex items-center gap-4">
              <div 
                onClick={() => fileInputRef.current?.click()}
                className="flex-1 group cursor-pointer bg-emerald-50/30 hover:bg-emerald-50 p-4 rounded-xl border-2 border-dashed border-emerald-200 hover:border-emerald-400 transition-all flex items-center justify-between"
              >
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  onChange={handleFileChange} 
                  accept=".csv, .xlsx, .xls" 
                  className="hidden" 
                />
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 group-hover:scale-110 transition-transform">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                  </div>
                  <div className="max-w-[150px]">
                    <p className="text-xs font-bold text-emerald-800 truncate">
                      {localFileName || '选择 CSV/Excel 文件'}
                    </p>
                    <p className="text-[10px] text-emerald-600 opacity-70">支持 XLSX, XLS, CSV</p>
                  </div>
                </div>
              </div>

              {localFileName && (
                <button 
                  onClick={handleSyncToCloud}
                  className="bg-indigo-600 text-white px-5 py-4 rounded-xl font-bold text-xs flex flex-col items-center gap-1 hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200 group"
                >
                  <svg className="w-5 h-5 group-hover:animate-bounce" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
                  <span>同步至云端</span>
                </button>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default FileSourceManager;

