### 2. 建议的后端代码 (Google Apps Script)

为了配合前端的改动，请确保你的 **Google Apps Script** 脚本如下编写（包含数据清洗逻辑）：

```javascript
/**
 * 处理前端发来的 POST 请求
 * 前端使用 text/plain 发送 JSON 字符串
 */
function doPost(e) {
  try {
    // 1. 解析前端数据
    var payload = JSON.parse(e.postData.contents);
    var records = payload.records;

    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getSheetByName('Sheet1') || ss.getSheets()[0];

    // 2. 获取现有数据单号，用于清洗（防重）
    var lastRow = sheet.getLastRow();
    var existingIds = [];
    if (lastRow > 1) {
      existingIds = sheet.getRange(2, 1, lastRow - 1, 1).getValues().flat().map(String);
    }

    // 3. 执行清洗与写入
    records.forEach(function(row) {
      // 清洗逻辑 A: 检查单号是否已存在
      if (existingIds.indexOf(String(row.id)) > -1) {
        return; // 跳过重复单号
      }

      // 清洗逻辑 B: 过滤掉总金额为 0 的异常数据
      if (row.totalAmount <= 0) {
        return;
      }

      // 清洗逻辑 C: 格式化日期字符串
      var formattedDate = row.date;
      if (row.date && row.date.indexOf('T') > -1) {
        formattedDate = row.date.split('T')[0];
      }

      // 4. 写入 Google Sheet
      sheet.appendRow([
        row.id,
        row.month,
        formattedDate,
        row.customer,
        row.salesperson,
        row.category,
        row.itemName,
        row.quantity,
        row.unitPrice,
        row.totalAmount
      ]);
    });

    return ContentService.createTextOutput("Sync Success").setMimeType(ContentService.MimeType.TEXT);

  } catch (err) {
    return ContentService.createTextOutput("Error: " + err.message).setMimeType(ContentService.MimeType.TEXT);
  }
}
```

### 操作要点：
1.  **发布脚本**：在 GAS 编辑器中点击“部署” -> “新建部署”，选择“网页应用”，并将“谁可以访问”设置为“任何人”（Anyone）。
2.  **权限**：第一次运行或部署时，Google 会要求授权。请务必完成授权，否则脚本无法写入你的表格。
3.  **前端同步**：现在上传本地 Excel 后点击“同步至云端”，数据将通过 `text/plain` 安全送达，后端脚本会自动执行去重和格式清洗。

