    customer: String(cols[3] || ''),
    salesperson: String(cols[4] || ''),
    category: String(cols[5] || ''),
    itemName: String(cols[6] || ''),
    quantity: parseFloat(cols[7]) || 0,
    unitPrice: parseFloat(cols[8]) || 0,
    totalAmount: parseFloat(cols[9]) || 0
  }));
};

/**
 * 解析 CSV 文本
 */
export const processCsvText = (csvText: string): SalesRecord[] => {
  const rows = csvText.split(/\r?\n/).filter(line => line.trim() !== '');
  const parsedRows = rows.map(line => {
    const result: string[] = [];
    let currentField = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') inQuotes = !inQuotes;
      else if (char === ',' && !inQuotes) {
        result.push(currentField.replace(/^"|"$/g, '').trim());
        currentField = '';
      } else currentField += char;
    }
    result.push(currentField.replace(/^"|"$/g, '').trim());
    return result;
  });

  const dataRows = parsedRows.slice(1);
  return dataRows.map((cols, index) => ({
    id: cols[0] || `ID-${index}`,
    month: cols[1] || '',
    date: cols[2] || '',
    customer: cols[3] || '',
    salesperson: cols[4] || '',
    category: cols[5] || '',
    itemName: cols[6] || '',
    quantity: parseFloat(cols[7]) || 0,
    unitPrice: parseFloat(cols[8]) || 0,
    totalAmount: parseFloat(cols[9]) || 0
  }));
};

export const fetchSalesData = async (): Promise<SalesRecord[]> => {
  try {
    const response = await fetch(CSV_URL);
    if (!response.ok) {
        throw new Error('表格连接受阻。请检查：1. 表格 ID 是否正确；2. 是否已设为“知道链接的任何人可查看”；3. 网络是否可访问 Google 域。');
    }
    const csvText = await response.text();
    // 检查是否返回了 HTML (通常是登录页面)
    if (csvText.includes('<!DOCTYPE html>')) {
        throw new Error('权限验证失败。Google 返回了登录页面，请确保表格已公开共享。');
    }
    return processCsvText(csvText);
  } catch (error) {
    console.error('Fetch Error:', error);
    throw error;
  }
};

import React, { useRef, useState } from 'react';
import { processCsvText, processExcelBuffer, syncToCloud } from '../services/dataService';
import { SalesRecord } from '../types';

interface FileSourceManagerProps {
  sourceType: 'cloud' | 'local';
  localFileName: string | null;
  localData: SalesRecord[];
  onSourceChange: (type: 'cloud' | 'local') => void;
  onFileUpload: (data: SalesRecord[], fileName: string) => void;
  onRefreshCloud: () => void;
}

const FileSourceManager: React.FC<FileSourceManagerProps> = ({ 
  sourceType, 
  localFileName, 
  localData,
  onSourceChange, 
  onFileUpload,
  onRefreshCloud 
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncDone, setSyncDone] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const name = file.name.toLowerCase();
    const isExcel = name.endsWith('.xlsx') || name.endsWith('.xls');
    const reader = new FileReader();

    reader.onload = (event) => {
      try {
        let data: SalesRecord[] = [];
        if (isExcel) {
          data = processExcelBuffer(event.target?.result as ArrayBuffer);
        } else {
          data = processCsvText(event.target?.result as string);
        }

        if (data.length === 0) throw new Error('文件中未检测到有效记录');
        onFileUpload(data, file.name);
        setSyncDone(false);
      } catch (err) {
        alert(`解析失败: ${err instanceof Error ? err.message : '未知错误'}`);
      }
    };

    if (isExcel) reader.readAsArrayBuffer(file);
    else reader.readAsText(file);
  };

  const handleSync = async () => {
    setIsSyncing(true);
    try {
      await syncToCloud(localData);
      setSyncDone(true);
      setTimeout(() => setIsSyncing(false), 2000);
    } catch (err) {
      alert('同步失败，请检查网络');
      setIsSyncing(false);
    }
  };

  return (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 mb-8 relative overflow-hidden">
      {isSyncing && (
        <div className="absolute inset-0 z-50 bg-white/90 backdrop-blur-sm flex flex-col items-center justify-center animate-in fade-in duration-300">
           {!syncDone ? (
             <>
               <div className="w-10 h-10 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mb-3"></div>
               <p className="text-sm font-bold text-slate-700">正在同步至 Google 表格并进行数据清洗...</p>
             </>
           ) : (
             <>
               <div className="w-12 h-12 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-3 animate-bounce">
                 <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" /></svg>
               </div>
               <p className="text-sm font-bold text-green-700">同步成功！请切换回云端模式查看</p>
             </>
           )}
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div>
          <h2 className="text-sm font-black text-slate-800 uppercase tracking-[0.2em] mb-3 flex items-center gap-2">
            <span className="w-1.5 h-4 bg-indigo-600 rounded-full"></span>
            数据源管理器
          </h2>
          <div className="flex p-1 bg-slate-100 rounded-xl">
            <button 
              onClick={() => onSourceChange('cloud')}
              className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${sourceType === 'cloud' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-indigo-400'}`}
            >
              🌐 实时云端
            </button>
            <button 
              onClick={() => onSourceChange('local')}
              className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${sourceType === 'local' ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-500 hover:text-emerald-400'}`}
            >
              📁 本地文件
            </button>
          </div>
        </div>

        <div className="flex-1 w-full md:w-auto">
          {sourceType === 'cloud' ? (
            <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-indigo-600 rounded-full flex items-center justify-center text-white font-bold shadow-lg shadow-indigo-100 text-lg">G</div>
                <div>
                  <p className="text-xs font-bold text-indigo-900">Google Sheets 连接中</p>
                  <p className="text-[10px] text-indigo-400">实时拉取并同步最新记录</p>
                </div>
              </div>
              <button onClick={onRefreshCloud} className="text-xs font-bold text-indigo-600 hover:bg-indigo-100 px-3 py-1.5 rounded-lg transition-colors">强制刷新</button>
            </div>
          ) : (
            <div className="flex gap-4 items-center">
              <div 
                onClick={() => fileInputRef.current?.click()}
                className="flex-1 group cursor-pointer border-2 border-dashed border-emerald-200 bg-emerald-50/20 hover:bg-emerald-50 hover:border-emerald-400 p-4 rounded-xl transition-all flex items-center justify-between"
              >
                <input type="file" ref={fileInputRef} onChange={handleFileChange} accept=".csv, .xlsx, .xls" className="hidden" />
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center group-hover:scale-110 transition-transform">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                  </div>
                  <div>
                    <p className="text-xs font-bold text-emerald-900 truncate max-w-[150px]">{localFileName || '选择 Excel/CSV 文件'}</p>
                    <p className="text-[10px] text-emerald-400">点击浏览本地文件并分析</p>
                  </div>
                </div>
              </div>
              {localData.length > 0 && (
                <button 
                  onClick={handleSync}
                  className="bg-indigo-600 text-white p-4 rounded-xl font-bold flex flex-col items-center gap-1 hover:bg-indigo-700 shadow-lg shadow-indigo-100 transition-all"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
                  <span className="text-[10px]">同步云端</span>
                </button>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default FileSourceManager;

import React, { useState, useMemo, useEffect } from 'react';
import { FilterState, SalesSummary, SalesRecord } from './types';
import Dashboard from './components/Dashboard';
import DataTable from './components/DataTable';
import MultiSelect from './components/MultiSelect';
import OrderDetailModal from './components/OrderDetailModal';
import FileSourceManager from './components/FileSourceManager';
import { fetchSalesData } from './services/dataService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'table'>('dashboard');
  const [sourceType, setSourceType] = useState<'cloud' | 'local'>('cloud');

  const [cloudData, setCloudData] = useState<SalesRecord[]>([]);
  const [localData, setLocalData] = useState<SalesRecord[]>([]);
  const [localFileName, setLocalFileName] = useState<string | null>(null);

  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedOrderId, setSelectedOrderId] = useState<string | null>(null);

  const [filters, setFilters] = useState<FilterState>({
    months: [],
    dateRange: ['', ''],
    customers: [],
    salespeople: [],
    categories: [],
    itemNames: []
  });

  const allData = sourceType === 'cloud' ? cloudData : localData;

  const loadCloudData = async () => {
    try {
      setIsLoading(true);
      setError(null);
      const data = await fetchSalesData();
      setCloudData(data);
      if (sourceType === 'cloud') initializeFilters(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : '连接 Google 表格失败');
    } finally {
      setIsLoading(false);
    }
  };

  const initializeFilters = (data: SalesRecord[]) => {
    const uniqueMonths = Array.from(new Set(data.map(d => d.month))).sort().reverse();
    const uniqueCustomers = Array.from(new Set(data.map(d => d.customer))).sort();
    const uniqueSalespeople = Array.from(new Set(data.map(d => d.salesperson))).sort();
    const uniqueCategories = Array.from(new Set(data.map(d => d.category))).sort();
    const uniqueItems = Array.from(new Set(data.map(d => d.itemName))).sort();

    setFilters({
      months: uniqueMonths,
      dateRange: ['', ''],
      customers: uniqueCustomers,
      salespeople: uniqueSalespeople,
      categories: uniqueCategories,
      itemNames: uniqueItems
    });
  };

  useEffect(() => {
    loadCloudData();
  }, []);

  const handleFileUpload = (data: SalesRecord[], fileName: string) => {
    setLocalData(data);
    setLocalFileName(fileName);
    setSourceType('local');
    initializeFilters(data);
  };

  const handleSourceChange = (type: 'cloud' | 'local') => {
    setSourceType(type);
    const dataToInitialize = type === 'cloud' ? cloudData : localData;
    if (dataToInitialize.length > 0) initializeFilters(dataToInitialize);
  };

  /** 筛选逻辑 */
  const getDynamicDimensionData = (dimension: keyof SalesRecord) => {
    const filteredByOthers = allData.filter(item => {
      const matchMonth = dimension === 'month' || filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = dimension === 'salesperson' || filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = dimension === 'category' || filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = dimension === 'customer' || filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = dimension === 'itemName' || filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (
        (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
        (!filters.dateRange[1] || item.date <= filters.dateRange[1])
      );
      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });

    const counts: Record<string, number> = {};
    filteredByOthers.forEach(item => {
      const val = item[dimension] as string;
      if (val) counts[val] = (counts[val] || 0) + 1;
    });

    const options = Object.keys(counts).sort();
    if (dimension === 'month') options.reverse();
    return { options, counts };
  };

  const dynamicFilterData = useMemo(() => ({
    months: getDynamicDimensionData('month'),
    customers: getDynamicDimensionData('customer'),
    salespeople: getDynamicDimensionData('salesperson'),
    categories: getDynamicDimensionData('category'),
    itemNames: getDynamicDimensionData('itemName')
  }), [allData, filters]);

  const filteredData = useMemo(() => {
    return allData.filter(item => {
      const matchMonth = filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
                        (!filters.dateRange[1] || item.date <= filters.dateRange[1]);
      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });
  }, [allData, filters]);

  const summary: SalesSummary = useMemo(() => {
    const totalSales = filteredData.reduce((acc, cur) => acc + cur.totalAmount, 0);
    const totalQuantity = filteredData.reduce((acc, cur) => acc + cur.quantity, 0);
    const uniqueOrderIds = Array.from(new Set(filteredData.map(d => d.id))).sort();

    const monthlyMap = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const existing = monthlyMap.get(d.month) || { sales: 0, quantity: 0 };
      monthlyMap.set(d.month, {
        sales: existing.sales + d.totalAmount,
        quantity: existing.quantity + d.quantity
      });
    });
    const monthlyTrend = Array.from(monthlyMap.entries()).map(([name, val]) => ({ name, ...val })).sort((a, b) => a.name.localeCompare(b.name));

    const catMap = new Map<string, number>();
    const catQtyMap = new Map<string, number>();
    filteredData.forEach(d => {
      catMap.set(d.category, (catMap.get(d.category) || 0) + d.totalAmount);
      catQtyMap.set(d.category, (catQtyMap.get(d.category) || 0) + d.quantity);
    });

    const spMap = new Map<string, number>();
    filteredData.forEach(d => spMap.set(d.salesperson, (spMap.get(d.salesperson) || 0) + d.totalAmount));

    return { 
      totalSales, 
      totalQuantity, 
      orderCount: uniqueOrderIds.length, 
      orderIds: uniqueOrderIds, 
      categoryDistribution: Array.from(catMap.entries()).map(([name, value]) => ({ name, value })),
      categoryQuantityDistribution: Array.from(catQtyMap.entries()).map(([name, value]) => ({ name, value })),
      salespersonPerformance: Array.from(spMap.entries()).map(([name, value]) => ({ name, value })).sort((a, b) => b.value - a.value),
      monthlyTrend 
    };
  }, [filteredData]);

  if (error && sourceType === 'cloud') {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 p-4 text-center">
        <div className="bg-white p-8 rounded-3xl shadow-2xl max-w-md border border-red-100">
          <div className="text-6xl mb-4">🔗</div>
          <h2 className="text-2xl font-black text-slate-900 mb-2">Google 表格连接受限</h2>
          <p className="text-slate-500 text-sm mb-6 leading-relaxed">{error}</p>
          <div className="space-y-3">
            <button onClick={loadCloudData} className="w-full bg-indigo-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100">重试连接云端</button>
            <button onClick={() => setSourceType('local')} className="w-full bg-emerald-50 text-emerald-700 px-6 py-3 rounded-xl font-bold hover:bg-emerald-100 transition-all">切换至本地模式</button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 pb-12">
      <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-2xl font-black shadow-lg shadow-indigo-100">S</div>
            <div>
              <div className="flex items-center gap-2">
                <h1 className="text-lg font-black text-slate-900">销售数据洞察专家</h1>
                <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold border ${sourceType === 'cloud' ? 'bg-indigo-50 text-indigo-600 border-indigo-100' : 'bg-emerald-50 text-emerald-600 border-emerald-100'}`}>
                   {sourceType === 'cloud' ? '实时云端模式' : '本地文件模式'}
                </span>
              </div>
            </div>
          </div>
          <nav className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setActiveTab('dashboard')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'dashboard' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-900'}`}>看板</button>
            <button onClick={() => setActiveTab('table')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'table' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-900'}`}>明细</button>
          </nav>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-8">
        <FileSourceManager 
          sourceType={sourceType} 
          localFileName={localFileName} 
          localData={localData}
          onSourceChange={handleSourceChange}
          onFileUpload={handleFileUpload}
          onRefreshCloud={loadCloudData}
        />

        {isLoading && sourceType === 'cloud' ? (
          <div className="flex flex-col items-center justify-center py-20 space-y-4">
            <div className="w-12 h-12 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
            <p className="text-slate-500 font-bold">正在同步云端数据...</p>
          </div>
        ) : (
          <>
            <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 mb-8">
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-sm font-black text-slate-800 uppercase tracking-widest flex items-center gap-2">
                  <span className="w-1.5 h-4 bg-indigo-600 rounded-full"></span> 筛选中心
                </h2>
                <span className="text-xs text-slate-400 font-mono">共 {filteredData.length} 条符合条件</span>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                <MultiSelect label="月份" options={dynamicFilterData.months.options} counts={dynamicFilterData.months.counts} selectedValues={filters.months} onChange={(v) => setFilters({...filters, months: v})} />
                <MultiSelect label="客户" options={dynamicFilterData.customers.options} counts={dynamicFilterData.customers.counts} selectedValues={filters.customers} onChange={(v) => setFilters({...filters, customers: v})} />
                <MultiSelect label="销售员" options={dynamicFilterData.salespeople.options} counts={dynamicFilterData.salespeople.counts} selectedValues={filters.salespeople} onChange={(v) => setFilters({...filters, salespeople: v})} />
                <MultiSelect label="品类" options={dynamicFilterData.categories.options} counts={dynamicFilterData.categories.counts} selectedValues={filters.categories} onChange={(v) => setFilters({...filters, categories: v})} />
              </div>
            </section>

            <div className="animate-in fade-in duration-500">
              {filteredData.length > 0 ? (
                activeTab === 'dashboard' ? (
                  <Dashboard summary={summary} filteredData={filteredData} onSelectOrderId={setSelectedOrderId} />
                ) : (
                  <DataTable data={filteredData} onSelectOrderId={setSelectedOrderId} />
                )
              ) : (
                <div className="py-24 bg-white rounded-3xl border border-dashed border-slate-200 text-center">
                  <div className="text-5xl mb-4">🔎</div>
                  <h3 className="text-xl font-bold text-slate-800">未找到匹配数据</h3>
                  <p className="text-slate-500 mt-2">请尝试调整筛选器组合</p>
                </div>
              )}
            </div>
          </>
        )}
      </main>

      {selectedOrderId && (
        <OrderDetailModal orderId={selectedOrderId} records={allData.filter(d => d.id === selectedOrderId)} onClose={() => setSelectedOrderId(null)} />
      )}
    </div>
  );
};

