                    </button>
                  </div>
                  <button onClick={() => { setSelectedCategory(null); setSelectedCustomerInDrillDown(null); setSelectedRowIndexes(new Set()); }} className="p-2 hover:bg-slate-100 rounded-full text-slate-400 hover:text-slate-600 transition-colors shadow-sm">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
