                            />
                          </th>
                          <th className="px-3 py-2 text-left font-bold text-slate-400">单号</th>
                          <th className="px-3 py-2 text-left font-bold text-slate-400">日期</th>
                          <th className="px-3 py-2 text-left font-bold text-slate-400">物料名称</th>
                          {!selectedCustomerInDrillDown && <th className="px-3 py-2 text-left font-bold text-slate-400">客户</th>}
                          <th className="px-3 py-2 text-right font-bold text-slate-400">数量</th>
                          <th className="px-3 py-2 text-right font-bold text-slate-400">金额</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {drillDownData.records.slice(0, 50).map((r, i) => (
                          <tr 
                            key={i} 
                            className={`hover:bg-slate-50 transition-colors cursor-pointer ${selectedRowIndexes.has(i) ? 'bg-blue-50/50' : ''}`}
                            onClick={() => handleToggleRow(i)}
                          >
                            <td className="px-3 py-2" onClick={(e) => e.stopPropagation()}>
                              <input 
                                type="checkbox" 
                                className="rounded border-slate-300 text-blue-600 focus:ring-blue-500 cursor-pointer"
                                checked={selectedRowIndexes.has(i)}
                                onChange={() => handleToggleRow(i)}
                              />
                            </td>
                            <td className="px-3 py-2 text-blue-600 font-mono font-bold">
                                <button onClick={(e) => { e.stopPropagation(); onSelectOrderId(r.id); }}>{r.id}</button>
                            </td>
                            <td className="px-3 py-2 text-slate-500">{r.date}</td>
                            <td className="px-3 py-2 text-slate-900 font-medium truncate max-w-[120px]">{r.itemName}</td>
                            {!selectedCustomerInDrillDown && <td className="px-3 py-2 text-slate-600 truncate max-w-[80px]">{r.customer}</td>}
                            <td className="px-3 py-2 text-right font-mono text-slate-600">{r.quantity}</td>
                            <td className="px-3 py-2 text-right font-mono text-slate-900">{r.totalAmount.toLocaleString()}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </section>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center"><span className="mr-2">🏆</span> 销售员业绩排行 (CFA)</h3>
        <div className="h-[350px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical">
              <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={80} tick={{fill: '#475569', fontWeight: 500}} />
              <Tooltip cursor={{fill: '#f8fafc'}} formatter={(value: number) => [`${value.toLocaleString()} CFA`, '销售额']} />
              <Bar dataKey="value" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={24} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-indigo-900 text-white p-8 rounded-2xl shadow-xl overflow-hidden relative">
        <div className="relative z-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
            <div>
              <h3 className="text-xl font-bold flex items-center"><span className="mr-2">✨</span> Gemini 智能分析</h3>
              <p className="text-indigo-200 text-sm mt-1">让 AI 为您的销售数据提供专业的商业建议 (以 CFA 计价)</p>
            </div>
            <button onClick={handleGetAIInsights} disabled={loading} className="bg-white text-indigo-900 px-6 py-2.5 rounded-full font-bold hover:bg-indigo-50 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center min-w-[140px]">
              {loading ? (
                <><svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-indigo-900" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>分析中...</>
              ) : '立即生成洞察'}
            </button>
          </div>
          {aiText ? (<div className="bg-indigo-800/50 p-6 rounded-xl border border-indigo-700 backdrop-blur-sm animate-fade-in whitespace-pre-wrap leading-relaxed text-indigo-50">{aiText}</div>
          ) : (<div className="flex flex-col items-center justify-center py-12 border-2 border-dashed border-indigo-700 rounded-xl"><span className="text-4xl mb-4">💡</span><p className="text-indigo-300">点击按钮，获取关于当前筛选数据的 AI 经营建议</p></div>)}
        </div>
        <div className="absolute -bottom-24 -right-24 w-64 h-64 bg-indigo-500/20 rounded-full blur-3xl"></div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Legend, Cell as RechartsCell
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';
import { getAIInsights } from '../services/geminiService';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

type RecordStatus = '正常' | '待核对' | '有疑问';

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [aiText, setAiText] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [drillDownMetric, setDrillDownMetric] = useState<'sales' | 'quantity'>('sales');
  const [showSummaryTable, setShowSummaryTable] = useState(false);
  const [selectedCustomerInDrillDown, setSelectedCustomerInDrillDown] = useState<string | null>(null);

  // 记录选中的行索引
  const [selectedRowIndexes, setSelectedRowIndexes] = useState<Set<number>>(new Set());
  // 记录每行的自定义状态（下拉选项）
  const [recordStatuses, setRecordStatuses] = useState<Record<number, RecordStatus>>({});
  // 批量操作下拉菜单状态
  const [isBatchMenuOpen, setIsBatchMenuOpen] = useState(false);

  const batchMenuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (batchMenuRef.current && !batchMenuRef.current.contains(event.target as Node)) {
        setIsBatchMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleGetAIInsights = async () => {
    setLoading(true);
    const insights = await getAIInsights(summary);
    setAiText(insights || '');
    setLoading(false);
  };

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], customers: [], records: [] };

    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const customersMap = new Map<string, { sales: number; qty: number; orderIds: Set<string> }>();
    const allRecordsForCategory: SalesRecord[] = [];

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        allRecordsForCategory.push(record);

        const itemExisting = itemsMap.get(record.itemName) || { sales: 0, qty: 0 };
        itemsMap.set(record.itemName, {
          sales: itemExisting.sales + record.totalAmount,
          qty: itemExisting.qty + record.quantity
        });

        const customerExisting = customersMap.get(record.customer) || { sales: 0, qty: 0, orderIds: new Set() };
        customerExisting.orderIds.add(record.id);
        customersMap.set(record.customer, {
          sales: customerExisting.sales + record.totalAmount,
          qty: customerExisting.qty + record.quantity,
          orderIds: customerExisting.orderIds
        });
      }
    });

    const items = Array.from(itemsMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty, orderIds: Array.from(val.orderIds).sort() }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const filteredRecords = selectedCustomerInDrillDown 
      ? allRecordsForCategory.filter(r => r.customer === selectedCustomerInDrillDown)
      : allRecordsForCategory;

    return { 
      items, 
      customers,
      records: filteredRecords.sort((a, b) => b.date.localeCompare(a.date)) 
    };
  }, [selectedCategory, filteredData, drillDownMetric, selectedCustomerInDrillDown]);

  const selectionSummary = useMemo(() => {
    let count = 0;
    let amount = 0;
    let qty = 0;
    selectedRowIndexes.forEach(idx => {
      const record = drillDownData.records[idx];
      if (record) {
        count++;
        amount += record.totalAmount;
        qty += record.quantity;
      }
    });
    return { count, amount, qty };
  }, [selectedRowIndexes, drillDownData.records]);

  const onPieClick = (data: any, metric: 'sales' | 'quantity') => {
    setDrillDownMetric(metric);
    if (selectedCategory === data.name) {
      setSelectedCategory(null);
      setSelectedCustomerInDrillDown(null);
      setSelectedRowIndexes(new Set());
    } else {
      setSelectedCategory(data.name);
      setSelectedCustomerInDrillDown(null);
      setSelectedRowIndexes(new Set());
    }
  };

  const onCustomerClick = (data: any) => {
    const customerName = data.name || data.value;
    if (customerName) {
      const newCustomer = customerName === selectedCustomerInDrillDown ? null : customerName;
      setSelectedCustomerInDrillDown(newCustomer);
      setSelectedRowIndexes(new Set());
    }
  };

  const handleToggleRow = (index: number) => {
    const newSet = new Set(selectedRowIndexes);
    if (newSet.has(index)) newSet.delete(index);
    else newSet.add(index);
    setSelectedRowIndexes(newSet);
  };

  const handleToggleAll = () => {
    if (selectedRowIndexes.size === drillDownData.records.length) {
      setSelectedRowIndexes(new Set());
    } else {
      const newSet = new Set<number>();
      drillDownData.records.forEach((_, i) => newSet.add(i));
      setSelectedRowIndexes(newSet);
    }
  };

  const updateStatus = (index: number, status: RecordStatus) => {
    setRecordStatuses(prev => ({ ...prev, [index]: status }));
  };

  const CustomYAxisTick = (props: any) => {
    const { x, y, payload } = props;
    const isSelected = payload.value === selectedCustomerInDrillDown;
    return (
      <g transform={`translate(${x},${y})`}>
        <text
          x={-10} y={0} dy={4} textAnchor="end"
          fill={isSelected ? '#2563eb' : '#475569'}
          className={`text-[10px] font-bold cursor-pointer hover:fill-blue-600 transition-colors ${isSelected ? 'underline' : ''}`}
          onClick={() => onCustomerClick(payload)}
        >
          {payload.value}
        </text>
      </g>
    );
  };

  return (
    <div className="space-y-8">
      {/* KPI Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KpiCard title="总销售额" value={`${summary.totalSales.toLocaleString()} CFA`} sub="当前筛选总额" icon="💰" />
        <KpiCard title="总出库数量" value={summary.totalQuantity.toLocaleString()} sub="物料销售总数" icon="📦" />
        <KpiCard title="出库单号" value={`${summary.orderCount} 个单号`} sub="点击单号查看详情" icon="📑">
          <div className="mt-auto max-h-32 overflow-y-auto pr-2 custom-scrollbar border-t border-slate-50 pt-2">
            <div className="flex flex-wrap gap-1.5">
              {summary.orderIds.map(id => (
                <button key={id} onClick={() => onSelectOrderId(id)} className="inline-block px-1.5 py-0.5 bg-blue-50 text-blue-600 text-[10px] font-mono rounded border border-blue-100 hover:bg-blue-600 hover:text-white transition-colors">
                  {id}
                </button>
              ))}
            </div>
          </div>
        </KpiCard>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col min-h-[640px]">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">
              <span className="mr-2">📊</span> 销售趋势综合分析
            </h3>
            <div className="flex bg-slate-100 p-1 rounded-lg self-start sm:self-auto">
              <button onClick={() => setShowCfa(!showCfa)} className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>金额</button>
              <button onClick={() => setShowQuantity(!showQuantity)} className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}>数量</button>
            </div>
          </div>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={summary.monthlyTrend} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#3b82f6', fontSize: 11}} />
                <Tooltip />
                {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorSales)" />}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative overflow-hidden flex flex-col min-h-[640px]">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">🧩 品类多维分布</h3>
          </div>
          <div className="flex-1 flex flex-col">
            <div className="flex-1 grid grid-rows-2 gap-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={summary.categoryDistribution} cx="50%" cy="55%" innerRadius={50} outerRadius={85} paddingAngle={5}
                    dataKey="value" onClick={(data) => onPieClick(data, 'sales')} style={{ cursor: 'pointer', outline: 'none' }}
                  >
                    {summary.categoryDistribution.map((entry, index) => (
                      <RechartsCell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />
                    ))}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={summary.categoryQuantityDistribution} cx="50%" cy="55%" innerRadius={50} outerRadius={85} paddingAngle={5}
                    dataKey="value" onClick={(data) => onPieClick(data, 'quantity')} style={{ cursor: 'pointer', outline: 'none' }}
                  >
                    {summary.categoryQuantityDistribution.map((entry, index) => (
                      <RechartsCell key={`cell-q-${index}`} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />
                    ))}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>

          {selectedCategory && (
            <div className="absolute inset-0 bg-white/98 backdrop-blur-md z-20 p-6 flex flex-col animate-in slide-in-from-right duration-300 shadow-2xl overflow-hidden">
              <div className="flex items-center justify-between mb-6 border-b border-slate-100 pb-4">
                <div>
                  <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">Category Analysis</h4>
                  <h3 className="text-2xl font-black text-slate-900">{selectedCategory}</h3>
                </div>
                <button onClick={() => { setSelectedCategory(null); setSelectedCustomerInDrillDown(null); }} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg></button>
              </div>

              <div className="flex-1 overflow-y-auto custom-scrollbar space-y-8 pr-2">
                <section className="bg-slate-50/50 p-4 rounded-2xl border border-slate-100 relative">
                  <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">客户分布</h5>
                  <div className="h-[250px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={drillDownData.customers} layout="vertical" onClick={(data) => data && data.activePayload && onCustomerClick(data.activePayload[0].payload)}>
                        <XAxis type="number" hide />
                        <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={100} tick={<CustomYAxisTick />} />
                        <Tooltip />
                        <Bar dataKey={drillDownMetric === 'sales' ? 'sales' : 'qty'} fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={20}>
                          {drillDownData.customers.map((entry, index) => <RechartsCell key={index} fill={COLORS[index % COLORS.length]} stroke={entry.name === selectedCustomerInDrillDown ? '#2563eb' : 'none'} strokeWidth={2} />)}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </section>

                <section className="relative">
                  <div className="flex items-center justify-between mb-4">
                    <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest">
                      {selectedCustomerInDrillDown ? `【${selectedCustomerInDrillDown}】` : ''} 交易明细与操作
                    </h5>
                    {selectedCustomerInDrillDown && <button onClick={() => { setSelectedCustomerInDrillDown(null); setSelectedRowIndexes(new Set()); }} className="text-[10px] text-blue-600 font-bold hover:underline">显示全部客户</button>}
                  </div>

                  {/* 顶部批量操作与选择汇总 */}
                  {selectedRowIndexes.size > 0 && (
                    <div className="sticky top-0 z-30 bg-indigo-600 text-white p-3 rounded-xl shadow-lg flex items-center justify-between mb-4 animate-in slide-in-from-top duration-300">
                      <div className="flex items-center gap-4">
                        <span className="text-xs font-bold">已选 {selectedRowIndexes.size} 条记录</span>
                        <div className="h-4 w-px bg-white/20 mx-2"></div>
                        <span className="text-[11px] font-mono opacity-90">{selectionSummary.amount.toLocaleString()} CFA</span>
                      </div>

                      <div className="flex items-center gap-2" ref={batchMenuRef}>
                        <div className="relative">
                          <button 
                            onClick={() => setIsBatchMenuOpen(!isBatchMenuOpen)}
                            className="bg-white text-indigo-600 px-3 py-1.5 rounded-lg text-[10px] font-bold flex items-center gap-2 hover:bg-indigo-50 transition-all"
                          >
                            批量操作选项
                            <svg className={`w-3 h-3 transition-transform ${isBatchMenuOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                          </button>

                          {isBatchMenuOpen && (
                            <div className="absolute right-0 bottom-full mb-2 w-40 bg-white rounded-xl shadow-2xl border border-slate-100 overflow-hidden animate-in fade-in zoom-in duration-150 origin-bottom-right">
                              <div className="p-1 space-y-0.5">
                                {['导出 CSV', '批量打印凭证', '生成分析报告'].map(action => (
                                  <button key={action} className="w-full text-left px-3 py-2 text-slate-700 hover:bg-indigo-50 hover:text-indigo-600 rounded-lg text-[10px] font-bold transition-all" onClick={() => setIsBatchMenuOpen(false)}>
                                    {action}
                                  </button>
                                ))}
                                <div className="h-px bg-slate-50 my-1"></div>
                                <button className="w-full text-left px-3 py-2 text-red-600 hover:bg-red-50 rounded-lg text-[10px] font-bold" onClick={() => setSelectedRowIndexes(new Set())}>清空选择</button>
                              </div>
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  )}

                  <div className="overflow-x-auto rounded-xl border border-slate-100 bg-white shadow-sm min-h-[400px]">
                    <table className="min-w-full text-[10px]">
                      <thead className="bg-slate-50 border-b border-slate-100 sticky top-0 z-10">
                        <tr>
                          <th className="px-3 py-2 text-left w-10">
                            <input type="checkbox" className="rounded border-slate-300 text-blue-600" checked={drillDownData.records.length > 0 && selectedRowIndexes.size === drillDownData.records.length} onChange={handleToggleAll} />
                          </th>
                          <th className="px-3 py-2 text-left font-bold text-slate-400">单号</th>
                          <th className="px-3 py-2 text-left font-bold text-slate-400">物料名称</th>
                          <th className="px-3 py-2 text-right font-bold text-slate-400">金额</th>
                          <th className="px-4 py-2 text-center font-bold text-slate-400">核对状态 (下拉选项)</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {drillDownData.records.slice(0, 50).map((r, i) => {
                          const status = recordStatuses[i] || '正常';
                          return (
                            <tr key={i} className={`hover:bg-slate-50 transition-colors ${selectedRowIndexes.has(i) ? 'bg-blue-50/50' : ''}`}>
                              <td className="px-3 py-3" onClick={() => handleToggleRow(i)}>
                                <input type="checkbox" className="rounded border-slate-300 text-blue-600" checked={selectedRowIndexes.has(i)} readOnly />
                              </td>
                              <td className="px-3 py-3 text-blue-600 font-mono font-bold">
                                <button onClick={() => onSelectOrderId(r.id)}>{r.id}</button>
                              </td>
                              <td className="px-3 py-3 text-slate-900 font-medium truncate max-w-[150px]">{r.itemName}</td>
                              <td className="px-3 py-3 text-right font-mono text-slate-900">{r.totalAmount.toLocaleString()}</td>
                              <td className="px-4 py-3 text-center">
                                {/* 行级下拉选择器 */}
                                <div className="relative inline-block">
                                  <select 
                                    value={status} 
                                    onChange={(e) => updateStatus(i, e.target.value as RecordStatus)}
                                    className={`appearance-none text-[9px] font-bold px-4 py-1.5 pr-8 rounded-full border-2 transition-all cursor-pointer outline-none 
                                      ${status === '正常' ? 'bg-emerald-50 border-emerald-200 text-emerald-700 focus:border-emerald-500' : 
                                        status === '待核对' ? 'bg-amber-50 border-amber-200 text-amber-700 focus:border-amber-500' : 
                                        'bg-rose-50 border-rose-200 text-rose-700 focus:border-rose-500'}`}
                                  >
                                    <option value="正常">✅ 正常</option>
                                    <option value="待核对">⏳ 待核对</option>
                                    <option value="有疑问">⚠️ 有疑问</option>
                                  </select>
                                  <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none opacity-50">
                                    <svg className="w-2.5 h-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg>
                                  </div>
                                </div>
                              </td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                </section>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-6">🏆 销售员业绩排行</h3>
        <div className="h-[350px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical">
              <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={80} />
              <Tooltip />
              <Bar dataKey="value" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={24} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-indigo-900 text-white p-8 rounded-2xl shadow-xl overflow-hidden relative">
        <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h3 className="text-xl font-bold flex items-center">✨ Gemini 智能洞察</h3>
            <p className="text-indigo-200 text-sm mt-1">让 AI 为您的销售数据提供专业的商业建议</p>
          </div>
          <button onClick={handleGetAIInsights} disabled={loading} className="bg-white text-indigo-900 px-6 py-2.5 rounded-full font-bold hover:bg-indigo-50 transition-all disabled:opacity-50 min-w-[140px]">
            {loading ? '分析中...' : '生成洞察'}
          </button>
        </div>
        {aiText && <div className="mt-6 bg-indigo-800/50 p-6 rounded-xl border border-indigo-700 text-indigo-50 whitespace-pre-wrap">{aiText}</div>}
      </div>
    </div>
  );
};

const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
  <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col h-full">
    <div className="flex justify-between items-start mb-4">
      <div className="p-2 bg-blue-50 rounded-lg text-blue-600 text-xl">{icon}</div>
      <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">{title}</span>
    </div>
    <div className="text-2xl font-bold text-slate-900 mb-1">{value}</div>
    <div className="text-sm text-slate-500 mb-3">{sub}</div>
    {children}
  </div>
);

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Legend, Cell as RechartsCell
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';
import { getAIInsights } from '../services/geminiService';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

type RecordStatus = '正常' | '待核对' | '有疑问';

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [aiText, setAiText] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [drillDownMetric, setDrillDownMetric] = useState<'sales' | 'quantity'>('sales');
  const [showSummaryTable, setShowSummaryTable] = useState(false);
  const [selectedCustomerInDrillDown, setSelectedCustomerInDrillDown] = useState<string | null>(null);

  // 局部明细筛选状态
  const [localTableFilters, setLocalTableFilters] = useState({
    id: '',
    itemName: '',
    status: ''
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);

  // 记录选中的行索引
  const [selectedRowIndexes, setSelectedRowIndexes] = useState<Set<number>>(new Set());
  // 记录每行的自定义状态（下拉选项）
  const [recordStatuses, setRecordStatuses] = useState<Record<string, RecordStatus>>({});
  // 批量操作下拉菜单状态
  const [isBatchMenuOpen, setIsBatchMenuOpen] = useState(false);

  const batchMenuRef = useRef<HTMLDivElement>(null);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (batchMenuRef.current && !batchMenuRef.current.contains(event.target as Node)) {
        setIsBatchMenuOpen(false);
      }
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleGetAIInsights = async () => {
    setLoading(true);
    const insights = await getAIInsights(summary);
    setAiText(insights || '');
    setLoading(false);
  };

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], customers: [], records: [] };

    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const customersMap = new Map<string, { sales: number; qty: number; orderIds: Set<string> }>();
    const allRecordsForCategory: SalesRecord[] = [];

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        allRecordsForCategory.push(record);

        const itemExisting = itemsMap.get(record.itemName) || { sales: 0, qty: 0 };
        itemsMap.set(record.itemName, {
          sales: itemExisting.sales + record.totalAmount,
          qty: itemExisting.qty + record.quantity
        });

        const customerExisting = customersMap.get(record.customer) || { sales: 0, qty: 0, orderIds: new Set() };
        customerExisting.orderIds.add(record.id);
        customersMap.set(record.customer, {
          sales: customerExisting.sales + record.totalAmount,
          qty: customerExisting.qty + record.quantity,
          orderIds: customerExisting.orderIds
        });
      }
    });

    const items = Array.from(itemsMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty, orderIds: Array.from(val.orderIds).sort() }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    // 首先根据选中的客户筛选
    let records = selectedCustomerInDrillDown 
      ? allRecordsForCategory.filter(r => r.customer === selectedCustomerInDrillDown)
      : allRecordsForCategory;

    // 然后根据表格局部的列筛选
    if (localTableFilters.id) records = records.filter(r => r.id === localTableFilters.id);
    if (localTableFilters.itemName) records = records.filter(r => r.itemName === localTableFilters.itemName);
    if (localTableFilters.status) {
      records = records.filter((r, idx) => {
        const currentStatus = recordStatuses[`${r.id}-${r.itemName}`] || '正常';
        return currentStatus === localTableFilters.status;
      });
    }

    return { 
      items, 
      customers,
      records: records.sort((a, b) => b.date.localeCompare(a.date)) 
    };
  }, [selectedCategory, filteredData, drillDownMetric, selectedCustomerInDrillDown, localTableFilters, recordStatuses]);

  // 获取各列唯一值用于下拉筛选
  const columnFilterOptions = useMemo(() => {
    const ids = new Set<string>();
    const itemNames = new Set<string>();

    // 从当前品类全集中获取选项
    filteredData.forEach(r => {
      if (r.category === selectedCategory && (!selectedCustomerInDrillDown || r.customer === selectedCustomerInDrillDown)) {
        ids.add(r.id);
        itemNames.add(r.itemName);
      }
    });

    return {
      ids: Array.from(ids).sort(),
      itemNames: Array.from(itemNames).sort(),
      statuses: ['正常', '待核对', '有疑问']
    };
  }, [filteredData, selectedCategory, selectedCustomerInDrillDown]);

  const selectionSummary = useMemo(() => {
    let count = 0;
    let amount = 0;
    let qty = 0;
    selectedRowIndexes.forEach(idx => {
      const record = drillDownData.records[idx];
      if (record) {
        count++;
        amount += record.totalAmount;
        qty += record.quantity;
      }
    });
    return { count, amount, qty };
  }, [selectedRowIndexes, drillDownData.records]);

  const onPieClick = (data: any, metric: 'sales' | 'quantity') => {
    setDrillDownMetric(metric);
    if (selectedCategory === data.name) {
      setSelectedCategory(null);
      setSelectedCustomerInDrillDown(null);
      setSelectedRowIndexes(new Set());
      setLocalTableFilters({ id: '', itemName: '', status: '' });
    } else {
      setSelectedCategory(data.name);
      setSelectedCustomerInDrillDown(null);
      setSelectedRowIndexes(new Set());
      setLocalTableFilters({ id: '', itemName: '', status: '' });
    }
  };

  const onCustomerClick = (data: any) => {
    const customerName = data.name || data.value;
    if (customerName) {
      const newCustomer = customerName === selectedCustomerInDrillDown ? null : customerName;
      setSelectedCustomerInDrillDown(newCustomer);
      setSelectedRowIndexes(new Set());
      setLocalTableFilters({ id: '', itemName: '', status: '' });
    }
  };

  const handleToggleRow = (index: number) => {
    const newSet = new Set(selectedRowIndexes);
    if (newSet.has(index)) newSet.delete(index);
    else newSet.add(index);
    setSelectedRowIndexes(newSet);
  };

  const handleToggleAll = () => {
    if (selectedRowIndexes.size === drillDownData.records.length) {
      setSelectedRowIndexes(new Set());
    } else {
      const newSet = new Set<number>();
      drillDownData.records.forEach((_, i) => newSet.add(i));
      setSelectedRowIndexes(newSet);
    }
  };

  const updateStatus = (recordId: string, itemName: string, status: RecordStatus) => {
    setRecordStatuses(prev => ({ ...prev, [`${recordId}-${itemName}`]: status }));
  };

  const CustomYAxisTick = (props: any) => {
    const { x, y, payload } = props;
    const isSelected = payload.value === selectedCustomerInDrillDown;
    return (
      <g transform={`translate(${x},${y})`}>
        <text
          x={-10} y={0} dy={4} textAnchor="end"
          fill={isSelected ? '#2563eb' : '#475569'}
          className={`text-[10px] font-bold cursor-pointer hover:fill-blue-600 transition-colors ${isSelected ? 'underline' : ''}`}
          onClick={() => onCustomerClick(payload)}
        >
          {payload.value}
        </text>
      </g>
    );
  };

  // 渲染列头筛选器
  const FilterHeader = ({ label, columnId, options }: { label: string, columnId: keyof typeof localTableFilters, options: string[] }) => {
    const isActive = !!localTableFilters[columnId];
    return (
      <th className="px-3 py-2 text-left relative">
        <div className="flex items-center gap-1 group">
          <span className="font-bold text-slate-400 uppercase">{label}</span>
          <button 
            onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)}
            className={`p-1 rounded hover:bg-slate-200 transition-colors ${isActive ? 'text-blue-600' : 'text-slate-300'}`}
          >
            <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" clipRule="evenodd" />
            </svg>
            {isActive && <span className="absolute top-1 right-1 w-1.5 h-1.5 bg-blue-500 rounded-full border border-white"></span>}
          </button>
        </div>

        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-48 bg-white rounded-xl shadow-2xl border border-slate-200 z-[60] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2 border-b border-slate-50 bg-slate-50 flex justify-between items-center">
              <span className="text-[10px] font-bold text-slate-400 uppercase">选择筛选值</span>
              {isActive && (
                <button 
                  onClick={() => setLocalTableFilters(p => ({ ...p, [columnId]: '' }))}
                  className="text-[9px] text-red-500 font-bold hover:underline"
                >
                  清除
                </button>
              )}
            </div>
            <div className="max-h-48 overflow-y-auto p-1 custom-scrollbar">
              {options.map(opt => (
                <button
                  key={opt}
                  onClick={() => {
                    setLocalTableFilters(p => ({ ...p, [columnId]: opt }));
                    setActiveFilterColumn(null);
                  }}
                  className={`w-full text-left px-3 py-2 rounded-lg text-[10px] transition-colors ${localTableFilters[columnId] === opt ? 'bg-blue-50 text-blue-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {opt}
                </button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  return (
    <div className="space-y-8">
      {/* KPI Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KpiCard title="总销售额" value={`${summary.totalSales.toLocaleString()} CFA`} sub="当前筛选总额" icon="💰" />
        <KpiCard title="总出库数量" value={summary.totalQuantity.toLocaleString()} sub="物料销售总数" icon="📦" />
        <KpiCard title="出库单号" value={`${summary.orderCount} 个单号`} sub="点击单号查看详情" icon="📑">
          <div className="mt-auto max-h-32 overflow-y-auto pr-2 custom-scrollbar border-t border-slate-50 pt-2">
            <div className="flex flex-wrap gap-1.5">
              {summary.orderIds.map(id => (
                <button key={id} onClick={() => onSelectOrderId(id)} className="inline-block px-1.5 py-0.5 bg-blue-50 text-blue-600 text-[10px] font-mono rounded border border-blue-100 hover:bg-blue-600 hover:text-white transition-colors">
                  {id}
                </button>
              ))}
            </div>
          </div>
        </KpiCard>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col min-h-[640px]">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">
              <span className="mr-2">📊</span> 销售趋势综合分析
            </h3>
            <div className="flex bg-slate-100 p-1 rounded-lg self-start sm:self-auto">
              <button onClick={() => setShowCfa(!showCfa)} className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>金额</button>
              <button onClick={() => setShowQuantity(!showQuantity)} className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}>数量</button>
            </div>
          </div>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={summary.monthlyTrend} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#3b82f6', fontSize: 11}} />
                <Tooltip />
                {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorSales)" />}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative overflow-hidden flex flex-col min-h-[640px]">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">🧩 品类多维分布</h3>
          </div>
          <div className="flex-1 flex flex-col">
            <div className="flex-1 grid grid-rows-2 gap-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={summary.categoryDistribution} cx="50%" cy="55%" innerRadius={50} outerRadius={85} paddingAngle={5}
                    dataKey="value" onClick={(data) => onPieClick(data, 'sales')} style={{ cursor: 'pointer', outline: 'none' }}
                  >
                    {summary.categoryDistribution.map((entry, index) => (
                      <RechartsCell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />
                    ))}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={summary.categoryQuantityDistribution} cx="50%" cy="55%" innerRadius={50} outerRadius={85} paddingAngle={5}
                    dataKey="value" onClick={(data) => onPieClick(data, 'quantity')} style={{ cursor: 'pointer', outline: 'none' }}
                  >
                    {summary.categoryQuantityDistribution.map((entry, index) => (
                      <RechartsCell key={`cell-q-${index}`} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />
                    ))}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>

          {selectedCategory && (
            <div className="absolute inset-0 bg-white/98 backdrop-blur-md z-20 p-6 flex flex-col animate-in slide-in-from-right duration-300 shadow-2xl overflow-hidden">
              <div className="flex items-center justify-between mb-6 border-b border-slate-100 pb-4">
                <div>
                  <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">Category Analysis</h4>
                  <h3 className="text-2xl font-black text-slate-900">{selectedCategory}</h3>
                </div>
                <button onClick={() => { setSelectedCategory(null); setSelectedCustomerInDrillDown(null); setLocalTableFilters({ id: '', itemName: '', status: '' }); }} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg></button>
              </div>

              <div className="flex-1 overflow-y-auto custom-scrollbar space-y-8 pr-2 pb-12">
                <section className="bg-slate-50/50 p-4 rounded-2xl border border-slate-100 relative">
                  <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">客户分布</h5>
                  <div className="h-[250px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={drillDownData.customers} layout="vertical" onClick={(data) => data && data.activePayload && onCustomerClick(data.activePayload[0].payload)}>
                        <XAxis type="number" hide />
                        <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={100} tick={<CustomYAxisTick />} />
                        <Tooltip />
                        <Bar dataKey={drillDownMetric === 'sales' ? 'sales' : 'qty'} fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={20}>
                          {drillDownData.customers.map((entry, index) => <RechartsCell key={index} fill={COLORS[index % COLORS.length]} stroke={entry.name === selectedCustomerInDrillDown ? '#2563eb' : 'none'} strokeWidth={2} />)}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </section>

                <section className="relative">
                  <div className="flex items-center justify-between mb-4">
                    <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest">
                      {selectedCustomerInDrillDown ? `【${selectedCustomerInDrillDown}】` : ''} 交易明细核对
                    </h5>
                    {(selectedCustomerInDrillDown || Object.values(localTableFilters).some(v => !!v)) && (
                      <button 
                        onClick={() => { 
                          setSelectedCustomerInDrillDown(null); 
                          setLocalTableFilters({ id: '', itemName: '', status: '' });
                          setSelectedRowIndexes(new Set()); 
                        }} 
                        className="text-[10px] text-blue-600 font-bold hover:underline"
                      >
                        重置所有筛选
                      </button>
                    )}
                  </div>

                  {/* 顶部批量操作与选择汇总 */}
                  {selectedRowIndexes.size > 0 && (
                    <div className="sticky top-0 z-30 bg-indigo-600 text-white p-3 rounded-xl shadow-lg flex items-center justify-between mb-4 animate-in slide-in-from-top duration-300">
                      <div className="flex items-center gap-4">
                        <span className="text-xs font-bold">已选 {selectedRowIndexes.size} 条记录</span>
                        <div className="h-4 w-px bg-white/20 mx-2"></div>
                        <span className="text-[11px] font-mono opacity-90">{selectionSummary.amount.toLocaleString()} CFA</span>
                      </div>

                      <div className="flex items-center gap-2" ref={batchMenuRef}>
                        <div className="relative">
                          <button 
                            onClick={() => setIsBatchMenuOpen(!isBatchMenuOpen)}
                            className="bg-white text-indigo-600 px-3 py-1.5 rounded-lg text-[10px] font-bold flex items-center gap-2 hover:bg-indigo-50 transition-all"
                          >
                            批量操作
                            <svg className={`w-3 h-3 transition-transform ${isBatchMenuOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                          </button>

                          {isBatchMenuOpen && (
                            <div className="absolute right-0 bottom-full mb-2 w-40 bg-white rounded-xl shadow-2xl border border-slate-100 overflow-hidden animate-in fade-in zoom-in duration-150 origin-bottom-right">
                              <div className="p-1 space-y-0.5">
                                {['批量导出', '打印对账单', '导出明细'].map(action => (
                                  <button key={action} className="w-full text-left px-3 py-2 text-slate-700 hover:bg-indigo-50 hover:text-indigo-600 rounded-lg text-[10px] font-bold transition-all" onClick={() => setIsBatchMenuOpen(false)}>
                                    {action}
                                  </button>
                                ))}
                                <div className="h-px bg-slate-50 my-1"></div>
                                <button className="w-full text-left px-3 py-2 text-red-600 hover:bg-red-50 rounded-lg text-[10px] font-bold" onClick={() => setSelectedRowIndexes(new Set())}>清空选择</button>
                              </div>
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  )}

                  <div className="overflow-x-auto rounded-xl border border-slate-100 bg-white shadow-sm min-h-[400px]">
                    <table className="min-w-full text-[10px]">
                      <thead className="bg-slate-50 border-b border-slate-100 sticky top-0 z-40">
                        <tr>
                          <th className="px-3 py-2 text-left w-10">
                            <input type="checkbox" className="rounded border-slate-300 text-blue-600" checked={drillDownData.records.length > 0 && selectedRowIndexes.size === drillDownData.records.length} onChange={handleToggleAll} />
                          </th>
                          <FilterHeader label="出库单号" columnId="id" options={columnFilterOptions.ids} />
                          <FilterHeader label="物料名称" columnId="itemName" options={columnFilterOptions.itemNames} />
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase">价税合计</th>
                          <FilterHeader label="核对状态" columnId="status" options={columnFilterOptions.statuses} />
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {drillDownData.records.slice(0, 100).map((r, i) => {
                          const status = recordStatuses[`${r.id}-${r.itemName}`] || '正常';
                          return (
                            <tr key={`${r.id}-${r.itemName}-${i}`} className={`hover:bg-slate-50 transition-colors ${selectedRowIndexes.has(i) ? 'bg-blue-50/50' : ''}`}>
                              <td className="px-3 py-3" onClick={() => handleToggleRow(i)}>
                                <input type="checkbox" className="rounded border-slate-300 text-blue-600" checked={selectedRowIndexes.has(i)} readOnly />
                              </td>
                              <td className="px-3 py-3 text-blue-600 font-mono font-bold">
                                <button onClick={() => onSelectOrderId(r.id)}>{r.id}</button>
                              </td>
                              <td className="px-3 py-3 text-slate-900 font-medium truncate max-w-[150px]">{r.itemName}</td>
                              <td className="px-3 py-3 text-right font-mono text-slate-900">{r.totalAmount.toLocaleString()}</td>
                              <td className="px-4 py-3 text-center">
                                <div className="relative inline-block">
                                  <select 
                                    value={status} 
                                    onChange={(e) => updateStatus(r.id, r.itemName, e.target.value as RecordStatus)}
                                    className={`appearance-none text-[9px] font-bold px-4 py-1.5 pr-8 rounded-full border-2 transition-all cursor-pointer outline-none 
                                      ${status === '正常' ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 
                                        status === '待核对' ? 'bg-amber-50 border-amber-200 text-amber-700' : 
                                        'bg-rose-50 border-rose-200 text-rose-700'}`}
                                  >
                                    <option value="正常">✅ 正常</option>
                                    <option value="待核对">⏳ 待核对</option>
                                    <option value="有疑问">⚠️ 有疑问</option>
                                  </select>
                                  <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none opacity-50">
                                    <svg className="w-2.5 h-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg>
                                  </div>
                                </div>
                              </td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                    {drillDownData.records.length === 0 && (
                      <div className="py-20 text-center text-slate-400 italic">
                        该筛选条件下没有交易记录
                      </div>
                    )}
                  </div>
                </section>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-6">🏆 销售员业绩排行</h3>
        <div className="h-[350px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical">
              <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={80} />
              <Tooltip />
              <Bar dataKey="value" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={24} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-indigo-900 text-white p-8 rounded-2xl shadow-xl overflow-hidden relative">
        <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h3 className="text-xl font-bold flex items-center">✨ Gemini 智能洞察</h3>
            <p className="text-indigo-200 text-sm mt-1">让 AI 为您的销售数据提供专业的商业建议</p>
          </div>
          <button onClick={handleGetAIInsights} disabled={loading} className="bg-white text-indigo-900 px-6 py-2.5 rounded-full font-bold hover:bg-indigo-50 transition-all disabled:opacity-50 min-w-[140px]">
            {loading ? '分析中...' : '生成洞察'}
          </button>
        </div>
        {aiText && <div className="mt-6 bg-indigo-800/50 p-6 rounded-xl border border-indigo-700 text-indigo-50 whitespace-pre-wrap">{aiText}</div>}
      </div>
    </div>
  );
};

const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
  <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col h-full">
    <div className="flex justify-between items-start mb-4">
      <div className="p-2 bg-blue-50 rounded-lg text-blue-600 text-xl">{icon}</div>
      <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">{title}</span>
    </div>
    <div className="text-2xl font-bold text-slate-900 mb-1">{value}</div>
    <div className="text-sm text-slate-500 mb-3">{sub}</div>
    {children}
  </div>
);

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Legend, Cell as RechartsCell
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';
import { getAIInsights } from '../services/geminiService';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

type RecordStatus = '正常' | '待核对' | '有疑问';

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [aiText, setAiText] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [drillDownMetric, setDrillDownMetric] = useState<'sales' | 'quantity'>('sales');
  const [showSummaryTable, setShowSummaryTable] = useState(false);
  const [selectedCustomerInDrillDown, setSelectedCustomerInDrillDown] = useState<string | null>(null);

  // Fix: Initialize missing state for trend visualization toggles
  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(false);

  // 局部明细筛选状态
  const [localTableFilters, setLocalTableFilters] = useState({
    id: '',
    itemName: '',
    status: ''
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);

  // 记录选中的行索引
  const [selectedRowIndexes, setSelectedRowIndexes] = useState<Set<number>>(new Set());
  // 记录每行的自定义状态（下拉选项）
  const [recordStatuses, setRecordStatuses] = useState<Record<string, RecordStatus>>({});
  // 批量操作下拉菜单状态
  const [isBatchMenuOpen, setIsBatchMenuOpen] = useState(false);

  const batchMenuRef = useRef<HTMLDivElement>(null);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (batchMenuRef.current && !batchMenuRef.current.contains(event.target as Node)) {
        setIsBatchMenuOpen(false);
      }
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleGetAIInsights = async () => {
    setLoading(true);
    const insights = await getAIInsights(summary);
    setAiText(insights || '');
    setLoading(false);
  };

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], customers: [], records: [] };

    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const customersMap = new Map<string, { sales: number; qty: number; orderIds: Set<string> }>();
    const allRecordsForCategory: SalesRecord[] = [];

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        allRecordsForCategory.push(record);

        const itemExisting = itemsMap.get(record.itemName) || { sales: 0, qty: 0 };
        itemsMap.set(record.itemName, {
          sales: itemExisting.sales + record.totalAmount,
          qty: itemExisting.qty + record.quantity
        });

        const customerExisting = customersMap.get(record.customer) || { sales: 0, qty: 0, orderIds: new Set() };
        customerExisting.orderIds.add(record.id);
        customersMap.set(record.customer, {
          sales: customerExisting.sales + record.totalAmount,
          qty: customerExisting.qty + record.quantity,
          orderIds: customerExisting.orderIds
        });
      }
    });

    const items = Array.from(itemsMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty, orderIds: Array.from(val.orderIds).sort() }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    // 首先根据选中的客户筛选
    let records = selectedCustomerInDrillDown 
      ? allRecordsForCategory.filter(r => r.customer === selectedCustomerInDrillDown)
      : allRecordsForCategory;

    // 然后根据表格局部的列筛选
    if (localTableFilters.id) records = records.filter(r => r.id === localTableFilters.id);
    if (localTableFilters.itemName) records = records.filter(r => r.itemName === localTableFilters.itemName);
    if (localTableFilters.status) {
      records = records.filter((r, idx) => {
        const currentStatus = recordStatuses[`${r.id}-${r.itemName}`] || '正常';
        return currentStatus === localTableFilters.status;
      });
    }

    return { 
      items, 
      customers,
      records: records.sort((a, b) => b.date.localeCompare(a.date)) 
    };
  }, [selectedCategory, filteredData, drillDownMetric, selectedCustomerInDrillDown, localTableFilters, recordStatuses]);

  // 获取各列唯一值用于下拉筛选
  const columnFilterOptions = useMemo(() => {
    const ids = new Set<string>();
    const itemNames = new Set<string>();

    // 从当前品类全集中获取选项
    filteredData.forEach(r => {
      if (r.category === selectedCategory && (!selectedCustomerInDrillDown || r.customer === selectedCustomerInDrillDown)) {
        ids.add(r.id);
        itemNames.add(r.itemName);
      }
    });

    return {
      ids: Array.from(ids).sort(),
      itemNames: Array.from(itemNames).sort(),
      statuses: ['正常', '待核对', '有疑问']
    };
  }, [filteredData, selectedCategory, selectedCustomerInDrillDown]);

  const selectionSummary = useMemo(() => {
    let count = 0;
    let amount = 0;
    let qty = 0;
    selectedRowIndexes.forEach(idx => {
      const record = drillDownData.records[idx];
      if (record) {
        count++;
        amount += record.totalAmount;
        qty += record.quantity;
      }
    });
    return { count, amount, qty };
  }, [selectedRowIndexes, drillDownData.records]);

  const onPieClick = (data: any, metric: 'sales' | 'quantity') => {
    setDrillDownMetric(metric);
    if (selectedCategory === data.name) {
      setSelectedCategory(null);
      setSelectedCustomerInDrillDown(null);
      setSelectedRowIndexes(new Set());
      setLocalTableFilters({ id: '', itemName: '', status: '' });
    } else {
      setSelectedCategory(data.name);
      setSelectedCustomerInDrillDown(null);
      setSelectedRowIndexes(new Set());
      setLocalTableFilters({ id: '', itemName: '', status: '' });
    }
  };

  const onCustomerClick = (data: any) => {
    const customerName = data.name || data.value;
    if (customerName) {
      const newCustomer = customerName === selectedCustomerInDrillDown ? null : customerName;
      setSelectedCustomerInDrillDown(newCustomer);
      setSelectedRowIndexes(new Set());
      setLocalTableFilters({ id: '', itemName: '', status: '' });
    }
  };

  const handleToggleRow = (index: number) => {
    const newSet = new Set(selectedRowIndexes);
    if (newSet.has(index)) newSet.delete(index);
    else newSet.add(index);
    setSelectedRowIndexes(newSet);
  };

  const handleToggleAll = () => {
    if (selectedRowIndexes.size === drillDownData.records.length) {
      setSelectedRowIndexes(new Set());
    } else {
      const newSet = new Set<number>();
      drillDownData.records.forEach((_, i) => newSet.add(i));
      setSelectedRowIndexes(newSet);
    }
  };

  const updateStatus = (recordId: string, itemName: string, status: RecordStatus) => {
    setRecordStatuses(prev => ({ ...prev, [`${recordId}-${itemName}`]: status }));
  };

  const CustomYAxisTick = (props: any) => {
    const { x, y, payload } = props;
    const isSelected = payload.value === selectedCustomerInDrillDown;
    return (
      <g transform={`translate(${x},${y})`}>
        <text
          x={-10} y={0} dy={4} textAnchor="end"
          fill={isSelected ? '#2563eb' : '#475569'}
          className={`text-[10px] font-bold cursor-pointer hover:fill-blue-600 transition-colors ${isSelected ? 'underline' : ''}`}
          onClick={() => onCustomerClick(payload)}
        >
          {payload.value}
        </text>
      </g>
    );
  };

  // 渲染列头筛选器
  const FilterHeader = ({ label, columnId, options }: { label: string, columnId: keyof typeof localTableFilters, options: string[] }) => {
    const isActive = !!localTableFilters[columnId];
    return (
      <th className="px-3 py-2 text-left relative">
        <div className="flex items-center gap-1 group">
          <span className="font-bold text-slate-400 uppercase">{label}</span>
          <button 
            onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)}
            className={`p-1 rounded hover:bg-slate-200 transition-colors ${isActive ? 'text-blue-600' : 'text-slate-300'}`}
          >
            <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" clipRule="evenodd" />
            </svg>
            {isActive && <span className="absolute top-1 right-1 w-1.5 h-1.5 bg-blue-500 rounded-full border border-white"></span>}
          </button>
        </div>

        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-48 bg-white rounded-xl shadow-2xl border border-slate-200 z-[60] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2 border-b border-slate-50 bg-slate-50 flex justify-between items-center">
              <span className="text-[10px] font-bold text-slate-400 uppercase">选择筛选值</span>
              {isActive && (
                <button 
                  onClick={() => setLocalTableFilters(p => ({ ...p, [columnId]: '' }))}
                  className="text-[9px] text-red-500 font-bold hover:underline"
                >
                  清除
                </button>
              )}
            </div>
            <div className="max-h-48 overflow-y-auto p-1 custom-scrollbar">
              {options.map(opt => (
                <button
                  key={opt}
                  onClick={() => {
                    setLocalTableFilters(p => ({ ...p, [columnId]: opt }));
                    setActiveFilterColumn(null);
                  }}
                  className={`w-full text-left px-3 py-2 rounded-lg text-[10px] transition-colors ${localTableFilters[columnId] === opt ? 'bg-blue-50 text-blue-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {opt}
                </button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  return (
    <div className="space-y-8">
      {/* KPI Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KpiCard title="总销售额" value={`${summary.totalSales.toLocaleString()} CFA`} sub="当前筛选总额" icon="💰" />
        <KpiCard title="总出库数量" value={summary.totalQuantity.toLocaleString()} sub="物料销售总数" icon="📦" />
        <KpiCard title="出库单号" value={`${summary.orderCount} 个单号`} sub="点击单号查看详情" icon="📑">
          <div className="mt-auto max-h-32 overflow-y-auto pr-2 custom-scrollbar border-t border-slate-50 pt-2">
            <div className="flex flex-wrap gap-1.5">
              {summary.orderIds.map(id => (
                <button key={id} onClick={() => onSelectOrderId(id)} className="inline-block px-1.5 py-0.5 bg-blue-50 text-blue-600 text-[10px] font-mono rounded border border-blue-100 hover:bg-blue-600 hover:text-white transition-colors">
                  {id}
                </button>
              ))}
            </div>
          </div>
        </KpiCard>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col min-h-[640px]">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">
              <span className="mr-2">📊</span> 销售趋势综合分析
            </h3>
            <div className="flex bg-slate-100 p-1 rounded-lg self-start sm:self-auto">
              {/* Fix: Applied missing state setters and variables */}
              <button onClick={() => setShowCfa(!showCfa)} className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>金额</button>
              <button onClick={() => setShowQuantity(!showQuantity)} className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}>数量</button>
            </div>
          </div>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={summary.monthlyTrend} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                  {/* Define gradient for Quantity trend */}
                  <linearGradient id="colorQty" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#3b82f6', fontSize: 11}} />
                {/* Add secondary Y-axis for Quantity */}
                <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 11}} />
                <Tooltip />
                {/* Fix: Conditionals for Sales and Quantity visualization */}
                {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorSales)" />}
                {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" stroke="#10b981" strokeWidth={3} fillOpacity={1} fill="url(#colorQty)" />}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative overflow-hidden flex flex-col min-h-[640px]">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">🧩 品类多维分布</h3>
          </div>
          <div className="flex-1 flex flex-col">
            <div className="flex-1 grid grid-rows-2 gap-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={summary.categoryDistribution} cx="50%" cy="55%" innerRadius={50} outerRadius={85} paddingAngle={5}
                    dataKey="value" onClick={(data) => onPieClick(data, 'sales')} style={{ cursor: 'pointer', outline: 'none' }}
                  >
                    {summary.categoryDistribution.map((entry, index) => (
                      <RechartsCell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />
                    ))}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={summary.categoryQuantityDistribution} cx="50%" cy="55%" innerRadius={50} outerRadius={85} paddingAngle={5}
                    dataKey="value" onClick={(data) => onPieClick(data, 'quantity')} style={{ cursor: 'pointer', outline: 'none' }}
                  >
                    {summary.categoryQuantityDistribution.map((entry, index) => (
                      <RechartsCell key={`cell-q-${index}`} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />
                    ))}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>

          {selectedCategory && (
            <div className="absolute inset-0 bg-white/98 backdrop-blur-md z-20 p-6 flex flex-col animate-in slide-in-from-right duration-300 shadow-2xl overflow-hidden">
              <div className="flex items-center justify-between mb-6 border-b border-slate-100 pb-4">
                <div>
                  <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">Category Analysis</h4>
                  <h3 className="text-2xl font-black text-slate-900">{selectedCategory}</h3>
                </div>
                <button onClick={() => { setSelectedCategory(null); setSelectedCustomerInDrillDown(null); setLocalTableFilters({ id: '', itemName: '', status: '' }); }} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg></button>
              </div>

              <div className="flex-1 overflow-y-auto custom-scrollbar space-y-8 pr-2 pb-12">
                <section className="bg-slate-50/50 p-4 rounded-2xl border border-slate-100 relative">
                  <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">客户分布</h5>
                  <div className="h-[250px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={drillDownData.customers} layout="vertical" onClick={(data) => data && data.activePayload && onCustomerClick(data.activePayload[0].payload)}>
                        <XAxis type="number" hide />
                        <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={100} tick={<CustomYAxisTick />} />
                        <Tooltip />
                        <Bar dataKey={drillDownMetric === 'sales' ? 'sales' : 'qty'} fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={20}>
                          {drillDownData.customers.map((entry, index) => <RechartsCell key={index} fill={COLORS[index % COLORS.length]} stroke={entry.name === selectedCustomerInDrillDown ? '#2563eb' : 'none'} strokeWidth={2} />)}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </section>

                <section className="relative">
                  <div className="flex items-center justify-between mb-4">
                    <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest">
                      {selectedCustomerInDrillDown ? `【${selectedCustomerInDrillDown}】` : ''} 交易明细核对
                    </h5>
                    {(selectedCustomerInDrillDown || Object.values(localTableFilters).some(v => !!v)) && (
                      <button 
                        onClick={() => { 
                          setSelectedCustomerInDrillDown(null); 
                          setLocalTableFilters({ id: '', itemName: '', status: '' });
                          setSelectedRowIndexes(new Set()); 
                        }} 
                        className="text-[10px] text-blue-600 font-bold hover:underline"
                      >
                        重置所有筛选
                      </button>
                    )}
                  </div>

                  {/* 顶部批量操作与选择汇总 */}
                  {selectedRowIndexes.size > 0 && (
                    <div className="sticky top-0 z-30 bg-indigo-600 text-white p-3 rounded-xl shadow-lg flex items-center justify-between mb-4 animate-in slide-in-from-top duration-300">
                      <div className="flex items-center gap-4">
                        <span className="text-xs font-bold">已选 {selectedRowIndexes.size} 条记录</span>
                        <div className="h-4 w-px bg-white/20 mx-2"></div>
                        <span className="text-[11px] font-mono opacity-90">{selectionSummary.amount.toLocaleString()} CFA</span>
                      </div>

                      <div className="flex items-center gap-2" ref={batchMenuRef}>
                        <div className="relative">
                          <button 
                            onClick={() => setIsBatchMenuOpen(!isBatchMenuOpen)}
                            className="bg-white text-indigo-600 px-3 py-1.5 rounded-lg text-[10px] font-bold flex items-center gap-2 hover:bg-indigo-50 transition-all"
                          >
                            批量操作
                            <svg className={`w-3 h-3 transition-transform ${isBatchMenuOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                          </button>

                          {isBatchMenuOpen && (
                            <div className="absolute right-0 bottom-full mb-2 w-40 bg-white rounded-xl shadow-2xl border border-slate-100 overflow-hidden animate-in fade-in zoom-in duration-150 origin-bottom-right">
                              <div className="p-1 space-y-0.5">
                                {['批量导出', '打印对账单', '导出明细'].map(action => (
                                  <button key={action} className="w-full text-left px-3 py-2 text-slate-700 hover:bg-indigo-50 hover:text-indigo-600 rounded-lg text-[10px] font-bold transition-all" onClick={() => setIsBatchMenuOpen(false)}>
                                    {action}
                                  </button>
                                ))}
                                <div className="h-px bg-slate-50 my-1"></div>
                                <button className="w-full text-left px-3 py-2 text-red-600 hover:bg-red-50 rounded-lg text-[10px] font-bold" onClick={() => setSelectedRowIndexes(new Set())}>清空选择</button>
                              </div>
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  )}

                  <div className="overflow-x-auto rounded-xl border border-slate-100 bg-white shadow-sm min-h-[400px]">
                    <table className="min-w-full text-[10px]">
                      <thead className="bg-slate-50 border-b border-slate-100 sticky top-0 z-40">
                        <tr>
                          <th className="px-3 py-2 text-left w-10">
                            <input type="checkbox" className="rounded border-slate-300 text-blue-600" checked={drillDownData.records.length > 0 && selectedRowIndexes.size === drillDownData.records.length} onChange={handleToggleAll} />
                          </th>
                          <FilterHeader label="出库单号" columnId="id" options={columnFilterOptions.ids} />
                          <FilterHeader label="物料名称" columnId="itemName" options={columnFilterOptions.itemNames} />
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase">价税合计</th>
                          <FilterHeader label="核对状态" columnId="status" options={columnFilterOptions.statuses} />
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {drillDownData.records.slice(0, 100).map((r, i) => {
                          const status = recordStatuses[`${r.id}-${r.itemName}`] || '正常';
                          return (
                            <tr key={`${r.id}-${r.itemName}-${i}`} className={`hover:bg-slate-50 transition-colors ${selectedRowIndexes.has(i) ? 'bg-blue-50/50' : ''}`}>
                              <td className="px-3 py-3" onClick={() => handleToggleRow(i)}>
                                <input type="checkbox" className="rounded border-slate-300 text-blue-600" checked={selectedRowIndexes.has(i)} readOnly />
                              </td>
                              <td className="px-3 py-3 text-blue-600 font-mono font-bold">
                                <button onClick={() => onSelectOrderId(r.id)}>{r.id}</button>
                              </td>
                              <td className="px-3 py-3 text-slate-900 font-medium truncate max-w-[150px]">{r.itemName}</td>
                              <td className="px-3 py-3 text-right font-mono text-slate-900">{r.totalAmount.toLocaleString()}</td>
                              <td className="px-4 py-3 text-center">
                                <div className="relative inline-block">
                                  <select 
                                    value={status} 
                                    onChange={(e) => updateStatus(r.id, r.itemName, e.target.value as RecordStatus)}
                                    className={`appearance-none text-[9px] font-bold px-4 py-1.5 pr-8 rounded-full border-2 transition-all cursor-pointer outline-none 
                                      ${status === '正常' ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 
                                        status === '待核对' ? 'bg-amber-50 border-amber-200 text-amber-700' : 
                                        'bg-rose-50 border-rose-200 text-rose-700'}`}
                                  >
                                    <option value="正常">✅ 正常</option>
                                    <option value="待核对">⏳ 待核对</option>
                                    <option value="有疑问">⚠️ 有疑问</option>
                                  </select>
                                  <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none opacity-50">
                                    <svg className="w-2.5 h-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg>
                                  </div>
                                </div>
                              </td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                    {drillDownData.records.length === 0 && (
                      <div className="py-20 text-center text-slate-400 italic">
                        该筛选条件下没有交易记录
                      </div>
                    )}
                  </div>
                </section>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-6">🏆 销售员业绩排行</h3>
        <div className="h-[350px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical">
              <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={80} />
              <Tooltip />
              <Bar dataKey="value" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={24} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-indigo-900 text-white p-8 rounded-2xl shadow-xl overflow-hidden relative">
        <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h3 className="text-xl font-bold flex items-center">✨ Gemini 智能洞察</h3>
            <p className="text-indigo-200 text-sm mt-1">让 AI 为您的销售数据 provide 专业的商业建议</p>
          </div>
          <button onClick={handleGetAIInsights} disabled={loading} className="bg-white text-indigo-900 px-6 py-2.5 rounded-full font-bold hover:bg-indigo-50 transition-all disabled:opacity-50 min-w-[140px]">
            {loading ? '分析中...' : '生成洞察'}
          </button>
        </div>
        {aiText && <div className="mt-6 bg-indigo-800/50 p-6 rounded-xl border border-indigo-700 text-indigo-50 whitespace-pre-wrap">{aiText}</div>}
      </div>
    </div>
  );
};

const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
  <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col h-full">
    <div className="flex justify-between items-start mb-4">
      <div className="p-2 bg-blue-50 rounded-lg text-blue-600 text-xl">{icon}</div>
      <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">{title}</span>
    </div>
    <div className="text-2xl font-bold text-slate-900 mb-1">{value}</div>
    <div className="text-sm text-slate-500 mb-3">{sub}</div>
    {children}
  </div>
);

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Legend, Cell as RechartsCell
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';
import { getAIInsights } from '../services/geminiService';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [aiText, setAiText] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [drillDownMetric, setDrillDownMetric] = useState<'sales' | 'quantity'>('sales');
  const [showSummaryTable, setShowSummaryTable] = useState(false);
  const [selectedCustomerInDrillDown, setSelectedCustomerInDrillDown] = useState<string | null>(null);

  // 趋势图显示维度
  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  // 局部明细表格筛选状态
  const [localTableFilters, setLocalTableFilters] = useState({
    id: '',
    date: '',
    customer: '',
    itemName: ''
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);

  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleGetAIInsights = async () => {
    setLoading(true);
    const insights = await getAIInsights(summary);
    setAiText(insights || '');
    setLoading(false);
  };

  // 核心业务逻辑：计算深度分析数据
  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], customers: [], records: [] };

    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const customersMap = new Map<string, { sales: number; qty: number; orderIds: Set<string> }>();
    let records: SalesRecord[] = [];

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        // 物料汇总
        const itemExisting = itemsMap.get(record.itemName) || { sales: 0, qty: 0 };
        itemsMap.set(record.itemName, {
          sales: itemExisting.sales + record.totalAmount,
          qty: itemExisting.qty + record.quantity
        });

        // 客户汇总
        const customerExisting = customersMap.get(record.customer) || { sales: 0, qty: 0, orderIds: new Set() };
        customerExisting.orderIds.add(record.id);
        customersMap.set(record.customer, {
          sales: customerExisting.sales + record.totalAmount,
          qty: customerExisting.qty + record.quantity,
          orderIds: customerExisting.orderIds
        });

        records.push(record);
      }
    });

    const items = Array.from(itemsMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty, orderIds: Array.from(val.orderIds).sort() }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    // 应用局部级联筛选
    if (selectedCustomerInDrillDown) records = records.filter(r => r.customer === selectedCustomerInDrillDown);
    if (localTableFilters.id) records = records.filter(r => r.id === localTableFilters.id);
    if (localTableFilters.date) records = records.filter(r => r.date === localTableFilters.date);
    if (localTableFilters.customer) records = records.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.itemName) records = records.filter(r => r.itemName === localTableFilters.itemName);

    return { 
      items, 
      customers,
      records: records.sort((a, b) => b.date.localeCompare(a.date)) 
    };
  }, [selectedCategory, filteredData, drillDownMetric, selectedCustomerInDrillDown, localTableFilters]);

  // 获取局部筛选的所有唯一选项
  const localFilterOptions = useMemo(() => {
    if (!selectedCategory) return { ids: [], dates: [], customers: [], itemNames: [] };
    const ids = new Set<string>();
    const dates = new Set<string>();
    const customers = new Set<string>();
    const itemNames = new Set<string>();

    filteredData.forEach(r => {
      if (r.category === selectedCategory) {
        ids.add(r.id);
        dates.add(r.date);
        customers.add(r.customer);
        itemNames.add(r.itemName);
      }
    });

    return {
      ids: Array.from(ids).sort().reverse(),
      dates: Array.from(dates).sort().reverse(),
      customers: Array.from(customers).sort(),
      itemNames: Array.from(itemNames).sort()
    };
  }, [filteredData, selectedCategory]);

  const onPieClick = (data: any, metric: 'sales' | 'quantity') => {
    setDrillDownMetric(metric);
    if (selectedCategory === data.name) {
      setSelectedCategory(null);
      setSelectedCustomerInDrillDown(null);
    } else {
      setSelectedCategory(data.name);
      setSelectedCustomerInDrillDown(null);
      setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' });
    }
  };

  const CustomYAxisTick = (props: any) => {
    const { x, y, payload } = props;
    const isSelected = payload.value === selectedCustomerInDrillDown;
    return (
      <g transform={`translate(${x},${y})`}>
        <text
          x={-10} y={0} dy={4} textAnchor="end"
          fill={isSelected ? '#2563eb' : '#475569'}
          className={`text-[10px] font-bold cursor-pointer hover:fill-blue-600 transition-colors ${isSelected ? 'underline' : ''}`}
          onClick={() => setSelectedCustomerInDrillDown(payload.value === selectedCustomerInDrillDown ? null : payload.value)}
        >
          {payload.value}
        </text>
      </g>
    );
  };

  // 内部表头筛选组件
  const FilterHeader = ({ label, columnId, options }: { label: string, columnId: keyof typeof localTableFilters, options: string[] }) => {
    const isActive = !!localTableFilters[columnId];
    return (
      <th className="px-3 py-2 text-left relative">
        <div className="flex items-center gap-1.5 group">
          <span className="font-bold text-slate-400 uppercase tracking-tighter">{label}</span>
          <button 
            onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)}
            className={`p-1 rounded hover:bg-slate-200 transition-all ${isActive ? 'text-blue-600' : 'text-slate-300'}`}
          >
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" clipRule="evenodd" />
            </svg>
          </button>
        </div>

        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-56 bg-white rounded-xl shadow-2xl border border-slate-200 z-[70] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2 border-b border-slate-50 bg-slate-50 flex justify-between items-center">
              <span className="text-[10px] font-bold text-slate-400 uppercase">筛选{label}</span>
              {isActive && (
                <button 
                  onClick={() => setLocalTableFilters(p => ({ ...p, [columnId]: '' }))}
                  className="text-[9px] text-red-500 font-bold hover:underline"
                >
                  清除
                </button>
              )}
            </div>
            <div className="max-h-56 overflow-y-auto p-1 custom-scrollbar">
              {options.map(opt => (
                <button
                  key={opt}
                  onClick={() => {
                    setLocalTableFilters(p => ({ ...p, [columnId]: opt }));
                    setActiveFilterColumn(null);
                  }}
                  className={`w-full text-left px-3 py-2 rounded-lg text-[11px] transition-colors ${localTableFilters[columnId] === opt ? 'bg-blue-50 text-blue-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {opt}
                </button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow flex flex-col h-full">
      <div className="flex justify-between items-start mb-4">
        <div className="p-2 bg-blue-50 rounded-lg text-blue-600 text-xl">{icon}</div>
        <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">{title}</span>
      </div>
      <div className="text-2xl font-bold text-slate-900 mb-1">{value}</div>
      <div className="text-sm text-slate-500 mb-3">{sub}</div>
      {children}
    </div>
  );

  return (
    <div className="space-y-8">
      {/* KPI Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KpiCard title="总销售额" value={`${summary.totalSales.toLocaleString()} CFA`} sub="当前筛选总额" icon="💰" />
        <KpiCard title="总出库数量" value={summary.totalQuantity.toLocaleString()} sub="物料销售总数" icon="📦" />
        <KpiCard title="出库单号" value={`${summary.orderCount} 个单号`} sub="点击快速查看详情" icon="📑">
          <div className="mt-auto max-h-32 overflow-y-auto pr-2 custom-scrollbar border-t border-slate-50 pt-2">
            <div className="flex flex-wrap gap-1.5">
              {summary.orderIds.map(id => (
                <button key={id} onClick={() => onSelectOrderId(id)} className="inline-block px-1.5 py-0.5 bg-blue-50 text-blue-600 text-[10px] font-mono rounded border border-blue-100 hover:bg-blue-600 hover:text-white transition-colors">
                  {id}
                </button>
              ))}
            </div>
          </div>
        </KpiCard>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col min-h-[640px]">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">📊 销售趋势综合分析</h3>
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button onClick={() => setShowCfa(!showCfa)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>金额</button>
              <button onClick={() => setShowQuantity(!showQuantity)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}>数量</button>
            </div>
          </div>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={summary.monthlyTrend} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorQty" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#3b82f6', fontSize: 11}} />
                <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 11}} />
                <Tooltip />
                {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorSales)" />}
                {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" stroke="#10b981" strokeWidth={3} fillOpacity={1} fill="url(#colorQty)" />}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative overflow-hidden flex flex-col min-h-[640px]">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">🧩 品类多维分布</h3>
            {showSummaryTable && <button onClick={() => setShowSummaryTable(false)} className="text-[10px] bg-blue-600 text-white font-bold px-3 py-1.5 rounded">← 返回</button>}
          </div>

          <div className="flex-1 flex flex-col overflow-hidden">
            {!showSummaryTable ? (
              <div className="flex-1 grid grid-rows-2 gap-4">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={summary.categoryDistribution} cx="50%" cy="50%" innerRadius={45} outerRadius={75} paddingAngle={5}
                      dataKey="value" onClick={(data) => onPieClick(data, 'sales')} style={{ cursor: 'pointer', outline: 'none' }}
                    >
                      {summary.categoryDistribution.map((entry, index) => <RechartsCell key={index} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />)}
                    </Pie>
                    <Tooltip />
                  </PieChart>
                </ResponsiveContainer>
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={summary.categoryQuantityDistribution} cx="50%" cy="50%" innerRadius={45} outerRadius={75} paddingAngle={5}
                      dataKey="value" onClick={(data) => onPieClick(data, 'quantity')} style={{ cursor: 'pointer', outline: 'none' }}
                    >
                      {summary.categoryQuantityDistribution.map((entry, index) => <RechartsCell key={index} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />)}
                    </Pie>
                    <Tooltip />
                    <Legend iconType="circle" />
                  </PieChart>
                </ResponsiveContainer>
                <button onClick={() => setShowSummaryTable(true)} className="mt-4 p-3 bg-slate-50 border border-dashed border-slate-200 rounded-xl text-[10px] font-bold text-slate-500 uppercase tracking-widest hover:bg-blue-50 transition-colors">展开汇总明细表</button>
              </div>
            ) : (
              <div className="flex-1 overflow-y-auto custom-scrollbar animate-in slide-in-from-right duration-300">
                <table className="min-w-full text-xs text-left">
                  <thead className="bg-slate-50 sticky top-0">
                    <tr>
                      <th className="px-3 py-2 text-slate-400 font-bold uppercase">品类</th>
                      <th className="px-3 py-2 text-slate-400 font-bold uppercase text-right">金额 (CFA)</th>
                      <th className="px-3 py-2 text-slate-400 font-bold uppercase text-right">数量</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {summary.categoryDistribution.map((cat, idx) => {
                      const qty = summary.categoryQuantityDistribution.find(q => q.name === cat.name)?.value || 0;
                      return (
                        <tr key={cat.name} onClick={() => { setSelectedCategory(cat.name); setDrillDownMetric('sales'); }} className="hover:bg-blue-50 cursor-pointer transition-colors group">
                          <td className="px-3 py-3 font-bold text-slate-700">{cat.name}</td>
                          <td className="px-3 py-3 text-right font-mono text-slate-600">{cat.value.toLocaleString()}</td>
                          <td className="px-3 py-3 text-right font-mono text-slate-600">{qty.toLocaleString()}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {selectedCategory && (
            <div className="absolute inset-0 bg-white/98 backdrop-blur-md z-20 p-6 flex flex-col animate-in slide-in-from-right duration-300 shadow-2xl overflow-hidden">
              <div className="flex items-center justify-between mb-6 border-b border-slate-100 pb-4">
                <div>
                  <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">Depth Analysis</h4>
                  <h3 className="text-2xl font-black text-slate-900">{selectedCategory}</h3>
                </div>
                <div className="flex items-center gap-2">
                   <div className="flex bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => setDrillDownMetric('sales')} className={`px-2 py-1 rounded-md text-[9px] font-bold transition-all ${drillDownMetric === 'sales' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400'}`}>按金额</button>
                    <button onClick={() => setDrillDownMetric('quantity')} className={`px-2 py-1 rounded-md text-[9px] font-bold transition-all ${drillDownMetric === 'quantity' ? 'bg-white shadow-sm text-green-600' : 'text-slate-400'}`}>按数量</button>
                  </div>
                  <button onClick={() => { setSelectedCategory(null); setSelectedCustomerInDrillDown(null); }} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg></button>
                </div>
              </div>

              <div className="flex-1 overflow-y-auto custom-scrollbar space-y-10 pb-20">
                <section>
                  <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">按客户分布</h5>
                  <div className="h-[250px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={drillDownData.customers} layout="vertical" margin={{ left: 20 }}>
                        <XAxis type="number" hide />
                        <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={100} tick={<CustomYAxisTick />} />
                        <Tooltip cursor={{fill: '#f8fafc'}} />
                        <Bar dataKey={drillDownMetric === 'sales' ? 'sales' : 'qty'} fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={18}>
                          {drillDownData.customers.map((entry, index) => <RechartsCell key={index} fill={COLORS[index % COLORS.length]} stroke={entry.name === selectedCustomerInDrillDown ? '#2563eb' : 'none'} strokeWidth={2} />)}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </section>

                <section>
                  <div className="flex items-center justify-between mb-4">
                    <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                       <span className="w-1.5 h-3 bg-blue-600 rounded-full"></span> 原始交易明细 (含多维下拉筛选)
                    </h5>
                    {(selectedCustomerInDrillDown || Object.values(localTableFilters).some(v => !!v)) && (
                      <button 
                        onClick={() => { 
                          setSelectedCustomerInDrillDown(null); 
                          setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' }); 
                        }} 
                        className="text-[10px] text-blue-600 font-bold hover:underline"
                      >
                        重置局部筛选
                      </button>
                    )}
                  </div>

                  <div className="overflow-x-auto rounded-xl border border-slate-100 bg-white shadow-sm min-h-[400px]">
                    <table className="min-w-full text-[11px]">
                      <thead className="bg-slate-50 border-b border-slate-100 sticky top-0 z-50">
                        <tr>
                          <FilterHeader label="出库单号" columnId="id" options={localFilterOptions.ids} />
                          <FilterHeader label="日期" columnId="date" options={localFilterOptions.dates} />
                          <FilterHeader label="客户" columnId="customer" options={localFilterOptions.customers} />
                          <FilterHeader label="物料名称" columnId="itemName" options={localFilterOptions.itemNames} />
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">数量</th>
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">金额 (CFA)</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {drillDownData.records.slice(0, 100).map((r, i) => (
                          <tr key={`${r.id}-${i}`} className="hover:bg-slate-50 transition-colors">
                            <td className="px-3 py-3 text-blue-600 font-mono font-bold">
                              <button onClick={() => onSelectOrderId(r.id)}>{r.id}</button>
                            </td>
                            <td className="px-3 py-3 text-slate-500">{r.date}</td>
                            <td className="px-3 py-3 text-slate-900 font-bold">{r.customer}</td>
                            <td className="px-3 py-3 text-slate-600 truncate max-w-[120px]">{r.itemName}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-600">{r.quantity}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-900 font-bold">{r.totalAmount.toLocaleString()}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    {drillDownData.records.length === 0 && (
                      <div className="py-20 text-center text-slate-400 italic bg-slate-50/50">该组合筛选条件下暂无明细记录</div>
                    )}
                    {drillDownData.records.length > 100 && (
                      <div className="py-3 text-center text-[10px] text-slate-400 bg-slate-50/50 border-t border-slate-100">仅显示前 100 条记录</div>
                    )}
                  </div>
                </section>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-6">🏆 销售员业绩排行 (CFA)</h3>
        <div className="h-[350px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical" margin={{ left: 20 }}>
              <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={80} tick={{fill: '#475569', fontWeight: 500}} />
              <Tooltip cursor={{fill: '#f8fafc'}} formatter={(v) => [`${v.toLocaleString()} CFA`, '总销售额']} />
              <Bar dataKey="value" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={24} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-indigo-900 text-white p-8 rounded-2xl shadow-xl overflow-hidden relative">
        <div className="relative z-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
            <div>
              <h3 className="text-xl font-bold flex items-center">✨ Gemini 智能商业洞察</h3>
              <p className="text-indigo-200 text-sm mt-1">AI 已根据您的当前筛选数据生成针对性建议 (金额以 CFA 为准)</p>
            </div>
            <button onClick={handleGetAIInsights} disabled={loading} className="bg-white text-indigo-900 px-6 py-2.5 rounded-full font-bold hover:bg-indigo-50 transition-all disabled:opacity-50 flex items-center justify-center min-w-[140px]">
              {loading ? '分析中...' : '生成最新洞察'}
            </button>
          </div>
          {aiText ? (
            <div className="bg-indigo-800/50 p-6 rounded-xl border border-indigo-700 text-indigo-50 whitespace-pre-wrap leading-relaxed animate-in fade-in">{aiText}</div>
          ) : (
            <div className="flex flex-col items-center justify-center py-12 border-2 border-dashed border-indigo-700 rounded-xl text-indigo-300">
              <span className="text-4xl mb-4">💡</span>
              <p>点击上方按钮，获取 AI 关于业绩、增长、瓶颈的深度分析建议</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Legend, Cell as RechartsCell
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';
import { getAIInsights } from '../services/geminiService';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [aiText, setAiText] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [drillDownMetric, setDrillDownMetric] = useState<'sales' | 'quantity'>('sales');
  const [showSummaryTable, setShowSummaryTable] = useState(false);
  const [selectedCustomerInDrillDown, setSelectedCustomerInDrillDown] = useState<string | null>(null);

  // 趋势图显示维度
  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  // 局部明细表格筛选状态
  const [localTableFilters, setLocalTableFilters] = useState({
    id: '',
    date: '',
    customer: '',
    itemName: ''
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);

  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleGetAIInsights = async () => {
    setLoading(true);
    const insights = await getAIInsights(summary);
    setAiText(insights || '');
    setLoading(false);
  };

  // 核心业务逻辑：计算深度分析数据
  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], customers: [], records: [] };

    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const customersMap = new Map<string, { sales: number; qty: number; orderIds: Set<string> }>();
    let records: SalesRecord[] = [];

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        // 物料汇总
        const itemExisting = itemsMap.get(record.itemName) || { sales: 0, qty: 0 };
        itemsMap.set(record.itemName, {
          sales: itemExisting.sales + record.totalAmount,
          qty: itemExisting.qty + record.quantity
        });

        // 客户汇总
        const customerExisting = customersMap.get(record.customer) || { sales: 0, qty: 0, orderIds: new Set() };
        customerExisting.orderIds.add(record.id);
        customersMap.set(record.customer, {
          sales: customerExisting.sales + record.totalAmount,
          qty: customerExisting.qty + record.quantity,
          orderIds: customerExisting.orderIds
        });

        records.push(record);
      }
    });

    const items = Array.from(itemsMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty, orderIds: Array.from(val.orderIds).sort() }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    // 应用局部级联筛选
    if (selectedCustomerInDrillDown) records = records.filter(r => r.customer === selectedCustomerInDrillDown);
    if (localTableFilters.id) records = records.filter(r => r.id === localTableFilters.id);
    if (localTableFilters.date) records = records.filter(r => r.date === localTableFilters.date);
    if (localTableFilters.customer) records = records.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.itemName) records = records.filter(r => r.itemName === localTableFilters.itemName);

    return { 
      items, 
      customers,
      records: records.sort((a, b) => b.date.localeCompare(a.date)) 
    };
  }, [selectedCategory, filteredData, drillDownMetric, selectedCustomerInDrillDown, localTableFilters]);

  // 获取局部筛选的所有唯一选项
  const localFilterOptions = useMemo(() => {
    if (!selectedCategory) return { ids: [], dates: [], customers: [], itemNames: [] };
    const ids = new Set<string>();
    const dates = new Set<string>();
    const customers = new Set<string>();
    const itemNames = new Set<string>();

    filteredData.forEach(r => {
      if (r.category === selectedCategory) {
        ids.add(r.id);
        dates.add(r.date);
        customers.add(r.customer);
        itemNames.add(r.itemName);
      }
    });

    return {
      ids: Array.from(ids).sort().reverse(),
      dates: Array.from(dates).sort().reverse(),
      customers: Array.from(customers).sort(),
      itemNames: Array.from(itemNames).sort()
    };
  }, [filteredData, selectedCategory]);

  const onPieClick = (data: any, metric: 'sales' | 'quantity') => {
    setDrillDownMetric(metric);
    if (selectedCategory === data.name) {
      setSelectedCategory(null);
      setSelectedCustomerInDrillDown(null);
    } else {
      setSelectedCategory(data.name);
      setSelectedCustomerInDrillDown(null);
      setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' });
    }
  };

  const CustomYAxisTick = (props: any) => {
    const { x, y, payload } = props;
    const isSelected = payload.value === selectedCustomerInDrillDown;
    return (
      <g transform={`translate(${x},${y})`}>
        <text
          x={-15} y={0} dy={4} textAnchor="end"
          fill={isSelected ? '#2563eb' : '#475569'}
          className={`text-[11px] font-bold cursor-pointer hover:fill-blue-600 transition-colors ${isSelected ? 'underline' : ''}`}
          onClick={() => setSelectedCustomerInDrillDown(payload.value === selectedCustomerInDrillDown ? null : payload.value)}
        >
          {payload.value}
        </text>
      </g>
    );
  };

  // 内部表头筛选组件
  const FilterHeader = ({ label, columnId, options }: { label: string, columnId: keyof typeof localTableFilters, options: string[] }) => {
    const isActive = !!localTableFilters[columnId];
    return (
      <th className="px-3 py-2 text-left relative">
        <div className="flex items-center gap-1.5 group">
          <span className="font-bold text-slate-400 uppercase tracking-tighter">{label}</span>
          <button 
            onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)}
            className={`p-1 rounded hover:bg-slate-200 transition-all ${isActive ? 'text-blue-600' : 'text-slate-300'}`}
          >
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" clipRule="evenodd" />
            </svg>
          </button>
        </div>

        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-56 bg-white rounded-xl shadow-2xl border border-slate-200 z-[70] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2 border-b border-slate-50 bg-slate-50 flex justify-between items-center">
              <span className="text-[10px] font-bold text-slate-400 uppercase">筛选{label}</span>
              {isActive && (
                <button 
                  onClick={() => setLocalTableFilters(p => ({ ...p, [columnId]: '' }))}
                  className="text-[9px] text-red-500 font-bold hover:underline"
                >
                  清除
                </button>
              )}
            </div>
            <div className="max-h-56 overflow-y-auto p-1 custom-scrollbar">
              {options.map(opt => (
                <button
                  key={opt}
                  onClick={() => {
                    setLocalTableFilters(p => ({ ...p, [columnId]: opt }));
                    setActiveFilterColumn(null);
                  }}
                  className={`w-full text-left px-3 py-2 rounded-lg text-[11px] transition-colors ${localTableFilters[columnId] === opt ? 'bg-blue-50 text-blue-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {opt}
                </button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow flex flex-col h-full">
      <div className="flex justify-between items-start mb-4">
        <div className="p-2 bg-blue-50 rounded-lg text-blue-600 text-xl">{icon}</div>
        <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">{title}</span>
      </div>
      <div className="text-2xl font-bold text-slate-900 mb-1">{value}</div>
      <div className="text-sm text-slate-500 mb-3">{sub}</div>
      {children}
    </div>
  );

  return (
    <div className="space-y-8">
      {/* KPI Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KpiCard title="总销售额" value={`${summary.totalSales.toLocaleString()} CFA`} sub="当前筛选总额" icon="💰" />
        <KpiCard title="总出库数量" value={summary.totalQuantity.toLocaleString()} sub="物料销售总数" icon="📦" />
        <KpiCard title="出库单号" value={`${summary.orderCount} 个单号`} sub="点击快速查看详情" icon="📑">
          <div className="mt-auto max-h-32 overflow-y-auto pr-2 custom-scrollbar border-t border-slate-50 pt-2">
            <div className="flex flex-wrap gap-1.5">
              {summary.orderIds.map(id => (
                <button key={id} onClick={() => onSelectOrderId(id)} className="inline-block px-1.5 py-0.5 bg-blue-50 text-blue-600 text-[10px] font-mono rounded border border-blue-100 hover:bg-blue-600 hover:text-white transition-colors">
                  {id}
                </button>
              ))}
            </div>
          </div>
        </KpiCard>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col min-h-[640px]">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">📊 销售趋势综合分析</h3>
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button onClick={() => setShowCfa(!showCfa)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>金额</button>
              <button onClick={() => setShowQuantity(!showQuantity)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}>数量</button>
            </div>
          </div>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={summary.monthlyTrend} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorQty" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#3b82f6', fontSize: 11}} />
                <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 11}} />
                <Tooltip />
                {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorSales)" />}
                {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" stroke="#10b981" strokeWidth={3} fillOpacity={1} fill="url(#colorQty)" />}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative overflow-hidden flex flex-col min-h-[640px]">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">🧩 品类多维分布</h3>
            {showSummaryTable && <button onClick={() => setShowSummaryTable(false)} className="text-[10px] bg-blue-600 text-white font-bold px-3 py-1.5 rounded">← 返回</button>}
          </div>

          <div className="flex-1 flex flex-col overflow-hidden">
            {!showSummaryTable ? (
              <div className="flex-1 grid grid-rows-2 gap-4">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={summary.categoryDistribution} cx="50%" cy="50%" innerRadius={45} outerRadius={75} paddingAngle={5}
                      dataKey="value" onClick={(data) => onPieClick(data, 'sales')} style={{ cursor: 'pointer', outline: 'none' }}
                    >
                      {summary.categoryDistribution.map((entry, index) => <RechartsCell key={index} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />)}
                    </Pie>
                    <Tooltip />
                  </PieChart>
                </ResponsiveContainer>
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={summary.categoryQuantityDistribution} cx="50%" cy="50%" innerRadius={45} outerRadius={75} paddingAngle={5}
                      dataKey="value" onClick={(data) => onPieClick(data, 'quantity')} style={{ cursor: 'pointer', outline: 'none' }}
                    >
                      {summary.categoryQuantityDistribution.map((entry, index) => <RechartsCell key={index} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />)}
                    </Pie>
                    <Tooltip />
                    <Legend iconType="circle" />
                  </PieChart>
                </ResponsiveContainer>
                <button onClick={() => setShowSummaryTable(true)} className="mt-4 p-3 bg-slate-50 border border-dashed border-slate-200 rounded-xl text-[10px] font-bold text-slate-500 uppercase tracking-widest hover:bg-blue-50 transition-colors">展开汇总明细表</button>
              </div>
            ) : (
              <div className="flex-1 overflow-y-auto custom-scrollbar animate-in slide-in-from-right duration-300">
                <table className="min-w-full text-xs text-left">
                  <thead className="bg-slate-50 sticky top-0">
                    <tr>
                      <th className="px-3 py-2 text-slate-400 font-bold uppercase">品类</th>
                      <th className="px-3 py-2 text-slate-400 font-bold uppercase text-right">金额 (CFA)</th>
                      <th className="px-3 py-2 text-slate-400 font-bold uppercase text-right">数量</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {summary.categoryDistribution.map((cat, idx) => {
                      const qty = summary.categoryQuantityDistribution.find(q => q.name === cat.name)?.value || 0;
                      return (
                        <tr key={cat.name} onClick={() => { setSelectedCategory(cat.name); setDrillDownMetric('sales'); }} className="hover:bg-blue-50 cursor-pointer transition-colors group">
                          <td className="px-3 py-3 font-bold text-slate-700">{cat.name}</td>
                          <td className="px-3 py-3 text-right font-mono text-slate-600">{cat.value.toLocaleString()}</td>
                          <td className="px-3 py-3 text-right font-mono text-slate-600">{qty.toLocaleString()}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {selectedCategory && (
            <div className="absolute inset-0 bg-white/98 backdrop-blur-md z-20 p-6 flex flex-col animate-in slide-in-from-right duration-300 shadow-2xl overflow-hidden">
              <div className="flex items-center justify-between mb-6 border-b border-slate-100 pb-4">
                <div>
                  <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">Depth Analysis</h4>
                  <h3 className="text-2xl font-black text-slate-900">{selectedCategory}</h3>
                </div>
                <div className="flex items-center gap-2">
                   <div className="flex bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => setDrillDownMetric('sales')} className={`px-2 py-1 rounded-md text-[9px] font-bold transition-all ${drillDownMetric === 'sales' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400'}`}>按金额</button>
                    <button onClick={() => setDrillDownMetric('quantity')} className={`px-2 py-1 rounded-md text-[9px] font-bold transition-all ${drillDownMetric === 'quantity' ? 'bg-white shadow-sm text-green-600' : 'text-slate-400'}`}>按数量</button>
                  </div>
                  <button onClick={() => { setSelectedCategory(null); setSelectedCustomerInDrillDown(null); }} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg></button>
                </div>
              </div>

              <div className="flex-1 overflow-y-auto custom-scrollbar space-y-10 pb-20">
                <section>
                  <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">按客户分布 (点击客户名进行二次筛选)</h5>
                  <div className="h-[280px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={drillDownData.customers} layout="vertical" margin={{ left: 10, right: 30 }}>
                        <XAxis type="number" hide />
                        {/* 增加了 width 从 100 到 180，确保长客户名不被裁剪 */}
                        <YAxis 
                          dataKey="name" 
                          type="category" 
                          axisLine={false} 
                          tickLine={false} 
                          width={180} 
                          tick={<CustomYAxisTick />} 
                        />
                        <Tooltip cursor={{fill: '#f8fafc'}} />
                        <Bar 
                          dataKey={drillDownMetric === 'sales' ? 'sales' : 'qty'} 
                          fill="#3b82f6" 
                          radius={[0, 6, 6, 0]} 
                          barSize={26} /* 增大了条形图粗细 */
                        >
                          {drillDownData.customers.map((entry, index) => (
                            <RechartsCell 
                              key={index} 
                              fill={COLORS[index % COLORS.length]} 
                              stroke={entry.name === selectedCustomerInDrillDown ? '#2563eb' : 'none'} 
                              strokeWidth={3} 
                            />
                          ))}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </section>

                <section>
                  <div className="flex items-center justify-between mb-4">
                    <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                       <span className="w-1.5 h-3 bg-blue-600 rounded-full"></span> 原始交易明细 (含多维下拉筛选)
                    </h5>
                    {(selectedCustomerInDrillDown || Object.values(localTableFilters).some(v => !!v)) && (
                      <button 
                        onClick={() => { 
                          setSelectedCustomerInDrillDown(null); 
                          setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' }); 
                        }} 
                        className="text-[10px] text-blue-600 font-bold hover:underline"
                      >
                        重置局部筛选
                      </button>
                    )}
                  </div>

                  <div className="overflow-x-auto rounded-xl border border-slate-100 bg-white shadow-sm min-h-[400px]">
                    <table className="min-w-full text-[11px]">
                      <thead className="bg-slate-50 border-b border-slate-100 sticky top-0 z-50">
                        <tr>
                          <FilterHeader label="出库单号" columnId="id" options={localFilterOptions.ids} />
                          <FilterHeader label="日期" columnId="date" options={localFilterOptions.dates} />
                          <FilterHeader label="客户" columnId="customer" options={localFilterOptions.customers} />
                          <FilterHeader label="物料名称" columnId="itemName" options={localFilterOptions.itemNames} />
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">数量</th>
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">金额 (CFA)</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {drillDownData.records.slice(0, 100).map((r, i) => (
                          <tr key={`${r.id}-${i}`} className="hover:bg-slate-50 transition-colors">
                            <td className="px-3 py-3 text-blue-600 font-mono font-bold">
                              <button onClick={() => onSelectOrderId(r.id)}>{r.id}</button>
                            </td>
                            <td className="px-3 py-3 text-slate-500">{r.date}</td>
                            <td className="px-3 py-3 text-slate-900 font-bold">{r.customer}</td>
                            <td className="px-3 py-3 text-slate-600 truncate max-w-[120px]">{r.itemName}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-600">{r.quantity}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-900 font-bold">{r.totalAmount.toLocaleString()}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    {drillDownData.records.length === 0 && (
                      <div className="py-20 text-center text-slate-400 italic bg-slate-50/50">该组合筛选条件下暂无明细记录</div>
                    )}
                    {drillDownData.records.length > 100 && (
                      <div className="py-3 text-center text-[10px] text-slate-400 bg-slate-50/50 border-t border-slate-100">仅显示前 100 条记录</div>
                    )}
                  </div>
                </section>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-6">🏆 销售员业绩排行 (CFA)</h3>
        <div className="h-[350px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical" margin={{ left: 20 }}>
              <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={80} tick={{fill: '#475569', fontWeight: 500}} />
              <Tooltip cursor={{fill: '#f8fafc'}} formatter={(v) => [`${v.toLocaleString()} CFA`, '总销售额']} />
              <Bar dataKey="value" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={24} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-indigo-900 text-white p-8 rounded-2xl shadow-xl overflow-hidden relative">
        <div className="relative z-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
            <div>
              <h3 className="text-xl font-bold flex items-center">✨ Gemini 智能商业洞察</h3>
              <p className="text-indigo-200 text-sm mt-1">AI 已根据您的当前筛选数据生成针对性建议 (金额以 CFA 为准)</p>
            </div>
            <button onClick={handleGetAIInsights} disabled={loading} className="bg-white text-indigo-900 px-6 py-2.5 rounded-full font-bold hover:bg-indigo-50 transition-all disabled:opacity-50 flex items-center justify-center min-w-[140px]">
              {loading ? '分析中...' : '生成最新洞察'}
            </button>
          </div>
          {aiText ? (
            <div className="bg-indigo-800/50 p-6 rounded-xl border border-indigo-700 text-indigo-50 whitespace-pre-wrap leading-relaxed animate-in fade-in">{aiText}</div>
          ) : (
            <div className="flex flex-col items-center justify-center py-12 border-2 border-dashed border-indigo-700 rounded-xl text-indigo-300">
              <span className="text-4xl mb-4">💡</span>
              <p>点击上方按钮，获取 AI 关于业绩、增长、瓶颈的深度分析建议</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Legend, Cell as RechartsCell
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';
import { getAIInsights } from '../services/geminiService';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [aiText, setAiText] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [drillDownMetric, setDrillDownMetric] = useState<'sales' | 'quantity'>('sales');
  const [showSummaryTable, setShowSummaryTable] = useState(false);
  const [selectedCustomerInDrillDown, setSelectedCustomerInDrillDown] = useState<string | null>(null);

  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  const [localTableFilters, setLocalTableFilters] = useState({
    id: '',
    date: '',
    customer: '',
    itemName: ''
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);

  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleGetAIInsights = async () => {
    setLoading(true);
    const insights = await getAIInsights(summary);
    setAiText(insights || '');
    setLoading(false);
  };

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], customers: [], records: [] };

    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const customersMap = new Map<string, { sales: number; qty: number; orderIds: Set<string> }>();
    let records: SalesRecord[] = [];

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        const itemExisting = itemsMap.get(record.itemName) || { sales: 0, qty: 0 };
        itemsMap.set(record.itemName, {
          sales: itemExisting.sales + record.totalAmount,
          qty: itemExisting.qty + record.quantity
        });

        const customerExisting = customersMap.get(record.customer) || { sales: 0, qty: 0, orderIds: new Set() };
        customerExisting.orderIds.add(record.id);
        customersMap.set(record.customer, {
          sales: customerExisting.sales + record.totalAmount,
          qty: customerExisting.qty + record.quantity,
          orderIds: customerExisting.orderIds
        });

        records.push(record);
      }
    });

    const items = Array.from(itemsMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty, orderIds: Array.from(val.orderIds).sort() }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    if (selectedCustomerInDrillDown) records = records.filter(r => r.customer === selectedCustomerInDrillDown);
    if (localTableFilters.id) records = records.filter(r => r.id === localTableFilters.id);
    if (localTableFilters.date) records = records.filter(r => r.date === localTableFilters.date);
    if (localTableFilters.customer) records = records.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.itemName) records = records.filter(r => r.itemName === localTableFilters.itemName);

    return { items, customers, records: records.sort((a, b) => b.date.localeCompare(a.date)) };
  }, [selectedCategory, filteredData, drillDownMetric, selectedCustomerInDrillDown, localTableFilters]);

  const localFilterOptions = useMemo(() => {
    if (!selectedCategory) return { ids: [], dates: [], customers: [], itemNames: [] };
    const ids = new Set<string>();
    const dates = new Set<string>();
    const customers = new Set<string>();
    const itemNames = new Set<string>();

    filteredData.forEach(r => {
      if (r.category === selectedCategory) {
        ids.add(r.id);
        dates.add(r.date);
        customers.add(r.customer);
        itemNames.add(r.itemName);
      }
    });

    return {
      ids: Array.from(ids).sort().reverse(),
      dates: Array.from(dates).sort().reverse(),
      customers: Array.from(customers).sort(),
      itemNames: Array.from(itemNames).sort()
    };
  }, [filteredData, selectedCategory]);

  const onPieClick = (data: any, metric: 'sales' | 'quantity') => {
    setDrillDownMetric(metric);
    if (selectedCategory === data.name) {
      setSelectedCategory(null);
      setSelectedCustomerInDrillDown(null);
    } else {
      setSelectedCategory(data.name);
      setSelectedCustomerInDrillDown(null);
      setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' });
    }
  };

  const CustomYAxisTick = (props: any) => {
    const { x, y, payload } = props;
    const isSelected = payload.value === selectedCustomerInDrillDown;
    return (
      <g transform={`translate(${x},${y})`}>
        <text
          x={-12} y={0} dy={4} textAnchor="end"
          fill={isSelected ? '#2563eb' : '#475569'}
          className={`text-[10px] font-bold cursor-pointer hover:fill-blue-600 transition-colors ${isSelected ? 'underline' : ''}`}
          onClick={() => setSelectedCustomerInDrillDown(payload.value === selectedCustomerInDrillDown ? null : payload.value)}
        >
          {payload.value}
        </text>
      </g>
    );
  };

  const FilterHeader = ({ label, columnId, options }: { label: string, columnId: keyof typeof localTableFilters, options: string[] }) => {
    const isActive = !!localTableFilters[columnId];
    return (
      <th className="px-3 py-2 text-left relative">
        <div className="flex items-center gap-1.5 group">
          <span className="font-bold text-slate-400 uppercase tracking-tighter">{label}</span>
          <button 
            onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)}
            className={`p-1 rounded hover:bg-slate-200 transition-all ${isActive ? 'text-blue-600' : 'text-slate-300'}`}
          >
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" clipRule="evenodd" />
            </svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-56 bg-white rounded-xl shadow-2xl border border-slate-200 z-[70] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2 border-b border-slate-50 bg-slate-50 flex justify-between items-center">
              <span className="text-[10px] font-bold text-slate-400 uppercase">筛选{label}</span>
              {isActive && (
                <button onClick={() => setLocalTableFilters(p => ({ ...p, [columnId]: '' }))} className="text-[9px] text-red-500 font-bold hover:underline">清除</button>
              )}
            </div>
            <div className="max-h-56 overflow-y-auto p-1 custom-scrollbar">
              {options.map(opt => (
                <button
                  key={opt}
                  onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }}
                  className={`w-full text-left px-3 py-2 rounded-lg text-[11px] transition-colors ${localTableFilters[columnId] === opt ? 'bg-blue-50 text-blue-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {opt}
                </button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow flex flex-col h-full">
      <div className="flex justify-between items-start mb-4">
        <div className="p-2 bg-blue-50 rounded-lg text-blue-600 text-xl">{icon}</div>
        <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">{title}</span>
      </div>
      <div className="text-2xl font-bold text-slate-900 mb-1">{value}</div>
      <div className="text-sm text-slate-500 mb-3">{sub}</div>
      {children}
    </div>
  );

  return (
    <div className="space-y-8">
      {/* KPI Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KpiCard title="总销售额" value={`${summary.totalSales.toLocaleString()} CFA`} sub="当前筛选总额" icon="💰" />
        <KpiCard title="总出库数量" value={summary.totalQuantity.toLocaleString()} sub="物料销售总数" icon="📦" />
        <KpiCard title="出库单号" value={`${summary.orderCount} 个单号`} sub="点击快速查看详情" icon="📑">
          <div className="mt-auto max-h-32 overflow-y-auto pr-2 custom-scrollbar border-t border-slate-50 pt-2">
            <div className="flex flex-wrap gap-1.5">
              {summary.orderIds.map(id => (
                <button key={id} onClick={() => onSelectOrderId(id)} className="inline-block px-1.5 py-0.5 bg-blue-50 text-blue-600 text-[10px] font-mono rounded border border-blue-100 hover:bg-blue-600 hover:text-white transition-colors">
                  {id}
                </button>
              ))}
            </div>
          </div>
        </KpiCard>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col min-h-[640px]">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">📊 销售趋势综合分析</h3>
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button onClick={() => setShowCfa(!showCfa)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>金额</button>
              <button onClick={() => setShowQuantity(!showQuantity)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}>数量</button>
            </div>
          </div>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={summary.monthlyTrend} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorQty" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#3b82f6', fontSize: 11}} />
                <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 11}} />
                <Tooltip />
                {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorSales)" />}
                {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" stroke="#10b981" strokeWidth={3} fillOpacity={1} fill="url(#colorQty)" />}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative overflow-hidden flex flex-col min-h-[640px]">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">🧩 品类多维分布</h3>
            {showSummaryTable && <button onClick={() => setShowSummaryTable(false)} className="text-[10px] bg-blue-600 text-white font-bold px-3 py-1.5 rounded">← 返回</button>}
          </div>

          <div className="flex-1 flex flex-col overflow-hidden">
            {!showSummaryTable ? (
              <div className="flex-1 grid grid-rows-2 gap-4">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={summary.categoryDistribution} cx="50%" cy="50%" innerRadius={45} outerRadius={75} paddingAngle={5}
                      dataKey="value" onClick={(data) => onPieClick(data, 'sales')} style={{ cursor: 'pointer', outline: 'none' }}
                    >
                      {summary.categoryDistribution.map((entry, index) => <RechartsCell key={index} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />)}
                    </Pie>
                    <Tooltip />
                  </PieChart>
                </ResponsiveContainer>
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={summary.categoryQuantityDistribution} cx="50%" cy="50%" innerRadius={45} outerRadius={75} paddingAngle={5}
                      dataKey="value" onClick={(data) => onPieClick(data, 'quantity')} style={{ cursor: 'pointer', outline: 'none' }}
                    >
                      {summary.categoryQuantityDistribution.map((entry, index) => <RechartsCell key={index} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />)}
                    </Pie>
                    <Tooltip />
                    <Legend iconType="circle" />
                  </PieChart>
                </ResponsiveContainer>
                <button onClick={() => setShowSummaryTable(true)} className="mt-4 p-3 bg-slate-50 border border-dashed border-slate-200 rounded-xl text-[10px] font-bold text-slate-500 uppercase tracking-widest hover:bg-blue-50 transition-colors">展开汇总明细表</button>
              </div>
            ) : (
              <div className="flex-1 overflow-y-auto custom-scrollbar animate-in slide-in-from-right duration-300">
                <table className="min-w-full text-xs text-left">
                  <thead className="bg-slate-50 sticky top-0">
                    <tr>
                      <th className="px-3 py-2 text-slate-400 font-bold uppercase">品类</th>
                      <th className="px-3 py-2 text-slate-400 font-bold uppercase text-right">金额 (CFA)</th>
                      <th className="px-3 py-2 text-slate-400 font-bold uppercase text-right">数量</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {summary.categoryDistribution.map((cat, idx) => {
                      const qty = summary.categoryQuantityDistribution.find(q => q.name === cat.name)?.value || 0;
                      return (
                        <tr key={cat.name} onClick={() => { setSelectedCategory(cat.name); setDrillDownMetric('sales'); }} className="hover:bg-blue-50 cursor-pointer transition-colors group">
                          <td className="px-3 py-3 font-bold text-slate-700">{cat.name}</td>
                          <td className="px-3 py-3 text-right font-mono text-slate-600">{cat.value.toLocaleString()}</td>
                          <td className="px-3 py-3 text-right font-mono text-slate-600">{qty.toLocaleString()}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {selectedCategory && (
            <div className="absolute inset-0 bg-white/98 backdrop-blur-md z-20 p-6 flex flex-col animate-in slide-in-from-right duration-300 shadow-2xl overflow-hidden">
              <div className="flex items-center justify-between mb-6 border-b border-slate-100 pb-4">
                <div>
                  <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">Depth Analysis</h4>
                  <h3 className="text-2xl font-black text-slate-900">{selectedCategory}</h3>
                </div>
                <div className="flex items-center gap-2">
                   <div className="flex bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => setDrillDownMetric('sales')} className={`px-2 py-1 rounded-md text-[9px] font-bold transition-all ${drillDownMetric === 'sales' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400'}`}>按金额</button>
                    <button onClick={() => setDrillDownMetric('quantity')} className={`px-2 py-1 rounded-md text-[9px] font-bold transition-all ${drillDownMetric === 'quantity' ? 'bg-white shadow-sm text-green-600' : 'text-slate-400'}`}>按数量</button>
                  </div>
                  <button onClick={() => { setSelectedCategory(null); setSelectedCustomerInDrillDown(null); }} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg></button>
                </div>
              </div>

              <div className="flex-1 overflow-y-auto custom-scrollbar space-y-10 pb-20">
                <section>
                  <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">按客户分布 (点击客户名进行二次筛选)</h5>
                  <div className="h-[280px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={drillDownData.customers} layout="vertical" margin={{ left: 20, right: 30 }}>
                        <XAxis type="number" hide />
                        {/* 显著增加了宽度至 240，确保极长客户名能完整显示 */}
                        <YAxis 
                          dataKey="name" 
                          type="category" 
                          axisLine={false} 
                          tickLine={false} 
                          width={240} 
                          tick={<CustomYAxisTick />} 
                        />
                        <Tooltip cursor={{fill: '#f8fafc'}} />
                        <Bar 
                          dataKey={drillDownMetric === 'sales' ? 'sales' : 'qty'} 
                          fill="#3b82f6" 
                          radius={[0, 6, 6, 0]} 
                          barSize={28}
                        >
                          {drillDownData.customers.map((entry, index) => (
                            <RechartsCell 
                              key={index} 
                              fill={COLORS[index % COLORS.length]} 
                              stroke={entry.name === selectedCustomerInDrillDown ? '#2563eb' : 'none'} 
                              strokeWidth={3} 
                            />
                          ))}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </section>

                <section>
                  <div className="flex items-center justify-between mb-4">
                    <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                       <span className="w-1.5 h-3 bg-blue-600 rounded-full"></span> 原始交易明细 (含多维下拉筛选)
                    </h5>
                    {(selectedCustomerInDrillDown || Object.values(localTableFilters).some(v => !!v)) && (
                      <button 
                        onClick={() => { 
                          setSelectedCustomerInDrillDown(null); 
                          setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' }); 
                        }} 
                        className="text-[10px] text-blue-600 font-bold hover:underline"
                      >
                        重置局部筛选
                      </button>
                    )}
                  </div>

                  <div className="overflow-x-auto rounded-xl border border-slate-100 bg-white shadow-sm min-h-[400px]">
                    <table className="min-w-full text-[11px]">
                      <thead className="bg-slate-50 border-b border-slate-100 sticky top-0 z-50">
                        <tr>
                          <FilterHeader label="出库单号" columnId="id" options={localFilterOptions.ids} />
                          <FilterHeader label="日期" columnId="date" options={localFilterOptions.dates} />
                          <FilterHeader label="客户" columnId="customer" options={localFilterOptions.customers} />
                          <FilterHeader label="物料名称" columnId="itemName" options={localFilterOptions.itemNames} />
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">数量</th>
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">金额 (CFA)</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {drillDownData.records.slice(0, 100).map((r, i) => (
                          <tr key={`${r.id}-${i}`} className="hover:bg-slate-50 transition-colors">
                            <td className="px-3 py-3 text-blue-600 font-mono font-bold">
                              <button onClick={() => onSelectOrderId(r.id)}>{r.id}</button>
                            </td>
                            <td className="px-3 py-3 text-slate-500">{r.date}</td>
                            <td className="px-3 py-3 text-slate-900 font-bold">{r.customer}</td>
                            <td className="px-3 py-3 text-slate-600 truncate max-w-[120px]">{r.itemName}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-600">{r.quantity}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-900 font-bold">{r.totalAmount.toLocaleString()}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    {drillDownData.records.length === 0 && (
                      <div className="py-20 text-center text-slate-400 italic bg-slate-50/50">该组合筛选条件下暂无明细记录</div>
                    )}
                  </div>
                </section>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-6">🏆 销售员业绩排行 (CFA)</h3>
        <div className="h-[350px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical" margin={{ left: 20 }}>
              <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={80} tick={{fill: '#475569', fontWeight: 500}} />
              <Tooltip cursor={{fill: '#f8fafc'}} formatter={(v) => [`${v.toLocaleString()} CFA`, '总销售额']} />
              <Bar dataKey="value" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={24} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-indigo-900 text-white p-8 rounded-2xl shadow-xl overflow-hidden relative">
        <div className="relative z-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
            <div>
              <h3 className="text-xl font-bold flex items-center">✨ Gemini 智能商业洞察</h3>
              <p className="text-indigo-200 text-sm mt-1">AI 已根据您的当前筛选数据生成针对性建议 (金额以 CFA 为准)</p>
            </div>
            <button onClick={handleGetAIInsights} disabled={loading} className="bg-white text-indigo-900 px-6 py-2.5 rounded-full font-bold hover:bg-indigo-50 transition-all disabled:opacity-50 flex items-center justify-center min-w-[140px]">
              {loading ? '分析中...' : '生成最新洞察'}
            </button>
          </div>
          {aiText ? (
            <div className="bg-indigo-800/50 p-6 rounded-xl border border-indigo-700 text-indigo-50 whitespace-pre-wrap leading-relaxed animate-in fade-in">{aiText}</div>
          ) : (
            <div className="flex flex-col items-center justify-center py-12 border-2 border-dashed border-indigo-700 rounded-xl text-indigo-300">
              <span className="text-4xl mb-4">💡</span>
              <p>点击上方按钮，获取 AI 关于业绩、增长、瓶颈的深度分析建议</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Legend, Cell as RechartsCell
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';
import { getAIInsights } from '../services/geminiService';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [aiText, setAiText] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [drillDownMetric, setDrillDownMetric] = useState<'sales' | 'quantity'>('sales');
  const [showSummaryTable, setShowSummaryTable] = useState(false);
  const [selectedCustomerInDrillDown, setSelectedCustomerInDrillDown] = useState<string | null>(null);

  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  const [localTableFilters, setLocalTableFilters] = useState({
    id: '',
    date: '',
    customer: '',
    itemName: ''
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);

  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleGetAIInsights = async () => {
    setLoading(true);
    const insights = await getAIInsights(summary);
    setAiText(insights || '');
    setLoading(false);
  };

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], customers: [], records: [] };

    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const customersMap = new Map<string, { sales: number; qty: number; orderIds: Set<string> }>();
    let records: SalesRecord[] = [];

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        const itemExisting = itemsMap.get(record.itemName) || { sales: 0, qty: 0 };
        itemsMap.set(record.itemName, {
          sales: itemExisting.sales + record.totalAmount,
          qty: itemExisting.qty + record.quantity
        });

        const customerExisting = customersMap.get(record.customer) || { sales: 0, qty: 0, orderIds: new Set() };
        customerExisting.orderIds.add(record.id);
        customersMap.set(record.customer, {
          sales: customerExisting.sales + record.totalAmount,
          qty: customerExisting.qty + record.quantity,
          orderIds: customerExisting.orderIds
        });

        records.push(record);
      }
    });

    const items = Array.from(itemsMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty, orderIds: Array.from(val.orderIds).sort() }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    if (selectedCustomerInDrillDown) records = records.filter(r => r.customer === selectedCustomerInDrillDown);
    if (localTableFilters.id) records = records.filter(r => r.id === localTableFilters.id);
    if (localTableFilters.date) records = records.filter(r => r.date === localTableFilters.date);
    if (localTableFilters.customer) records = records.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.itemName) records = records.filter(r => r.itemName === localTableFilters.itemName);

    return { items, customers, records: records.sort((a, b) => b.date.localeCompare(a.date)) };
  }, [selectedCategory, filteredData, drillDownMetric, selectedCustomerInDrillDown, localTableFilters]);

  const localFilterOptions = useMemo(() => {
    if (!selectedCategory) return { ids: [], dates: [], customers: [], itemNames: [] };
    const ids = new Set<string>();
    const dates = new Set<string>();
    const customers = new Set<string>();
    const itemNames = new Set<string>();

    filteredData.forEach(r => {
      if (r.category === selectedCategory) {
        ids.add(r.id);
        dates.add(r.date);
        customers.add(r.customer);
        itemNames.add(r.itemName);
      }
    });

    return {
      ids: Array.from(ids).sort().reverse(),
      dates: Array.from(dates).sort().reverse(),
      customers: Array.from(customers).sort(),
      itemNames: Array.from(itemNames).sort()
    };
  }, [filteredData, selectedCategory]);

  const onPieClick = (data: any, metric: 'sales' | 'quantity') => {
    setDrillDownMetric(metric);
    if (selectedCategory === data.name) {
      setSelectedCategory(null);
      setSelectedCustomerInDrillDown(null);
    } else {
      setSelectedCategory(data.name);
      setSelectedCustomerInDrillDown(null);
      setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' });
    }
  };

  const CustomYAxisTick = (props: any) => {
    const { x, y, payload } = props;
    const isSelected = payload.value === selectedCustomerInDrillDown;
    return (
      <g transform={`translate(${x},${y})`}>
        <text
          x={-15} y={0} dy={4} textAnchor="end"
          fill={isSelected ? '#2563eb' : '#475569'}
          className={`text-[10px] font-bold cursor-pointer hover:fill-blue-600 transition-colors ${isSelected ? 'underline' : ''}`}
          onClick={() => setSelectedCustomerInDrillDown(payload.value === selectedCustomerInDrillDown ? null : payload.value)}
        >
          {payload.value}
        </text>
      </g>
    );
  };

  const FilterHeader = ({ label, columnId, options }: { label: string, columnId: keyof typeof localTableFilters, options: string[] }) => {
    const isActive = !!localTableFilters[columnId];
    return (
      <th className="px-3 py-2 text-left relative">
        <div className="flex items-center gap-1.5 group">
          <span className="font-bold text-slate-400 uppercase tracking-tighter">{label}</span>
          <button 
            onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)}
            className={`p-1 rounded hover:bg-slate-200 transition-all ${isActive ? 'text-blue-600' : 'text-slate-300'}`}
          >
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" clipRule="evenodd" />
            </svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-56 bg-white rounded-xl shadow-2xl border border-slate-200 z-[70] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2 border-b border-slate-50 bg-slate-50 flex justify-between items-center">
              <span className="text-[10px] font-bold text-slate-400 uppercase">筛选{label}</span>
              {isActive && (
                <button onClick={() => setLocalTableFilters(p => ({ ...p, [columnId]: '' }))} className="text-[9px] text-red-500 font-bold hover:underline">清除</button>
              )}
            </div>
            <div className="max-h-56 overflow-y-auto p-1 custom-scrollbar">
              {options.map(opt => (
                <button
                  key={opt}
                  onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }}
                  className={`w-full text-left px-3 py-2 rounded-lg text-[11px] transition-colors ${localTableFilters[columnId] === opt ? 'bg-blue-50 text-blue-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {opt}
                </button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow flex flex-col h-full">
      <div className="flex justify-between items-start mb-4">
        <div className="p-2 bg-blue-50 rounded-lg text-blue-600 text-xl">{icon}</div>
        <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">{title}</span>
      </div>
      <div className="text-2xl font-bold text-slate-900 mb-1">{value}</div>
      <div className="text-sm text-slate-500 mb-3">{sub}</div>
      {children}
    </div>
  );

  return (
    <div className="space-y-8">
      {/* KPI Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KpiCard title="总销售额" value={`${summary.totalSales.toLocaleString()} CFA`} sub="当前筛选总额" icon="💰" />
        <KpiCard title="总出库数量" value={summary.totalQuantity.toLocaleString()} sub="物料销售总数" icon="📦" />
        <KpiCard title="出库单号" value={`${summary.orderCount} 个单号`} sub="点击快速查看详情" icon="📑">
          <div className="mt-auto max-h-32 overflow-y-auto pr-2 custom-scrollbar border-t border-slate-50 pt-2">
            <div className="flex flex-wrap gap-1.5">
              {summary.orderIds.map(id => (
                <button key={id} onClick={() => onSelectOrderId(id)} className="inline-block px-1.5 py-0.5 bg-blue-50 text-blue-600 text-[10px] font-mono rounded border border-blue-100 hover:bg-blue-600 hover:text-white transition-colors">
                  {id}
                </button>
              ))}
            </div>
          </div>
        </KpiCard>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col min-h-[640px]">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">📊 销售趋势综合分析</h3>
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button onClick={() => setShowCfa(!showCfa)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>金额</button>
              <button onClick={() => setShowQuantity(!showQuantity)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}>数量</button>
            </div>
          </div>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={summary.monthlyTrend} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorQty" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#3b82f6', fontSize: 11}} />
                <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 11}} />
                <Tooltip />
                {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorSales)" />}
                {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" stroke="#10b981" strokeWidth={3} fillOpacity={1} fill="url(#colorQty)" />}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative overflow-hidden flex flex-col min-h-[640px]">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">🧩 品类多维分布</h3>
            {showSummaryTable && <button onClick={() => setShowSummaryTable(false)} className="text-[10px] bg-blue-600 text-white font-bold px-3 py-1.5 rounded">← 返回</button>}
          </div>

          <div className="flex-1 flex flex-col overflow-hidden">
            {!showSummaryTable ? (
              <div className="flex-1 grid grid-rows-2 gap-4">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={summary.categoryDistribution} cx="50%" cy="50%" innerRadius={45} outerRadius={75} paddingAngle={5}
                      dataKey="value" onClick={(data) => onPieClick(data, 'sales')} style={{ cursor: 'pointer', outline: 'none' }}
                    >
                      {summary.categoryDistribution.map((entry, index) => <RechartsCell key={index} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />)}
                    </Pie>
                    <Tooltip />
                  </PieChart>
                </ResponsiveContainer>
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={summary.categoryQuantityDistribution} cx="50%" cy="50%" innerRadius={45} outerRadius={75} paddingAngle={5}
                      dataKey="value" onClick={(data) => onPieClick(data, 'quantity')} style={{ cursor: 'pointer', outline: 'none' }}
                    >
                      {summary.categoryQuantityDistribution.map((entry, index) => <RechartsCell key={index} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />)}
                    </Pie>
                    <Tooltip />
                    <Legend iconType="circle" />
                  </PieChart>
                </ResponsiveContainer>
                <button onClick={() => setShowSummaryTable(true)} className="mt-4 p-3 bg-slate-50 border border-dashed border-slate-200 rounded-xl text-[10px] font-bold text-slate-500 uppercase tracking-widest hover:bg-blue-50 transition-colors">展开汇总明细表</button>
              </div>
            ) : (
              <div className="flex-1 overflow-y-auto custom-scrollbar animate-in slide-in-from-right duration-300">
                <table className="min-w-full text-xs text-left">
                  <thead className="bg-slate-50 sticky top-0">
                    <tr>
                      <th className="px-3 py-2 text-slate-400 font-bold uppercase">品类</th>
                      <th className="px-3 py-2 text-slate-400 font-bold uppercase text-right">金额 (CFA)</th>
                      <th className="px-3 py-2 text-slate-400 font-bold uppercase text-right">数量</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {summary.categoryDistribution.map((cat, idx) => {
                      const qty = summary.categoryQuantityDistribution.find(q => q.name === cat.name)?.value || 0;
                      return (
                        <tr key={cat.name} onClick={() => { setSelectedCategory(cat.name); setDrillDownMetric('sales'); }} className="hover:bg-blue-50 cursor-pointer transition-colors group">
                          <td className="px-3 py-3 font-bold text-slate-700">{cat.name}</td>
                          <td className="px-3 py-3 text-right font-mono text-slate-600">{cat.value.toLocaleString()}</td>
                          <td className="px-3 py-3 text-right font-mono text-slate-600">{qty.toLocaleString()}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {selectedCategory && (
            <div className="absolute inset-0 bg-white/98 backdrop-blur-md z-20 p-6 flex flex-col animate-in slide-in-from-right duration-300 shadow-2xl overflow-hidden">
              <div className="flex items-center justify-between mb-6 border-b border-slate-100 pb-4">
                <div>
                  <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">Depth Analysis</h4>
                  <h3 className="text-2xl font-black text-slate-900">{selectedCategory}</h3>
                </div>
                <div className="flex items-center gap-2">
                   <div className="flex bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => setDrillDownMetric('sales')} className={`px-2 py-1 rounded-md text-[9px] font-bold transition-all ${drillDownMetric === 'sales' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400'}`}>按金额</button>
                    <button onClick={() => setDrillDownMetric('quantity')} className={`px-2 py-1 rounded-md text-[9px] font-bold transition-all ${drillDownMetric === 'quantity' ? 'bg-white shadow-sm text-green-600' : 'text-slate-400'}`}>按数量</button>
                  </div>
                  <button onClick={() => { setSelectedCategory(null); setSelectedCustomerInDrillDown(null); }} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg></button>
                </div>
              </div>

              <div className="flex-1 overflow-y-auto custom-scrollbar space-y-10 pb-20">
                <section>
                  <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">按客户分布 (点击客户名进行二次筛选)</h5>
                  {/* 大幅增加了容器高度，从 280px 增至 450px，确保纵向空间充裕 */}
                  <div className="min-h-[450px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={drillDownData.customers} layout="vertical" margin={{ left: 20, right: 40 }}>
                        <XAxis type="number" hide />
                        <YAxis 
                          dataKey="name" 
                          type="category" 
                          axisLine={false} 
                          tickLine={false} 
                          width={240} 
                          interval={0} /* 关键：强制显示所有刻度标签，防止自动隐藏 */
                          tick={<CustomYAxisTick />} 
                        />
                        <Tooltip cursor={{fill: '#f8fafc'}} />
                        <Bar 
                          dataKey={drillDownMetric === 'sales' ? 'sales' : 'qty'} 
                          fill="#3b82f6" 
                          radius={[0, 6, 6, 0]} 
                          barSize={20} /* 适当调小 barSize，配合增加的高度使分布更均匀 */
                        >
                          {drillDownData.customers.map((entry, index) => (
                            <RechartsCell 
                              key={index} 
                              fill={COLORS[index % COLORS.length]} 
                              stroke={entry.name === selectedCustomerInDrillDown ? '#2563eb' : 'none'} 
                              strokeWidth={3} 
                            />
                          ))}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </section>

                <section>
                  <div className="flex items-center justify-between mb-4">
                    <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                       <span className="w-1.5 h-3 bg-blue-600 rounded-full"></span> 原始交易明细 (含多维下拉筛选)
                    </h5>
                    {(selectedCustomerInDrillDown || Object.values(localTableFilters).some(v => !!v)) && (
                      <button 
                        onClick={() => { 
                          setSelectedCustomerInDrillDown(null); 
                          setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' }); 
                        }} 
                        className="text-[10px] text-blue-600 font-bold hover:underline"
                      >
                        重置局部筛选
                      </button>
                    )}
                  </div>

                  <div className="overflow-x-auto rounded-xl border border-slate-100 bg-white shadow-sm min-h-[400px]">
                    <table className="min-w-full text-[11px]">
                      <thead className="bg-slate-50 border-b border-slate-100 sticky top-0 z-50">
                        <tr>
                          <FilterHeader label="出库单号" columnId="id" options={localFilterOptions.ids} />
                          <FilterHeader label="日期" columnId="date" options={localFilterOptions.dates} />
                          <FilterHeader label="客户" columnId="customer" options={localFilterOptions.customers} />
                          <FilterHeader label="物料名称" columnId="itemName" options={localFilterOptions.itemNames} />
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">数量</th>
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">金额 (CFA)</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {drillDownData.records.slice(0, 100).map((r, i) => (
                          <tr key={`${r.id}-${i}`} className="hover:bg-slate-50 transition-colors">
                            <td className="px-3 py-3 text-blue-600 font-mono font-bold">
                              <button onClick={() => onSelectOrderId(r.id)}>{r.id}</button>
                            </td>
                            <td className="px-3 py-3 text-slate-500">{r.date}</td>
                            <td className="px-3 py-3 text-slate-900 font-bold">{r.customer}</td>
                            <td className="px-3 py-3 text-slate-600 truncate max-w-[120px]">{r.itemName}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-600">{r.quantity}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-900 font-bold">{r.totalAmount.toLocaleString()}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    {drillDownData.records.length === 0 && (
                      <div className="py-20 text-center text-slate-400 italic bg-slate-50/50">该组合筛选条件下暂无明细记录</div>
                    )}
                  </div>
                </section>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-6">🏆 销售员业绩排行 (CFA)</h3>
        <div className="h-[350px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical" margin={{ left: 20 }}>
              <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={80} tick={{fill: '#475569', fontWeight: 500}} />
              <Tooltip cursor={{fill: '#f8fafc'}} formatter={(v) => [`${v.toLocaleString()} CFA`, '总销售额']} />
              <Bar dataKey="value" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={24} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-indigo-900 text-white p-8 rounded-2xl shadow-xl overflow-hidden relative">
        <div className="relative z-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
            <div>
              <h3 className="text-xl font-bold flex items-center">✨ Gemini 智能商业洞察</h3>
              <p className="text-indigo-200 text-sm mt-1">AI 已根据您的当前筛选数据生成针对性建议 (金额以 CFA 为准)</p>
            </div>
            <button onClick={handleGetAIInsights} disabled={loading} className="bg-white text-indigo-900 px-6 py-2.5 rounded-full font-bold hover:bg-indigo-50 transition-all disabled:opacity-50 flex items-center justify-center min-w-[140px]">
              {loading ? '分析中...' : '生成最新洞察'}
            </button>
          </div>
          {aiText ? (
            <div className="bg-indigo-800/50 p-6 rounded-xl border border-indigo-700 text-indigo-50 whitespace-pre-wrap leading-relaxed animate-in fade-in">{aiText}</div>
          ) : (
            <div className="flex flex-col items-center justify-center py-12 border-2 border-dashed border-indigo-700 rounded-xl text-indigo-300">
              <span className="text-4xl mb-4">💡</span>
              <p>点击上方按钮，获取 AI 关于业绩、增长、瓶颈的深度分析建议</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Legend, Cell as RechartsCell
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';
import { getAIInsights } from '../services/geminiService';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [aiText, setAiText] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [drillDownMetric, setDrillDownMetric] = useState<'sales' | 'quantity'>('sales');
  const [showSummaryTable, setShowSummaryTable] = useState(false);
  const [selectedCustomerInDrillDown, setSelectedCustomerInDrillDown] = useState<string | null>(null);

  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  const [localTableFilters, setLocalTableFilters] = useState({
    id: '',
    date: '',
    customer: '',
    itemName: ''
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);

  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleGetAIInsights = async () => {
    setLoading(true);
    const insights = await getAIInsights(summary);
    setAiText(insights || '');
    setLoading(false);
  };

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], customers: [], records: [] };

    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const customersMap = new Map<string, { sales: number; qty: number; orderIds: Set<string> }>();
    let records: SalesRecord[] = [];

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        const itemExisting = itemsMap.get(record.itemName) || { sales: 0, qty: 0 };
        itemsMap.set(record.itemName, {
          sales: itemExisting.sales + record.totalAmount,
          qty: itemExisting.qty + record.quantity
        });

        const customerExisting = customersMap.get(record.customer) || { sales: 0, qty: 0, orderIds: new Set() };
        customerExisting.orderIds.add(record.id);
        customersMap.set(record.customer, {
          sales: customerExisting.sales + record.totalAmount,
          qty: customerExisting.qty + record.quantity,
          orderIds: customerExisting.orderIds
        });

        records.push(record);
      }
    });

    const items = Array.from(itemsMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty, orderIds: Array.from(val.orderIds).sort() }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    if (selectedCustomerInDrillDown) records = records.filter(r => r.customer === selectedCustomerInDrillDown);
    if (localTableFilters.id) records = records.filter(r => r.id === localTableFilters.id);
    if (localTableFilters.date) records = records.filter(r => r.date === localTableFilters.date);
    if (localTableFilters.customer) records = records.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.itemName) records = records.filter(r => r.itemName === localTableFilters.itemName);

    return { items, customers, records: records.sort((a, b) => b.date.localeCompare(a.date)) };
  }, [selectedCategory, filteredData, drillDownMetric, selectedCustomerInDrillDown, localTableFilters]);

  const localFilterOptions = useMemo(() => {
    if (!selectedCategory) return { ids: [], dates: [], customers: [], itemNames: [] };
    const ids = new Set<string>();
    const dates = new Set<string>();
    const customers = new Set<string>();
    const itemNames = new Set<string>();

    filteredData.forEach(r => {
      if (r.category === selectedCategory) {
        ids.add(r.id);
        dates.add(r.date);
        customers.add(r.customer);
        itemNames.add(r.itemName);
      }
    });

    return {
      ids: Array.from(ids).sort().reverse(),
      dates: Array.from(dates).sort().reverse(),
      customers: Array.from(customers).sort(),
      itemNames: Array.from(itemNames).sort()
    };
  }, [filteredData, selectedCategory]);

  const onPieClick = (data: any, metric: 'sales' | 'quantity') => {
    setDrillDownMetric(metric);
    if (selectedCategory === data.name) {
      setSelectedCategory(null);
      setSelectedCustomerInDrillDown(null);
    } else {
      setSelectedCategory(data.name);
      setSelectedCustomerInDrillDown(null);
      setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' });
    }
  };

  const CustomYAxisTick = (props: any) => {
    const { x, y, payload } = props;
    const isSelected = payload.value === selectedCustomerInDrillDown;
    return (
      <g transform={`translate(${x},${y})`}>
        <text
          x={-15} y={0} dy={4} textAnchor="end"
          fill={isSelected ? '#2563eb' : '#475569'}
          className={`text-[10px] font-bold cursor-pointer hover:fill-blue-600 transition-colors ${isSelected ? 'underline' : ''}`}
          onClick={() => setSelectedCustomerInDrillDown(payload.value === selectedCustomerInDrillDown ? null : payload.value)}
        >
          {payload.value}
        </text>
      </g>
    );
  };

  const FilterHeader = ({ label, columnId, options }: { label: string, columnId: keyof typeof localTableFilters, options: string[] }) => {
    const isActive = !!localTableFilters[columnId];
    return (
      <th className="px-3 py-2 text-left relative">
        <div className="flex items-center gap-1.5 group">
          <span className="font-bold text-slate-400 uppercase tracking-tighter">{label}</span>
          <button 
            onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)}
            className={`p-1 rounded hover:bg-slate-200 transition-all ${isActive ? 'text-blue-600' : 'text-slate-300'}`}
          >
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" clipRule="evenodd" />
            </svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-56 bg-white rounded-xl shadow-2xl border border-slate-200 z-[70] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2 border-b border-slate-50 bg-slate-50 flex justify-between items-center">
              <span className="text-[10px] font-bold text-slate-400 uppercase">筛选{label}</span>
              {isActive && (
                <button onClick={() => setLocalTableFilters(p => ({ ...p, [columnId]: '' }))} className="text-[9px] text-red-500 font-bold hover:underline">清除</button>
              )}
            </div>
            <div className="max-h-56 overflow-y-auto p-1 custom-scrollbar">
              {options.map(opt => (
                <button
                  key={opt}
                  onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }}
                  className={`w-full text-left px-3 py-2 rounded-lg text-[11px] transition-colors ${localTableFilters[columnId] === opt ? 'bg-blue-50 text-blue-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {opt}
                </button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow flex flex-col h-full">
      <div className="flex justify-between items-start mb-4">
        <div className="p-2 bg-blue-50 rounded-lg text-blue-600 text-xl">{icon}</div>
        <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">{title}</span>
      </div>
      <div className="text-2xl font-bold text-slate-900 mb-1">{value}</div>
      <div className="text-sm text-slate-500 mb-3">{sub}</div>
      {children}
    </div>
  );

  return (
    <div className="space-y-8">
      {/* KPI Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KpiCard title="总销售额" value={`${summary.totalSales.toLocaleString()} CFA`} sub="当前筛选总额" icon="💰" />
        <KpiCard title="总出库数量" value={summary.totalQuantity.toLocaleString()} sub="物料销售总数" icon="📦" />
        <KpiCard title="出库单号" value={`${summary.orderCount} 个单号`} sub="点击快速查看详情" icon="📑">
          <div className="mt-auto max-h-32 overflow-y-auto pr-2 custom-scrollbar border-t border-slate-50 pt-2">
            <div className="flex flex-wrap gap-1.5">
              {summary.orderIds.map(id => (
                <button key={id} onClick={() => onSelectOrderId(id)} className="inline-block px-1.5 py-0.5 bg-blue-50 text-blue-600 text-[10px] font-mono rounded border border-blue-100 hover:bg-blue-600 hover:text-white transition-colors">
                  {id}
                </button>
              ))}
            </div>
          </div>
        </KpiCard>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col min-h-[640px]">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">📊 销售趋势综合分析</h3>
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button onClick={() => setShowCfa(!showCfa)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>金额</button>
              <button onClick={() => setShowQuantity(!showQuantity)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}>数量</button>
            </div>
          </div>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={summary.monthlyTrend} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorQty" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#3b82f6', fontSize: 11}} />
                <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 11}} />
                <Tooltip />
                {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorSales)" />}
                {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" stroke="#10b981" strokeWidth={3} fillOpacity={1} fill="url(#colorQty)" />}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative overflow-hidden flex flex-col min-h-[640px]">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">🧩 品类多维分布</h3>
            {showSummaryTable && <button onClick={() => setShowSummaryTable(false)} className="text-[10px] bg-blue-600 text-white font-bold px-3 py-1.5 rounded">← 返回</button>}
          </div>

          <div className="flex-1 flex flex-col overflow-hidden">
            {!showSummaryTable ? (
              <div className="flex-1 grid grid-rows-2 gap-4">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={summary.categoryDistribution} cx="50%" cy="50%" innerRadius={45} outerRadius={75} paddingAngle={5}
