                  <tbody className="divide-y divide-slate-100">
                    {summary.categoryDistribution.map((cat, idx) => {
                      const qty = summary.categoryQuantityDistribution.find(q => q.name === cat.name)?.value || 0;
                      return (
                        <tr key={cat.name} onClick={() => { setSelectedCategory(cat.name); setDrillDownMetric('sales'); }} className="hover:bg-blue-50 cursor-pointer transition-colors group">
                          <td className="px-3 py-3 font-bold text-slate-700">{cat.name}</td>
