export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Legend, Cell as RechartsCell
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';
import { getAIInsights } from '../services/geminiService';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [aiText, setAiText] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [drillDownMetric, setDrillDownMetric] = useState<'sales' | 'quantity'>('sales');
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); // 控制饼图显示的度量指标
  const [showSummaryTable, setShowSummaryTable] = useState(false);
  const [selectedCustomerInDrillDown, setSelectedCustomerInDrillDown] = useState<string | null>(null);

  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  const [localTableFilters, setLocalTableFilters] = useState({
    id: '',
    date: '',
    customer: '',
    itemName: ''
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);

  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleGetAIInsights = async () => {
    setLoading(true);
    const insights = await getAIInsights(summary);
    setAiText(insights || '');
    setLoading(false);
  };

  /** 处理饼图展示数据：排序并计算百分比 */
  const sortedPieData = useMemo(() => {
    const rawData = pieMetric === 'sales' ? summary.categoryDistribution : summary.categoryQuantityDistribution;
    return [...rawData].sort((a, b) => b.value - a.value);
  }, [pieMetric, summary]);

  const totalPieValue = useMemo(() => 
    sortedPieData.reduce((acc, cur) => acc + cur.value, 0)
  , [sortedPieData]);

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], customers: [], records: [] };

    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const customersMap = new Map<string, { sales: number; qty: number; orderIds: Set<string> }>();
    let records: SalesRecord[] = [];

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        const itemExisting = itemsMap.get(record.itemName) || { sales: 0, qty: 0 };
        itemsMap.set(record.itemName, {
          sales: itemExisting.sales + record.totalAmount,
          qty: itemExisting.qty + record.quantity
        });

        const customerExisting = customersMap.get(record.customer) || { sales: 0, qty: 0, orderIds: new Set() };
        customerExisting.orderIds.add(record.id);
        customersMap.set(record.customer, {
          sales: customerExisting.sales + record.totalAmount,
          qty: customerExisting.qty + record.quantity,
          orderIds: customerExisting.orderIds
        });

        records.push(record);
      }
    });

    const items = Array.from(itemsMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty, orderIds: Array.from(val.orderIds).sort() }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    if (selectedCustomerInDrillDown) records = records.filter(r => r.customer === selectedCustomerInDrillDown);
    if (localTableFilters.id) records = records.filter(r => r.id === localTableFilters.id);
    if (localTableFilters.date) records = records.filter(r => r.date === localTableFilters.date);
    if (localTableFilters.customer) records = records.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.itemName) records = records.filter(r => r.itemName === localTableFilters.itemName);

    return { items, customers, records: records.sort((a, b) => b.date.localeCompare(a.date)) };
  }, [selectedCategory, filteredData, drillDownMetric, selectedCustomerInDrillDown, localTableFilters]);

  const localFilterOptions = useMemo(() => {
    if (!selectedCategory) return { ids: [], dates: [], customers: [], itemNames: [] };
    const ids = new Set<string>();
    const dates = new Set<string>();
    const customers = new Set<string>();
    const itemNames = new Set<string>();

    filteredData.forEach(r => {
      if (r.category === selectedCategory) {
        ids.add(r.id);
        dates.add(r.date);
        customers.add(r.customer);
        itemNames.add(r.itemName);
      }
    });

    return {
      ids: Array.from(ids).sort().reverse(),
      dates: Array.from(dates).sort().reverse(),
      customers: Array.from(customers).sort(),
      itemNames: Array.from(itemNames).sort()
    };
  }, [filteredData, selectedCategory]);

  const onPieClick = (data: any) => {
    setDrillDownMetric(pieMetric);
    if (selectedCategory === data.name) {
      setSelectedCategory(null);
      setSelectedCustomerInDrillDown(null);
    } else {
      setSelectedCategory(data.name);
      setSelectedCustomerInDrillDown(null);
      setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' });
    }
  };

  const CustomYAxisTick = (props: any) => {
    const { x, y, payload } = props;
    const isSelected = payload.value === selectedCustomerInDrillDown;
    return (
      <g transform={`translate(${x},${y})`}>
        <text
          x={-15} y={0} dy={4} textAnchor="end"
          fill={isSelected ? '#2563eb' : '#475569'}
          className={`text-[10px] font-bold cursor-pointer hover:fill-blue-600 transition-colors ${isSelected ? 'underline' : ''}`}
          onClick={() => setSelectedCustomerInDrillDown(payload.value === selectedCustomerInDrillDown ? null : payload.value)}
        >
          {payload.value}
        </text>
      </g>
    );
  };

  const FilterHeader = ({ label, columnId, options }: { label: string, columnId: keyof typeof localTableFilters, options: string[] }) => {
    const isActive = !!localTableFilters[columnId];
    return (
      <th className="px-3 py-2 text-left relative">
        <div className="flex items-center gap-1.5 group">
          <span className="font-bold text-slate-400 uppercase tracking-tighter">{label}</span>
          <button 
            onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)}
            className={`p-1 rounded hover:bg-slate-200 transition-all ${isActive ? 'text-blue-600' : 'text-slate-300'}`}
          >
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" clipRule="evenodd" />
            </svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-56 bg-white rounded-xl shadow-2xl border border-slate-200 z-[70] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2 border-b border-slate-50 bg-slate-50 flex justify-between items-center">
              <span className="text-[10px] font-bold text-slate-400 uppercase">筛选{label}</span>
              {isActive && (
                <button onClick={() => setLocalTableFilters(p => ({ ...p, [columnId]: '' }))} className="text-[9px] text-red-500 font-bold hover:underline">清除</button>
              )}
            </div>
            <div className="max-h-56 overflow-y-auto p-1 custom-scrollbar">
              {options.map(opt => (
                <button
                  key={opt}
                  onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }}
                  className={`w-full text-left px-3 py-2 rounded-lg text-[11px] transition-colors ${localTableFilters[columnId] === opt ? 'bg-blue-50 text-blue-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {opt}
                </button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow flex flex-col h-full">
      <div className="flex justify-between items-start mb-4">
        <div className="p-2 bg-blue-50 rounded-lg text-blue-600 text-xl">{icon}</div>
        <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">{title}</span>
      </div>
      <div className="text-2xl font-bold text-slate-900 mb-1">{value}</div>
      <div className="text-sm text-slate-500 mb-3">{sub}</div>
      {children}
    </div>
  );

  return (
    <div className="space-y-8">
      {/* KPI Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KpiCard title="总销售额" value={`${summary.totalSales.toLocaleString()} CFA`} sub="当前筛选总额" icon="💰" />
        <KpiCard title="总出库数量" value={summary.totalQuantity.toLocaleString()} sub="物料销售总数" icon="📦" />
        <KpiCard title="出库单号" value={`${summary.orderCount} 个单号`} sub="点击快速查看详情" icon="📑">
          <div className="mt-auto max-h-32 overflow-y-auto pr-2 custom-scrollbar border-t border-slate-50 pt-2">
            <div className="flex flex-wrap gap-1.5">
              {summary.orderIds.map(id => (
                <button key={id} onClick={() => onSelectOrderId(id)} className="inline-block px-1.5 py-0.5 bg-blue-50 text-blue-600 text-[10px] font-mono rounded border border-blue-100 hover:bg-blue-600 hover:text-white transition-colors">
                  {id}
                </button>
              ))}
            </div>
          </div>
        </KpiCard>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col min-h-[640px]">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">📊 销售趋势综合分析</h3>
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button onClick={() => setShowCfa(!showCfa)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>金额</button>
              <button onClick={() => setShowQuantity(!showQuantity)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}>数量</button>
            </div>
          </div>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={summary.monthlyTrend} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorQty" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#3b82f6', fontSize: 11}} />
                <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 11}} />
                <Tooltip />
                {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorSales)" />}
                {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" stroke="#10b981" strokeWidth={3} fillOpacity={1} fill="url(#colorQty)" />}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative overflow-hidden flex flex-col min-h-[640px]">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">🧩 品类多维分布</h3>
            <div className="flex items-center gap-3">
               {!showSummaryTable && (
                 <div className="flex bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => setPieMetric('sales')} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${pieMetric === 'sales' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>金额</button>
                    <button onClick={() => setPieMetric('quantity')} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}>数量</button>
                  </div>
