                      <Pie
                        data={sortedPieData} 
                        cx="50%" cy="50%" innerRadius={70} outerRadius={110} paddingAngle={5}
                        dataKey="value" onClick={onPieClick} style={{ cursor: 'pointer', outline: 'none' }}
                      >
                        {sortedPieData.map((entry, index) => (
                          <RechartsCell key={index} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />
