          {selectedCategory && (
            <div className="absolute inset-0 bg-white/98 backdrop-blur-md z-20 p-6 flex flex-col animate-in slide-in-from-right duration-300 shadow-2xl overflow-hidden">
              <div className="flex items-center justify-between mb-6 border-b border-slate-100 pb-4">
                <div>
                  <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">Depth Analysis</h4>
                  <h3 className="text-2xl font-black text-slate-900">{selectedCategory}</h3>
                </div>
                <div className="flex items-center gap-2">
                   <div className="flex bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => setDrillDownMetric('sales')} className={`px-2 py-1 rounded-md text-[9px] font-bold transition-all ${drillDownMetric === 'sales' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400'}`}>按金额</button>
                    <button onClick={() => setDrillDownMetric('quantity')} className={`px-2 py-1 rounded-md text-[9px] font-bold transition-all ${drillDownMetric === 'quantity' ? 'bg-white shadow-sm text-green-600' : 'text-slate-400'}`}>按数量</button>
                  </div>
                  <button onClick={() => { setSelectedCategory(null); setSelectedCustomerInDrillDown(null); }} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg></button>
                </div>
              </div>

              <div className="flex-1 overflow-y-auto custom-scrollbar space-y-10 pb-20">
                <section>
                  <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">按客户分布 (点击客户名进行二次筛选)</h5>
                  <div className="min-h-[450px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={drillDownData.customers} layout="vertical" margin={{ left: 20, right: 40 }}>
                        <XAxis type="number" hide />
                        <YAxis 
                          dataKey="name" 
                          type="category" 
                          axisLine={false} 
                          tickLine={false} 
                          width={240} 
