                      <Tooltip formatter={(value: number) => [pieMetric === 'sales' ? `${value.toLocaleString()} CFA` : value.toLocaleString(), pieMetric === 'sales' ? '销售额' : '数量']} />
                      <Legend 
                        verticalAlign="bottom" 
                        height={48}
                        formatter={(value) => {
                          const item = sortedCategorySummary.find(d => d.name === value);
                          const val = pieMetric === 'sales' ? item?.sales : item?.quantity;
                          const percentage = currentTotal > 0 ? ((val || 0) / currentTotal * 100).toFixed(1) : 0;
                          return <span className="text-[11px] text-slate-600 font-medium">{value} ({percentage}%)</span>;
                        }}
                      />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
                <button onClick={() => setShowSummaryTable(true)} className="mt-4 p-3 bg-slate-50 border border-dashed border-slate-200 rounded-xl text-[10px] font-bold text-slate-500 uppercase tracking-widest hover:bg-blue-50 transition-colors">展开汇总明细表</button>
