      </div>

      <div className="bg-indigo-900 text-white p-8 rounded-2xl shadow-xl overflow-hidden relative">
        <div className="relative z-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
            <div>
              <h3 className="text-xl font-bold flex items-center">✨ Gemini 智能商业洞察</h3>
              <p className="text-indigo-200 text-sm mt-1">AI 已根据您的当前筛选数据生成针对性建议 (金额以 CFA 为准)</p>
            </div>
            <button onClick={handleGetAIInsights} disabled={loading} className="bg-white text-indigo-900 px-6 py-2.5 rounded-full font-bold hover:bg-indigo-50 transition-all disabled:opacity-50 flex items-center justify-center min-w-[140px]">
              {loading ? '分析中...' : '生成最新洞察'}
            </button>
          </div>
          {aiText ? (
            <div className="bg-indigo-800/50 p-6 rounded-xl border border-indigo-700 text-indigo-50 whitespace-pre-wrap leading-relaxed animate-in fade-in">{aiText}</div>
