const COLORS = [
  '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [aiText, setAiText] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [drillDownMetric, setDrillDownMetric] = useState<'sales' | 'quantity'>('sales');
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [showSummaryTable, setShowSummaryTable] = useState(false);
  const [selectedCustomerInDrillDown, setSelectedCustomerInDrillDown] = useState<string | null>(null);

  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  const [localTableFilters, setLocalTableFilters] = useState({
    id: '',
    date: '',
    customer: '',
    itemName: ''
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);

  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleGetAIInsights = async () => {
    setLoading(true);
    const insights = await getAIInsights(summary);
    setAiText(insights || '');
    setLoading(false);
  };

  /** 
   * 统一品类分析数据源 
   * 严格按照当前选中的 pieMetric (销售额或数量) 进行降序排列，确保饼图和图例顺序一致
   */
  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return {
        name: cat.name,
        sales: cat.value,
        quantity: qtyItem ? qtyItem.value : 0
      };
    });

    return merged.sort((a, b) => {
      if (pieMetric === 'sales') return b.sales - a.sales;
      return b.quantity - a.quantity;
    });
  }, [summary, pieMetric]);

  /** 当前度量指标下的总量，用于计算百分比 */
  const currentTotal = useMemo(() => {
    return sortedCategorySummary.reduce((acc, cur) => acc + (pieMetric === 'sales' ? cur.sales : cur.quantity), 0);
  }, [sortedCategorySummary, pieMetric]);

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], customers: [], records: [] };

    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const customersMap = new Map<string, { sales: number; qty: number; orderIds: Set<string> }>();
    let records: SalesRecord[] = [];

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        const itemExisting = itemsMap.get(record.itemName) || { sales: 0, qty: 0 };
        itemsMap.set(record.itemName, {
          sales: itemExisting.sales + record.totalAmount,
          qty: itemExisting.qty + record.quantity
        });

        const customerExisting = customersMap.get(record.customer) || { sales: 0, qty: 0, orderIds: new Set() };
        customerExisting.orderIds.add(record.id);
        customersMap.set(record.customer, {
          sales: customerExisting.sales + record.totalAmount,
          qty: customerExisting.qty + record.quantity,
          orderIds: customerExisting.orderIds
        });

        records.push(record);
      }
    });

    const items = Array.from(itemsMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty, orderIds: Array.from(val.orderIds).sort() }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    if (selectedCustomerInDrillDown) records = records.filter(r => r.customer === selectedCustomerInDrillDown);
    if (localTableFilters.id) records = records.filter(r => r.id === localTableFilters.id);
    if (localTableFilters.date) records = records.filter(r => r.date >= localTableFilters.date);
    if (localTableFilters.customer) records = records.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.itemName) records = records.filter(r => r.itemName === localTableFilters.itemName);

    return { items, customers, records: records.sort((a, b) => b.date.localeCompare(a.date)) };
  }, [selectedCategory, filteredData, drillDownMetric, selectedCustomerInDrillDown, localTableFilters]);

  const localFilterOptions = useMemo(() => {
    if (!selectedCategory) return { ids: [], dates: [], customers: [], itemNames: [] };
    const ids = new Set<string>();
    const dates = new Set<string>();
    const customers = new Set<string>();
    const itemNames = new Set<string>();

    filteredData.forEach(r => {
      if (r.category === selectedCategory) {
        ids.add(r.id);
        dates.add(r.date);
        customers.add(r.customer);
        itemNames.add(r.itemName);
      }
    });

    return {
      ids: Array.from(ids).sort().reverse(),
      dates: Array.from(dates).sort().reverse(),
      customers: Array.from(customers).sort(),
      itemNames: Array.from(itemNames).sort()
    };
  }, [filteredData, selectedCategory]);

  const onPieClick = (data: any) => {
    setDrillDownMetric(pieMetric);
    if (selectedCategory === data.name) {
      setSelectedCategory(null);
      setSelectedCustomerInDrillDown(null);
    } else {
      setSelectedCategory(data.name);
      setSelectedCustomerInDrillDown(null);
      setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' });
    }
  };

  const CustomYAxisTick = (props: any) => {
    const { x, y, payload } = props;
    const isSelected = payload.value === selectedCustomerInDrillDown;
    return (
      <g transform={`translate(${x},${y})`}>
        <text
          x={-15} y={0} dy={4} textAnchor="end"
          fill={isSelected ? '#2563eb' : '#475569'}
          className={`text-[10px] font-bold cursor-pointer hover:fill-blue-600 transition-colors ${isSelected ? 'underline' : ''}`}
          onClick={() => setSelectedCustomerInDrillDown(payload.value === selectedCustomerInDrillDown ? null : payload.value)}
        >
          {payload.value}
        </text>
      </g>
    );
  };

  const FilterHeader = ({ label, columnId, options }: { label: string, columnId: keyof typeof localTableFilters, options: string[] }) => {
    const isActive = !!localTableFilters[columnId];
    return (
      <th className="px-3 py-2 text-left relative">
        <div className="flex items-center gap-1.5 group">
          <span className="font-bold text-slate-400 uppercase tracking-tighter">{label}</span>
          <button 
            onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)}
            className={`p-1 rounded hover:bg-slate-200 transition-all ${isActive ? 'text-blue-600' : 'text-slate-300'}`}
          >
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" clipRule="evenodd" />
            </svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-56 bg-white rounded-xl shadow-2xl border border-slate-200 z-[70] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2 border-b border-slate-50 bg-slate-50 flex justify-between items-center">
              <span className="text-[10px] font-bold text-slate-400 uppercase">筛选{label}</span>
              {isActive && (
                <button onClick={() => setLocalTableFilters(p => ({ ...p, [columnId]: '' }))} className="text-[9px] text-red-500 font-bold hover:underline">清除</button>
              )}
            </div>
            <div className="max-h-56 overflow-y-auto p-1 custom-scrollbar">
              {options.map(opt => (
                <button
                  key={opt}
                  onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }}
                  className={`w-full text-left px-3 py-2 rounded-lg text-[11px] transition-colors ${localTableFilters[columnId] === opt ? 'bg-blue-50 text-blue-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {opt}
                </button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow flex flex-col h-full">
      <div className="flex justify-between items-start mb-4">
        <div className="p-2 bg-blue-50 rounded-lg text-blue-600 text-xl">{icon}</div>
        <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">{title}</span>
      </div>
      <div className="text-2xl font-bold text-slate-900 mb-1">{value}</div>
      <div className="text-sm text-slate-500 mb-3">{sub}</div>
      {children}
    </div>
  );

  return (
    <div className="space-y-8">
      {/* KPI Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KpiCard title="总销售额" value={`${summary.totalSales.toLocaleString()} CFA`} sub="当前筛选总额" icon="💰" />
        <KpiCard title="总出库数量" value={summary.totalQuantity.toLocaleString()} sub="物料销售总数" icon="📦" />
        <KpiCard title="出库单号" value={`${summary.orderCount} 个单号`} sub="点击快速查看详情" icon="📑">
          <div className="mt-auto max-h-32 overflow-y-auto pr-2 custom-scrollbar border-t border-slate-50 pt-2">
            <div className="flex flex-wrap gap-1.5">
              {summary.orderIds.map(id => (
                <button key={id} onClick={() => onSelectOrderId(id)} className="inline-block px-1.5 py-0.5 bg-blue-50 text-blue-600 text-[10px] font-mono rounded border border-blue-100 hover:bg-blue-600 hover:text-white transition-colors">
                  {id}
                </button>
              ))}
            </div>
          </div>
        </KpiCard>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col min-h-[640px]">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">📊 销售趋势综合分析</h3>
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button onClick={() => setShowCfa(!showCfa)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>金额</button>
              <button onClick={() => setShowQuantity(!showQuantity)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}>数量</button>
            </div>
          </div>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={summary.monthlyTrend} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorQty" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#3b82f6', fontSize: 11}} />
                <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 11}} />
                <Tooltip />
                {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorSales)" />}
                {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" stroke="#10b981" strokeWidth={3} fillOpacity={1} fill="url(#colorQty)" />}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative overflow-hidden flex flex-col min-h-[640px]">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">🧩 品类多维分布</h3>
            <div className="flex items-center gap-3">
               {!showSummaryTable && (
                 <div className="flex bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => setPieMetric('sales')} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${pieMetric === 'sales' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>金额</button>
                    <button onClick={() => setPieMetric('quantity')} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}>数量</button>
                  </div>
               )}
               {showSummaryTable && <button onClick={() => setShowSummaryTable(false)} className="text-[10px] bg-blue-600 text-white font-bold px-3 py-1.5 rounded">← 返回</button>}
            </div>
          </div>

          <div className="flex-1 flex flex-col overflow-hidden">
            {!showSummaryTable ? (
              <div className="flex-1 flex flex-col">
                <div className="flex-1">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie
                        data={sortedCategorySummary} 
                        cx="50%" cy="45%" innerRadius={70} outerRadius={110} paddingAngle={2}
                        startAngle={90} endAngle={-270}
                        dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} 
                        onClick={onPieClick} 
                        style={{ cursor: 'pointer', outline: 'none' }}
                      >
                        {sortedCategorySummary.map((entry, index) => (
                          <RechartsCell key={index} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />
                        ))}
                      </Pie>
                      <Tooltip formatter={(value: number) => [pieMetric === 'sales' ? `${value.toLocaleString()} CFA` : value.toLocaleString(), pieMetric === 'sales' ? '销售额' : '数量']} />
                      <Legend 
                        verticalAlign="bottom" 
                        layout="vertical"
                        align="center"
                        iconType="circle"
                        height={100}
                        formatter={(value) => {
                          const item = sortedCategorySummary.find(d => d.name === value);
                          const val = pieMetric === 'sales' ? item?.sales : item?.quantity;
                          const percentage = currentTotal > 0 ? ((val || 0) / currentTotal * 100).toFixed(1) : "0.0";
                          return (
                            <span className="text-[11px] text-slate-700 font-bold inline-flex justify-between w-[180px]">
                              <span>{value}</span>
                              <span className="text-blue-600 ml-2">{percentage}%</span>
                            </span>
                          );
                        }}
                      />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
                <button onClick={() => setShowSummaryTable(true)} className="mt-4 p-3 bg-slate-50 border border-dashed border-slate-200 rounded-xl text-[10px] font-bold text-slate-500 uppercase tracking-widest hover:bg-blue-50 transition-colors">展开汇总明细表</button>
              </div>
            ) : (
              <div className="flex-1 overflow-y-auto custom-scrollbar animate-in slide-in-from-right duration-300">
                <table className="min-w-full text-xs text-left">
                  <thead className="bg-slate-50 sticky top-0 z-10">
                    <tr>
                      <th className="px-3 py-2 text-slate-400 font-bold uppercase">品类 (按占比降序)</th>
                      <th className={`px-3 py-2 text-right font-bold uppercase ${pieMetric === 'sales' ? 'text-blue-600 bg-blue-50' : 'text-slate-400'}`}>金额 (CFA)</th>
                      <th className={`px-3 py-2 text-right font-bold uppercase ${pieMetric === 'quantity' ? 'text-green-600 bg-green-50' : 'text-slate-400'}`}>数量</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {sortedCategorySummary.map((item) => (
                      <tr key={item.name} onClick={() => { setSelectedCategory(item.name); setDrillDownMetric(pieMetric); }} className="hover:bg-blue-50 cursor-pointer transition-colors group">
                        <td className="px-3 py-3 font-bold text-slate-700">
                          <div className="flex items-center gap-2">
                             <div className="w-2 h-2 rounded-full" style={{backgroundColor: COLORS[sortedCategorySummary.indexOf(item) % COLORS.length]}}></div>
                             {item.name}
                          </div>
                        </td>
                        <td className={`px-3 py-3 text-right font-mono ${pieMetric === 'sales' ? 'font-black text-blue-700' : 'text-slate-600'}`}>{item.sales.toLocaleString()}</td>
                        <td className={`px-3 py-3 text-right font-mono ${pieMetric === 'quantity' ? 'font-black text-green-700' : 'text-slate-600'}`}>{item.quantity.toLocaleString()}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {selectedCategory && (
            <div className="absolute inset-0 bg-white/98 backdrop-blur-md z-20 p-6 flex flex-col animate-in slide-in-from-right duration-300 shadow-2xl overflow-hidden">
              <div className="flex items-center justify-between mb-6 border-b border-slate-100 pb-4">
                <div>
                  <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">Depth Analysis</h4>
                  <h3 className="text-2xl font-black text-slate-900">{selectedCategory}</h3>
                </div>
                <div className="flex items-center gap-2">
                   <div className="flex bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => setDrillDownMetric('sales')} className={`px-2 py-1 rounded-md text-[9px] font-bold transition-all ${drillDownMetric === 'sales' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400'}`}>按金额</button>
                    <button onClick={() => setDrillDownMetric('quantity')} className={`px-2 py-1 rounded-md text-[9px] font-bold transition-all ${drillDownMetric === 'quantity' ? 'bg-white shadow-sm text-green-600' : 'text-slate-400'}`}>按数量</button>
                  </div>
                  <button onClick={() => { setSelectedCategory(null); setSelectedCustomerInDrillDown(null); }} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg></button>
                </div>
              </div>

              <div className="flex-1 overflow-y-auto custom-scrollbar space-y-10 pb-20">
                <section>
                  <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">按客户分布 (点击客户名进行二次筛选)</h5>
                  <div className="min-h-[450px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={drillDownData.customers} layout="vertical" margin={{ left: 20, right: 40 }}>
                        <XAxis type="number" hide />
                        <YAxis 
                          dataKey="name" 
                          type="category" 
                          axisLine={false} 
                          tickLine={false} 
                          width={240} 
                          interval={0} 
                          tick={<CustomYAxisTick />} 
                        />
                        <Tooltip cursor={{fill: '#f8fafc'}} />
                        <Bar 
                          dataKey={drillDownMetric === 'sales' ? 'sales' : 'qty'} 
                          fill="#3b82f6" 
                          radius={[0, 6, 6, 0]} 
                          barSize={20}
                        >
                          {drillDownData.customers.map((entry, index) => (
                            <RechartsCell 
                              key={index} 
                              fill={COLORS[index % COLORS.length]} 
                              stroke={entry.name === selectedCustomerInDrillDown ? '#2563eb' : 'none'} 
                              strokeWidth={3} 
                            />
                          ))}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </section>

                <section>
                  <div className="flex items-center justify-between mb-4">
                    <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                       <span className="w-1.5 h-3 bg-blue-600 rounded-full"></span> 原始交易明细 (含多维下拉筛选)
                    </h5>
                    {(selectedCustomerInDrillDown || Object.values(localTableFilters).some(v => !!v)) && (
                      <button 
                        onClick={() => { 
                          setSelectedCustomerInDrillDown(null); 
                          setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' }); 
                        }} 
                        className="text-[10px] text-blue-600 font-bold hover:underline"
                      >
                        重置局部筛选
                      </button>
                    )}
                  </div>

                  <div className="overflow-x-auto rounded-xl border border-slate-100 bg-white shadow-sm min-h-[400px]">
                    <table className="min-w-full text-[11px]">
                      <thead className="bg-slate-50 border-b border-slate-100 sticky top-0 z-50">
                        <tr>
                          <FilterHeader label="出库单号" columnId="id" options={localFilterOptions.ids} />
                          <FilterHeader label="日期" columnId="date" options={localFilterOptions.dates} />
                          <FilterHeader label="客户" columnId="customer" options={localFilterOptions.customers} />
                          <FilterHeader label="物料名称" columnId="itemName" options={localFilterOptions.itemNames} />
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">单价</th>
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">数量</th>
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">金额 (CFA)</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {drillDownData.records.slice(0, 100).map((r, i) => (
                          <tr key={`${r.id}-${i}`} className="hover:bg-slate-50 transition-colors">
                            <td className="px-3 py-3 text-blue-600 font-mono font-bold">
                              <button onClick={() => onSelectOrderId(r.id)}>{r.id}</button>
                            </td>
                            <td className="px-3 py-3 text-slate-500">{r.date}</td>
                            <td className="px-3 py-3 text-slate-900 font-bold">{r.customer}</td>
                            <td className="px-3 py-3 text-slate-600 truncate max-w-[120px]">{r.itemName}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-500">{r.unitPrice.toLocaleString()}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-600">{r.quantity}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-900 font-bold">{r.totalAmount.toLocaleString()}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    {drillDownData.records.length === 0 && (
                      <div className="py-20 text-center text-slate-400 italic bg-slate-50/50">该组合筛选条件下暂无明细记录</div>
                    )}
                  </div>
                </section>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-6">🏆 销售员业绩排行 (CFA)</h3>
        <div className="h-[350px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical" margin={{ left: 20 }}>
              <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={80} tick={{fill: '#475569', fontWeight: 500}} />
              <Tooltip cursor={{fill: '#f8fafc'}} formatter={(v) => [`${v.toLocaleString()} CFA`, '总销售额']} />
              <Bar dataKey="value" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={24} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-indigo-900 text-white p-8 rounded-2xl shadow-xl overflow-hidden relative">
        <div className="relative z-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
            <div>
              <h3 className="text-xl font-bold flex items-center">✨ Gemini 智能商业洞察</h3>
              <p className="text-indigo-200 text-sm mt-1">AI 已根据您的当前筛选数据生成针对性建议 (金额以 CFA 为准)</p>
            </div>
            <button onClick={handleGetAIInsights} disabled={loading} className="bg-white text-indigo-900 px-6 py-2.5 rounded-full font-bold hover:bg-indigo-50 transition-all disabled:opacity-50 flex items-center justify-center min-w-[140px]">
              {loading ? '分析中...' : '生成最新洞察'}
            </button>
          </div>
          {aiText ? (
            <div className="bg-indigo-800/50 p-6 rounded-xl border border-indigo-700 text-indigo-50 whitespace-pre-wrap leading-relaxed animate-in fade-in">{aiText}</div>
          ) : (
            <div className="flex flex-col items-center justify-center py-12 border-2 border-dashed border-indigo-700 rounded-xl text-indigo-300">
              <span className="text-4xl mb-4">💡</span>
              <p>点击上方按钮，获取 AI 关于业绩、增长、瓶颈的深度分析建议</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Legend, Cell as RechartsCell
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';
import { getAIInsights } from '../services/geminiService';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [aiText, setAiText] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [drillDownMetric, setDrillDownMetric] = useState<'sales' | 'quantity'>('sales');
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [showSummaryTable, setShowSummaryTable] = useState(false);
  const [selectedCustomerInDrillDown, setSelectedCustomerInDrillDown] = useState<string | null>(null);

  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  const [localTableFilters, setLocalTableFilters] = useState({
    id: '',
    date: '',
    customer: '',
    itemName: ''
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);

  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleGetAIInsights = async () => {
    setLoading(true);
    const insights = await getAIInsights(summary);
    setAiText(insights || '');
    setLoading(false);
  };

  /** 
   * 统一品类分析数据源 
   * 严格按照当前选中的 pieMetric (销售额或数量) 进行降序排列，确保饼图和图例顺序一致
   */
  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return {
        name: cat.name,
        sales: cat.value,
        quantity: qtyItem ? qtyItem.value : 0
      };
    });

    return merged.sort((a, b) => {
      if (pieMetric === 'sales') return b.sales - a.sales;
      return b.quantity - a.quantity;
    });
  }, [summary, pieMetric]);

  /** 当前度量指标下的总量，用于计算百分比和顶部标题显示 */
  const currentTotal = useMemo(() => {
    return sortedCategorySummary.reduce((acc, cur) => acc + (pieMetric === 'sales' ? cur.sales : cur.quantity), 0);
  }, [sortedCategorySummary, pieMetric]);

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], customers: [], records: [] };

    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const customersMap = new Map<string, { sales: number; qty: number; orderIds: Set<string> }>();
    let records: SalesRecord[] = [];

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        const itemExisting = itemsMap.get(record.itemName) || { sales: 0, qty: 0 };
        itemsMap.set(record.itemName, {
          sales: itemExisting.sales + record.totalAmount,
          qty: itemExisting.qty + record.quantity
        });

        const customerExisting = customersMap.get(record.customer) || { sales: 0, qty: 0, orderIds: new Set() };
        customerExisting.orderIds.add(record.id);
        customersMap.set(record.customer, {
          sales: customerExisting.sales + record.totalAmount,
          qty: customerExisting.qty + record.quantity,
          orderIds: customerExisting.orderIds
        });

        records.push(record);
      }
    });

    const items = Array.from(itemsMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty, orderIds: Array.from(val.orderIds).sort() }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    if (selectedCustomerInDrillDown) records = records.filter(r => r.customer === selectedCustomerInDrillDown);
    if (localTableFilters.id) records = records.filter(r => r.id === localTableFilters.id);
    if (localTableFilters.date) records = records.filter(r => r.date >= localTableFilters.date);
    if (localTableFilters.customer) records = records.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.itemName) records = records.filter(r => r.itemName === localTableFilters.itemName);

    return { items, customers, records: records.sort((a, b) => b.date.localeCompare(a.date)) };
  }, [selectedCategory, filteredData, drillDownMetric, selectedCustomerInDrillDown, localTableFilters]);

  const localFilterOptions = useMemo(() => {
    if (!selectedCategory) return { ids: [], dates: [], customers: [], itemNames: [] };
    const ids = new Set<string>();
    const dates = new Set<string>();
    const customers = new Set<string>();
    const itemNames = new Set<string>();

    filteredData.forEach(r => {
      if (r.category === selectedCategory) {
        ids.add(r.id);
        dates.add(r.date);
        customers.add(r.customer);
        itemNames.add(r.itemName);
      }
    });

    return {
      ids: Array.from(ids).sort().reverse(),
      dates: Array.from(dates).sort().reverse(),
      customers: Array.from(customers).sort(),
      itemNames: Array.from(itemNames).sort()
    };
  }, [filteredData, selectedCategory]);

  const onPieClick = (data: any) => {
    setDrillDownMetric(pieMetric);
    if (selectedCategory === data.name) {
      setSelectedCategory(null);
      setSelectedCustomerInDrillDown(null);
    } else {
      setSelectedCategory(data.name);
      setSelectedCustomerInDrillDown(null);
      setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' });
    }
  };

  const CustomYAxisTick = (props: any) => {
    const { x, y, payload } = props;
    const isSelected = payload.value === selectedCustomerInDrillDown;
    return (
      <g transform={`translate(${x},${y})`}>
        <text
          x={-15} y={0} dy={4} textAnchor="end"
          fill={isSelected ? '#2563eb' : '#475569'}
          className={`text-[10px] font-bold cursor-pointer hover:fill-blue-600 transition-colors ${isSelected ? 'underline' : ''}`}
          onClick={() => setSelectedCustomerInDrillDown(payload.value === selectedCustomerInDrillDown ? null : payload.value)}
        >
          {payload.value}
        </text>
      </g>
    );
  };

  const FilterHeader = ({ label, columnId, options }: { label: string, columnId: keyof typeof localTableFilters, options: string[] }) => {
    const isActive = !!localTableFilters[columnId];
    return (
      <th className="px-3 py-2 text-left relative">
        <div className="flex items-center gap-1.5 group">
          <span className="font-bold text-slate-400 uppercase tracking-tighter">{label}</span>
          <button 
            onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)}
            className={`p-1 rounded hover:bg-slate-200 transition-all ${isActive ? 'text-blue-600' : 'text-slate-300'}`}
          >
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" clipRule="evenodd" />
            </svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-56 bg-white rounded-xl shadow-2xl border border-slate-200 z-[70] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2 border-b border-slate-50 bg-slate-50 flex justify-between items-center">
              <span className="text-[10px] font-bold text-slate-400 uppercase">筛选{label}</span>
              {isActive && (
                <button onClick={() => setLocalTableFilters(p => ({ ...p, [columnId]: '' }))} className="text-[9px] text-red-500 font-bold hover:underline">清除</button>
              )}
            </div>
            <div className="max-h-56 overflow-y-auto p-1 custom-scrollbar">
              {options.map(opt => (
                <button
                  key={opt}
                  onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }}
                  className={`w-full text-left px-3 py-2 rounded-lg text-[11px] transition-colors ${localTableFilters[columnId] === opt ? 'bg-blue-50 text-blue-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {opt}
                </button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow flex flex-col h-full">
      <div className="flex justify-between items-start mb-4">
        <div className="p-2 bg-blue-50 rounded-lg text-blue-600 text-xl">{icon}</div>
        <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">{title}</span>
      </div>
      <div className="text-2xl font-bold text-slate-900 mb-1">{value}</div>
      <div className="text-sm text-slate-500 mb-3">{sub}</div>
      {children}
    </div>
  );

  return (
    <div className="space-y-8">
      {/* KPI Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KpiCard title="总销售额" value={`${summary.totalSales.toLocaleString()} CFA`} sub="当前筛选总额" icon="💰" />
        <KpiCard title="总出库数量" value={summary.totalQuantity.toLocaleString()} sub="物料销售总数" icon="📦" />
        <KpiCard title="出库单号" value={`${summary.orderCount} 个单号`} sub="点击快速查看详情" icon="📑">
          <div className="mt-auto max-h-32 overflow-y-auto pr-2 custom-scrollbar border-t border-slate-50 pt-2">
            <div className="flex flex-wrap gap-1.5">
              {summary.orderIds.map(id => (
                <button key={id} onClick={() => onSelectOrderId(id)} className="inline-block px-1.5 py-0.5 bg-blue-50 text-blue-600 text-[10px] font-mono rounded border border-blue-100 hover:bg-blue-600 hover:text-white transition-colors">
                  {id}
                </button>
              ))}
            </div>
          </div>
        </KpiCard>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col min-h-[780px]">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">📊 销售趋势综合分析</h3>
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button onClick={() => setShowCfa(!showCfa)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>金额</button>
              <button onClick={() => setShowQuantity(!showQuantity)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}>数量</button>
            </div>
          </div>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={summary.monthlyTrend} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorQty" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#3b82f6', fontSize: 11}} />
                <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 11}} />
                <Tooltip />
                {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorSales)" />}
                {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" stroke="#10b981" strokeWidth={3} fillOpacity={1} fill="url(#colorQty)" />}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative overflow-hidden flex flex-col min-h-[780px]">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h3 className="text-lg font-bold text-slate-800 flex items-center">🧩 品类多维分布</h3>
              {/* 动态汇总显示：左上角根据选中的度量指标显示总和 */}
              <div className="mt-1.5 flex items-center gap-2">
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{pieMetric === 'sales' ? '当前筛选总额:' : '当前筛选总量:'}</span>
                <span className={`text-sm font-black ${pieMetric === 'sales' ? 'text-blue-600' : 'text-green-600'}`}>
                   {pieMetric === 'sales' ? `${currentTotal.toLocaleString()} CFA` : currentTotal.toLocaleString()}
                </span>
              </div>
            </div>
            <div className="flex items-center gap-3">
               {!showSummaryTable && (
                 <div className="flex bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => setPieMetric('sales')} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${pieMetric === 'sales' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>金额</button>
                    <button onClick={() => setPieMetric('quantity')} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}>数量</button>
                  </div>
               )}
               {showSummaryTable && <button onClick={() => setShowSummaryTable(false)} className="text-[10px] bg-blue-600 text-white font-bold px-3 py-1.5 rounded">← 返回</button>}
            </div>
          </div>

          <div className="flex-1 flex flex-col overflow-hidden">
            {!showSummaryTable ? (
              <div className="flex-1 flex flex-col">
                <div className="flex-1">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie
                        data={sortedCategorySummary} 
                        cx="50%" cy="45%" innerRadius={80} outerRadius={130} paddingAngle={2}
                        startAngle={90} endAngle={-270}
                        dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} 
                        onClick={onPieClick} 
                        style={{ cursor: 'pointer', outline: 'none' }}
                      >
                        {sortedCategorySummary.map((entry, index) => (
                          <RechartsCell key={index} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />
                        ))}
                      </Pie>
                      <Tooltip formatter={(value: number) => [pieMetric === 'sales' ? `${value.toLocaleString()} CFA` : value.toLocaleString(), pieMetric === 'sales' ? '销售额' : '数量']} />
                      <Legend 
                        verticalAlign="bottom" 
                        layout="vertical"
                        align="center"
                        iconType="circle"
                        height={140}
                        formatter={(value) => {
                          const item = sortedCategorySummary.find(d => d.name === value);
                          const val = pieMetric === 'sales' ? item?.sales : item?.quantity;
                          const percentage = currentTotal > 0 ? ((val || 0) / currentTotal * 100).toFixed(1) : "0.0";
                          return (
                            <span className="text-[11px] text-slate-700 font-bold inline-flex justify-between w-[220px] py-0.5 border-b border-slate-50">
                              <span>{value}</span>
                              <span className={pieMetric === 'sales' ? 'text-blue-600' : 'text-green-600'}>{percentage}%</span>
                            </span>
                          );
                        }}
                      />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
                <button onClick={() => setShowSummaryTable(true)} className="mt-4 p-3 bg-slate-50 border border-dashed border-slate-200 rounded-xl text-[10px] font-bold text-slate-500 uppercase tracking-widest hover:bg-blue-50 transition-colors">展开汇总明细表</button>
              </div>
            ) : (
              <div className="flex-1 overflow-y-auto custom-scrollbar animate-in slide-in-from-right duration-300">
                <table className="min-w-full text-xs text-left">
                  <thead className="bg-slate-50 sticky top-0 z-10">
                    <tr>
                      <th className="px-3 py-2 text-slate-400 font-bold uppercase">品类 (按占比降序)</th>
                      <th className={`px-3 py-2 text-right font-bold uppercase ${pieMetric === 'sales' ? 'text-blue-600 bg-blue-50' : 'text-slate-400'}`}>金额 (CFA)</th>
                      <th className={`px-3 py-2 text-right font-bold uppercase ${pieMetric === 'quantity' ? 'text-green-600 bg-green-50' : 'text-slate-400'}`}>数量</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {sortedCategorySummary.map((item) => (
                      <tr key={item.name} onClick={() => { setSelectedCategory(item.name); setDrillDownMetric(pieMetric); }} className="hover:bg-blue-50 cursor-pointer transition-colors group">
                        <td className="px-3 py-3 font-bold text-slate-700">
                          <div className="flex items-center gap-2">
                             <div className="w-2 h-2 rounded-full" style={{backgroundColor: COLORS[sortedCategorySummary.indexOf(item) % COLORS.length]}}></div>
                             {item.name}
                          </div>
                        </td>
                        <td className={`px-3 py-3 text-right font-mono ${pieMetric === 'sales' ? 'font-black text-blue-700' : 'text-slate-600'}`}>{item.sales.toLocaleString()}</td>
                        <td className={`px-3 py-3 text-right font-mono ${pieMetric === 'quantity' ? 'font-black text-green-700' : 'text-slate-600'}`}>{item.quantity.toLocaleString()}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {selectedCategory && (
            <div className="absolute inset-0 bg-white/98 backdrop-blur-md z-20 p-6 flex flex-col animate-in slide-in-from-right duration-300 shadow-2xl overflow-hidden">
              <div className="flex items-center justify-between mb-6 border-b border-slate-100 pb-4">
                <div>
                  <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">Depth Analysis</h4>
                  <h3 className="text-2xl font-black text-slate-900">{selectedCategory}</h3>
                </div>
                <div className="flex items-center gap-2">
                   <div className="flex bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => setDrillDownMetric('sales')} className={`px-2 py-1 rounded-md text-[9px] font-bold transition-all ${drillDownMetric === 'sales' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400'}`}>按金额</button>
                    <button onClick={() => setDrillDownMetric('quantity')} className={`px-2 py-1 rounded-md text-[9px] font-bold transition-all ${drillDownMetric === 'quantity' ? 'bg-white shadow-sm text-green-600' : 'text-slate-400'}`}>按数量</button>
                  </div>
                  <button onClick={() => { setSelectedCategory(null); setSelectedCustomerInDrillDown(null); }} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg></button>
                </div>
              </div>

              <div className="flex-1 overflow-y-auto custom-scrollbar space-y-10 pb-20">
                <section>
                  <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">按客户分布 (点击客户名进行二次筛选)</h5>
                  <div className="min-h-[450px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={drillDownData.customers} layout="vertical" margin={{ left: 20, right: 40 }}>
                        <XAxis type="number" hide />
                        <YAxis 
                          dataKey="name" 
                          type="category" 
                          axisLine={false} 
                          tickLine={false} 
                          width={240} 
                          interval={0} 
                          tick={<CustomYAxisTick />} 
                        />
                        <Tooltip cursor={{fill: '#f8fafc'}} />
                        <Bar 
                          dataKey={drillDownMetric === 'sales' ? 'sales' : 'qty'} 
                          fill="#3b82f6" 
                          radius={[0, 6, 6, 0]} 
                          barSize={20}
                        >
                          {drillDownData.customers.map((entry, index) => (
                            <RechartsCell 
                              key={index} 
                              fill={COLORS[index % COLORS.length]} 
                              stroke={entry.name === selectedCustomerInDrillDown ? '#2563eb' : 'none'} 
                              strokeWidth={3} 
                            />
                          ))}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </section>

                <section>
                  <div className="flex items-center justify-between mb-4">
                    <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                       <span className="w-1.5 h-3 bg-blue-600 rounded-full"></span> 原始交易明细 (含多维下拉筛选)
                    </h5>
                    {(selectedCustomerInDrillDown || Object.values(localTableFilters).some(v => !!v)) && (
                      <button 
                        onClick={() => { 
                          setSelectedCustomerInDrillDown(null); 
                          setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' }); 
                        }} 
                        className="text-[10px] text-blue-600 font-bold hover:underline"
                      >
                        重置局部筛选
                      </button>
                    )}
                  </div>

                  <div className="overflow-x-auto rounded-xl border border-slate-100 bg-white shadow-sm min-h-[400px]">
                    <table className="min-w-full text-[11px]">
                      <thead className="bg-slate-50 border-b border-slate-100 sticky top-0 z-50">
                        <tr>
                          <FilterHeader label="出库单号" columnId="id" options={localFilterOptions.ids} />
                          <FilterHeader label="日期" columnId="date" options={localFilterOptions.dates} />
                          <FilterHeader label="客户" columnId="customer" options={localFilterOptions.customers} />
                          <FilterHeader label="物料名称" columnId="itemName" options={localFilterOptions.itemNames} />
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">单价</th>
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">数量</th>
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">金额 (CFA)</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {drillDownData.records.slice(0, 100).map((r, i) => (
                          <tr key={`${r.id}-${i}`} className="hover:bg-slate-50 transition-colors">
                            <td className="px-3 py-3 text-blue-600 font-mono font-bold">
                              <button onClick={() => onSelectOrderId(r.id)}>{r.id}</button>
                            </td>
                            <td className="px-3 py-3 text-slate-500">{r.date}</td>
                            <td className="px-3 py-3 text-slate-900 font-bold">{r.customer}</td>
                            <td className="px-3 py-3 text-slate-600 truncate max-w-[120px]">{r.itemName}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-500">{r.unitPrice.toLocaleString()}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-600">{r.quantity}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-900 font-bold">{r.totalAmount.toLocaleString()}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    {drillDownData.records.length === 0 && (
                      <div className="py-20 text-center text-slate-400 italic bg-slate-50/50">该组合筛选条件下暂无明细记录</div>
                    )}
                  </div>
                </section>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-6">🏆 销售员业绩排行 (CFA)</h3>
        <div className="h-[350px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical" margin={{ left: 20 }}>
              <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={80} tick={{fill: '#475569', fontWeight: 500}} />
              <Tooltip cursor={{fill: '#f8fafc'}} formatter={(v) => [`${v.toLocaleString()} CFA`, '总销售额']} />
              <Bar dataKey="value" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={24} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-indigo-900 text-white p-8 rounded-2xl shadow-xl overflow-hidden relative">
        <div className="relative z-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
            <div>
              <h3 className="text-xl font-bold flex items-center">✨ Gemini 智能商业洞察</h3>
              <p className="text-indigo-200 text-sm mt-1">AI 已根据您的当前筛选数据生成针对性建议 (金额以 CFA 为准)</p>
            </div>
            <button onClick={handleGetAIInsights} disabled={loading} className="bg-white text-indigo-900 px-6 py-2.5 rounded-full font-bold hover:bg-indigo-50 transition-all disabled:opacity-50 flex items-center justify-center min-w-[140px]">
              {loading ? '分析中...' : '生成最新洞察'}
            </button>
          </div>
          {aiText ? (
            <div className="bg-indigo-800/50 p-6 rounded-xl border border-indigo-700 text-indigo-50 whitespace-pre-wrap leading-relaxed animate-in fade-in">{aiText}</div>
          ) : (
            <div className="flex flex-col items-center justify-center py-12 border-2 border-dashed border-indigo-700 rounded-xl text-indigo-300">
              <span className="text-4xl mb-4">💡</span>
              <p>点击上方按钮，获取 AI 关于业绩、增长、瓶颈的深度分析建议</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Legend, Cell as RechartsCell
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';
import { getAIInsights } from '../services/geminiService';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [aiText, setAiText] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [drillDownMetric, setDrillDownMetric] = useState<'sales' | 'quantity'>('sales');
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [showSummaryTable, setShowSummaryTable] = useState(false);
  const [selectedCustomerInDrillDown, setSelectedCustomerInDrillDown] = useState<string | null>(null);

  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  const [localTableFilters, setLocalTableFilters] = useState({
    id: '',
    date: '',
    customer: '',
    itemName: ''
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);

  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleGetAIInsights = async () => {
    setLoading(true);
    const insights = await getAIInsights(summary);
    setAiText(insights || '');
    setLoading(false);
  };

  /** 
   * 统一品类分析数据源 
   * 严格按照当前选中的 pieMetric (销售额或数量) 进行降序排列，确保饼图和图例顺序一致
   */
  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return {
        name: cat.name,
        sales: cat.value,
        quantity: qtyItem ? qtyItem.value : 0
      };
    });

    return merged.sort((a, b) => {
      if (pieMetric === 'sales') return b.sales - a.sales;
      return b.quantity - a.quantity;
    });
  }, [summary, pieMetric]);

  /** 当前度量指标下的总量，用于计算百分比和顶部标题显示 */
  const currentTotal = useMemo(() => {
    return sortedCategorySummary.reduce((acc, cur) => acc + (pieMetric === 'sales' ? cur.sales : cur.quantity), 0);
  }, [sortedCategorySummary, pieMetric]);

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], customers: [], records: [] };

    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const customersMap = new Map<string, { sales: number; qty: number; orderIds: Set<string> }>();
    let records: SalesRecord[] = [];

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        const itemExisting = itemsMap.get(record.itemName) || { sales: 0, qty: 0 };
        itemsMap.set(record.itemName, {
          sales: itemExisting.sales + record.totalAmount,
          qty: itemExisting.qty + record.quantity
        });

        const customerExisting = customersMap.get(record.customer) || { sales: 0, qty: 0, orderIds: new Set() };
        customerExisting.orderIds.add(record.id);
        customersMap.set(record.customer, {
          sales: customerExisting.sales + record.totalAmount,
          qty: customerExisting.qty + record.quantity,
          orderIds: customerExisting.orderIds
        });

        records.push(record);
      }
    });

    const items = Array.from(itemsMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty, orderIds: Array.from(val.orderIds).sort() }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    if (selectedCustomerInDrillDown) records = records.filter(r => r.customer === selectedCustomerInDrillDown);
    if (localTableFilters.id) records = records.filter(r => r.id === localTableFilters.id);
    if (localTableFilters.date) records = records.filter(r => r.date >= localTableFilters.date);
    if (localTableFilters.customer) records = records.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.itemName) records = records.filter(r => r.itemName === localTableFilters.itemName);

    return { items, customers, records: records.sort((a, b) => b.date.localeCompare(a.date)) };
  }, [selectedCategory, filteredData, drillDownMetric, selectedCustomerInDrillDown, localTableFilters]);

  const localFilterOptions = useMemo(() => {
    if (!selectedCategory) return { ids: [], dates: [], customers: [], itemNames: [] };
    const ids = new Set<string>();
    const dates = new Set<string>();
    const customers = new Set<string>();
    const itemNames = new Set<string>();

    filteredData.forEach(r => {
      if (r.category === selectedCategory) {
        ids.add(r.id);
        dates.add(r.date);
        customers.add(r.customer);
        itemNames.add(r.itemName);
      }
    });

    return {
      ids: Array.from(ids).sort().reverse(),
      dates: Array.from(dates).sort().reverse(),
      customers: Array.from(customers).sort(),
      itemNames: Array.from(itemNames).sort()
    };
  }, [filteredData, selectedCategory]);

  const onPieClick = (data: any) => {
    setDrillDownMetric(pieMetric);
    if (selectedCategory === data.name) {
      setSelectedCategory(null);
      setSelectedCustomerInDrillDown(null);
    } else {
      setSelectedCategory(data.name);
      setSelectedCustomerInDrillDown(null);
      setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' });
    }
  };

  const CustomYAxisTick = (props: any) => {
    const { x, y, payload } = props;
    const isSelected = payload.value === selectedCustomerInDrillDown;
    return (
      <g transform={`translate(${x},${y})`}>
        <text
          x={-15} y={0} dy={4} textAnchor="end"
          fill={isSelected ? '#2563eb' : '#475569'}
          className={`text-[10px] font-bold cursor-pointer hover:fill-blue-600 transition-colors ${isSelected ? 'underline' : ''}`}
          onClick={() => setSelectedCustomerInDrillDown(payload.value === selectedCustomerInDrillDown ? null : payload.value)}
        >
          {payload.value}
        </text>
      </g>
    );
  };

  const FilterHeader = ({ label, columnId, options }: { label: string, columnId: keyof typeof localTableFilters, options: string[] }) => {
    const isActive = !!localTableFilters[columnId];
    return (
      <th className="px-3 py-2 text-left relative">
        <div className="flex items-center gap-1.5 group">
          <span className="font-bold text-slate-400 uppercase tracking-tighter">{label}</span>
          <button 
            onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)}
            className={`p-1 rounded hover:bg-slate-200 transition-all ${isActive ? 'text-blue-600' : 'text-slate-300'}`}
          >
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" clipRule="evenodd" />
            </svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-56 bg-white rounded-xl shadow-2xl border border-slate-200 z-[70] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2 border-b border-slate-50 bg-slate-50 flex justify-between items-center">
              <span className="text-[10px] font-bold text-slate-400 uppercase">筛选{label}</span>
              {isActive && (
                <button onClick={() => setLocalTableFilters(p => ({ ...p, [columnId]: '' }))} className="text-[9px] text-red-500 font-bold hover:underline">清除</button>
              )}
            </div>
            <div className="max-h-56 overflow-y-auto p-1 custom-scrollbar">
              {options.map(opt => (
                <button
                  key={opt}
                  onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }}
                  className={`w-full text-left px-3 py-2 rounded-lg text-[11px] transition-colors ${localTableFilters[columnId] === opt ? 'bg-blue-50 text-blue-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {opt}
                </button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow flex flex-col h-full">
      <div className="flex justify-between items-start mb-4">
        <div className="p-2 bg-blue-50 rounded-lg text-blue-600 text-xl">{icon}</div>
        <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">{title}</span>
      </div>
      <div className="text-2xl font-bold text-slate-900 mb-1">{value}</div>
      <div className="text-sm text-slate-500 mb-3">{sub}</div>
      {children}
    </div>
  );

  return (
    <div className="space-y-8">
      {/* KPI Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KpiCard title="总销售额" value={`${summary.totalSales.toLocaleString()} CFA`} sub="当前筛选总额" icon="💰" />
        <KpiCard title="总出库数量" value={summary.totalQuantity.toLocaleString()} sub="物料销售总数" icon="📦" />
        <KpiCard title="出库单号" value={`${summary.orderCount} 个单号`} sub="点击快速查看详情" icon="📑">
          <div className="mt-auto max-h-32 overflow-y-auto pr-2 custom-scrollbar border-t border-slate-50 pt-2">
            <div className="flex flex-wrap gap-1.5">
              {summary.orderIds.map(id => (
                <button key={id} onClick={() => onSelectOrderId(id)} className="inline-block px-1.5 py-0.5 bg-blue-50 text-blue-600 text-[10px] font-mono rounded border border-blue-100 hover:bg-blue-600 hover:text-white transition-colors">
                  {id}
                </button>
              ))}
            </div>
          </div>
        </KpiCard>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col min-h-[780px]">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">📊 销售趋势综合分析</h3>
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button onClick={() => setShowCfa(!showCfa)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>金额</button>
              <button onClick={() => setShowQuantity(!showQuantity)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}>数量</button>
            </div>
          </div>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={summary.monthlyTrend} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorQty" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#3b82f6', fontSize: 11}} />
                <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 11}} />
                <Tooltip />
                {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorSales)" />}
                {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" stroke="#10b981" strokeWidth={3} fillOpacity={1} fill="url(#colorQty)" />}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative overflow-hidden flex flex-col min-h-[780px]">
          <div className="flex justify-between items-center mb-6">
            <div className="flex flex-col">
              <div className="flex items-center gap-2">
                <h3 className="text-lg font-bold text-slate-800 flex items-center">🧩 品类多维分布</h3>
                {/* 简化后的展开明细按钮，位于左侧标题旁 */}
                {!showSummaryTable && (
                  <button 
                    onClick={() => setShowSummaryTable(true)} 
                    title="展开汇总明细表"
                    className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-md transition-all flex items-center justify-center border border-slate-100"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 10h16M4 14h16M4 18h16" />
                    </svg>
                  </button>
                )}
              </div>
              <div className="mt-1.5 flex items-center gap-2">
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{pieMetric === 'sales' ? '当前筛选总额:' : '当前筛选总量:'}</span>
                <span className={`text-sm font-black ${pieMetric === 'sales' ? 'text-blue-600' : 'text-green-600'}`}>
                   {pieMetric === 'sales' ? `${currentTotal.toLocaleString()} CFA` : currentTotal.toLocaleString()}
                </span>
              </div>
            </div>
            <div className="flex items-center gap-3">
               {!showSummaryTable && (
                 <div className="flex bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => setPieMetric('sales')} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${pieMetric === 'sales' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>金额</button>
                    <button onClick={() => setPieMetric('quantity')} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}>数量</button>
                  </div>
               )}
               {showSummaryTable && <button onClick={() => setShowSummaryTable(false)} className="text-[10px] bg-blue-600 text-white font-bold px-3 py-1.5 rounded shadow-sm hover:bg-blue-700 transition-colors">← 返回图表</button>}
            </div>
          </div>

          <div className="flex-1 flex flex-col overflow-hidden">
            {!showSummaryTable ? (
              <div className="flex-1 flex flex-col">
                <div className="flex-1">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie
                        data={sortedCategorySummary} 
                        cx="50%" cy="45%" innerRadius={80} outerRadius={130} paddingAngle={2}
                        startAngle={90} endAngle={-270}
                        dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} 
                        onClick={onPieClick} 
                        style={{ cursor: 'pointer', outline: 'none' }}
                      >
                        {sortedCategorySummary.map((entry, index) => (
                          <RechartsCell key={index} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />
                        ))}
                      </Pie>
                      <Tooltip formatter={(value: number) => [pieMetric === 'sales' ? `${value.toLocaleString()} CFA` : value.toLocaleString(), pieMetric === 'sales' ? '销售额' : '数量']} />
                      <Legend 
                        verticalAlign="bottom" 
                        layout="vertical"
                        align="center"
                        iconType="circle"
                        height={140}
                        formatter={(value) => {
                          const item = sortedCategorySummary.find(d => d.name === value);
                          const val = pieMetric === 'sales' ? item?.sales : item?.quantity;
                          const percentage = currentTotal > 0 ? ((val || 0) / currentTotal * 100).toFixed(1) : "0.0";
                          return (
                            <span className="text-[11px] text-slate-700 font-bold inline-flex justify-between w-[220px] py-0.5 border-b border-slate-50">
                              <span>{value}</span>
                              <span className={pieMetric === 'sales' ? 'text-blue-600' : 'text-green-600'}>{percentage}%</span>
                            </span>
                          );
                        }}
                      />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              </div>
            ) : (
              <div className="flex-1 overflow-y-auto custom-scrollbar animate-in slide-in-from-right duration-300">
                <table className="min-w-full text-xs text-left">
                  <thead className="bg-slate-50 sticky top-0 z-10">
                    <tr>
                      <th className="px-3 py-2 text-slate-400 font-bold uppercase">品类 (按占比降序)</th>
                      <th className={`px-3 py-2 text-right font-bold uppercase ${pieMetric === 'sales' ? 'text-blue-600 bg-blue-50' : 'text-slate-400'}`}>金额 (CFA)</th>
                      <th className={`px-3 py-2 text-right font-bold uppercase ${pieMetric === 'quantity' ? 'text-green-600 bg-green-50' : 'text-slate-400'}`}>数量</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {sortedCategorySummary.map((item) => (
                      <tr key={item.name} onClick={() => { setSelectedCategory(item.name); setDrillDownMetric(pieMetric); }} className="hover:bg-blue-50 cursor-pointer transition-colors group">
                        <td className="px-3 py-3 font-bold text-slate-700">
                          <div className="flex items-center gap-2">
                             <div className="w-2 h-2 rounded-full" style={{backgroundColor: COLORS[sortedCategorySummary.indexOf(item) % COLORS.length]}}></div>
                             {item.name}
                          </div>
                        </td>
                        <td className={`px-3 py-3 text-right font-mono ${pieMetric === 'sales' ? 'font-black text-blue-700' : 'text-slate-600'}`}>{item.sales.toLocaleString()}</td>
                        <td className={`px-3 py-3 text-right font-mono ${pieMetric === 'quantity' ? 'font-black text-green-700' : 'text-slate-600'}`}>{item.quantity.toLocaleString()}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {selectedCategory && (
            <div className="absolute inset-0 bg-white/98 backdrop-blur-md z-20 p-6 flex flex-col animate-in slide-in-from-right duration-300 shadow-2xl overflow-hidden">
              <div className="flex items-center justify-between mb-6 border-b border-slate-100 pb-4">
                <div>
                  <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">Depth Analysis</h4>
                  <h3 className="text-2xl font-black text-slate-900">{selectedCategory}</h3>
                </div>
                <div className="flex items-center gap-2">
                   <div className="flex bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => setDrillDownMetric('sales')} className={`px-2 py-1 rounded-md text-[9px] font-bold transition-all ${drillDownMetric === 'sales' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400'}`}>按金额</button>
                    <button onClick={() => setDrillDownMetric('quantity')} className={`px-2 py-1 rounded-md text-[9px] font-bold transition-all ${drillDownMetric === 'quantity' ? 'bg-white shadow-sm text-green-600' : 'text-slate-400'}`}>按数量</button>
                  </div>
                  <button onClick={() => { setSelectedCategory(null); setSelectedCustomerInDrillDown(null); }} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg></button>
                </div>
              </div>

              <div className="flex-1 overflow-y-auto custom-scrollbar space-y-10 pb-20">
                <section>
                  <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">按客户分布 (点击客户名进行二次筛选)</h5>
                  <div className="min-h-[450px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={drillDownData.customers} layout="vertical" margin={{ left: 20, right: 40 }}>
                        <XAxis type="number" hide />
                        <YAxis 
                          dataKey="name" 
                          type="category" 
                          axisLine={false} 
                          tickLine={false} 
                          width={240} 
                          interval={0} 
                          tick={<CustomYAxisTick />} 
                        />
                        <Tooltip cursor={{fill: '#f8fafc'}} />
                        <Bar 
                          dataKey={drillDownMetric === 'sales' ? 'sales' : 'qty'} 
                          fill="#3b82f6" 
                          radius={[0, 6, 6, 0]} 
                          barSize={20}
                        >
                          {drillDownData.customers.map((entry, index) => (
                            <RechartsCell 
                              key={index} 
                              fill={COLORS[index % COLORS.length]} 
                              stroke={entry.name === selectedCustomerInDrillDown ? '#2563eb' : 'none'} 
                              strokeWidth={3} 
                            />
                          ))}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </section>

                <section>
                  <div className="flex items-center justify-between mb-4">
                    <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                       <span className="w-1.5 h-3 bg-blue-600 rounded-full"></span> 原始交易明细 (含多维下拉筛选)
                    </h5>
                    {(selectedCustomerInDrillDown || Object.values(localTableFilters).some(v => !!v)) && (
                      <button 
                        onClick={() => { 
                          setSelectedCustomerInDrillDown(null); 
                          setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' }); 
                        }} 
                        className="text-[10px] text-blue-600 font-bold hover:underline"
                      >
                        重置局部筛选
                      </button>
                    )}
                  </div>

                  <div className="overflow-x-auto rounded-xl border border-slate-100 bg-white shadow-sm min-h-[400px]">
                    <table className="min-w-full text-[11px]">
                      <thead className="bg-slate-50 border-b border-slate-100 sticky top-0 z-50">
                        <tr>
                          <FilterHeader label="出库单号" columnId="id" options={localFilterOptions.ids} />
                          <FilterHeader label="日期" columnId="date" options={localFilterOptions.dates} />
                          <FilterHeader label="客户" columnId="customer" options={localFilterOptions.customers} />
                          <FilterHeader label="物料名称" columnId="itemName" options={localFilterOptions.itemNames} />
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">单价</th>
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">数量</th>
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">金额 (CFA)</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {drillDownData.records.slice(0, 100).map((r, i) => (
                          <tr key={`${r.id}-${i}`} className="hover:bg-slate-50 transition-colors">
                            <td className="px-3 py-3 text-blue-600 font-mono font-bold">
                              <button onClick={() => onSelectOrderId(r.id)}>{r.id}</button>
                            </td>
                            <td className="px-3 py-3 text-slate-500">{r.date}</td>
                            <td className="px-3 py-3 text-slate-900 font-bold">{r.customer}</td>
                            <td className="px-3 py-3 text-slate-600 truncate max-w-[120px]">{r.itemName}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-500">{r.unitPrice.toLocaleString()}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-600">{r.quantity}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-900 font-bold">{r.totalAmount.toLocaleString()}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    {drillDownData.records.length === 0 && (
                      <div className="py-20 text-center text-slate-400 italic bg-slate-50/50">该组合筛选条件下暂无明细记录</div>
                    )}
                  </div>
                </section>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-6">🏆 销售员业绩排行 (CFA)</h3>
        <div className="h-[350px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical" margin={{ left: 20 }}>
              <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={80} tick={{fill: '#475569', fontWeight: 500}} />
              <Tooltip cursor={{fill: '#f8fafc'}} formatter={(v) => [`${v.toLocaleString()} CFA`, '总销售额']} />
              <Bar dataKey="value" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={24} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-indigo-900 text-white p-8 rounded-2xl shadow-xl overflow-hidden relative">
        <div className="relative z-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
            <div>
              <h3 className="text-xl font-bold flex items-center">✨ Gemini 智能商业洞察</h3>
              <p className="text-indigo-200 text-sm mt-1">AI 已根据您的当前筛选数据生成针对性建议 (金额以 CFA 为准)</p>
            </div>
            <button onClick={handleGetAIInsights} disabled={loading} className="bg-white text-indigo-900 px-6 py-2.5 rounded-full font-bold hover:bg-indigo-50 transition-all disabled:opacity-50 flex items-center justify-center min-w-[140px]">
              {loading ? '分析中...' : '生成最新洞察'}
            </button>
          </div>
          {aiText ? (
            <div className="bg-indigo-800/50 p-6 rounded-xl border border-indigo-700 text-indigo-50 whitespace-pre-wrap leading-relaxed animate-in fade-in">{aiText}</div>
          ) : (
            <div className="flex flex-col items-center justify-center py-12 border-2 border-dashed border-indigo-700 rounded-xl text-indigo-300">
              <span className="text-4xl mb-4">💡</span>
              <p>点击上方按钮，获取 AI 关于业绩、增长、瓶颈的深度分析建议</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Legend, Cell as RechartsCell
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';
import { getAIInsights } from '../services/geminiService';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [aiText, setAiText] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [drillDownMetric, setDrillDownMetric] = useState<'sales' | 'quantity'>('sales');
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [showSummaryTable, setShowSummaryTable] = useState(false);
  const [selectedCustomerInDrillDown, setSelectedCustomerInDrillDown] = useState<string | null>(null);

  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  const [localTableFilters, setLocalTableFilters] = useState({
    id: '',
    date: '',
    customer: '',
    itemName: ''
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);

  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleGetAIInsights = async () => {
    setLoading(true);
    const insights = await getAIInsights(summary);
    setAiText(insights || '');
    setLoading(false);
  };

  /** 
   * 统一品类分析数据源 
   * 严格按照当前选中的 pieMetric (销售额或数量) 进行降序排列
   */
  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return {
        name: cat.name,
        sales: cat.value,
        quantity: qtyItem ? qtyItem.value : 0
      };
    });

    return merged.sort((a, b) => {
      if (pieMetric === 'sales') return b.sales - a.sales;
      return b.quantity - a.quantity;
    });
  }, [summary, pieMetric]);

  /** 当前度量指标下的总量 */
  const currentTotal = useMemo(() => {
    return sortedCategorySummary.reduce((acc, cur) => acc + (pieMetric === 'sales' ? cur.sales : cur.quantity), 0);
  }, [sortedCategorySummary, pieMetric]);

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], customers: [], records: [] };

    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const customersMap = new Map<string, { sales: number; qty: number; orderIds: Set<string> }>();
    let records: SalesRecord[] = [];

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        const itemExisting = itemsMap.get(record.itemName) || { sales: 0, qty: 0 };
        itemsMap.set(record.itemName, {
          sales: itemExisting.sales + record.totalAmount,
          qty: itemExisting.qty + record.quantity
        });

        const customerExisting = customersMap.get(record.customer) || { sales: 0, qty: 0, orderIds: new Set() };
        customerExisting.orderIds.add(record.id);
        customersMap.set(record.customer, {
          sales: customerExisting.sales + record.totalAmount,
          qty: customerExisting.qty + record.quantity,
          orderIds: customerExisting.orderIds
        });

        records.push(record);
      }
    });

    const items = Array.from(itemsMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty, orderIds: Array.from(val.orderIds).sort() }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    if (selectedCustomerInDrillDown) records = records.filter(r => r.customer === selectedCustomerInDrillDown);
    if (localTableFilters.id) records = records.filter(r => r.id === localTableFilters.id);
    if (localTableFilters.date) records = records.filter(r => r.date >= localTableFilters.date);
    if (localTableFilters.customer) records = records.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.itemName) records = records.filter(r => r.itemName === localTableFilters.itemName);

    return { items, customers, records: records.sort((a, b) => b.date.localeCompare(a.date)) };
  }, [selectedCategory, filteredData, drillDownMetric, selectedCustomerInDrillDown, localTableFilters]);

  const localFilterOptions = useMemo(() => {
    if (!selectedCategory) return { ids: [], dates: [], customers: [], itemNames: [] };
    const ids = new Set<string>();
    const dates = new Set<string>();
    const customers = new Set<string>();
    const itemNames = new Set<string>();

    filteredData.forEach(r => {
      if (r.category === selectedCategory) {
        ids.add(r.id);
        dates.add(r.date);
        customers.add(r.customer);
        itemNames.add(r.itemName);
      }
    });

    return {
      ids: Array.from(ids).sort().reverse(),
      dates: Array.from(dates).sort().reverse(),
      customers: Array.from(customers).sort(),
      itemNames: Array.from(itemNames).sort()
    };
  }, [filteredData, selectedCategory]);

  const onPieClick = (data: any) => {
    setDrillDownMetric(pieMetric);
    if (selectedCategory === data.name) {
      setSelectedCategory(null);
      setSelectedCustomerInDrillDown(null);
    } else {
      setSelectedCategory(data.name);
      setSelectedCustomerInDrillDown(null);
      setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' });
    }
  };

  const CustomYAxisTick = (props: any) => {
    const { x, y, payload } = props;
    const isSelected = payload.value === selectedCustomerInDrillDown;
    return (
      <g transform={`translate(${x},${y})`}>
        <text
          x={-15} y={0} dy={4} textAnchor="end"
          fill={isSelected ? '#2563eb' : '#475569'}
          className={`text-[10px] font-bold cursor-pointer hover:fill-blue-600 transition-colors ${isSelected ? 'underline' : ''}`}
          onClick={() => setSelectedCustomerInDrillDown(payload.value === selectedCustomerInDrillDown ? null : payload.value)}
        >
          {payload.value}
        </text>
      </g>
    );
  };

  const FilterHeader = ({ label, columnId, options }: { label: string, columnId: keyof typeof localTableFilters, options: string[] }) => {
    const isActive = !!localTableFilters[columnId];
    return (
      <th className="px-3 py-2 text-left relative">
        <div className="flex items-center gap-1.5 group">
          <span className="font-bold text-slate-400 uppercase tracking-tighter">{label}</span>
          <button 
            onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)}
            className={`p-1 rounded hover:bg-slate-200 transition-all ${isActive ? 'text-blue-600' : 'text-slate-300'}`}
          >
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" clipRule="evenodd" />
            </svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-56 bg-white rounded-xl shadow-2xl border border-slate-200 z-[70] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2 border-b border-slate-50 bg-slate-50 flex justify-between items-center">
              <span className="text-[10px] font-bold text-slate-400 uppercase">筛选{label}</span>
              {isActive && (
                <button onClick={() => setLocalTableFilters(p => ({ ...p, [columnId]: '' }))} className="text-[9px] text-red-500 font-bold hover:underline">清除</button>
              )}
            </div>
            <div className="max-h-56 overflow-y-auto p-1 custom-scrollbar">
              {options.map(opt => (
                <button
                  key={opt}
                  onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }}
                  className={`w-full text-left px-3 py-2 rounded-lg text-[11px] transition-colors ${localTableFilters[columnId] === opt ? 'bg-blue-50 text-blue-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {opt}
                </button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow flex flex-col h-full">
      <div className="flex justify-between items-start mb-4">
        <div className="p-2 bg-blue-50 rounded-lg text-blue-600 text-xl">{icon}</div>
        <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">{title}</span>
      </div>
      <div className="text-2xl font-bold text-slate-900 mb-1">{value}</div>
      <div className="text-sm text-slate-500 mb-3">{sub}</div>
      {children}
    </div>
  );

  return (
    <div className="space-y-8">
      {/* KPI Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KpiCard title="总销售额" value={`${summary.totalSales.toLocaleString()} CFA`} sub="当前筛选总额" icon="💰" />
        <KpiCard title="总出库数量" value={summary.totalQuantity.toLocaleString()} sub="物料销售总数" icon="📦" />
        <KpiCard title="出库单号" value={`${summary.orderCount} 个单号`} sub="点击快速查看详情" icon="📑">
          <div className="mt-auto max-h-32 overflow-y-auto pr-2 custom-scrollbar border-t border-slate-50 pt-2">
            <div className="flex flex-wrap gap-1.5">
              {summary.orderIds.map(id => (
                <button key={id} onClick={() => onSelectOrderId(id)} className="inline-block px-1.5 py-0.5 bg-blue-50 text-blue-600 text-[10px] font-mono rounded border border-blue-100 hover:bg-blue-600 hover:text-white transition-colors">
                  {id}
                </button>
              ))}
            </div>
          </div>
        </KpiCard>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col min-h-[780px]">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center">📊 销售趋势综合分析</h3>
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button onClick={() => setShowCfa(!showCfa)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>金额</button>
              <button onClick={() => setShowQuantity(!showQuantity)} className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-green-600' : 'text-slate-400 hover:text-slate-600'}`}>数量</button>
            </div>
          </div>
          <div className="flex-1">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={summary.monthlyTrend} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
