               {showSummaryTable && <button onClick={() => setShowSummaryTable(false)} className="text-[10px] bg-blue-600 text-white font-bold px-3 py-1.5 rounded shadow-sm hover:bg-blue-700 transition-colors">← 返回图表</button>}
