              <div className="mt-1.5 flex items-center gap-2">
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{pieMetric === 'sales' ? '当前筛选总额:' : '当前筛选总量:'}</span>
                <span className={`text-sm font-black ${pieMetric === 'sales' ? 'text-blue-600' : 'text-green-600'}`}>
                   {currentTotal.toLocaleString()}{pieMetric === 'sales' ? ' CFA' : ''}
