          <div className="flex-1 flex flex-col overflow-hidden">
            {!showSummaryTable ? (
              <div className="flex-1 flex flex-col">
                <div className="flex-1">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie
                        data={sortedCategorySummary} 
