                  <div className="overflow-x-auto rounded-xl border border-slate-100 bg-white shadow-sm min-h-[400px]">
                    <table className="min-w-full text-[11px]">
                      <thead className="bg-slate-50 border-b border-slate-100 sticky top-0 z-50">
                        <tr>
                          <FilterHeader label="出库单号" columnId="id" options={localFilterOptions.ids} />
                          <FilterHeader label="日期" columnId="date" options={localFilterOptions.dates} />
                          <FilterHeader label="客户" columnId="customer" options={localFilterOptions.customers} />
                          <FilterHeader label="物料名称" columnId="itemName" options={localFilterOptions.itemNames} />
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">单价</th>
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">数量</th>
                          <th className="px-3 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">金额 (CFA)</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {drillDownData.records.slice(0, 100).map((r, i) => (
                          <tr key={`${r.id}-${i}`} className="hover:bg-slate-50 transition-colors">
                            <td className="px-3 py-3 text-blue-600 font-mono font-bold">
                              <button onClick={() => onSelectOrderId(r.id)}>{r.id}</button>
                            </td>
                            <td className="px-3 py-3 text-slate-500">{r.date}</td>
                            <td className="px-3 py-3 text-slate-900 font-bold">{r.customer}</td>
                            <td className="px-3 py-3 text-slate-600 truncate max-w-[120px]">{r.itemName}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-500">{r.unitPrice.toLocaleString()}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-600">{r.quantity}</td>
                            <td className="px-3 py-3 text-right font-mono text-slate-900 font-bold">{r.totalAmount.toLocaleString()}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    {drillDownData.records.length === 0 && (
                      <div className="py-20 text-center text-slate-400 italic bg-slate-50/50">该组合筛选条件下暂无明细记录</div>
                    )}
                  </div>
                </section>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-6">🏆 销售员业绩排行 (CFA)</h3>
        <div className="h-[350px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical" margin={{ left: 20 }}>
              <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={80} tick={{fill: '#475569', fontWeight: 500}} />
              <Tooltip cursor={{fill: '#f8fafc'}} formatter={(v) => [`${v.toLocaleString()} CFA`, '总销售额']} />
              <Bar dataKey="value" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={24} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-indigo-900 text-white p-8 rounded-2xl shadow-xl overflow-hidden relative">
        <div className="relative z-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
            <div>
              <h3 className="text-xl font-bold flex items-center">✨ Gemini 智能商业洞察</h3>
              <p className="text-indigo-200 text-sm mt-1">AI 已根据您的当前筛选数据生成针对性建议 (金额以 CFA 为准)</p>
