                          {drillDownData.records.slice(0, 30).map((r, i) => (
                            <tr key={`${r.id}-${i}`} className="hover:bg-slate-50 transition-colors">
                              <td className="px-2 py-2 text-blue-600 font-mono font-bold truncate">
                                <button onClick={() => onSelectOrderId(r.id)}>{r.id.split('-').pop()}</button>
                              </td>
                              <td className="px-2 py-2 text-slate-900 font-bold truncate max-w-[70px]">{r.customer}</td>
                              <td className="px-2 py-2 text-right font-mono text-slate-900 font-bold">{r.totalAmount.toLocaleString()}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                </section>
              </div>
            </div>
          )}
        </div>

        {/* 第三栏：销售员排行 */}
        <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 flex flex-col h-[680px]">
          <h3 className="text-base font-bold text-slate-800 mb-6 flex items-center justify-between">
             🏆 销售排行
             <span className="text-[10px] text-slate-400 font-normal">CFA 金额</span>
          </h3>
          <div className="flex-1 min-h-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={summary.salespersonPerformance} layout="vertical" margin={{ left: -10, right: 30 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
                <XAxis type="number" hide />
                <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={60} tick={{fill: '#475569', fontWeight: 600, fontSize: 10}} />
                <Tooltip cursor={{fill: '#f8fafc'}} formatter={(v) => [`${v.toLocaleString()} CFA`, '总销售额']} />
                <Bar dataKey="value" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={20}>
                   {summary.salespersonPerformance.map((entry, index) => (
                     <RechartsCell key={index} fill={COLORS[index % COLORS.length]} />
                   ))}
                   <LabelList dataKey="value" position="right" formatter={(v: any) => v.toLocaleString()} fill="#94a3b8" fontSize={9} fontWeight="bold" offset={8} />
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

      </div>

      {/* AI 洞察区域 */}
      <div className="bg-indigo-900 text-white p-6 rounded-2xl shadow-xl overflow-hidden relative">
        <div className="relative z-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-4">
            <div>
              <h3 className="text-lg font-bold flex items-center gap-2">✨ Gemini 智能商业洞察</h3>
              <p className="text-indigo-200 text-xs mt-0.5">基于当前筛选数据自动生成的深度建议</p>
            </div>
            <button onClick={handleGetAIInsights} disabled={loading} className="bg-white text-indigo-900 px-5 py-2 rounded-full font-bold text-sm hover:bg-indigo-50 transition-all disabled:opacity-50">
              {loading ? '分析中...' : '生成洞察'}
            </button>
          </div>
          {aiText ? (
            <div className="bg-indigo-800/50 p-5 rounded-xl border border-indigo-700 text-indigo-50 text-xs whitespace-pre-wrap leading-relaxed animate-in fade-in">{aiText}</div>
          ) : (
            <div className="flex flex-col items-center justify-center py-8 border-2 border-dashed border-indigo-700 rounded-xl text-indigo-300">
              <span className="text-3xl mb-2">💡</span>
              <p className="text-xs">点击按钮获取业绩增长、瓶颈识别与运营改进建议</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';
import { getAIInsights } from '../services/geminiService';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [aiText, setAiText] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [drillDownMetric, setDrillDownMetric] = useState<'sales' | 'quantity'>('sales');
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [showSummaryTable, setShowSummaryTable] = useState(false);
  const [selectedCustomerInDrillDown, setSelectedCustomerInDrillDown] = useState<string | null>(null);

  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  const [localTableFilters, setLocalTableFilters] = useState({
    id: '',
    date: '',
    customer: '',
    itemName: ''
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);

  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleGetAIInsights = async () => {
    setLoading(true);
    const insights = await getAIInsights(summary);
    setAiText(insights || '');
    setLoading(false);
  };

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return {
        name: cat.name,
        sales: cat.value,
        quantity: qtyItem ? qtyItem.value : 0
      };
    });

    return merged.sort((a, b) => {
      if (pieMetric === 'sales') return b.sales - a.sales;
      return b.quantity - a.quantity;
    });
  }, [summary, pieMetric]);

  const globalTotals = useMemo(() => {
    return sortedCategorySummary.reduce((acc, cur) => {
      acc.sales += cur.sales;
      acc.quantity += cur.quantity;
      return acc;
    }, { sales: 0, quantity: 0 });
  }, [sortedCategorySummary]);

  const currentTotal = pieMetric === 'sales' ? globalTotals.sales : globalTotals.quantity;

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], customers: [], records: [], drillDownTotal: 0 };

    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const customersMap = new Map<string, { sales: number; qty: number; orderIds: Set<string> }>();
    let records: SalesRecord[] = [];
    let drillDownTotal = 0;

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        const itemExisting = itemsMap.get(record.itemName) || { sales: 0, qty: 0 };
        itemsMap.set(record.itemName, {
          sales: itemExisting.sales + record.totalAmount,
          qty: itemExisting.qty + record.quantity
        });

        const customerExisting = customersMap.get(record.customer) || { sales: 0, qty: 0, orderIds: new Set() };
        customerExisting.orderIds.add(record.id);
        customersMap.set(record.customer, {
          sales: customerExisting.sales + record.totalAmount,
          qty: customerExisting.qty + record.quantity,
          orderIds: customerExisting.orderIds
        });

        records.push(record);
        drillDownTotal += (drillDownMetric === 'sales' ? record.totalAmount : record.quantity);
      }
    });

    const items = Array.from(itemsMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ 
        name, 
        sales: val.sales, 
        qty: val.qty, 
        orderIds: Array.from(val.orderIds).sort(),
        percentage: drillDownTotal > 0 ? (((drillDownMetric === 'sales' ? val.sales : val.qty) / drillDownTotal) * 100).toFixed(1) + '%' : '0%'
      }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    if (selectedCustomerInDrillDown) records = records.filter(r => r.customer === selectedCustomerInDrillDown);
    if (localTableFilters.id) records = records.filter(r => r.id === localTableFilters.id);
    if (localTableFilters.date) records = records.filter(r => r.date >= localTableFilters.date);
    if (localTableFilters.customer) records = records.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.itemName) records = records.filter(r => r.itemName === localTableFilters.itemName);

    return { items, customers, records: records.sort((a, b) => b.date.localeCompare(a.date)), drillDownTotal };
  }, [selectedCategory, filteredData, drillDownMetric, selectedCustomerInDrillDown, localTableFilters]);

  const localFilterOptions = useMemo(() => {
    if (!selectedCategory) return { ids: [], dates: [], customers: [], itemNames: [] };
    const ids = new Set<string>();
    const dates = new Set<string>();
    const customers = new Set<string>();
    const itemNames = new Set<string>();

    filteredData.forEach(r => {
      if (r.category === selectedCategory) {
        ids.add(r.id);
        dates.add(r.date);
        customers.add(r.customer);
        itemNames.add(r.itemName);
      }
    });

    return {
      ids: Array.from(ids).sort().reverse(),
      dates: Array.from(dates).sort().reverse(),
      customers: Array.from(customers).sort(),
      itemNames: Array.from(itemNames).sort()
    };
  }, [filteredData, selectedCategory]);

  const handleCategorySelection = (categoryName: string) => {
    setDrillDownMetric(pieMetric);
    if (selectedCategory === categoryName) {
      setSelectedCategory(null);
      setSelectedCustomerInDrillDown(null);
    } else {
      setSelectedCategory(categoryName);
      setSelectedCustomerInDrillDown(null);
      setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' });
    }
  };

  const onPieClick = (data: any) => {
    handleCategorySelection(data.name);
  };

  const CustomYAxisTick = (props: any) => {
    const { x, y, payload } = props;
    const isSelected = payload.value === selectedCustomerInDrillDown;
    return (
      <g transform={`translate(${x},${y})`}>
        <text
          x={-10} y={0} dy={4} textAnchor="end"
          fill={isSelected ? '#2563eb' : '#475569'}
          className={`text-[9px] font-bold cursor-pointer hover:fill-blue-600 transition-colors ${isSelected ? 'underline' : ''}`}
          onClick={() => setSelectedCustomerInDrillDown(payload.value === selectedCustomerInDrillDown ? null : payload.value)}
        >
          {payload.value.length > 10 ? payload.value.substring(0, 8) + '...' : payload.value}
        </text>
      </g>
    );
  };

  const FilterHeader = ({ label, columnId, options }: { label: string, columnId: keyof typeof localTableFilters, options: string[] }) => {
    const isActive = !!localTableFilters[columnId];
    return (
      <th className="px-2 py-2 text-left relative min-w-[70px]">
        <div className="flex items-center gap-1 group">
          <span className="font-bold text-slate-400 uppercase tracking-tighter text-[9px] whitespace-nowrap">{label}</span>
          <button 
            onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)}
            className={`p-0.5 rounded hover:bg-slate-200 transition-all ${isActive ? 'text-blue-600' : 'text-slate-300'}`}
          >
            <svg className="w-2.5 h-2.5" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" clipRule="evenodd" />
            </svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-48 bg-white rounded-xl shadow-2xl border border-slate-200 z-[3000] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2 border-b border-slate-50 bg-slate-50 flex justify-between items-center">
              <span className="text-[9px] font-bold text-slate-400 uppercase">筛选{label}</span>
              {isActive && (
                <button onClick={() => setLocalTableFilters(p => ({ ...p, [columnId]: '' }))} className="text-[8px] text-red-500 font-bold hover:underline">清除</button>
              )}
            </div>
            <div className="max-h-48 overflow-y-auto p-1 custom-scrollbar">
              {options.map(opt => (
                <button
                  key={opt}
                  onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }}
                  className={`w-full text-left px-2 py-1.5 rounded-lg text-[10px] transition-colors ${localTableFilters[columnId] === opt ? 'bg-blue-50 text-blue-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {opt}
                </button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  const CustomPieTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const data = payload[0].payload;
      const salesPct = globalTotals.sales > 0 ? (data.sales / globalTotals.sales * 100).toFixed(1) : "0.0";
      const qtyPct = globalTotals.quantity > 0 ? (data.quantity / globalTotals.quantity * 100).toFixed(1) : "0.0";
      const color = payload[0].payload.fill || '#3b82f6';
      const isSalesMode = pieMetric === 'sales';

      return (
        <div className="bg-white/98 backdrop-blur-xl p-3.5 rounded-2xl shadow-2xl border border-slate-100 min-w-[240px] max-w-[280px] animate-in fade-in zoom-in duration-200 z-[1000]">
          <div className="flex items-center gap-2 mb-2 border-b border-slate-100 pb-1.5">
            <div className="w-3.5 h-3.5 rounded-full shadow-inner flex-shrink-0" style={{ backgroundColor: color }}></div>
            <div className="flex flex-col min-w-0">
              <span className="text-base font-black text-slate-900 leading-tight truncate">{data.name}</span>
            </div>
          </div>

          <div className="space-y-2">
            <div className={`p-2 rounded-xl border transition-all duration-300 ${isSalesMode ? 'bg-blue-50 border-blue-100' : 'bg-slate-50 border-slate-100'}`}>
              <div className="flex justify-between items-center mb-0.5">
                <span className={`text-[8px] font-bold uppercase ${isSalesMode ? 'text-blue-600' : 'text-slate-500'}`}>销售金额 (CFA)</span>
              </div>
              <div className="flex justify-between items-end">
                <span className={`font-mono font-black ${isSalesMode ? 'text-lg text-blue-700' : 'text-xs text-slate-700'}`}>{data.sales.toLocaleString()}</span>
                <span className={`text-[9px] font-bold ${isSalesMode ? 'text-blue-500' : 'text-slate-400'}`}>份额 {salesPct}%</span>
              </div>
            </div>

            <div className={`p-2 rounded-xl border transition-all duration-300 ${!isSalesMode ? 'bg-green-50 border-green-100' : 'bg-slate-50 border-slate-100'}`}>
              <div className="flex justify-between items-center mb-0.5">
                <span className={`text-[8px] font-bold uppercase ${!isSalesMode ? 'text-green-600' : 'text-slate-500'}`}>出库数量</span>
              </div>
              <div className="flex justify-between items-end">
                <span className={`font-mono font-black ${!isSalesMode ? 'text-lg text-green-700' : 'text-xs text-slate-700'}`}>{data.quantity.toLocaleString()}</span>
                <span className={`text-[9px] font-bold ${!isSalesMode ? 'text-green-500' : 'text-slate-400'}`}>份额 {qtyPct}%</span>
              </div>
            </div>
          </div>
        </div>
      );
    }
    return null;
  };

  const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
    <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow flex flex-col h-full">
      <div className="flex justify-between items-start mb-2">
        <div className="p-1.5 bg-blue-50 rounded-lg text-blue-600 text-lg">{icon}</div>
        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{title}</span>
      </div>
      <div className="text-xl font-bold text-slate-900 mb-0.5">{value}</div>
      <div className="text-[10px] text-slate-500 mb-2">{sub}</div>
      {children}
    </div>
  );

  return (
    <div className="space-y-6">
      {/* KPI Section */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KpiCard title="总销售额" value={`${summary.totalSales.toLocaleString()} CFA`} sub="当前筛选总额" icon="💰" />
        <KpiCard title="总出库数量" value={summary.totalQuantity.toLocaleString()} sub="物料销售总数" icon="📦" />
        <KpiCard title="出库单号" value={`${summary.orderCount} 个单号`} sub="点击详情" icon="📑">
          <div className="mt-auto max-h-24 overflow-y-auto pr-1 custom-scrollbar border-t border-slate-50 pt-1.5">
            <div className="flex flex-wrap gap-1">
              {summary.orderIds.map(id => (
                <button key={id} onClick={() => onSelectOrderId(id)} className="inline-block px-1 py-0.5 bg-blue-50 text-blue-600 text-[9px] font-mono rounded border border-blue-100 hover:bg-blue-600 hover:text-white transition-colors">
                  {id}
                </button>
              ))}
            </div>
          </div>
        </KpiCard>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* 第一栏：销售趋势 */}
        <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 flex flex-col h-[680px]">
          <div className="flex items-center justify-between mb-6 gap-2">
            <h3 className="text-base font-bold text-slate-800 flex items-center">📊 销售趋势</h3>
            <div className="flex bg-slate-100 p-0.5 rounded-lg">
              <button onClick={() => setShowCfa(!showCfa)} className={`px-2 py-1 rounded-md text-[10px] font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400'}`}>金额</button>
              <button onClick={() => setShowQuantity(!showQuantity)} className={`px-2 py-1 rounded-md text-[10px] font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-green-600' : 'text-slate-400'}`}>数量</button>
            </div>
          </div>
          <div className="flex-1 min-h-0">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={summary.monthlyTrend} margin={{ top: 5, right: 10, left: -20, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorQty" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10}} dy={5} />
                <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#3b82f6', fontSize: 9}} />
                <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 9}} />
                <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" stroke="#3b82f6" strokeWidth={2} fillOpacity={1} fill="url(#colorSales)" />}
                {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" stroke="#10b981" strokeWidth={2} fillOpacity={1} fill="url(#colorQty)" />}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* 第二栏：品类分布与下钻 - 优化动态图例区布局 */}
        <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 relative flex flex-col h-[680px] overflow-hidden">
          <div className="flex justify-between items-center mb-4 relative z-10">
            <div className="flex flex-col">
              <div className="flex items-center gap-1.5">
                {!showSummaryTable && (
                  <button onClick={() => setShowSummaryTable(true)} className="p-1 bg-blue-50 text-blue-600 rounded-md hover:bg-blue-600 hover:text-white transition-all border border-blue-100" title="列表视图">
                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 10h16M4 14h16M4 18h16" /></svg>
                  </button>
                )}
                <h3 className="text-base font-bold text-slate-800">🧩 品类分布</h3>
              </div>
            </div>
            {!showSummaryTable && (
              <div className="flex bg-slate-100 p-0.5 rounded-lg">
                <button onClick={() => setPieMetric('sales')} className={`px-2 py-1 rounded-md text-[10px] font-bold transition-all ${pieMetric === 'sales' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400'}`}>金额</button>
                <button onClick={() => setPieMetric('quantity')} className={`px-2 py-1 rounded-md text-[10px] font-bold transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-sm text-green-600' : 'text-slate-400'}`}>数量</button>
              </div>
            )}
            {showSummaryTable && <button onClick={() => setShowSummaryTable(false)} className="text-[9px] bg-blue-600 text-white font-bold px-2 py-1 rounded shadow-sm">← 返回图表</button>}
          </div>

          <div className="flex-1 flex flex-col min-h-0 relative">
            {!showSummaryTable ? (
              <>
                {/* 饼图中心数值叠加 */}
                <div className="absolute top-[40%] left-1/2 -translate-x-1/2 -translate-y-1/2 text-center pointer-events-none z-0">
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">总计 ({pieMetric === 'sales' ? 'CFA' : '数量'})</p>
                  <p className={`text-xl font-black ${pieMetric === 'sales' ? 'text-blue-600' : 'text-green-600'}`}>
                    {currentTotal.toLocaleString()}
                  </p>
                </div>

                {/* 饼图容器：高度固定部分，留出空间给下方的水平图例 */}
                <div className="h-[420px] w-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie
                        data={sortedCategorySummary} 
                        cx="50%" cy="50%" 
                        innerRadius={110} 
                        outerRadius={180} 
                        paddingAngle={2}
                        dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} 
                        onClick={onPieClick} 
                        stroke="none"
                        style={{ cursor: 'pointer', outline: 'none' }}
                      >
                        {sortedCategorySummary.map((entry, index) => (
                          <RechartsCell key={index} fill={COLORS[index % COLORS.length]} opacity={selectedCategory && selectedCategory !== entry.name ? 0.3 : 1} />
                        ))}
                      </Pie>
                      <Tooltip content={<CustomPieTooltip />} wrapperStyle={{ zIndex: 1000 }} />
                    </PieChart>
                  </ResponsiveContainer>
                </div>

                {/* 独立动态图例区 (Dynamic Legend Area) - 从左到右排列，支持内滚 */}
                <div className="flex-1 mt-4 overflow-hidden flex flex-col">
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2 px-1">点击品类名称查看详情</p>
                  <div className="flex-1 overflow-y-auto custom-scrollbar pr-2">
                    <div className="flex flex-wrap gap-2 pb-4">
                      {sortedCategorySummary.map((item, index) => {
                        const val = pieMetric === 'sales' ? item.sales : item.quantity;
                        const percentage = currentTotal > 0 ? (val / currentTotal * 100).toFixed(1) : "0.0";
                        const isSelected = selectedCategory === item.name;

                        return (
                          <button
                            key={item.name}
                            onClick={() => handleCategorySelection(item.name)}
                            className={`flex items-center gap-2 px-3 py-1.5 rounded-full border transition-all duration-200 group ${isSelected ? 'bg-blue-600 border-blue-600 shadow-lg shadow-blue-100' : 'bg-slate-50 border-slate-100 hover:bg-white hover:border-blue-300 hover:shadow-md'}`}
                          >
                            <div className="w-2 h-2 rounded-full flex-shrink-0" style={{ backgroundColor: isSelected ? '#fff' : COLORS[index % COLORS.length] }}></div>
                            <span className={`text-[10px] font-bold truncate max-w-[100px] ${isSelected ? 'text-white' : 'text-slate-700'}`}>{item.name}</span>
                            <span className={`text-[9px] font-black font-mono ${isSelected ? 'text-blue-100' : 'text-slate-400 group-hover:text-blue-600'}`}>{percentage}%</span>
                          </button>
                        );
                      })}
                    </div>
                  </div>
                </div>
              </>
            ) : (
              <div className="flex-1 overflow-y-auto custom-scrollbar bg-slate-50/30 rounded-xl border border-slate-100">
                <table className="min-w-full text-[10px] text-left">
                  <thead className="bg-white sticky top-0 z-10 shadow-sm">
                    <tr>
                      <th className="px-3 py-2 text-slate-400 font-bold uppercase">品类</th>
                      <th className={`px-3 py-2 text-right font-bold ${pieMetric === 'sales' ? 'text-blue-600' : 'text-slate-400'}`}>数据</th>
                      <th className="px-3 py-2 text-right text-slate-400 font-bold w-16">占比</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 bg-white">
                    {sortedCategorySummary.map((item, idx) => {
                      const val = pieMetric === 'sales' ? item.sales : item.quantity;
                      const percentage = currentTotal > 0 ? (val / currentTotal * 100) : 0;
                      return (
                        <tr key={item.name} onClick={() => handleCategorySelection(item.name)} className="hover:bg-blue-50 cursor-pointer transition-colors group">
                          <td className="px-3 py-2.5 font-bold text-slate-700">
                            <div className="flex items-center gap-1.5">
                               <div className="w-1.5 h-1.5 rounded-full flex-shrink-0" style={{backgroundColor: COLORS[idx % COLORS.length]}}></div>
                               <span className="truncate max-w-[100px]">{item.name}</span>
                            </div>
                          </td>
                          <td className={`px-3 py-2.5 text-right font-mono ${pieMetric === 'sales' ? 'font-bold text-blue-700' : 'text-slate-600'}`}>{val.toLocaleString()}</td>
                          <td className="px-3 py-2.5 text-right font-mono text-slate-500">{percentage.toFixed(1)}%</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {selectedCategory && (
            <div className="absolute inset-0 bg-white/98 backdrop-blur-md z-[2000] p-4 flex flex-col animate-in slide-in-from-right duration-300 shadow-2xl overflow-hidden">
              <div className="flex items-center justify-between mb-4 border-b border-slate-100 pb-2">
                <div className="min-w-0">
                  <h4 className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">下钻分析详情</h4>
                  <h3 className="text-base font-black text-slate-900 truncate">{selectedCategory}</h3>
                </div>
                <button onClick={() => { setSelectedCategory(null); setSelectedCustomerInDrillDown(null); }} className="p-1 hover:bg-slate-100 rounded-full text-slate-400"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg></button>
              </div>

              <div className="flex-1 overflow-y-auto custom-scrollbar space-y-6 pb-12">
                <section>
                  <h5 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 flex items-center justify-between">
                    <span>客户贡献 Top 排行</span>
                    <div className="flex bg-slate-100 p-0.5 rounded-lg">
                      <button onClick={() => setDrillDownMetric('sales')} className={`px-1.5 py-0.5 rounded text-[8px] font-bold ${drillDownMetric === 'sales' ? 'bg-white text-blue-600' : 'text-slate-400'}`}>金额</button>
                      <button onClick={() => setDrillDownMetric('quantity')} className={`px-1.5 py-0.5 rounded text-[8px] font-bold ${drillDownMetric === 'quantity' ? 'bg-white text-green-600' : 'text-slate-400'}`}>数量</button>
                    </div>
                  </h5>
                  <div className="h-[220px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={drillDownData.customers.slice(0, 6)} layout="vertical" margin={{ left: 0, right: 35 }}>
                        <XAxis type="number" hide />
                        <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={75} interval={0} tick={<CustomYAxisTick />} />
                        <Tooltip cursor={{fill: '#f8fafc'}} />
                        <Bar dataKey={drillDownMetric === 'sales' ? 'sales' : 'qty'} fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={10}>
                          {drillDownData.customers.map((entry, index) => (
                            <RechartsCell key={index} fill={COLORS[index % COLORS.length]} />
                          ))}
                          <LabelList dataKey="percentage" position="right" fill="#94a3b8" fontSize={8} fontWeight="bold" offset={5} />
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </section>

                <section>
                  <h5 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">历史交易明细</h5>
                  <div className="rounded-xl border border-slate-100 bg-white overflow-hidden shadow-sm">
                    <div className="overflow-x-auto max-h-[220px] custom-scrollbar">
                      <table className="min-w-full text-[9px]">
                        <thead className="bg-slate-50 border-b border-slate-100 sticky top-0 z-10">
                          <tr>
                            <FilterHeader label="单号" columnId="id" options={localFilterOptions.ids} />
                            <FilterHeader label="客户" columnId="customer" options={localFilterOptions.customers} />
                            <th className="px-2 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter">金额</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
                          {drillDownData.records.slice(0, 30).map((r, i) => (
                            <tr key={`${r.id}-${i}`} className="hover:bg-slate-50 transition-colors">
                              <td className="px-2 py-2 text-blue-600 font-mono font-bold truncate">
                                <button onClick={() => onSelectOrderId(r.id)}>{r.id.split('-').pop()}</button>
                              </td>
                              <td className="px-2 py-2 text-slate-900 font-bold truncate max-w-[70px]">{r.customer}</td>
                              <td className="px-2 py-2 text-right font-mono text-slate-900 font-bold">{r.totalAmount.toLocaleString()}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                </section>
              </div>
            </div>
          )}
        </div>

        {/* 第三栏：销售员排行 */}
        <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 flex flex-col h-[680px]">
          <h3 className="text-base font-bold text-slate-800 mb-6 flex items-center justify-between">
             🏆 销售排行
             <span className="text-[10px] text-slate-400 font-normal">CFA 金额</span>
          </h3>
          <div className="flex-1 min-h-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={summary.salespersonPerformance} layout="vertical" margin={{ left: -10, right: 30 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
                <XAxis type="number" hide />
                <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={60} tick={{fill: '#475569', fontWeight: 600, fontSize: 10}} />
                <Tooltip cursor={{fill: '#f8fafc'}} formatter={(v) => [`${v.toLocaleString()} CFA`, '总销售额']} />
                <Bar dataKey="value" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={20}>
                   {summary.salespersonPerformance.map((entry, index) => (
                     <RechartsCell key={index} fill={COLORS[index % COLORS.length]} />
                   ))}
                   <LabelList dataKey="value" position="right" formatter={(v: any) => v.toLocaleString()} fill="#94a3b8" fontSize={9} fontWeight="bold" offset={8} />
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

      </div>

      {/* AI 洞察区域 */}
      <div className="bg-indigo-900 text-white p-6 rounded-2xl shadow-xl overflow-hidden relative">
        <div className="relative z-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-4">
            <div>
              <h3 className="text-lg font-bold flex items-center gap-2">✨ Gemini 智能商业洞察</h3>
              <p className="text-indigo-200 text-xs mt-0.5">基于当前筛选数据自动生成的深度建议</p>
            </div>
            <button onClick={handleGetAIInsights} disabled={loading} className="bg-white text-indigo-900 px-5 py-2 rounded-full font-bold text-sm hover:bg-indigo-50 transition-all disabled:opacity-50">
              {loading ? '分析中...' : '生成洞察'}
            </button>
          </div>
          {aiText ? (
            <div className="bg-indigo-800/50 p-5 rounded-xl border border-indigo-700 text-indigo-50 text-xs whitespace-pre-wrap leading-relaxed animate-in fade-in">{aiText}</div>
          ) : (
            <div className="flex flex-col items-center justify-center py-8 border-2 border-dashed border-indigo-700 rounded-xl text-indigo-300">
              <span className="text-3xl mb-2">💡</span>
              <p className="text-xs">点击按钮获取业绩增长、瓶颈识别与运营改进建议</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';
import { getAIInsights } from '../services/geminiService';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [aiText, setAiText] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [drillDownMetric, setDrillDownMetric] = useState<'sales' | 'quantity'>('sales');
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [showSummaryTable, setShowSummaryTable] = useState(false);
  const [selectedCustomerInDrillDown, setSelectedCustomerInDrillDown] = useState<string | null>(null);

  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  const [localTableFilters, setLocalTableFilters] = useState({
    id: '',
    date: '',
    customer: '',
    itemName: ''
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);

  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleGetAIInsights = async () => {
    setLoading(true);
    const insights = await getAIInsights(summary);
    setAiText(insights || '');
    setLoading(false);
  };

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return {
        name: cat.name,
        sales: cat.value,
        quantity: qtyItem ? qtyItem.value : 0
      };
    });

    return merged.sort((a, b) => {
      if (pieMetric === 'sales') return b.sales - a.sales;
      return b.quantity - a.quantity;
    });
  }, [summary, pieMetric]);

  const globalTotals = useMemo(() => {
    return sortedCategorySummary.reduce((acc, cur) => {
      acc.sales += cur.sales;
      acc.quantity += cur.quantity;
      return acc;
    }, { sales: 0, quantity: 0 });
  }, [sortedCategorySummary]);

  const currentTotal = pieMetric === 'sales' ? globalTotals.sales : globalTotals.quantity;

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], customers: [], records: [], drillDownTotal: 0 };

    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const customersMap = new Map<string, { sales: number; qty: number; orderIds: Set<string> }>();
    let records: SalesRecord[] = [];
    let drillDownTotal = 0;

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        const itemExisting = itemsMap.get(record.itemName) || { sales: 0, qty: 0 };
        itemsMap.set(record.itemName, {
          sales: itemExisting.sales + record.totalAmount,
          qty: itemExisting.qty + record.quantity
        });

        const customerExisting = customersMap.get(record.customer) || { sales: 0, qty: 0, orderIds: new Set() };
        customerExisting.orderIds.add(record.id);
        customersMap.set(record.customer, {
          sales: customerExisting.sales + record.totalAmount,
          qty: customerExisting.qty + record.quantity,
          orderIds: customerExisting.orderIds
        });

        records.push(record);
        drillDownTotal += (drillDownMetric === 'sales' ? record.totalAmount : record.quantity);
      }
    });

    const items = Array.from(itemsMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ 
        name, 
        sales: val.sales, 
        qty: val.qty, 
        orderIds: Array.from(val.orderIds).sort(),
        percentage: drillDownTotal > 0 ? (((drillDownMetric === 'sales' ? val.sales : val.qty) / drillDownTotal) * 100).toFixed(1) + '%' : '0%'
      }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    if (selectedCustomerInDrillDown) records = records.filter(r => r.customer === selectedCustomerInDrillDown);
    if (localTableFilters.id) records = records.filter(r => r.id === localTableFilters.id);
    if (localTableFilters.date) records = records.filter(r => r.date >= localTableFilters.date);
    if (localTableFilters.customer) records = records.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.itemName) records = records.filter(r => r.itemName === localTableFilters.itemName);

    return { items, customers, records: records.sort((a, b) => b.date.localeCompare(a.date)), drillDownTotal };
  }, [selectedCategory, filteredData, drillDownMetric, selectedCustomerInDrillDown, localTableFilters]);

  const localFilterOptions = useMemo(() => {
    if (!selectedCategory) return { ids: [], dates: [], customers: [], itemNames: [] };
    const ids = new Set<string>();
    const dates = new Set<string>();
    const customers = new Set<string>();
    const itemNames = new Set<string>();

    filteredData.forEach(r => {
      if (r.category === selectedCategory) {
        ids.add(r.id);
        dates.add(r.date);
        customers.add(r.customer);
        itemNames.add(r.itemName);
      }
    });

    return {
      ids: Array.from(ids).sort().reverse(),
      dates: Array.from(dates).sort().reverse(),
      customers: Array.from(customers).sort(),
      itemNames: Array.from(itemNames).sort()
    };
  }, [filteredData, selectedCategory]);

  const handleCategorySelection = (categoryName: string) => {
    setDrillDownMetric(pieMetric);
    if (selectedCategory === categoryName) {
      setSelectedCategory(null);
      setSelectedCustomerInDrillDown(null);
    } else {
      setSelectedCategory(categoryName);
      setSelectedCustomerInDrillDown(null);
      setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' });
    }
  };

  const onPieClick = (data: any) => {
    handleCategorySelection(data.name);
  };

  const CustomYAxisTick = (props: any) => {
    const { x, y, payload } = props;
    const isSelected = payload.value === selectedCustomerInDrillDown;
    return (
      <g transform={`translate(${x},${y})`}>
        <text
          x={-10} y={0} dy={4} textAnchor="end"
          fill={isSelected ? '#2563eb' : '#475569'}
          className={`text-[9px] font-bold cursor-pointer hover:fill-blue-600 transition-colors ${isSelected ? 'underline' : ''}`}
          onClick={() => setSelectedCustomerInDrillDown(payload.value === selectedCustomerInDrillDown ? null : payload.value)}
        >
          {payload.value.length > 10 ? payload.value.substring(0, 8) + '...' : payload.value}
        </text>
      </g>
    );
  };

  const FilterHeader = ({ label, columnId, options }: { label: string, columnId: keyof typeof localTableFilters, options: string[] }) => {
    const isActive = !!localTableFilters[columnId];
    return (
      <th className="px-2 py-2 text-left relative min-w-[70px]">
        <div className="flex items-center gap-1 group">
          <span className="font-bold text-slate-400 uppercase tracking-tighter text-[9px] whitespace-nowrap">{label}</span>
          <button 
            onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)}
            className={`p-0.5 rounded hover:bg-slate-200 transition-all ${isActive ? 'text-blue-600' : 'text-slate-300'}`}
          >
            <svg className="w-2.5 h-2.5" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" clipRule="evenodd" />
            </svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-48 bg-white rounded-xl shadow-2xl border border-slate-200 z-[3000] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2 border-b border-slate-50 bg-slate-50 flex justify-between items-center">
              <span className="text-[9px] font-bold text-slate-400 uppercase">筛选{label}</span>
              {isActive && (
                <button onClick={() => setLocalTableFilters(p => ({ ...p, [columnId]: '' }))} className="text-[8px] text-red-500 font-bold hover:underline">清除</button>
              )}
            </div>
            <div className="max-h-48 overflow-y-auto p-1 custom-scrollbar">
              {options.map(opt => (
                <button
                  key={opt}
                  onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }}
                  className={`w-full text-left px-2 py-1.5 rounded-lg text-[10px] transition-colors ${localTableFilters[columnId] === opt ? 'bg-blue-50 text-blue-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {opt}
                </button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  const CustomPieTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const data = payload[0].payload;
      const salesPct = globalTotals.sales > 0 ? (data.sales / globalTotals.sales * 100).toFixed(1) : "0.0";
      const qtyPct = globalTotals.quantity > 0 ? (data.quantity / globalTotals.quantity * 100).toFixed(1) : "0.0";
      const color = payload[0].payload.fill || '#3b82f6';
      const isSalesMode = pieMetric === 'sales';

      return (
        <div className="bg-white/98 backdrop-blur-xl p-3.5 rounded-2xl shadow-2xl border border-slate-100 min-w-[240px] max-w-[280px] animate-in fade-in zoom-in duration-200 z-[1000]">
          <div className="flex items-center gap-2 mb-2 border-b border-slate-100 pb-1.5">
            <div className="w-3.5 h-3.5 rounded-full shadow-inner flex-shrink-0" style={{ backgroundColor: color }}></div>
            <div className="flex flex-col min-w-0">
              <span className="text-base font-black text-slate-900 leading-tight truncate">{data.name}</span>
            </div>
          </div>

          <div className="space-y-2">
            <div className={`p-2 rounded-xl border transition-all duration-300 ${isSalesMode ? 'bg-blue-50 border-blue-100' : 'bg-slate-50 border-slate-100'}`}>
              <div className="flex justify-between items-center mb-0.5">
                <span className={`text-[8px] font-bold uppercase ${isSalesMode ? 'text-blue-600' : 'text-slate-500'}`}>销售金额 (CFA)</span>
              </div>
              <div className="flex justify-between items-end">
                <span className={`font-mono font-black ${isSalesMode ? 'text-lg text-blue-700' : 'text-xs text-slate-700'}`}>{data.sales.toLocaleString()}</span>
                <span className={`text-[9px] font-bold ${isSalesMode ? 'text-blue-500' : 'text-slate-400'}`}>份额 {salesPct}%</span>
              </div>
            </div>

            <div className={`p-2 rounded-xl border transition-all duration-300 ${!isSalesMode ? 'bg-green-50 border-green-100' : 'bg-slate-50 border-slate-100'}`}>
              <div className="flex justify-between items-center mb-0.5">
                <span className={`text-[8px] font-bold uppercase ${!isSalesMode ? 'text-green-600' : 'text-slate-500'}`}>出库数量</span>
              </div>
              <div className="flex justify-between items-end">
                <span className={`font-mono font-black ${!isSalesMode ? 'text-lg text-green-700' : 'text-xs text-slate-700'}`}>{data.quantity.toLocaleString()}</span>
                <span className={`text-[9px] font-bold ${!isSalesMode ? 'text-green-500' : 'text-slate-400'}`}>份额 {qtyPct}%</span>
              </div>
            </div>
          </div>
        </div>
      );
    }
    return null;
  };

  const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
    <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow flex flex-col h-full">
      <div className="flex justify-between items-start mb-2">
