                        <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={75} interval={0} tick={<CustomYAxisTick />} />
                        <Tooltip cursor={{fill: '#f8fafc'}} />
                        <Bar dataKey={drillDownMetric === 'sales' ? 'sales' : 'qty'} fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={10}>
                          {drillDownData.customers.map((entry, index) => (
                            <RechartsCell key={index} fill={COLORS[index % COLORS.length]} />
                          ))}
                          <LabelList dataKey="percentage" position="right" fill="#94a3b8" fontSize={8} fontWeight="bold" offset={5} />
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </section>

                <section>
                  <h5 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">历史交易明细</h5>
                  <div className="rounded-xl border border-slate-100 bg-white overflow-hidden shadow-sm">
                    <div className="overflow-x-auto max-h-[320px] custom-scrollbar">
                      <table className="min-w-full text-[9px] border-collapse">
                        <thead className="bg-slate-50 border-b border-slate-100 sticky top-0 z-10">
                          <tr>
                            <FilterHeader label="出库单号" columnId="id" options={localFilterOptions.ids} />
                            <FilterHeader label="客户名" columnId="customer" options={localFilterOptions.customers} />
                            <FilterHeader label="物料名称" columnId="itemName" options={localFilterOptions.itemNames} />
                            <th className="px-2 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter whitespace-nowrap">单价</th>
                            <th className="px-2 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter whitespace-nowrap">数量</th>
                            <th className="px-2 py-2 text-right font-bold text-slate-400 uppercase tracking-tighter whitespace-nowrap">价税合计</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50 bg-white">
