      const matchSalesperson = dimension === 'salesperson' || filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = dimension === 'category' || filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = dimension === 'customer' || filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = dimension === 'itemName' || filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (
        (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
        (!filters.dateRange[1] || item.date <= filters.dateRange[1])
      );
      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });

    const counts: Record<string, number> = {};
    filteredByOthers.forEach(item => {
      const val = item[dimension] as string;
      if (val) counts[val] = (counts[val] || 0) + 1;
    });

    const options = Array.from(new Set(cloudData.map(d => d[dimension] as string))).sort();
    if (dimension === 'month') options.reverse();
    return { options, counts };
  };

  const dynamicFilterData = useMemo(() => ({
    months: getDynamicDimensionData('month'),
    customers: getDynamicDimensionData('customer'),
    salespeople: getDynamicDimensionData('salesperson'),
    categories: getDynamicDimensionData('category'),
    itemNames: getDynamicDimensionData('itemName')
  }), [cloudData, filters]);

  const filteredData = useMemo(() => {
    return cloudData.filter(item => {
      const matchMonth = filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
                        (!filters.dateRange[1] || item.date <= filters.dateRange[1]);
      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });
  }, [cloudData, filters]);

  const summary: SalesSummary = useMemo(() => {
    const totalSales = filteredData.reduce((acc, cur) => acc + cur.totalAmount, 0);
    const totalQuantity = filteredData.reduce((acc, cur) => acc + cur.quantity, 0);
    const uniqueOrderIds = Array.from(new Set(filteredData.map(d => d.id))).sort();

    const monthlyMap = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const existing = monthlyMap.get(d.month) || { sales: 0, quantity: 0 };
      monthlyMap.set(d.month, {
        sales: existing.sales + d.totalAmount,
        quantity: existing.quantity + d.quantity
      });
    });
    const monthlyTrend = Array.from(monthlyMap.entries()).map(([name, val]) => ({ name, ...val })).sort((a, b) => a.name.localeCompare(b.name));

    const catMap = new Map<string, number>();
    const catQtyMap = new Map<string, number>();
    filteredData.forEach(d => {
      catMap.set(d.category, (catMap.get(d.category) || 0) + d.totalAmount);
      catQtyMap.set(d.category, (catQtyMap.get(d.category) || 0) + d.quantity);
    });

    const spMap = new Map<string, number>();
    filteredData.forEach(d => spMap.set(d.salesperson, (spMap.get(d.salesperson) || 0) + d.totalAmount));

    return { 
      totalSales, 
      totalQuantity, 
      orderCount: uniqueOrderIds.length, 
      orderIds: uniqueOrderIds, 
      categoryDistribution: Array.from(catMap.entries()).map(([name, value]) => ({ name, value })),
      categoryQuantityDistribution: Array.from(catQtyMap.entries()).map(([name, value]) => ({ name, value })),
      salespersonPerformance: Array.from(spMap.entries()).map(([name, value]) => ({ name, value })).sort((a, b) => b.value - a.value),
      monthlyTrend 
    };
  }, [filteredData]);

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 p-4 text-center">
        <div className="bg-white p-8 rounded-3xl shadow-2xl max-w-md border border-red-100">
          <div className="text-6xl mb-4">🔗</div>
          <h2 className="text-2xl font-black text-slate-900 mb-2">Google 表格连接受限</h2>
          <p className="text-slate-500 text-sm mb-6 rounded-lg bg-red-50 p-3 leading-relaxed">{error}</p>
          <button onClick={loadCloudData} className="w-full mt-4 bg-indigo-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100">重试连接云端</button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 pb-12">
      <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-2xl font-black shadow-lg shadow-indigo-100">S</div>
            <div>
              <div className="flex items-center gap-2">
                <h1 className="text-lg font-black text-slate-900">销售数据分析</h1>
                <span className="hidden sm:inline-block px-2 py-0.5 rounded-full text-[10px] font-bold border bg-indigo-50 text-indigo-600 border-indigo-100 uppercase tracking-widest">
                   Cloud Sync
                </span>
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <nav className="flex bg-slate-100 p-1 rounded-xl">
              <button onClick={() => setActiveTab('dashboard')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'dashboard' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-900'}`}>看板</button>
              <button onClick={() => setActiveTab('table')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'table' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-900'}`}>明细</button>
            </nav>
          </div>
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 pt-8">
        <div className="flex justify-between items-center mb-6">
          <div className="flex items-center gap-2 text-slate-500">
             <span className="text-xs font-bold uppercase tracking-wider">数据状态:</span>
             <span className="flex items-center gap-1.5 text-xs font-bold text-emerald-600">
                <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
                已同步
             </span>
          </div>
          <button 
            onClick={loadCloudData} 
            className="flex items-center gap-2 bg-white border border-slate-200 px-4 py-2 rounded-xl text-xs font-bold text-slate-600 hover:bg-slate-50 hover:border-indigo-300 hover:text-indigo-600 transition-all shadow-sm active:scale-95"
          >
            <svg className={`w-3.5 h-3.5 ${isLoading ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
            刷新数据
          </button>
        </div>

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-32 space-y-4">
            <div className="w-12 h-12 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
            <p className="text-slate-500 font-bold tracking-widest uppercase text-xs">正在同步云端数据...</p>
          </div>
        ) : (
          <>
            <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 mb-8">
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-sm font-black text-slate-800 uppercase tracking-widest flex items-center gap-2">
                  <span className="w-1.5 h-4 bg-indigo-600 rounded-full"></span> 筛选中心
                </h2>
                <div className="flex items-center gap-3">
                   <span className="text-xs text-slate-400 font-mono">共 {filteredData.length} 条符合条件</span>
                   {Object.values(filters).some(f => Array.isArray(f) ? f.length > 0 : !!f) && (
                     <button onClick={() => setFilters({ months: [], dateRange: ['', ''], customers: [], salespeople: [], categories: [], itemNames: [] })} className="text-[10px] text-red-500 font-bold hover:underline px-2 py-1 bg-red-50 rounded-md">重置全部</button>
                   )}
                </div>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6">
                <MultiSelect label="月份" options={dynamicFilterData.months.options} counts={dynamicFilterData.months.counts} selectedValues={filters.months} onChange={(v) => setFilters({...filters, months: v})} />
                <MultiSelect label="客户" options={dynamicFilterData.customers.options} counts={dynamicFilterData.customers.counts} selectedValues={filters.customers} onChange={(v) => setFilters({...filters, customers: v})} />
                <MultiSelect label="销售员" options={dynamicFilterData.salespeople.options} counts={dynamicFilterData.salespeople.counts} selectedValues={filters.salespeople} onChange={(v) => setFilters({...filters, salespeople: v})} />
                <MultiSelect label="品类" options={dynamicFilterData.categories.options} counts={dynamicFilterData.categories.counts} selectedValues={filters.categories} onChange={(v) => setFilters({...filters, categories: v})} />
                <MultiSelect label="物料名称" options={dynamicFilterData.itemNames.options} counts={dynamicFilterData.itemNames.counts} selectedValues={filters.itemNames} onChange={(v) => setFilters({...filters, itemNames: v})} />
              </div>
            </section>

            <div className="animate-in fade-in duration-700">
              {filteredData.length > 0 ? (
                activeTab === 'dashboard' ? (
                  <Dashboard summary={summary} filteredData={filteredData} onSelectOrderId={setSelectedOrderId} />
                ) : (
                  <DataTable data={filteredData} onSelectOrderId={setSelectedOrderId} />
                )
              ) : (
                <div className="py-32 bg-white rounded-3xl border border-dashed border-slate-200 text-center">
                  <div className="text-5xl mb-4">🔎</div>
                  <h3 className="text-xl font-bold text-slate-800">未找到匹配数据</h3>
                  <p className="text-slate-500 mt-2">请尝试调整筛选器组合或重置条件</p>
                </div>
              )}
            </div>
          </>
        )}
      </main>

      {selectedOrderId && (
        <OrderDetailModal orderId={selectedOrderId} records={cloudData.filter(d => d.id === selectedOrderId)} onClose={() => setSelectedOrderId(null)} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [drillDownMetric, setDrillDownMetric] = useState<'sales' | 'quantity'>('sales');
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [selectedCustomerInDrillDown, setSelectedCustomerInDrillDown] = useState<string | null>(null);

  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  const [localTableFilters, setLocalTableFilters] = useState({
    id: '',
    date: '',
    customer: '',
    itemName: ''
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);

  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return {
        name: cat.name,
        sales: cat.value,
        quantity: qtyItem ? qtyItem.value : 0
      };
    });

    return merged.sort((a, b) => {
      if (pieMetric === 'sales') return b.sales - a.sales;
      return b.quantity - a.quantity;
    });
  }, [summary, pieMetric]);

  const globalTotals = useMemo(() => {
    return sortedCategorySummary.reduce((acc, cur) => {
      acc.sales += cur.sales;
      acc.quantity += cur.quantity;
      return acc;
    }, { sales: 0, quantity: 0 });
  }, [sortedCategorySummary]);

  const currentTotal = pieMetric === 'sales' ? globalTotals.sales : globalTotals.quantity;

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], customers: [], records: [], drillDownTotal: 0 };

    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const customersMap = new Map<string, { sales: number; qty: number; orderIds: Set<string> }>();
    let records: SalesRecord[] = [];
    let drillDownTotal = 0;

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        const itemExisting = itemsMap.get(record.itemName) || { sales: 0, qty: 0 };
        itemsMap.set(record.itemName, {
          sales: itemExisting.sales + record.totalAmount,
          qty: itemExisting.qty + record.quantity
        });

        const customerExisting = customersMap.get(record.customer) || { sales: 0, qty: 0, orderIds: new Set() };
        customerExisting.orderIds.add(record.id);
        customersMap.set(record.customer, {
          sales: customerExisting.sales + record.totalAmount,
          qty: customerExisting.qty + record.quantity,
          orderIds: customerExisting.orderIds
        });

        records.push(record);
        drillDownTotal += (drillDownMetric === 'sales' ? record.totalAmount : record.quantity);
      }
    });

    const items = Array.from(itemsMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ 
        name, 
        sales: val.sales, 
        qty: val.qty, 
        orderIds: Array.from(val.orderIds).sort(),
        percentage: drillDownTotal > 0 ? (((drillDownMetric === 'sales' ? val.sales : val.qty) / drillDownTotal) * 100).toFixed(1) + '%' : '0%'
      }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    if (selectedCustomerInDrillDown) records = records.filter(r => r.customer === selectedCustomerInDrillDown);
    if (localTableFilters.id) records = records.filter(r => r.id === localTableFilters.id);
    if (localTableFilters.date) records = records.filter(r => r.date >= localTableFilters.date);
    if (localTableFilters.customer) records = records.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.itemName) records = records.filter(r => r.itemName === localTableFilters.itemName);

    return { items, customers, records: records.sort((a, b) => b.date.localeCompare(a.date)), drillDownTotal };
  }, [selectedCategory, filteredData, drillDownMetric, selectedCustomerInDrillDown, localTableFilters]);

  const localFilterOptions = useMemo(() => {
    if (!selectedCategory) return { ids: [], dates: [], customers: [], itemNames: [] };
    const ids = new Set<string>();
    const dates = new Set<string>();
    const customers = new Set<string>();
    const itemNames = new Set<string>();

    filteredData.forEach(r => {
      if (r.category === selectedCategory) {
        ids.add(r.id);
        dates.add(r.date);
        customers.add(r.customer);
        itemNames.add(r.itemName);
      }
    });

    return {
      ids: Array.from(ids).sort().reverse(),
      dates: Array.from(dates).sort().reverse(),
      customers: Array.from(customers).sort(),
      itemNames: Array.from(itemNames).sort()
    };
  }, [filteredData, selectedCategory]);

  const handleCategorySelection = (categoryName: string) => {
    setDrillDownMetric(pieMetric);
    if (selectedCategory === categoryName) {
      setSelectedCategory(null);
      setSelectedCustomerInDrillDown(null);
    } else {
      setSelectedCategory(categoryName);
      setSelectedCustomerInDrillDown(null);
      setLocalTableFilters({ id: '', date: '', customer: '', itemName: '' });
    }
  };

  const FilterHeader = ({ label, columnId, options }: { label: string, columnId: keyof typeof localTableFilters, options: string[] }) => {
    const isActive = !!localTableFilters[columnId];
    return (
      <th className="px-3 py-3 text-left relative">
        <div className="flex items-center gap-1.5 group">
          <span className="font-bold text-slate-400 uppercase tracking-tighter text-[10px] whitespace-nowrap">{label}</span>
          <button 
            onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)}
            className={`p-1 rounded hover:bg-slate-200 transition-all ${isActive ? 'text-indigo-600' : 'text-slate-300'}`}
          >
            <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" clipRule="evenodd" />
            </svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-56 bg-white rounded-xl shadow-2xl border border-slate-200 z-[3000] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2 border-b border-slate-50 bg-slate-50 flex justify-between items-center">
              <span className="text-[10px] font-bold text-slate-400 uppercase">筛选{label}</span>
              {isActive && (
                <button onClick={() => setLocalTableFilters(p => ({ ...p, [columnId]: '' }))} className="text-[9px] text-red-500 font-bold hover:underline">清除</button>
              )}
            </div>
            <div className="max-h-60 overflow-y-auto p-1 custom-scrollbar">
              {options.map(opt => (
                <button
                  key={opt}
                  onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }}
                  className={`w-full text-left px-3 py-2 rounded-lg text-xs transition-colors ${localTableFilters[columnId] === opt ? 'bg-indigo-50 text-indigo-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
                >
                  {opt}
                </button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow flex flex-col h-full group">
      <div className="flex justify-between items-start mb-3">
        <div className="p-2.5 bg-indigo-50 rounded-xl text-indigo-600 text-xl group-hover:bg-indigo-600 group-hover:text-white transition-all duration-300">{icon}</div>
        <span className="text-[11px] font-bold text-slate-400 uppercase tracking-widest">{title}</span>
      </div>
      <div className="text-2xl font-black text-slate-900 mb-1">{value}</div>
      <div className="text-xs text-slate-500 mb-4">{sub}</div>
      {children}
    </div>
  );

  return (
    <div className="space-y-8 pb-10">
      {/* KPI Section - 全宽一行 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KpiCard title="总销售额" value={`${summary.totalSales.toLocaleString()} CFA`} sub="当前筛选范围内的成交总额" icon="💰" />
        <KpiCard title="出库总量" value={summary.totalQuantity.toLocaleString()} sub="全品类物料累计出库件数" icon="📦" />
        <KpiCard title="关联单据" value={`${summary.orderCount} 个单号`} sub="点击单号查看完整明细" icon="📑">
          <div className="mt-auto max-h-24 overflow-y-auto pr-1 custom-scrollbar border-t border-slate-50 pt-2">
            <div className="flex flex-wrap gap-1.5">
              {summary.orderIds.map(id => (
                <button key={id} onClick={() => onSelectOrderId(id)} className="inline-block px-2 py-0.5 bg-indigo-50 text-indigo-600 text-[10px] font-mono rounded border border-indigo-100 hover:bg-indigo-600 hover:text-white transition-colors">
                  {id}
                </button>
              ))}
            </div>
          </div>
        </KpiCard>
      </div>

      {/* 第一行：宽幅趋势分析 */}
      <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-8">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">
              <span className="w-1 h-6 bg-indigo-600 rounded-full"></span> 销售趋势全览
            </h3>
            <p className="text-xs text-slate-400 mt-1 uppercase tracking-widest font-bold">Sales & Quantity Monthly Trend</p>
          </div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setShowCfa(!showCfa)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>销售金额</button>
            <button onClick={() => setShowQuantity(!showQuantity)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>出库数量</button>
          </div>
        </div>
        <div className="h-[400px] w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={summary.monthlyTrend} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
              <defs>
                <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#6366f1" stopOpacity={0.15}/>
                  <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                </linearGradient>
                <linearGradient id="colorQty" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#10b981" stopOpacity={0.15}/>
                  <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 500}} dy={10} />
              <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#6366f1', fontSize: 10, fontWeight: 'bold'}} />
              <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 10, fontWeight: 'bold'}} />
              <Tooltip 
                contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', padding: '12px' }}
                itemStyle={{ fontSize: '12px', fontWeight: 'bold' }}
              />
