import React, { useState, useMemo, useEffect } from 'react';
import { FilterState, SalesSummary, SalesRecord } from './types';
import Dashboard from './components/Dashboard';
import DataTable from './components/DataTable';
import MultiSelect from './components/MultiSelect';
import OrderDetailModal from './components/OrderDetailModal';
import { fetchSalesData } from './services/dataService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'table'>('dashboard');
  const [cloudData, setCloudData] = useState<SalesRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedOrderId, setSelectedOrderId] = useState<string | null>(null);

  const [filters, setFilters] = useState<FilterState>({
    months: [],
    dateRange: ['', ''],
    customers: [],
    salespeople: [],
    categories: [],
    itemNames: []
  });

  const loadCloudData = async () => {
    try {
      setIsLoading(true);
      setError(null);
      const data = await fetchSalesData();
      setCloudData(data);
      initializeFilters();
    } catch (err) {
      const message = err instanceof Error ? err.message : '连接数据源失败';
      setError(message || '未知错误');
    } finally {
      setIsLoading(false);
    }
  };

  const initializeFilters = () => {
    setFilters({
      months: [],
      dateRange: ['', ''],
      customers: [],
      salespeople: [],
      categories: [],
      itemNames: []
    });
  };

  useEffect(() => {
    loadCloudData();
  }, []);

  const getDynamicDimensionData = (dimension: keyof SalesRecord) => {
    const filteredByOthers = cloudData.filter(item => {
      const matchMonth = dimension === 'month' || filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = dimension === 'salesperson' || filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = dimension === 'category' || filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = dimension === 'customer' || filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = dimension === 'itemName' || filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (
        (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
        (!filters.dateRange[1] || item.date <= filters.dateRange[1])
      );
      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });

    const counts: Record<string, number> = {};
    filteredByOthers.forEach(item => {
      const val = item[dimension] as string;
      if (val) counts[val] = (counts[val] || 0) + 1;
    });

    const options = Array.from(new Set(cloudData.map(d => d[dimension] as string))).sort();
    if (dimension === 'month') options.reverse();
    return { options, counts };
  };

  const dynamicFilterData = useMemo(() => ({
    months: getDynamicDimensionData('month'),
    customers: getDynamicDimensionData('customer'),
    salespeople: getDynamicDimensionData('salesperson'),
    categories: getDynamicDimensionData('category'),
    itemNames: getDynamicDimensionData('itemName')
  }), [cloudData, filters]);

  const filteredData = useMemo(() => {
    return cloudData.filter(item => {
      const matchMonth = filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
                        (!filters.dateRange[1] || item.date <= filters.dateRange[1]);
      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });
  }, [cloudData, filters]);

  const summary: SalesSummary = useMemo(() => {
    const totalSales = filteredData.reduce((acc, cur) => acc + cur.totalAmount, 0);
    const totalQuantity = filteredData.reduce((acc, cur) => acc + cur.quantity, 0);
    const uniqueOrderIds = Array.from(new Set(filteredData.map(d => d.id))).sort();

    const monthlyMap = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const existing = monthlyMap.get(d.month) || { sales: 0, quantity: 0 };
      monthlyMap.set(d.month, {
        sales: existing.sales + d.totalAmount,
        quantity: existing.quantity + d.quantity
      });
    });
    const monthlyTrend = Array.from(monthlyMap.entries()).map(([name, val]) => ({ name, ...val })).sort((a, b) => a.name.localeCompare(b.name));

    const catMap = new Map<string, number>();
    const catQtyMap = new Map<string, number>();
    filteredData.forEach(d => {
      catMap.set(d.category, (catMap.get(d.category) || 0) + d.totalAmount);
      catQtyMap.set(d.category, (catQtyMap.get(d.category) || 0) + d.quantity);
    });

    const spMap = new Map<string, number>();
    filteredData.forEach(d => spMap.set(d.salesperson, (spMap.get(d.salesperson) || 0) + d.totalAmount));

    return { 
      totalSales, 
      totalQuantity, 
      orderCount: uniqueOrderIds.length, 
      orderIds: uniqueOrderIds, 
      categoryDistribution: Array.from(catMap.entries()).map(([name, value]) => ({ name, value })),
      categoryQuantityDistribution: Array.from(catQtyMap.entries()).map(([name, value]) => ({ name, value })),
      salespersonPerformance: Array.from(spMap.entries()).map(([name, value]) => ({ name, value })).sort((a, b) => b.value - a.value),
      monthlyTrend 
    };
  }, [filteredData]);

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 p-4 text-center">
        <div className="bg-white p-8 rounded-3xl shadow-2xl max-w-md border border-red-100">
          <div className="text-6xl mb-4">🔗</div>
          <h2 className="text-2xl font-black text-slate-900 mb-2">数据连接受阻</h2>
          <p className="text-slate-500 text-sm mb-6 rounded-lg bg-red-50 p-3 leading-relaxed">{error}</p>
          <button onClick={loadCloudData} className="w-full mt-4 bg-indigo-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100">重试连接</button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 pb-12">
      <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-2xl font-black shadow-lg shadow-indigo-100">S</div>
            <div>
              <div className="flex items-center gap-2">
                <h1 className="text-lg font-black text-slate-900">销售数据洞察</h1>
                <span className="hidden sm:inline-block px-2 py-0.5 rounded-full text-[10px] font-bold border bg-emerald-50 text-emerald-600 border-emerald-100 uppercase tracking-widest">
                   Cloud Sync
                </span>
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <nav className="flex bg-slate-100 p-1 rounded-xl">
              <button onClick={() => setActiveTab('dashboard')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'dashboard' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-900'}`}>分析看板</button>
              <button onClick={() => setActiveTab('table')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'table' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-900'}`}>数据明细</button>
            </nav>
          </div>
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 pt-8">
        <div className="flex justify-between items-center mb-6">
          <div className="flex items-center gap-2 text-slate-500">
             <span className="text-xs font-bold uppercase tracking-wider">数据状态:</span>
             <span className="flex items-center gap-1.5 text-xs font-bold text-emerald-600">
                <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
                同步成功
             </span>
          </div>
          <button 
            onClick={loadCloudData} 
            className="flex items-center gap-2 bg-white border border-slate-200 px-4 py-2 rounded-xl text-xs font-bold text-slate-600 hover:bg-slate-50 hover:border-indigo-300 hover:text-indigo-600 transition-all shadow-sm active:scale-95"
          >
            <svg className={`w-3.5 h-3.5 ${isLoading ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
            刷新数据
          </button>
        </div>

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-32 space-y-4">
            <div className="w-12 h-12 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
            <p className="text-slate-500 font-bold tracking-widest uppercase text-xs">正在拉取最新数据...</p>
          </div>
        ) : (
          <>
            <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 mb-8">
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-sm font-black text-slate-800 uppercase tracking-widest flex items-center gap-2">
                  <span className="w-1.5 h-4 bg-indigo-600 rounded-full"></span> 筛选中心
                </h2>
                <div className="flex items-center gap-3">
                   <span className="text-xs text-slate-400 font-mono tracking-tight">符合条件: {filteredData.length} 条</span>
                   {(Object.values(filters).some(f => Array.isArray(f) ? f.length > 0 : !!f) || filters.dateRange.some(d => !!d)) && (
                     <button onClick={initializeFilters} className="text-[10px] text-red-500 font-bold hover:underline px-2 py-1 bg-red-50 rounded-md">清空所有</button>
                   )}
                </div>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-6">
                <MultiSelect label="月份" options={dynamicFilterData.months.options} counts={dynamicFilterData.months.counts} selectedValues={filters.months} onChange={(v) => setFilters({...filters, months: v})} />
                <MultiSelect label="客户" options={dynamicFilterData.customers.options} counts={dynamicFilterData.customers.counts} selectedValues={filters.customers} onChange={(v) => setFilters({...filters, customers: v})} />
                <MultiSelect label="销售员" options={dynamicFilterData.salespeople.options} counts={dynamicFilterData.salespeople.counts} selectedValues={filters.salespeople} onChange={(v) => setFilters({...filters, salespeople: v})} />
                <MultiSelect label="品类" options={dynamicFilterData.categories.options} counts={dynamicFilterData.categories.counts} selectedValues={filters.categories} onChange={(v) => setFilters({...filters, categories: v})} />
                <MultiSelect label="物料" options={dynamicFilterData.itemNames.options} counts={dynamicFilterData.itemNames.counts} selectedValues={filters.itemNames} onChange={(v) => setFilters({...filters, itemNames: v})} />

                {/* 业务日期 放在最后 */}
                <div className="space-y-1.5">
                  <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider">业务日期范围</label>
                  <div className="flex items-center gap-1 bg-slate-50 border border-slate-200 rounded-lg px-2 py-1.5 hover:bg-white hover:border-indigo-300 transition-all focus-within:border-indigo-500 focus-within:ring-2 focus-within:ring-indigo-100">
                    <input 
                      type="date" 
                      value={filters.dateRange[0]} 
                      onChange={(e) => setFilters({...filters, dateRange: [e.target.value, filters.dateRange[1]]})}
                      className="bg-transparent text-[11px] font-bold text-slate-600 outline-none w-full cursor-pointer"
                    />
                    <span className="text-slate-300">-</span>
                    <input 
                      type="date" 
                      value={filters.dateRange[1]} 
                      onChange={(e) => setFilters({...filters, dateRange: [filters.dateRange[0], e.target.value]})}
                      className="bg-transparent text-[11px] font-bold text-slate-600 outline-none w-full cursor-pointer"
                    />
                  </div>
                </div>
              </div>
            </section>

            <div className="animate-in fade-in duration-700">
              {filteredData.length > 0 ? (
                activeTab === 'dashboard' ? (
                  <Dashboard summary={summary} filteredData={filteredData} onSelectOrderId={setSelectedOrderId} />
                ) : (
                  <DataTable data={filteredData} onSelectOrderId={setSelectedOrderId} />
                )
              ) : (
                <div className="py-32 bg-white rounded-3xl border border-dashed border-slate-200 text-center">
                  <div className="text-5xl mb-4">🔎</div>
                  <h3 className="text-xl font-bold text-slate-800">未找到匹配数据</h3>
                  <p className="text-slate-500 mt-2">请尝试调整筛选器组合</p>
                </div>
              )}
            </div>
          </>
        )}
      </main>

      {selectedOrderId && (
        <OrderDetailModal orderId={selectedOrderId} records={cloudData.filter(d => d.id === selectedOrderId)} onClose={() => setSelectedOrderId(null)} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [drillDownMetric, setDrillDownMetric] = useState<'sales' | 'quantity'>('sales');
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  const [localTableFilters, setLocalTableFilters] = useState({ id: '', date: '', customer: '', itemName: '' });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const globalTotals = useMemo(() => {
    return sortedCategorySummary.reduce((acc, cur) => {
      acc.sales += cur.sales;
      acc.quantity += cur.quantity;
      return acc;
    }, { sales: 0, quantity: 0 });
  }, [sortedCategorySummary]);

  const currentTotal = pieMetric === 'sales' ? globalTotals.sales : globalTotals.quantity;

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { items: [], customers: [], records: [], drillDownTotal: 0 };
    const itemsMap = new Map<string, { sales: number; qty: number }>();
    const customersMap = new Map<string, { sales: number; qty: number; orderIds: Set<string> }>();
    let records: SalesRecord[] = [];
    let drillDownTotal = 0;

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        itemsMap.set(record.itemName, {
          sales: (itemsMap.get(record.itemName)?.sales || 0) + record.totalAmount,
          qty: (itemsMap.get(record.itemName)?.qty || 0) + record.quantity
        });
        const c = customersMap.get(record.customer) || { sales: 0, qty: 0, orderIds: new Set() };
        c.orderIds.add(record.id);
        customersMap.set(record.customer, { sales: c.sales + record.totalAmount, qty: c.qty + record.quantity, orderIds: c.orderIds });
        records.push(record);
        drillDownTotal += (drillDownMetric === 'sales' ? record.totalAmount : record.quantity);
      }
    });

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ 
        name, 
        sales: val.sales, 
        qty: val.qty, 
        percentage: drillDownTotal > 0 ? (((drillDownMetric === 'sales' ? val.sales : val.qty) / drillDownTotal) * 100).toFixed(1) + '%' : '0%'
      }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    if (localTableFilters.id) records = records.filter(r => r.id === localTableFilters.id);
    if (localTableFilters.date) records = records.filter(r => r.date >= localTableFilters.date);
    if (localTableFilters.customer) records = records.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.itemName) records = records.filter(r => r.itemName === localTableFilters.itemName);

    return { customers, records: records.sort((a, b) => b.date.localeCompare(a.date)), drillDownTotal };
  }, [selectedCategory, filteredData, drillDownMetric, localTableFilters]);

  const FilterHeader = ({ label, columnId, options }: { label: string, columnId: keyof typeof localTableFilters, options: string[] }) => (
    <th className="px-3 py-3 text-left relative group min-w-[100px]">
      <div className="flex items-center gap-1.5">
        <span className="font-bold text-slate-400 uppercase tracking-tighter text-[10px]">{label}</span>
        <button onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)} className={`p-1 rounded transition-all ${!!localTableFilters[columnId] ? 'text-indigo-600' : 'text-slate-300'}`}>
          <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" /></svg>
        </button>
      </div>
      {activeFilterColumn === columnId && (
        <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-56 bg-white rounded-xl shadow-2xl border border-slate-200 z-[3000] overflow-hidden">
          <div className="p-2 border-b border-slate-50 bg-slate-50 flex justify-between items-center text-[10px] font-bold text-slate-400">筛选{label}</div>
          <div className="max-h-60 overflow-y-auto p-1 custom-scrollbar">
            <button onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: '' })); setActiveFilterColumn(null); }} className="w-full text-left px-3 py-2 rounded-lg text-xs text-slate-400 italic hover:bg-slate-50">清除筛选</button>
            {options.map(opt => (
              <button key={opt} onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }} className={`w-full text-left px-3 py-2 rounded-lg text-xs transition-colors ${localTableFilters[columnId] === opt ? 'bg-indigo-50 text-indigo-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}>{opt}</button>
            ))}
          </div>
        </div>
      )}
    </th>
  );

  const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-all flex flex-col group h-full">
      <div className="flex justify-between items-start mb-3">
        <div className="p-2.5 bg-indigo-50 rounded-xl text-indigo-600 text-xl group-hover:bg-indigo-600 group-hover:text-white transition-all duration-300">{icon}</div>
        <span className="text-[11px] font-bold text-slate-400 uppercase tracking-widest">{title}</span>
      </div>
      <div className="text-2xl font-black text-slate-900 mb-1">{value}</div>
      <div className="text-xs text-slate-500 mb-4">{sub}</div>
      {children}
    </div>
  );

  return (
    <div className="space-y-8 pb-10">
      {/* 核心 KPI - 分布在顶部 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KpiCard title="成交总额" value={`${summary.totalSales.toLocaleString()} CFA`} sub="成交额包含所有品类" icon="💰" />
        <KpiCard title="出库总量" value={summary.totalQuantity.toLocaleString()} sub="全品类物料累计出库件数" icon="📦" />
        <KpiCard title="业务单据" value={`${summary.orderCount} 个单号`} sub="单号分布范围" icon="📑">
          <div className="mt-auto max-h-24 overflow-y-auto pr-1 custom-scrollbar border-t border-slate-50 pt-2 flex flex-wrap gap-1.5">
            {summary.orderIds.map(id => (
              <button key={id} onClick={() => onSelectOrderId(id)} className="inline-block px-2 py-0.5 bg-indigo-50 text-indigo-600 text-[10px] font-mono rounded border border-indigo-100 hover:bg-indigo-600 hover:text-white transition-colors">{id}</button>
            ))}
          </div>
        </KpiCard>
      </div>

      {/* 1. 销售趋势分析 - 独占一行 */}
      <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-8">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">
              <span className="w-1 h-6 bg-indigo-600 rounded-full"></span> 销售趋势全览
            </h3>
            <p className="text-xs text-slate-400 mt-1 uppercase tracking-widest font-bold font-mono">Sales & Quantity Trend</p>
          </div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setShowCfa(!showCfa)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>销售金额</button>
            <button onClick={() => setShowQuantity(!showQuantity)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>出库数量</button>
          </div>
        </div>
        <div className="h-[450px]">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={summary.monthlyTrend} margin={{ left: 0, right: 10, top: 0, bottom: 0 }}>
              <defs>
                <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#6366f1" stopOpacity={0.15}/><stop offset="95%" stopColor="#6366f1" stopOpacity={0}/></linearGradient>
                <linearGradient id="colorQty" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#10b981" stopOpacity={0.15}/><stop offset="95%" stopColor="#10b981" stopOpacity={0}/></linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} dy={10} />
              <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#6366f1', fontSize: 10, fontWeight: 'bold'}} />
              <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 10, fontWeight: 'bold'}} />
              <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }} />
              {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" name="金额 (CFA)" stroke="#6366f1" strokeWidth={4} fill="url(#colorSales)" />}
              {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" name="数量" stroke="#10b981" strokeWidth={4} fill="url(#colorQty)" />}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* 2. 品类分布洞察 - 独占一行且更宽 */}
      <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200 relative min-h-[650px] overflow-hidden">
        <div className="flex justify-between items-center mb-10">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">
              <span className="w-1 h-6 bg-indigo-600 rounded-full"></span> 品类结构洞察
            </h3>
            <p className="text-xs text-slate-400 mt-1 uppercase tracking-widest font-bold font-mono">Category Analysis</p>
          </div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'sales' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>按金额</button>
            <button onClick={() => setPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>按数量</button>
          </div>
        </div>

        <div className="flex flex-col xl:flex-row items-center gap-16">
          <div className="relative w-full xl:w-[480px] h-[480px] flex-shrink-0">
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none text-center">
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">选中汇总</p>
              <p className={`text-4xl font-black ${pieMetric === 'sales' ? 'text-indigo-600' : 'text-emerald-600'}`}>{currentTotal.toLocaleString()}</p>
            </div>
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={sortedCategorySummary} cx="50%" cy="50%" innerRadius={150} outerRadius={210} paddingAngle={4} dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} onClick={(d) => setSelectedCategory(d.name)} stroke="none" style={{ cursor: 'pointer', outline: 'none' }}>
                  {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} opacity={selectedCategory && selectedCategory !== sortedCategorySummary[i].name ? 0.3 : 1} />)}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-2 gap-4">
            {sortedCategorySummary.map((item, idx) => {
              const val = pieMetric === 'sales' ? item.sales : item.quantity;
              const isSelected = selectedCategory === item.name;
              return (
                <button key={item.name} onClick={() => setSelectedCategory(item.name)} className={`flex items-center justify-between p-5 rounded-2xl border transition-all ${isSelected ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl scale-[1.02]' : 'bg-slate-50 border-slate-100 hover:bg-white hover:border-indigo-300'}`}>
                  <div className="flex items-center gap-4 text-left">
                    <div className="w-2.5 h-10 rounded-full" style={{ backgroundColor: isSelected ? '#fff' : COLORS[idx % COLORS.length] }}></div>
                    <div><p className="text-sm font-black">{item.name}</p><p className={`text-[10px] font-bold uppercase ${isSelected ? 'text-indigo-100' : 'text-slate-400'}`}>占比 {(val / currentTotal * 100).toFixed(1)}%</p></div>
                  </div>
                  <p className="text-lg font-mono font-black">{val.toLocaleString()}</p>
                </button>
              );
            })}
          </div>
        </div>

        {selectedCategory && (
          <div className="absolute inset-0 bg-white/98 backdrop-blur-xl z-[2000] p-10 flex flex-col animate-in slide-in-from-bottom duration-500 overflow-hidden">
            <div className="flex items-center justify-between mb-8 pb-6 border-b border-slate-100">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-xl"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg></div>
                <div><h4 className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">Detail Down</h4><h3 className="text-3xl font-black text-slate-900">{selectedCategory}</h3></div>
              </div>
              <button onClick={() => setSelectedCategory(null)} className="flex items-center gap-2 px-6 py-3 bg-slate-100 hover:bg-red-50 hover:text-red-600 rounded-2xl text-sm font-bold transition-all">关闭下钻<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg></button>
            </div>
            <div className="flex-1 flex gap-10 overflow-hidden min-h-0">
              <div className="w-1/4 flex flex-col">
                <h5 className="text-xs font-black text-slate-800 uppercase tracking-wider mb-6">🏆 核心客户排行</h5>
                <div className="flex-1 bg-slate-50/50 rounded-3xl p-6 border border-slate-100">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={drillDownData.customers.slice(0, 10)} layout="vertical" margin={{ left: 0, right: 60 }}>
                      <XAxis type="number" hide /><YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={80} tick={{fill: '#475569', fontSize: 11, fontWeight: 'bold'}} />
                      <Tooltip /><Bar dataKey={drillDownMetric === 'sales' ? 'sales' : 'qty'} fill="#6366f1" radius={[0, 8, 8, 0]} barSize={24}>
                        {drillDownData.customers.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                        <LabelList dataKey="percentage" position="right" fill="#94a3b8" fontSize={10} fontWeight="black" offset={10} />
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
              <div className="flex-1 flex flex-col min-h-0">
                <h5 className="text-xs font-black text-slate-800 uppercase tracking-wider mb-6">📑 关联交易记录</h5>
                <div className="flex-1 bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden flex flex-col">
                  <div className="overflow-x-auto flex-1 custom-scrollbar"><table className="min-w-full text-xs">
                    <thead className="bg-slate-50 sticky top-0 z-10">
                      <tr>
                        <FilterHeader label="单号" columnId="id" options={Array.from(new Set(drillDownData.records.map(r => r.id))).sort()} />
                        <FilterHeader label="日期" columnId="date" options={Array.from(new Set(drillDownData.records.map(r => r.date))).sort().reverse()} />
                        <FilterHeader label="客户" columnId="customer" options={Array.from(new Set(drillDownData.records.map(r => r.customer))).sort()} />
                        <th className="px-4 py-3 text-left font-bold text-slate-400 uppercase tracking-widest text-[10px]">物料</th>
                        <th className="px-4 py-3 text-right font-bold text-slate-400 uppercase tracking-widest text-[10px]">单价</th>
                        <th className="px-4 py-3 text-right font-bold text-slate-400 uppercase tracking-widest text-[10px]">数量</th>
                        <th className="px-4 py-3 text-right font-bold text-slate-400 uppercase tracking-widest text-[10px]">金额</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {drillDownData.records.map((r, i) => (
                        <tr key={i} className="hover:bg-indigo-50/50 transition-colors group">
                          <td className="px-4 py-3.5 text-indigo-600 font-mono font-black"><button onClick={() => onSelectOrderId(r.id)} className="hover:underline">{r.id}</button></td>
                          <td className="px-4 py-3.5 text-slate-500 font-mono">{r.date}</td>
                          <td className="px-4 py-3.5 text-slate-900 font-bold">{r.customer}</td>
                          <td className="px-4 py-3.5 text-slate-600 truncate max-w-[150px] font-bold">{r.itemName}</td>
                          <td className="px-4 py-3.5 text-right font-mono text-slate-400">{r.unitPrice.toLocaleString()}</td>
                          <td className="px-4 py-3.5 text-right font-mono font-bold text-indigo-600">{r.quantity}</td>
                          <td className="px-4 py-3.5 text-right font-mono font-black text-slate-900 group-hover:text-indigo-700">{r.totalAmount.toLocaleString()}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table></div>
                  <div className="px-6 py-4 bg-slate-50 border-t border-slate-100 text-[10px] font-bold text-slate-400 flex justify-between">
                    <span>记录数: {drillDownData.records.length}</span><span className="text-indigo-600 font-black">小计: {drillDownData.drillDownTotal.toLocaleString()}</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* 3. 销售绩效排行 - 独占一行 */}
      <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-10">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">
              <span className="w-1 h-6 bg-indigo-600 rounded-full"></span> 销售精英业绩榜
            </h3>
            <p className="text-xs text-slate-400 mt-1 uppercase tracking-widest font-bold font-mono">Performance Ranking</p>
          </div>
          <span className="px-4 py-1.5 bg-indigo-50 text-indigo-600 rounded-full text-[10px] font-black border border-indigo-100 uppercase tracking-widest">单位: CFA</span>
        </div>
        <div className="h-[450px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical" margin={{ left: 20, right: 100, top: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide /><YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={100} tick={{fill: '#1e293b', fontWeight: 800, fontSize: 13}} />
              <Tooltip cursor={{fill: '#f8fafc'}} formatter={(v) => [`${v.toLocaleString()} CFA`, '业绩金额']} />
              <Bar dataKey="value" fill="#6366f1" radius={[0, 12, 12, 0]} barSize={32}>
                 {summary.salespersonPerformance.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                 <LabelList dataKey="value" position="right" formatter={(v: any) => `${v.toLocaleString()} CFA`} fill="#1e293b" fontSize={12} fontWeight="black" offset={20} />
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { FilterState, SalesSummary, SalesRecord } from './types';
import Dashboard from './components/Dashboard';
import DataTable from './components/DataTable';
import MultiSelect from './components/MultiSelect';
import OrderDetailModal from './components/OrderDetailModal';
import { fetchSalesData } from './services/dataService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'table'>('dashboard');
  const [cloudData, setCloudData] = useState<SalesRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedOrderId, setSelectedOrderId] = useState<string | null>(null);

  const [filters, setFilters] = useState<FilterState>({
    months: [],
    dateRange: ['', ''],
    customers: [],
    salespeople: [],
    categories: [],
    itemNames: []
  });

  const loadCloudData = async () => {
    try {
      setIsLoading(true);
      setError(null);
      const data = await fetchSalesData();
      setCloudData(data);
      initializeFilters();
    } catch (err) {
      const message = err instanceof Error ? err.message : '连接数据源失败';
      setError(message);
    } finally {
      setIsLoading(false);
    }
  };

  const initializeFilters = () => {
    setFilters({
      months: [],
      dateRange: ['', ''],
      customers: [],
      salespeople: [],
      categories: [],
      itemNames: []
    });
  };

  useEffect(() => {
    loadCloudData();
  }, []);

  const getDynamicDimensionData = (dimension: keyof SalesRecord) => {
    const filteredByOthers = cloudData.filter(item => {
      const matchMonth = dimension === 'month' || filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = dimension === 'salesperson' || filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = dimension === 'category' || filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = dimension === 'customer' || filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = dimension === 'itemName' || filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (
        (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
        (!filters.dateRange[1] || item.date <= filters.dateRange[1])
      );
      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });

    const counts: Record<string, number> = {};
    filteredByOthers.forEach(item => {
      const val = item[dimension] as string;
      if (val) counts[val] = (counts[val] || 0) + 1;
    });

    const options = Array.from(new Set(cloudData.map(d => d[dimension] as string))).sort();
    if (dimension === 'month') options.reverse();
    return { options, counts };
  };

  const dynamicFilterData = useMemo(() => ({
    months: getDynamicDimensionData('month'),
    customers: getDynamicDimensionData('customer'),
    salespeople: getDynamicDimensionData('salesperson'),
    categories: getDynamicDimensionData('category'),
    itemNames: getDynamicDimensionData('itemName')
  }), [cloudData, filters]);

  const filteredData = useMemo(() => {
    return cloudData.filter(item => {
      const matchMonth = filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
                        (!filters.dateRange[1] || item.date <= filters.dateRange[1]);
      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });
  }, [cloudData, filters]);

  const summary: SalesSummary = useMemo(() => {
    const totalSales = filteredData.reduce((acc, cur) => acc + cur.totalAmount, 0);
    const totalQuantity = filteredData.reduce((acc, cur) => acc + cur.quantity, 0);
    const uniqueOrderIds = Array.from(new Set(filteredData.map(d => d.id))).sort();

    const monthlyMap = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const existing = monthlyMap.get(d.month) || { sales: 0, quantity: 0 };
      monthlyMap.set(d.month, {
        sales: existing.sales + d.totalAmount,
        quantity: existing.quantity + d.quantity
      });
    });
    const monthlyTrend = Array.from(monthlyMap.entries()).map(([name, val]) => ({ name, ...val })).sort((a, b) => a.name.localeCompare(b.name));

    const catMap = new Map<string, number>();
    const catQtyMap = new Map<string, number>();
    filteredData.forEach(d => {
      catMap.set(d.category, (catMap.get(d.category) || 0) + d.totalAmount);
      catQtyMap.set(d.category, (catQtyMap.get(d.category) || 0) + d.quantity);
    });

    const spMap = new Map<string, number>();
    filteredData.forEach(d => spMap.set(d.salesperson, (spMap.get(d.salesperson) || 0) + d.totalAmount));

    return { 
      totalSales, 
      totalQuantity, 
      orderCount: uniqueOrderIds.length, 
      orderIds: uniqueOrderIds, 
      categoryDistribution: Array.from(catMap.entries()).map(([name, value]) => ({ name, value })),
      categoryQuantityDistribution: Array.from(catQtyMap.entries()).map(([name, value]) => ({ name, value })),
      salespersonPerformance: Array.from(spMap.entries()).map(([name, value]) => ({ name, value })).sort((a, b) => b.value - a.value),
      monthlyTrend 
    };
  }, [filteredData]);

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 p-4 text-center">
        <div className="bg-white p-8 rounded-3xl shadow-2xl max-w-md border border-red-100">
          <div className="text-6xl mb-4">🔗</div>
          <h2 className="text-2xl font-black text-slate-900 mb-2">连接受阻</h2>
          <p className="text-slate-500 text-sm mb-6 bg-red-50 p-3 rounded-lg">{error}</p>
          <button onClick={loadCloudData} className="w-full bg-indigo-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-lg">重试连接</button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 pb-12">
      <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-2xl font-black shadow-lg">S</div>
            <h1 className="text-lg font-black text-slate-900">销售数据洞察</h1>
          </div>
          <nav className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setActiveTab('dashboard')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'dashboard' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-900'}`}>分析看板</button>
            <button onClick={() => setActiveTab('table')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'table' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-900'}`}>数据明细</button>
          </nav>
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 pt-8">
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 mb-8">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-sm font-black text-slate-800 uppercase tracking-widest flex items-center gap-2">
              <span className="w-1.5 h-4 bg-indigo-600 rounded-full"></span> 筛选中心
            </h2>
            <div className="flex items-center gap-4">
              <span className="text-xs text-slate-400 font-mono">符合条件: {filteredData.length} 条</span>
              <button onClick={initializeFilters} className="text-[10px] text-red-500 font-bold hover:underline">重置</button>
            </div>
          </div>
          {/* 筛选布局: 月份-客户-销售员-品类-物料-业务日期 */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-6">
            <MultiSelect label="月份" options={dynamicFilterData.months.options} counts={dynamicFilterData.months.counts} selectedValues={filters.months} onChange={(v) => setFilters({...filters, months: v})} />
            <MultiSelect label="客户" options={dynamicFilterData.customers.options} counts={dynamicFilterData.customers.counts} selectedValues={filters.customers} onChange={(v) => setFilters({...filters, customers: v})} />
            <MultiSelect label="销售员" options={dynamicFilterData.salespeople.options} counts={dynamicFilterData.salespeople.counts} selectedValues={filters.salespeople} onChange={(v) => setFilters({...filters, salespeople: v})} />
            <MultiSelect label="品类" options={dynamicFilterData.categories.options} counts={dynamicFilterData.categories.counts} selectedValues={filters.categories} onChange={(v) => setFilters({...filters, categories: v})} />
            <MultiSelect label="物料名称" options={dynamicFilterData.itemNames.options} counts={dynamicFilterData.itemNames.counts} selectedValues={filters.itemNames} onChange={(v) => setFilters({...filters, itemNames: v})} />

            {/* 业务日期放在最后 */}
            <div className="space-y-1.5">
              <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider">业务日期</label>
              <div className="flex items-center gap-1 bg-slate-50 border border-slate-200 rounded-lg px-2 py-1.5 hover:bg-white hover:border-indigo-300 transition-all focus-within:ring-2 focus-within:ring-indigo-100">
                <input 
                  type="date" 
                  value={filters.dateRange[0]} 
                  onChange={(e) => setFilters({...filters, dateRange: [e.target.value, filters.dateRange[1]]})}
                  className="bg-transparent text-[10px] font-bold text-slate-600 outline-none w-full"
                />
                <span className="text-slate-300">-</span>
                <input 
                  type="date" 
                  value={filters.dateRange[1]} 
                  onChange={(e) => setFilters({...filters, dateRange: [filters.dateRange[0], e.target.value]})}
                  className="bg-transparent text-[10px] font-bold text-slate-600 outline-none w-full"
                />
              </div>
            </div>
          </div>
        </section>

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-24 space-y-4">
            <div className="w-12 h-12 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
            <p className="text-slate-500 font-bold tracking-widest uppercase text-xs">正在分析数据...</p>
          </div>
        ) : (
          <div className="animate-in fade-in duration-700">
            {filteredData.length > 0 ? (
              activeTab === 'dashboard' ? (
                <Dashboard summary={summary} filteredData={filteredData} onSelectOrderId={setSelectedOrderId} />
              ) : (
                <DataTable data={filteredData} onSelectOrderId={setSelectedOrderId} />
              )
            ) : (
              <div className="py-32 bg-white rounded-3xl border border-dashed border-slate-200 text-center">
                <div className="text-5xl mb-4">🔎</div>
                <h3 className="text-xl font-bold text-slate-800">未找到匹配数据</h3>
                <p className="text-slate-500 mt-2">请调整筛选器条件</p>
              </div>
            )}
          </div>
        )}
      </main>

      {selectedOrderId && (
        <OrderDetailModal orderId={selectedOrderId} records={cloudData.filter(d => d.id === selectedOrderId)} onClose={() => setSelectedOrderId(null)} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [drillDownMetric, setDrillDownMetric] = useState<'sales' | 'quantity'>('sales');
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  const [localTableFilters, setLocalTableFilters] = useState({ id: '', date: '', customer: '', itemName: '' });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const globalTotals = useMemo(() => {
    return sortedCategorySummary.reduce((acc, cur) => {
      acc.sales += cur.sales;
      acc.quantity += cur.quantity;
      return acc;
    }, { sales: 0, quantity: 0 });
  }, [sortedCategorySummary]);

  const currentTotal = pieMetric === 'sales' ? globalTotals.sales : globalTotals.quantity;

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { customers: [], records: [], drillDownTotal: 0 };

    const customersMap = new Map<string, { sales: number; qty: number }>();
    let records: SalesRecord[] = [];
    let drillDownTotal = 0;

    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        const c = customersMap.get(record.customer) || { sales: 0, qty: 0 };
        customersMap.set(record.customer, { sales: c.sales + record.totalAmount, qty: c.qty + record.quantity });
        records.push(record);
        drillDownTotal += (drillDownMetric === 'sales' ? record.totalAmount : record.quantity);
      }
    });

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ 
        name, 
        sales: val.sales, 
        qty: val.qty, 
        percentage: drillDownTotal > 0 ? (((drillDownMetric === 'sales' ? val.sales : val.qty) / drillDownTotal) * 100).toFixed(1) + '%' : '0%'
      }))
      .sort((a, b) => drillDownMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    if (localTableFilters.id) records = records.filter(r => r.id === localTableFilters.id);
    if (localTableFilters.date) records = records.filter(r => r.date >= localTableFilters.date);
    if (localTableFilters.customer) records = records.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.itemName) records = records.filter(r => r.itemName === localTableFilters.itemName);

    return { customers, records: records.sort((a, b) => b.date.localeCompare(a.date)), drillDownTotal };
  }, [selectedCategory, filteredData, drillDownMetric, localTableFilters]);

  const FilterHeader = ({ label, columnId, options }: { label: string, columnId: keyof typeof localTableFilters, options: string[] }) => (
    <th className="px-3 py-2 text-left relative group">
      <div className="flex items-center gap-1.5">
        <span className="font-bold text-slate-400 uppercase tracking-tighter text-[10px] whitespace-nowrap">{label}</span>
        <button onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)} className={`p-1 rounded transition-all ${!!localTableFilters[columnId] ? 'text-indigo-600' : 'text-slate-300'}`}>
          <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" /></svg>
        </button>
      </div>
      {activeFilterColumn === columnId && (
        <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-48 bg-white rounded-xl shadow-2xl border border-slate-200 z-[3000] overflow-hidden">
          <div className="p-2 border-b border-slate-50 bg-slate-50 flex justify-between items-center text-[10px] font-bold text-slate-400">筛选{label}</div>
          <div className="max-h-48 overflow-y-auto p-1 custom-scrollbar">
            {options.map(opt => (
              <button key={opt} onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }} className={`w-full text-left px-3 py-2 rounded-lg text-xs transition-colors ${localTableFilters[columnId] === opt ? 'bg-indigo-50 text-indigo-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}>{opt}</button>
            ))}
          </div>
        </div>
      )}
    </th>
  );

  const KpiCard = ({ title, value, sub, icon, children }: { title: string; value: string; sub: string; icon: string; children?: React.ReactNode }) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col h-full group">
      <div className="flex justify-between items-start mb-3">
        <div className="p-2.5 bg-indigo-50 rounded-xl text-indigo-600 text-xl group-hover:bg-indigo-600 group-hover:text-white transition-all duration-300">{icon}</div>
        <span className="text-[11px] font-bold text-slate-400 uppercase tracking-widest">{title}</span>
      </div>
      <div className="text-2xl font-black text-slate-900 mb-1">{value}</div>
      <div className="text-xs text-slate-500 mb-4">{sub}</div>
      {children}
    </div>
  );

  return (
    <div className="space-y-8 pb-10">
      {/* KPI 卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <KpiCard title="成交总额" value={`${summary.totalSales.toLocaleString()} CFA`} sub="所选范围总金额" icon="💰" />
        <KpiCard title="出库总量" value={summary.totalQuantity.toLocaleString()} sub="总计物料数量" icon="📦" />
        <KpiCard title="业务单据" value={`${summary.orderCount} 个单号`} sub="关联出库单数" icon="📑">
          <div className="mt-auto max-h-24 overflow-y-auto pr-1 custom-scrollbar border-t border-slate-50 pt-2 flex flex-wrap gap-1.5">
            {summary.orderIds.map(id => (
              <button key={id} onClick={() => onSelectOrderId(id)} className="inline-block px-2 py-0.5 bg-indigo-50 text-indigo-600 text-[10px] font-mono rounded border border-indigo-100 hover:bg-indigo-600 hover:text-white transition-colors">{id}</button>
            ))}
          </div>
        </KpiCard>
      </div>

      {/* 1. 销售趋势分析 - 全宽堆叠 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-8">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">📊 销售趋势全览</h3>
            <p className="text-xs text-slate-400 uppercase font-bold tracking-widest mt-1">Monthly Sales Trend</p>
          </div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setShowCfa(!showCfa)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>金额</button>
            <button onClick={() => setShowQuantity(!showQuantity)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>数量</button>
          </div>
        </div>
        <div className="h-[400px]">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={summary.monthlyTrend} margin={{ left: 0, right: 10, top: 0, bottom: 0 }}>
              <defs>
                <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#6366f1" stopOpacity={0.1}/><stop offset="95%" stopColor="#6366f1" stopOpacity={0}/></linearGradient>
                <linearGradient id="colorQty" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/><stop offset="95%" stopColor="#10b981" stopOpacity={0}/></linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} dy={10} />
              <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#6366f1', fontSize: 10, fontWeight: 'bold'}} />
              <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 10, fontWeight: 'bold'}} />
              <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }} />
              {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" name="金额" stroke="#6366f1" strokeWidth={4} fill="url(#colorSales)" />}
              {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" name="数量" stroke="#10b981" strokeWidth={4} fill="url(#colorQty)" />}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </section>

      {/* 2. 品类分布洞察 - 全宽堆叠 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200 relative min-h-[600px] overflow-hidden">
        <div className="flex justify-between items-center mb-10">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">🧩 品类结构分析</h3>
            <p className="text-xs text-slate-400 uppercase font-bold tracking-widest mt-1">Category Distribution & Drilldown</p>
          </div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'sales' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>金额</button>
            <button onClick={() => setPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>数量</button>
          </div>
        </div>

        <div className="flex flex-col lg:flex-row items-center gap-16">
          <div className="relative w-full lg:w-[450px] h-[450px] flex-shrink-0">
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none text-center">
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">选中汇总</p>
              <p className={`text-3xl font-black ${pieMetric === 'sales' ? 'text-indigo-600' : 'text-emerald-600'}`}>{currentTotal.toLocaleString()}</p>
            </div>
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={sortedCategorySummary} cx="50%" cy="50%" innerRadius={140} outerRadius={200} paddingAngle={4} dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} onClick={(d) => setSelectedCategory(d.name)} stroke="none" style={{ cursor: 'pointer', outline: 'none' }}>
                  {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} opacity={selectedCategory && selectedCategory !== sortedCategorySummary[i].name ? 0.3 : 1} />)}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-2 gap-4">
            {sortedCategorySummary.map((item, idx) => {
              const val = pieMetric === 'sales' ? item.sales : item.quantity;
              const isSelected = selectedCategory === item.name;
              return (
                <button key={item.name} onClick={() => setSelectedCategory(item.name)} className={`flex items-center justify-between p-5 rounded-2xl border transition-all ${isSelected ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl scale-[1.02]' : 'bg-slate-50 border-slate-100 hover:bg-white hover:border-indigo-300'}`}>
                  <div className="flex items-center gap-4 text-left">
                    <div className="w-2.5 h-10 rounded-full" style={{ backgroundColor: isSelected ? '#fff' : COLORS[idx % COLORS.length] }}></div>
                    <div><p className="text-sm font-black">{item.name}</p><p className={`text-[10px] font-bold uppercase ${isSelected ? 'text-indigo-100' : 'text-slate-400'}`}>占比 {(val / currentTotal * 100).toFixed(1)}%</p></div>
                  </div>
                  <p className="text-lg font-mono font-black">{val.toLocaleString()}</p>
                </button>
              );
            })}
          </div>
        </div>

        {selectedCategory && (
          <div className="absolute inset-0 bg-white/98 backdrop-blur-xl z-[2000] p-8 flex flex-col animate-in slide-in-from-bottom duration-500 overflow-hidden">
            <div className="flex items-center justify-between mb-8 pb-4 border-b border-slate-100">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-xl">🎯</div>
                <div><h4 className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">Detail View</h4><h3 className="text-2xl font-black text-slate-900">{selectedCategory}</h3></div>
              </div>
              <button onClick={() => setSelectedCategory(null)} className="flex items-center gap-2 px-6 py-3 bg-slate-100 hover:bg-red-50 hover:text-red-600 rounded-2xl text-sm font-bold transition-all">关闭下钻</button>
            </div>
            <div className="flex-1 flex gap-8 overflow-hidden">
              <div className="w-1/3 flex flex-col">
                <h5 className="text-xs font-black text-slate-800 uppercase tracking-wider mb-4">🏆 核心客户分布</h5>
                <div className="flex-1 bg-slate-50/50 rounded-2xl p-4 border border-slate-100">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={drillDownData.customers.slice(0, 8)} layout="vertical" margin={{ left: 0, right: 60 }}>
                      <XAxis type="number" hide /><YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={80} tick={{fill: '#475569', fontSize: 11, fontWeight: 'bold'}} />
                      <Tooltip /><Bar dataKey={drillDownMetric === 'sales' ? 'sales' : 'qty'} fill="#6366f1" radius={[0, 8, 8, 0]} barSize={20}>
                        {drillDownData.customers.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                        <LabelList dataKey="percentage" position="right" fill="#94a3b8" fontSize={10} fontWeight="black" offset={10} />
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
              <div className="flex-1 flex flex-col overflow-hidden">
                <h5 className="text-xs font-black text-slate-800 uppercase tracking-wider mb-4">📑 关联交易明细</h5>
                <div className="flex-1 bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden flex flex-col">
                  <div className="overflow-auto flex-1 custom-scrollbar">
