                    </table>
                  </div>
                  <div className="px-6 py-3 bg-slate-50 border-t border-slate-100 flex justify-between items-center text-[10px] font-bold text-slate-400">
                    <span>记录数: {drillDownData.records.length}</span><span className="text-indigo-600 font-black tracking-widest">小计: {drillDownData.drillDownTotal.toLocaleString()}</span>
                  </div>
                </div>
              </div>
