          </div>
        )}
      </section>

      {/* 3. 销售绩效排行 - 全宽堆叠 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-10">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">🏆 销售精英榜</h3>
            <p className="text-xs text-slate-400 uppercase font-bold tracking-widest mt-1">Individual Performance Ranking</p>
