          <span className="px-4 py-1.5 bg-indigo-50 text-indigo-600 rounded-full text-[10px] font-black border border-indigo-100 uppercase tracking-widest">金额单位: CFA</span>
        </div>
        <div className="h-[450px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical" margin={{ left: 20, right: 100, top: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide /><YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={100} tick={{fill: '#1e293b', fontWeight: 800, fontSize: 13}} />
              <Tooltip cursor={{fill: '#f8fafc'}} />
