import React, { useState, useMemo, useEffect } from 'react';
import { FilterState, SalesSummary, SalesRecord } from './types';
import Dashboard from './components/Dashboard';
import DataTable from './components/DataTable';
import MultiSelect from './components/MultiSelect';
import OrderDetailModal from './components/OrderDetailModal';
import { fetchSalesData } from './services/dataService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'table'>('dashboard');
  const [cloudData, setCloudData] = useState<SalesRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedOrderId, setSelectedOrderId] = useState<string | null>(null);

  const [filters, setFilters] = useState<FilterState>({
    months: [],
    dateRange: ['', ''],
    customers: [],
    salespeople: [],
    categories: [],
    itemNames: []
  });

  const loadCloudData = async () => {
    try {
      setIsLoading(true);
      setError(null);
      const data = await fetchSalesData();
      setCloudData(data);
      initializeFilters();
    } catch (err) {
      const message = err instanceof Error ? err.message : '连接数据源失败';
      setError(message);
    } finally {
      setIsLoading(false);
    }
  };

  const initializeFilters = () => {
    setFilters({
      months: [],
      dateRange: ['', ''],
      customers: [],
      salespeople: [],
      categories: [],
      itemNames: []
    });
  };

  useEffect(() => {
    loadCloudData();
  }, []);

  const getDynamicDimensionData = (dimension: keyof SalesRecord) => {
    const filteredByOthers = cloudData.filter(item => {
      const matchMonth = dimension === 'month' || filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = dimension === 'salesperson' || filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = dimension === 'category' || filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = dimension === 'customer' || filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = dimension === 'itemName' || filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (
        (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
        (!filters.dateRange[1] || item.date <= filters.dateRange[1])
      );
      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });

    const counts: Record<string, number> = {};
    filteredByOthers.forEach(item => {
      const val = item[dimension] as string;
      if (val) counts[val] = (counts[val] || 0) + 1;
    });

    const options = Array.from(new Set(cloudData.map(d => d[dimension] as string))).sort();
    if (dimension === 'month') options.reverse();
    return { options, counts };
  };

  const dynamicFilterData = useMemo(() => ({
    months: getDynamicDimensionData('month'),
    customers: getDynamicDimensionData('customer'),
    salespeople: getDynamicDimensionData('salesperson'),
    categories: getDynamicDimensionData('category'),
    itemNames: getDynamicDimensionData('itemName')
  }), [cloudData, filters]);

  const filteredData = useMemo(() => {
    return cloudData.filter(item => {
      const matchMonth = filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
                        (!filters.dateRange[1] || item.date <= filters.dateRange[1]);
      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });
  }, [cloudData, filters]);

  const summary: SalesSummary = useMemo(() => {
    const totalSales = filteredData.reduce((acc, cur) => acc + cur.totalAmount, 0);
    const totalQuantity = filteredData.reduce((acc, cur) => acc + cur.quantity, 0);
    const uniqueOrderIds = Array.from(new Set(filteredData.map(d => d.id))).sort();

    const monthlyMap = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const existing = monthlyMap.get(d.month) || { sales: 0, quantity: 0 };
      monthlyMap.set(d.month, {
        sales: existing.sales + d.totalAmount,
        quantity: existing.quantity + d.quantity
      });
    });
    const monthlyTrend = Array.from(monthlyMap.entries()).map(([name, val]) => ({ name, ...val })).sort((a, b) => a.name.localeCompare(b.name));

    const catMap = new Map<string, number>();
    const catQtyMap = new Map<string, number>();
    filteredData.forEach(d => {
      catMap.set(d.category, (catMap.get(d.category) || 0) + d.totalAmount);
      catQtyMap.set(d.category, (catQtyMap.get(d.category) || 0) + d.quantity);
    });

    const spMap = new Map<string, number>();
    filteredData.forEach(d => spMap.set(d.salesperson, (spMap.get(d.salesperson) || 0) + d.totalAmount));

    return { 
      totalSales, 
      totalQuantity, 
      orderCount: uniqueOrderIds.length, 
      orderIds: uniqueOrderIds, 
      categoryDistribution: Array.from(catMap.entries()).map(([name, value]) => ({ name, value })),
      categoryQuantityDistribution: Array.from(catQtyMap.entries()).map(([name, value]) => ({ name, value })),
      salespersonPerformance: Array.from(spMap.entries()).map(([name, value]) => ({ name, value })).sort((a, b) => b.value - a.value),
      monthlyTrend 
    };
  }, [filteredData]);

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 p-4">
        <div className="bg-white p-8 rounded-3xl shadow-xl max-w-md border border-red-100 text-center">
          <div className="text-5xl mb-4">⚠️</div>
          <h2 className="text-xl font-bold text-slate-900 mb-2">服务暂时不可用</h2>
          <p className="text-slate-500 text-sm mb-6">{error}</p>
          <button onClick={loadCloudData} className="w-full bg-indigo-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-indigo-700 transition-all">尝试重新连接</button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 pb-12">
      <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-[100]">
        <div className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-2xl font-black shadow-lg shadow-indigo-100">S</div>
            <h1 className="text-lg font-black text-slate-900">TTP 销售数据分析</h1>
          </div>
          <nav className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setActiveTab('dashboard')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'dashboard' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-900'}`}>分析中心</button>
            <button onClick={() => setActiveTab('table')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'table' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-900'}`}>数据清单</button>
          </nav>
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 pt-8">
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 mb-8">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-sm font-black text-slate-800 uppercase tracking-[0.2em] flex items-center gap-2">
              <span className="w-1.5 h-4 bg-indigo-600 rounded-full"></span> 筛选中心
            </h2>
            <div className="flex items-center gap-4 text-xs font-bold">
               <span className="text-slate-400">有效记录: <span className="text-indigo-600 font-mono">{filteredData.length}</span> 条</span>
               <button onClick={initializeFilters} className="text-red-500 hover:underline">重置所有条件</button>
            </div>
          </div>

          {/* 筛选布局调整：月份 -> 客户 -> 销售员 -> 品类 -> 物料 -> 业务日期 (xl:grid-cols-6) */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-6">
            <MultiSelect label="月份" options={dynamicFilterData.months.options} counts={dynamicFilterData.months.counts} selectedValues={filters.months} onChange={(v) => setFilters({...filters, months: v})} />
            <MultiSelect label="客户" options={dynamicFilterData.customers.options} counts={dynamicFilterData.customers.counts} selectedValues={filters.customers} onChange={(v) => setFilters({...filters, customers: v})} />
            <MultiSelect label="销售员" options={dynamicFilterData.salespeople.options} counts={dynamicFilterData.salespeople.counts} selectedValues={filters.salespeople} onChange={(v) => setFilters({...filters, salespeople: v})} />
            <MultiSelect label="品类" options={dynamicFilterData.categories.options} counts={dynamicFilterData.categories.counts} selectedValues={filters.categories} onChange={(v) => setFilters({...filters, categories: v})} />
            <MultiSelect label="物料名称" options={dynamicFilterData.itemNames.options} counts={dynamicFilterData.itemNames.counts} selectedValues={filters.itemNames} onChange={(v) => setFilters({...filters, itemNames: v})} />

            {/* 业务日期置末位 */}
            <div className="space-y-1.5">
              <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider">业务日期</label>
              <div className="flex items-center gap-1 bg-slate-50 border border-slate-200 rounded-lg px-2 py-1.5 hover:bg-white hover:border-indigo-300 transition-all focus-within:ring-2 focus-within:ring-indigo-100">
                <input 
                  type="date" 
                  value={filters.dateRange[0]} 
                  onChange={(e) => setFilters({...filters, dateRange: [e.target.value, filters.dateRange[1]]})}
                  className="bg-transparent text-[10px] font-bold text-slate-600 outline-none w-full cursor-pointer"
                />
                <span className="text-slate-300">-</span>
                <input 
                  type="date" 
                  value={filters.dateRange[1]} 
                  onChange={(e) => setFilters({...filters, dateRange: [filters.dateRange[0], e.target.value]})}
                  className="bg-transparent text-[10px] font-bold text-slate-600 outline-none w-full cursor-pointer"
                />
              </div>
            </div>
          </div>
        </section>

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-32 space-y-4">
            <div className="w-12 h-12 border-4 border-slate-200 border-t-indigo-600 rounded-full animate-spin"></div>
            <p className="text-slate-400 font-bold tracking-widest uppercase text-xs">正在拉取实时数据...</p>
          </div>
        ) : (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
            {filteredData.length > 0 ? (
              activeTab === 'dashboard' ? (
                <Dashboard summary={summary} filteredData={filteredData} onSelectOrderId={setSelectedOrderId} />
              ) : (
                <DataTable data={filteredData} onSelectOrderId={setSelectedOrderId} />
              )
            ) : (
              <div className="py-32 bg-white rounded-3xl border border-dashed border-slate-200 text-center">
                <div className="text-5xl mb-4">🔎</div>
                <h3 className="text-xl font-bold text-slate-800">未检索到数据</h3>
                <p className="text-slate-500 mt-2">请尝试放宽筛选条件或检查日期范围</p>
              </div>
            )}
          </div>
        )}
      </main>

      {selectedOrderId && (
        <OrderDetailModal orderId={selectedOrderId} records={cloudData.filter(d => d.id === selectedOrderId)} onClose={() => setSelectedOrderId(null)} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  // 下钻视图局部筛选状态 (涵盖所有核心数据)
  const [localTableFilters, setLocalTableFilters] = useState({ 
    id: '', 
    date: '', 
    customer: '', 
    salesperson: '',
    itemName: '' 
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const globalTotals = useMemo(() => {
    return sortedCategorySummary.reduce((acc, cur) => {
      acc.sales += cur.sales;
      acc.quantity += cur.quantity;
      return acc;
    }, { sales: 0, quantity: 0 });
  }, [sortedCategorySummary]);

  const currentTotal = pieMetric === 'sales' ? globalTotals.sales : globalTotals.quantity;

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { customers: [], records: [], drillDownTotal: 0 };

    const customersMap = new Map<string, { sales: number; qty: number }>();
    let records: SalesRecord[] = [];

    // 该品类原始记录池
    filteredData.forEach(record => {
      if (record.category === selectedCategory) {
        const c = customersMap.get(record.customer) || { sales: 0, qty: 0 };
        customersMap.set(record.customer, { sales: c.sales + record.totalAmount, qty: c.qty + record.quantity });
        records.push(record);
      }
    });

    // 计算客户贡献分布
    const catTotal = records.reduce((s, r) => s + (pieMetric === 'sales' ? r.totalAmount : r.quantity), 0);
    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ 
        name, 
        sales: val.sales, 
        qty: val.qty, 
        percentage: catTotal > 0 ? (((pieMetric === 'sales' ? val.sales : val.qty) / catTotal) * 100).toFixed(1) + '%' : '0%'
      }))
      .sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    // 应用表格内的局部筛选 (所有字段均支持模糊匹配)
    let filteredRecords = [...records];
    if (localTableFilters.id) filteredRecords = filteredRecords.filter(r => r.id.toLowerCase().includes(localTableFilters.id.toLowerCase()));
    if (localTableFilters.date) filteredRecords = filteredRecords.filter(r => r.date.includes(localTableFilters.date));
    if (localTableFilters.customer) filteredRecords = filteredRecords.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.salesperson) filteredRecords = filteredRecords.filter(r => r.salesperson === localTableFilters.salesperson);
    if (localTableFilters.itemName) filteredRecords = filteredRecords.filter(r => r.itemName.toLowerCase().includes(localTableFilters.itemName.toLowerCase()));

    const drillDownTotal = filteredRecords.reduce((s, r) => s + (pieMetric === 'sales' ? r.totalAmount : r.quantity), 0);

    return { customers, records: filteredRecords.sort((a, b) => b.date.localeCompare(a.date)), drillDownTotal };
  }, [selectedCategory, filteredData, pieMetric, localTableFilters]);

  const FilterHeader = ({ label, columnId, options }: { label: string, columnId: keyof typeof localTableFilters, options: string[] }) => (
    <th className="px-4 py-3 text-left relative group bg-slate-50 border-b border-slate-100">
      <div className="flex items-center gap-1.5">
        <span className="font-bold text-slate-400 uppercase tracking-widest text-[10px] whitespace-nowrap">{label}</span>
        <button 
          onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)} 
          className={`p-1 rounded-md transition-all ${!!localTableFilters[columnId] ? 'text-indigo-600 bg-indigo-50 shadow-sm' : 'text-slate-300 hover:text-indigo-400'}`}
        >
          <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" /></svg>
        </button>
      </div>
      {activeFilterColumn === columnId && (
        <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-56 bg-white rounded-xl shadow-2xl border border-slate-200 z-[3000] overflow-hidden animate-in fade-in zoom-in duration-150">
          <div className="p-2.5 border-b border-slate-50 bg-slate-50 flex justify-between items-center text-[10px] font-black text-slate-400 uppercase tracking-widest">
            {label} 过滤控制
          </div>
          <div className="max-h-60 overflow-y-auto p-1 custom-scrollbar">
            <button 
              onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: '' })); setActiveFilterColumn(null); }} 
              className="w-full text-left px-3 py-2 rounded-lg text-[11px] text-slate-400 italic hover:bg-slate-50"
            >
              清除该列筛选
            </button>
            {options.map(opt => (
              <button 
                key={opt} 
                onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }} 
                className={`w-full text-left px-3 py-2 rounded-lg text-xs transition-colors ${localTableFilters[columnId] === opt ? 'bg-indigo-50 text-indigo-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
              >
                {opt}
              </button>
            ))}
          </div>
        </div>
      )}
    </th>
  );

  return (
    <div className="space-y-10 pb-16">
      {/* KPI 指标栏 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-6">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-6">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">物料出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-6">
           <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
           <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">业务单据总数</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div>
        </div>
      </div>

      {/* 第一行：销售趋势分析 (全宽) */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-8">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">📈 业绩增长趋势</h3>
            <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 font-mono">Monthly Performance History</p>
          </div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setShowCfa(!showCfa)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>金额 (CFA)</button>
            <button onClick={() => setShowQuantity(!showQuantity)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>数量</button>
          </div>
        </div>
        <div className="h-[450px]">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={summary.monthlyTrend} margin={{ left: 0, right: 10, top: 0, bottom: 0 }}>
              <defs>
                <linearGradient id="gSales" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#6366f1" stopOpacity={0.15}/><stop offset="95%" stopColor="#6366f1" stopOpacity={0}/></linearGradient>
                <linearGradient id="gQty" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#10b981" stopOpacity={0.15}/><stop offset="95%" stopColor="#10b981" stopOpacity={0}/></linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} dy={10} />
              <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#6366f1', fontSize: 10, fontWeight: 'bold'}} />
              <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 10, fontWeight: 'bold'}} />
              <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }} />
              {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" name="销售额" stroke="#6366f1" strokeWidth={4} fill="url(#gSales)" />}
              {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" name="出库量" stroke="#10b981" strokeWidth={4} fill="url(#gQty)" />}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </section>

      {/* 第二行：品类分布洞察 (全宽，带联动下钻) */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200 relative min-h-[600px] overflow-hidden">
        <div className="flex justify-between items-center mb-10">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">🧩 品类业务构成</h3>
            <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 font-mono">Market Share Analysis</p>
          </div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'sales' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>按金额</button>
            <button onClick={() => setPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>按数量</button>
          </div>
        </div>

        <div className="flex flex-col xl:flex-row items-center gap-16">
          <div className="relative w-full xl:w-[480px] h-[480px] flex-shrink-0">
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none text-center">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">选中品类小计</p>
              <p className={`text-4xl font-black ${pieMetric === 'sales' ? 'text-indigo-600' : 'text-emerald-600'}`}>{currentTotal.toLocaleString()}</p>
              <p className="text-[10px] font-bold text-slate-300 tracking-[0.2em] mt-1">{pieMetric === 'sales' ? 'CFA' : 'UNITS'}</p>
            </div>
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={sortedCategorySummary} cx="50%" cy="50%" innerRadius={150} outerRadius={210} paddingAngle={4} dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} onClick={(d) => setSelectedCategory(d.name)} stroke="none" style={{ cursor: 'pointer', outline: 'none' }}>
                  {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} opacity={selectedCategory && selectedCategory !== sortedCategorySummary[i].name ? 0.3 : 1} />)}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-2 gap-4">
            {sortedCategorySummary.map((item, idx) => {
              const val = pieMetric === 'sales' ? item.sales : item.quantity;
              const isSelected = selectedCategory === item.name;
              return (
                <button key={item.name} onClick={() => setSelectedCategory(item.name)} className={`flex items-center justify-between p-5 rounded-2xl border transition-all ${isSelected ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl scale-[1.02]' : 'bg-slate-50 border-slate-100 hover:bg-white hover:border-indigo-300'}`}>
                  <div className="flex items-center gap-4 text-left min-w-0">
                    <div className="w-2.5 h-10 rounded-full flex-shrink-0" style={{ backgroundColor: isSelected ? '#fff' : COLORS[idx % COLORS.length] }}></div>
                    <div className="min-w-0"><p className="text-sm font-black truncate">{item.name}</p><p className={`text-[10px] font-bold uppercase tracking-tight ${isSelected ? 'text-indigo-100' : 'text-slate-400'}`}>占比 {(val / currentTotal * 100).toFixed(1)}%</p></div>
                  </div>
                  <p className="text-lg font-mono font-black">{val.toLocaleString()}</p>
                </button>
              );
            })}
          </div>
        </div>

        {/* 重点重构：上下布局的下钻详情视图 */}
        {selectedCategory && (
