                    <div className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">当前筛选总计: <span className="text-slate-900 font-black text-xs">{drillDownData.drillDownTotal.toLocaleString()} {pieMetric === 'sales' ? 'CFA' : '件'}</span></div>
