import React, { useState, useMemo, useEffect } from 'react';
import { FilterState, SalesSummary, SalesRecord } from './types';
import Dashboard from './components/Dashboard';
import DataTable from './components/DataTable';
import MultiSelect from './components/MultiSelect';
import OrderDetailModal from './components/OrderDetailModal';
import { fetchSalesData } from './services/dataService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'table'>('dashboard');
  const [cloudData, setCloudData] = useState<SalesRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedOrderId, setSelectedOrderId] = useState<string | null>(null);

  const [filters, setFilters] = useState<FilterState>({
    months: [],
    dateRange: ['', ''],
    customers: [],
    salespeople: [],
    categories: [],
    itemNames: []
  });

  const loadCloudData = async () => {
    try {
      setIsLoading(true);
      setError(null);
      const data = await fetchSalesData();
      setCloudData(data);
      initializeFilters();
    } catch (err) {
      const message = err instanceof Error ? err.message : '连接数据源失败';
      setError(message);
    } finally {
      setIsLoading(false);
    }
  };

  const initializeFilters = () => {
    setFilters({
      months: [],
      dateRange: ['', ''],
      customers: [],
      salespeople: [],
      categories: [],
      itemNames: []
    });
  };

  useEffect(() => {
    loadCloudData();
  }, []);

  /**
   * 级联筛选核心逻辑：
   * 计算某个维度的备选项时，需要应用除该维度自身以外的所有其他筛选条件。
   */
  const getCascadingDimensionData = (dimension: keyof SalesRecord) => {
    const filteredByOthers = cloudData.filter(item => {
      const matchMonth = dimension === 'month' || filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = dimension === 'salesperson' || filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = dimension === 'category' || filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = dimension === 'customer' || filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = dimension === 'itemName' || filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (
        (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
        (!filters.dateRange[1] || item.date <= filters.dateRange[1])
      );
      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });

    const counts: Record<string, number> = {};
    filteredByOthers.forEach(item => {
      const val = item[dimension] as string;
      if (val) counts[val] = (counts[val] || 0) + 1;
    });

    // 选项列表：仅显示当前环境下有数据的选项，并按逻辑排序
    const options = Array.from(new Set(filteredByOthers.map(d => d[dimension] as string))).sort();
    if (dimension === 'month') options.reverse();

    // 如果某个已选中的值在当前级联结果中没有数据了，我们依然保留它在 options 中，以便用户取消选择
    const selectedButEmpty = filters[dimension === 'itemName' ? 'itemNames' : dimension === 'salesperson' ? 'salespeople' : (dimension + 's') as keyof FilterState] as string[];
    if (Array.isArray(selectedButEmpty)) {
      selectedButEmpty.forEach(val => {
        if (!options.includes(val)) options.push(val);
      });
    }

    return { options: options.sort(), counts };
  };

  const dynamicFilterData = useMemo(() => ({
    months: getCascadingDimensionData('month'),
    customers: getCascadingDimensionData('customer'),
    salespeople: getCascadingDimensionData('salesperson'),
    categories: getCascadingDimensionData('category'),
    itemNames: getCascadingDimensionData('itemName')
  }), [cloudData, filters]);

  const filteredData = useMemo(() => {
    return cloudData.filter(item => {
      const matchMonth = filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
                        (!filters.dateRange[1] || item.date <= filters.dateRange[1]);
      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });
  }, [cloudData, filters]);

  const summary: SalesSummary = useMemo(() => {
    const totalSales = filteredData.reduce((acc, cur) => acc + cur.totalAmount, 0);
    const totalQuantity = filteredData.reduce((acc, cur) => acc + cur.quantity, 0);
    const uniqueOrderIds = Array.from(new Set(filteredData.map(d => d.id))).sort();

    const monthlyMap = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const existing = monthlyMap.get(d.month) || { sales: 0, quantity: 0 };
      monthlyMap.set(d.month, {
        sales: existing.sales + d.totalAmount,
        quantity: existing.quantity + d.quantity
      });
    });
    const monthlyTrend = Array.from(monthlyMap.entries()).map(([name, val]) => ({ name, ...val })).sort((a, b) => a.name.localeCompare(b.name));

    const catMap = new Map<string, number>();
    const catQtyMap = new Map<string, number>();
    filteredData.forEach(d => {
      catMap.set(d.category, (catMap.get(d.category) || 0) + d.totalAmount);
      catQtyMap.set(d.category, (catQtyMap.get(d.category) || 0) + d.quantity);
    });

    const spMap = new Map<string, number>();
    filteredData.forEach(d => spMap.set(d.salesperson, (spMap.get(d.salesperson) || 0) + d.totalAmount));

    return { 
      totalSales, 
      totalQuantity, 
      orderCount: uniqueOrderIds.length, 
      orderIds: uniqueOrderIds, 
      categoryDistribution: Array.from(catMap.entries()).map(([name, value]) => ({ name, value })),
      categoryQuantityDistribution: Array.from(catQtyMap.entries()).map(([name, value]) => ({ name, value })),
      salespersonPerformance: Array.from(spMap.entries()).map(([name, value]) => ({ name, value })).sort((a, b) => b.value - a.value),
      monthlyTrend 
    };
  }, [filteredData]);

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 p-4">
        <div className="bg-white p-8 rounded-3xl shadow-xl max-w-md border border-red-100 text-center">
          <div className="text-5xl mb-4">⚠️</div>
          <h2 className="text-xl font-bold text-slate-900 mb-2">服务暂时不可用</h2>
          <p className="text-slate-500 text-sm mb-6">{error}</p>
          <button onClick={loadCloudData} className="w-full bg-indigo-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-indigo-700 transition-all">尝试重新连接</button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 pb-12">
      <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-[100]">
        <div className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-2xl font-black shadow-lg shadow-indigo-100">S</div>
            <h1 className="text-lg font-black text-slate-900">TTP 销售数据分析</h1>
          </div>
          <nav className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setActiveTab('dashboard')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'dashboard' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-900'}`}>分析中心</button>
            <button onClick={() => setActiveTab('table')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'table' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-900'}`}>数据清单</button>
          </nav>
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 pt-8">
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 mb-8">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-sm font-black text-slate-800 uppercase tracking-[0.2em] flex items-center gap-2">
              <span className="w-1.5 h-4 bg-indigo-600 rounded-full"></span> 筛选中心
            </h2>
            <div className="flex items-center gap-4 text-xs font-bold">
               <span className="text-slate-400">当前匹配: <span className="text-indigo-600 font-mono">{filteredData.length}</span> 行</span>
               <button onClick={initializeFilters} className="text-red-500 hover:underline">重置所有条件</button>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-6">
            <MultiSelect label="月份" options={dynamicFilterData.months.options} counts={dynamicFilterData.months.counts} selectedValues={filters.months} onChange={(v) => setFilters({...filters, months: v})} />
            <MultiSelect label="客户" options={dynamicFilterData.customers.options} counts={dynamicFilterData.customers.counts} selectedValues={filters.customers} onChange={(v) => setFilters({...filters, customers: v})} />
            <MultiSelect label="销售员" options={dynamicFilterData.salespeople.options} counts={dynamicFilterData.salespeople.counts} selectedValues={filters.salespeople} onChange={(v) => setFilters({...filters, salespeople: v})} />
            <MultiSelect label="品类" options={dynamicFilterData.categories.options} counts={dynamicFilterData.categories.counts} selectedValues={filters.categories} onChange={(v) => setFilters({...filters, categories: v})} />
            <MultiSelect label="物料名称" options={dynamicFilterData.itemNames.options} counts={dynamicFilterData.itemNames.counts} selectedValues={filters.itemNames} onChange={(v) => setFilters({...filters, itemNames: v})} />

            <div className="space-y-1.5">
              <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider">业务日期</label>
              <div className="flex items-center gap-1 bg-slate-50 border border-slate-200 rounded-lg px-2 py-1.5 hover:bg-white hover:border-indigo-300 transition-all focus-within:ring-2 focus-within:ring-indigo-100">
                <input 
                  type="date" 
                  value={filters.dateRange[0]} 
                  onChange={(e) => setFilters({...filters, dateRange: [e.target.value, filters.dateRange[1]]})}
                  className="bg-transparent text-[10px] font-bold text-slate-600 outline-none w-full cursor-pointer"
                />
                <span className="text-slate-300">-</span>
                <input 
                  type="date" 
                  value={filters.dateRange[1]} 
                  onChange={(e) => setFilters({...filters, dateRange: [filters.dateRange[0], e.target.value]})}
                  className="bg-transparent text-[10px] font-bold text-slate-600 outline-none w-full cursor-pointer"
                />
              </div>
            </div>
          </div>
        </section>

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-32 space-y-4">
            <div className="w-12 h-12 border-4 border-slate-200 border-t-indigo-600 rounded-full animate-spin"></div>
            <p className="text-slate-400 font-bold tracking-widest uppercase text-xs">正在刷新级联数据...</p>
          </div>
        ) : (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
            {filteredData.length > 0 ? (
              activeTab === 'dashboard' ? (
                <Dashboard summary={summary} filteredData={filteredData} onSelectOrderId={setSelectedOrderId} />
              ) : (
                <DataTable data={filteredData} onSelectOrderId={setSelectedOrderId} />
              )
            ) : (
              <div className="py-32 bg-white rounded-3xl border border-dashed border-slate-200 text-center">
                <div className="text-5xl mb-4">🔎</div>
                <h3 className="text-xl font-bold text-slate-800">未检索到数据</h3>
                <p className="text-slate-500 mt-2">级联筛选已自动排除了无结果组合，请尝试重置或调整条件</p>
                <button onClick={initializeFilters} className="mt-6 px-6 py-2 bg-indigo-600 text-white rounded-xl text-sm font-bold shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all">重置所有筛选</button>
              </div>
            )}
          </div>
        )}
      </main>

      {selectedOrderId && (
        <OrderDetailModal orderId={selectedOrderId} records={cloudData.filter(d => d.id === selectedOrderId)} onClose={() => setSelectedOrderId(null)} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  // 下钻视图局部筛选状态
  const [localTableFilters, setLocalTableFilters] = useState({ 
    id: '', 
    date: '', 
    customer: '', 
    salesperson: '',
    itemName: '' 
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const globalTotals = useMemo(() => {
    return sortedCategorySummary.reduce((acc, cur) => {
      acc.sales += cur.sales;
      acc.quantity += cur.quantity;
      return acc;
    }, { sales: 0, quantity: 0 });
  }, [sortedCategorySummary]);

  const currentTotal = pieMetric === 'sales' ? globalTotals.sales : globalTotals.quantity;

  // 下钻核心数据计算
  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { customers: [], records: [], drillDownTotal: 0, cascadingOptions: {} };

    // 1. 获取该品类下的初始池
    const baseRecords = filteredData.filter(r => r.category === selectedCategory);

    // 2. 计算当前完全过滤后的记录 (用于显示表格内容)
    const filteredRecords = baseRecords.filter(r => {
      const matchId = !localTableFilters.id || r.id === localTableFilters.id;
      const matchDate = !localTableFilters.date || r.date === localTableFilters.date;
      const matchCustomer = !localTableFilters.customer || r.customer === localTableFilters.customer;
      const matchSalesperson = !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
      const matchItemName = !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
      return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
    });

    // 3. 计算级联筛选器的备选项 (基于排除自身的逻辑)
    const getOptionsFor = (key: keyof typeof localTableFilters) => {
      const tempFiltered = baseRecords.filter(r => {
        const matchId = key === 'id' || !localTableFilters.id || r.id === localTableFilters.id;
        const matchDate = key === 'date' || !localTableFilters.date || r.date === localTableFilters.date;
        const matchCustomer = key === 'customer' || !localTableFilters.customer || r.customer === localTableFilters.customer;
        const matchSalesperson = key === 'salesperson' || !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
        const matchItemName = key === 'itemName' || !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
        return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
      });
      return Array.from(new Set(tempFiltered.map(r => r[key === 'itemName' ? 'itemName' : key as keyof SalesRecord] as string))).sort();
    };

    const cascadingOptions = {
      id: getOptionsFor('id'),
      date: getOptionsFor('date').reverse(),
      customer: getOptionsFor('customer'),
      salesperson: getOptionsFor('salesperson'),
      itemName: getOptionsFor('itemName')
    };

    // 4. 计算客户贡献度 (基于该品类所有记录)
    const customersMap = new Map<string, { sales: number; qty: number }>();
    baseRecords.forEach(record => {
      const c = customersMap.get(record.customer) || { sales: 0, qty: 0 };
      customersMap.set(record.customer, { sales: c.sales + record.totalAmount, qty: c.qty + record.quantity });
    });
    const catTotal = baseRecords.reduce((s, r) => s + (pieMetric === 'sales' ? r.totalAmount : r.quantity), 0);
    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ 
        name, 
        sales: val.sales, 
        qty: val.qty, 
        percentage: catTotal > 0 ? (((pieMetric === 'sales' ? val.sales : val.qty) / catTotal) * 100).toFixed(1) + '%' : '0%'
      }))
      .sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const drillDownTotal = filteredRecords.reduce((s, r) => s + (pieMetric === 'sales' ? r.totalAmount : r.quantity), 0);

    return { 
      customers, 
      records: filteredRecords.sort((a, b) => b.date.localeCompare(a.date)), 
      drillDownTotal,
      cascadingOptions 
    };
  }, [selectedCategory, filteredData, pieMetric, localTableFilters]);

  const FilterHeader = ({ label, columnId }: { label: string, columnId: keyof typeof localTableFilters }) => {
    const options = (drillDownData.cascadingOptions as any)[columnId] || [];
    const isSelected = !!localTableFilters[columnId];

    return (
      <th className="px-4 py-3 text-left relative group bg-slate-50 border-b border-slate-100">
        <div className="flex items-center gap-1.5">
          <span className="font-bold text-slate-400 uppercase tracking-widest text-[10px] whitespace-nowrap">{label}</span>
          <button 
            onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)} 
            className={`p-1 rounded-md transition-all ${isSelected ? 'text-indigo-600 bg-indigo-50 shadow-sm' : 'text-slate-300 hover:text-indigo-400'}`}
          >
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" /></svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-64 bg-white rounded-xl shadow-2xl border border-slate-200 z-[3000] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2.5 border-b border-slate-50 bg-slate-50 flex justify-between items-center">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label} 级联筛选</span>
              {isSelected && <button onClick={() => setLocalTableFilters(p => ({...p, [columnId]: ''}))} className="text-[10px] font-bold text-red-500 hover:underline">清除</button>}
            </div>
            <div className="max-h-64 overflow-y-auto p-1 custom-scrollbar">
              {options.length === 0 ? (
                <div className="px-3 py-4 text-center text-xs text-slate-400 italic">当前组合下无可选项</div>
              ) : (
                options.map((opt: string) => (
                  <button 
                    key={opt} 
                    onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }} 
                    className={`w-full text-left px-3 py-2 rounded-lg text-xs transition-colors flex items-center justify-between ${localTableFilters[columnId] === opt ? 'bg-indigo-50 text-indigo-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
                  >
                    <span className="truncate pr-2">{opt}</span>
                    {localTableFilters[columnId] === opt && <svg className="w-3 h-3 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20"><path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" /></svg>}
                  </button>
                ))
              )}
            </div>
          </div>
        )}
      </th>
    );
  };

  return (
    <div className="space-y-10 pb-16">
      {/* KPI 指标栏 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-6">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-6">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">物料出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-6">
           <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
           <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">业务单据总数</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div>
        </div>
      </div>

      {/* 第一行：销售趋势分析 (全宽) */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-8">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">📈 业绩增长趋势</h3>
            <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 font-mono">Monthly Performance History</p>
          </div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setShowCfa(!showCfa)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>金额 (CFA)</button>
            <button onClick={() => setShowQuantity(!showQuantity)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>数量</button>
          </div>
        </div>
        <div className="h-[450px]">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={summary.monthlyTrend} margin={{ left: 0, right: 10, top: 0, bottom: 0 }}>
              <defs>
                <linearGradient id="gSales" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#6366f1" stopOpacity={0.15}/><stop offset="95%" stopColor="#6366f1" stopOpacity={0}/></linearGradient>
                <linearGradient id="gQty" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#10b981" stopOpacity={0.15}/><stop offset="95%" stopColor="#10b981" stopOpacity={0}/></linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} dy={10} />
              <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#6366f1', fontSize: 10, fontWeight: 'bold'}} />
              <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 10, fontWeight: 'bold'}} />
              <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }} />
              {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" name="销售额" stroke="#6366f1" strokeWidth={4} fill="url(#gSales)" />}
              {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" name="出库量" stroke="#10b981" strokeWidth={4} fill="url(#gQty)" />}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </section>

      {/* 第二行：品类分布洞察 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200 relative min-h-[600px] overflow-hidden">
        <div className="flex justify-between items-center mb-10">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">🧩 品类业务构成</h3>
            <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 font-mono">Market Share Analysis</p>
          </div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'sales' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>按金额</button>
            <button onClick={() => setPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>按数量</button>
          </div>
        </div>

        <div className="flex flex-col xl:flex-row items-center gap-16">
          <div className="relative w-full xl:w-[480px] h-[480px] flex-shrink-0">
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none text-center">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">当前总量</p>
              <p className={`text-4xl font-black ${pieMetric === 'sales' ? 'text-indigo-600' : 'text-emerald-600'}`}>{currentTotal.toLocaleString()}</p>
            </div>
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={sortedCategorySummary} cx="50%" cy="50%" innerRadius={150} outerRadius={210} paddingAngle={4} dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} onClick={(d) => setSelectedCategory(d.name)} stroke="none" style={{ cursor: 'pointer', outline: 'none' }}>
                  {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} opacity={selectedCategory && selectedCategory !== sortedCategorySummary[i].name ? 0.3 : 1} />)}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-2 gap-4">
            {sortedCategorySummary.map((item, idx) => {
              const val = pieMetric === 'sales' ? item.sales : item.quantity;
              const isSelected = selectedCategory === item.name;
              return (
                <button key={item.name} onClick={() => setSelectedCategory(item.name)} className={`flex items-center justify-between p-5 rounded-2xl border transition-all ${isSelected ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl scale-[1.02]' : 'bg-slate-50 border-slate-100 hover:bg-white hover:border-indigo-300'}`}>
                  <div className="flex items-center gap-4 text-left min-w-0">
                    <div className="w-2.5 h-10 rounded-full flex-shrink-0" style={{ backgroundColor: isSelected ? '#fff' : COLORS[idx % COLORS.length] }}></div>
                    <div className="min-w-0"><p className="text-sm font-black truncate">{item.name}</p><p className={`text-[10px] font-bold uppercase tracking-tight ${isSelected ? 'text-indigo-100' : 'text-slate-400'}`}>占比 {(val / currentTotal * 100).toFixed(1)}%</p></div>
                  </div>
                  <p className="text-lg font-mono font-black">{val.toLocaleString()}</p>
                </button>
              );
            })}
          </div>
        </div>

        {/* 级联下钻详情视图 (上下堆叠布局) */}
        {selectedCategory && (
          <div className="absolute inset-0 bg-white/98 backdrop-blur-2xl z-[2000] p-10 flex flex-col animate-in slide-in-from-bottom duration-500 overflow-hidden">
            <div className="flex items-center justify-between mb-8 pb-6 border-b border-slate-100">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-xl text-2xl font-black">C</div>
                <div>
                  <h4 className="text-[10px] font-black text-indigo-500 uppercase tracking-[0.3em] mb-1">Drilldown Cascading Analytics</h4>
                  <h3 className="text-3xl font-black text-slate-900">{selectedCategory}</h3>
                </div>
              </div>
              <div className="flex items-center gap-4">
                {Object.values(localTableFilters).some(v => v !== '') && (
                  <button onClick={() => setLocalTableFilters({id:'', date:'', customer:'', salesperson:'', itemName:''})} className="text-xs font-bold text-red-500 hover:underline">清除局部筛选</button>
                )}
                <button onClick={() => { setSelectedCategory(null); setLocalTableFilters({ id: '', date: '', customer: '', salesperson: '', itemName: '' }); }} className="flex items-center gap-2 px-6 py-3 bg-slate-900 text-white hover:bg-red-600 rounded-2xl text-sm font-bold transition-all shadow-lg">退出分析</button>
              </div>
            </div>

            <div className="flex-1 flex flex-col gap-8 overflow-hidden">
              {/* 上方：客户分布柱状图 (带点击联动) */}
              <div className="h-[240px] flex-shrink-0 bg-slate-50/50 rounded-3xl p-6 border border-slate-100 flex flex-col">
                <div className="flex items-center justify-between mb-4 px-2">
                  <h5 className="text-[11px] font-black text-slate-800 uppercase tracking-widest flex items-center gap-2">
                    <span className="w-1.5 h-3 bg-indigo-500 rounded-full"></span> 客户成交分布 (点击柱条快速筛选下方表格)
                  </h5>
                  <span className="text-[10px] font-bold text-slate-400">当前维度: {pieMetric === 'sales' ? '金额' : '数量'}</span>
                </div>
                <div className="flex-1">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={drillDownData.customers.slice(0, 15)} margin={{ left: 0, right: 30, top: 10, bottom: 0 }}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10, fontWeight: 'bold'}} />
                      <YAxis hide />
                      <Tooltip cursor={{fill: '#e2e8f0', opacity: 0.3}} contentStyle={{borderRadius: '12px', border: 'none', fontWeight: 'bold'}} />
                      <Bar 
                        dataKey={pieMetric === 'sales' ? 'sales' : 'qty'} 
                        fill="#6366f1" 
                        radius={[8, 8, 0, 0]} 
                        barSize={40}
                        onClick={(d) => setLocalTableFilters(p => ({...p, customer: d.name === p.customer ? '' : d.name}))}
                        style={{ cursor: 'pointer' }}
                      >
                        {drillDownData.customers.map((_, i) => (
                          <RechartsCell key={i} fill={localTableFilters.customer === _.name ? '#4338ca' : COLORS[i % COLORS.length]} />
                        ))}
                        <LabelList dataKey="percentage" position="top" fill="#94a3b8" fontSize={9} fontWeight="black" offset={8} />
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>

              {/* 下方：级联过滤明细表 */}
              <div className="flex-1 flex flex-col min-h-0 bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
                <div className="px-6 py-4 bg-slate-50/50 border-b border-slate-100 flex justify-between items-center">
                  <h5 className="text-[11px] font-black text-slate-800 uppercase tracking-widest flex items-center gap-2 font-mono">
                    <span className="w-1.5 h-3 bg-emerald-500 rounded-full"></span> Detail List (Cascading-Enabled)
                  </h5>
                  <div className="flex items-center gap-8">
                    <div className="text-[10px] font-bold text-slate-400">有效明细: <span className="text-indigo-600 font-black">{drillDownData.records.length}</span></div>
                    <div className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">当前筛选总计: <span className="text-slate-900 font-black text-xs">{drillDownData.drillDownTotal.toLocaleString()} {pieMetric === 'sales' ? 'CFA' : '件'}</span></div>
                  </div>
                </div>

                <div className="flex-1 overflow-auto custom-scrollbar">
                  <table className="min-w-full text-[11px] border-separate border-spacing-0">
                    <thead className="bg-slate-50 sticky top-0 z-50">
                      <tr>
                        <FilterHeader label="单号" columnId="id" />
                        <FilterHeader label="日期" columnId="date" />
                        <FilterHeader label="客户" columnId="customer" />
                        <FilterHeader label="销售员" columnId="salesperson" />
                        <FilterHeader label="物料名称" columnId="itemName" />
                        <th className="px-4 py-3 text-right font-bold text-slate-400 uppercase tracking-widest text-[10px] bg-slate-50">数量</th>
                        <th className="px-4 py-3 text-right font-bold text-slate-400 uppercase tracking-widest text-[10px] bg-slate-50">金额 (CFA)</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 bg-white">
                      {drillDownData.records.map((r, i) => (
                        <tr key={i} className="hover:bg-indigo-50/40 transition-colors group">
                          <td className="px-4 py-3.5 text-indigo-600 font-mono font-black"><button onClick={() => onSelectOrderId(r.id)} className="hover:underline text-left">{r.id}</button></td>
                          <td className="px-4 py-3.5 text-slate-500 font-mono">{r.date}</td>
                          <td className="px-4 py-3.5">
                            <button onClick={() => setLocalTableFilters(p => ({...p, customer: r.customer}))} className={`font-bold transition-colors text-left ${localTableFilters.customer === r.customer ? 'text-indigo-600' : 'text-slate-900 hover:text-indigo-500'}`}>{r.customer}</button>
                          </td>
                          <td className="px-4 py-3.5 text-slate-600 font-semibold">{r.salesperson}</td>
                          <td className="px-4 py-3.5 text-slate-700 font-bold truncate max-w-[220px]" title={r.itemName}>{r.itemName}</td>
                          <td className="px-4 py-3.5 text-right font-mono font-bold text-indigo-600">{r.quantity}</td>
                          <td className="px-4 py-3.5 text-right font-mono font-black text-slate-900 group-hover:text-indigo-700">{r.totalAmount.toLocaleString()}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        )}
      </section>

      {/* 销售绩效排行榜 (全宽) */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-10">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">🏆 销售绩效排行榜</h3>
            <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 font-mono">Performance Leaderboard</p>
          </div>
          <div className="px-4 py-1.5 bg-indigo-50 text-indigo-600 rounded-full text-[10px] font-black border border-indigo-100 uppercase tracking-[0.2em]">单位: 西非法郎 (CFA)</div>
        </div>
        <div className="h-[450px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical" margin={{ left: 20, right: 120, top: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide /><YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={100} tick={{fill: '#1e293b', fontWeight: 800, fontSize: 13}} />
              <Tooltip cursor={{fill: '#f8fafc'}} formatter={(v) => [`${v.toLocaleString()} CFA`, '业绩金额']} />
              <Bar dataKey="value" fill="#6366f1" radius={[0, 12, 12, 0]} barSize={32}>
                 {summary.salespersonPerformance.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                 <LabelList dataKey="value" position="right" formatter={(v: any) => `${v.toLocaleString()} CFA`} fill="#1e293b" fontSize={12} fontWeight="black" offset={20} />
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </section>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  // 下钻视图局部筛选状态
  const [localTableFilters, setLocalTableFilters] = useState({ 
    id: '', 
    date: '', 
    customer: '', 
    salesperson: '',
    itemName: '' 
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const globalTotals = useMemo(() => {
    return sortedCategorySummary.reduce((acc, cur) => {
      acc.sales += cur.sales;
      acc.quantity += cur.quantity;
      return acc;
    }, { sales: 0, quantity: 0 });
  }, [sortedCategorySummary]);

  const currentTotal = pieMetric === 'sales' ? globalTotals.sales : globalTotals.quantity;

  const filteredOrderIds = useMemo(() => {
    return summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase()));
  }, [summary.orderIds, orderSearchTerm]);

  // 下钻核心数据计算
  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { customers: [], records: [], drillDownTotal: 0, cascadingOptions: {} };

    const baseRecords = filteredData.filter(r => r.category === selectedCategory);

    const filteredRecords = baseRecords.filter(r => {
      const matchId = !localTableFilters.id || r.id === localTableFilters.id;
      const matchDate = !localTableFilters.date || r.date === localTableFilters.date;
      const matchCustomer = !localTableFilters.customer || r.customer === localTableFilters.customer;
      const matchSalesperson = !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
      const matchItemName = !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
      return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
    });

    const getOptionsFor = (key: keyof typeof localTableFilters) => {
      const tempFiltered = baseRecords.filter(r => {
        const matchId = key === 'id' || !localTableFilters.id || r.id === localTableFilters.id;
        const matchDate = key === 'date' || !localTableFilters.date || r.date === localTableFilters.date;
        const matchCustomer = key === 'customer' || !localTableFilters.customer || r.customer === localTableFilters.customer;
        const matchSalesperson = key === 'salesperson' || !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
        const matchItemName = key === 'itemName' || !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
        return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
      });
      return Array.from(new Set(tempFiltered.map(r => r[key === 'itemName' ? 'itemName' : key as keyof SalesRecord] as string))).sort();
    };

    const cascadingOptions = {
      id: getOptionsFor('id'),
      date: getOptionsFor('date').reverse(),
      customer: getOptionsFor('customer'),
      salesperson: getOptionsFor('salesperson'),
      itemName: getOptionsFor('itemName')
    };

    const customersMap = new Map<string, { sales: number; qty: number }>();
    baseRecords.forEach(record => {
      const c = customersMap.get(record.customer) || { sales: 0, qty: 0 };
      customersMap.set(record.customer, { sales: c.sales + record.totalAmount, qty: c.qty + record.quantity });
    });
    const catTotal = baseRecords.reduce((s, r) => s + (pieMetric === 'sales' ? r.totalAmount : r.quantity), 0);
    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ 
        name, 
        sales: val.sales, 
        qty: val.qty, 
        percentage: catTotal > 0 ? (((pieMetric === 'sales' ? val.sales : val.qty) / catTotal) * 100).toFixed(1) + '%' : '0%'
      }))
      .sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const drillDownTotal = filteredRecords.reduce((s, r) => s + (pieMetric === 'sales' ? r.totalAmount : r.quantity), 0);

    return { 
      customers, 
      records: filteredRecords.sort((a, b) => b.date.localeCompare(a.date)), 
      drillDownTotal,
      cascadingOptions 
    };
  }, [selectedCategory, filteredData, pieMetric, localTableFilters]);

  const FilterHeader = ({ label, columnId }: { label: string, columnId: keyof typeof localTableFilters }) => {
    const options = (drillDownData.cascadingOptions as any)[columnId] || [];
    const isSelected = !!localTableFilters[columnId];

    return (
      <th className="px-4 py-3 text-left relative group bg-slate-50 border-b border-slate-100">
        <div className="flex items-center gap-1.5">
          <span className="font-bold text-slate-400 uppercase tracking-widest text-[10px] whitespace-nowrap">{label}</span>
          <button 
            onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)} 
            className={`p-1 rounded-md transition-all ${isSelected ? 'text-indigo-600 bg-indigo-50 shadow-sm' : 'text-slate-300 hover:text-indigo-400'}`}
          >
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" /></svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-64 bg-white rounded-xl shadow-2xl border border-slate-200 z-[3000] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2.5 border-b border-slate-50 bg-slate-50 flex justify-between items-center">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label} 级联筛选</span>
              {isSelected && <button onClick={() => setLocalTableFilters(p => ({...p, [columnId]: ''}))} className="text-[10px] font-bold text-red-500 hover:underline">清除</button>}
            </div>
            <div className="max-h-64 overflow-y-auto p-1 custom-scrollbar">
              {options.length === 0 ? (
                <div className="px-3 py-4 text-center text-xs text-slate-400 italic">当前组合下无可选项</div>
              ) : (
                options.map((opt: string) => (
                  <button 
                    key={opt} 
                    onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }} 
                    className={`w-full text-left px-3 py-2 rounded-lg text-xs transition-colors flex items-center justify-between ${localTableFilters[columnId] === opt ? 'bg-indigo-50 text-indigo-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
                  >
                    <span className="truncate pr-2">{opt}</span>
                    {localTableFilters[columnId] === opt && <svg className="w-3 h-3 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20"><path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" /></svg>}
                  </button>
                ))
              )}
            </div>
          </div>
        )}
      </th>
    );
  };

  return (
    <div className="space-y-10 pb-16">
      {/* KPI 指标栏 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        {/* 金额 KPI */}
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>

        {/* 数量 KPI */}
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">物料出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>

        {/* 穿透式单据总数 KPI */}
        <div className="bg-white rounded-2xl border border-slate-100 shadow-sm flex flex-col overflow-hidden min-h-[100px] transition-all hover:shadow-md">
           <div className="p-6 flex items-center gap-6 border-b border-slate-50 bg-white">
              <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
              <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">业务单据总数</p>
                <div className="flex items-baseline gap-2">
                  <p className="text-2xl font-black text-slate-900">{summary.orderCount}</p>
                  <span className="text-[10px] text-slate-400 font-bold">张</span>
                </div>
              </div>
           </div>

           {/* 单号索引区 */}
           <div className="px-5 py-4 bg-slate-50/50">
              <div className="flex items-center justify-between mb-3">
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">单号快速索引</p>
                <div className="relative">
                  <input 
                    type="text" 
                    placeholder="搜单号..." 
                    value={orderSearchTerm}
                    onChange={(e) => setOrderSearchTerm(e.target.value)}
                    className="bg-white border border-slate-200 rounded-lg pl-6 pr-2 py-1 text-[10px] outline-none focus:border-amber-400 w-28 font-bold transition-all"
                  />
                  <svg className="w-2.5 h-2.5 absolute left-2 top-2 text-slate-300" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M8 4a4 4 0 100 8 4 4 0 000-8zM2 8a6 6 0 1110.89 3.476l4.817 4.817a1 1 0 01-1.414 1.414l-4.816-4.816A6 6 0 012 8z" clipRule="evenodd" /></svg>
                </div>
              </div>
              <div className="max-h-24 overflow-y-auto flex flex-wrap gap-1.5 custom-scrollbar">
                {filteredOrderIds.length > 0 ? (
                  filteredOrderIds.map(id => (
                    <button 
                      key={id} 
                      onClick={() => onSelectOrderId(id)}
                      className="px-2 py-1 bg-white border border-slate-200 rounded-md text-[10px] font-mono font-bold text-slate-600 hover:border-amber-500 hover:text-amber-600 hover:shadow-sm transition-all"
                    >
                      {id}
                    </button>
                  ))
                ) : (
                  <p className="text-[10px] text-slate-400 italic py-2">无匹配结果</p>
                )}
              </div>
           </div>
        </div>
      </div>

      {/* 第一行：销售趋势分析 (全宽) */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-8">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">📈 业绩增长趋势</h3>
            <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 font-mono">Monthly Performance History</p>
          </div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setShowCfa(!showCfa)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>金额 (CFA)</button>
            <button onClick={() => setShowQuantity(!showQuantity)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>数量</button>
          </div>
        </div>
        <div className="h-[450px]">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={summary.monthlyTrend} margin={{ left: 0, right: 10, top: 0, bottom: 0 }}>
              <defs>
                <linearGradient id="gSales" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#6366f1" stopOpacity={0.15}/><stop offset="95%" stopColor="#6366f1" stopOpacity={0}/></linearGradient>
                <linearGradient id="gQty" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#10b981" stopOpacity={0.15}/><stop offset="95%" stopColor="#10b981" stopOpacity={0}/></linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} dy={10} />
              <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#6366f1', fontSize: 10, fontWeight: 'bold'}} />
              <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 10, fontWeight: 'bold'}} />
              <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }} />
              {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" name="销售额" stroke="#6366f1" strokeWidth={4} fill="url(#gSales)" />}
              {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" name="出库量" stroke="#10b981" strokeWidth={4} fill="url(#gQty)" />}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </section>

      {/* 第二行：品类分布洞察 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200 relative min-h-[600px] overflow-hidden">
        <div className="flex justify-between items-center mb-10">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">🧩 品类业务构成</h3>
            <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 font-mono">Market Share Analysis</p>
          </div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'sales' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>按金额</button>
            <button onClick={() => setPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>按数量</button>
          </div>
        </div>

        <div className="flex flex-col xl:flex-row items-center gap-16">
          <div className="relative w-full xl:w-[480px] h-[480px] flex-shrink-0">
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none text-center">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">当前总量</p>
              <p className={`text-4xl font-black ${pieMetric === 'sales' ? 'text-indigo-600' : 'text-emerald-600'}`}>{currentTotal.toLocaleString()}</p>
            </div>
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={sortedCategorySummary} cx="50%" cy="50%" innerRadius={150} outerRadius={210} paddingAngle={4} dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} onClick={(d) => setSelectedCategory(d.name)} stroke="none" style={{ cursor: 'pointer', outline: 'none' }}>
                  {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} opacity={selectedCategory && selectedCategory !== sortedCategorySummary[i].name ? 0.3 : 1} />)}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-2 gap-4">
            {sortedCategorySummary.map((item, idx) => {
              const val = pieMetric === 'sales' ? item.sales : item.quantity;
              const isSelected = selectedCategory === item.name;
              return (
                <button key={item.name} onClick={() => setSelectedCategory(item.name)} className={`flex items-center justify-between p-5 rounded-2xl border transition-all ${isSelected ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl scale-[1.02]' : 'bg-slate-50 border-slate-100 hover:bg-white hover:border-indigo-300'}`}>
                  <div className="flex items-center gap-4 text-left min-w-0">
                    <div className="w-2.5 h-10 rounded-full flex-shrink-0" style={{ backgroundColor: isSelected ? '#fff' : COLORS[idx % COLORS.length] }}></div>
                    <div className="min-w-0"><p className="text-sm font-black truncate">{item.name}</p><p className={`text-[10px] font-bold uppercase tracking-tight ${isSelected ? 'text-indigo-100' : 'text-slate-400'}`}>占比 {(val / currentTotal * 100).toFixed(1)}%</p></div>
                  </div>
                  <p className="text-lg font-mono font-black">{val.toLocaleString()}</p>
                </button>
              );
            })}
          </div>
        </div>

        {/* 级联下钻详情视图 (上下堆叠布局) */}
        {selectedCategory && (
          <div className="absolute inset-0 bg-white/98 backdrop-blur-2xl z-[2000] p-10 flex flex-col animate-in slide-in-from-bottom duration-500 overflow-hidden">
            <div className="flex items-center justify-between mb-8 pb-6 border-b border-slate-100">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-xl text-2xl font-black">C</div>
                <div>
                  <h4 className="text-[10px] font-black text-indigo-500 uppercase tracking-[0.3em] mb-1">Drilldown Cascading Analytics</h4>
                  <h3 className="text-3xl font-black text-slate-900">{selectedCategory}</h3>
                </div>
              </div>
              <div className="flex items-center gap-4">
                {Object.values(localTableFilters).some(v => v !== '') && (
                  <button onClick={() => setLocalTableFilters({id:'', date:'', customer:'', salesperson:'', itemName:''})} className="text-xs font-bold text-red-500 hover:underline">清除局部筛选</button>
                )}
                <button onClick={() => { setSelectedCategory(null); setLocalTableFilters({ id: '', date: '', customer: '', salesperson: '', itemName: '' }); }} className="flex items-center gap-2 px-6 py-3 bg-slate-900 text-white hover:bg-red-600 rounded-2xl text-sm font-bold transition-all shadow-lg">退出分析</button>
              </div>
            </div>

            <div className="flex-1 flex flex-col gap-8 overflow-hidden">
              {/* 上方：客户分布柱状图 (带点击联动) */}
              <div className="h-[240px] flex-shrink-0 bg-slate-50/50 rounded-3xl p-6 border border-slate-100 flex flex-col">
                <div className="flex items-center justify-between mb-4 px-2">
                  <h5 className="text-[11px] font-black text-slate-800 uppercase tracking-widest flex items-center gap-2">
                    <span className="w-1.5 h-3 bg-indigo-500 rounded-full"></span> 客户成交分布 (点击柱条快速筛选下方表格)
                  </h5>
                  <span className="text-[10px] font-bold text-slate-400">当前维度: {pieMetric === 'sales' ? '金额' : '数量'}</span>
                </div>
                <div className="flex-1">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={drillDownData.customers.slice(0, 15)} margin={{ left: 0, right: 30, top: 10, bottom: 0 }}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10, fontWeight: 'bold'}} />
                      <YAxis hide />
                      <Tooltip cursor={{fill: '#e2e8f0', opacity: 0.3}} contentStyle={{borderRadius: '12px', border: 'none', fontWeight: 'bold'}} />
                      <Bar 
                        dataKey={pieMetric === 'sales' ? 'sales' : 'qty'} 
                        fill="#6366f1" 
                        radius={[8, 8, 0, 0]} 
                        barSize={40}
                        onClick={(d) => setLocalTableFilters(p => ({...p, customer: d.name === p.customer ? '' : d.name}))}
                        style={{ cursor: 'pointer' }}
                      >
                        {drillDownData.customers.map((_, i) => (
                          <RechartsCell key={i} fill={localTableFilters.customer === _.name ? '#4338ca' : COLORS[i % COLORS.length]} />
                        ))}
                        <LabelList dataKey="percentage" position="top" fill="#94a3b8" fontSize={9} fontWeight="black" offset={8} />
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>

              {/* 下方：级联过滤明细表 */}
              <div className="flex-1 flex flex-col min-h-0 bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
                <div className="px-6 py-4 bg-slate-50/50 border-b border-slate-100 flex justify-between items-center">
                  <h5 className="text-[11px] font-black text-slate-800 uppercase tracking-widest flex items-center gap-2 font-mono">
                    <span className="w-1.5 h-3 bg-emerald-500 rounded-full"></span> Detail List (Cascading-Enabled)
                  </h5>
                  <div className="flex items-center gap-8">
                    <div className="text-[10px] font-bold text-slate-400">有效明细: <span className="text-indigo-600 font-black">{drillDownData.records.length}</span></div>
                    <div className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">当前筛选总计: <span className="text-slate-900 font-black text-xs">{drillDownData.drillDownTotal.toLocaleString()} {pieMetric === 'sales' ? 'CFA' : '件'}</span></div>
                  </div>
                </div>

                <div className="flex-1 overflow-auto custom-scrollbar">
                  <table className="min-w-full text-[11px] border-separate border-spacing-0">
                    <thead className="bg-slate-50 sticky top-0 z-50">
                      <tr>
                        <FilterHeader label="单号" columnId="id" />
                        <FilterHeader label="日期" columnId="date" />
                        <FilterHeader label="客户" columnId="customer" />
                        <FilterHeader label="销售员" columnId="salesperson" />
                        <FilterHeader label="物料名称" columnId="itemName" />
                        <th className="px-4 py-3 text-right font-bold text-slate-400 uppercase tracking-widest text-[10px] bg-slate-50">数量</th>
                        <th className="px-4 py-3 text-right font-bold text-slate-400 uppercase tracking-widest text-[10px] bg-slate-50">金额 (CFA)</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 bg-white">
                      {drillDownData.records.map((r, i) => (
                        <tr key={i} className="hover:bg-indigo-50/40 transition-colors group">
                          <td className="px-4 py-3.5 text-indigo-600 font-mono font-black"><button onClick={() => onSelectOrderId(r.id)} className="hover:underline text-left">{r.id}</button></td>
                          <td className="px-4 py-3.5 text-slate-500 font-mono">{r.date}</td>
                          <td className="px-4 py-3.5">
                            <button onClick={() => setLocalTableFilters(p => ({...p, customer: r.customer}))} className={`font-bold transition-colors text-left ${localTableFilters.customer === r.customer ? 'text-indigo-600' : 'text-slate-900 hover:text-indigo-500'}`}>{r.customer}</button>
                          </td>
                          <td className="px-4 py-3.5 text-slate-600 font-semibold">{r.salesperson}</td>
                          <td className="px-4 py-3.5 text-slate-700 font-bold truncate max-w-[220px]" title={r.itemName}>{r.itemName}</td>
                          <td className="px-4 py-3.5 text-right font-mono font-bold text-indigo-600">{r.quantity}</td>
                          <td className="px-4 py-3.5 text-right font-mono font-black text-slate-900 group-hover:text-indigo-700">{r.totalAmount.toLocaleString()}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        )}
      </section>

      {/* 销售绩效排行榜 (全宽) */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-10">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">🏆 销售绩效排行榜</h3>
            <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 font-mono">Performance Leaderboard</p>
          </div>
          <div className="px-4 py-1.5 bg-indigo-50 text-indigo-600 rounded-full text-[10px] font-black border border-indigo-100 uppercase tracking-[0.2em]">单位: 西非法郎 (CFA)</div>
        </div>
        <div className="h-[450px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical" margin={{ left: 20, right: 120, top: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide /><YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={100} tick={{fill: '#1e293b', fontWeight: 800, fontSize: 13}} />
              <Tooltip cursor={{fill: '#f8fafc'}} formatter={(v) => [`${v.toLocaleString()} CFA`, '业绩金额']} />
              <Bar dataKey="value" fill="#6366f1" radius={[0, 12, 12, 0]} barSize={32}>
                 {summary.salespersonPerformance.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                 <LabelList dataKey="value" position="right" formatter={(v: any) => `${v.toLocaleString()} CFA`} fill="#1e293b" fontSize={12} fontWeight="black" offset={20} />
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </section>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  // KPI 展开状态与搜索
  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  // 下钻视图局部筛选状态
  const [localTableFilters, setLocalTableFilters] = useState({ 
    id: '', 
    date: '', 
    customer: '', 
    salesperson: '',
    itemName: '' 
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const globalTotals = useMemo(() => {
    return sortedCategorySummary.reduce((acc, cur) => {
      acc.sales += cur.sales;
      acc.quantity += cur.quantity;
      return acc;
    }, { sales: 0, quantity: 0 });
  }, [sortedCategorySummary]);

  const currentTotal = pieMetric === 'sales' ? globalTotals.sales : globalTotals.quantity;

  const filteredOrderIds = useMemo(() => {
    return summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase()));
  }, [summary.orderIds, orderSearchTerm]);

  // 下钻核心数据计算
  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { customers: [], records: [], drillDownTotal: 0, cascadingOptions: {} };

    const baseRecords = filteredData.filter(r => r.category === selectedCategory);

    const filteredRecords = baseRecords.filter(r => {
      const matchId = !localTableFilters.id || r.id === localTableFilters.id;
      const matchDate = !localTableFilters.date || r.date === localTableFilters.date;
      const matchCustomer = !localTableFilters.customer || r.customer === localTableFilters.customer;
      const matchSalesperson = !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
      const matchItemName = !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
      return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
    });

    const getOptionsFor = (key: keyof typeof localTableFilters) => {
      const tempFiltered = baseRecords.filter(r => {
        const matchId = key === 'id' || !localTableFilters.id || r.id === localTableFilters.id;
        const matchDate = key === 'date' || !localTableFilters.date || r.date === localTableFilters.date;
        const matchCustomer = key === 'customer' || !localTableFilters.customer || r.customer === localTableFilters.customer;
        const matchSalesperson = key === 'salesperson' || !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
        const matchItemName = key === 'itemName' || !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
        return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
      });
      return Array.from(new Set(tempFiltered.map(r => r[key === 'itemName' ? 'itemName' : key as keyof SalesRecord] as string))).sort();
    };

    const cascadingOptions = {
      id: getOptionsFor('id'),
      date: getOptionsFor('date').reverse(),
      customer: getOptionsFor('customer'),
      salesperson: getOptionsFor('salesperson'),
      itemName: getOptionsFor('itemName')
    };

    const customersMap = new Map<string, { sales: number; qty: number }>();
    baseRecords.forEach(record => {
      const c = customersMap.get(record.customer) || { sales: 0, qty: 0 };
      customersMap.set(record.customer, { sales: c.sales + record.totalAmount, qty: c.qty + record.quantity });
    });
    const catTotal = baseRecords.reduce((s, r) => s + (pieMetric === 'sales' ? r.totalAmount : r.quantity), 0);
    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ 
        name, 
        sales: val.sales, 
        qty: val.qty, 
        percentage: catTotal > 0 ? (((pieMetric === 'sales' ? val.sales : val.qty) / catTotal) * 100).toFixed(1) + '%' : '0%'
      }))
      .sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const drillDownTotal = filteredRecords.reduce((s, r) => s + (pieMetric === 'sales' ? r.totalAmount : r.quantity), 0);

    return { 
      customers, 
      records: filteredRecords.sort((a, b) => b.date.localeCompare(a.date)), 
      drillDownTotal,
      cascadingOptions 
    };
  }, [selectedCategory, filteredData, pieMetric, localTableFilters]);

  const FilterHeader = ({ label, columnId }: { label: string, columnId: keyof typeof localTableFilters }) => {
    const options = (drillDownData.cascadingOptions as any)[columnId] || [];
    const isSelected = !!localTableFilters[columnId];

    return (
      <th className="px-4 py-3 text-left relative group bg-slate-50 border-b border-slate-100">
        <div className="flex items-center gap-1.5">
          <span className="font-bold text-slate-400 uppercase tracking-widest text-[10px] whitespace-nowrap">{label}</span>
          <button 
            onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)} 
            className={`p-1 rounded-md transition-all ${isSelected ? 'text-indigo-600 bg-indigo-50 shadow-sm' : 'text-slate-300 hover:text-indigo-400'}`}
          >
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" /></svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-64 bg-white rounded-xl shadow-2xl border border-slate-200 z-[3000] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2.5 border-b border-slate-50 bg-slate-50 flex justify-between items-center">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label} 级联筛选</span>
              {isSelected && <button onClick={() => setLocalTableFilters(p => ({...p, [columnId]: ''}))} className="text-[10px] font-bold text-red-500 hover:underline">清除</button>}
            </div>
            <div className="max-h-64 overflow-y-auto p-1 custom-scrollbar">
              {options.length === 0 ? (
                <div className="px-3 py-4 text-center text-xs text-slate-400 italic">当前组合下无可选项</div>
              ) : (
                options.map((opt: string) => (
                  <button 
                    key={opt} 
                    onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }} 
                    className={`w-full text-left px-3 py-2 rounded-lg text-xs transition-colors flex items-center justify-between ${localTableFilters[columnId] === opt ? 'bg-indigo-50 text-indigo-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}
                  >
                    <span className="truncate pr-2">{opt}</span>
                    {localTableFilters[columnId] === opt && <svg className="w-3 h-3 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20"><path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" /></svg>}
                  </button>
                ))
              )}
            </div>
          </div>
        )}
      </th>
    );
  };

  return (
    <div className="space-y-10 pb-16">
      {/* KPI 指标栏 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        {/* 金额 KPI */}
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-6 h-[100px] hover:shadow-md transition-shadow">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>

        {/* 数量 KPI */}
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-6 h-[100px] hover:shadow-md transition-shadow">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">物料出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>

        {/* 穿透式/可折叠 单据总数 KPI */}
        <div className="bg-white rounded-2xl border border-slate-100 shadow-sm flex flex-col overflow-hidden transition-all duration-300 hover:shadow-md">
           <div className="p-6 flex items-center justify-between bg-white border-b border-slate-50">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
                <div>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">业务单据总数</p>
                  <div className="flex items-baseline gap-2">
                    <p className="text-2xl font-black text-slate-900">{summary.orderCount}</p>
                    <span className="text-[10px] text-slate-400 font-bold">张</span>
                  </div>
                </div>
              </div>
              <button 
                onClick={() => setIsOrdersExpanded(!isOrdersExpanded)}
                className={`p-2 rounded-xl transition-all ${isOrdersExpanded ? 'bg-amber-100 text-amber-700' : 'bg-slate-50 text-slate-400 hover:bg-slate-100 hover:text-slate-600'}`}
                title={isOrdersExpanded ? "折叠列表" : "展开单号列表"}
              >
                <svg className={`w-5 h-5 transition-transform duration-300 ${isOrdersExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" />
                </svg>
              </button>
           </div>

           {/* 可折叠的单号索引区 */}
           <div className={`overflow-hidden transition-all duration-500 ease-in-out ${isOrdersExpanded ? 'max-height-[500px] opacity-100' : 'max-h-0 opacity-0 pointer-events-none'}`}>
              <div className="px-5 py-5 bg-slate-50/50 border-t border-slate-100 space-y-4">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <span className="w-1.5 h-1.5 bg-amber-500 rounded-full animate-pulse"></span>
                    <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">单号实时索引</p>
                  </div>
                  <div className="relative">
                    <input 
                      type="text" 
                      placeholder="快速检索单号..." 
                      value={orderSearchTerm}
                      onChange={(e) => setOrderSearchTerm(e.target.value)}
                      className="bg-white border border-slate-200 rounded-lg pl-8 pr-3 py-1.5 text-[10px] outline-none focus:border-amber-400 focus:ring-4 focus:ring-amber-50 w-40 font-bold transition-all shadow-sm placeholder:font-normal"
                    />
                    <svg className="w-3.5 h-3.5 absolute left-2.5 top-2.5 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                  </div>
                </div>

                <div className="bg-white/60 p-3 rounded-xl border border-slate-100">
                  <div className="max-h-40 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar pr-1">
                    {filteredOrderIds.length > 0 ? (
                      filteredOrderIds.map(id => (
                        <button 
                          key={id} 
                          onClick={() => onSelectOrderId(id)}
                          className="px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-black text-slate-600 hover:border-amber-400 hover:text-amber-700 hover:bg-amber-50 hover:shadow-sm transition-all group flex items-center gap-1.5"
                        >
                          <span className="w-1 h-1 bg-slate-300 rounded-full group-hover:bg-amber-400"></span>
                          {id}
                        </button>
                      ))
                    ) : (
                      <div className="w-full py-6 text-center">
                        <p className="text-[10px] text-slate-400 italic">没有找到匹配的单据号</p>
                      </div>
                    )}
                  </div>
                </div>

                <div className="flex justify-between items-center px-1">
                  <p className="text-[9px] text-slate-400 font-bold">显示 {filteredOrderIds.length} / {summary.orderCount} 条</p>
                  <button onClick={() => setIsOrdersExpanded(false)} className="text-[9px] font-black text-amber-600 uppercase tracking-widest hover:underline">收起面板</button>
                </div>
              </div>
           </div>
        </div>
      </div>

      {/* 第一行：销售趋势分析 (全宽) */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-8">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">📈 业绩增长趋势</h3>
            <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 font-mono">Monthly Performance History</p>
          </div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setShowCfa(!showCfa)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>金额 (CFA)</button>
            <button onClick={() => setShowQuantity(!showQuantity)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>数量</button>
          </div>
        </div>
        <div className="h-[450px]">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={summary.monthlyTrend} margin={{ left: 0, right: 10, top: 0, bottom: 0 }}>
              <defs>
                <linearGradient id="gSales" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#6366f1" stopOpacity={0.15}/><stop offset="95%" stopColor="#6366f1" stopOpacity={0}/></linearGradient>
                <linearGradient id="gQty" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#10b981" stopOpacity={0.15}/><stop offset="95%" stopColor="#10b981" stopOpacity={0}/></linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} dy={10} />
              <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#6366f1', fontSize: 10, fontWeight: 'bold'}} />
              <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 10, fontWeight: 'bold'}} />
              <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }} />
              {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" name="销售额" stroke="#6366f1" strokeWidth={4} fill="url(#gSales)" />}
              {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" name="出库量" stroke="#10b981" strokeWidth={4} fill="url(#gQty)" />}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </section>

      {/* 第二行：品类分布洞察 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200 relative min-h-[600px] overflow-hidden">
        <div className="flex justify-between items-center mb-10">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">🧩 品类业务构成</h3>
            <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 font-mono">Market Share Analysis</p>
          </div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'sales' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>按金额</button>
            <button onClick={() => setPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>按数量</button>
          </div>
        </div>

        <div className="flex flex-col xl:flex-row items-center gap-16">
          <div className="relative w-full xl:w-[480px] h-[480px] flex-shrink-0">
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none text-center">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">当前总量</p>
              <p className={`text-4xl font-black ${pieMetric === 'sales' ? 'text-indigo-600' : 'text-emerald-600'}`}>{currentTotal.toLocaleString()}</p>
            </div>
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={sortedCategorySummary} cx="50%" cy="50%" innerRadius={150} outerRadius={210} paddingAngle={4} dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} onClick={(d) => setSelectedCategory(d.name)} stroke="none" style={{ cursor: 'pointer', outline: 'none' }}>
                  {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} opacity={selectedCategory && selectedCategory !== sortedCategorySummary[i].name ? 0.3 : 1} />)}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-2 gap-4">
            {sortedCategorySummary.map((item, idx) => {
              const val = pieMetric === 'sales' ? item.sales : item.quantity;
              const isSelected = selectedCategory === item.name;
              return (
                <button key={item.name} onClick={() => setSelectedCategory(item.name)} className={`flex items-center justify-between p-5 rounded-2xl border transition-all ${isSelected ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl scale-[1.02]' : 'bg-slate-50 border-slate-100 hover:bg-white hover:border-indigo-300'}`}>
                  <div className="flex items-center gap-4 text-left min-w-0">
                    <div className="w-2.5 h-10 rounded-full flex-shrink-0" style={{ backgroundColor: isSelected ? '#fff' : COLORS[idx % COLORS.length] }}></div>
                    <div className="min-w-0"><p className="text-sm font-black truncate">{item.name}</p><p className={`text-[10px] font-bold uppercase tracking-tight ${isSelected ? 'text-indigo-100' : 'text-slate-400'}`}>占比 {(val / currentTotal * 100).toFixed(1)}%</p></div>
                  </div>
                  <p className="text-lg font-mono font-black">{val.toLocaleString()}</p>
                </button>
              );
            })}
          </div>
        </div>

        {/* 级联下钻详情视图 (上下堆叠布局) */}
        {selectedCategory && (
          <div className="absolute inset-0 bg-white/98 backdrop-blur-2xl z-[2000] p-10 flex flex-col animate-in slide-in-from-bottom duration-500 overflow-hidden">
            <div className="flex items-center justify-between mb-8 pb-6 border-b border-slate-100">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-xl text-2xl font-black">C</div>
                <div>
                  <h4 className="text-[10px] font-black text-indigo-500 uppercase tracking-[0.3em] mb-1">Drilldown Cascading Analytics</h4>
                  <h3 className="text-3xl font-black text-slate-900">{selectedCategory}</h3>
                </div>
              </div>
              <div className="flex items-center gap-4">
                {Object.values(localTableFilters).some(v => v !== '') && (
                  <button onClick={() => setLocalTableFilters({id:'', date:'', customer:'', salesperson:'', itemName:''})} className="text-xs font-bold text-red-500 hover:underline">清除局部筛选</button>
                )}
                <button onClick={() => { setSelectedCategory(null); setLocalTableFilters({ id: '', date: '', customer: '', salesperson: '', itemName: '' }); }} className="flex items-center gap-2 px-6 py-3 bg-slate-900 text-white hover:bg-red-600 rounded-2xl text-sm font-bold transition-all shadow-lg">退出分析</button>
              </div>
            </div>

            <div className="flex-1 flex flex-col gap-8 overflow-hidden">
              {/* 上方：客户分布柱状图 (带点击联动) */}
              <div className="h-[240px] flex-shrink-0 bg-slate-50/50 rounded-3xl p-6 border border-slate-100 flex flex-col">
                <div className="flex items-center justify-between mb-4 px-2">
                  <h5 className="text-[11px] font-black text-slate-800 uppercase tracking-widest flex items-center gap-2">
                    <span className="w-1.5 h-3 bg-indigo-500 rounded-full"></span> 客户成交分布 (点击柱条快速筛选下方表格)
                  </h5>
                  <span className="text-[10px] font-bold text-slate-400">当前维度: {pieMetric === 'sales' ? '金额' : '数量'}</span>
                </div>
                <div className="flex-1">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={drillDownData.customers.slice(0, 15)} margin={{ left: 0, right: 30, top: 10, bottom: 0 }}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10, fontWeight: 'bold'}} />
                      <YAxis hide />
                      <Tooltip cursor={{fill: '#e2e8f0', opacity: 0.3}} contentStyle={{borderRadius: '12px', border: 'none', fontWeight: 'bold'}} />
                      <Bar 
                        dataKey={pieMetric === 'sales' ? 'sales' : 'qty'} 
                        fill="#6366f1" 
                        radius={[8, 8, 0, 0]} 
                        barSize={40}
                        onClick={(d) => setLocalTableFilters(p => ({...p, customer: d.name === p.customer ? '' : d.name}))}
                        style={{ cursor: 'pointer' }}
                      >
                        {drillDownData.customers.map((_, i) => (
                          <RechartsCell key={i} fill={localTableFilters.customer === _.name ? '#4338ca' : COLORS[i % COLORS.length]} />
                        ))}
                        <LabelList dataKey="percentage" position="top" fill="#94a3b8" fontSize={9} fontWeight="black" offset={8} />
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>

              {/* 下方：级联过滤明细表 */}
              <div className="flex-1 flex flex-col min-h-0 bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
                <div className="px-6 py-4 bg-slate-50/50 border-b border-slate-100 flex justify-between items-center">
                  <h5 className="text-[11px] font-black text-slate-800 uppercase tracking-widest flex items-center gap-2 font-mono">
                    <span className="w-1.5 h-3 bg-emerald-500 rounded-full"></span> Detail List (Cascading-Enabled)
                  </h5>
                  <div className="flex items-center gap-8">
                    <div className="text-[10px] font-bold text-slate-400">有效明细: <span className="text-indigo-600 font-black">{drillDownData.records.length}</span></div>
                    <div className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">当前筛选总计: <span className="text-slate-900 font-black text-xs">{drillDownData.drillDownTotal.toLocaleString()} {pieMetric === 'sales' ? 'CFA' : '件'}</span></div>
                  </div>
                </div>

                <div className="flex-1 overflow-auto custom-scrollbar">
                  <table className="min-w-full text-[11px] border-separate border-spacing-0">
                    <thead className="bg-slate-50 sticky top-0 z-50">
                      <tr>
                        <FilterHeader label="单号" columnId="id" />
                        <FilterHeader label="日期" columnId="date" />
                        <FilterHeader label="客户" columnId="customer" />
                        <FilterHeader label="销售员" columnId="salesperson" />
                        <FilterHeader label="物料名称" columnId="itemName" />
                        <th className="px-4 py-3 text-right font-bold text-slate-400 uppercase tracking-widest text-[10px] bg-slate-50">数量</th>
                        <th className="px-4 py-3 text-right font-bold text-slate-400 uppercase tracking-widest text-[10px] bg-slate-50">金额 (CFA)</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 bg-white">
                      {drillDownData.records.map((r, i) => (
                        <tr key={i} className="hover:bg-indigo-50/40 transition-colors group">
                          <td className="px-4 py-3.5 text-indigo-600 font-mono font-black"><button onClick={() => onSelectOrderId(r.id)} className="hover:underline text-left">{r.id}</button></td>
                          <td className="px-4 py-3.5 text-slate-500 font-mono">{r.date}</td>
                          <td className="px-4 py-3.5">
                            <button onClick={() => setLocalTableFilters(p => ({...p, customer: r.customer}))} className={`font-bold transition-colors text-left ${localTableFilters.customer === r.customer ? 'text-indigo-600' : 'text-slate-900 hover:text-indigo-500'}`}>{r.customer}</button>
                          </td>
                          <td className="px-4 py-3.5 text-slate-600 font-semibold">{r.salesperson}</td>
                          <td className="px-4 py-3.5 text-slate-700 font-bold truncate max-w-[220px]" title={r.itemName}>{r.itemName}</td>
                          <td className="px-4 py-3.5 text-right font-mono font-bold text-indigo-600">{r.quantity}</td>
                          <td className="px-4 py-3.5 text-right font-mono font-black text-slate-900 group-hover:text-indigo-700">{r.totalAmount.toLocaleString()}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        )}
      </section>

      {/* 销售绩效排行榜 (全宽) */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-10">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">🏆 销售绩效排行榜</h3>
            <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 font-mono">Performance Leaderboard</p>
          </div>
          <div className="px-4 py-1.5 bg-indigo-50 text-indigo-600 rounded-full text-[10px] font-black border border-indigo-100 uppercase tracking-[0.2em]">单位: 西非法郎 (CFA)</div>
        </div>
        <div className="h-[450px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={summary.salespersonPerformance} layout="vertical" margin={{ left: 20, right: 120, top: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide /><YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={100} tick={{fill: '#1e293b', fontWeight: 800, fontSize: 13}} />
              <Tooltip cursor={{fill: '#f8fafc'}} formatter={(v) => [`${v.toLocaleString()} CFA`, '业绩金额']} />
              <Bar dataKey="value" fill="#6366f1" radius={[0, 12, 12, 0]} barSize={32}>
                 {summary.salespersonPerformance.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                 <LabelList dataKey="value" position="right" formatter={(v: any) => `${v.toLocaleString()} CFA`} fill="#1e293b" fontSize={12} fontWeight="black" offset={20} />
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </section>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  const [localTableFilters, setLocalTableFilters] = useState({ 
    id: '', 
    date: '', 
    customer: '', 
    salesperson: '',
    itemName: '' 
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const globalTotals = useMemo(() => {
    return sortedCategorySummary.reduce((acc, cur) => {
      acc.sales += cur.sales;
      acc.quantity += cur.quantity;
      return acc;
    }, { sales: 0, quantity: 0 });
  }, [sortedCategorySummary]);

  const currentTotal = pieMetric === 'sales' ? globalTotals.sales : globalTotals.quantity;

  const filteredOrderIds = useMemo(() => {
    return summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase()));
  }, [summary.orderIds, orderSearchTerm]);

  // 自定义引导线标注渲染函数
  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-RADIAN * midAngle);
    const cos = Math.cos(-RADIAN * midAngle);

    // 线条起点 (扇形外边缘)
    const sx = cx + (outerRadius + 5) * cos;
    const sy = cy + (outerRadius + 5) * sin;

    // 线条拐点
    const mx = cx + (outerRadius + 30) * cos;
    const my = cy + (outerRadius + 30) * sin;

    // 线条终点
    const ex = mx + (cos >= 0 ? 1 : -1) * 22;
    const ey = my;

    const textAnchor = cos >= 0 ? 'start' : 'end';

    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} opacity={0.6} />
        <circle cx={ex} cy={ey} r={2} fill={fill} />
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} textAnchor={textAnchor} fill="#1e293b" style={{ fontSize: '11px', fontWeight: 900 }}>
          {name}
        </text>
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} dy={14} textAnchor={textAnchor} fill="#64748b" style={{ fontSize: '10px', fontWeight: 600 }}>
          {(percent * 100).toFixed(1)}%
        </text>
      </g>
    );
  };

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { customers: [], records: [], drillDownTotal: 0, cascadingOptions: {} };
    const baseRecords = filteredData.filter(r => r.category === selectedCategory);
    const filteredRecords = baseRecords.filter(r => {
      const matchId = !localTableFilters.id || r.id === localTableFilters.id;
      const matchDate = !localTableFilters.date || r.date === localTableFilters.date;
      const matchCustomer = !localTableFilters.customer || r.customer === localTableFilters.customer;
      const matchSalesperson = !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
      const matchItemName = !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
      return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
    });
    const getOptionsFor = (key: keyof typeof localTableFilters) => {
      const tempFiltered = baseRecords.filter(r => {
        const matchId = key === 'id' || !localTableFilters.id || r.id === localTableFilters.id;
        const matchDate = key === 'date' || !localTableFilters.date || r.date === localTableFilters.date;
        const matchCustomer = key === 'customer' || !localTableFilters.customer || r.customer === localTableFilters.customer;
        const matchSalesperson = key === 'salesperson' || !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
        const matchItemName = key === 'itemName' || !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
        return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
      });
      return Array.from(new Set(tempFiltered.map(r => r[key === 'itemName' ? 'itemName' : key as keyof SalesRecord] as string))).sort();
    };
    const cascadingOptions = { id: getOptionsFor('id'), date: getOptionsFor('date').reverse(), customer: getOptionsFor('customer'), salesperson: getOptionsFor('salesperson'), itemName: getOptionsFor('itemName') };
    const customersMap = new Map<string, { sales: number; qty: number }>();
    baseRecords.forEach(record => {
      const c = customersMap.get(record.customer) || { sales: 0, qty: 0 };
      customersMap.set(record.customer, { sales: c.sales + record.totalAmount, qty: c.qty + record.quantity });
    });
    const catTotal = baseRecords.reduce((s, r) => s + (pieMetric === 'sales' ? r.totalAmount : r.quantity), 0);
    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty, percentage: catTotal > 0 ? (((pieMetric === 'sales' ? val.sales : val.qty) / catTotal) * 100).toFixed(1) + '%' : '0%' }))
      .sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);
    const drillDownTotal = filteredRecords.reduce((s, r) => s + (pieMetric === 'sales' ? r.totalAmount : r.quantity), 0);
    return { customers, records: filteredRecords.sort((a, b) => b.date.localeCompare(a.date)), drillDownTotal, cascadingOptions };
  }, [selectedCategory, filteredData, pieMetric, localTableFilters]);

  const FilterHeader = ({ label, columnId }: { label: string, columnId: keyof typeof localTableFilters }) => {
    const options = (drillDownData.cascadingOptions as any)[columnId] || [];
    const isSelected = !!localTableFilters[columnId];
    return (
      <th className="px-4 py-3 text-left relative group bg-slate-50 border-b border-slate-100">
        <div className="flex items-center gap-1.5">
          <span className="font-bold text-slate-400 uppercase tracking-widest text-[10px] whitespace-nowrap">{label}</span>
          <button onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)} className={`p-1 rounded-md transition-all ${isSelected ? 'text-indigo-600 bg-indigo-50 shadow-sm' : 'text-slate-300 hover:text-indigo-400'}`}>
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" /></svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-64 bg-white rounded-xl shadow-2xl border border-slate-200 z-[3000] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2.5 border-b border-slate-50 bg-slate-50 flex justify-between items-center"><span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label} 级联筛选</span>{isSelected && <button onClick={() => setLocalTableFilters(p => ({...p, [columnId]: ''}))} className="text-[10px] font-bold text-red-500 hover:underline">清除</button>}</div>
            <div className="max-h-64 overflow-y-auto p-1 custom-scrollbar">
              {options.length === 0 ? (<div className="px-3 py-4 text-center text-xs text-slate-400 italic">当前组合下无可选项</div>) : (
                options.map((opt: string) => (<button key={opt} onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }} className={`w-full text-left px-3 py-2 rounded-lg text-xs transition-colors flex items-center justify-between ${localTableFilters[columnId] === opt ? 'bg-indigo-50 text-indigo-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}><span className="truncate pr-2">{opt}</span>{localTableFilters[columnId] === opt && <svg className="w-3 h-3 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20"><path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" /></svg>}</button>))
              )}
            </div>
          </div>
        )}
      </th>
    );
  };

  return (
    <div className="space-y-10 pb-16">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-6 h-[100px] hover:shadow-md transition-shadow">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-6 h-[100px] hover:shadow-md transition-shadow">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">物料出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-2xl border border-slate-100 shadow-sm flex flex-col overflow-hidden transition-all duration-300 hover:shadow-md">
           <div className="p-6 flex items-center justify-between bg-white border-b border-slate-50">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
                <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">业务单据总数</p><div className="flex items-baseline gap-2"><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p><span className="text-[10px] text-slate-400 font-bold">张</span></div></div>
              </div>
              <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className={`p-2 rounded-xl transition-all ${isOrdersExpanded ? 'bg-amber-100 text-amber-700' : 'bg-slate-50 text-slate-400 hover:bg-slate-100 hover:text-slate-600'}`} title={isOrdersExpanded ? "折叠列表" : "展开单号列表"}><svg className={`w-5 h-5 transition-transform duration-300 ${isOrdersExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
           </div>
           <div className={`overflow-hidden transition-all duration-500 ease-in-out ${isOrdersExpanded ? 'max-height-[500px] opacity-100' : 'max-h-0 opacity-0 pointer-events-none'}`}>
              <div className="px-5 py-5 bg-slate-50/50 border-t border-slate-100 space-y-4">
                <div className="flex items-center justify-between"><div className="flex items-center gap-2"><span className="w-1.5 h-1.5 bg-amber-500 rounded-full animate-pulse"></span><p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">单号实时索引</p></div><div className="relative"><input type="text" placeholder="快速检索单号..." value={orderSearchTerm} onChange={(e) => setOrderSearchTerm(e.target.value)} className="bg-white border border-slate-200 rounded-lg pl-8 pr-3 py-1.5 text-[10px] outline-none focus:border-amber-400 focus:ring-4 focus:ring-amber-50 w-40 font-bold transition-all shadow-sm placeholder:font-normal" /><svg className="w-3.5 h-3.5 absolute left-2.5 top-2.5 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg></div></div>
                <div className="bg-white/60 p-3 rounded-xl border border-slate-100">
                  <div className="max-h-40 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar pr-1">
                    {filteredOrderIds.length > 0 ? (filteredOrderIds.map(id => (<button key={id} onClick={() => onSelectOrderId(id)} className="px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-black text-slate-600 hover:border-amber-400 hover:text-amber-700 hover:bg-amber-50 hover:shadow-sm transition-all group flex items-center gap-1.5"><span className="w-1 h-1 bg-slate-300 rounded-full group-hover:bg-amber-400"></span>{id}</button>))) : (<div className="w-full py-6 text-center"><p className="text-[10px] text-slate-400 italic">没有找到匹配的单据号</p></div>)}
                  </div>
                </div>
                <div className="flex justify-between items-center px-1"><p className="text-[9px] text-slate-400 font-bold">显示 {filteredOrderIds.length} / {summary.orderCount} 条</p><button onClick={() => setIsOrdersExpanded(false)} className="text-[9px] font-black text-amber-600 uppercase tracking-widest hover:underline">收起面板</button></div>
              </div>
           </div>
        </div>
      </div>

      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-8">
          <div><h3 className="text-lg font-black text-slate-900 flex items-center gap-2">📈 业绩增长趋势</h3><p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 font-mono">Monthly Performance History</p></div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setShowCfa(!showCfa)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>金额 (CFA)</button>
            <button onClick={() => setShowQuantity(!showQuantity)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>数量</button>
          </div>
        </div>
        <div className="h-[450px]">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={summary.monthlyTrend} margin={{ left: 0, right: 10, top: 0, bottom: 0 }}>
              <defs><linearGradient id="gSales" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#6366f1" stopOpacity={0.15}/><stop offset="95%" stopColor="#6366f1" stopOpacity={0}/></linearGradient><linearGradient id="gQty" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#10b981" stopOpacity={0.15}/><stop offset="95%" stopColor="#10b981" stopOpacity={0}/></linearGradient></defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} dy={10} />
              <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#6366f1', fontSize: 10, fontWeight: 'bold'}} />
              <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 10, fontWeight: 'bold'}} />
              <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }} />
              {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" name="销售额" stroke="#6366f1" strokeWidth={4} fill="url(#gSales)" />}
              {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" name="出库量" stroke="#10b981" strokeWidth={4} fill="url(#gQty)" />}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </section>

      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200 relative min-h-[600px] overflow-hidden">
        <div className="flex justify-between items-center mb-10">
          <div><h3 className="text-lg font-black text-slate-900 flex items-center gap-2">🧩 品类业务构成</h3><p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 font-mono">Market Share Analysis</p></div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'sales' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>按金额</button>
            <button onClick={() => setPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>按数量</button>
          </div>
        </div>
        <div className="flex flex-col xl:flex-row items-center gap-16">
          <div className="relative w-full xl:w-[600px] h-[480px] flex-shrink-0">
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none text-center">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">当前总量</p>
              <p className={`text-4xl font-black ${pieMetric === 'sales' ? 'text-indigo-600' : 'text-emerald-600'}`}>{currentTotal.toLocaleString()}</p>
            </div>
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie 
                  data={sortedCategorySummary} 
                  cx="50%" 
                  cy="50%" 
                  innerRadius={110} 
                  outerRadius={160} 
                  paddingAngle={5} 
                  dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} 
                  onClick={(d) => setSelectedCategory(d.name)} 
                  stroke="none" 
                  style={{ cursor: 'pointer', outline: 'none' }}
                  label={renderCustomizedLabel}
                  labelLine={false}
                >
                  {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} opacity={selectedCategory && selectedCategory !== sortedCategorySummary[i].name ? 0.3 : 1} />)}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-2 gap-4">
            {sortedCategorySummary.map((item, idx) => {
              const val = pieMetric === 'sales' ? item.sales : item.quantity;
              const isSelected = selectedCategory === item.name;
              return (
                <button key={item.name} onClick={() => setSelectedCategory(item.name)} className={`flex items-center justify-between p-5 rounded-2xl border transition-all ${isSelected ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl scale-[1.02]' : 'bg-slate-50 border-slate-100 hover:bg-white hover:border-indigo-300'}`}>
                  <div className="flex items-center gap-4 text-left min-w-0"><div className="w-2.5 h-10 rounded-full flex-shrink-0" style={{ backgroundColor: isSelected ? '#fff' : COLORS[idx % COLORS.length] }}></div><div className="min-w-0"><p className="text-sm font-black truncate">{item.name}</p><p className={`text-[10px] font-bold uppercase tracking-tight ${isSelected ? 'text-indigo-100' : 'text-slate-400'}`}>占比 {(val / currentTotal * 100).toFixed(1)}%</p></div></div>
                  <p className="text-lg font-mono font-black">{val.toLocaleString()}</p>
                </button>
              );
            })}
          </div>
        </div>
        {selectedCategory && (
          <div className="absolute inset-0 bg-white/98 backdrop-blur-2xl z-[2000] p-10 flex flex-col animate-in slide-in-from-bottom duration-500 overflow-hidden">
            <div className="flex items-center justify-between mb-8 pb-6 border-b border-slate-100"><div className="flex items-center gap-6"><div className="w-14 h-14 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-xl text-2xl font-black">C</div><div><h4 className="text-[10px] font-black text-indigo-500 uppercase tracking-[0.3em] mb-1">Drilldown Cascading Analytics</h4><h3 className="text-3xl font-black text-slate-900">{selectedCategory}</h3></div></div><div className="flex items-center gap-4">{Object.values(localTableFilters).some(v => v !== '') && (<button onClick={() => setLocalTableFilters({id:'', date:'', customer:'', salesperson:'', itemName:''})} className="text-xs font-bold text-red-500 hover:underline">清除局部筛选</button>)}<button onClick={() => { setSelectedCategory(null); setLocalTableFilters({ id: '', date: '', customer: '', salesperson: '', itemName: '' }); }} className="flex items-center gap-2 px-6 py-3 bg-slate-900 text-white hover:bg-red-600 rounded-2xl text-sm font-bold transition-all shadow-lg">退出分析</button></div></div>
            <div className="flex-1 flex flex-col gap-8 overflow-hidden">
              <div className="h-[240px] flex-shrink-0 bg-slate-50/50 rounded-3xl p-6 border border-slate-100 flex flex-col"><div className="flex items-center justify-between mb-4 px-2"><h5 className="text-[11px] font-black text-slate-800 uppercase tracking-widest flex items-center gap-2"><span className="w-1.5 h-3 bg-indigo-500 rounded-full"></span> 客户成交分布 (点击柱条快速筛选下方表格)</h5><span className="text-[10px] font-bold text-slate-400">当前维度: {pieMetric === 'sales' ? '金额' : '数量'}</span></div>
                <div className="flex-1">
                  <ResponsiveContainer width="100%" height="100%"><BarChart data={drillDownData.customers.slice(0, 15)} margin={{ left: 0, right: 30, top: 10, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" /><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10, fontWeight: 'bold'}} /><YAxis hide /><Tooltip cursor={{fill: '#e2e8f0', opacity: 0.3}} contentStyle={{borderRadius: '12px', border: 'none', fontWeight: 'bold'}} /><Bar dataKey={pieMetric === 'sales' ? 'sales' : 'qty'} fill="#6366f1" radius={[8, 8, 0, 0]} barSize={40} onClick={(d) => setLocalTableFilters(p => ({...p, customer: d.name === p.customer ? '' : d.name}))} style={{ cursor: 'pointer' }}>{drillDownData.customers.map((_, i) => (<RechartsCell key={i} fill={localTableFilters.customer === _.name ? '#4338ca' : COLORS[i % COLORS.length]} />))}<LabelList dataKey="percentage" position="top" fill="#94a3b8" fontSize={9} fontWeight="black" offset={8} /></Bar></BarChart></ResponsiveContainer>
                </div>
              </div>
              <div className="flex-1 flex flex-col min-h-0 bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden"><div className="px-6 py-4 bg-slate-50/50 border-b border-slate-100 flex justify-between items-center"><h5 className="text-[11px] font-black text-slate-800 uppercase tracking-widest flex items-center gap-2 font-mono"><span className="w-1.5 h-3 bg-emerald-500 rounded-full"></span> Detail List (Cascading-Enabled)</h5><div className="flex items-center gap-8"><div className="text-[10px] font-bold text-slate-400">有效明细: <span className="text-indigo-600 font-black">{drillDownData.records.length}</span></div><div className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">当前筛选总计: <span className="text-slate-900 font-black text-xs">{drillDownData.drillDownTotal.toLocaleString()} {pieMetric === 'sales' ? 'CFA' : '件'}</span></div></div></div>
                <div className="flex-1 overflow-auto custom-scrollbar">
                  <table className="min-w-full text-[11px] border-separate border-spacing-0"><thead className="bg-slate-50 sticky top-0 z-50"><tr><FilterHeader label="单号" columnId="id" /><FilterHeader label="日期" columnId="date" /><FilterHeader label="客户" columnId="customer" /><FilterHeader label="销售员" columnId="salesperson" /><FilterHeader label="物料名称" columnId="itemName" /><th className="px-4 py-3 text-right font-bold text-slate-400 uppercase tracking-widest text-[10px] bg-slate-50">数量</th><th className="px-4 py-3 text-right font-bold text-slate-400 uppercase tracking-widest text-[10px] bg-slate-50">金额 (CFA)</th></tr></thead>
                    <tbody className="divide-y divide-slate-100 bg-white">{drillDownData.records.map((r, i) => (<tr key={i} className="hover:bg-indigo-50/40 transition-colors group"><td className="px-4 py-3.5 text-indigo-600 font-mono font-black"><button onClick={() => onSelectOrderId(r.id)} className="hover:underline text-left">{r.id}</button></td><td className="px-4 py-3.5 text-slate-500 font-mono">{r.date}</td><td className="px-4 py-3.5"><button onClick={() => setLocalTableFilters(p => ({...p, customer: r.customer}))} className={`font-bold transition-colors text-left ${localTableFilters.customer === r.customer ? 'text-indigo-600' : 'text-slate-900 hover:text-indigo-500'}`}>{r.customer}</button></td><td className="px-4 py-3.5 text-slate-600 font-semibold">{r.salesperson}</td><td className="px-4 py-3.5 text-slate-700 font-bold truncate max-w-[220px]" title={r.itemName}>{r.itemName}</td><td className="px-4 py-3.5 text-right font-mono font-bold text-indigo-600">{r.quantity}</td><td className="px-4 py-3.5 text-right font-mono font-black text-slate-900 group-hover:text-indigo-700">{r.totalAmount.toLocaleString()}</td></tr>))}</tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        )}
      </section>

      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-10"><div><h3 className="text-lg font-black text-slate-900 flex items-center gap-2">🏆 销售绩效排行榜</h3><p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 font-mono">Performance Leaderboard</p></div><div className="px-4 py-1.5 bg-indigo-50 text-indigo-600 rounded-full text-[10px] font-black border border-indigo-100 uppercase tracking-[0.2em]">单位: 西非法郎 (CFA)</div></div>
        <div className="h-[450px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={summary.salespersonPerformance} layout="vertical" margin={{ left: 20, right: 120, top: 0, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" /><XAxis type="number" hide /><YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={100} tick={{fill: '#1e293b', fontWeight: 800, fontSize: 13}} /><Tooltip cursor={{fill: '#f8fafc'}} formatter={(v) => [`${v.toLocaleString()} CFA`, '业绩金额']} /><Bar dataKey="value" fill="#6366f1" radius={[0, 12, 12, 0]} barSize={32}>{summary.salespersonPerformance.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}<LabelList dataKey="value" position="right" formatter={(v: any) => `${v.toLocaleString()} CFA`} fill="#1e293b" fontSize={12} fontWeight="black" offset={20} /></Bar></BarChart></ResponsiveContainer></div>
      </section>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  const [localTableFilters, setLocalTableFilters] = useState({ 
    id: '', 
    date: '', 
    customer: '', 
    salesperson: '',
    itemName: '' 
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const globalTotals = useMemo(() => {
    return sortedCategorySummary.reduce((acc, cur) => {
      acc.sales += cur.sales;
      acc.quantity += cur.quantity;
      return acc;
    }, { sales: 0, quantity: 0 });
  }, [sortedCategorySummary]);

  const currentTotal = pieMetric === 'sales' ? globalTotals.sales : globalTotals.quantity;

  const filteredOrderIds = useMemo(() => {
    return summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase()));
  }, [summary.orderIds, orderSearchTerm]);

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-RADIAN * midAngle);
    const cos = Math.cos(-RADIAN * midAngle);
    const sx = cx + (outerRadius + 5) * cos;
    const sy = cy + (outerRadius + 5) * sin;
    const mx = cx + (outerRadius + 30) * cos;
    const my = cy + (outerRadius + 30) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 22;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} opacity={0.6} />
        <circle cx={ex} cy={ey} r={2} fill={fill} />
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} textAnchor={textAnchor} fill="#1e293b" style={{ fontSize: '11px', fontWeight: 900 }}>{name}</text>
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} dy={14} textAnchor={textAnchor} fill="#64748b" style={{ fontSize: '10px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  const drillDownData = useMemo(() => {
    if (!selectedCategory) return { customers: [], records: [], drillDownTotal: 0, cascadingOptions: {}, trendData: [] };

    const baseRecords = filteredData.filter(r => r.category === selectedCategory);

    // 基础过滤（面板内级联逻辑）
    const filteredRecords = baseRecords.filter(r => {
      const matchId = !localTableFilters.id || r.id === localTableFilters.id;
      const matchDate = !localTableFilters.date || r.date === localTableFilters.date;
      const matchCustomer = !localTableFilters.customer || r.customer === localTableFilters.customer;
      const matchSalesperson = !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
      const matchItemName = !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
      return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
    });

    // 计算特定趋势图数据：仅当客户和物料都被选中时
    let trendData: any[] = [];
    if (localTableFilters.customer && localTableFilters.itemName) {
      const specificRecords = baseRecords.filter(r => 
        r.customer === localTableFilters.customer && 
        r.itemName === localTableFilters.itemName
      );
      // 按日期分组汇总
      const dayMap = new Map<string, number>();
      specificRecords.forEach(r => {
        const val = pieMetric === 'sales' ? r.totalAmount : r.quantity;
        dayMap.set(r.date, (dayMap.get(r.date) || 0) + val);
      });
      trendData = Array.from(dayMap.entries())
        .map(([date, value]) => ({ date, value }))
        .sort((a, b) => a.date.localeCompare(b.date));
    }

    const getOptionsFor = (key: keyof typeof localTableFilters) => {
      const tempFiltered = baseRecords.filter(r => {
        const matchId = key === 'id' || !localTableFilters.id || r.id === localTableFilters.id;
        const matchDate = key === 'date' || !localTableFilters.date || r.date === localTableFilters.date;
        const matchCustomer = key === 'customer' || !localTableFilters.customer || r.customer === localTableFilters.customer;
        const matchSalesperson = key === 'salesperson' || !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
        const matchItemName = key === 'itemName' || !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
        return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
      });
      return Array.from(new Set(tempFiltered.map(r => r[key === 'itemName' ? 'itemName' : key as keyof SalesRecord] as string))).sort();
    };

    const cascadingOptions = { id: getOptionsFor('id'), date: getOptionsFor('date').reverse(), customer: getOptionsFor('customer'), salesperson: getOptionsFor('salesperson'), itemName: getOptionsFor('itemName') };

    const customersMap = new Map<string, { sales: number; qty: number }>();
    baseRecords.forEach(record => {
      const c = customersMap.get(record.customer) || { sales: 0, qty: 0 };
      customersMap.set(record.customer, { sales: c.sales + record.totalAmount, qty: c.qty + record.quantity });
    });
    const catTotal = baseRecords.reduce((s, r) => s + (pieMetric === 'sales' ? r.totalAmount : r.quantity), 0);
    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty, percentage: catTotal > 0 ? (((pieMetric === 'sales' ? val.sales : val.qty) / catTotal) * 100).toFixed(1) + '%' : '0%' }))
      .sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);
    const drillDownTotal = filteredRecords.reduce((s, r) => s + (pieMetric === 'sales' ? r.totalAmount : r.quantity), 0);

    return { customers, records: filteredRecords.sort((a, b) => b.date.localeCompare(a.date)), drillDownTotal, cascadingOptions, trendData };
  }, [selectedCategory, filteredData, pieMetric, localTableFilters]);

  const FilterHeader = ({ label, columnId }: { label: string, columnId: keyof typeof localTableFilters }) => {
    const options = (drillDownData.cascadingOptions as any)[columnId] || [];
    const isSelected = !!localTableFilters[columnId];
    return (
      <th className="px-4 py-3 text-left relative group bg-slate-50 border-b border-slate-100">
        <div className="flex items-center gap-1.5">
          <span className="font-bold text-slate-400 uppercase tracking-widest text-[10px] whitespace-nowrap">{label}</span>
          <button onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)} className={`p-1 rounded-md transition-all ${isSelected ? 'text-indigo-600 bg-indigo-50 shadow-sm' : 'text-slate-300 hover:text-indigo-400'}`}>
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" /></svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-64 bg-white rounded-xl shadow-2xl border border-slate-200 z-[3000] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2.5 border-b border-slate-50 bg-slate-50 flex justify-between items-center"><span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label} 级联筛选</span>{isSelected && <button onClick={() => setLocalTableFilters(p => ({...p, [columnId]: ''}))} className="text-[10px] font-bold text-red-500 hover:underline">清除</button>}</div>
            <div className="max-h-64 overflow-y-auto p-1 custom-scrollbar">
              {options.length === 0 ? (<div className="px-3 py-4 text-center text-xs text-slate-400 italic">当前组合下无可选项</div>) : (
