  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [perfMetric, setPerfMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  const [localTableFilters, setLocalTableFilters] = useState({ 
    id: '', 
    date: '', 
    customer: '', 
    salesperson: '',
    itemName: '' 
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, itemPieMetric]);

  const sortedSalespersonPerf = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.salesperson) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.salesperson, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => perfMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, perfMetric]);

  const globalTotals = useMemo(() => {
    return sortedCategorySummary.reduce((acc, cur) => {
      acc.sales += cur.sales;
      acc.quantity += cur.quantity;
      return acc;
    }, { sales: 0, quantity: 0 });
  }, [sortedCategorySummary]);

  const currentCategoryTotal = pieMetric === 'sales' ? globalTotals.sales : globalTotals.quantity;
  const currentItemTotal = itemPieMetric === 'sales' ? globalTotals.sales : globalTotals.quantity;

  const filteredOrderIds = useMemo(() => {
    return summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase()));
  }, [summary.orderIds, orderSearchTerm]);

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-RADIAN * midAngle);
    const cos = Math.cos(-RADIAN * midAngle);
    const sx = cx + (outerRadius + 5) * cos;
    const sy = cy + (outerRadius + 5) * sin;
    const mx = cx + (outerRadius + 30) * cos;
    const my = cy + (outerRadius + 30) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 22;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} opacity={0.6} />
        <circle cx={ex} cy={ey} r={2} fill={fill} />
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} textAnchor={textAnchor} fill="#1e293b" style={{ fontSize: '11px', fontWeight: 900 }}>{name}</text>
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} dy={14} textAnchor={textAnchor} fill="#64748b" style={{ fontSize: '10px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  const drillDownData = useMemo(() => {
    const activeDimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : null);
    const activeValue = selectedCategory || selectedItem;
    const currentMetric = selectedCategory ? pieMetric : itemPieMetric;

    if (!activeDimension || !activeValue) return { customers: [], records: [], drillDownTotal: 0, cascadingOptions: {}, trendData: [], trendTitle: '' };

    const baseRecords = filteredData.filter(r => r[activeDimension] === activeValue);

    const filteredRecords = baseRecords.filter(r => {
      const matchId = !localTableFilters.id || r.id === localTableFilters.id;
      const matchDate = !localTableFilters.date || r.date === localTableFilters.date;
      const matchCustomer = !localTableFilters.customer || r.customer === localTableFilters.customer;
      const matchSalesperson = !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
      const matchItemName = !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
      return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
    });

    const trendMap = new Map<string, number>();
    filteredRecords.forEach(r => {
      const val = currentMetric === 'sales' ? r.totalAmount : r.quantity;
      trendMap.set(r.month, (trendMap.get(r.month) || 0) + val);
    });
    const trendData = Array.from(trendMap.entries())
      .map(([month, value]) => ({ month, value }))
      .sort((a, b) => a.month.localeCompare(b.month));

    let trendTitle = `${activeValue} 全市场趋势`;
    if (localTableFilters.customer && (localTableFilters.itemName || selectedItem)) {
      trendTitle = `${localTableFilters.customer} 对 ${selectedItem || localTableFilters.itemName} 的精确采购轨迹`;
    } else if (localTableFilters.customer) {
      trendTitle = `${localTableFilters.customer} 在 ${activeValue} 维度的采购波动`;
    } else if (localTableFilters.itemName) {
      trendTitle = `${localTableFilters.itemName} 单品全市场销售趋势`;
    }

    const getOptionsFor = (key: keyof typeof localTableFilters) => {
      const tempFiltered = baseRecords.filter(r => {
        const matchId = key === 'id' || !localTableFilters.id || r.id === localTableFilters.id;
        const matchDate = key === 'date' || !localTableFilters.date || r.date === localTableFilters.date;
        const matchCustomer = key === 'customer' || !localTableFilters.customer || r.customer === localTableFilters.customer;
        const matchSalesperson = key === 'salesperson' || !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
        const matchItemName = key === 'itemName' || !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
        return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
      });
      return Array.from(new Set(tempFiltered.map(r => r[key === 'itemName' ? 'itemName' : key as keyof SalesRecord] as string))).sort();
    };

    const cascadingOptions = { id: getOptionsFor('id'), date: getOptionsFor('date').reverse(), customer: getOptionsFor('customer'), salesperson: getOptionsFor('salesperson'), itemName: getOptionsFor('itemName') };

    const customersMap = new Map<string, { sales: number; qty: number }>();
    baseRecords.forEach(record => {
      const c = customersMap.get(record.customer) || { sales: 0, qty: 0 };
      customersMap.set(record.customer, { sales: c.sales + record.totalAmount, qty: c.qty + record.quantity });
    });
    const drillDownBaseTotal = baseRecords.reduce((s, r) => s + (currentMetric === 'sales' ? r.totalAmount : r.quantity), 0);
    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty, percentage: drillDownBaseTotal > 0 ? (((currentMetric === 'sales' ? val.sales : val.qty) / drillDownBaseTotal) * 100).toFixed(1) + '%' : '0%' }))
      .sort((a, b) => currentMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const drillDownTotal = filteredRecords.reduce((s, r) => s + (currentMetric === 'sales' ? r.totalAmount : r.quantity), 0);

    return { customers, records: filteredRecords.sort((a, b) => b.date.localeCompare(a.date)), drillDownTotal, cascadingOptions, trendData, trendTitle };
  }, [selectedCategory, selectedItem, filteredData, pieMetric, itemPieMetric, localTableFilters]);

  const FilterHeader = ({ label, columnId }: { label: string, columnId: keyof typeof localTableFilters }) => {
    const options = (drillDownData.cascadingOptions as any)[columnId] || [];
    const isSelected = !!localTableFilters[columnId];
    return (
      <th className="px-4 py-3 text-left relative group bg-slate-50 border-b border-slate-100">
        <div className="flex items-center gap-1.5">
          <span className="font-bold text-slate-400 uppercase tracking-widest text-[10px] whitespace-nowrap">{label}</span>
          <button onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)} className={`p-1 rounded-md transition-all ${isSelected ? 'text-indigo-600 bg-indigo-50 shadow-sm' : 'text-slate-300 hover:text-indigo-400'}`}>
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" /></svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-64 bg-white rounded-xl shadow-2xl border border-slate-200 z-[3000] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2.5 border-b border-slate-50 bg-slate-50 flex justify-between items-center"><span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label} 级联筛选</span>{isSelected && <button onClick={() => setLocalTableFilters(p => ({...p, [columnId]: ''}))} className="text-[10px] font-bold text-red-500 hover:underline">清除</button>}</div>
            <div className="max-h-64 overflow-y-auto p-1 custom-scrollbar">
              {options.length === 0 ? (<div className="px-3 py-4 text-center text-xs text-slate-400 italic">无匹配</div>) : (
                options.map((opt: string) => (<button key={opt} onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }} className={`w-full text-left px-3 py-2 rounded-lg text-xs transition-colors flex items-center justify-between ${localTableFilters[columnId] === opt ? 'bg-indigo-50 text-indigo-600 font-bold' : 'text-slate-600 hover:bg-slate-50'}`}><span className="truncate pr-2">{opt}</span>{localTableFilters[columnId] === opt && <svg className="w-3 h-3 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20"><path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" /></svg>}</button>))
              )}
            </div>
          </div>
        )}
      </th>
    );
  };

  return (
    <div className="space-y-10 pb-16">
      {/* 核心指标卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-6 h-[100px] hover:shadow-md transition-shadow">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-6 h-[100px] hover:shadow-md transition-shadow">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">物料出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-2xl border border-slate-100 shadow-sm flex flex-col overflow-hidden transition-all duration-300 hover:shadow-md">
           <div className="p-6 flex items-center justify-between bg-white border-b border-slate-50">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
                <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">业务单据总数</p><div className="flex items-baseline gap-2"><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p><span className="text-[10px] text-slate-400 font-bold">张</span></div></div>
              </div>
              <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className={`p-2 rounded-xl transition-all ${isOrdersExpanded ? 'bg-amber-100 text-amber-700' : 'bg-slate-50 text-slate-400 hover:bg-slate-100 hover:text-slate-600'}`}><svg className={`w-5 h-5 transition-transform duration-300 ${isOrdersExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
           </div>
           {isOrdersExpanded && (
              <div className="px-5 py-5 bg-slate-50/50 border-t border-slate-100 space-y-4 animate-in slide-in-from-top-4">
                <div className="flex items-center justify-between"><div className="flex items-center gap-2"><span className="w-1.5 h-1.5 bg-amber-500 rounded-full animate-pulse"></span><p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">单号实时索引</p></div><div className="relative"><input type="text" placeholder="快速检索单号..." value={orderSearchTerm} onChange={(e) => setOrderSearchTerm(e.target.value)} className="bg-white border border-slate-200 rounded-lg pl-8 pr-3 py-1.5 text-[10px] outline-none focus:border-amber-400 w-40 font-bold shadow-sm transition-all" /><svg className="w-3.5 h-3.5 absolute left-2.5 top-2.5 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg></div></div>
                <div className="max-h-40 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar pr-1">
                  {filteredOrderIds.map(id => (<button key={id} onClick={() => onSelectOrderId(id)} className="px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-black text-slate-600 hover:border-amber-400 hover:text-amber-700 hover:bg-amber-50 transition-all">{id}</button>))}
                </div>
              </div>
           )}
        </div>
      </div>

      {/* 业绩增长趋势 (恢复此模块) */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-8">
          <div><h3 className="text-lg font-black text-slate-900 flex items-center gap-2">📈 业绩增长趋势</h3><p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 font-mono">Monthly Performance History</p></div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setShowCfa(!showCfa)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${showCfa ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>金额 (CFA)</button>
            <button onClick={() => setShowQuantity(!showQuantity)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${showQuantity ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>数量</button>
          </div>
        </div>
        <div className="h-[450px]">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={summary.monthlyTrend} margin={{ left: 0, right: 10, top: 0, bottom: 0 }}>
              <defs>
                <linearGradient id="gSales" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#6366f1" stopOpacity={0.15}/><stop offset="95%" stopColor="#6366f1" stopOpacity={0}/></linearGradient>
                <linearGradient id="gQty" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#10b981" stopOpacity={0.15}/><stop offset="95%" stopColor="#10b981" stopOpacity={0}/></linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} dy={10} />
              <YAxis yAxisId="left" hide={!showCfa} axisLine={false} tickLine={false} tick={{fill: '#6366f1', fontSize: 10, fontWeight: 'bold'}} />
              <YAxis yAxisId="right" orientation="right" hide={!showQuantity} axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 10, fontWeight: 'bold'}} />
              <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }} />
              {showCfa && <Area yAxisId="left" type="monotone" dataKey="sales" name="销售额" stroke="#6366f1" strokeWidth={4} fill="url(#gSales)" animationDuration={1500} />}
              {showQuantity && <Area yAxisId="right" type="monotone" dataKey="quantity" name="出库量" stroke="#10b981" strokeWidth={4} fill="url(#gQty)" animationDuration={1500} />}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </section>

      {/* 品类业务构成 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200 relative min-h-[600px] overflow-hidden">
        <div className="flex justify-between items-center mb-10">
          <div><h3 className="text-lg font-black text-slate-900 flex items-center gap-2">🧩 品类业务构成</h3><p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 font-mono">Analysis by Category</p></div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'sales' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>按金额</button>
            <button onClick={() => setPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>按数量</button>
          </div>
        </div>
        <div className="flex flex-col xl:flex-row items-center gap-16">
          <div className="relative w-full xl:w-[600px] h-[480px] flex-shrink-0">
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none text-center">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">总量</p>
              <p className={`text-4xl font-black ${pieMetric === 'sales' ? 'text-indigo-600' : 'text-emerald-600'}`}>{currentCategoryTotal.toLocaleString()}</p>
            </div>
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={sortedCategorySummary} cx="50%" cy="50%" innerRadius={110} outerRadius={160} paddingAngle={5} dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} onClick={(d) => { setSelectedCategory(d.name); setSelectedItem(null); }} stroke="none" label={renderCustomizedLabel} labelLine={false} animationDuration={1000}>
                  {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} opacity={selectedCategory && selectedCategory !== sortedCategorySummary[i].name ? 0.3 : 1} />)}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-2 gap-4">
            {sortedCategorySummary.map((item, idx) => (
              <button key={item.name} onClick={() => { setSelectedCategory(item.name); setSelectedItem(null); }} className={`flex items-center justify-between p-5 rounded-2xl border transition-all ${selectedCategory === item.name ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl scale-[1.02]' : 'bg-slate-50 border-slate-100 hover:border-indigo-300'}`}>
                <div className="flex items-center gap-4 text-left min-w-0"><div className="w-2.5 h-10 rounded-full" style={{ backgroundColor: selectedCategory === item.name ? '#fff' : COLORS[idx % COLORS.length] }}></div><div className="min-w-0"><p className="text-sm font-black truncate">{item.name}</p></div></div>
                <p className="text-lg font-mono font-black">{(pieMetric === 'sales' ? item.sales : item.quantity).toLocaleString()}</p>
              </button>
            ))}
          </div>
        </div>
      </section>

      {/* 物料业务构成 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200 relative min-h-[600px] overflow-hidden">
        <div className="flex justify-between items-center mb-10">
          <div><h3 className="text-lg font-black text-slate-900 flex items-center gap-2">📦 物料业务构成</h3><p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 font-mono">Deep Item Analysis</p></div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setItemPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${itemPieMetric === 'sales' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>按金额</button>
            <button onClick={() => setItemPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${itemPieMetric === 'quantity' ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>按数量</button>
          </div>
        </div>
        <div className="flex flex-col xl:flex-row items-center gap-16">
          <div className="relative w-full xl:w-[600px] h-[480px] flex-shrink-0">
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none text-center">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">物料总量</p>
              <p className={`text-4xl font-black ${itemPieMetric === 'sales' ? 'text-indigo-600' : 'text-emerald-600'}`}>{currentItemTotal.toLocaleString()}</p>
            </div>
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={sortedItemSummary.slice(0, 10)} cx="50%" cy="50%" innerRadius={110} outerRadius={160} paddingAngle={5} dataKey={itemPieMetric === 'sales' ? 'sales' : 'quantity'} onClick={(d) => { setSelectedItem(d.name); setSelectedCategory(null); }} stroke="none" label={renderCustomizedLabel} labelLine={false} animationDuration={1000}>
                  {sortedItemSummary.slice(0, 10).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} opacity={selectedItem && selectedItem !== sortedItemSummary[i].name ? 0.3 : 1} />)}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[500px] overflow-y-auto custom-scrollbar pr-2">
            {sortedItemSummary.map((item, idx) => (
              <button key={item.name} onClick={() => { setSelectedItem(item.name); setSelectedCategory(null); }} className={`flex items-center justify-between p-5 rounded-2xl border transition-all ${selectedItem === item.name ? 'bg-emerald-600 border-emerald-600 text-white shadow-xl scale-[1.02]' : 'bg-slate-50 border-slate-100 hover:border-emerald-300'}`}>
                <div className="flex items-center gap-4 text-left min-w-0"><div className="w-2.5 h-10 rounded-full" style={{ backgroundColor: selectedItem === item.name ? '#fff' : COLORS[idx % COLORS.length] }}></div><div className="min-w-0"><p className="text-sm font-black truncate">{item.name}</p></div></div>
                <p className="text-lg font-mono font-black">{(itemPieMetric === 'sales' ? item.sales : item.quantity).toLocaleString()}</p>
              </button>
            ))}
          </div>
        </div>

        {/* 下钻深度分析面板 */}
        {(selectedCategory || selectedItem) && (
          <div className="absolute inset-0 bg-white/98 backdrop-blur-3xl z-[2000] p-10 flex flex-col animate-in slide-in-from-bottom-8 duration-500 overflow-hidden">
            <div className="flex items-center justify-between mb-8 pb-6 border-b border-slate-100 flex-shrink-0">
              <div className="flex items-center gap-6">
                <div className={`w-14 h-14 ${selectedItem ? 'bg-emerald-600' : 'bg-indigo-600'} rounded-2xl flex items-center justify-center text-white text-2xl font-black shadow-xl`}>{selectedItem ? 'I' : 'C'}</div>
                <div><h4 className={`text-[10px] font-black ${selectedItem ? 'text-emerald-500' : 'text-indigo-500'} uppercase tracking-[0.3em] mb-1`}>Dynamic Drilldown Analysis</h4><h3 className="text-3xl font-black text-slate-900">{selectedCategory || selectedItem}</h3></div>
              </div>
              <button onClick={() => { setSelectedCategory(null); setSelectedItem(null); setLocalTableFilters({ id: '', date: '', customer: '', salesperson: '', itemName: '' }); }} className="px-6 py-3 bg-slate-900 text-white rounded-2xl text-sm font-bold shadow-lg hover:bg-red-600 transition-colors">退出分析</button>
            </div>

            <div className="flex-1 flex flex-col gap-6 overflow-y-auto custom-scrollbar pr-2 pb-8">
              {/* 客户成交分布 */}
              <div className="h-[220px] flex-shrink-0 bg-slate-50/50 rounded-3xl p-6 border border-slate-100 flex flex-col"><div className="flex items-center justify-between mb-4 px-2"><h5 className="text-[11px] font-black text-slate-800 uppercase tracking-widest flex items-center gap-2"><span className={`w-1.5 h-3 ${selectedItem ? 'bg-emerald-500' : 'bg-indigo-500'} rounded-full`}></span> 客户成交分布</h5></div>
                <div className="flex-1">
                  <ResponsiveContainer width="100%" height="100%"><BarChart data={drillDownData.customers.slice(0, 15)} margin={{ left: 0, right: 30, top: 10, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" /><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10, fontWeight: 'bold'}} /><YAxis hide /><Tooltip cursor={{fill: '#e2e8f0', opacity: 0.3}} /><Bar dataKey={(selectedCategory ? pieMetric : itemPieMetric) === 'sales' ? 'sales' : 'qty'} fill={selectedItem ? '#10b981' : '#6366f1'} radius={[8, 8, 0, 0]} barSize={40} onClick={(d) => setLocalTableFilters(p => ({...p, customer: d.name === p.customer ? '' : d.name}))} style={{ cursor: 'pointer' }}>{drillDownData.customers.map((_, i) => (<RechartsCell key={i} fill={localTableFilters.customer === _.name ? (selectedItem ? '#047857' : '#4338ca') : COLORS[i % COLORS.length]} />))}<LabelList dataKey="percentage" position="top" fill="#94a3b8" fontSize={9} fontWeight="black" offset={8} /></Bar></BarChart></ResponsiveContainer>
                </div>
              </div>

              {/* 明细列表 */}
              <div className="flex-shrink-0 flex flex-col bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden"><div className="px-6 py-4 bg-slate-50/50 border-b border-slate-100 flex justify-between items-center"><h5 className="text-[11px] font-black text-slate-800 uppercase tracking-widest">Detail List</h5><div className="text-[10px] font-bold text-slate-400 tracking-tighter">总计: <span className="text-slate-900 font-black text-xs">{drillDownData.drillDownTotal.toLocaleString()}</span></div></div>
                <div className="overflow-auto max-h-[400px] custom-scrollbar">
                  <table className="min-w-full text-[11px] border-separate border-spacing-0"><thead className="bg-slate-50 sticky top-0 z-50"><tr><FilterHeader label="单号" columnId="id" /><FilterHeader label="日期" columnId="date" /><FilterHeader label="客户" columnId="customer" /><FilterHeader label="销售员" columnId="salesperson" /><FilterHeader label="物料名称" columnId="itemName" /><th className="px-4 py-3 text-right text-slate-400 text-[10px]">数量</th><th className="px-4 py-3 text-right text-slate-400 text-[10px]">金额</th></tr></thead>
                    <tbody className="divide-y divide-slate-100 bg-white">{drillDownData.records.map((r, i) => (<tr key={i} className="hover:bg-blue-50/40 transition-colors"><td className="px-4 py-3.5 text-blue-600 font-mono font-black">{r.id}</td><td className="px-4 py-3.5 text-slate-500">{r.date}</td><td className="px-4 py-3.5 font-bold">{r.customer}</td><td className="px-4 py-3.5 text-slate-600">{r.salesperson}</td><td className="px-4 py-3.5 text-slate-700 truncate max-w-[180px]">{r.itemName}</td><td className="px-4 py-3.5 text-right font-bold">{r.quantity}</td><td className="px-4 py-3.5 text-right font-black">{r.totalAmount.toLocaleString()}</td></tr>))}</tbody>
                  </table>
                </div>
              </div>

              {/* 趋势扫描仪 (常驻版) */}
              <div className="flex-shrink-0 bg-slate-900 rounded-3xl p-8 border border-slate-700 shadow-2xl">
                <div className="flex items-center justify-between mb-8">
                  <div className="space-y-1"><div className="flex items-center gap-2"><span className="w-3 h-3 bg-amber-400 rounded-full animate-pulse shadow-[0_0_10px_rgba(251,191,36,0.6)]"></span><h5 className="text-[10px] font-black text-amber-400 uppercase tracking-[0.3em]">Adaptive Trend Scanner</h5></div><h3 className="text-xl font-black text-white">{drillDownData.trendTitle}</h3></div>
                  <div className="text-right text-2xl font-black text-white font-mono">{drillDownData.trendData.length} <span className="text-[10px] text-slate-500">MONTHS</span></div>
                </div>
                <div className="h-[280px] w-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={drillDownData.trendData} margin={{ left: 0, right: 10, top: 10, bottom: 0 }}>
                      <defs><linearGradient id="trendGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#fbbf24" stopOpacity={0.3}/><stop offset="95%" stopColor="#fbbf24" stopOpacity={0}/></linearGradient></defs>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#334155" opacity={0.5} />
                      <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 'bold'}} />
                      <YAxis hide />
                      <Tooltip contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155', borderRadius: '12px' }} />
                      <Area type="monotone" dataKey="value" stroke="#fbbf24" strokeWidth={4} fill="url(#trendGradient)" dot={{ r: 4, fill: '#fbbf24' }} activeDot={{ r: 7, fill: '#fff' }} />
                    </AreaChart>
                  </ResponsiveContainer>
                </div>
              </div>
            </div>
          </div>
        )}
      </section>

      {/* 销售绩效排行榜 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-10">
          <div><h3 className="text-lg font-black text-slate-900 flex items-center gap-2">🏆 销售绩效排行榜</h3><p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 font-mono">Performance Leaderboard</p></div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setPerfMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${perfMetric === 'sales' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}>按金额</button>
            <button onClick={() => setPerfMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${perfMetric === 'quantity' ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`}>按数量</button>
          </div>
        </div>
        <div className="h-[450px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={sortedSalespersonPerf} layout="vertical" margin={{ left: 20, right: 120, top: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={100} tick={{fill: '#1e293b', fontWeight: 800, fontSize: 13}} />
              <Tooltip cursor={{fill: '#f8fafc'}} />
              <Bar dataKey={perfMetric === 'sales' ? 'sales' : 'quantity'} fill="#6366f1" radius={[0, 12, 12, 0]} barSize={32}>
                 {sortedSalespersonPerf.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                 <LabelList dataKey={perfMetric === 'sales' ? 'sales' : 'quantity'} position="right" formatter={(v: any) => `${v.toLocaleString()}`} fill="#1e293b" fontSize={12} fontWeight="black" offset={20} />
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </section>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [perfMetric, setPerfMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [showCfa, setShowCfa] = useState(true);
  const [showQuantity, setShowQuantity] = useState(true);

  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  const [localTableFilters, setLocalTableFilters] = useState({ 
    id: '', 
    date: '', 
    customer: '', 
    salesperson: '',
    itemName: '' 
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, itemPieMetric]);

  const sortedSalespersonPerf = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.salesperson) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.salesperson, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => perfMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, perfMetric]);

  const globalTotals = useMemo(() => {
    return sortedCategorySummary.reduce((acc, cur) => {
      acc.sales += cur.sales;
      acc.quantity += cur.quantity;
      return acc;
    }, { sales: 0, quantity: 0 });
  }, [sortedCategorySummary]);

  const currentCategoryTotal = pieMetric === 'sales' ? globalTotals.sales : globalTotals.quantity;
  const currentItemTotal = itemPieMetric === 'sales' ? globalTotals.sales : globalTotals.quantity;

  const filteredOrderIds = useMemo(() => {
    return summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase()));
  }, [summary.orderIds, orderSearchTerm]);

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-RADIAN * midAngle);
    const cos = Math.cos(-RADIAN * midAngle);
    const sx = cx + (outerRadius + 5) * cos;
    const sy = cy + (outerRadius + 5) * sin;
    const mx = cx + (outerRadius + 30) * cos;
    const my = cy + (outerRadius + 30) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 22;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={2} opacity={0.6} />
        <circle cx={ex} cy={ey} r={3} fill={fill} />
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} textAnchor={textAnchor} fill="#0f172a" style={{ fontSize: '12px', fontWeight: 800 }}>{name}</text>
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} dy={16} textAnchor={textAnchor} fill="#475569" style={{ fontSize: '11px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  const drillDownData = useMemo(() => {
    const activeDimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : null);
    const activeValue = selectedCategory || selectedItem;
    const currentMetric = selectedCategory ? pieMetric : itemPieMetric;

    if (!activeDimension || !activeValue) return { customers: [], records: [], drillDownTotal: 0, cascadingOptions: {}, trendData: [], trendTitle: '' };

    const baseRecords = filteredData.filter(r => r[activeDimension] === activeValue);

    const filteredRecords = baseRecords.filter(r => {
      const matchId = !localTableFilters.id || r.id === localTableFilters.id;
      const matchDate = !localTableFilters.date || r.date === localTableFilters.date;
      const matchCustomer = !localTableFilters.customer || r.customer === localTableFilters.customer;
      const matchSalesperson = !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
      const matchItemName = !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
      return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
    });

    const trendMap = new Map<string, number>();
    filteredRecords.forEach(r => {
      const val = currentMetric === 'sales' ? r.totalAmount : r.quantity;
      trendMap.set(r.month, (trendMap.get(r.month) || 0) + val);
    });
    const trendData = Array.from(trendMap.entries())
      .map(([month, value]) => ({ month, value }))
      .sort((a, b) => a.month.localeCompare(b.month));

    let trendTitle = `${activeValue} 全市场趋势`;
    if (localTableFilters.customer && (localTableFilters.itemName || selectedItem)) {
      trendTitle = `${localTableFilters.customer} 对 ${selectedItem || localTableFilters.itemName} 的精确采购轨迹`;
    } else if (localTableFilters.customer) {
      trendTitle = `${localTableFilters.customer} 在 ${activeValue} 维度的采购波动`;
    } else if (localTableFilters.itemName) {
      trendTitle = `${localTableFilters.itemName} 单品全市场销售趋势`;
    }

    const getOptionsFor = (key: keyof typeof localTableFilters) => {
      const tempFiltered = baseRecords.filter(r => {
        const matchId = key === 'id' || !localTableFilters.id || r.id === localTableFilters.id;
        const matchDate = key === 'date' || !localTableFilters.date || r.date === localTableFilters.date;
        const matchCustomer = key === 'customer' || !localTableFilters.customer || r.customer === localTableFilters.customer;
        const matchSalesperson = key === 'salesperson' || !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
        const matchItemName = key === 'itemName' || !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
        return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
      });
      return Array.from(new Set(tempFiltered.map(r => r[key === 'itemName' ? 'itemName' : key as keyof SalesRecord] as string))).sort();
    };

    const cascadingOptions = { id: getOptionsFor('id'), date: getOptionsFor('date').reverse(), customer: getOptionsFor('customer'), salesperson: getOptionsFor('salesperson'), itemName: getOptionsFor('itemName') };

    const customersMap = new Map<string, { sales: number; qty: number }>();
    baseRecords.forEach(record => {
      const c = customersMap.get(record.customer) || { sales: 0, qty: 0 };
      customersMap.set(record.customer, { sales: c.sales + record.totalAmount, qty: c.qty + record.quantity });
    });
    const drillDownBaseTotal = baseRecords.reduce((s, r) => s + (currentMetric === 'sales' ? r.totalAmount : r.quantity), 0);
    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty, percentage: drillDownBaseTotal > 0 ? (((currentMetric === 'sales' ? val.sales : val.qty) / drillDownBaseTotal) * 100).toFixed(1) + '%' : '0%' }))
      .sort((a, b) => currentMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const drillDownTotal = filteredRecords.reduce((s, r) => s + (currentMetric === 'sales' ? r.totalAmount : r.quantity), 0);

    return { customers, records: filteredRecords.sort((a, b) => b.date.localeCompare(a.date)), drillDownTotal, cascadingOptions, trendData, trendTitle };
  }, [selectedCategory, selectedItem, filteredData, pieMetric, itemPieMetric, localTableFilters]);

  const FilterHeader = ({ label, columnId }: { label: string, columnId: keyof typeof localTableFilters }) => {
    const options = (drillDownData.cascadingOptions as any)[columnId] || [];
    const isSelected = !!localTableFilters[columnId];
    return (
      <th className="px-4 py-3 text-left relative group bg-slate-50 border-b border-slate-200">
        <div className="flex items-center gap-1.5">
          <span className="font-bold text-slate-600 uppercase tracking-widest text-[10px] whitespace-nowrap">{label}</span>
          <button onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)} className={`p-1 rounded-md transition-all ${isSelected ? 'text-indigo-600 bg-indigo-50 shadow-sm' : 'text-slate-400 hover:text-indigo-600'}`}>
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" /></svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-64 bg-white rounded-xl shadow-2xl border border-slate-200 z-[3000] overflow-hidden animate-in fade-in zoom-in duration-150">
            <div className="p-2.5 border-b border-slate-100 bg-slate-50 flex justify-between items-center"><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{label} 级联筛选</span>{isSelected && <button onClick={() => setLocalTableFilters(p => ({...p, [columnId]: ''}))} className="text-[10px] font-bold text-red-500 hover:underline">清除</button>}</div>
            <div className="max-h-64 overflow-y-auto p-1 custom-scrollbar">
              {options.length === 0 ? (<div className="px-3 py-4 text-center text-xs text-slate-400 italic font-medium">无匹配选项</div>) : (
                options.map((opt: string) => (<button key={opt} onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }} className={`w-full text-left px-3 py-2 rounded-lg text-xs transition-colors flex items-center justify-between ${localTableFilters[columnId] === opt ? 'bg-indigo-50 text-indigo-700 font-bold' : 'text-slate-700 hover:bg-slate-50'}`}><span className="truncate pr-2">{opt}</span>{localTableFilters[columnId] === opt && <svg className="w-3 h-3 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20"><path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" /></svg>}</button>))
              )}
            </div>
          </div>
        )}
      </th>
    );
  };

  return (
    <div className="space-y-10 pb-16">
      {/* 核心指标卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px] hover:shadow-md transition-shadow">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px] hover:shadow-md transition-shadow">
