import { GoogleGenAI } from "@google/genai";
import { SalesSummary } from "../types";

export const getAIInsights = async (summary: SalesSummary) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    作为一名资深商业分析师，请根据以下含单价维度的销售数据进行多维深度洞察，并提供3-5条极具参考价值的行动建议。
    注意：所有金额单位均为 CFA (西非法郎)。

    核心指标：
    - 全局销售总额: ${summary.totalSales.toLocaleString()} CFA
    - 总出库量: ${summary.totalQuantity.toLocaleString()}
    - 业务单数: ${summary.orderCount}
    - 系统计算平均单价: ${summary.totalQuantity > 0 ? Math.round(summary.totalSales / summary.totalQuantity).toLocaleString() : 0} CFA

    品类价格带分布 (总额与均价对比):
    ${summary.categoryDistribution.map(c => {
      const qty = summary.categoryQuantityDistribution.find(q => q.name === c.name)?.value || 0;
      const avg = qty > 0 ? Math.round(c.value / qty) : 0;
      return `- ${c.name}: 销售额 ${c.value.toLocaleString()} CFA, 平均单价 ${avg.toLocaleString()} CFA`;
    }).join('\n')}

    精英销售员梯队:
    ${summary.salespersonPerformance.slice(0, 3).map(s => `${s.name}: ${s.value.toLocaleString()} CFA`).join(', ')}

    请使用专业中文回答，重点关注以下维度：
    1. 【盈利能力分析】：识别哪些品类属于高溢价（均价高）产品，哪些属于引流款（跑量但均价低）。
    2. 【单价健康度】：分析当前平均单价是否处于行业合理区间，是否存在通过提升客单价来增长销售额的机会。
    3. 【风险预警】：若核心品类均价出现异常波动或销售员过于依赖低价策略，请指出。
    4. 【策略建议】：针对不同价格带的产品，建议采取何种差异化的促销或客户开发策略。
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini AI Error:", error);
    return "抱歉，AI 洞察引擎在解析价格模型时遇到障碍，请稍后再试。";
  }
};

