      </section>

      {/* 销售绩效排行榜 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-10">
          <div><h3 className="text-xl font-black text-slate-900 flex items-center gap-2">🏆 销售绩效排行榜</h3><p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1 font-mono">Performance Leaderboard</p></div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setPerfMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${perfMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500 hover:text-slate-800'}`}>按金额</button>
            <button onClick={() => setPerfMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${perfMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500 hover:text-slate-800'}`}>按数量</button>
          </div>
        </div>
        <div className="h-[450px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={sortedSalespersonPerf} layout="vertical" margin={{ left: 20, right: 140, top: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
