  const [perfMetric, setPerfMetric] = useState<'sales' | 'quantity'>('sales');

  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  const [localTableFilters, setLocalTableFilters] = useState({ 
    id: '', 
    date: '', 
    customer: '', 
    salesperson: '',
    itemName: '' 
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // 1. 趋势图数据计算 (固定 Y 轴逻辑)
  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set(filteredData.map(d => d.month))).sort();
    const metrics = !activeMetrics.amount && !activeMetrics.quantity ? { amount: true, quantity: false } : activeMetrics;

    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return {
          name: month,
          amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0),
          quantity: monthRecords.reduce((s, r) => s + r.quantity, 0)
        };
      });
      const series: any[] = [];
      if (metrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (metrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }

    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set(filteredData.map(d => d[dimKey] as string))).slice(0, 8);

    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (metrics.amount) series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor });
      if (metrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
    });

    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });

    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  // 2. 品类与物料数据计算
  const sortedCategorySummary = useMemo(() => {
    return summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    }).sort((a, b) => b.sales - a.sales);
  }, [summary]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const e = map.get(d.itemName) || { sales: 0, quantity: 0 };
      map.set(d.itemName, { sales: e.sales + d.totalAmount, quantity: e.quantity + d.quantity });
    });
    return Array.from(map.entries())
      .map(([name, v]) => ({ name, sales: v.sales, quantity: v.quantity }))
      .sort((a, b) => b.sales - a.sales);
  }, [filteredData]);

  const sortedSalespersonPerf = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const e = map.get(d.salesperson) || { sales: 0, quantity: 0 };
      map.set(d.salesperson, { sales: e.sales + d.totalAmount, quantity: e.quantity + d.quantity });
    });
    return Array.from(map.entries())
      .map(([name, v]) => ({ name, sales: v.sales, quantity: v.quantity }))
      .sort((a, b) => perfMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, perfMetric]);

  // 3. 下钻逻辑处理 (Drilldown)
  const drillDownData = useMemo(() => {
    const dim = selectedCategory ? 'category' : (selectedItem ? 'itemName' : null);
    const val = selectedCategory || selectedItem;
    if (!dim || !val) return null;

    const base = filteredData.filter(r => r[dim as keyof SalesRecord] === val);
    const records = base.filter(r => {
      return (!localTableFilters.customer || r.customer === localTableFilters.customer) &&
             (!localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson) &&
             (!localTableFilters.date || r.date === localTableFilters.date);
    });

    const customersMap = new Map<string, { sales: number; qty: number }>();
    base.forEach(r => {
      const e = customersMap.get(r.customer) || { sales: 0, qty: 0 };
      customersMap.set(r.customer, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });

    const customers = Array.from(customersMap.entries())
      .map(([name, v]) => ({ name, sales: v.sales, qty: v.qty }))
      .sort((a, b) => b.sales - a.sales);

    return { records, customers, total: records.reduce((s, r) => s + r.totalAmount, 0) };
  }, [selectedCategory, selectedItem, filteredData, localTableFilters]);

  const toggleMetric = (type: 'amount' | 'quantity') => {
    setActiveMetrics(prev => ({ ...prev, [type]: !prev[type] }));
  };

  const renderLabel = (props: any) => {
    const { cx, cy, midAngle, outerRadius, name, percent } = props;
    const RADIAN = Math.PI / 180;
    const x = cx + (outerRadius + 25) * Math.cos(-RADIAN * midAngle);
    const y = cy + (outerRadius + 25) * Math.sin(-RADIAN * midAngle);
    return (
      <text x={x} y={y} fill="#475569" textAnchor={x > cx ? 'start' : 'end'} dominantBaseline="central" className="text-[10px] font-black">
        {name} ({(percent * 100).toFixed(0)}%)
      </text>
    );
  };

  return (
    <div className="space-y-10 pb-16">
      {/* 核心指标卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl">💰</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl">📦</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl">📑</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">单据总数</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div>
        </div>
      </div>

      {/* 趋势分析模块 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex flex-col lg:flex-row items-center justify-between mb-8 gap-6">
          <div className="w-full lg:w-auto">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-2">📈 业绩增长趋势</h3>
            <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">Dual-Axis Adaptive Tracker</p>
          </div>
          <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200 shadow-inner">
            {['total', 'customer', 'salesperson'].map(m => (
              <button key={m} onClick={() => setTrendMode(m as any)} className={`px-5 py-2 rounded-xl text-xs font-black transition-all ${trendMode === m ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>
                {m === 'total' ? '合并统计' : m === 'customer' ? '客户对比' : '销售对比'}
              </button>
            ))}
          </div>
          <div className="flex gap-3">
            <button onClick={() => toggleMetric('amount')} className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black border-2 transition-all ${activeMetrics.amount ? 'bg-indigo-50 border-indigo-600 text-indigo-700' : 'bg-white border-slate-200 text-slate-400'}`}>
               金额 (CFA)
            </button>
            <button onClick={() => toggleMetric('quantity')} className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black border-2 transition-all ${activeMetrics.quantity ? 'bg-emerald-50 border-emerald-600 text-emerald-700' : 'bg-white border-slate-200 text-slate-400'}`}>
               数量
            </button>
          </div>
        </div>
        <div className="h-[450px] w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={trendAnalysis.data} margin={{ left: 10, right: 10, top: 10, bottom: 0 }}>
              <defs>
                {trendAnalysis.series.map((s, i) => (
                  <linearGradient key={s.key} id={`g-${i}`} x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor={s.color} stopOpacity={0.3}/><stop offset="95%" stopColor={s.color} stopOpacity={0}/>
                  </linearGradient>
                ))}
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11, fontWeight: 700}} />
              <YAxis yAxisId="amount" hide={!activeMetrics.amount} axisLine={false} tickLine={false} width={activeMetrics.amount ? 70 : 0} tick={{fill: '#6366f1', fontSize: 11, fontWeight: 800}} />
              <YAxis yAxisId="quantity" hide={!activeMetrics.quantity} orientation="right" axisLine={false} tickLine={false} width={activeMetrics.quantity ? 50 : 0} tick={{fill: '#10b981', fontSize: 11, fontWeight: 800}} />
              <Tooltip formatter={(v: any) => v.toLocaleString()} contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 30px rgba(0,0,0,0.1)'}} />
              <Legend wrapperStyle={{paddingTop: '20px', fontSize: '11px', fontWeight: 'bold'}} />
              {trendAnalysis.series.map((s, i) => (
                <Area key={s.key} yAxisId={s.type} type="monotone" dataKey={s.key} name={s.name} stroke={s.color} strokeWidth={3} strokeDasharray={s.dashed ? "5 5" : "0"} fill={`url(#g-${i})`} dot={false} animationDuration={800} />
              ))}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </section>

      {/* 模块：品类与物料 (并排展示) */}
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
        {/* 品类分布 */}
        <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
           <h3 className="text-lg font-black text-slate-900 mb-6">🧩 品类业务构成</h3>
           <div className="h-[350px]">
             <ResponsiveContainer width="100%" height="100%">
               <PieChart>
                 <Pie data={sortedCategorySummary} dataKey="sales" nameKey="name" cx="50%" cy="50%" innerRadius={70} outerRadius={100} label={renderLabel} labelLine={false} onClick={(d) => {setSelectedCategory(d.name); setSelectedItem(null);}}>
                   {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                 </Pie>
                 <Tooltip formatter={(v: any) => v.toLocaleString()} />
               </PieChart>
             </ResponsiveContainer>
           </div>
        </section>

        {/* 物料分布 */}
        <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
           <h3 className="text-lg font-black text-slate-900 mb-6">📦 物料业务构成</h3>
           <div className="h-[350px]">
             <ResponsiveContainer width="100%" height="100%">
               <PieChart>
                 <Pie data={sortedItemSummary.slice(0, 10)} dataKey="sales" nameKey="name" cx="50%" cy="50%" innerRadius={70} outerRadius={100} label={renderLabel} labelLine={false} onClick={(d) => {setSelectedItem(d.name); setSelectedCategory(null);}}>
                   {sortedItemSummary.slice(0, 10).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                 </Pie>
                 <Tooltip formatter={(v: any) => v.toLocaleString()} />
               </PieChart>
             </ResponsiveContainer>
           </div>
        </section>
      </div>

      {/* 模块：销售排行 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-8">
          <h3 className="text-lg font-black text-slate-900">🏆 销售绩效排行榜</h3>
          <div className="flex bg-slate-100 p-1 rounded-xl">
             <button onClick={() => setPerfMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold ${perfMetric === 'sales' ? 'bg-white shadow-sm text-indigo-700' : 'text-slate-500'}`}>按金额</button>
             <button onClick={() => setPerfMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold ${perfMetric === 'quantity' ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-500'}`}>按数量</button>
          </div>
        </div>
        <div className="h-[400px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={sortedSalespersonPerf} layout="vertical" margin={{left: 20, right: 60}}>
               <XAxis type="number" hide />
               <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={100} tick={{fontWeight: 800, fill: '#1e293b'}} />
               <Tooltip cursor={{fill: '#f8fafc'}} />
               <Bar dataKey={perfMetric === 'sales' ? 'sales' : 'quantity'} fill="#6366f1" radius={[0, 8, 8, 0]} barSize={24}>
                 {sortedSalespersonPerf.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                 <LabelList dataKey={perfMetric === 'sales' ? 'sales' : 'quantity'} position="right" formatter={(v: any) => v.toLocaleString()} style={{fontSize: '11px', fontWeight: 'bold'}} />
               </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </section>

      {/* 深度下钻分析面板 (Overlay) */}
      {drillDownData && (
        <div className="fixed inset-0 bg-white/95 backdrop-blur-xl z-[2000] p-10 flex flex-col overflow-hidden animate-in slide-in-from-bottom-12 duration-500">
           <div className="flex justify-between items-center mb-10 pb-6 border-b border-slate-200">
             <div>
               <p className="text-xs font-black text-indigo-600 uppercase tracking-widest mb-1">Deep Analysis Mode</p>
               <h3 className="text-3xl font-black text-slate-900">{selectedCategory || selectedItem}</h3>
             </div>
             <button onClick={() => {setSelectedCategory(null); setSelectedItem(null); setLocalTableFilters({id:'', date:'', customer:'', salesperson:'', itemName:''});}} className="px-8 py-3 bg-slate-900 text-white rounded-2xl font-black shadow-lg">退出分析</button>
           </div>

           <div className="flex-1 overflow-y-auto custom-scrollbar pr-4 space-y-8">
              {/* 客户贡献柱图 */}
              <div className="h-[250px] bg-slate-50 rounded-3xl p-6 border border-slate-100">
                <p className="text-xs font-black text-slate-500 uppercase mb-4">核心客户贡献分布</p>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={drillDownData.customers.slice(0, 10)}>
                    <XAxis dataKey="name" tick={{fontSize: 10, fontWeight: 800}} axisLine={false} tickLine={false} />
                    <Tooltip />
                    <Bar dataKey="sales" fill="#6366f1" radius={[10, 10, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>

              {/* 明细列表 */}
              <div className="bg-white rounded-3xl border border-slate-200 overflow-hidden">
                <table className="w-full text-sm border-separate border-spacing-0">
                  <thead className="bg-slate-50">
                    <tr>
                      <th className="px-6 py-4 text-left font-black text-slate-500 uppercase text-[10px]">单号</th>
                      <th className="px-6 py-4 text-left font-black text-slate-500 uppercase text-[10px]">日期</th>
                      <th className="px-6 py-4 text-left font-black text-slate-500 uppercase text-[10px]">客户</th>
                      <th className="px-6 py-4 text-right font-black text-slate-500 uppercase text-[10px]">单价</th>
                      <th className="px-6 py-4 text-right font-black text-slate-500 uppercase text-[10px]">数量</th>
                      <th className="px-6 py-4 text-right font-black text-slate-500 uppercase text-[10px]">金额</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {drillDownData.records.slice(0, 50).map((r, i) => (
                      <tr key={i} className="hover:bg-slate-50 transition-colors">
                        <td className="px-6 py-4 font-mono font-bold text-indigo-600">{r.id}</td>
                        <td className="px-6 py-4 text-slate-500">{r.date}</td>
                        <td className="px-6 py-4 font-bold text-slate-900">{r.customer}</td>
                        <td className="px-6 py-4 text-right font-mono">{r.unitPrice.toLocaleString()}</td>
                        <td className="px-6 py-4 text-right font-black">{r.quantity}</td>
                        <td className="px-6 py-4 text-right font-black text-slate-900">{r.totalAmount.toLocaleString()}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, LabelList, Legend
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [perfMetric, setPerfMetric] = useState<'sales' | 'quantity'>('sales'); 

  // 趋势图专项状态
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');
  const [activeMetrics, setActiveMetrics] = useState({
    amount: true,
    quantity: true
  });

  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  const [localTableFilters, setLocalTableFilters] = useState({ 
    id: '', 
    date: '', 
    customer: '', 
    salesperson: '',
    itemName: '' 
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // 1. 核心趋势图数据计算逻辑
  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set(filteredData.map(d => d.month))).sort();

    // 如果全没选，内部强制显示金额防止空图
    const metrics = !activeMetrics.amount && !activeMetrics.quantity ? { amount: true, quantity: false } : activeMetrics;

    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return {
          name: month,
          amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0),
          quantity: monthRecords.reduce((s, r) => s + r.quantity, 0)
        };
      });
      const series: any[] = [];
      if (metrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (metrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }

    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const entities = Array.from(new Set(filteredData.map(d => d[dimKey] as string))).slice(0, 8);

    const series: any[] = [];
    entities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (metrics.amount) {
        series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor });
      }
      if (metrics.quantity) {
        series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
      }
    });

    const data = months.map(month => {
      const row: any = { name: month };
      entities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });

    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  // 其他模块数据计算
  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, itemPieMetric]);

  const sortedSalespersonPerf = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.salesperson) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.salesperson, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => perfMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, perfMetric]);

  const toggleMetric = (type: 'amount' | 'quantity') => {
    setActiveMetrics(prev => ({ ...prev, [type]: !prev[type] }));
  };

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-RADIAN * midAngle);
    const cos = Math.cos(-RADIAN * midAngle);
    const sx = cx + (outerRadius + 5) * cos;
    const sy = cy + (outerRadius + 5) * sin;
    const mx = cx + (outerRadius + 30) * cos;
    const my = cy + (outerRadius + 30) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 22;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={2} opacity={0.6} />
        <circle cx={ex} cy={ey} r={3} fill={fill} />
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} textAnchor={textAnchor} fill="#0f172a" style={{ fontSize: '10px', fontWeight: 800 }}>{name}</text>
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} dy={12} textAnchor={textAnchor} fill="#475569" style={{ fontSize: '9px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  const drillDownData = useMemo(() => {
    const activeDimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : null);
    const activeValue = selectedCategory || selectedItem;
    const currentMetric = selectedCategory ? pieMetric : itemPieMetric;

    if (!activeDimension || !activeValue) return null;

    const baseRecords = filteredData.filter(r => r[activeDimension as keyof SalesRecord] === activeValue);

    const filteredRecords = baseRecords.filter(r => {
      const matchId = !localTableFilters.id || r.id === localTableFilters.id;
      const matchDate = !localTableFilters.date || r.date === localTableFilters.date;
      const matchCustomer = !localTableFilters.customer || r.customer === localTableFilters.customer;
      const matchSalesperson = !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
      const matchItemName = !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
      return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
    });

    const customersMap = new Map<string, { sales: number; qty: number }>();
    baseRecords.forEach(record => {
      const c = customersMap.get(record.customer) || { sales: 0, qty: 0 };
      customersMap.set(record.customer, { sales: c.sales + record.totalAmount, qty: c.qty + record.quantity });
    });

    const drillDownBaseTotal = baseRecords.reduce((s, r) => s + (currentMetric === 'sales' ? r.totalAmount : r.quantity), 0);
    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ 
        name, 
        sales: val.sales, 
        qty: val.qty, 
        percentage: drillDownBaseTotal > 0 ? (((currentMetric === 'sales' ? val.sales : val.qty) / drillDownBaseTotal) * 100).toFixed(1) + '%' : '0%' 
      }))
      .sort((a, b) => currentMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const trendMap = new Map<string, number>();
    filteredRecords.forEach(r => {
      const val = currentMetric === 'sales' ? r.totalAmount : r.quantity;
      trendMap.set(r.month, (trendMap.get(r.month) || 0) + val);
    });
    const trendData = Array.from(trendMap.entries())
      .map(([month, value]) => ({ month, value }))
      .sort((a, b) => a.month.localeCompare(b.month));

    const getOptionsFor = (key: keyof typeof localTableFilters) => {
      const tempFiltered = baseRecords.filter(r => {
        const matchId = key === 'id' || !localTableFilters.id || r.id === localTableFilters.id;
        const matchDate = key === 'date' || !localTableFilters.date || r.date === localTableFilters.date;
        const matchCustomer = key === 'customer' || !localTableFilters.customer || r.customer === localTableFilters.customer;
        const matchSalesperson = key === 'salesperson' || !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
        const matchItemName = key === 'itemName' || !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
        return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
      });
      return Array.from(new Set(tempFiltered.map(r => r[key === 'itemName' ? 'itemName' : key as keyof SalesRecord] as string))).sort();
    };

    return { 
      customers, 
      records: filteredRecords.sort((a, b) => b.date.localeCompare(a.date)), 
      drillDownTotal: filteredRecords.reduce((s, r) => s + (currentMetric === 'sales' ? r.totalAmount : r.quantity), 0),
      cascadingOptions: { id: getOptionsFor('id'), date: getOptionsFor('date').reverse(), customer: getOptionsFor('customer'), salesperson: getOptionsFor('salesperson'), itemName: getOptionsFor('itemName') },
      trendData,
      trendTitle: `${activeValue} 全市场趋势`
    };
  }, [selectedCategory, selectedItem, filteredData, pieMetric, itemPieMetric, localTableFilters]);

  const FilterHeader = ({ label, columnId }: { label: string, columnId: keyof typeof localTableFilters }) => {
    const options = (drillDownData?.cascadingOptions as any)?.[columnId] || [];
    const isSelected = !!localTableFilters[columnId];
    return (
      <th className="px-4 py-3 text-left relative group bg-slate-50 border-b border-slate-200">
        <div className="flex items-center gap-1.5">
          <span className="font-bold text-slate-600 uppercase tracking-widest text-[10px] whitespace-nowrap">{label}</span>
          <button onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)} className={`p-1 rounded-md transition-all ${isSelected ? 'text-indigo-600 bg-indigo-50 shadow-sm' : 'text-slate-400 hover:text-indigo-600'}`}>
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" /></svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-64 bg-white rounded-xl shadow-2xl border border-slate-200 z-[3000] overflow-hidden">
            <div className="p-2.5 border-b border-slate-100 bg-slate-50 flex justify-between items-center"><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{label} 筛选</span></div>
            <div className="max-h-64 overflow-y-auto p-1 custom-scrollbar">
              {options.map((opt: string) => (
                <button key={opt} onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }} className={`w-full text-left px-3 py-2 rounded-lg text-xs transition-colors ${localTableFilters[columnId] === opt ? 'bg-indigo-50 text-indigo-700 font-bold' : 'text-slate-700 hover:bg-slate-50'}`}>{opt}</button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  return (
    <div className="space-y-10 pb-16">
      {/* 核心指标卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col overflow-hidden">
           <div className="p-6 flex items-center justify-between bg-white border-b border-slate-100">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
                <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">业务单据</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div>
              </div>
              <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${isOrdersExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
           </div>
           {isOrdersExpanded && (
              <div className="px-5 py-5 bg-slate-50/50 border-t border-slate-100 space-y-4">
                <input type="text" placeholder="检索单号..." value={orderSearchTerm} onChange={(e) => setOrderSearchTerm(e.target.value)} className="w-full bg-white border border-slate-300 rounded-lg px-3 py-1.5 text-xs outline-none focus:border-indigo-500" />
                <div className="max-h-40 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar">
                  {summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase())).map(id => (<button key={id} onClick={() => onSelectOrderId(id)} className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-bold hover:border-indigo-500">{id}</button>))}
                </div>
              </div>
           )}
        </div>
      </div>

      {/* 业绩增长趋势模块 - 深度更新 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex flex-col lg:flex-row items-center justify-between mb-8 gap-6">
          <div className="w-full lg:w-auto">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-2">📈 业绩增长趋势</h3>
            <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">Dual-Axis Adaptive Tracker</p>
          </div>

          {/* 维度切换器 */}
          <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200 shadow-inner">
            <button onClick={() => setTrendMode('total')} className={`px-5 py-2 rounded-xl text-xs font-black transition-all ${trendMode === 'total' ? 'bg-white shadow-md text-slate-900' : 'text-slate-500 hover:text-slate-700'}`}>汇总统计</button>
            <button onClick={() => setTrendMode('customer')} className={`px-5 py-2 rounded-xl text-xs font-black transition-all ${trendMode === 'customer' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500 hover:text-slate-700'}`}>客户对比</button>
            <button onClick={() => setTrendMode('salesperson')} className={`px-5 py-2 rounded-xl text-xs font-black transition-all ${trendMode === 'salesperson' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500 hover:text-slate-700'}`}>销售对比</button>
          </div>

          {/* 指标显隐勾选 */}
          <div className="flex gap-3">
            <button 
              onClick={() => toggleMetric('amount')}
              className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black transition-all border-2 ${activeMetrics.amount ? 'bg-indigo-50 border-indigo-600 text-indigo-700 shadow-sm' : 'bg-white border-slate-200 text-slate-400 hover:border-indigo-200'}`}
            >
              <div className={`w-4 h-4 rounded-md border flex items-center justify-center transition-all ${activeMetrics.amount ? 'bg-indigo-600 border-indigo-600' : 'border-slate-300'}`}>
                {activeMetrics.amount && <svg className="w-3 h-3 text-white" fill="currentColor" viewBox="0 0 20 20"><path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"/></svg>}
              </div>
              金额 (CFA)
            </button>
            <button 
              onClick={() => toggleMetric('quantity')}
              className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black transition-all border-2 ${activeMetrics.quantity ? 'bg-emerald-50 border-emerald-600 text-emerald-700 shadow-sm' : 'bg-white border-slate-200 text-slate-400 hover:border-emerald-200'}`}
            >
              <div className={`w-4 h-4 rounded-md border flex items-center justify-center transition-all ${activeMetrics.quantity ? 'bg-emerald-600 border-emerald-600' : 'border-slate-300'}`}>
                {activeMetrics.quantity && <svg className="w-3 h-3 text-white" fill="currentColor" viewBox="0 0 20 20"><path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"/></svg>}
              </div>
              数量
            </button>
          </div>
        </div>

        <div className="h-[480px] w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={trendAnalysis.data} margin={{ left: 10, right: 10, top: 10, bottom: 0 }}>
              <defs>
                {trendAnalysis.series.map((s, i) => (
                  <linearGradient key={s.key} id={`grad-${i}`} x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor={s.color} stopOpacity={0.3}/>
                    <stop offset="95%" stopColor={s.color} stopOpacity={0}/>
                  </linearGradient>
                ))}
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11, fontWeight: 700}} dy={10} />

              {/* 金额轴 - 固定在左侧 */}
              <YAxis 
                yAxisId="amount" 
                orientation="left"
                axisLine={false} 
                tickLine={false} 
                hide={!activeMetrics.amount}
                width={activeMetrics.amount ? 70 : 0}
                tick={{fill: '#6366f1', fontSize: 11, fontWeight: 800}}
                tickFormatter={(v) => v >= 1000000 ? `${(v/1000000).toFixed(1)}M` : v.toLocaleString()}
              />

              {/* 数量轴 - 固定在右侧 */}
              <YAxis 
                yAxisId="quantity" 
                orientation="right"
                axisLine={false} 
                tickLine={false} 
                hide={!activeMetrics.quantity}
                width={activeMetrics.quantity ? 50 : 0}
                tick={{fill: '#10b981', fontSize: 11, fontWeight: 800}}
                tickFormatter={(v) => v.toLocaleString()}
              />

              <Tooltip 
                contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 25px 50px -12px rgb(0 0 0 / 0.25)', fontWeight: 800 }}
                formatter={(value: any, name: string) => [value.toLocaleString(), name]}
              />
              <Legend wrapperStyle={{ paddingTop: '30px', fontSize: '11px', fontWeight: 'bold' }} />

              {trendAnalysis.series.map((s, i) => (
                <Area
                  key={s.key}
                  yAxisId={s.type}
                  type="monotone"
                  dataKey={s.key}
                  name={s.name}
                  stroke={s.color}
                  strokeWidth={3}
                  strokeDasharray={s.dashed ? "5 5" : "0"}
                  fill={`url(#grad-${i})`}
                  activeDot={{ r: 6, strokeWidth: 0 }}
                  animationDuration={800}
                />
              ))}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </section>

      {/* 品类与物料业务构成 - 组合恢复 */}
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
        <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-lg font-black text-slate-900">🧩 品类业务构成</h3>
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button onClick={() => setPieMetric('sales')} className={`px-3 py-1 rounded-md text-[10px] font-bold ${pieMetric === 'sales' ? 'bg-white text-indigo-700' : 'text-slate-500'}`}>金额</button>
              <button onClick={() => setPieMetric('quantity')} className={`px-3 py-1 rounded-md text-[10px] font-bold ${pieMetric === 'quantity' ? 'bg-white text-emerald-700' : 'text-slate-500'}`}>数量</button>
            </div>
          </div>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={sortedCategorySummary} cx="50%" cy="50%" innerRadius={60} outerRadius={90} dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} onClick={(d) => setSelectedCategory(d.name)} label={renderCustomizedLabel} labelLine={false}>
                  {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </section>

        <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-lg font-black text-slate-900">📦 物料业务构成</h3>
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button onClick={() => setItemPieMetric('sales')} className={`px-3 py-1 rounded-md text-[10px] font-bold ${itemPieMetric === 'sales' ? 'bg-white text-indigo-700' : 'text-slate-500'}`}>金额</button>
              <button onClick={() => setItemPieMetric('quantity')} className={`px-3 py-1 rounded-md text-[10px] font-bold ${itemPieMetric === 'quantity' ? 'bg-white text-emerald-700' : 'text-slate-500'}`}>数量</button>
            </div>
          </div>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={sortedItemSummary.slice(0, 10)} cx="50%" cy="50%" innerRadius={60} outerRadius={90} dataKey={itemPieMetric === 'sales' ? 'sales' : 'quantity'} onClick={(d) => setSelectedItem(d.name)} label={renderCustomizedLabel} labelLine={false}>
                  {sortedItemSummary.slice(0, 10).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </section>
      </div>

      {/* 销售绩效排行榜 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-8">
          <h3 className="text-xl font-black text-slate-900">🏆 销售绩效排行榜</h3>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setPerfMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold ${perfMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>金额</button>
            <button onClick={() => setPerfMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold ${perfMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量</button>
          </div>
        </div>
        <div className="h-[400px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={sortedSalespersonPerf} layout="vertical" margin={{ left: 20, right: 120 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={100} tick={{fill: '#0f172a', fontWeight: 900}} />
              <Tooltip cursor={{fill: '#f1f5f9', opacity: 0.5}} />
              <Bar dataKey={perfMetric === 'sales' ? 'sales' : 'quantity'} fill="#6366f1" radius={[0, 10, 10, 0]} barSize={28}>
                 {sortedSalespersonPerf.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                 <LabelList dataKey={perfMetric === 'sales' ? 'sales' : 'quantity'} position="right" style={{fontSize: '11px', fontWeight: 'black'}} />
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </section>

      {/* 深度下钻分析面板 */}
      {(selectedCategory || selectedItem) && drillDownData && (
        <div className="fixed inset-0 bg-white/98 backdrop-blur-3xl z-[2000] p-10 flex flex-col animate-in slide-in-from-bottom-8 duration-500 overflow-hidden">
          <div className="flex items-center justify-between mb-8 pb-6 border-b border-slate-200">
            <div>
              <h4 className="text-xs font-black text-indigo-600 uppercase tracking-widest mb-1">Drilldown Analysis</h4>
              <h3 className="text-3xl font-black text-slate-900">{selectedCategory || selectedItem}</h3>
            </div>
            <button 
              onClick={() => { setSelectedCategory(null); setSelectedItem(null); setLocalTableFilters({ id: '', date: '', customer: '', salesperson: '', itemName: '' }); }} 
              className="px-8 py-3 bg-slate-900 text-white rounded-2xl font-black shadow-lg hover:bg-red-600 transition-colors"
            >
              退出分析
            </button>
          </div>

          <div className="flex-1 overflow-y-auto custom-scrollbar pr-4 space-y-8">
            {/* 客户分布 */}
            <div className="bg-slate-50 rounded-3xl p-8 border border-slate-100">
               <h5 className="text-[11px] font-black text-slate-800 uppercase tracking-widest mb-6">核心客户采购分布 (TOP 10)</h5>
               <div className="h-[220px]">
                 <ResponsiveContainer width="100%" height="100%">
                   <BarChart data={drillDownData.customers.slice(0, 10)}>
                     <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 800}} />
                     <Tooltip />
                     <Bar dataKey={(selectedCategory ? pieMetric : itemPieMetric) === 'sales' ? 'sales' : 'qty'} fill="#6366f1" radius={[8, 8, 0, 0]} barSize={40} />
                   </BarChart>
                 </ResponsiveContainer>
               </div>
            </div>

            {/* 明细表格 */}
            <div className="bg-white rounded-3xl border border-slate-200 overflow-hidden">
              <table className="min-w-full text-[12px] border-separate border-spacing-0">
                <thead className="bg-slate-50">
                  <tr>
                    <FilterHeader label="单号" columnId="id" />
                    <FilterHeader label="日期" columnId="date" />
                    <FilterHeader label="客户" columnId="customer" />
                    <FilterHeader label="销售" columnId="salesperson" />
                    <th className="px-4 py-3 text-right font-black text-slate-500 uppercase">数量</th>
                    <th className="px-4 py-3 text-right font-black text-slate-500 uppercase">金额</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {drillDownData.records.slice(0, 50).map((r, i) => (
                    <tr key={i} className="hover:bg-slate-50 transition-colors">
                      <td className="px-4 py-3 font-mono font-bold text-indigo-600">{r.id}</td>
                      <td className="px-4 py-3 text-slate-500">{r.date}</td>
                      <td className="px-4 py-3 font-bold text-slate-900">{r.customer}</td>
                      <td className="px-4 py-3 text-slate-600">{r.salesperson}</td>
                      <td className="px-4 py-3 text-right font-black">{r.quantity}</td>
                      <td className="px-4 py-3 text-right font-black text-slate-900">{r.totalAmount.toLocaleString()}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* 趋势扫描 */}
            <div className="bg-slate-900 rounded-3xl p-8 border border-slate-700">
               <h5 className="text-[11px] font-black text-amber-400 uppercase tracking-widest mb-6">历史波动趋势图</h5>
               <div className="h-[250px]">
                 <ResponsiveContainer width="100%" height="100%">
                   <AreaChart data={drillDownData.trendData}>
                     <defs>
                       <linearGradient id="drillGrad" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#fbbf24" stopOpacity={0.3}/><stop offset="95%" stopColor="#fbbf24" stopOpacity={0}/></linearGradient>
                     </defs>
                     <CartesianGrid strokeDasharray="3 3" stroke="#475569" vertical={false} />
                     <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fill: '#94a3b8'}} />
                     <Tooltip />
                     <Area type="monotone" dataKey="value" stroke="#fbbf24" fill="url(#drillGrad)" strokeWidth={4} />
                   </AreaChart>
                 </ResponsiveContainer>
               </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, LabelList, Legend
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [perfMetric, setPerfMetric] = useState<'sales' | 'quantity'>('sales'); 

  // 趋势图专项状态：多维视角切换与指标多选
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');
  const [activeMetrics, setActiveMetrics] = useState({
    amount: true,
    quantity: true
  });

  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  const [localTableFilters, setLocalTableFilters] = useState({ 
    id: '', 
    date: '', 
    customer: '', 
    salesperson: '',
    itemName: '' 
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // 1. 业绩增长趋势 - 深度逻辑更新
  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set(filteredData.map(d => d.month))).sort();
    const metrics = !activeMetrics.amount && !activeMetrics.quantity ? { amount: true, quantity: false } : activeMetrics;

    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return {
          name: month,
          amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0),
          quantity: monthRecords.reduce((s, r) => s + r.quantity, 0)
        };
      });
      const series: any[] = [];
      if (metrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (metrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }

    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const entities = Array.from(new Set(filteredData.map(d => d[dimKey] as string))).slice(0, 8);

    const series: any[] = [];
    entities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (metrics.amount) {
        series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor, dashed: false });
      }
      if (metrics.quantity) {
        series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
      }
    });

    const data = months.map(month => {
      const row: any = { name: month };
      entities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });

    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  // 品类/物料模块逻辑保持不变
  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, itemPieMetric]);

  const sortedSalespersonPerf = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.salesperson) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.salesperson, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => perfMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, perfMetric]);

  const toggleMetric = (type: 'amount' | 'quantity') => {
    setActiveMetrics(prev => ({ ...prev, [type]: !prev[type] }));
  };

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-RADIAN * midAngle);
    const cos = Math.cos(-RADIAN * midAngle);
    const sx = cx + (outerRadius + 5) * cos;
    const sy = cy + (outerRadius + 5) * sin;
    const mx = cx + (outerRadius + 30) * cos;
    const my = cy + (outerRadius + 30) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 22;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={2} opacity={0.6} />
        <circle cx={ex} cy={ey} r={3} fill={fill} />
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} textAnchor={textAnchor} fill="#0f172a" style={{ fontSize: '10px', fontWeight: 800 }}>{name}</text>
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} dy={12} textAnchor={textAnchor} fill="#475569" style={{ fontSize: '9px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  const drillDownData = useMemo(() => {
    const activeDimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : null);
    const activeValue = selectedCategory || selectedItem;
    const currentMetric = selectedCategory ? pieMetric : itemPieMetric;

    if (!activeDimension || !activeValue) return null;

    const baseRecords = filteredData.filter(r => r[activeDimension as keyof SalesRecord] === activeValue);

    const filteredRecords = baseRecords.filter(r => {
      const matchId = !localTableFilters.id || r.id === localTableFilters.id;
      const matchDate = !localTableFilters.date || r.date === localTableFilters.date;
      const matchCustomer = !localTableFilters.customer || r.customer === localTableFilters.customer;
      const matchSalesperson = !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
      const matchItemName = !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
      return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
    });

    const customersMap = new Map<string, { sales: number; qty: number }>();
    baseRecords.forEach(record => {
      const c = customersMap.get(record.customer) || { sales: 0, qty: 0 };
      customersMap.set(record.customer, { sales: c.sales + record.totalAmount, qty: c.qty + record.quantity });
    });

    const drillDownBaseTotal = baseRecords.reduce((s, r) => s + (currentMetric === 'sales' ? r.totalAmount : r.quantity), 0);
    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ 
        name, 
        sales: val.sales, 
        qty: val.qty, 
        percentage: drillDownBaseTotal > 0 ? (((currentMetric === 'sales' ? val.sales : val.qty) / drillDownBaseTotal) * 100).toFixed(1) + '%' : '0%' 
      }))
      .sort((a, b) => currentMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const trendMap = new Map<string, number>();
    filteredRecords.forEach(r => {
      const val = currentMetric === 'sales' ? r.totalAmount : r.quantity;
      trendMap.set(r.month, (trendMap.get(r.month) || 0) + val);
    });
    const trendData = Array.from(trendMap.entries())
      .map(([month, value]) => ({ month, value }))
      .sort((a, b) => a.month.localeCompare(b.month));

    const getOptionsFor = (key: keyof typeof localTableFilters) => {
      const tempFiltered = baseRecords.filter(r => {
        const matchId = key === 'id' || !localTableFilters.id || r.id === localTableFilters.id;
        const matchDate = key === 'date' || !localTableFilters.date || r.date === localTableFilters.date;
        const matchCustomer = key === 'customer' || !localTableFilters.customer || r.customer === localTableFilters.customer;
        const matchSalesperson = key === 'salesperson' || !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
        const matchItemName = key === 'itemName' || !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
        return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
      });
      return Array.from(new Set(tempFiltered.map(r => r[key === 'itemName' ? 'itemName' : key as keyof SalesRecord] as string))).sort();
    };

    return { 
      customers, 
      records: filteredRecords.sort((a, b) => b.date.localeCompare(a.date)), 
      drillDownTotal: filteredRecords.reduce((s, r) => s + (currentMetric === 'sales' ? r.totalAmount : r.quantity), 0),
      cascadingOptions: { id: getOptionsFor('id'), date: getOptionsFor('date').reverse(), customer: getOptionsFor('customer'), salesperson: getOptionsFor('salesperson'), itemName: getOptionsFor('itemName') },
      trendData,
      trendTitle: `${activeValue} 全市场趋势`
    };
  }, [selectedCategory, selectedItem, filteredData, pieMetric, itemPieMetric, localTableFilters]);

  const FilterHeader = ({ label, columnId }: { label: string, columnId: keyof typeof localTableFilters }) => {
    const options = (drillDownData?.cascadingOptions as any)?.[columnId] || [];
    const isSelected = !!localTableFilters[columnId];
    return (
      <th className="px-4 py-3 text-left relative group bg-slate-50 border-b border-slate-200">
        <div className="flex items-center gap-1.5">
          <span className="font-bold text-slate-600 uppercase tracking-widest text-[10px] whitespace-nowrap">{label}</span>
          <button onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)} className={`p-1 rounded-md transition-all ${isSelected ? 'text-indigo-600 bg-indigo-50 shadow-sm' : 'text-slate-400 hover:text-indigo-600'}`}>
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" /></svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-64 bg-white rounded-xl shadow-2xl border border-slate-200 z-[3000] overflow-hidden">
            <div className="p-2.5 border-b border-slate-100 bg-slate-50 flex justify-between items-center"><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{label} 筛选</span></div>
            <div className="max-h-64 overflow-y-auto p-1 custom-scrollbar">
              {options.map((opt: string) => (
                <button key={opt} onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }} className={`w-full text-left px-3 py-2 rounded-lg text-xs transition-colors ${localTableFilters[columnId] === opt ? 'bg-indigo-50 text-indigo-700 font-bold' : 'text-slate-700 hover:bg-slate-50'}`}>{opt}</button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  return (
    <div className="space-y-10 pb-16">
      {/* 核心指标卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col overflow-hidden">
           <div className="p-6 flex items-center justify-between bg-white border-b border-slate-100">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
                <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">业务单据</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div>
              </div>
              <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${isOrdersExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
           </div>
           {isOrdersExpanded && (
              <div className="px-5 py-5 bg-slate-50/50 border-t border-slate-100 space-y-4">
                <input type="text" placeholder="检索单号..." value={orderSearchTerm} onChange={(e) => setOrderSearchTerm(e.target.value)} className="w-full bg-white border border-slate-300 rounded-lg px-3 py-1.5 text-xs outline-none focus:border-indigo-500" />
                <div className="max-h-40 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar">
                  {summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase())).map(id => (<button key={id} onClick={() => onSelectOrderId(id)} className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-bold hover:border-indigo-500">{id}</button>))}
                </div>
              </div>
           )}
        </div>
      </div>

      {/* 业绩增长趋势模块 - 核心升级点 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex flex-col lg:flex-row items-center justify-between mb-8 gap-6">
          <div className="w-full lg:w-auto">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-2">📈 业绩增长趋势</h3>
            <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">Dual-Axis Adaptive Tracker</p>
          </div>

          <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200 shadow-inner">
            <button onClick={() => setTrendMode('total')} className={`px-5 py-2 rounded-xl text-xs font-black transition-all ${trendMode === 'total' ? 'bg-white shadow-md text-slate-900' : 'text-slate-500 hover:text-slate-700'}`}>汇总统计</button>
            <button onClick={() => setTrendMode('customer')} className={`px-5 py-2 rounded-xl text-xs font-black transition-all ${trendMode === 'customer' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500 hover:text-slate-700'}`}>客户对比</button>
            <button onClick={() => setTrendMode('salesperson')} className={`px-5 py-2 rounded-xl text-xs font-black transition-all ${trendMode === 'salesperson' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500 hover:text-slate-700'}`}>销售对比</button>
          </div>

          <div className="flex gap-3">
            <button onClick={() => toggleMetric('amount')} className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black transition-all border-2 ${activeMetrics.amount ? 'bg-indigo-50 border-indigo-600 text-indigo-700 shadow-sm' : 'bg-white border-slate-200 text-slate-400 hover:border-indigo-200'}`}>
              <div className={`w-4 h-4 rounded-md border flex items-center justify-center transition-all ${activeMetrics.amount ? 'bg-indigo-600 border-indigo-600' : 'border-slate-300'}`}>
                {activeMetrics.amount && <svg className="w-3 h-3 text-white" fill="currentColor" viewBox="0 0 20 20"><path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"/></svg>}
              </div>
              金额
            </button>
            <button onClick={() => toggleMetric('quantity')} className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black transition-all border-2 ${activeMetrics.quantity ? 'bg-emerald-50 border-emerald-600 text-emerald-700 shadow-sm' : 'bg-white border-slate-200 text-slate-400 hover:border-emerald-200'}`}>
              <div className={`w-4 h-4 rounded-md border flex items-center justify-center transition-all ${activeMetrics.quantity ? 'bg-emerald-600 border-emerald-600' : 'border-slate-300'}`}>
                {activeMetrics.quantity && <svg className="w-3 h-3 text-white" fill="currentColor" viewBox="0 0 20 20"><path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"/></svg>}
              </div>
              数量
            </button>
          </div>
        </div>

        <div className="h-[480px] w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={trendAnalysis.data} margin={{ left: 10, right: 10, top: 10, bottom: 0 }}>
              <defs>
                {trendAnalysis.series.map((s, i) => (
                  <linearGradient key={s.key} id={`trend-grad-${i}`} x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor={s.color} stopOpacity={0.3}/>
                    <stop offset="95%" stopColor={s.color} stopOpacity={0}/>
                  </linearGradient>
                ))}
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11, fontWeight: 700}} dy={10} />
              <YAxis yAxisId="amount" orientation="left" axisLine={false} tickLine={false} hide={!activeMetrics.amount} width={activeMetrics.amount ? 80 : 0} tick={{fill: '#6366f1', fontSize: 11, fontWeight: 800}} tickFormatter={(v) => v >= 1000000 ? `${(v/1000000).toFixed(1)}M` : v.toLocaleString()} />
              <YAxis yAxisId="quantity" orientation="right" axisLine={false} tickLine={false} hide={!activeMetrics.quantity} width={activeMetrics.quantity ? 60 : 0} tick={{fill: '#10b981', fontSize: 11, fontWeight: 800}} tickFormatter={(v) => v.toLocaleString()} />
              <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 25px 50px -12px rgb(0 0 0 / 0.25)', fontWeight: 800 }} formatter={(value: any) => value.toLocaleString()} />
              <Legend wrapperStyle={{ paddingTop: '30px', fontSize: '11px', fontWeight: 'bold' }} />
              {trendAnalysis.series.map((s, i) => (
                <Area key={s.key} yAxisId={s.type} type="monotone" dataKey={s.key} name={s.name} stroke={s.color} strokeWidth={3} strokeDasharray={s.dashed ? "5 5" : "0"} fill={`url(#trend-grad-${i})`} activeDot={{ r: 6, strokeWidth: 0 }} animationDuration={800} />
              ))}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </section>

      {/* 品类与物料业务构成 - 保持原始逻辑不变 */}
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
        <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-lg font-black text-slate-900">🧩 品类业务构成</h3>
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button onClick={() => setPieMetric('sales')} className={`px-3 py-1 rounded-md text-[10px] font-bold ${pieMetric === 'sales' ? 'bg-white text-indigo-700' : 'text-slate-500'}`}>金额</button>
              <button onClick={() => setPieMetric('quantity')} className={`px-3 py-1 rounded-md text-[10px] font-bold ${pieMetric === 'quantity' ? 'bg-white text-emerald-700' : 'text-slate-500'}`}>数量</button>
            </div>
          </div>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={sortedCategorySummary} cx="50%" cy="50%" innerRadius={60} outerRadius={90} dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} onClick={(d) => setSelectedCategory(d.name)} label={renderCustomizedLabel} labelLine={false}>
                  {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </section>

        <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-lg font-black text-slate-900">📦 物料业务构成</h3>
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button onClick={() => setItemPieMetric('sales')} className={`px-3 py-1 rounded-md text-[10px] font-bold ${itemPieMetric === 'sales' ? 'bg-white text-indigo-700' : 'text-slate-500'}`}>金额</button>
              <button onClick={() => setItemPieMetric('quantity')} className={`px-3 py-1 rounded-md text-[10px] font-bold ${itemPieMetric === 'quantity' ? 'bg-white text-emerald-700' : 'text-slate-500'}`}>数量</button>
            </div>
          </div>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={sortedItemSummary.slice(0, 10)} cx="50%" cy="50%" innerRadius={60} outerRadius={90} dataKey={itemPieMetric === 'sales' ? 'sales' : 'quantity'} onClick={(d) => setSelectedItem(d.name)} label={renderCustomizedLabel} labelLine={false}>
                  {sortedItemSummary.slice(0, 10).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </section>
      </div>

      {/* 销售绩效排行榜 - 保持原始逻辑不变 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-8">
          <h3 className="text-xl font-black text-slate-900">🏆 销售绩效排行榜</h3>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setPerfMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold ${perfMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>金额</button>
            <button onClick={() => setPerfMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold ${perfMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量</button>
          </div>
        </div>
        <div className="h-[400px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={sortedSalespersonPerf} layout="vertical" margin={{ left: 20, right: 120 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={100} tick={{fill: '#0f172a', fontWeight: 900}} />
              <Tooltip cursor={{fill: '#f1f5f9', opacity: 0.5}} />
              <Bar dataKey={perfMetric === 'sales' ? 'sales' : 'quantity'} fill="#6366f1" radius={[0, 10, 10, 0]} barSize={28}>
                 {sortedSalespersonPerf.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                 <LabelList dataKey={perfMetric === 'sales' ? 'sales' : 'quantity'} position="right" style={{fontSize: '11px', fontWeight: 'black'}} />
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </section>

      {/* 深度下钻分析面板 - 保持原始逻辑不变 */}
      {(selectedCategory || selectedItem) && drillDownData && (
        <div className="fixed inset-0 bg-white/98 backdrop-blur-3xl z-[2000] p-10 flex flex-col animate-in slide-in-from-bottom-8 duration-500 overflow-hidden">
          <div className="flex items-center justify-between mb-8 pb-6 border-b border-slate-200">
            <div>
              <h4 className="text-xs font-black text-indigo-600 uppercase tracking-widest mb-1">Drilldown Analysis</h4>
              <h3 className="text-3xl font-black text-slate-900">{selectedCategory || selectedItem}</h3>
            </div>
            <button onClick={() => { setSelectedCategory(null); setSelectedItem(null); setLocalTableFilters({ id: '', date: '', customer: '', salesperson: '', itemName: '' }); }} className="px-8 py-3 bg-slate-900 text-white rounded-2xl font-black shadow-lg hover:bg-red-600 transition-colors">退出分析</button>
          </div>
          <div className="flex-1 overflow-y-auto custom-scrollbar pr-4 space-y-8">
            <div className="bg-slate-50 rounded-3xl p-8 border border-slate-100">
               <h5 className="text-[11px] font-black text-slate-800 uppercase tracking-widest mb-6">核心客户采购分布 (TOP 10)</h5>
               <div className="h-[220px]">
                 <ResponsiveContainer width="100%" height="100%">
                   <BarChart data={drillDownData.customers.slice(0, 10)}>
                     <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 800}} />
                     <Tooltip />
                     <Bar dataKey={(selectedCategory ? pieMetric : itemPieMetric) === 'sales' ? 'sales' : 'qty'} fill="#6366f1" radius={[8, 8, 0, 0]} barSize={40} />
                   </BarChart>
                 </ResponsiveContainer>
               </div>
            </div>
            <div className="bg-white rounded-3xl border border-slate-200 overflow-hidden">
              <table className="min-w-full text-[12px] border-separate border-spacing-0">
                <thead className="bg-slate-50">
                  <tr>
                    <FilterHeader label="单号" columnId="id" />
                    <FilterHeader label="日期" columnId="date" />
                    <FilterHeader label="客户" columnId="customer" />
                    <FilterHeader label="销售" columnId="salesperson" />
                    <th className="px-4 py-3 text-right font-black text-slate-500 uppercase">数量</th>
                    <th className="px-4 py-3 text-right font-black text-slate-500 uppercase">金额</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {drillDownData.records.slice(0, 50).map((r, i) => (
                    <tr key={i} className="hover:bg-slate-50 transition-colors">
                      <td className="px-4 py-3 font-mono font-bold text-indigo-600">{r.id}</td>
                      <td className="px-4 py-3 text-slate-500">{r.date}</td>
                      <td className="px-4 py-3 font-bold text-slate-900">{r.customer}</td>
                      <td className="px-4 py-3 text-slate-600">{r.salesperson}</td>
                      <td className="px-4 py-3 text-right font-black">{r.quantity}</td>
                      <td className="px-4 py-3 text-right font-black text-slate-900">{r.totalAmount.toLocaleString()}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, LabelList, Legend
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [perfMetric, setPerfMetric] = useState<'sales' | 'quantity'>('sales'); 

  // 趋势图专项状态
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');
  const [activeMetrics, setActiveMetrics] = useState({
    amount: true,
    quantity: true
  });

  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  const [localTableFilters, setLocalTableFilters] = useState({ 
    id: '', 
    date: '', 
    customer: '', 
    salesperson: '',
    itemName: '' 
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // 1. 业绩增长趋势 - 核心逻辑升级
  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set(filteredData.map(d => d.month))).sort();
    const metrics = !activeMetrics.amount && !activeMetrics.quantity ? { amount: true, quantity: false } : activeMetrics;

    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return {
          name: month,
          amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0),
          quantity: monthRecords.reduce((s, r) => s + r.quantity, 0)
        };
      });
      const series: any[] = [];
      if (metrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (metrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }

    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set(filteredData.map(d => d[dimKey] as string))).slice(0, 8);

    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (metrics.amount) {
        series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor, dashed: false });
      }
      if (metrics.quantity) {
        series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
      }
    });

    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });

    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, itemPieMetric]);

  const sortedSalespersonPerf = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.salesperson) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.salesperson, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => perfMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, perfMetric]);

  const toggleMetric = (type: 'amount' | 'quantity') => {
    setActiveMetrics(prev => ({ ...prev, [type]: !prev[type] }));
  };

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-RADIAN * midAngle);
    const cos = Math.cos(-RADIAN * midAngle);
    const sx = cx + (outerRadius + 5) * cos;
    const sy = cy + (outerRadius + 5) * sin;
    const mx = cx + (outerRadius + 30) * cos;
    const my = cy + (outerRadius + 30) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 22;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={2} opacity={0.6} />
        <circle cx={ex} cy={ey} r={3} fill={fill} />
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} textAnchor={textAnchor} fill="#0f172a" style={{ fontSize: '12px', fontWeight: 800 }}>{name}</text>
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} dy={16} textAnchor={textAnchor} fill="#475569" style={{ fontSize: '11px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  const drillDownData = useMemo(() => {
    const activeDimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : null);
    const activeValue = selectedCategory || selectedItem;
    const currentMetric = selectedCategory ? pieMetric : itemPieMetric;

    if (!activeDimension || !activeValue) return null;

    const baseRecords = filteredData.filter(r => r[activeDimension as keyof SalesRecord] === activeValue);

    const filteredRecords = baseRecords.filter(r => {
      const matchId = !localTableFilters.id || r.id === localTableFilters.id;
      const matchDate = !localTableFilters.date || r.date === localTableFilters.date;
      const matchCustomer = !localTableFilters.customer || r.customer === localTableFilters.customer;
      const matchSalesperson = !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
      const matchItemName = !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
      return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
    });

    const customersMap = new Map<string, { sales: number; qty: number }>();
    baseRecords.forEach(record => {
      const c = customersMap.get(record.customer) || { sales: 0, qty: 0 };
      customersMap.set(record.customer, { sales: c.sales + record.totalAmount, qty: c.qty + record.quantity });
    });

    const drillDownBaseTotal = baseRecords.reduce((s, r) => s + (currentMetric === 'sales' ? r.totalAmount : r.quantity), 0);
    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ 
        name, 
        sales: val.sales, 
        qty: val.qty, 
        percentage: drillDownBaseTotal > 0 ? (((currentMetric === 'sales' ? val.sales : val.qty) / drillDownBaseTotal) * 100).toFixed(1) + '%' : '0%' 
      }))
      .sort((a, b) => currentMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const trendMap = new Map<string, number>();
    filteredRecords.forEach(r => {
      const val = currentMetric === 'sales' ? r.totalAmount : r.quantity;
      trendMap.set(r.month, (trendMap.get(r.month) || 0) + val);
    });
    const trendData = Array.from(trendMap.entries())
      .map(([month, value]) => ({ month, value }))
      .sort((a, b) => a.month.localeCompare(b.month));

    const getOptionsFor = (key: keyof typeof localTableFilters) => {
      const tempFiltered = baseRecords.filter(r => {
        const matchId = key === 'id' || !localTableFilters.id || r.id === localTableFilters.id;
        const matchDate = key === 'date' || !localTableFilters.date || r.date === localTableFilters.date;
        const matchCustomer = key === 'customer' || !localTableFilters.customer || r.customer === localTableFilters.customer;
        const matchSalesperson = key === 'salesperson' || !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
        const matchItemName = key === 'itemName' || !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
        return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName;
      });
      return Array.from(new Set(tempFiltered.map(r => r[key === 'itemName' ? 'itemName' : key as keyof SalesRecord] as string))).sort();
    };

    return { 
      customers, 
      records: filteredRecords.sort((a, b) => b.date.localeCompare(a.date)), 
      drillDownTotal: filteredRecords.reduce((s, r) => s + (currentMetric === 'sales' ? r.totalAmount : r.quantity), 0),
      cascadingOptions: { id: getOptionsFor('id'), date: getOptionsFor('date').reverse(), customer: getOptionsFor('customer'), salesperson: getOptionsFor('salesperson'), itemName: getOptionsFor('itemName') },
      trendData,
      trendTitle: `${activeValue} 全市场趋势`
    };
  }, [selectedCategory, selectedItem, filteredData, pieMetric, itemPieMetric, localTableFilters]);

  const FilterHeader = ({ label, columnId }: { label: string, columnId: keyof typeof localTableFilters }) => {
    const options = (drillDownData?.cascadingOptions as any)?.[columnId] || [];
    const isSelected = !!localTableFilters[columnId];
    return (
      <th className="px-4 py-3 text-left relative group bg-slate-50 border-b border-slate-200">
        <div className="flex items-center gap-1.5">
          <span className="font-bold text-slate-600 uppercase tracking-widest text-[10px] whitespace-nowrap">{label}</span>
          <button onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)} className={`p-1 rounded-md transition-all ${isSelected ? 'text-indigo-600 bg-indigo-50 shadow-sm' : 'text-slate-400 hover:text-indigo-600'}`}>
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" /></svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-64 bg-white rounded-xl shadow-2xl border border-slate-200 z-[3000] overflow-hidden">
            <div className="p-2.5 border-b border-slate-100 bg-slate-50 flex justify-between items-center"><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{label} 筛选</span></div>
            <div className="max-h-64 overflow-y-auto p-1 custom-scrollbar">
              {options.map((opt: string) => (
                <button key={opt} onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }} className={`w-full text-left px-3 py-2 rounded-lg text-xs transition-colors ${localTableFilters[columnId] === opt ? 'bg-indigo-50 text-indigo-700 font-bold' : 'text-slate-700 hover:bg-slate-50'}`}>{opt}</button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  return (
    <div className="space-y-10 pb-16">
      {/* 核心指标卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">物料出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col overflow-hidden">
           <div className="p-6 flex items-center justify-between bg-white border-b border-slate-100">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
                <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">业务单据总数</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div>
              </div>
              <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${isOrdersExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
           </div>
           {isOrdersExpanded && (
              <div className="px-5 py-5 bg-slate-50/50 border-t border-slate-100 space-y-4">
                <input type="text" placeholder="检索单号..." value={orderSearchTerm} onChange={(e) => setOrderSearchTerm(e.target.value)} className="w-full bg-white border border-slate-300 rounded-lg px-3 py-1.5 text-xs outline-none focus:border-indigo-500 font-bold" />
                <div className="max-h-40 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar pr-1">
                  {summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase())).map(id => (<button key={id} onClick={() => onSelectOrderId(id)} className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-bold hover:border-indigo-500 transition-colors">{id}</button>))}
                </div>
              </div>
           )}
        </div>
      </div>

      {/* 业绩增长趋势模块 - 深度更新 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex flex-col lg:flex-row items-center justify-between mb-8 gap-6">
          <div className="w-full lg:w-auto">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-2">📈 业绩增长趋势</h3>
            <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">Dual-Axis Adaptive Tracker</p>
          </div>

          <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200 shadow-inner">
