      {/* 物料模块 - 保持不变 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200 relative min-h-[600px] overflow-hidden">
        <div className="flex justify-between items-center mb-10">
          <div><h3 className="text-xl font-black text-slate-900 flex items-center gap-2">📦 物料业务构成</h3><p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1 font-mono">Deep Item Analysis</p></div>
