                <div><h4 className={`text-xs font-black ${selectedItem ? 'text-emerald-600' : 'text-indigo-600'} uppercase tracking-[0.3em] mb-1`}>Dynamic Drilldown Analysis</h4><h3 className="text-3xl font-black text-slate-900">{selectedCategory || selectedItem}</h3></div>
