import { SalesRecord } from '../types';
import * as XLSX from 'xlsx';

const SHEET_ID = '190CYOeWCVB68eCOszi7VwADf3N3jHwN7msmI1jmgzlg';
const GID = '1447308255';
const CSV_URL = `https://docs.google.com/spreadsheets/d/${SHEET_ID}/gviz/tq?tqx=out:csv&gid=${GID}`;

/**
 * 注意：请在此处填入您部署 Apps Script Web App 后获得的 URL。
 * 它可以接收 POST 请求并触发您的清洗脚本。
 */
const APPS_SCRIPT_WEB_APP_URL = 'https://script.google.com/macros/s/AKfycbwXXXXXXXXXXXXXXXXXXXXX/exec';

/**
 * 格式化日期字符串为标准的 YYYY-MM-DD
 */
const normalizeDate = (dateStr: string): string => {
  if (!dateStr) return '';
  try {
    const d = new Date(dateStr.replace(/\./g, '-').replace(/\//g, '-'));
    if (isNaN(d.getTime())) return dateStr.trim();

    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  } catch (e) {
    return dateStr.trim();
  }
};

/**
 * 解析 CSV 文本
 */
export const processCsvText = (csvText: string): SalesRecord[] => {
  const rows = csvText.split(/\r?\n/).filter(line => line.trim() !== '');
  const parsedRows = rows.map(line => {
    const result: string[] = [];
    let currentField = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') inQuotes = !inQuotes;
      else if (char === ',' && !inQuotes) {
        result.push(currentField.replace(/^"|"$/g, '').trim());
        currentField = '';
      } else currentField += char;
    }
    result.push(currentField.replace(/^"|"$/g, '').trim());
    return result;
  });

  const dataRows = parsedRows.slice(1);
  return dataRows.map((cols, index) => {
    const standardizedDate = normalizeDate(cols[2] || '');
    const month = standardizedDate ? standardizedDate.substring(0, 7) : (cols[1] || '');

    return {
      id: cols[0] || `ID-${index}`,
      month: month,
      date: standardizedDate,
      customer: cols[3] || '',
      salesperson: cols[4] || '',
      category: cols[5] || '',
      itemName: cols[6] || '',
      quantity: parseFloat(cols[7]) || 0,
      unitPrice: parseFloat(cols[8]) || 0,
      totalAmount: parseFloat(cols[9]) || 0
    };
  });
};

/**
 * 使用 SheetJS 解析 Excel 二进制流
 */
export const processExcelBuffer = (buffer: ArrayBuffer): SalesRecord[] => {
  const workbook = XLSX.read(buffer, { type: 'array' });
  const firstSheetName = workbook.SheetNames[0];
  const worksheet = workbook.Sheets[firstSheetName];
  const json = XLSX.utils.sheet_to_json(worksheet, { header: 1 }) as any[][];

  if (json.length < 2) throw new Error('文件中未检测到有效数据行');

  // 假设第一行为表头，从第二行开始处理
  return json.slice(1).map((row, index) => {
    const standardizedDate = normalizeDate(row[2] ? String(row[2]) : '');
    const month = standardizedDate ? standardizedDate.substring(0, 7) : (row[1] ? String(row[1]) : '');

    return {
      id: String(row[0] || `EX-${index}`),
      month: String(month),
      date: String(standardizedDate),
      customer: String(row[3] || ''),
      salesperson: String(row[4] || ''),
      category: String(row[5] || ''),
      itemName: String(row[6] || ''),
      quantity: parseFloat(row[7]) || 0,
      unitPrice: parseFloat(row[8]) || 0,
      totalAmount: parseFloat(row[9]) || 0
    };
  });
};

/**
 * 将解析后的数据同步到 Google Sheets 并触发后端清洗脚本
 */
export const syncToCloud = async (data: SalesRecord[]): Promise<void> => {
  if (APPS_SCRIPT_WEB_APP_URL.includes('XXXXXXXX')) {
    throw new Error('同步失败：尚未配置 Apps Script 部署 URL。请在 dataService.ts 中进行配置。');
  }

  try {
    // 使用 POST 发送 JSON 数据。
    // 注意：Google Apps Script 的 doPost 接口通常需要 no-cors 模式来规避浏览器重定向限制
    // 或者需要后端配置好跨域处理。为了触发稳定性，我们使用 text/plain 发送 JSON 字符串。
    const response = await fetch(APPS_SCRIPT_WEB_APP_URL, {
      method: 'POST',
      mode: 'no-cors', 
      headers: {
        'Content-Type': 'text/plain',
      },
      body: JSON.stringify(data),
    });

    // 由于是 no-cors，fetch 可能无法获得 response.ok。
    // 我们假设连接成功。如果脚本配置正确，清洗将自动开始。
    return;
  } catch (error) {
    console.error('Sync Error:', error);
    throw error;
  }
};

export const fetchSalesData = async (): Promise<SalesRecord[]> => {
  try {
    const response = await fetch(CSV_URL);
    if (!response.ok) {
        throw new Error('表格连接受阻。请检查公开分享设置或网络连接。');
    }
    const csvText = await response.text();
    if (csvText.includes('<!DOCTYPE html>')) {
        throw new Error('权限验证失败。请确保表格已设为“知道链接的任何人可查看”。');
    }
    return processCsvText(csvText);
  } catch (error) {
    console.error('Fetch Error:', error);
    throw error;
  }
};

import React, { useRef, useState } from 'react';
import { processCsvText, processExcelBuffer, syncToCloud } from '../services/dataService';
import { SalesRecord } from '../types';

interface FileSourceManagerProps {
  sourceType: 'cloud' | 'local';
  localFileName: string | null;
  localData: SalesRecord[];
  onSourceChange: (type: 'cloud' | 'local') => void;
  onFileUpload: (data: SalesRecord[], fileName: string) => void;
  onRefreshCloud: () => void;
}

const FileSourceManager: React.FC<FileSourceManagerProps> = ({ 
  sourceType, 
  localFileName, 
  localData,
  onSourceChange, 
  onFileUpload,
  onRefreshCloud 
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncDone, setSyncDone] = useState(false);
  const [syncError, setSyncError] = useState<string | null>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const name = file.name.toLowerCase();
    const isExcel = name.endsWith('.xlsx') || name.endsWith('.xls');
    const reader = new FileReader();

    reader.onload = (event) => {
      try {
        let data: SalesRecord[] = [];
        if (isExcel) {
          data = processExcelBuffer(event.target?.result as ArrayBuffer);
        } else {
          data = processCsvText(event.target?.result as string);
        }

        if (data.length === 0) throw new Error('文件中未检测到有效记录');
        onFileUpload(data, file.name);
        setSyncDone(false);
        setSyncError(null);
      } catch (err) {
        alert(`解析失败: ${err instanceof Error ? err.message : '未知错误'}`);
      }
    };

    if (isExcel) reader.readAsArrayBuffer(file);
    else reader.readAsText(file);
  };

  const handleSync = async () => {
    setIsSyncing(true);
    setSyncError(null);
    try {
      await syncToCloud(localData);
      setSyncDone(true);
      // 成功同步后，延迟几秒让用户看到成功状态，然后自动刷新云端并切换
      setTimeout(() => {
        setIsSyncing(false);
        onSourceChange('cloud');
        onRefreshCloud();
      }, 2500);
    } catch (err) {
      setSyncError(err instanceof Error ? err.message : '同步至云端失败');
      setTimeout(() => setIsSyncing(false), 3000);
    }
  };

  return (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 mb-8 relative overflow-hidden">
      {isSyncing && (
        <div className="absolute inset-0 z-50 bg-white/95 backdrop-blur-md flex flex-col items-center justify-center animate-in fade-in duration-300">
