import { SalesRecord } from '../types';
import * as XLSX from 'xlsx';

const SHEET_ID = '190CYOeWCVB68eCOszi7VwADf3N3jHwN7msmI1jmgzlg';
const GID = '1447308255';
const CSV_URL = `https://docs.google.com/spreadsheets/d/${SHEET_ID}/gviz/tq?tqx=out:csv&gid=${GID}`;

/**
 * 已更新为您提供的真实 Apps Script Web App URL
 */
const APPS_SCRIPT_WEB_APP_URL = 'https://script.google.com/macros/s/AKfycbxAjMNShi09cF-1lMUt0BDRckFWJTRBbXwmi7hbHPx8vtSu1q1AzGdh8ZCKGhiTc94l/exec';

/**
 * 格式化日期字符串为标准的 YYYY-MM-DD
 */
const normalizeDate = (dateStr: string): string => {
  if (!dateStr) return '';
  try {
    const d = new Date(dateStr.replace(/\./g, '-').replace(/\//g, '-'));
    if (isNaN(d.getTime())) return dateStr.trim();

    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  } catch (e) {
    return dateStr.trim();
  }
};

/**
 * 解析 CSV 文本
 */
export const processCsvText = (csvText: string): SalesRecord[] => {
  const rows = csvText.split(/\r?\n/).filter(line => line.trim() !== '');
  const parsedRows = rows.map(line => {
    const result: string[] = [];
    let currentField = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') inQuotes = !inQuotes;
      else if (char === ',' && !inQuotes) {
        result.push(currentField.replace(/^"|"$/g, '').trim());
        currentField = '';
      } else currentField += char;
    }
    result.push(currentField.replace(/^"|"$/g, '').trim());
    return result;
  });

  const dataRows = parsedRows.slice(1);
  return dataRows.map((cols, index) => {
    const standardizedDate = normalizeDate(cols[2] || '');
    const month = standardizedDate ? standardizedDate.substring(0, 7) : (cols[1] || '');

    return {
      id: cols[0] || `ID-${index}`,
      month: month,
      date: standardizedDate,
      customer: cols[3] || '',
      salesperson: cols[4] || '',
      category: cols[5] || '',
      itemName: cols[6] || '',
      quantity: parseFloat(cols[7]) || 0,
      unitPrice: parseFloat(cols[8]) || 0,
      totalAmount: parseFloat(cols[9]) || 0
    };
  });
};

/**
 * 使用 SheetJS 解析 Excel 二进制流
 */
export const processExcelBuffer = (buffer: ArrayBuffer): SalesRecord[] => {
  const workbook = XLSX.read(buffer, { type: 'array' });
  const firstSheetName = workbook.SheetNames[0];
  const worksheet = workbook.Sheets[firstSheetName];
  const json = XLSX.utils.sheet_to_json(worksheet, { header: 1 }) as any[][];

  if (json.length < 2) throw new Error('文件中未检测到有效数据行');

  // 假设第一行为表头，从第二行开始处理
  return json.slice(1).map((row, index) => {
    const standardizedDate = normalizeDate(row[2] ? String(row[2]) : '');
    const month = standardizedDate ? standardizedDate.substring(0, 7) : (row[1] ? String(row[1]) : '');

    return {
      id: String(row[0] || `EX-${index}`),
      month: String(month),
      date: String(standardizedDate),
      customer: String(row[3] || ''),
      salesperson: String(row[4] || ''),
      category: String(row[5] || ''),
      itemName: String(row[6] || ''),
      quantity: parseFloat(row[7]) || 0,
      unitPrice: parseFloat(row[8]) || 0,
      totalAmount: parseFloat(row[9]) || 0
    };
  });
};

/**
 * 将解析后的数据同步到 Google Sheets 并触发后端清洗脚本
 */
export const syncToCloud = async (data: SalesRecord[]): Promise<void> => {
  try {
    // 使用 POST 发送 JSON 数据。
    // 使用 no-cors 模式确保即便 GAS 返回重定向也能成功触发
    await fetch(APPS_SCRIPT_WEB_APP_URL, {
      method: 'POST',
      mode: 'no-cors', 
      headers: {
        'Content-Type': 'text/plain',
      },
      body: JSON.stringify(data),
    });
    return;
  } catch (error) {
    console.error('Sync Error:', error);
    throw error;
  }
};

export const fetchSalesData = async (): Promise<SalesRecord[]> => {
  try {
    const response = await fetch(CSV_URL);
    if (!response.ok) {
        throw new Error('表格连接受阻。请检查公开分享设置或网络连接。');
    }
    const csvText = await response.text();
    if (csvText.includes('<!DOCTYPE html>')) {
        throw new Error('权限验证失败。请确保表格已设为“知道链接的任何人可查看”。');
    }
    return processCsvText(csvText);
  } catch (error) {
    console.error('Fetch Error:', error);
    throw error;
  }
};

import React, { useState, useMemo, useEffect } from 'react';
