    if (csvText.includes('<!DOCTYPE html>') || csvText.includes('google-signin')) {
        throw new Error('权限错误：请在 Google 表格中确认已设为“知道链接的任何人可查看”。');
    }

    return processCsvText(csvText);
  } catch (error) {
    console.error('获取云端数据失败:', error);
    throw error;
  }
};

