export interface SalesRecord {
  id: string; // 出库单号
  month: string; // 月份
  date: string; // 业务日期
  customer: string; // 客户
  salesperson: string; // 销售员
  category: string; // 品类
  itemName: string; // 物料名称
  quantity: number; // 数量
  unitPrice: number; // 单价
  totalAmount: number; // 价税合计
}

export interface SalesSummary {
  totalSales: number;
  totalQuantity: number;
  orderCount: number;
  orderIds: string[]; // 具体的出库单号列表
  categoryDistribution: { name: string; value: number }[];
  categoryQuantityDistribution: { name: string; value: number }[];
  monthlyTrend: { name: string; sales: number; quantity: number }[];
}

export interface FilterState {
  months: string[];
  dateRange: [string, string];
  customers: string[];
  salespeople: string[];
  categories: string[];
  itemNames: string[];
}

import React, { useState, useMemo, useEffect } from 'react';
import { FilterState, SalesSummary, SalesRecord } from './types';
import Dashboard from './components/Dashboard';
import DataTable from './components/DataTable';
import MultiSelect from './components/MultiSelect';
import OrderDetailModal from './components/OrderDetailModal';
import { fetchSalesData } from './services/dataService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'table'>('dashboard');
  const [cloudData, setCloudData] = useState<SalesRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedOrderId, setSelectedOrderId] = useState<string | null>(null);

  const [filters, setFilters] = useState<FilterState>({
    months: [],
    dateRange: ['', ''],
    customers: [],
    salespeople: [],
    categories: [],
    itemNames: []
  });

  const loadCloudData = async () => {
    try {
      setIsLoading(true);
      setError(null);
      const data = await fetchSalesData();
      setCloudData(data);
      initializeFilters();
    } catch (err) {
      const message = err instanceof Error ? err.message : '连接数据源失败';
      setError(message);
    } finally {
      setIsLoading(false);
    }
  };

  const initializeFilters = () => {
    setFilters({
      months: [],
      dateRange: ['', ''],
      customers: [],
      salespeople: [],
      categories: [],
      itemNames: []
    });
  };

  useEffect(() => {
    loadCloudData();
  }, []);

  /**
   * 级联筛选核心逻辑：
   * 计算某个维度的备选项时，需要应用除该维度自身以外的所有其他筛选条件。
   */
  const getCascadingDimensionData = (dimension: keyof SalesRecord) => {
    const filteredByOthers = cloudData.filter(item => {
      const matchMonth = dimension === 'month' || filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = dimension === 'salesperson' || filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = dimension === 'category' || filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = dimension === 'customer' || filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = dimension === 'itemName' || filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (
        (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
        (!filters.dateRange[1] || item.date <= filters.dateRange[1])
      );
      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });

    const counts: Record<string, number> = {};
    filteredByOthers.forEach(item => {
      const val = item[dimension] as string;
      if (val) counts[val] = (counts[val] || 0) + 1;
    });

    // 选项列表：仅显示当前环境下有数据的选项，并按逻辑排序
    const options = Array.from(new Set(filteredByOthers.map(d => d[dimension] as string))).sort();
    if (dimension === 'month') options.reverse();

    // 如果某个已选中的值在当前级联结果中没有数据了，我们依然保留它在 options 中，以便用户取消选择
    const selectedButEmpty = filters[dimension === 'itemName' ? 'itemNames' : dimension === 'salesperson' ? 'salespeople' : (dimension + 's') as keyof FilterState] as string[];
    if (Array.isArray(selectedButEmpty)) {
      selectedButEmpty.forEach(val => {
        if (!options.includes(val)) options.push(val);
      });
    }

    return { options: options.sort(), counts };
  };

  const dynamicFilterData = useMemo(() => ({
    months: getCascadingDimensionData('month'),
    customers: getCascadingDimensionData('customer'),
    salespeople: getCascadingDimensionData('salesperson'),
    categories: getCascadingDimensionData('category'),
    itemNames: getCascadingDimensionData('itemName')
  }), [cloudData, filters]);

  const filteredData = useMemo(() => {
    return cloudData.filter(item => {
      const matchMonth = filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
                        (!filters.dateRange[1] || item.date <= filters.dateRange[1]);
      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });
  }, [cloudData, filters]);

  const summary: SalesSummary = useMemo(() => {
    const totalSales = filteredData.reduce((acc, cur) => acc + cur.totalAmount, 0);
    const totalQuantity = filteredData.reduce((acc, cur) => acc + cur.quantity, 0);
    const uniqueOrderIds = Array.from(new Set(filteredData.map(d => d.id))).sort();

    const monthlyMap = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const existing = monthlyMap.get(d.month) || { sales: 0, quantity: 0 };
      monthlyMap.set(d.month, {
        sales: existing.sales + d.totalAmount,
        quantity: existing.quantity + d.quantity
      });
    });
    const monthlyTrend = Array.from(monthlyMap.entries()).map(([name, val]) => ({ name, ...val })).sort((a, b) => a.name.localeCompare(b.name));

    const catMap = new Map<string, number>();
    const catQtyMap = new Map<string, number>();
    filteredData.forEach(d => {
      catMap.set(d.category, (catMap.get(d.category) || 0) + d.totalAmount);
      catQtyMap.set(d.category, (catQtyMap.get(d.category) || 0) + d.quantity);
    });

    return { 
      totalSales, 
      totalQuantity, 
      orderCount: uniqueOrderIds.length, 
      orderIds: uniqueOrderIds, 
      categoryDistribution: Array.from(catMap.entries()).map(([name, value]) => ({ name, value })),
      categoryQuantityDistribution: Array.from(catQtyMap.entries()).map(([name, value]) => ({ name, value })),
      monthlyTrend 
    };
  }, [filteredData]);

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 p-4">
        <div className="bg-white p-8 rounded-3xl shadow-xl max-w-md border border-red-100 text-center">
          <div className="text-5xl mb-4">⚠️</div>
          <h2 className="text-xl font-bold text-slate-900 mb-2">服务暂时不可用</h2>
          <p className="text-slate-500 text-sm mb-6">{error}</p>
          <button onClick={loadCloudData} className="w-full bg-indigo-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-indigo-700 transition-all">尝试重新连接</button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 pb-12">
      <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-[100]">
        <div className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-2xl font-black shadow-lg shadow-indigo-100">S</div>
            <h1 className="text-lg font-black text-slate-900">TTP 销售数据分析</h1>
          </div>
          <nav className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setActiveTab('dashboard')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'dashboard' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-900'}`}>分析中心</button>
            <button onClick={() => setActiveTab('table')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'table' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-900'}`}>数据清单</button>
          </nav>
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 pt-8">
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 mb-8">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-sm font-black text-slate-800 uppercase tracking-[0.2em] flex items-center gap-2">
              <span className="w-1.5 h-4 bg-indigo-600 rounded-full"></span> 筛选中心
            </h2>
            <div className="flex items-center gap-4 text-xs font-bold">
               <span className="text-slate-400">当前匹配: <span className="text-indigo-600 font-mono">{filteredData.length}</span> 行</span>
               <button onClick={initializeFilters} className="text-red-500 hover:underline">重置所有条件</button>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-6">
            <MultiSelect label="月份" options={dynamicFilterData.months.options} counts={dynamicFilterData.months.counts} selectedValues={filters.months} onChange={(v) => setFilters({...filters, months: v})} />
            <MultiSelect label="客户" options={dynamicFilterData.customers.options} counts={dynamicFilterData.customers.counts} selectedValues={filters.customers} onChange={(v) => setFilters({...filters, customers: v})} />
            <MultiSelect label="销售员" options={dynamicFilterData.salespeople.options} counts={dynamicFilterData.salespeople.counts} selectedValues={filters.salespeople} onChange={(v) => setFilters({...filters, salespeople: v})} />
            <MultiSelect label="品类" options={dynamicFilterData.categories.options} counts={dynamicFilterData.categories.counts} selectedValues={filters.categories} onChange={(v) => setFilters({...filters, categories: v})} />
            <MultiSelect label="物料名称" options={dynamicFilterData.itemNames.options} counts={dynamicFilterData.itemNames.counts} selectedValues={filters.itemNames} onChange={(v) => setFilters({...filters, itemNames: v})} />

            <div className="space-y-1.5">
              <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider">业务日期</label>
              <div className="flex items-center gap-1 bg-slate-50 border border-slate-200 rounded-lg px-2 py-1.5 hover:bg-white hover:border-indigo-300 transition-all focus-within:ring-2 focus-within:ring-indigo-100">
                <input 
                  type="date" 
                  value={filters.dateRange[0]} 
                  onChange={(e) => setFilters({...filters, dateRange: [e.target.value, filters.dateRange[1]]})}
                  className="bg-transparent text-[10px] font-bold text-slate-600 outline-none w-full cursor-pointer"
                />
                <span className="text-slate-300">-</span>
                <input 
                  type="date" 
                  value={filters.dateRange[1]} 
                  onChange={(e) => setFilters({...filters, dateRange: [filters.dateRange[0], e.target.value]})}
                  className="bg-transparent text-[10px] font-bold text-slate-600 outline-none w-full cursor-pointer"
                />
              </div>
            </div>
          </div>
        </section>

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-32 space-y-4">
            <div className="w-12 h-12 border-4 border-slate-200 border-t-indigo-600 rounded-full animate-spin"></div>
            <p className="text-slate-400 font-bold tracking-widest uppercase text-xs">正在刷新级联数据...</p>
          </div>
        ) : (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
            {filteredData.length > 0 ? (
              activeTab === 'dashboard' ? (
                <Dashboard summary={summary} filteredData={filteredData} onSelectOrderId={setSelectedOrderId} />
              ) : (
                <DataTable data={filteredData} onSelectOrderId={setSelectedOrderId} />
              )
            ) : (
              <div className="py-32 bg-white rounded-3xl border border-dashed border-slate-200 text-center">
                <div className="text-5xl mb-4">🔎</div>
                <h3 className="text-xl font-bold text-slate-800">未检索到数据</h3>
                <p className="text-slate-500 mt-2">级联筛选已自动排除了无结果组合，请尝试重置或调整条件</p>
                <button onClick={initializeFilters} className="mt-6 px-6 py-2 bg-indigo-600 text-white rounded-xl text-sm font-bold shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all">重置所有筛选</button>
              </div>
            )}
          </div>
        )}
      </main>

      {selectedOrderId && (
        <OrderDetailModal orderId={selectedOrderId} records={cloudData.filter(d => d.id === selectedOrderId)} onClose={() => setSelectedOrderId(null)} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');

  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');
  const [activeMetrics, setActiveMetrics] = useState({
    amount: true,
    quantity: true
  });

  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  const [localTableFilters, setLocalTableFilters] = useState({ 
    id: '', 
    date: '', 
    customer: '', 
    salesperson: '',
    itemName: '',
    month: '' 
  });
  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set(filteredData.map(d => d.month))).sort();
    const metrics = !activeMetrics.amount && !activeMetrics.quantity ? { amount: true, quantity: false } : activeMetrics;

    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return {
          name: month,
          amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0),
          quantity: monthRecords.reduce((s, r) => s + r.quantity, 0)
        };
      });
      const series: any[] = [];
      if (metrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (metrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }

    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set(filteredData.map(d => d[dimKey] as string))).slice(0, 8);

    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (metrics.amount) {
        series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor, dashed: false });
      }
      if (metrics.quantity) {
        series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
      }
    });

    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });

    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const categoryGrandTotal = useMemo(() => {
    return sortedCategorySummary.reduce((acc, curr) => acc + (pieMetric === 'sales' ? curr.sales : curr.quantity), 0);
  }, [sortedCategorySummary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, itemPieMetric]);

  const itemGrandTotal = useMemo(() => {
    return sortedItemSummary.reduce((acc, curr) => acc + (itemPieMetric === 'sales' ? curr.sales : curr.quantity), 0);
  }, [sortedItemSummary, itemPieMetric]);

  const toggleMetric = (type: 'amount' | 'quantity') => {
    setActiveMetrics(prev => ({ ...prev, [type]: !prev[type] }));
  };

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-RADIAN * midAngle);
    const cos = Math.cos(-RADIAN * midAngle);
    const sx = cx + (outerRadius + 5) * cos;
    const sy = cy + (outerRadius + 5) * sin;
    const mx = cx + (outerRadius + 30) * cos;
    const my = cy + (outerRadius + 30) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 22;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={2} opacity={0.6} />
        <circle cx={ex} cy={ey} r={3} fill={fill} />
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} textAnchor={textAnchor} fill="#0f172a" style={{ fontSize: '12px', fontWeight: 800 }}>{name}</text>
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} dy={16} textAnchor={textAnchor} fill="#475569" style={{ fontSize: '11px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  const drillDownData = useMemo(() => {
    const activeDimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : null);
    const activeValue = selectedCategory || selectedItem;
    const currentMetric = selectedCategory ? pieMetric : itemPieMetric;

    if (!activeDimension || !activeValue) return null;

    const baseRecords = filteredData.filter(r => r[activeDimension as keyof SalesRecord] === activeValue);

    const filteredRecords = baseRecords.filter(r => {
      const matchId = !localTableFilters.id || r.id === localTableFilters.id;
      const matchDate = !localTableFilters.date || r.date === localTableFilters.date;
      const matchCustomer = !localTableFilters.customer || r.customer === localTableFilters.customer;
      const matchSalesperson = !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
      const matchItemName = !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
      const matchMonth = !localTableFilters.month || r.month === localTableFilters.month;
      return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName && matchMonth;
    });

    const customersMap = new Map<string, { sales: number; qty: number }>();
    baseRecords.forEach(record => {
      const c = customersMap.get(record.customer) || { sales: 0, qty: 0 };
      customersMap.set(record.customer, { sales: c.sales + record.totalAmount, qty: c.qty + record.quantity });
    });

    const customers = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => currentMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const trendRecords = localTableFilters.customer 
      ? baseRecords.filter(r => r.customer === localTableFilters.customer)
      : baseRecords;

    const trendMap = new Map<string, { sales: number; qty: number }>();
    trendRecords.forEach(r => {
      const entry = trendMap.get(r.month) || { sales: 0, qty: 0 };
      entry.sales += r.totalAmount;
      entry.qty += r.quantity;
      trendMap.set(r.month, entry);
    });
    const monthlyTrend = Array.from(trendMap.entries())
      .map(([month, val]) => ({ month, sales: val.sales, qty: val.qty }))
      .sort((a, b) => a.month.localeCompare(b.month));

    const getOptionsFor = (key: keyof typeof localTableFilters) => {
      const tempFiltered = baseRecords.filter(r => {
        const matchId = key === 'id' || !localTableFilters.id || r.id === localTableFilters.id;
        const matchDate = key === 'date' || !localTableFilters.date || r.date === localTableFilters.date;
        const matchCustomer = key === 'customer' || !localTableFilters.customer || r.customer === localTableFilters.customer;
        const matchSalesperson = key === 'salesperson' || !localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson;
        const matchItemName = key === 'itemName' || !localTableFilters.itemName || r.itemName === localTableFilters.itemName;
        const matchMonth = key === 'month' || !localTableFilters.month || r.month === localTableFilters.month;
        return matchId && matchDate && matchCustomer && matchSalesperson && matchItemName && matchMonth;
      });
      return Array.from(new Set(tempFiltered.map(r => r[key === 'itemName' ? 'itemName' : key as keyof SalesRecord] as string))).sort();
    };

    return { 
      customers, 
      monthlyTrend,
      records: filteredRecords.sort((a, b) => b.date.localeCompare(a.date)), 
      cascadingOptions: { 
        id: getOptionsFor('id'), 
        date: getOptionsFor('date').reverse(), 
        customer: getOptionsFor('customer'), 
        salesperson: getOptionsFor('salesperson'), 
        itemName: getOptionsFor('itemName'),
        month: getOptionsFor('month').reverse()
      }
    };
  }, [selectedCategory, selectedItem, filteredData, pieMetric, itemPieMetric, localTableFilters]);

  const FilterHeader = ({ label, columnId, textAlign = "left" }: { label: string, columnId: keyof typeof localTableFilters, textAlign?: "left" | "right" }) => {
    const options = (drillDownData?.cascadingOptions as any)?.[columnId] || [];
    const isSelected = !!localTableFilters[columnId];
    return (
      <th className={`px-3 py-3 relative group bg-slate-50 border-b border-slate-200 text-${textAlign}`}>
        <div className={`flex items-center gap-1.5 ${textAlign === 'right' ? 'justify-end' : ''}`}>
          <span className="font-bold text-slate-600 uppercase tracking-widest text-[10px] whitespace-nowrap">{label}</span>
          <button onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)} className={`p-1 rounded-md transition-all ${isSelected ? 'text-indigo-600 bg-indigo-50 shadow-sm' : 'text-slate-400 hover:text-indigo-600'}`}>
            <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" /></svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-64 bg-white rounded-xl shadow-2xl border border-slate-200 z-[3000] overflow-hidden">
            <div className="p-2.5 border-b border-slate-100 bg-slate-50 flex justify-between items-center"><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{label} 筛选</span></div>
            <div className="max-h-64 overflow-y-auto p-1 custom-scrollbar">
              <button onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: '' })); setActiveFilterColumn(null); }} className="w-full text-left px-3 py-2 rounded-lg text-xs italic text-red-500 hover:bg-red-50">清除筛选</button>
              {options.map((opt: string) => (
                <button key={opt} onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }} className={`w-full text-left px-3 py-2 rounded-lg text-xs transition-colors ${localTableFilters[columnId] === opt ? 'bg-indigo-50 text-indigo-700 font-bold' : 'text-slate-700 hover:bg-slate-50'}`}>{opt}</button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  return (
    <div className="space-y-10 pb-16">
      {/* 核心指标卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">物料出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col overflow-hidden">
           <div className="p-6 flex items-center justify-between bg-white border-b border-slate-100">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
                <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">业务单据总数</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div>
              </div>
              <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${isOrdersExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
           </div>
           {isOrdersExpanded && (
              <div className="px-5 py-5 bg-slate-50/50 border-t border-slate-100 space-y-4">
                <input type="text" placeholder="检索单号..." value={orderSearchTerm} onChange={(e) => setOrderSearchTerm(e.target.value)} className="w-full bg-white border border-slate-300 rounded-lg px-3 py-1.5 text-xs outline-none focus:border-indigo-500 font-bold" />
                <div className="max-h-40 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar pr-1">
                  {summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase())).map(id => (<button key={id} onClick={() => onSelectOrderId(id)} className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-bold hover:border-indigo-500 transition-colors">{id}</button>))}
                </div>
              </div>
           )}
        </div>
      </div>

      {/* 业绩增长趋势 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex flex-col lg:flex-row items-center justify-between mb-8 gap-6">
          <div className="w-full lg:w-auto">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-2">📈 业绩增长趋势</h3>
            <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">Dual-Axis Adaptive Tracker</p>
          </div>

          <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200 shadow-inner">
            <button onClick={() => setTrendMode('total')} className={`px-5 py-2 rounded-xl text-xs font-black transition-all ${trendMode === 'total' ? 'bg-white shadow-md text-slate-900' : 'text-slate-500 hover:text-slate-700'}`}>汇总统计</button>
            <button onClick={() => setTrendMode('customer')} className={`px-5 py-2 rounded-xl text-xs font-black transition-all ${trendMode === 'customer' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500 hover:text-slate-700'}`}>客户对比</button>
            <button onClick={() => setTrendMode('salesperson')} className={`px-5 py-2 rounded-xl text-xs font-black transition-all ${trendMode === 'salesperson' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500 hover:text-slate-700'}`}>销售对比</button>
          </div>

          <div className="flex gap-3">
            <button onClick={() => toggleMetric('amount')} className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black transition-all border-2 ${activeMetrics.amount ? 'bg-indigo-50 border-indigo-600 text-indigo-700 shadow-sm' : 'bg-white border-slate-200 text-slate-400 hover:border-indigo-200'}`}>
              <div className={`w-4 h-4 rounded-md border flex items-center justify-center transition-all ${activeMetrics.amount ? 'bg-indigo-600 border-indigo-600' : 'border-slate-300'}`}>
                {activeMetrics.amount && <svg className="w-3 h-3 text-white" fill="currentColor" viewBox="0 0 20 20"><path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"/></svg>}
              </div>
              金额
            </button>
            <button onClick={() => toggleMetric('quantity')} className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black transition-all border-2 ${activeMetrics.quantity ? 'bg-emerald-50 border-emerald-600 text-emerald-700 shadow-sm' : 'bg-white border-slate-200 text-slate-400 hover:border-emerald-200'}`}>
              <div className={`w-4 h-4 rounded-md border flex items-center justify-center transition-all ${activeMetrics.quantity ? 'bg-emerald-600 border-emerald-600' : 'border-slate-300'}`}>
                {activeMetrics.quantity && <svg className="w-3 h-3 text-white" fill="currentColor" viewBox="0 0 20 20"><path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"/></svg>}
              </div>
              数量
            </button>
          </div>
        </div>

        <div className="h-[480px] w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={trendAnalysis.data} margin={{ left: 10, right: 10, top: 10, bottom: 0 }}>
              <defs>
                {trendAnalysis.series.map((s, i) => (
                  <linearGradient key={s.key} id={`grad-${i}`} x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor={s.color} stopOpacity={0.3}/>
                    <stop offset="95%" stopColor={s.color} stopOpacity={0}/>
                  </linearGradient>
                ))}
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11, fontWeight: 700}} dy={10} />
              <YAxis yAxisId="amount" orientation="left" axisLine={false} tickLine={false} hide={!activeMetrics.amount} width={activeMetrics.amount ? 80 : 0} tick={{fill: '#6366f1', fontSize: 11, fontWeight: 800}} tickFormatter={(v) => v >= 1000000 ? `${(v/1000000).toFixed(1)}M` : v.toLocaleString()} />
