/**
 * 鲁棒的日期标准化函数
 * 避免使用 new Date() 产生时区偏移（JS 的 new Date("YYYY-MM-DD") 会按 UTC 解析，导致本地时间减一天）
 */
const formatDateString = (dateStr: string): string => {
  if (!dateStr) return '';

  // 处理 Google Gviz 特有的 Date(2024,4,1) 格式
  if (dateStr.includes('Date(')) {
    const match = dateStr.match(/\d+/g);
    if (match && match.length >= 3) {
      const y = match[0];
      const m = (parseInt(match[1]) + 1).toString().padStart(2, '0');
      const d = match[2].padStart(2, '0');
      return `${y}-${m}-${d}`;
    }
  }

  // 处理标准字符串格式 YYYY/MM/DD 或 YYYY-MM-DD
  const clean = dateStr.replace(/^"|"$/g, '').trim();
  const parts = clean.split(/[/-]/);

  if (parts.length === 3) {
    let y = parts[0];
    let m = parts[1].padStart(2, '0');
    let d = parts[2].padStart(2, '0');

    // 如果年份在最后（某些区域设置）
    if (y.length < 4 && d.length === 4) {
      const temp = y;
      y = d;
      d = temp.padStart(2, '0');
    }

    // 确保年份是 4 位
    if (y.length === 2) y = '20' + y;

    // 检查是否为有效数值
    if (!isNaN(parseInt(y)) && !isNaN(parseInt(m)) && !isNaN(parseInt(d))) {
      return `${y}-${m}-${d}`;
    }
  }

  return clean;
};

