              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={sortedItemSummary.slice(0, 10)} cx="50%" cy="50%" innerRadius={110} outerRadius={160} paddingAngle={5} dataKey={itemPieMetric === 'sales' ? 'sales' : 'quantity'} onClick={(d) => { setSelectedItem(d.name); setSelectedCategory(null); }} stroke="#fff" strokeWidth={3} label={renderCustomizedLabel} labelLine={false}>
                    {sortedItemSummary.slice(0, 10).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} opacity={selectedItem && selectedItem !== sortedItemSummary[i].name ? 0.3 : 1} />)}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[500px] overflow-y-auto custom-scrollbar">
              {sortedItemSummary.map((item, idx) => (
                <button key={item.name} onClick={() => { setSelectedItem(item.name); setSelectedCategory(null); }} className={`flex items-center justify-between p-5 rounded-2xl border transition-all ${selectedItem === item.name ? 'bg-emerald-600 text-white' : 'bg-slate-50 text-slate-900 hover:border-emerald-400'}`}>
                  <span className="text-sm font-black truncate">{item.name}</span>
                  <span className="text-lg font-mono font-black">{(itemPieMetric === 'sales' ? item.sales : item.quantity).toLocaleString()}</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* 深度下钻分析面板 */}
        {(selectedCategory || selectedItem) && drillDownData && (
          <div className="absolute inset-0 bg-white/99 backdrop-blur-3xl z-[2000] p-10 flex flex-col animate-in slide-in-from-bottom-8 duration-500 overflow-hidden">
             <div className="flex items-center justify-between mb-8 pb-6 border-b border-slate-200 flex-shrink-0">
              <h3 className="text-3xl font-black text-slate-900">{selectedCategory || selectedItem} 深度分析</h3>
              <button onClick={() => { setSelectedCategory(null); setSelectedItem(null); setLocalTableFilters({ id: '', date: '', customer: '', salesperson: '', itemName: '', month: '' }); }} className="px-6 py-2 bg-slate-900 text-white rounded-xl text-sm font-bold">退出分析</button>
