                <div className="bg-slate-50 rounded-3xl p-6 border border-slate-200 h-[300px]">
                  <h5 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">月度业务趋势</h5>
                  <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={drillDownData.monthlyTrend}>
