      </section>

      {/* 物料业务构成 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200 relative min-h-[100px] overflow-hidden">
        <div className="flex justify-between items-center mb-10">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-2">📦 物料业务构成</h3>
          <div className="flex items-center gap-4">
            {isItemExpanded && (
              <div className="flex bg-slate-100 p-1 rounded-xl animate-in fade-in duration-300">
                <button onClick={() => setItemPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${itemPieMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>按金额</button>
                <button onClick={() => setItemPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${itemPieMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>按数量</button>
              </div>
            )}
            <button 
              onClick={() => setIsItemExpanded(!isItemExpanded)}
              className={`px-4 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-2 ${isItemExpanded ? 'bg-slate-100 text-slate-500 hover:bg-slate-200' : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-lg shadow-indigo-100'}`}
            >
              {isItemExpanded ? '收起物料分析' : '展开物料分析'}
              <svg className={`w-4 h-4 transition-transform duration-300 ${isItemExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
            </button>
          </div>
        </div>

        {isItemExpanded && (
          <div className="flex flex-col xl:flex-row items-center gap-16 animate-in fade-in slide-in-from-top-4 duration-500">
            <div className="relative w-full xl:w-[600px] h-[480px] flex-shrink-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={sortedItemSummary.slice(0, 10)} cx="50%" cy="50%" innerRadius={110} outerRadius={160} paddingAngle={5} dataKey={itemPieMetric === 'sales' ? 'sales' : 'quantity'} onClick={(d) => { setSelectedItem(d.name); setSelectedCategory(null); }} stroke="#fff" strokeWidth={3} label={renderCustomizedLabel} labelLine={false}>
                    {sortedItemSummary.slice(0, 10).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} opacity={selectedItem && selectedItem !== sortedItemSummary[i].name ? 0.3 : 1} />)}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[500px] overflow-y-auto custom-scrollbar">
              {sortedItemSummary.map((item, idx) => (
                <button key={item.name} onClick={() => { setSelectedItem(item.name); setSelectedCategory(null); }} className={`flex items-center justify-between p-5 rounded-2xl border transition-all ${selectedItem === item.name ? 'bg-emerald-600 text-white' : 'bg-slate-50 text-slate-900 hover:border-emerald-400'}`}>
                  <span className="text-sm font-black truncate">{item.name}</span>
                  <span className="text-lg font-mono font-black">{(itemPieMetric === 'sales' ? item.sales : item.quantity).toLocaleString()}</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* 深度下钻分析面板 */}
        {(selectedCategory || selectedItem) && drillDownData && (
          <div className="absolute inset-0 bg-white/99 backdrop-blur-3xl z-[2000] p-10 flex flex-col animate-in slide-in-from-bottom-8 duration-500 overflow-hidden">
             <div className="flex items-center justify-between mb-8 pb-6 border-b border-slate-200 flex-shrink-0">
              <h3 className="text-3xl font-black text-slate-900">{selectedCategory || selectedItem} 深度分析</h3>
              <button onClick={() => { setSelectedCategory(null); setSelectedItem(null); setLocalTableFilters({ id: '', date: '', customer: '', salesperson: '', itemName: '', month: '' }); }} className="px-6 py-2 bg-slate-900 text-white rounded-xl text-sm font-bold">退出分析</button>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar space-y-8 pr-2">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="bg-slate-50 rounded-3xl p-6 border border-slate-200 h-[300px]">
                  <h5 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">核心客户分布</h5>
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={drillDownData.customers.slice(0, 10)}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} />
                      <XAxis dataKey="name" tick={{fontSize: 10}} />
                      <Tooltip />
                      <Bar dataKey={(selectedCategory ? pieMetric : itemPieMetric) === 'sales' ? 'sales' : 'qty'} fill="#6366f1" radius={[4, 4, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
                <div className="bg-slate-50 rounded-3xl p-6 border border-slate-200 h-[300px]">
                  <h5 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">月度业务趋势</h5>
                  <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={drillDownData.monthlyTrend}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} />
                      <XAxis dataKey="month" tick={{fontSize: 10}} />
                      <Tooltip />
                      <Area type="monotone" dataKey={(selectedCategory ? pieMetric : itemPieMetric) === 'sales' ? 'sales' : 'qty'} stroke="#6366f1" fill="#6366f133" />
                    </AreaChart>
                  </ResponsiveContainer>
                </div>
              </div>

              <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden">
                <table className="min-w-full text-xs">
                  <thead className="bg-slate-50">
