                    {sortedItemSummary.slice(0, 10).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} opacity={selectedItem && selectedItem !== sortedItemSummary[i].name ? 0.3 : 1} />)}
