                  <div className="bg-slate-50 rounded-3xl p-8 border border-slate-200 h-[400px]">
                    <div className="flex items-center justify-between mb-6">
                       <h5 className="text-xs font-black text-slate-400 uppercase tracking-widest">核心客户分布 (Top 10)</h5>
                       {localTableFilters.customer && (
                         <button onClick={() => setLocalTableFilters(p => ({...p, customer: ''}))} className="text-[10px] font-black text-indigo-600 hover:underline">清除选中客户</button>
                       )}
                    </div>
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart 
                        data={drillDownData.customers.slice(0, 10)}
                        onClick={(data) => {
                          if (data && data.activePayload && data.activePayload[0]) {
                            const name = data.activePayload[0].payload.name;
                            setLocalTableFilters(p => ({ ...p, customer: p.customer === name ? '' : name }));
                          }
                        }}
                      >
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                        <XAxis dataKey="name" tick={{fontSize: 10, fill: '#64748b'}} axisLine={false} tickLine={false} />
                        <YAxis axisLine={false} tickLine={false} tickFormatter={(v) => (selectedCategory ? pieMetric : itemPieMetric) === 'sales' ? `${(v/1000000).toFixed(1)}M` : v} />
                        <Tooltip cursor={{fill: '#f1f5f9'}} formatter={(v: any) => [v.toLocaleString(), (selectedCategory ? pieMetric : itemPieMetric) === 'sales' ? '金额' : '数量']} />
                        <Bar dataKey={(selectedCategory ? pieMetric : itemPieMetric) === 'sales' ? 'sales' : 'qty'} radius={[8, 8, 0, 0]} cursor="pointer">
                          {drillDownData.customers.slice(0, 10).map((entry, idx) => (
                            <RechartsCell 
                              key={`cell-${idx}`} 
                              fill={COLORS[idx % COLORS.length]} 
                              fillOpacity={!localTableFilters.customer || localTableFilters.customer === entry.name ? 1 : 0.3}
                            />
                          ))}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>

                  <div className="bg-slate-50 rounded-3xl p-8 border border-slate-200 h-[400px]">
                    <h5 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6">
                      {localTableFilters.customer ? `${localTableFilters.customer} 的` : ''} 历史业务趋势 (按月)
                    </h5>
                    <ResponsiveContainer width="100%" height="100%">
                      <AreaChart data={drillDownData.monthlyTrend}>
                        <defs>
                          <linearGradient id="drillGrad" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="5%" stopColor="#10b981" stopOpacity={0.3}/>
                            <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                          </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                        <XAxis dataKey="month" tick={{fontSize: 10, fill: '#64748b'}} axisLine={false} tickLine={false} />
                        <YAxis axisLine={false} tickLine={false} tickFormatter={(v) => (selectedCategory ? pieMetric : itemPieMetric) === 'sales' ? `${(v/1000000).toFixed(1)}M` : v} />
                        <Tooltip formatter={(v: any) => [v.toLocaleString(), (selectedCategory ? pieMetric : itemPieMetric) === 'sales' ? '金额' : '数量']} />
                        <Area type="monotone" dataKey={(selectedCategory ? pieMetric : itemPieMetric) === 'sales' ? 'sales' : 'qty'} stroke="#10b981" strokeWidth={3} fill="url(#drillGrad)" />
                      </AreaChart>
                    </ResponsiveContainer>
                  </div>
                </div>

                <div className="bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-sm">
                  <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">关联单据明细</span>
                      {localTableFilters.customer && (
                        <span className="px-2 py-0.5 bg-indigo-100 text-indigo-700 text-[10px] font-black rounded uppercase">仅显示: {localTableFilters.customer}</span>
                      )}
                    </div>
                    <span className="text-xs font-bold text-slate-400">共 {drillDownData.records.length} 条记录</span>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="min-w-full text-xs">
                      <thead>
                        <tr>
                          <FilterHeader label="单号" columnId="id" />
                          <FilterHeader label="月份" columnId="month" />
                          <FilterHeader label="日期" columnId="date" />
                          <FilterHeader label="客户" columnId="customer" />
                          <FilterHeader label="销售员" columnId="salesperson" />
                          <FilterHeader label="物料名称" columnId="itemName" />
                          <th className="px-4 py-4 text-right bg-slate-50 border-b border-slate-200 font-bold text-slate-600 uppercase tracking-widest text-[10px]">单价</th>
                          <th className="px-4 py-4 text-right bg-slate-50 border-b border-slate-200 font-bold text-slate-600 uppercase tracking-widest text-[10px]">数量</th>
                          <th className="px-4 py-4 text-right bg-slate-50 border-b border-slate-200 font-bold text-slate-600 uppercase tracking-widest text-[10px]">价税合计</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {drillDownData.records.map((r, i) => (
                          <tr key={i} className="hover:bg-slate-50 transition-colors group">
                            <td className="px-4 py-4"><button onClick={() => onSelectOrderId(r.id)} className="text-indigo-600 font-black hover:underline">{r.id}</button></td>
                            <td className="px-4 py-4 text-slate-500 font-medium">{r.month}</td>
                            <td className="px-4 py-4 text-slate-500 font-medium">{r.date}</td>
                            <td className={`px-4 py-4 font-bold ${localTableFilters.customer === r.customer ? 'text-indigo-600' : 'text-slate-900'}`}>{r.customer}</td>
                            <td className="px-4 py-4 text-slate-600">{r.salesperson}</td>
                            <td className="px-4 py-4 text-slate-600">{r.itemName}</td>
                            <td className="px-4 py-4 text-right font-mono text-slate-500">{r.unitPrice.toLocaleString()}</td>
                            <td className="px-4 py-4 text-right font-black text-indigo-700">{r.quantity}</td>
                            <td className="px-4 py-4 text-right font-black text-slate-900">{r.totalAmount.toLocaleString()}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
