              {/* 核心内容滚动区域 - flex-1 与 min-h-0 是关键，确保内部 overflow-y-auto 生效 */}
              <div className="flex-1 min-h-0 overflow-y-auto custom-scrollbar space-y-10 pr-2 pb-10">
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                  {/* 分布图增加多彩填充与点击联动 */}
