                        </BarChart>
                      </ResponsiveContainer>
                    </div>
                  </div>

                  {/* 联动趋势图 */}
                  <div className="bg-slate-50 rounded-3xl p-8 border border-slate-200 h-[400px] flex flex-col">
                    <h5 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6">
                      {localTableFilters.customer ? `${localTableFilters.customer} 的` : ''} 历史业务趋势 (按月)
                    </h5>
                    <div className="flex-1 min-h-0">
                      <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={drillDownData.monthlyTrend}>
                          <defs>
                            <linearGradient id="drillGrad" x1="0" y1="0" x2="0" y2="1">
                              <stop offset="5%" stopColor="#10b981" stopOpacity={0.3}/>
                              <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                            </linearGradient>
                          </defs>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                          <XAxis dataKey="month" tick={{fontSize: 10, fill: '#64748b'}} axisLine={false} tickLine={false} />
                          <YAxis axisLine={false} tickLine={false} tickFormatter={(v) => (selectedCategory ? pieMetric : itemPieMetric) === 'sales' ? `${(v/1000000).toFixed(1)}M` : v} />
                          <Tooltip formatter={(v: any) => [v.toLocaleString(), (selectedCategory ? pieMetric : itemPieMetric) === 'sales' ? '金额' : '数量']} />
                          <Area type="monotone" dataKey={(selectedCategory ? pieMetric : itemPieMetric) === 'sales' ? 'sales' : 'qty'} stroke="#10b981" strokeWidth={3} fill="url(#drillGrad)" />
                        </AreaChart>
                      </ResponsiveContainer>
                    </div>
                  </div>
                </div>

                {/* 明细表格增加单价列与全字段筛选 */}
                <div className="bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-sm">
                  <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">关联单据明细</span>
                      {localTableFilters.customer && (
                        <span className="px-2 py-0.5 bg-indigo-100 text-indigo-700 text-[10px] font-black rounded uppercase">仅显示客户: {localTableFilters.customer}</span>
                      )}
                    </div>
                    <span className="text-xs font-bold text-slate-400">共 {drillDownData.records.length} 条记录</span>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="min-w-full text-xs">
