                   dataKey="value" 
                   onClick={(d) => { setSelectedCategory(d.name); setSelectedItem(null); }}
                 >
                    {summary.categoryDistribution.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} cursor="pointer" />)}
                 </Pie>
                 <Tooltip />
               </PieChart>
             </ResponsiveContainer>
           </div>
        </section>
        <section className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
           <h3 className="text-xl font-black text-slate-900 mb-8">📦 物料出库排名</h3>
           <div className="h-[350px]">
             <ResponsiveContainer width="100%" height="100%">
               <BarChart data={summary.categoryDistribution.slice(0, 8)} layout="vertical">
                 <XAxis type="number" hide />
                 <YAxis type="category" dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 11}} />
                 <Tooltip />
                 <Bar dataKey="value" fill="#6366f1" radius={[0, 4, 4, 0]} barSize={18} />
               </BarChart>
             </ResponsiveContainer>
           </div>
        </section>
      </div>

      {/* 深度下钻分析面板 (Drill Down) */}
      {(selectedCategory || selectedItem) && drillDownData && (
        <div className="fixed inset-0 bg-white z-[5000] flex flex-col animate-in slide-in-from-bottom-10 duration-500 overflow-hidden">
           <div className="max-w-[1600px] mx-auto w-full h-full flex flex-col p-8 min-h-0">
              {/* 头部 */}
              <div className="flex items-center justify-between mb-8 pb-6 border-b border-slate-100 flex-shrink-0">
                <div>
                  <h3 className="text-3xl font-black text-slate-900">{selectedCategory || selectedItem} 深度透视分析</h3>
                  <div className="flex items-center gap-2 mt-2">
                    <span className="px-2 py-0.5 bg-indigo-50 text-indigo-600 text-[10px] font-black rounded uppercase tracking-widest">下钻模式</span>
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest italic">点击客户柱子可联动趋势与明细</span>
                  </div>
                </div>
                <button 
                  onClick={() => { setSelectedCategory(null); setSelectedItem(null); setLocalTableFilters({id:'', date:'', customer:'', salesperson:'', itemName:'', month:''}); }} 
                  className="px-10 py-4 bg-slate-900 text-white rounded-2xl text-sm font-black hover:bg-slate-800 transition-all shadow-xl"
                >
                  退出深度分析
                </button>
              </div>

              {/* 核心联动区域 */}
