                      </ResponsiveContainer>
                    </div>
                  </div>
                </div>

                {/* 明细表格：同步过滤 */}
                <div className="bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-2xl">
                  <div className="p-5 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">关联单据明细</span>
                      {localTableFilters.customer && (
                        <span className="px-3 py-1 bg-indigo-600 text-white text-[10px] font-black rounded-lg shadow-xl animate-in fade-in zoom-in">仅显示客户: {localTableFilters.customer}</span>
                      )}
                    </div>
                    <span className="text-xs font-bold text-slate-400">查询结果: {drillDownData.records.length} 条</span>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="min-w-full text-xs">
                      <thead>
                        <tr>
                          <FilterHeader label="单号" columnId="id" />
                          <FilterHeader label="月份" columnId="month" />
                          <th className="px-3 py-4 text-left font-bold text-slate-600 text-[10px] uppercase tracking-widest">日期</th>
                          <FilterHeader label="客户" columnId="customer" />
                          <FilterHeader label="销售员" columnId="salesperson" />
                          <FilterHeader label="物料名称" columnId="itemName" />
                          <th className="px-4 py-4 text-right font-bold text-slate-600 text-[10px] uppercase tracking-widest">单价</th>
                          <th className="px-4 py-4 text-right font-bold text-slate-600 text-[10px] uppercase tracking-widest">数量</th>
                          <th className="px-4 py-4 text-right font-bold text-slate-600 text-[10px] uppercase tracking-widest">价税合计</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {drillDownData.records.map((r, i) => (
                          <tr key={i} className={`hover:bg-slate-50 transition-colors ${localTableFilters.customer === r.customer ? 'bg-indigo-50/40' : ''}`}>
                            <td className="px-3 py-4 font-mono font-bold text-indigo-600">
                              <button onClick={() => onSelectOrderId(r.id)} className="hover:underline">{r.id}</button>
                            </td>
                            <td className="px-3 py-4 text-slate-500">{r.month}</td>
                            <td className="px-3 py-4 text-slate-500">{r.date}</td>
                            <td className={`px-3 py-4 font-bold ${localTableFilters.customer === r.customer ? 'text-indigo-800' : 'text-slate-900'}`}>{r.customer}</td>
                            <td className="px-3 py-4 text-slate-600">{r.salesperson}</td>
                            <td className="px-3 py-4 text-slate-600">{r.itemName}</td>
                            <td className="px-4 py-4 text-right font-mono text-slate-400">{r.unitPrice.toLocaleString()}</td>
                            <td className="px-4 py-4 text-right font-black text-indigo-600">{r.quantity}</td>
                            <td className="px-4 py-4 text-right font-black text-slate-900">{r.totalAmount.toLocaleString()}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [customerMetric, setCustomerMetric] = useState<'sales' | 'quantity'>('sales');

  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');

  // 折叠状态管理
  const [isTrendExpanded, setIsTrendExpanded] = useState(true);
  const [isCategoryExpanded, setIsCategoryExpanded] = useState(true);
  const [isItemExpanded, setIsItemExpanded] = useState(true);
  const [isCustomerExpanded, setIsCustomerExpanded] = useState(true);

  const [activeMetrics, setActiveMetrics] = useState({
    amount: true,
    quantity: true
  });

  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  // 1. 状态隔离：深度分析面板的局部筛选状态
  const [localTableFilters, setLocalTableFilters] = useState({ 
    id: '', 
    customer: '', 
    salesperson: '',
    itemName: '',
    month: '' 
  });

  const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);
  const filterDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target as Node)) {
        setActiveFilterColumn(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // 2. 响应式计算链 (Reactive Computation Chain)
  const drillDownData = useMemo(() => {
    // 原始数据 -> 品类/物料过滤 (第一层过滤)
    const activeDimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : null);
    const activeValue = selectedCategory || selectedItem;
    const currentMetric = selectedCategory ? pieMetric : itemPieMetric;

    if (!activeDimension || !activeValue) return null;

    // 基础记录集：锁定当前分析的主维度
    const baseRecords = filteredData.filter(r => r[activeDimension as keyof SalesRecord] === activeValue);

    // 计算客户贡献分布 (展示给左侧柱状图，不随局部客户筛选变化，以便用户切换)
    const customersMap = new Map<string, { sales: number; qty: number }>();
    baseRecords.forEach(record => {
      const c = customersMap.get(record.customer) || { sales: 0, qty: 0 };
      customersMap.set(record.customer, { sales: c.sales + record.totalAmount, qty: c.qty + record.quantity });
    });
    const customersList = Array.from(customersMap.entries())
      .map(([name, val]) => ({ name, sales: val.sales, qty: val.qty }))
      .sort((a, b) => currentMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    // 客户联动过滤 (第二层过滤)
    // 趋势图逻辑：若选中客户，则展示该客户在该品类下的趋势；否则展示全量趋势
    const trendRecords = localTableFilters.customer 
      ? baseRecords.filter(r => r.customer === localTableFilters.customer) 
      : baseRecords;

    const trendMap = new Map<string, { sales: number; qty: number }>();
    trendRecords.forEach(r => {
      const entry = trendMap.get(r.month) || { sales: 0, qty: 0 };
      entry.sales += r.totalAmount;
      entry.qty += r.quantity;
      trendMap.set(r.month, entry);
    });
    const monthlyTrend = Array.from(trendMap.entries())
      .map(([month, val]) => ({ month, sales: val.sales, qty: val.qty }))
      .sort((a, b) => a.month.localeCompare(b.month));

    // 明细表逻辑：同步所有局部过滤器
    const filteredRecords = baseRecords.filter(r => {
      return (!localTableFilters.id || r.id === localTableFilters.id) &&
             (!localTableFilters.customer || r.customer === localTableFilters.customer) &&
             (!localTableFilters.salesperson || r.salesperson === localTableFilters.salesperson) &&
             (!localTableFilters.itemName || r.itemName === localTableFilters.itemName) &&
             (!localTableFilters.month || r.month === localTableFilters.month);
    });

    const getOptionsFor = (key: keyof typeof localTableFilters) => {
      return Array.from(new Set(baseRecords.map(r => r[key === 'itemName' ? 'itemName' : key as keyof SalesRecord] as string))).sort();
    };

    return { 
      customers: customersList, 
      monthlyTrend,
      records: filteredRecords.sort((a, b) => b.date.localeCompare(a.date)),
      cascadingOptions: { 
        id: getOptionsFor('id'), 
        customer: getOptionsFor('customer'), 
        salesperson: getOptionsFor('salesperson'), 
        itemName: getOptionsFor('itemName'),
        month: getOptionsFor('month').reverse()
      }
    };
  }, [selectedCategory, selectedItem, filteredData, pieMetric, itemPieMetric, localTableFilters]);

  // 3. 点击捕获稳定性：通过 BarChart 容器的 activeLabel 触发联动
  const handleCustomerChartClick = (state: any) => {
    if (state && state.activeLabel) {
      const clickedName = state.activeLabel;
      setLocalTableFilters(prev => ({
        ...prev,
        customer: prev.customer === clickedName ? '' : clickedName
      }));
    }
  };

  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set(filteredData.map(d => d.month))).sort();
    const metrics = !activeMetrics.amount && !activeMetrics.quantity ? { amount: true, quantity: false } : activeMetrics;

    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return {
          name: month,
          amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0),
          quantity: monthRecords.reduce((s, r) => s + r.quantity, 0)
        };
      });
      const series: any[] = [];
      if (metrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (metrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }

    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set(filteredData.map(d => d[dimKey] as string))).slice(0, 8);

    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (metrics.amount) series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor });
      if (metrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
    });

    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });

    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  const customerAnalysisData = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.customer) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.customer, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => customerMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, customerMetric]);

  const toggleMetric = (type: 'amount' | 'quantity') => {
    setActiveMetrics(prev => ({ ...prev, [type]: !prev[type] }));
  };

  const FilterHeader = ({ label, columnId }: { label: string, columnId: keyof typeof localTableFilters }) => {
    const options = (drillDownData?.cascadingOptions as any)?.[columnId] || [];
    const isSelected = !!localTableFilters[columnId];
    return (
      <th className="px-3 py-3 relative bg-slate-50 border-b border-slate-200 text-left">
        <div className="flex items-center gap-1.5">
          <span className="font-bold text-slate-600 uppercase tracking-widest text-[10px] whitespace-nowrap">{label}</span>
          <button onClick={() => setActiveFilterColumn(activeFilterColumn === columnId ? null : columnId)} className={`p-1 rounded-md transition-all ${isSelected ? 'text-indigo-600 bg-indigo-50' : 'text-slate-400 hover:text-indigo-600'}`}>
            <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M3 3a1 1 0 011-1h12a1 1 0 011 1v3a1 1 0 01-.293.707L12 11.414V15a1 1 0 01-.293.707l-2 2A1 1 0 018 17v-5.586L3.293 6.707A1 1 0 013 6V3z" /></svg>
          </button>
        </div>
        {activeFilterColumn === columnId && (
          <div ref={filterDropdownRef} className="absolute left-0 top-full mt-1 w-64 bg-white rounded-xl shadow-2xl border border-slate-200 z-[5000] overflow-hidden">
            <div className="max-h-64 overflow-y-auto p-1 custom-scrollbar">
              <button onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: '' })); setActiveFilterColumn(null); }} className="w-full text-left px-3 py-2 rounded-lg text-xs italic text-red-500 hover:bg-red-50">清除筛选</button>
              {options.map((opt: string) => (
                <button key={opt} onClick={() => { setLocalTableFilters(p => ({ ...p, [columnId]: opt })); setActiveFilterColumn(null); }} className={`w-full text-left px-3 py-2 rounded-lg text-xs transition-colors ${localTableFilters[columnId] === opt ? 'bg-indigo-50 text-indigo-700 font-bold' : 'text-slate-700 hover:bg-slate-50'}`}>{opt}</button>
              ))}
            </div>
          </div>
        )}
      </th>
    );
  };

  return (
    <div className="space-y-10 pb-16 relative">
      {/* 顶部指标卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl">💰</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl">📦</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest">出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl">📑</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest">单据总数</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div>
        </div>
      </div>

      {/* 趋势图 */}
      <section className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
        <div className="flex items-center justify-between mb-8">
          <h3 className="text-xl font-black text-slate-900">📈 业绩增长趋势</h3>
          <div className="flex bg-slate-100 p-1 rounded-xl">
             <button onClick={() => setTrendMode('total')} className={`px-4 py-1.5 rounded-lg text-xs font-bold ${trendMode === 'total' ? 'bg-white shadow-sm' : ''}`}>汇总</button>
             <button onClick={() => setTrendMode('customer')} className={`px-4 py-1.5 rounded-lg text-xs font-bold ${trendMode === 'customer' ? 'bg-white shadow-sm' : ''}`}>按客户</button>
          </div>
        </div>
        <div className="h-[400px]">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={trendAnalysis.data}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 11}} />
              <YAxis yAxisId="amount" axisLine={false} tickLine={false} tickFormatter={(v) => `${(v/1000000).toFixed(1)}M`} />
              <Tooltip />
              <Legend />
              {trendAnalysis.series.map((s: any) => (
                <Area key={s.key} yAxisId={s.type} dataKey={s.key} name={s.name} stroke={s.color} fill={s.color} fillOpacity={0.05} strokeWidth={2.5} />
              ))}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </section>

      {/* 品类分布 */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
        <section className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
           <h3 className="text-xl font-black text-slate-900 mb-8">🧩 品类业务构成</h3>
           <div className="h-[350px]">
             <ResponsiveContainer width="100%" height="100%">
               <PieChart>
                 <Pie 
                    data={summary.categoryDistribution} 
                    cx="50%" cy="50%" innerRadius={80} outerRadius={120} 
                    dataKey="value" 
                    onClick={(d) => { setSelectedCategory(d.name); setSelectedItem(null); }}
                  >
                    {summary.categoryDistribution.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} cursor="pointer" />)}
                 </Pie>
                 <Tooltip />
               </PieChart>
             </ResponsiveContainer>
           </div>
        </section>
        <section className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
           <h3 className="text-xl font-black text-slate-900 mb-8">📦 核心物料贡献</h3>
           <div className="h-[350px]">
             <ResponsiveContainer width="100%" height="100%">
               <BarChart data={summary.categoryDistribution.slice(0, 8)} layout="vertical">
                 <XAxis type="number" hide />
                 <YAxis type="category" dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 11}} />
                 <Tooltip />
                 <Bar dataKey="value" fill="#6366f1" radius={[0, 4, 4, 0]} barSize={20} />
               </BarChart>
             </ResponsiveContainer>
           </div>
        </section>
      </div>

      {/* 全屏深度下钻分析面板 (Drill Down) */}
      {(selectedCategory || selectedItem) && drillDownData && (
        <div className="fixed inset-0 bg-white z-[4000] flex flex-col animate-in slide-in-from-bottom-10 duration-500 overflow-hidden">
           <div className="max-w-[1600px] mx-auto w-full h-full flex flex-col p-10 min-h-0">
              <div className="flex items-center justify-between mb-8 pb-6 border-b border-slate-100 flex-shrink-0">
                <div>
                  <h3 className="text-3xl font-black text-slate-900">{selectedCategory || selectedItem} 深度下钻分析</h3>
                  <p className="text-[10px] font-bold text-slate-400 mt-2 uppercase tracking-widest italic flex items-center gap-2">
                    <span className="w-1.5 h-1.5 rounded-full bg-indigo-600 animate-pulse"></span>
                    下钻模式 · 点击客户分布柱图实现交叉联动
                  </p>
                </div>
                <div className="flex gap-4">
                  {localTableFilters.customer && (
                    <button onClick={() => setLocalTableFilters(p => ({ ...p, customer: '' }))} className="px-6 py-4 border-2 border-slate-200 rounded-2xl text-xs font-black hover:bg-slate-50">重置客户筛选</button>
                  )}
                  <button onClick={() => { setSelectedCategory(null); setSelectedItem(null); setLocalTableFilters({ id: '', customer: '', salesperson: '', itemName: '', month: '' }); }} className="px-10 py-4 bg-slate-900 text-white rounded-2xl text-sm font-black hover:bg-slate-800 shadow-2xl transition-all">退出分析</button>
                </div>
              </div>

              <div className="flex-1 min-h-0 overflow-y-auto custom-scrollbar pr-2 pb-12 space-y-12">
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                  {/* 分布图：交叉联动触发源 */}
                  <div className="bg-slate-50/50 rounded-3xl p-8 border border-slate-200 h-[450px] flex flex-col">
                    <div className="flex items-center justify-between mb-6">
                       <h5 className="text-xs font-black text-slate-400 uppercase tracking-widest">核心客户分布 (Top 10)</h5>
                       <div className="flex bg-slate-200/50 p-1 rounded-lg">
                          <button onClick={() => (selectedCategory ? setPieMetric('sales') : setItemPieMetric('sales'))} className={`px-3 py-1 rounded-md text-[10px] font-bold ${(selectedCategory ? pieMetric : itemPieMetric) === 'sales' ? 'bg-white shadow-sm' : ''}`}>金额</button>
                          <button onClick={() => (selectedCategory ? setPieMetric('quantity') : setItemPieMetric('quantity'))} className={`px-3 py-1 rounded-md text-[10px] font-bold ${(selectedCategory ? pieMetric : itemPieMetric) === 'quantity' ? 'bg-white shadow-sm' : ''}`}>数量</button>
                       </div>
                    </div>
                    <div className="flex-1 min-h-0">
                      <ResponsiveContainer width="100%" height="100%">
                        <BarChart 
                          data={drillDownData.customers.slice(0, 10)}
                          onClick={handleCustomerChartClick}
                        >
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                          <XAxis dataKey="name" tick={{fontSize: 10, fill: '#64748b'}} axisLine={false} tickLine={false} />
                          <YAxis axisLine={false} tickLine={false} tickFormatter={(v) => `${(v/1000000).toFixed(1)}M`} />
                          <Tooltip cursor={{fill: '#f1f5f9'}} />
                          <Bar 
                            dataKey={(selectedCategory ? pieMetric : itemPieMetric) === 'sales' ? 'sales' : 'qty'} 
                            radius={[8, 8, 0, 0]} 
                            cursor="pointer"
                          >
                            {drillDownData.customers.slice(0, 10).map((entry, idx) => (
                              <RechartsCell 
                                key={`cell-${idx}`} 
                                fill={localTableFilters.customer === entry.name ? '#6366f1' : COLORS[idx % COLORS.length]} 
                                fillOpacity={!localTableFilters.customer || localTableFilters.customer === entry.name ? 1 : 0.2}
                                style={{ transition: 'all 0.3s' }}
                              />
                            ))}
                          </Bar>
                        </BarChart>
                      </ResponsiveContainer>
                    </div>
                  </div>

                  {/* 联动趋势图：响应 localTableFilters.customer */}
                  <div className="bg-slate-50/50 rounded-3xl p-8 border border-slate-200 h-[450px] flex flex-col">
                    <h5 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2">
                       {localTableFilters.customer && <span className="w-2 h-2 rounded-full bg-indigo-600 animate-pulse"></span>}
                       {localTableFilters.customer ? `${localTableFilters.customer} 的` : '该品类的'} 历史业务走势
                    </h5>
                    <div className="flex-1 min-h-0">
                      <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={drillDownData.monthlyTrend}>
                          <defs>
                            <linearGradient id="drillGrad" x1="0" y1="0" x2="0" y2="1">
                              <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/>
                              <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                            </linearGradient>
                          </defs>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                          <XAxis dataKey="month" tick={{fontSize: 10, fill: '#64748b'}} axisLine={false} tickLine={false} />
                          <YAxis axisLine={false} tickLine={false} tickFormatter={(v) => `${(v/1000000).toFixed(1)}M`} />
                          <Tooltip formatter={(v: any) => v.toLocaleString()} />
                          <Area 
                            type="monotone" 
                            dataKey={(selectedCategory ? pieMetric : itemPieMetric) === 'sales' ? 'sales' : 'qty'} 
                            stroke="#6366f1" 
                            strokeWidth={3} 
                            fill="url(#drillGrad)" 
                          />
                        </AreaChart>
                      </ResponsiveContainer>
                    </div>
                  </div>
                </div>

                {/* 关联表格明细：执行最终过滤 */}
                <div className="bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-2xl">
                  <div className="p-5 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">单据明细</span>
                      {localTableFilters.customer && (
                        <span className="px-3 py-1 bg-indigo-600 text-white text-[10px] font-black rounded-lg animate-in zoom-in">筛选客户: {localTableFilters.customer}</span>
                      )}
                    </div>
                    <span className="text-xs font-bold text-slate-400">匹配记录: {drillDownData.records.length} 条</span>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="min-w-full text-xs">
                      <thead>
                        <tr>
                          <FilterHeader label="单号" columnId="id" />
                          <FilterHeader label="月份" columnId="month" />
                          <th className="px-3 py-3 bg-slate-50 border-b border-slate-200 text-left font-bold text-slate-600 text-[10px] uppercase">业务日期</th>
                          <FilterHeader label="客户" columnId="customer" />
                          <FilterHeader label="销售" columnId="salesperson" />
                          <FilterHeader label="物料" columnId="itemName" />
                          <th className="px-4 py-3 text-right bg-slate-50 border-b border-slate-200 font-bold text-slate-600 text-[10px] uppercase">单价</th>
                          <th className="px-4 py-3 text-right bg-slate-50 border-b border-slate-200 font-bold text-slate-600 text-[10px] uppercase">数量</th>
                          <th className="px-4 py-3 text-right bg-slate-50 border-b border-slate-200 font-bold text-slate-600 text-[10px] uppercase">合计金额</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {drillDownData.records.map((r, i) => (
                          <tr key={i} className={`hover:bg-slate-50 transition-colors ${localTableFilters.customer === r.customer ? 'bg-indigo-50/40' : ''}`}>
                            <td className="px-3 py-4 font-mono font-bold text-indigo-600">
                              <button onClick={() => onSelectOrderId(r.id)} className="hover:underline">{r.id}</button>
                            </td>
                            <td className="px-3 py-4 text-slate-500">{r.month}</td>
                            <td className="px-3 py-4 text-slate-500">{r.date}</td>
                            <td className={`px-3 py-4 font-bold ${localTableFilters.customer === r.customer ? 'text-indigo-800' : 'text-slate-900'}`}>{r.customer}</td>
                            <td className="px-3 py-4 text-slate-600">{r.salesperson}</td>
                            <td className="px-3 py-4 text-slate-600">{r.itemName}</td>
                            <td className="px-4 py-4 text-right font-mono text-slate-400">{r.unitPrice.toLocaleString()}</td>
                            <td className="px-4 py-4 text-right font-black text-indigo-700">{r.quantity}</td>
                            <td className="px-4 py-4 text-right font-black text-slate-900">{r.totalAmount.toLocaleString()}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [customerMetric, setCustomerMetric] = useState<'sales' | 'quantity'>('sales');

  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');

  // 折叠状态管理
  const [isTrendExpanded, setIsTrendExpanded] = useState(true);
  const [isCategoryExpanded, setIsCategoryExpanded] = useState(true);
  const [isItemExpanded, setIsItemExpanded] = useState(true);
  const [isCustomerExpanded, setIsCustomerExpanded] = useState(true);

  const [activeMetrics, setActiveMetrics] = useState({
    amount: true,
    quantity: true
  });

  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set(filteredData.map(d => d.month))).sort();
    const metrics = !activeMetrics.amount && !activeMetrics.quantity ? { amount: true, quantity: false } : activeMetrics;

    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return {
          name: month,
          amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0),
          quantity: monthRecords.reduce((s, r) => s + r.quantity, 0)
        };
      });
      const series: any[] = [];
      if (metrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (metrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }

    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set(filteredData.map(d => d[dimKey] as string))).slice(0, 8);

    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (metrics.amount) {
        series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor, dashed: false });
      }
      if (metrics.quantity) {
        series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
      }
    });

    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });

    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  const trendStats = useMemo(() => {
    const data = trendAnalysis.data;
    if (!data.length) return { amount: { total: 0, avg: 0 }, quantity: { total: 0, avg: 0 } };
    let totalAmt = 0;
    let totalQty = 0;
    if (trendMode === 'total') {
      totalAmt = data.reduce((s, d) => s + (d.amount || 0), 0);
      totalQty = data.reduce((s, d) => s + (d.quantity || 0), 0);
    } else {
      data.forEach(row => {
        trendAnalysis.series.forEach(s => {
          if (s.type === 'amount') totalAmt += (row[s.key] || 0);
          if (s.type === 'quantity') totalQty += (row[s.key] || 0);
        });
      });
    }
    return {
      amount: { total: totalAmt, avg: totalAmt / data.length },
      quantity: { total: totalQty, avg: totalQty / data.length }
    };
  }, [trendAnalysis, trendMode]);

  const customerAnalysisData = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.customer) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.customer, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => customerMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, customerMetric]);

  const customerModuleTotal = useMemo(() => {
    return customerAnalysisData.reduce((acc, cur) => acc + (customerMetric === 'sales' ? cur.sales : cur.quantity), 0);
  }, [customerAnalysisData, customerMetric]);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, itemPieMetric]);

  const toggleMetric = (type: 'amount' | 'quantity') => {
    setActiveMetrics(prev => ({ ...prev, [type]: !prev[type] }));
  };

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-RADIAN * midAngle);
    const cos = Math.cos(-RADIAN * midAngle);
    const sx = cx + (outerRadius + 5) * cos;
    const sy = cy + (outerRadius + 5) * sin;
    const mx = cx + (outerRadius + 30) * cos;
    const my = cy + (outerRadius + 30) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 22;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={2} opacity={0.6} />
        <circle cx={ex} cy={ey} r={3} fill={fill} />
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} textAnchor={textAnchor} fill="#0f172a" style={{ fontSize: '12px', fontWeight: 800 }}>{name}</text>
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} dy={16} textAnchor={textAnchor} fill="#475569" style={{ fontSize: '11px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  return (
    <div className="space-y-10 pb-16 relative">
      {/* 核心指标卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">物料出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col overflow-hidden">
           <div className="p-6 flex items-center justify-between bg-white border-b border-slate-100">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
                <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">业务单据总数</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div>
              </div>
              <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${isOrdersExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
           </div>
           {isOrdersExpanded && (
              <div className="px-5 py-5 bg-slate-50/50 border-t border-slate-100 space-y-4">
                <input type="text" placeholder="检索单号..." value={orderSearchTerm} onChange={(e) => setOrderSearchTerm(e.target.value)} className="w-full bg-white border border-slate-300 rounded-lg px-3 py-1.5 text-xs outline-none focus:border-indigo-500 font-bold" />
                <div className="max-h-40 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar pr-1">
                  {summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase())).map(id => (<button key={id} onClick={() => onSelectOrderId(id)} className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-bold hover:border-indigo-500 transition-colors">{id}</button>))}
                </div>
              </div>
           )}
        </div>
      </div>

      {/* 业绩增长趋势 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-8">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-2">📈 业绩增长趋势</h3>
          <button onClick={() => setIsTrendExpanded(!isTrendExpanded)} className={`px-4 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-2 ${isTrendExpanded ? 'bg-slate-100 text-slate-500 hover:bg-slate-200' : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-lg shadow-indigo-100'}`}>
            {isTrendExpanded ? '收起趋势分析' : '展开趋势分析'}
            <svg className={`w-4 h-4 transition-transform duration-300 ${isTrendExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
          </button>
        </div>
        {isTrendExpanded && (
          <div className="animate-in fade-in slide-in-from-top-4 duration-500">
            <div className="flex flex-col items-center justify-center mb-10 gap-6 relative">
              <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200 shadow-inner">
                <button onClick={() => setTrendMode('total')} className={`px-5 py-2 rounded-xl text-xs font-black transition-all ${trendMode === 'total' ? 'bg-white shadow-md text-slate-900' : 'text-slate-500 hover:text-slate-700'}`}>汇总统计</button>
                <button onClick={() => setTrendMode('customer')} className={`px-5 py-2 rounded-xl text-xs font-black transition-all ${trendMode === 'customer' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500 hover:text-slate-700'}`}>客户对比</button>
                <button onClick={() => setTrendMode('salesperson')} className={`px-5 py-2 rounded-xl text-xs font-black transition-all ${trendMode === 'salesperson' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500 hover:text-slate-700'}`}>销售对比</button>
              </div>
              <div className="lg:absolute lg:right-0 flex gap-3">
                <button onClick={() => toggleMetric('amount')} className={`px-4 py-2 rounded-xl text-xs font-black transition-all border ${activeMetrics.amount ? 'bg-indigo-50 border-indigo-600 text-indigo-700' : 'bg-white border-slate-200 text-slate-400'}`}>金额</button>
                <button onClick={() => toggleMetric('quantity')} className={`px-4 py-2 rounded-xl text-xs font-black transition-all border ${activeMetrics.quantity ? 'bg-emerald-50 border-emerald-600 text-emerald-700' : 'bg-white border-slate-200 text-slate-400'}`}>数量</button>
              </div>
            </div>
            <div className="flex flex-wrap justify-center items-center gap-12 mb-8 bg-slate-50/50 p-6 rounded-2xl border border-slate-100">
              {activeMetrics.amount && (
                <div className="flex items-center gap-12 pr-12 border-r border-slate-200 last:border-0 last:pr-0">
                  <div className="flex flex-col items-center text-center">
                    <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1">周期累计金额</span>
                    <div className="flex items-baseline gap-1">
                      <span className="text-2xl font-black text-indigo-600">{trendStats.amount.total.toLocaleString()}</span>
                      <span className="text-[10px] font-bold text-slate-400 uppercase">CFA</span>
                    </div>
                  </div>
                  <div className="flex flex-col items-center text-center">
                    <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1">周期月均金额</span>
                    <div className="flex items-baseline gap-1">
                      <span className="text-2xl font-black text-indigo-600">{trendStats.amount.avg.toLocaleString(undefined, { maximumFractionDigits: 0 })}</span>
                      <span className="text-[10px] font-bold text-slate-400 uppercase">CFA</span>
                    </div>
                  </div>
                </div>
              )}
              {activeMetrics.quantity && (
                <div className="flex items-center gap-12 pr-12 border-r border-slate-200 last:border-0 last:pr-0">
                  <div className="flex flex-col items-center text-center">
                    <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest mb-1">周期累计数量</span>
                    <div className="flex items-baseline gap-1">
                      <span className="text-2xl font-black text-emerald-600">{trendStats.quantity.total.toLocaleString()}</span>
                      <span className="text-[10px] font-bold text-slate-400 uppercase">UNIT</span>
                    </div>
                  </div>
                  <div className="flex flex-col items-center text-center">
                    <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest mb-1">周期月均数量</span>
                    <div className="flex items-baseline gap-1">
                      <span className="text-2xl font-black text-emerald-600">{trendStats.quantity.avg.toLocaleString(undefined, { maximumFractionDigits: 1 })}</span>
                      <span className="text-[10px] font-bold text-slate-400 uppercase">UNIT</span>
                    </div>
                  </div>
                </div>
              )}
            </div>
            <div className="h-[480px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={trendAnalysis.data}>
                  <defs>
                    {trendAnalysis.series.map((s, i) => (
                      <linearGradient key={s.key} id={`grad-${i}`} x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor={s.color} stopOpacity={0.3}/>
                        <stop offset="95%" stopColor={s.color} stopOpacity={0}/>
                      </linearGradient>
                    ))}
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11}} dy={10} />
                  <YAxis yAxisId="amount" orientation="left" axisLine={false} tickLine={false} hide={!activeMetrics.amount} tick={{fill: '#6366f1', fontSize: 11}} tickFormatter={(v) => `${(v / 1000000).toFixed(1)}M`} />
                  <YAxis yAxisId="quantity" orientation="right" axisLine={false} tickLine={false} hide={!activeMetrics.quantity} tick={{fill: '#10b981', fontSize: 11}} />
                  <Tooltip formatter={(value: any, name: any) => [value.toLocaleString(), name]} />
                  <Legend />
                  {trendAnalysis.series.map((s, i) => (
                    <Area key={s.key} yAxisId={s.type} type="monotone" dataKey={s.key} name={s.name} stroke={s.color} strokeWidth={3} fill={`url(#grad-${i})`} />
                  ))}
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}
      </section>

      {/* 品类业务构成 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex justify-between items-center mb-10">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-2">🧩 品类业务构成</h3>
          <div className="flex items-center gap-4">
            {isCategoryExpanded && (
              <div className="flex bg-slate-100 p-1 rounded-xl animate-in fade-in duration-300">
                <button onClick={() => setPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>按金额</button>
                <button onClick={() => setPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>按数量</button>
              </div>
            )}
            <button onClick={() => setIsCategoryExpanded(!isCategoryExpanded)} className={`px-4 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-2 ${isCategoryExpanded ? 'bg-slate-100 text-slate-500 hover:bg-slate-200' : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-lg shadow-indigo-100'}`}>
              {isCategoryExpanded ? '收起构成分析' : '展开构成分析'}
              <svg className={`w-4 h-4 transition-transform duration-300 ${isCategoryExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
            </button>
          </div>
        </div>
        {isCategoryExpanded && (
          <div className="flex flex-col xl:flex-row items-center gap-16 animate-in fade-in slide-in-from-top-4 duration-500">
            <div className="relative w-full xl:w-[600px] h-[480px] flex-shrink-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={sortedCategorySummary} cx="50%" cy="50%" innerRadius={110} outerRadius={160} paddingAngle={5} dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} stroke="#fff" strokeWidth={3} label={renderCustomizedLabel} labelLine={false}>
                    {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-2 gap-4">
              {sortedCategorySummary.map((item) => (
                <div key={item.name} className="flex items-center justify-between p-5 rounded-2xl border border-slate-200 bg-slate-50 text-slate-900">
                  <span className="text-sm font-black truncate">{item.name}</span>
                  <span className="text-lg font-mono font-black">{(pieMetric === 'sales' ? item.sales : item.quantity).toLocaleString()}</span>
                </div>
              ))}
            </div>
          </div>
        )}
      </section>

      {/* 物料业务构成 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex justify-between items-center mb-10">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-2">📦 物料业务构成</h3>
          <div className="flex items-center gap-4">
            {isItemExpanded && (
              <div className="flex bg-slate-100 p-1 rounded-xl animate-in fade-in duration-300">
                <button onClick={() => setItemPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${itemPieMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>按金额</button>
                <button onClick={() => setItemPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${itemPieMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>按数量</button>
              </div>
            )}
            <button onClick={() => setIsItemExpanded(!isItemExpanded)} className={`px-4 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-2 ${isItemExpanded ? 'bg-slate-100 text-slate-500 hover:bg-slate-200' : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-lg shadow-indigo-100'}`}>
              {isItemExpanded ? '收起物料分析' : '展开物料分析'}
              <svg className={`w-4 h-4 transition-transform duration-300 ${isItemExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
            </button>
          </div>
        </div>
        {isItemExpanded && (
          <div className="flex flex-col xl:flex-row items-center gap-16 animate-in fade-in slide-in-from-top-4 duration-500">
            <div className="relative w-full xl:w-[600px] h-[480px] flex-shrink-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={sortedItemSummary.slice(0, 10)} cx="50%" cy="50%" innerRadius={110} outerRadius={160} paddingAngle={5} dataKey={itemPieMetric === 'sales' ? 'sales' : 'quantity'} stroke="#fff" strokeWidth={3} label={renderCustomizedLabel} labelLine={false}>
                    {sortedItemSummary.slice(0, 10).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[500px] overflow-y-auto custom-scrollbar">
              {sortedItemSummary.map((item) => (
                <div key={item.name} className="flex items-center justify-between p-5 rounded-2xl border border-slate-200 bg-slate-50 text-slate-900">
                  <span className="text-sm font-black truncate">{item.name}</span>
                  <span className="text-lg font-mono font-black">{(itemPieMetric === 'sales' ? item.sales : item.quantity).toLocaleString()}</span>
                </div>
              ))}
            </div>
          </div>
        )}
      </section>

      {/* 客户采购排行分析 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-8">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-2">👥 客户采购排行分析</h3>
          <button onClick={() => setIsCustomerExpanded(!isCustomerExpanded)} className={`px-4 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-2 ${isCustomerExpanded ? 'bg-slate-100 text-slate-500 hover:bg-slate-200' : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-lg shadow-indigo-100'}`}>
            {isCustomerExpanded ? '收起排名分析' : '展开排名分析'}
            <svg className={`w-4 h-4 transition-transform duration-300 ${isCustomerExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
          </button>
        </div>
        {isCustomerExpanded && (
          <div className="animate-in fade-in slide-in-from-top-4 duration-500">
            <div className="flex flex-col md:flex-row items-start md:items-end justify-between mb-10 gap-6">
              <div className="flex flex-col">
                <span className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-1">
                  {customerMetric === 'sales' ? '累计采购总额 (CFA)' : '累计采购总量 (UNIT)'}
                </span>
                <div className="flex items-baseline gap-2">
                  <span className={`text-4xl font-black ${customerMetric === 'sales' ? 'text-indigo-600' : 'text-emerald-600'}`}>
                    {customerMetric === 'sales' 
                      ? `${(customerModuleTotal / 1000000).toFixed(2)}M` 
                      : customerModuleTotal.toLocaleString()}
                  </span>
                  {customerMetric === 'sales' && <span className="text-sm font-bold text-slate-400">百万 CFA</span>}
                </div>
              </div>
              <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200 shadow-inner">
                <button onClick={() => setCustomerMetric('sales')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${customerMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500 hover:text-slate-700'}`}>按采购金额</button>
                <button onClick={() => setCustomerMetric('quantity')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${customerMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500 hover:text-slate-700'}`}>按采购数量</button>
              </div>
            </div>
            <div className="w-full" style={{ height: `${Math.max(400, customerAnalysisData.length * 45)}px` }}>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={customerAnalysisData} layout="vertical" margin={{ left: 20, right: 80, top: 0, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#e2e8f0" />
                  <XAxis type="number" hide />
                  <YAxis type="category" dataKey="name" width={150} axisLine={false} tickLine={false} tick={{ fill: '#475569', fontSize: 12, fontWeight: 700 }} />
                  <Tooltip cursor={{ fill: '#f1f5f9' }} contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)' }} formatter={(v: any) => [v.toLocaleString(), customerMetric === 'sales' ? '金额 (CFA)' : '数量 (UNIT)']} />
                  <Bar dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} radius={[0, 8, 8, 0]} barSize={24}>
                    {customerAnalysisData.map((_, index) => (
                      <RechartsCell key={`cell-${index}`} fill={customerMetric === 'sales' ? '#6366f1' : '#10b981'} fillOpacity={1 - (index / customerAnalysisData.length) * 0.6} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}
      </section>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  // 全局展示状态
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [customerMetric, setCustomerMetric] = useState<'sales' | 'quantity'>('sales');
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');

  // 深度分析联动状态 (State Isolation)
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [localTableFilters, setLocalTableFilters] = useState({
    customer: '' // 局部交叉联动核心状态
  });

  // 折叠状态管理
  const [isTrendExpanded, setIsTrendExpanded] = useState(true);
  const [isCategoryExpanded, setIsCategoryExpanded] = useState(true);
  const [isItemExpanded, setIsItemExpanded] = useState(true);
  const [isCustomerExpanded, setIsCustomerExpanded] = useState(true);

  const [activeMetrics, setActiveMetrics] = useState({ amount: true, quantity: true });
  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  // --- 响应式计算链 (Reactive Computation Chain) ---
  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : null);
    const value = selectedCategory || selectedItem;
    if (!dimension || !value) return null;

    // 1. 原始数据 -> 维度过滤 (Category/Item)
    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);

    // 2. 基础指标计算
    const totalSales = baseRecords.reduce((s, r) => s + r.totalAmount, 0);
    const totalQty = baseRecords.reduce((s, r) => s + r.quantity, 0);

    // 3. 客户分布计算 (不随 localFilter 变化，用于作为触发源)
    const custMap = new Map<string, { sales: number; qty: number }>();
    baseRecords.forEach(r => {
      const e = custMap.get(r.customer) || { sales: 0, qty: 0 };
      custMap.set(r.customer, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });
    const customers = Array.from(custMap.entries())
      .map(([name, v]) => ({ name, sales: v.sales, qty: v.qty }))
      .sort((a, b) => b.sales - a.sales);

    // 4. 联动过滤响应：趋势图 & 明细表 (基于 selectedCustomer)
    const trendAndTableRecords = localTableFilters.customer 
      ? baseRecords.filter(r => r.customer === localTableFilters.customer)
      : baseRecords;

    // 趋势图数据
    const monthMap = new Map<string, { sales: number; qty: number }>();
    trendAndTableRecords.forEach(r => {
      const e = monthMap.get(r.month) || { sales: 0, qty: 0 };
      monthMap.set(r.month, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });
    const monthlyTrend = Array.from(monthMap.entries())
      .map(([name, v]) => ({ name, sales: v.sales, qty: v.qty }))
      .sort((a, b) => a.name.localeCompare(b.name));

    return {
      baseRecords,
      totalSales,
      totalQty,
      customers,
      monthlyTrend,
      tableRecords: trendAndTableRecords.sort((a, b) => b.date.localeCompare(a.date))
    };
  }, [selectedCategory, selectedItem, filteredData, localTableFilters.customer]);

  // --- 事件处理：点击捕获稳定性 ---
  const handleBarChartClick = (state: any) => {
    if (state && state.activeLabel) {
      const clickedCustomer = state.activeLabel;
      setLocalTableFilters(prev => ({
        customer: prev.customer === clickedCustomer ? '' : clickedCustomer
      }));
    }
  };

  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set(filteredData.map(d => d.month))).sort();
    const metrics = !activeMetrics.amount && !activeMetrics.quantity ? { amount: true, quantity: false } : activeMetrics;

    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return {
          name: month,
          amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0),
          quantity: monthRecords.reduce((s, r) => s + r.quantity, 0)
        };
      });
      const series: any[] = [];
      if (metrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (metrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }

    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set(filteredData.map(d => d[dimKey] as string))).slice(0, 8);

    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (metrics.amount) series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor });
      if (metrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
    });

    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });

    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  const customerAnalysisData = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.customer) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.customer, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => customerMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, customerMetric]);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, itemPieMetric]);

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-RADIAN * midAngle);
    const cos = Math.cos(-RADIAN * midAngle);
    const sx = cx + (outerRadius + 5) * cos;
    const sy = cy + (outerRadius + 5) * sin;
    const mx = cx + (outerRadius + 30) * cos;
    const my = cy + (outerRadius + 30) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 22;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={2} opacity={0.6} />
        <circle cx={ex} cy={ey} r={3} fill={fill} />
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} textAnchor={textAnchor} fill="#0f172a" style={{ fontSize: '11px', fontWeight: 800 }}>{name}</text>
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} dy={14} textAnchor={textAnchor} fill="#475569" style={{ fontSize: '10px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  return (
    <div className="space-y-10 pb-16 relative">
      {/* 核心指标卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col overflow-hidden">
           <div className="p-6 flex items-center justify-between bg-white border-b border-slate-100">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
                <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">单据总数</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div>
              </div>
              <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${isOrdersExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
           </div>
           {isOrdersExpanded && (
              <div className="px-5 py-5 bg-slate-50/50 border-t border-slate-100 space-y-4 animate-in fade-in duration-300">
                <input type="text" placeholder="检索单号..." value={orderSearchTerm} onChange={(e) => setOrderSearchTerm(e.target.value)} className="w-full bg-white border border-slate-300 rounded-lg px-3 py-1.5 text-xs outline-none focus:border-indigo-500 font-bold" />
                <div className="max-h-40 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar pr-1">
                  {summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase())).map(id => (<button key={id} onClick={() => onSelectOrderId(id)} className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-bold hover:border-indigo-500 transition-colors">{id}</button>))}
                </div>
              </div>
           )}
        </div>
      </div>

      {/* 业绩增长趋势 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-8">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-2">📈 业绩增长趋势</h3>
          <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200">
            <button onClick={() => setTrendMode('total')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'total' ? 'bg-white shadow-md text-slate-900' : 'text-slate-500 hover:text-slate-700'}`}>汇总</button>
            <button onClick={() => setTrendMode('customer')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'customer' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500 hover:text-slate-700'}`}>按客户</button>
            <button onClick={() => setTrendMode('salesperson')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'salesperson' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500 hover:text-slate-700'}`}>按销售</button>
          </div>
        </div>
        <div className="h-[400px] w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={trendAnalysis.data}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11}} />
              <YAxis yAxisId="amount" axisLine={false} tickLine={false} hide={!activeMetrics.amount} tickFormatter={(v) => `${(v / 1000000).toFixed(1)}M`} />
              <YAxis yAxisId="quantity" orientation="right" axisLine={false} tickLine={false} hide={!activeMetrics.quantity} />
              <Tooltip />
              <Legend />
              {trendAnalysis.series.map((s, i) => (
                <Area key={s.key} yAxisId={s.type} type="monotone" dataKey={s.key} name={s.name} stroke={s.color} strokeWidth={2.5} fill={s.color} fillOpacity={0.05} />
              ))}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </section>

      {/* 品类业务构成 - 点击下钻入口 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex justify-between items-center mb-10">
          <div>
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-2">🧩 品类业务构成</h3>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1 italic">点击饼图或列表进入下钻深度分析</p>
          </div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>金额</button>
            <button onClick={() => setPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量</button>
          </div>
        </div>
        <div className="flex flex-col xl:flex-row items-center gap-16">
          <div className="relative w-full xl:w-[500px] h-[400px]">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie 
                  data={sortedCategorySummary} 
                  cx="50%" cy="50%" innerRadius={100} outerRadius={140} paddingAngle={5} 
                  dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} 
                  stroke="#fff" strokeWidth={3} label={renderCustomizedLabel} labelLine={false}
                  onClick={(d) => { setSelectedCategory(d.name); setSelectedItem(null); }}
                >
                  {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} className="cursor-pointer hover:opacity-80 transition-opacity" />)}
                </Pie>
