        {/* 物料业务构成 */}
        <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200 flex flex-col items-center">
          <div className="w-full flex justify-between items-center mb-6">
            <div>
              <h3 className="text-xl font-black text-slate-900">📦 物料业务构成</h3>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1 italic">点击扇区进入下钻穿透分析</p>
            </div>
            <div className="flex bg-slate-100 p-1 rounded-xl">
              <button onClick={() => setItemPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${itemPieMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>金额</button>
              <button onClick={() => setItemPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${itemPieMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量</button>
            </div>
          </div>
          <div className="relative w-full h-[450px]">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie 
                  data={sortedItemSummary.slice(0, 15)} 
                  cx="50%" cy="50%" innerRadius={100} outerRadius={150} paddingAngle={5} 
                  dataKey={itemPieMetric === 'sales' ? 'sales' : 'quantity'} 
                  stroke="#fff" strokeWidth={3} label={renderCustomizedLabel} labelLine={false}
                  onClick={(d) => openItemDrillDown(d.name)}
                >
                  {sortedItemSummary.slice(0, 15).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} className="cursor-pointer hover:opacity-80 transition-opacity" />)}
