            </ResponsiveContainer>
          </div>
        </section>
      </div>

      {/* 客户排行 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-8">
          <div className="flex flex-col">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-2">👥 客户采购排行分析</h3>
            <div className="mt-2 flex items-baseline gap-2">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest italic">当前汇总:</span>
              <span className={`text-2xl font-black ${customerMetric === 'sales' ? 'text-indigo-600' : 'text-emerald-600'}`}>
                {customerTotalMetricValue.toLocaleString()} 
                <span className="ml-1 text-xs font-bold opacity-70">{customerMetric === 'sales' ? 'CFA' : 'UNIT'}</span>
              </span>
            </div>
          </div>
          <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200">
            <button onClick={() => setCustomerMetric('sales')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${customerMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500 hover:text-slate-700'}`}>金额</button>
            <button onClick={() => setCustomerMetric('quantity')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${customerMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500 hover:text-slate-700'}`}>数量</button>
          </div>
        </div>
        <div className="w-full" style={{ height: `${Math.max(400, customerAnalysisData.length * 48)}px` }}>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={customerAnalysisData} layout="vertical" margin={{ left: 20, right: 120 }}>
              <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#e2e8f0" />
              <XAxis type="number" hide />
              <YAxis 
                type="category" 
                dataKey="name" 
                width={150} 
                axisLine={false} 
                tickLine={false} 
                tick={(props) => (
                  <text 
                    {...props} 
                    className="fill-slate-600 font-black text-[12px] hover:fill-indigo-600 hover:underline cursor-pointer transition-colors"
                    onClick={() => openCustomerDrillDown(props.payload.value)}
                  >
                    {props.payload.value}
                  </text>
                )} 
              />
              <Tooltip 
                cursor={{ fill: '#f1f5f9', opacity: 0.5 }} 
                contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                formatter={(v: any) => [v.toLocaleString(), customerMetric === 'sales' ? '采购总额' : '采购总量']}
              />
              <Bar 
                dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} 
                radius={[0, 10, 10, 0]} 
                barSize={30}
                onClick={(d) => openCustomerDrillDown(d.name)}
                className="cursor-pointer"
              >
                {customerAnalysisData.map((_, index) => (
                  <RechartsCell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
                <LabelList 
                  dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} 
                  position="right" 
                  formatter={(v: any) => v.toLocaleString()}
                  style={{ fill: '#475569', fontSize: '11px', fontWeight: 900, fontFamily: 'monospace' }}
                />
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </section>

      {/* --- 深度下钻分析全屏面板 --- */}
      {(selectedCategory || selectedItem || selectedCustomer) && (
        <div className="fixed inset-0 bg-white z-[5000] flex flex-col animate-in slide-in-from-bottom-10 duration-500 overflow-hidden">
           {/* 面板头部 */}
           <div className="px-10 py-6 border-b border-slate-200 bg-white flex items-center justify-between shadow-sm z-10">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-indigo-100">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                </div>
                <div>
                  <h3 className="text-2xl font-black text-slate-900 tracking-tight flex items-center gap-3">
                    {selectedCategory || selectedItem || selectedCustomer} <span className="text-slate-300 font-normal">|</span> <span className="text-indigo-600">深度业务穿透分析</span>
                  </h3>
                  <p className="text-[10px] font-bold text-slate-400 italic mt-1 uppercase tracking-widest">
                    维度性质：{selectedCategory ? '业务品类' : (selectedItem ? '物料明细' : '关联客户')} · 点击柱图锁定对比分析
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-6">
                <div className="flex bg-slate-100 p-1.5 rounded-xl">
                  <button onClick={() => setDrillMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${drillMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>金额</button>
                  <button onClick={() => setDrillMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${drillMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量</button>
                </div>
                <button 
                  onClick={() => { setSelectedCategory(null); setSelectedItem(null); setSelectedCustomer(null); setLocalTableFilters({ customer: '' }); setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] }); }}
                  className="px-10 py-3 bg-slate-900 text-white rounded-2xl text-xs font-black hover:bg-slate-800 transition-all shadow-2xl"
                >
                  关闭分析面板
                </button>
              </div>
           </div>

           {/* 面板内容区域 */}
           <div className="flex-1 overflow-y-auto custom-scrollbar p-10 bg-slate-50/30 space-y-10">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className={`bg-white p-6 rounded-2xl border ${drillMetric === 'sales' ? 'border-indigo-200 ring-2 ring-indigo-50' : 'border-slate-200'} shadow-sm transition-all`}>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">该维度累计销售 (CFA)</p>
                  <p className="text-3xl font-black text-indigo-600">{(drillDownAnalysis.totalSales || 0).toLocaleString()}</p>
                </div>
                <div className={`bg-white p-6 rounded-2xl border ${drillMetric === 'quantity' ? 'border-emerald-200 ring-2 ring-emerald-50' : 'border-slate-200'} shadow-sm transition-all`}>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">累计出库总量 (UNIT)</p>
                  <p className="text-3xl font-black text-emerald-600">{(drillDownAnalysis.totalQty || 0).toLocaleString()}</p>
                </div>
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">关联记录行数</p>
                  <p className="text-3xl font-black text-slate-900">{drillDownAnalysis.baseRecords.length} <span className="text-sm font-bold text-slate-400 uppercase">Lines</span></p>
                </div>
              </div>

              {/* 中间图表联动 - 垂直并列布局 */}
              <div className="flex flex-col gap-10">
                <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm flex flex-col h-[400px] overflow-hidden">
                   <h5 className="text-xs font-black text-slate-500 uppercase tracking-widest mb-6 flex items-center justify-between">
                     关联客户贡献分布 ({drillMetric === 'sales' ? '金额' : '数量'})
                     {localTableFilters.customer && <span className="px-2 py-0.5 bg-indigo-100 text-indigo-600 rounded text-[9px]">已锁定：{localTableFilters.customer}</span>}
                   </h5>
                   <div className="flex-1">
                      <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={drillDownAnalysis.customers.slice(0, 15)} onClick={handleBarChartClick}>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                          <XAxis dataKey="name" tick={{ fontSize: 10, fill: '#64748b' }} axisLine={false} tickLine={false} />
                          <YAxis axisLine={false} tickLine={false} tickFormatter={(v) => drillMetric === 'sales' ? `${(v/1000000).toFixed(1)}M` : v.toLocaleString()} />
                          <Tooltip cursor={{ fill: '#f8fafc' }} formatter={(v: any) => [v.toLocaleString(), drillMetric === 'sales' ? '金额' : '数量']} />
                          <Bar dataKey={drillMetric === 'sales' ? 'sales' : 'qty'} radius={[8, 8, 0, 0]} barSize={40} cursor="pointer">
                            {drillDownAnalysis.customers.slice(0, 15).map((entry, idx) => (
                              <RechartsCell 
                                key={`cell-${idx}`} 
                                fill={localTableFilters.customer === entry.name ? '#6366f1' : COLORS[idx % COLORS.length]} 
                                fillOpacity={!localTableFilters.customer || localTableFilters.customer === entry.name ? 1 : 0.2}
                              />
                            ))}
                          </Bar>
                        </BarChart>
                      </ResponsiveContainer>
                   </div>
                </div>

                <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm flex flex-col h-[400px] overflow-hidden">
                   <h5 className="text-xs font-black text-slate-500 uppercase tracking-widest mb-6">业务趋势概览</h5>
                   <div className="flex-1">
                      <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={drillDownAnalysis.monthlyTrend}>
                          <defs>
                            <linearGradient id="drillGrad" x1="0" y1="0" x2="0" y2="1">
                              <stop offset="5%" stopColor={drillMetric === 'sales' ? '#6366f1' : '#10b981'} stopOpacity={0.3}/>
                              <stop offset="95%" stopColor={drillMetric === 'sales' ? '#6366f1' : '#10b981'} stopOpacity={0}/>
                            </linearGradient>
                          </defs>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                          <XAxis dataKey="name" tick={{ fontSize: 10, fill: '#64748b' }} axisLine={false} tickLine={false} />
                          <YAxis axisLine={false} tickLine={false} tickFormatter={(v) => drillMetric === 'sales' ? `${(v/1000000).toFixed(1)}M` : v.toLocaleString()} />
                          <Tooltip />
                          <Area type="monotone" dataKey={drillMetric === 'sales' ? 'sales' : 'qty'} stroke={drillMetric === 'sales' ? '#6366f1' : '#10b981'} fill="url(#drillGrad)" strokeWidth={3} />
                        </AreaChart>
                      </ResponsiveContainer>
                   </div>
                </div>
              </div>

              {/* 带下拉筛选的明细表 */}
              <div className="bg-white rounded-3xl border border-slate-200 shadow-xl overflow-hidden mb-12">
                 <div className="px-8 py-5 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">关联订单明细清单</span>
                      {(Object.values(columnFilters) as string[][]).some(v => v.length > 0) && (
                        <button 
                          onClick={() => setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] })}
                          className="text-[10px] font-black text-red-500 bg-red-50 px-3 py-1 rounded border border-red-100 hover:bg-red-100 transition-all"
                        >
                          重置所有明细筛选
                        </button>
                      )}
                    </div>
                    <span className="text-xs font-black text-slate-400">已过滤: {drillDownAnalysis.tableRecords.length} 行 / 共 {drillDownAnalysis.baseRecords.length} 行</span>
                 </div>
                 <div className="overflow-x-auto max-h-[600px] custom-scrollbar">
                    <table className="min-w-full divide-y divide-slate-100">
                       <thead className="bg-white sticky top-0 z-[500] shadow-sm">
                          <tr>
                            <th className="px-8 py-5 text-left"><TableDropdownFilter field="id" label="单号" /></th>
                            <th className="px-8 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">日期</th>
                            <th className="px-8 py-5 text-left"><TableDropdownFilter field="customer" label="客户" /></th>
                            <th className="px-8 py-5 text-left"><TableDropdownFilter field="salesperson" label="销售员" /></th>
                            <th className="px-8 py-5 text-left"><TableDropdownFilter field="itemName" label="物料名称" /></th>
                            <th className="px-8 py-5 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">数量</th>
                            <th className="px-8 py-5 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">单价</th>
                            <th className="px-8 py-5 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">合计(CFA)</th>
                          </tr>
                       </thead>
                       <tbody className="bg-white divide-y divide-slate-50">
                          {drillDownAnalysis.tableRecords.map((r, i) => (
                            <tr key={`${r.id}-${i}`} className="hover:bg-slate-50/80 transition-colors">
                               <td className="px-8 py-4 whitespace-nowrap text-xs font-mono font-bold text-indigo-600">
                                  <button onClick={() => onSelectOrderId(r.id)} className="hover:underline">{r.id}</button>
                               </td>
                               <td className="px-8 py-4 whitespace-nowrap text-xs font-bold text-slate-500">{r.date}</td>
                               <td className="px-8 py-4 whitespace-nowrap text-xs font-black text-slate-900">{r.customer}</td>
                               <td className="px-8 py-4 whitespace-nowrap text-xs font-bold text-slate-500">{r.salesperson}</td>
                               <td className="px-8 py-4 whitespace-nowrap text-xs font-black text-slate-700">{r.itemName}</td>
                               <td className="px-8 py-4 whitespace-nowrap text-right text-xs font-mono font-black text-indigo-700">{r.quantity}</td>
                               <td className="px-8 py-4 whitespace-nowrap text-right text-xs font-mono font-bold text-slate-400">{r.unitPrice.toLocaleString()}</td>
                               <td className="px-8 py-4 whitespace-nowrap text-right text-sm font-mono font-black text-slate-900">{r.totalAmount.toLocaleString()}</td>
                            </tr>
                          ))}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7', '#fb7185', '#2dd4bf', '#fbbf24'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  // 全局展示状态
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [customerMetric, setCustomerMetric] = useState<'sales' | 'quantity'>('sales');
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');

  // 深度分析联动状态
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<string | null>(null);
  const [drillMetric, setDrillMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [localTableFilters, setLocalTableFilters] = useState({
    customer: '' // 面板内点击图表触发的二级过滤
  });

  // 明细表内部表头多选筛选状态
  const [columnFilters, setColumnFilters] = useState<Record<string, string[]>>({
    id: [],
    customer: [],
    salesperson: [],
    itemName: []
  });

  // 记录当前打开的筛选菜单
  const [activeFilterMenu, setActiveFilterMenu] = useState<string | null>(null);

  // 业绩趋势图指标控制
  const [activeMetrics, setActiveMetrics] = useState({ amount: true, quantity: true });

  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  // --- 响应式计算链 ---
  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : (selectedCustomer ? 'customer' : null));
    const value = selectedCategory || selectedItem || selectedCustomer;

    const defaultState = {
      baseRecords: [] as SalesRecord[],
      totalSales: 0,
      totalQty: 0,
      customers: [] as { name: string; sales: number; qty: number }[],
      monthlyTrend: [] as { name: string; sales: number; qty: number }[],
      filterOptions: {
        id: [] as string[],
        customer: [] as string[],
        salesperson: [] as string[],
        itemName: [] as string[]
      },
      tableRecords: [] as SalesRecord[]
    };

    if (!dimension || !value) return defaultState;

    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);
    const totalSales = baseRecords.reduce((s, r) => s + r.totalAmount, 0);
    const totalQty = baseRecords.reduce((s, r) => s + r.quantity, 0);

    const custMap = new Map<string, { sales: number; qty: number }>();
    baseRecords.forEach(r => {
      const e = custMap.get(r.customer) || { sales: 0, qty: 0 };
      custMap.set(r.customer, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });
    const customers = Array.from(custMap.entries())
      .map(([name, v]) => ({ name, sales: v.sales, qty: v.qty }))
      .sort((a, b) => drillMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    let finalRecords = baseRecords;
    if (localTableFilters.customer) {
      finalRecords = finalRecords.filter(r => r.customer === localTableFilters.customer);
    }

    (Object.entries(columnFilters) as [string, string[]][]).forEach(([field, selectedValues]) => {
      if (selectedValues.length > 0) {
        finalRecords = finalRecords.filter(r => selectedValues.includes(r[field as keyof SalesRecord] as string));
      }
    });

    const filterOptions = {
      id: Array.from(new Set(baseRecords.map(r => r.id))).sort(),
      customer: Array.from(new Set(baseRecords.map(r => r.customer))).sort(),
      salesperson: Array.from(new Set(baseRecords.map(r => r.salesperson))).sort(),
      itemName: Array.from(new Set(baseRecords.map(r => r.itemName))).sort()
    };

    const trendRecords = localTableFilters.customer 
      ? baseRecords.filter(r => r.customer === localTableFilters.customer)
      : baseRecords;

    const monthMap = new Map<string, { sales: number; qty: number }>();
    trendRecords.forEach(r => {
      const e = monthMap.get(r.month) || { sales: 0, qty: 0 };
      monthMap.set(r.month, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });
    const monthlyTrend = Array.from(monthMap.entries())
      .map(([name, v]) => ({ name, sales: v.sales, qty: v.qty }))
      .sort((a, b) => a.name.localeCompare(b.name));

    return {
      baseRecords,
      totalSales,
      totalQty,
      customers,
      monthlyTrend,
      filterOptions,
      tableRecords: finalRecords.sort((a, b) => b.date.localeCompare(a.date))
    };
  }, [selectedCategory, selectedItem, selectedCustomer, filteredData, localTableFilters.customer, columnFilters, drillMetric]);

  const handleBarChartClick = (state: any) => {
    if (state && state.activeLabel) {
      const clickedCustomer = state.activeLabel;
      setLocalTableFilters(prev => ({
        customer: prev.customer === clickedCustomer ? '' : clickedCustomer
      }));
    }
  };

  const openCategoryDrillDown = (name: string) => {
    setDrillMetric(pieMetric); 
    setSelectedCategory(name);
    setSelectedItem(null);
    setSelectedCustomer(null);
    setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] });
  };

  const openItemDrillDown = (name: string) => {
    setDrillMetric(itemPieMetric); 
    setSelectedItem(name);
    setSelectedCategory(null);
    setSelectedCustomer(null);
    setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] });
  };

  const openCustomerDrillDown = (name: string) => {
    setDrillMetric(customerMetric);
    setSelectedCustomer(name);
    setSelectedCategory(null);
    setSelectedItem(null);
    setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] });
  };

  const TableDropdownFilter = ({ field, label }: { field: string, label: string }) => {
    const options = (drillDownAnalysis.filterOptions as Record<string, string[]>)?.[field] || [];
    const selected = columnFilters[field] || [];
    const isActive = selected.length > 0;
    const menuRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
      const handleClickOutside = (e: MouseEvent) => {
        if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
          setActiveFilterMenu(null);
        }
      };
      if (activeFilterMenu === field) {
        document.addEventListener('mousedown', handleClickOutside);
      }
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [activeFilterMenu, field]);

    const toggleValue = (val: string) => {
      const next = selected.includes(val) ? selected.filter(v => v !== val) : [...selected, val];
      setColumnFilters(prev => ({ ...prev, [field]: next }));
    };

    return (
      <div className="relative inline-block" ref={menuRef}>
        <button 
          onClick={() => setActiveFilterMenu(activeFilterMenu === field ? null : field)}
          className={`flex items-center gap-1.5 transition-colors group ${isActive ? 'text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}
        >
          <span className={`text-[10px] font-black uppercase tracking-widest ${isActive ? 'text-indigo-600' : 'text-slate-400'}`}>{label}</span>
          <svg className={`w-2.5 h-2.5 transition-transform ${activeFilterMenu === field ? 'rotate-180' : ''}`} fill="currentColor" viewBox="0 0 20 20">
             <path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" />
          </svg>
        </button>

        {activeFilterMenu === field && (
          <div className="absolute top-full left-0 mt-2 w-64 bg-white border border-slate-200 shadow-2xl rounded-2xl z-[6000] overflow-hidden animate-in fade-in zoom-in-95 duration-150 origin-top-left">
             <div className="max-h-64 overflow-y-auto p-1.5 custom-scrollbar bg-white">
                <button 
                  onClick={() => setColumnFilters(prev => ({ ...prev, [field]: [] }))}
                  className="w-full text-left px-3 py-2 text-[10px] font-black text-indigo-600 hover:bg-indigo-50 rounded-lg mb-1"
                >
                  清除所有选择
                </button>
                {options.map(opt => (
                  <label key={opt} className="flex items-center px-3 py-2 hover:bg-slate-50 rounded-lg cursor-pointer group">
                    <input 
                      type="checkbox" 
                      checked={selected.includes(opt)}
                      onChange={() => toggleValue(opt)}
                      className="w-4 h-4 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 mr-3 cursor-pointer"
                    />
                    <span className={`text-xs truncate font-bold ${selected.includes(opt) ? 'text-indigo-900' : 'text-slate-600 group-hover:text-slate-900'}`}>{opt}</span>
                  </label>
                ))}
                {options.length === 0 && <p className="p-4 text-center text-[10px] text-slate-400 font-bold italic">无可用选项</p>}
             </div>
             <div className="px-3 py-2 border-t border-slate-100 bg-slate-50 flex justify-between items-center">
                <span className="text-[10px] font-black text-slate-400 uppercase">已选: {selected.length}</span>
                <button onClick={() => setActiveFilterMenu(null)} className="text-[10px] font-black text-slate-700 hover:text-indigo-600">确定</button>
             </div>
          </div>
        )}
      </div>
    );
  };

  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set(filteredData.map(d => d.month))).sort();
    const metrics = !activeMetrics.amount && !activeMetrics.quantity ? { amount: true, quantity: true } : activeMetrics;

    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return {
          name: month,
          amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0),
          quantity: monthRecords.reduce((s, r) => s + r.quantity, 0)
        };
      });
      const series: any[] = [];
      if (metrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (metrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }

    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set(filteredData.map(d => d[dimKey] as string))).slice(0, 8);

    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (metrics.amount) series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor });
      if (metrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
    });

    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });

    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  const customerAnalysisData = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.customer) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.customer, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => customerMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, customerMetric]);

  // 计算当前排名数据中的总金额(百万为单位)或总数量
  const customerTotalMetricDisplay = useMemo(() => {
    const rawSum = customerAnalysisData.reduce((acc, curr) => acc + (customerMetric === 'sales' ? curr.sales : curr.quantity), 0);
    if (customerMetric === 'sales') {
      return `${(rawSum / 1000000).toFixed(2)}M CFA`;
    }
    return `${rawSum.toLocaleString()} UNIT`;
  }, [customerAnalysisData, customerMetric]);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, itemPieMetric]);

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-RADIAN * midAngle);
    const cos = Math.cos(-RADIAN * midAngle);
    const sx = cx + (outerRadius + 5) * cos;
    const sy = cy + (outerRadius + 5) * sin;
    const mx = cx + (outerRadius + 30) * cos;
    const my = cy + (outerRadius + 30) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 22;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={2} opacity={0.6} />
        <circle cx={ex} cy={ey} r={3} fill={fill} />
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} textAnchor={textAnchor} fill="#0f172a" style={{ fontSize: '13px', fontWeight: 800 }}>{name}</text>
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} dy={16} textAnchor={textAnchor} fill="#475569" style={{ fontSize: '12px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  return (
    <div className="space-y-10 pb-16 relative">
      {/* 核心指标卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col overflow-hidden">
           <div className="p-6 flex items-center justify-between bg-white border-b border-slate-100">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
                <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">单据总数</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div>
              </div>
              <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${isOrdersExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
           </div>
           {isOrdersExpanded && (
              <div className="px-5 py-5 bg-slate-50/50 border-t border-slate-100 space-y-4 animate-in fade-in duration-300">
                <input type="text" placeholder="检索单号..." value={orderSearchTerm} onChange={(e) => setOrderSearchTerm(e.target.value)} className="w-full bg-white border border-slate-300 rounded-lg px-3 py-1.5 text-xs outline-none focus:border-indigo-500 font-bold" />
                <div className="max-h-40 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar pr-1">
                  {summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase())).map(id => (<button key={id} onClick={() => onSelectOrderId(id)} className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-bold hover:border-indigo-500 transition-colors">{id}</button>))}
                </div>
              </div>
           )}
        </div>
      </div>

      {/* 业绩增长趋势 */}
      <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 mb-8">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-2 shrink-0">📈 业绩增长趋势</h3>
          <div className="flex flex-wrap items-center gap-4">
            {/* 指标选择组 */}
            <div className="flex bg-slate-100 p-1 rounded-2xl border border-slate-200 shadow-inner">
               <button 
                onClick={() => setActiveMetrics({ amount: true, quantity: false })} 
                className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${activeMetrics.amount && !activeMetrics.quantity ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500 hover:text-slate-700'}`}
               >
                 金额
               </button>
               <button 
                onClick={() => setActiveMetrics({ amount: false, quantity: true })} 
                className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${!activeMetrics.amount && activeMetrics.quantity ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500 hover:text-slate-700'}`}
               >
                 数量
               </button>
               <button 
                onClick={() => setActiveMetrics({ amount: true, quantity: true })} 
                className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${activeMetrics.amount && activeMetrics.quantity ? 'bg-white shadow-md text-slate-900' : 'text-slate-500 hover:text-slate-700'}`}
               >
                 双轴
               </button>
            </div>
            {/* 维度切换组 */}
            <div className="flex bg-slate-100 p-1 rounded-2xl border border-slate-200 shadow-inner">
              <button onClick={() => setTrendMode('total')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'total' ? 'bg-white shadow-md text-slate-900' : 'text-slate-500 hover:text-slate-700'}`}>汇总</button>
              <button onClick={() => setTrendMode('customer')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'customer' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500 hover:text-slate-700'}`}>按客户</button>
              <button onClick={() => setTrendMode('salesperson')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'salesperson' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500 hover:text-slate-700'}`}>按销售</button>
            </div>
          </div>
        </div>
        <div className="h-[450px] w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={trendAnalysis.data}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11}} />

              {/* 金额主轴 */}
              {activeMetrics.amount && (
                <YAxis 
                  yAxisId="amount" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#6366f1', fontSize: 10, fontWeight: 700}}
                  tickFormatter={(v) => `${(v / 1000000).toFixed(1)}M`} 
                />
              )}

              {/* 数量次轴 */}
              {activeMetrics.quantity && (
                <YAxis 
                  yAxisId="quantity" 
                  orientation="right" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#10b981', fontSize: 10, fontWeight: 700}}
                  tickFormatter={(v) => v.toLocaleString()}
                />
              )}

              <Tooltip 
                contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }}
                formatter={(value: any, name: string) => [value.toLocaleString(), name]}
              />
              <Legend iconType="circle" />

              {trendAnalysis.series.map((s, i) => (
                <Area 
                  key={s.key} 
                  yAxisId={s.type} 
                  type="monotone" 
                  dataKey={s.key} 
                  name={s.name} 
                  stroke={s.color} 
                  strokeWidth={s.dashed ? 2 : 3} 
                  strokeDasharray={s.dashed ? "5 5" : "0"}
                  fill={s.color} 
                  fillOpacity={s.dashed ? 0 : 0.08} 
                  activeDot={{ r: 6, strokeWidth: 0 }}
                />
              ))}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </section>

      {/* 业务构成分析 */}
      <div className="flex flex-col gap-10">
        <section className="bg-white p-10 rounded-3xl shadow-sm border border-slate-200 flex flex-col items-center">
          <div className="w-full flex justify-between items-center mb-8">
            <div>
              <h3 className="text-2xl font-black text-slate-900">🧩 品类业务构成分析</h3>
              <p className="text-xs text-slate-400 font-bold uppercase tracking-[0.2em] mt-2 italic">点击扇区进入该品类的多维穿透分析面板</p>
            </div>
            <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200 shadow-inner">
              <button onClick={() => setPieMetric('sales')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${pieMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>按金额 (CFA)</button>
              <button onClick={() => setPieMetric('quantity')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>按数量 (UNIT)</button>
            </div>
          </div>
          <div className="w-full h-[600px] relative">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie 
                  data={sortedCategorySummary} 
                  cx="50%" cy="50%" innerRadius={140} outerRadius={220} paddingAngle={4} 
                  dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} 
                  stroke="#fff" strokeWidth={4} label={renderCustomizedLabel} labelLine={false}
                  onClick={(d) => openCategoryDrillDown(d.name)}
                >
                  {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} className="cursor-pointer hover:opacity-85 transition-opacity" />)}
                </Pie>
                <Tooltip formatter={(v: any) => v.toLocaleString()} />
                <Legend verticalAlign="bottom" height={36}/>
              </PieChart>
            </ResponsiveContainer>
          </div>
        </section>

        <section className="bg-white p-10 rounded-3xl shadow-sm border border-slate-200 flex flex-col items-center">
          <div className="w-full flex justify-between items-center mb-8">
            <div>
              <h3 className="text-2xl font-black text-slate-900">📦 物料核心业务构成 (TOP 15)</h3>
              <p className="text-xs text-slate-400 font-bold uppercase tracking-[0.2em] mt-2 italic">点击具体物料扇区查看全链路交易明细</p>
            </div>
            <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200 shadow-inner">
              <button onClick={() => setItemPieMetric('sales')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${itemPieMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>按金额 (CFA)</button>
              <button onClick={() => setItemPieMetric('quantity')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${itemPieMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>按数量 (UNIT)</button>
            </div>
          </div>
          <div className="w-full h-[600px] relative">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie 
                  data={sortedItemSummary.slice(0, 15)} 
                  cx="50%" cy="50%" innerRadius={140} outerRadius={220} paddingAngle={2} 
                  dataKey={itemPieMetric === 'sales' ? 'sales' : 'quantity'} 
                  stroke="#fff" strokeWidth={4} label={renderCustomizedLabel} labelLine={false}
                  onClick={(d) => openItemDrillDown(d.name)}
                >
                  {sortedItemSummary.slice(0, 15).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} className="cursor-pointer hover:opacity-85 transition-opacity" />)}
