                    {props.payload.value}
                  </text>
                )} 
              />
              <Tooltip 
                cursor={{ fill: '#f1f5f9', opacity: 0.5 }} 
                contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                formatter={(v: any) => [
                  customerMetric === 'sales' ? `${(v / 1000000).toFixed(2)}M` : v.toLocaleString(), 
                  customerMetric === 'sales' ? '金额(M)' : '采购总量'
