              <button onClick={() => setPieMetric('sales')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${pieMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>按金额</button>
