                <Pie data={sortedCategorySummary} cx="50%" cy="50%" innerRadius={140} outerRadius={220} paddingAngle={4} dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} stroke="#fff" strokeWidth={4} label={renderCustomizedLabel} labelLine={false} onClick={(d) => openCategoryDrillDown(d.name)}>
