                               <td className="px-8 py-4 whitespace-nowrap text-xs font-mono font-bold text-indigo-600"><button onClick={() => onSelectOrderId(r.id)} className="hover:underline">{r.id}</button></td>
                               <td className="px-8 py-4 whitespace-nowrap text-xs font-bold text-slate-500">{r.date}</td>
