/**
 * 极简健壮的日期标准化函数
 * 强制将各种输入转化为 YYYY-MM-DD
 */
const formatDateString = (dateStr: string): string => {
  if (!dateStr || typeof dateStr !== 'string') return '';

  // 移除所有空格，统一分隔符
  const cleanStr = dateStr.trim().replace(/[\/\.年 月]/g, '-').replace(/日/g, '');

  // 匹配常见的 YYYY-MM-DD 结构
  const match = cleanStr.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);

  if (match) {
    const year = match[1];
    const month = match[2].padStart(2, '0');
    const day = match[3].padStart(2, '0');
    return `${year}-${month}-${day}`;
  }

  // 兜底尝试 Date 解析
  try {
    const d = new Date(dateStr);
    if (!isNaN(d.getTime())) {
      const y = d.getFullYear();
      const m = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      return `${y}-${m}-${day}`;
    }
  } catch (e) {
    console.warn('Date parsing failed for:', dateStr);
  }

  return dateStr;
};

/**
 * 解析 CSV 文本
 */
export const processCsvText = (csvText: string): SalesRecord[] => {
  const rows = csvText.split(/\r?\n/).filter(line => line.trim() !== '');
  const parsedRows = rows.map(line => {
    const result: string[] = [];
    let currentField = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') inQuotes = !inQuotes;
      else if (char === ',' && !inQuotes) {
        result.push(currentField.replace(/^"|"$/g, '').trim());
        currentField = '';
      } else currentField += char;
    }
    result.push(currentField.replace(/^"|"$/g, '').trim());
    return result;
  });

  const dataRows = parsedRows.slice(1);
  return dataRows.map((cols, index) => {
    const rawDate = cols[2] || '';
    const standardizedDate = formatDateString(rawDate);

    // 如果月份列为空，根据 standardizedDate 自动提取
    let month = cols[1] || '';
    if (!month && standardizedDate.length >= 7) {
      month = standardizedDate.substring(0, 7);
    }

    return {
      id: cols[0] || `ID-${index}`,
      month: month,
      date: standardizedDate,
      customer: cols[3] || '',
      salesperson: cols[4] || '',
      category: cols[5] || '',
      itemName: cols[6] || '',
      quantity: parseFloat(cols[7].replace(/,/g, '')) || 0,
      unitPrice: parseFloat(cols[8].replace(/,/g, '')) || 0,
      totalAmount: parseFloat(cols[9].replace(/,/g, '')) || 0
    };
  });
};

/**
 * 远程获取数据
 */
export const fetchSalesData = async (): Promise<SalesRecord[]> => {
  try {
    const response = await fetch(`${CSV_URL}&t=${Date.now()}`); // 增加时间戳防止缓存
    if (!response.ok) {
        throw new Error('表格连接受阻。请检查共享权限或网络。');
    }
    const csvText = await response.text();
    if (csvText.includes('<!DOCTYPE html>')) {
        throw new Error('权限验证失败，请确保表格已公开共享。');
    }
    return processCsvText(csvText);
  } catch (error) {
    console.error('Fetch Error:', error);
    throw error;
  }
};

