                <MultiSelect label="客户" options={dynamicFilterData.customers.options} counts={dynamicFilterData.customers.counts} selectedValues={filters.customers} onChange={(v) => setFilters({...filters, customers: v})} />
                <MultiSelect label="销售员" options={dynamicFilterData.salespeople.options} counts={dynamicFilterData.salespeople.counts} selectedValues={filters.salespeople} onChange={(v) => setFilters({...filters, salespeople: v})} />
                <MultiSelect label="品类" options={dynamicFilterData.categories.options} counts={dynamicFilterData.categories.counts} selectedValues={filters.categories} onChange={(v) => setFilters({...filters, categories: v})} />
                <MultiSelect label="物料名称" options={dynamicFilterData.itemNames.options} counts={dynamicFilterData.itemNames.counts} selectedValues={filters.itemNames} onChange={(v) => setFilters({...filters, itemNames: v})} />
                <div className="space-y-1.5">
                  <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider">业务日期范围</label>
                  <div className="flex items-center gap-1 bg-slate-50 border border-slate-200 rounded-lg px-2 py-1.5 hover:bg-white hover:border-indigo-300 transition-all focus-within:ring-2 focus-within:ring-indigo-100 h-[42px]">
                    <input type="date" value={filters.dateRange[0]} onChange={(e) => setFilters({...filters, dateRange: [e.target.value, filters.dateRange[1]]})} className="bg-transparent text-[10px] font-bold text-slate-600 outline-none w-full cursor-pointer" />
                    <span className="text-slate-300">-</span>
                    <input type="date" value={filters.dateRange[1]} onChange={(e) => setFilters({...filters, dateRange: [filters.dateRange[0], e.target.value]})} className="bg-transparent text-[10px] font-bold text-slate-600 outline-none w-full cursor-pointer" />
                  </div>
                </div>
              </div>
            </div>
          )}
        </section>

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-32 space-y-4">
            <div className="w-12 h-12 border-4 border-slate-200 border-t-indigo-600 rounded-full animate-spin"></div>
            <p className="text-slate-400 font-bold tracking-widest uppercase text-xs">同步云端数据中...</p>
          </div>
        ) : (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
            {filteredData.length > 0 ? (
              activeTab === 'dashboard' ? (
                <Dashboard summary={summary} filteredData={filteredData} onSelectOrderId={setSelectedOrderId} />
              ) : (
                <DataTable data={filteredData} onSelectOrderId={setSelectedOrderId} />
              )
            ) : (
              <div className="py-32 bg-white rounded-3xl border border-dashed border-slate-200 text-center">
                <div className="text-5xl mb-4">🔎</div>
                <h3 className="text-xl font-bold text-slate-800">暂无匹配数据</h3>
                <p className="text-slate-500 mt-2">请尝试放宽筛选条件或重置日期范围</p>
                <button onClick={initializeFilters} className="mt-6 px-6 py-2 bg-indigo-600 text-white rounded-xl text-sm font-bold shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all">重置全部筛选</button>
              </div>
            )}
          </div>
        )}
      </main>

      {selectedOrderId && (
        <OrderDetailModal orderId={selectedOrderId} records={cloudData.filter(d => d.id === selectedOrderId)} onClose={() => setSelectedOrderId(null)} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7', '#fb7185', '#2dd4bf', '#fbbf24'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  // 版块折叠状态
  const [sections, setSections] = useState({
    trend: true,
    composition: true,
    ranking: true
  });

  // 全局展示状态
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [customerMetric, setCustomerMetric] = useState<'sales' | 'quantity'>('sales');
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');

  // 深度分析联动状态
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<string | null>(null);
  const [drillMetric, setDrillMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [localTableFilters, setLocalTableFilters] = useState({
    customer: '', 
    category: ''  
  });

  const [columnFilters, setColumnFilters] = useState<Record<string, string[]>>({
    id: [],
    customer: [],
    salesperson: [],
    itemName: []
  });

  const [activeFilterMenu, setActiveFilterMenu] = useState<string | null>(null);
  const [activeMetrics, setActiveMetrics] = useState({ amount: true, quantity: true });
  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  const toggleSection = (section: keyof typeof sections) => {
    setSections(prev => ({ ...prev, [section]: !prev[section] }));
  };

  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : (selectedCustomer ? 'customer' : null));
    const value = selectedCategory || selectedItem || selectedCustomer;

    if (!dimension || !value) return {
      baseRecords: [], totalSales: 0, totalQty: 0, secondaryDistribution: [], monthlyTrend: [], filterOptions: { id: [], customer: [], salesperson: [], itemName: [] }, tableRecords: [], contextTitle: ''
    };

    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);
    const totalSales = baseRecords.reduce((s, r) => s + r.totalAmount, 0);
    const totalQty = baseRecords.reduce((s, r) => s + r.quantity, 0);

    const secondaryDim = selectedCustomer ? 'category' : 'customer';
    const distMap = new Map<string, { sales: number; qty: number }>();
    baseRecords.forEach(r => {
      const key = r[secondaryDim] as string;
      const e = distMap.get(key) || { sales: 0, qty: 0 };
      distMap.set(key, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });
    const secondaryDistribution = Array.from(distMap.entries())
      .map(([name, v]) => ({ name, sales: v.sales, qty: v.qty }))
      .sort((a, b) => drillMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    let finalRecords = baseRecords;
    if (localTableFilters.customer && !selectedCustomer) {
      finalRecords = finalRecords.filter(r => r.customer === localTableFilters.customer);
    }
    if (localTableFilters.category && selectedCustomer) {
      finalRecords = finalRecords.filter(r => r.category === localTableFilters.category);
    }

    Object.entries(columnFilters).forEach(([field, selectedValues]) => {
      if (selectedValues.length > 0) {
        finalRecords = finalRecords.filter(r => selectedValues.includes(r[field as keyof SalesRecord] as string));
      }
    });

    const filterOptions = {
      id: Array.from(new Set(baseRecords.map(r => r.id))).sort(),
      customer: Array.from(new Set(baseRecords.map(r => r.customer))).sort(),
      salesperson: Array.from(new Set(baseRecords.map(r => r.salesperson))).sort(),
      itemName: Array.from(new Set(baseRecords.map(r => r.itemName))).sort()
    };

    const monthlyMap = new Map<string, { sales: number; qty: number }>();
    finalRecords.forEach(r => {
      const e = monthlyMap.get(r.month) || { sales: 0, qty: 0 };
      monthlyMap.set(r.month, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });
    const monthlyTrend = Array.from(monthlyMap.entries())
      .map(([name, v]) => ({ name, sales: v.sales, qty: v.qty }))
      .sort((a, b) => a.name.localeCompare(b.name));

    return {
      baseRecords, totalSales, totalQty, secondaryDistribution, monthlyTrend, filterOptions,
      tableRecords: finalRecords.sort((a, b) => b.date.localeCompare(a.date)),
      contextTitle: selectedCustomer ? '品类偏好' : '客户排行'
    };
  }, [selectedCategory, selectedItem, selectedCustomer, filteredData, localTableFilters, columnFilters, drillMetric]);

  const handleBarChartClick = (state: any) => {
    if (state && state.activeLabel) {
      const label = state.activeLabel;
      if (selectedCustomer) {
        setLocalTableFilters(prev => ({ ...prev, category: prev.category === label ? '' : label }));
      } else {
        setLocalTableFilters(prev => ({ ...prev, customer: prev.customer === label ? '' : label }));
      }
    }
  };

  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set(filteredData.map(d => d.month))).sort();
    const metrics = !activeMetrics.amount && !activeMetrics.quantity ? { amount: true, quantity: true } : activeMetrics;

    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return {
          name: month,
          amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0),
          quantity: monthRecords.reduce((s, r) => s + r.quantity, 0)
        };
      });
      const series: any[] = [];
      if (metrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (metrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }

    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set(filteredData.map(d => d[dimKey] as string))).slice(0, 8);

    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (metrics.amount) series.push({ key: `${entity}_amt`, name: `${entity}`, type: 'amount', color: baseColor });
      if (metrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数)`, type: 'quantity', color: baseColor, dashed: true });
    });

    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });

    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  const TableDropdownFilter = ({ field, label }: { field: string, label: string }) => {
    const options = (drillDownAnalysis.filterOptions as Record<string, string[]>)?.[field] || [];
    const selected = columnFilters[field] || [];
    const isActive = selected.length > 0;
    const menuRef = useRef<HTMLDivElement>(null);
    const [localSearch, setLocalSearch] = useState('');

    useEffect(() => {
      const handleClickOutside = (e: MouseEvent) => {
        if (menuRef.current && !menuRef.current.contains(e.target as Node)) setActiveFilterMenu(null);
      };
      if (activeFilterMenu === field) document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [activeFilterMenu, field]);

    const toggleValue = (val: string) => {
      const next = selected.includes(val) ? selected.filter(v => v !== val) : [...selected, val];
      setColumnFilters(prev => ({ ...prev, [field]: next }));
    };

    return (
      <div className="relative inline-block" ref={menuRef}>
        <button onClick={() => { setActiveFilterMenu(activeFilterMenu === field ? null : field); setLocalSearch(''); }} className={`flex items-center gap-2 px-2 py-1.5 rounded-lg transition-all ${isActive ? 'bg-indigo-50 text-indigo-700' : 'text-slate-400 hover:bg-slate-100'}`}>
          <span className="text-[10px] font-black uppercase tracking-widest">{label}</span>
          <svg className={`w-3 h-3 transition-transform ${activeFilterMenu === field ? 'rotate-180 text-indigo-500' : 'text-slate-300'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg>
        </button>
        {activeFilterMenu === field && (
          <div className="absolute top-full left-0 mt-2 w-64 bg-white border border-slate-200 shadow-2xl rounded-2xl z-[6000] overflow-hidden animate-in fade-in zoom-in-95 duration-150">
             <div className="p-3 bg-slate-50 border-b border-slate-100">
                <input type="text" placeholder={`检索...`} value={localSearch} onChange={(e) => setLocalSearch(e.target.value)} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-xl text-xs outline-none focus:ring-2 focus:ring-indigo-100" autoFocus />
             </div>
             <div className="max-h-64 overflow-y-auto p-1.5 custom-scrollbar bg-white">
                <button onClick={() => { setColumnFilters(prev => ({ ...prev, [field]: [] })); setActiveFilterMenu(null); }} className="w-full text-left px-3 py-2 text-[10px] font-black text-red-500 hover:bg-red-50 rounded-lg mb-1">重置</button>
                {options.filter(o => o.toLowerCase().includes(localSearch.toLowerCase())).map(opt => (
                    <button key={opt} onClick={() => toggleValue(opt)} className={`w-full text-left px-3 py-2 rounded-lg mb-0.5 flex items-center justify-between group ${selected.includes(opt) ? 'bg-indigo-600 text-white shadow-lg' : 'hover:bg-indigo-50 text-slate-700'}`}>
                      <span className="text-[11px] font-bold truncate">{opt}</span>
                      {selected.includes(opt) && <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7" /></svg>}
                    </button>
                ))}
             </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-10 pb-16 relative">
      {/* 核心指标 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col overflow-hidden h-[100px]">
           <div className="p-6 flex items-center justify-between h-full">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
                <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">单据总数</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div>
              </div>
              <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2 bg-slate-100 rounded-xl">
                <svg className={`w-5 h-5 transition-transform ${isOrdersExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
              </button>
           </div>
        </div>
      </div>

      {isOrdersExpanded && (
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm animate-in slide-in-from-top-2 duration-300">
           <input type="text" placeholder="检索单号..." value={orderSearchTerm} onChange={(e) => setOrderSearchTerm(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs outline-none focus:ring-2 focus:ring-indigo-100 mb-4" />
           <div className="max-h-40 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar">
              {summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase())).map(id => (<button key={id} onClick={() => onSelectOrderId(id)} className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-bold hover:border-indigo-500 transition-colors">{id}</button>))}
           </div>
        </div>
      )}

      {/* 趋势模块 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div onClick={() => toggleSection('trend')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3"><span className="p-2 bg-indigo-50 text-indigo-600 rounded-xl">📈</span> 业绩增长趋势</h3>
          <div className="flex items-center gap-6" onClick={e => e.stopPropagation()}>
             {sections.trend && (
               <div className="hidden lg:flex gap-4">
                 <div className="flex bg-slate-100 p-1 rounded-xl">
                   <button onClick={() => setActiveMetrics({ amount: true, quantity: false })} className={`px-4 py-1.5 rounded-lg text-xs font-black ${activeMetrics.amount && !activeMetrics.quantity ? 'bg-white shadow text-indigo-600' : 'text-slate-500'}`}>金额</button>
                   <button onClick={() => setActiveMetrics({ amount: false, quantity: true })} className={`px-4 py-1.5 rounded-lg text-xs font-black ${!activeMetrics.amount && activeMetrics.quantity ? 'bg-white shadow text-emerald-600' : 'text-slate-500'}`}>数量</button>
                   <button onClick={() => setActiveMetrics({ amount: true, quantity: true })} className={`px-4 py-1.5 rounded-lg text-xs font-black ${activeMetrics.amount && activeMetrics.quantity ? 'bg-white shadow text-slate-900' : 'text-slate-500'}`}>双轴</button>
                 </div>
                 <div className="flex bg-slate-100 p-1 rounded-xl">
                   <button onClick={() => setTrendMode('total')} className={`px-4 py-1.5 rounded-lg text-xs font-black ${trendMode === 'total' ? 'bg-white shadow' : 'text-slate-500'}`}>汇总</button>
                   <button onClick={() => setTrendMode('customer')} className={`px-4 py-1.5 rounded-lg text-xs font-black ${trendMode === 'customer' ? 'bg-white shadow text-indigo-600' : 'text-slate-500'}`}>客户</button>
                   <button onClick={() => setTrendMode('salesperson')} className={`px-4 py-1.5 rounded-lg text-xs font-black ${trendMode === 'salesperson' ? 'bg-white shadow text-emerald-600' : 'text-slate-500'}`}>销售</button>
                 </div>
               </div>
             )}
             <button className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform duration-300 ${sections.trend ? 'rotate-180 text-indigo-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
          </div>
        </div>
        {sections.trend && (
          <div className="px-8 pb-8 animate-in fade-in duration-500 h-[450px]">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendAnalysis.data}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11}} />
                {activeMetrics.amount && <YAxis yAxisId="amount" axisLine={false} tickLine={false} tick={{fill: '#6366f1', fontSize: 10, fontWeight: 700}} tickFormatter={v => `${(v/1000000).toFixed(1)}M`} />}
                {activeMetrics.quantity && <YAxis yAxisId="quantity" orientation="right" axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 10, fontWeight: 700}} />}
                <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} />
                <Legend iconType="circle" />
                {trendAnalysis.series.map(s => <Area key={s.key} yAxisId={s.type} type="monotone" dataKey={s.key} name={s.name} stroke={s.color} fill={s.color} fillOpacity={0.08} strokeDasharray={s.dashed ? "5 5" : "0"} strokeWidth={3} />)}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        )}
      </section>

      {/* 构成分析 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div onClick={() => toggleSection('composition')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3"><span className="p-2 bg-emerald-50 text-emerald-600 rounded-xl">🧩</span> 业务构成分析</h3>
          <button className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform duration-300 ${sections.composition ? 'rotate-180 text-emerald-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
        </div>
        {sections.composition && (
          <div className="grid lg:grid-cols-2 gap-10 p-10 pt-0 animate-in fade-in duration-500">
             <div className="flex flex-col items-center">
                <div className="flex justify-between w-full mb-6 items-start">
                   <div className="flex flex-col"><span className="text-xs font-black text-slate-400 uppercase">按品类</span><span className="text-lg font-black text-slate-800">业务分布</span></div>
                   <div className="flex bg-slate-100 p-1 rounded-xl">
                      <button onClick={() => setPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-[10px] font-black ${pieMetric === 'sales' ? 'bg-white shadow text-indigo-600' : 'text-slate-500'}`}>金额</button>
                      <button onClick={() => setPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-[10px] font-black ${pieMetric === 'quantity' ? 'bg-white shadow text-emerald-600' : 'text-slate-500'}`}>数量</button>
                   </div>
                </div>
                <div className="h-[400px] w-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie data={summary.categoryDistribution} cx="50%" cy="50%" innerRadius={80} outerRadius={120} paddingAngle={4} dataKey={pieMetric === 'sales' ? 'value' : 'value'} stroke="#fff" strokeWidth={4} onClick={d => setSelectedCategory(d.name)}>
                        {summary.categoryDistribution.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} className="cursor-pointer" />)}
                      </Pie>
                      <Tooltip />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
             </div>
             <div className="flex flex-col items-center">
                <div className="flex justify-between w-full mb-6 items-start">
                   <div className="flex flex-col"><span className="text-xs font-black text-slate-400 uppercase">按物料</span><span className="text-lg font-black text-slate-800">核心分布 (TOP15)</span></div>
                   <div className="flex bg-slate-100 p-1 rounded-xl">
                      <button onClick={() => setItemPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-[10px] font-black ${itemPieMetric === 'sales' ? 'bg-white shadow text-indigo-600' : 'text-slate-500'}`}>金额</button>
                      <button onClick={() => setItemPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-[10px] font-black ${itemPieMetric === 'quantity' ? 'bg-white shadow text-emerald-600' : 'text-slate-500'}`}>数量</button>
                   </div>
                </div>
                <div className="h-[400px] w-full">
