/**
 * 极简且鲁棒的日期标准化函数
 * 强制将各种输入（如 2024/1/1, 1/1/2024, Date(2024,0,1)）统一转化为 YYYY-MM-DD 格式
 */
const formatDateString = (dateStr: string): string => {
  if (!dateStr) return '';
  let s = dateStr.replace(/^"|"$/g, '').trim();

  // 1. 处理 Google Gviz 特有的 Date(2024,0,1) 格式 (注意：该格式下月份是从0开始的)
  if (s.startsWith('Date(')) {
    const match = s.match(/Date\((\d+),(\d+),(\d+)(?:,\d+,\d+,\d+)?\)/);
    if (match) {
      const y = match[1];
      const m = String(parseInt(match[2], 10) + 1).padStart(2, '0');
      const d = match[3].padStart(2, '0');
      return `${y}-${m}-${d}`;
    }
  }

  // 2. 尝试常见的分隔符解析 (YYYY-MM-DD 或 YYYY/MM/DD)
  const parts = s.split(/[\/\-\s.]/).filter(Boolean);
  if (parts.length >= 3) {
    let y = '', m = '', d = '';
    // 寻找 4 位数的年份
    const yearIdx = parts.findIndex(p => p.length === 4);
    if (yearIdx === 0) {
      // YYYY MM DD
      y = parts[0];
      m = parts[1].padStart(2, '0');
      d = parts[2].padStart(2, '0');
    } else if (yearIdx === 2) {
      // DD MM YYYY 或 MM DD YYYY
      y = parts[2];
      const p0 = parseInt(parts[0], 10);
      const p1 = parseInt(parts[1], 10);
      // 简单逻辑：如果第一个数 > 12，则必定是 DD
      if (p0 > 12) {
        d = String(p0).padStart(2, '0');
        m = String(p1).padStart(2, '0');
      } else {
        // 否则默认为 MM DD YYYY (常见于美式格式)
        m = String(p0).padStart(2, '0');
        d = String(p1).padStart(2, '0');
      }
    }

    if (y && m && d) return `${y}-${m}-${d}`;
  }

  // 3. 兜底解析
  try {
    const date = new Date(s.replace(/\//g, '-'));
    if (!isNaN(date.getTime())) {
      const y = date.getFullYear();
      const m = String(date.getMonth() + 1).padStart(2, '0');
      const d = String(date.getDate()).padStart(2, '0');
      return `${y}-${m}-${d}`;
    }
  } catch (e) {}

  return s;
};

/**
 * 解析 CSV 文本
 */
export const processCsvText = (csvText: string): SalesRecord[] => {
  const rows = csvText.split(/\r?\n/).filter(line => line.trim() !== '');
  if (rows.length < 2) return [];

  const parsedRows = rows.map(line => {
    const result: string[] = [];
    let currentField = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') inQuotes = !inQuotes;
      else if (char === ',' && !inQuotes) {
        result.push(currentField.replace(/^"|"$/g, '').trim());
        currentField = '';
      } else currentField += char;
    }
    result.push(currentField.replace(/^"|"$/g, '').trim());
    return result;
  });

  const dataRows = parsedRows.slice(1);
  return dataRows.map((cols, index) => {
    const rawDate = cols[2] || '';
    const standardizedDate = formatDateString(rawDate);

    // 自动补齐月份（如果月份列缺失，则从标准化日期截取 YYYY-MM）
    let monthStr = cols[1] || '';
    if (!monthStr && standardizedDate.includes('-')) {
      monthStr = standardizedDate.substring(0, 7);
    }

    return {
      id: cols[0] || `ID-${index}`,
      month: monthStr,
      date: standardizedDate,
      customer: cols[3] || '',
      salesperson: cols[4] || '',
      category: cols[5] || '',
      itemName: cols[6] || '',
      quantity: parseFloat(cols[7]?.replace(/,/g, '')) || 0,
      unitPrice: parseFloat(cols[8]?.replace(/,/g, '')) || 0,
      totalAmount: parseFloat(cols[9]?.replace(/,/g, '')) || 0
    };
  });
};

export const fetchSalesData = async (): Promise<SalesRecord[]> => {
  try {
    const response = await fetch(`${CSV_URL}&t=${Date.now()}`);
    if (!response.ok) {
        throw new Error('表格连接受阻，请检查共享权限。');
    }
    const csvText = await response.text();
    if (csvText.includes('<!DOCTYPE html>')) {
        throw new Error('权限验证失败，请确保表格已“发布到网络”并公开。');
    }
    return processCsvText(csvText);
  } catch (error) {
    console.error('Fetch Error:', error);
    throw error;
  }
};

