                      <Pie data={summary.categoryQuantityDistribution.slice(0, 15)} cx="50%" cy="50%" innerRadius={80} outerRadius={120} paddingAngle={2} dataKey="value" stroke="#fff" strokeWidth={4} onClick={d => setSelectedItem(d.name)}>
