      {/* 客户排行模块 - 可折叠 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div onClick={() => toggleSection('ranking')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3"><span className="p-2 bg-amber-50 text-amber-600 rounded-xl">👥</span> 客户采购排行</h3>
          <button className="p-2 bg-slate-100 rounded-xl hover:bg-slate-200 transition-all"><svg className={`w-5 h-5 transition-transform duration-300 ${sections.ranking ? 'rotate-180 text-amber-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
        </div>
        {sections.ranking && (
          <div className="px-8 pb-10 animate-in fade-in duration-500">
             <div className="flex bg-slate-100 p-1 rounded-xl w-fit mb-6 ml-auto">
                <button onClick={() => setCustomerMetric('sales')} className={`px-6 py-1.5 rounded-lg text-xs font-black ${customerMetric === 'sales' ? 'bg-white shadow text-indigo-600' : 'text-slate-500'}`}>按金额</button>
                <button onClick={() => setCustomerMetric('quantity')} className={`px-6 py-1.5 rounded-lg text-xs font-black ${customerMetric === 'quantity' ? 'bg-white shadow text-emerald-600' : 'text-slate-500'}`}>按数量</button>
             </div>
             <div className="w-full" style={{ height: `${Math.max(400, (summary.categoryDistribution.length > 20 ? 20 : summary.categoryDistribution.length) * 40)}px` }}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={summary.categoryDistribution.slice(0, 20)} layout="vertical" margin={{ left: 20, right: 60 }}>
                    <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#e2e8f0" />
                    <XAxis type="number" hide />
                    <YAxis type="category" dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#64748b', fontWeight: 700 }} />
                    <Tooltip cursor={{ fill: '#f1f5f9' }} />
                    <Bar dataKey="value" radius={[0, 10, 10, 0]} barSize={25} onClick={d => setSelectedCustomer(d.name)} cursor="pointer">
                      {summary.categoryDistribution.slice(0, 20).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                      <LabelList dataKey="value" position="right" style={{ fontSize: 10, fontWeight: 900, fill: '#64748b' }} formatter={(v: number) => v > 1000000 ? `${(v/1000000).toFixed(1)}M` : v.toLocaleString()} />
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
             </div>
          </div>
        )}
      </section>

      {/* 深度穿透分析面板 */}
      {(selectedCategory || selectedItem || selectedCustomer) && (
        <div className="fixed inset-0 bg-white z-[5000] flex flex-col animate-in slide-in-from-bottom-10 duration-500 overflow-hidden">
           <div className="px-10 py-6 border-b border-slate-200 bg-white flex items-center justify-between shadow-sm z-10">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-xl">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                </div>
                <div>
                  <h3 className="text-2xl font-black text-slate-900 tracking-tight flex items-center gap-3">
                    {selectedCategory || selectedItem || selectedCustomer} <span className="text-indigo-600 font-bold">穿透分析</span>
                  </h3>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-0.5 italic">
                    维度: {selectedCategory ? '品类' : selectedItem ? '物料' : '客户'} · 实时联动监测
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-6">
                 <div className="flex bg-slate-100 p-1 rounded-xl">
                   <button onClick={() => setDrillMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-black ${drillMetric === 'sales' ? 'bg-white shadow text-indigo-600' : 'text-slate-500'}`}>金额</button>
                   <button onClick={() => setDrillMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-black ${drillMetric === 'quantity' ? 'bg-white shadow text-emerald-600' : 'text-slate-500'}`}>数量</button>
                 </div>
                 <button onClick={() => { setSelectedCategory(null); setSelectedItem(null); setSelectedCustomer(null); setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] }); }} className="px-8 py-3 bg-slate-900 text-white rounded-2xl text-xs font-black hover:bg-slate-800 transition-all shadow-lg">关闭面板</button>
              </div>
           </div>

           <div className="flex-1 overflow-y-auto p-10 bg-slate-50/30 space-y-10 custom-scrollbar">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                 <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm"><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">该维度累计金额 (CFA)</p><p className="text-3xl font-black text-indigo-600">{drillDownAnalysis.totalSales.toLocaleString()}</p></div>
                 <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm"><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">该维度累计数量</p><p className="text-3xl font-black text-emerald-600">{drillDownAnalysis.totalQty.toLocaleString()}</p></div>
                 <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm"><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">关联业务行数</p><p className="text-3xl font-black text-slate-900">{drillDownAnalysis.baseRecords.length} <span className="text-sm font-bold text-slate-400">Lines</span></p></div>
              </div>

              <div className="bg-white rounded-3xl border border-slate-200 shadow-xl overflow-hidden">
                 <div className="px-8 py-5 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">关联穿透明细表</span>
                    <span className="text-xs font-black text-slate-400">已匹配: {drillDownAnalysis.tableRecords.length} 条</span>
                 </div>
                 <div className="overflow-x-auto max-h-[600px] custom-scrollbar">
                    <table className="min-w-full divide-y divide-slate-100">
                       <thead className="bg-white sticky top-0 z-[500] shadow-sm">
                          <tr>
                            <th className="px-8 py-4"><TableDropdownFilter field="id" label="单号" /></th>
                            <th className="px-8 py-4 text-left text-[11px] font-black text-slate-400 uppercase tracking-wider">业务日期</th>
                            <th className="px-8 py-4"><TableDropdownFilter field="customer" label="客户" /></th>
                            <th className="px-8 py-4"><TableDropdownFilter field="salesperson" label="销售员" /></th>
                            <th className="px-8 py-4"><TableDropdownFilter field="itemName" label="物料详情" /></th>
                            <th className="px-8 py-4 text-right text-[11px] font-black text-slate-400 uppercase tracking-wider">价税合计(CFA)</th>
                          </tr>
                       </thead>
                       <tbody className="bg-white divide-y divide-slate-50">
                          {drillDownAnalysis.tableRecords.map((r, i) => (
                            <tr key={i} className="hover:bg-slate-50/80 transition-colors">
                               <td className="px-8 py-4 font-mono font-bold text-indigo-600 text-xs"><button onClick={() => onSelectOrderId(r.id)} className="hover:underline">{r.id}</button></td>
                               <td className="px-8 py-4 text-slate-500 text-xs font-bold">{r.date}</td>
                               <td className="px-8 py-4 text-slate-900 text-xs font-black">{r.customer}</td>
                               <td className="px-8 py-4 text-slate-500 text-xs font-bold">{r.salesperson}</td>
                               <td className="px-8 py-4 text-slate-700 text-xs font-black truncate max-w-[200px]">{r.itemName}</td>
                               <td className="px-8 py-4 text-right font-mono font-black text-slate-900 text-xs">{r.totalAmount.toLocaleString()}</td>
                            </tr>
                          ))}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7', '#fb7185', '#2dd4bf', '#fbbf24'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  // 版块折叠状态：已拆分为四个独立模块
  const [sections, setSections] = useState({
    trend: true,
    categoryComposition: true,
    itemComposition: true,
    ranking: true
  });

  // 状态变量
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [customerMetric, setCustomerMetric] = useState<'sales' | 'quantity'>('sales');
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');

  // 深度分析状态
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<string | null>(null);
  const [drillMetric, setDrillMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [localTableFilters, setLocalTableFilters] = useState({ customer: '', category: '' });
  const [columnFilters, setColumnFilters] = useState<Record<string, string[]>>({
    id: [], customer: [], salesperson: [], itemName: []
  });

  const [activeFilterMenu, setActiveFilterMenu] = useState<string | null>(null);
  const [activeMetrics, setActiveMetrics] = useState({ amount: true, quantity: true });
  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  const toggleSection = (section: keyof typeof sections) => {
    setSections(prev => ({ ...prev, [section]: !prev[section] }));
  };

  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : (selectedCustomer ? 'customer' : null));
    const value = selectedCategory || selectedItem || selectedCustomer;

    if (!dimension || !value) return {
      baseRecords: [], totalSales: 0, totalQty: 0, secondaryDistribution: [], monthlyTrend: [], filterOptions: { id: [], customer: [], salesperson: [], itemName: [] }, tableRecords: [], contextTitle: ''
    };

    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);
    const totalSales = baseRecords.reduce((s, r) => s + r.totalAmount, 0);
    const totalQty = baseRecords.reduce((s, r) => s + r.quantity, 0);

    const secondaryDim = selectedCustomer ? 'category' : 'customer';
    const distMap = new Map<string, { sales: number; qty: number }>();
    baseRecords.forEach(r => {
      const key = r[secondaryDim] as string;
      const e = distMap.get(key) || { sales: 0, qty: 0 };
      distMap.set(key, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });
    const secondaryDistribution = Array.from(distMap.entries())
      .map(([name, v]) => ({ name, sales: v.sales, qty: v.qty }))
      .sort((a, b) => drillMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    let finalRecords = baseRecords;
    if (localTableFilters.customer && !selectedCustomer) finalRecords = finalRecords.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.category && selectedCustomer) finalRecords = finalRecords.filter(r => r.category === localTableFilters.category);

    (Object.entries(columnFilters) as [string, string[]][]).forEach(([field, selectedValues]) => {
      if (selectedValues.length > 0) {
        finalRecords = finalRecords.filter(r => selectedValues.includes(r[field as keyof SalesRecord] as string));
      }
    });

    const filterOptions = {
      id: Array.from(new Set(baseRecords.map(r => r.id))).sort(),
      customer: Array.from(new Set(baseRecords.map(r => r.customer))).sort(),
      salesperson: Array.from(new Set(baseRecords.map(r => r.salesperson))).sort(),
      itemName: Array.from(new Set(baseRecords.map(r => r.itemName))).sort()
    };

    const monthlyMap = new Map<string, { sales: number; qty: number }>();
    finalRecords.forEach(r => {
      const e = monthlyMap.get(r.month) || { sales: 0, qty: 0 };
      monthlyMap.set(r.month, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });
    const monthlyTrend = Array.from(monthlyMap.entries())
      .map(([name, v]) => ({ name, sales: v.sales, qty: v.qty }))
      .sort((a, b) => a.name.localeCompare(b.name));

    return {
      baseRecords, totalSales, totalQty, secondaryDistribution, monthlyTrend, filterOptions,
      tableRecords: finalRecords.sort((a, b) => b.date.localeCompare(a.date)),
      contextTitle: selectedCustomer ? '品类偏好' : '关联客群'
    };
  }, [selectedCategory, selectedItem, selectedCustomer, filteredData, localTableFilters, columnFilters, drillMetric]);

  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set(filteredData.map(d => d.month))).sort();
    const metrics = !activeMetrics.amount && !activeMetrics.quantity ? { amount: true, quantity: true } : activeMetrics;

    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return {
          name: month,
          amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0),
          quantity: monthRecords.reduce((s, r) => s + r.quantity, 0)
        };
      });
      const series: any[] = [];
      if (metrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (metrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }

    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set(filteredData.map(d => d[dimKey] as string))).slice(0, 8);

    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (metrics.amount) series.push({ key: `${entity}_amt`, name: `${entity}`, type: 'amount', color: baseColor });
      if (metrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数)`, type: 'quantity', color: baseColor, dashed: true });
    });

    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });

    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  const TableDropdownFilter = ({ field, label }: { field: string, label: string }) => {
    const options = (drillDownAnalysis.filterOptions as Record<string, string[]>)?.[field] || [];
    const selected = columnFilters[field] || [];
    const isActive = selected.length > 0;
    const menuRef = useRef<HTMLDivElement>(null);
    const [localSearch, setLocalSearch] = useState('');

    useEffect(() => {
      const handleClickOutside = (e: MouseEvent) => {
        if (menuRef.current && !menuRef.current.contains(e.target as Node)) setActiveFilterMenu(null);
      };
      if (activeFilterMenu === field) document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [activeFilterMenu, field]);

    return (
      <div className="relative inline-block" ref={menuRef}>
        <button onClick={() => { setActiveFilterMenu(activeFilterMenu === field ? null : field); setLocalSearch(''); }} className={`flex items-center gap-2 px-2 py-1.5 rounded-lg transition-all ${isActive ? 'bg-indigo-50 text-indigo-700' : 'text-slate-400 hover:bg-slate-100'}`}>
          <span className="text-[10px] font-black uppercase tracking-widest">{label}</span>
          <svg className={`w-3 h-3 transition-transform ${activeFilterMenu === field ? 'rotate-180 text-indigo-500' : 'text-slate-300'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg>
        </button>
        {activeFilterMenu === field && (
          <div className="absolute top-full left-0 mt-2 w-64 bg-white border border-slate-200 shadow-2xl rounded-2xl z-[6000] overflow-hidden animate-in fade-in zoom-in-95 duration-150">
             <div className="p-3 bg-slate-50 border-b border-slate-100">
