  };

  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : (selectedCustomer ? 'customer' : null));
    const value = selectedCategory || selectedItem || selectedCustomer;

    if (!dimension || !value) return {
      baseRecords: [], totalSales: 0, totalQty: 0, secondaryDistribution: [], monthlyTrend: [], filterOptions: { id: [], customer: [], salesperson: [], itemName: [] }, tableRecords: [], contextTitle: ''
    };

    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);
    const totalSales = baseRecords.reduce((s, r) => s + r.totalAmount, 0);
    const totalQty = baseRecords.reduce((s, r) => s + r.quantity, 0);

    const secondaryDim = selectedCustomer ? 'category' : 'customer';
    const distMap = new Map<string, { sales: number; qty: number }>();
    baseRecords.forEach(r => {
      const key = r[secondaryDim] as string;
      const e = distMap.get(key) || { sales: 0, qty: 0 };
      distMap.set(key, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });

    let finalRecords = baseRecords;
    (Object.entries(columnFilters) as [string, string[]][]).forEach(([field, selectedValues]) => {
      if (selectedValues.length > 0) {
        finalRecords = finalRecords.filter(r => selectedValues.includes(String(r[field as keyof SalesRecord])));
      }
    });

    const filterOptions = {
      id: Array.from(new Set(baseRecords.map(r => r.id))).sort(),
