import React, { useState, useMemo, useEffect } from 'react';
import { FilterState, SalesSummary, SalesRecord } from './types';
import Dashboard from './components/Dashboard';
import DataTable from './components/DataTable';
import MultiSelect from './components/MultiSelect';
import OrderDetailModal from './components/OrderDetailModal';
import { fetchSalesData } from './services/dataService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'table'>('dashboard');
  const [cloudData, setCloudData] = useState<SalesRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedOrderId, setSelectedOrderId] = useState<string | null>(null);

  const [filters, setFilters] = useState<FilterState>({
    months: [],
    dateRange: ['', ''],
    customers: [],
    salespeople: [],
    categories: [],
    itemNames: []
  });

  const loadCloudData = async () => {
    try {
      setIsLoading(true);
      setError(null);
      const data = await fetchSalesData();
      setCloudData(data);
      initializeFilters();
    } catch (err) {
      const message = err instanceof Error ? err.message : '连接数据源失败';
      setError(message);
    } finally {
      setIsLoading(false);
    }
  };

  const initializeFilters = () => {
    setFilters({
      months: [],
      dateRange: ['', ''],
      customers: [],
      salespeople: [],
      categories: [],
      itemNames: []
    });
  };

  useEffect(() => {
    loadCloudData();
  }, []);

  const getCascadingDimensionData = (dimension: keyof SalesRecord) => {
    const filteredByOthers = cloudData.filter(item => {
      const matchMonth = dimension === 'month' || filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = dimension === 'salesperson' || filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = dimension === 'category' || filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = dimension === 'customer' || filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = dimension === 'itemName' || filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (
        (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
        (!filters.dateRange[1] || item.date <= filters.dateRange[1])
      );
      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });

    const counts: Record<string, number> = {};
    filteredByOthers.forEach(item => {
      const val = String(item[dimension]);
      if (val) counts[val] = (counts[val] || 0) + 1;
    });

    const options = Array.from(new Set(filteredByOthers.map(d => String(d[dimension])))).sort();
    if (dimension === 'month') options.reverse();

    return { options, counts };
  };

  const dynamicFilterData = useMemo(() => ({
    months: getCascadingDimensionData('month'),
    customers: getCascadingDimensionData('customer'),
    salespeople: getCascadingDimensionData('salesperson'),
    categories: getCascadingDimensionData('category'),
    itemNames: getCascadingDimensionData('itemName')
  }), [cloudData, filters]);

  const filteredData = useMemo(() => {
    return cloudData.filter(item => {
      const matchMonth = filters.months.length === 0 || filters.months.includes(item.month);
      const matchSalesperson = filters.salespeople.length === 0 || filters.salespeople.includes(item.salesperson);
      const matchCategory = filters.categories.length === 0 || filters.categories.includes(item.category);
      const matchCustomer = filters.customers.length === 0 || filters.customers.includes(item.customer);
      const matchItemName = filters.itemNames.length === 0 || filters.itemNames.includes(item.itemName);
      const matchDate = (!filters.dateRange[0] || item.date >= filters.dateRange[0]) &&
                        (!filters.dateRange[1] || item.date <= filters.dateRange[1]);
      return matchMonth && matchSalesperson && matchCategory && matchCustomer && matchItemName && matchDate;
    });
  }, [cloudData, filters]);

  const summary: SalesSummary = useMemo(() => {
    const totalSales = filteredData.reduce((acc, cur) => acc + cur.totalAmount, 0);
    const totalQuantity = filteredData.reduce((acc, cur) => acc + cur.quantity, 0);
    const uniqueOrderIds = Array.from(new Set(filteredData.map(d => d.id))).sort();

    const monthlyMap = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const existing = monthlyMap.get(d.month) || { sales: 0, quantity: 0 };
      monthlyMap.set(d.month, {
        sales: existing.sales + d.totalAmount,
        quantity: existing.quantity + d.quantity
      });
    });
    const monthlyTrend = Array.from(monthlyMap.entries()).map(([name, val]) => ({ name, ...val })).sort((a, b) => a.name.localeCompare(b.name));

    const catMap = new Map<string, number>();
    const catQtyMap = new Map<string, number>();
    filteredData.forEach(d => {
      catMap.set(d.category, (catMap.get(d.category) || 0) + d.totalAmount);
      catQtyMap.set(d.category, (catQtyMap.get(d.category) || 0) + d.quantity);
    });

    return { 
      totalSales, 
      totalQuantity, 
      orderCount: uniqueOrderIds.length, 
      orderIds: uniqueOrderIds, 
      categoryDistribution: Array.from(catMap.entries()).map(([name, value]) => ({ name, value })),
      categoryQuantityDistribution: Array.from(catQtyMap.entries()).map(([name, value]) => ({ name, value })),
      monthlyTrend 
    };
  }, [filteredData]);

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 p-4">
        <div className="bg-white p-8 rounded-3xl shadow-xl max-w-md border border-red-100 text-center">
          <div className="text-5xl mb-4">⚠️</div>
          <h2 className="text-xl font-bold text-slate-900 mb-2">服务暂时不可用</h2>
          <p className="text-slate-500 text-sm mb-6">{error}</p>
          <button onClick={loadCloudData} className="w-full bg-indigo-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-indigo-700 transition-all">尝试重新连接</button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 pb-12">
      <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-[1000]">
        <div className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-2xl font-black shadow-lg shadow-indigo-100">S</div>
            <h1 className="text-lg font-black text-slate-900">TTP 销售数据分析</h1>
          </div>
          <nav className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setActiveTab('dashboard')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'dashboard' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-900'}`}>分析中心</button>
            <button onClick={() => setActiveTab('table')} className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'table' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-900'}`}>数据清单</button>
          </nav>
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 pt-8">
        {/* 筛选中心：不再折叠，且 overflow-visible 确保下拉内容在外部可选 */}
        <section className="bg-white rounded-2xl shadow-sm border border-slate-200 mb-8 overflow-visible relative">
          <div className="p-6 flex items-center justify-between border-b border-slate-100">
            <div className="flex items-center gap-4">
              <h2 className="text-sm font-black text-slate-800 uppercase tracking-[0.2em] flex items-center gap-2">
                <span className="w-1.5 h-4 rounded-full bg-indigo-600"></span> 筛选中心
              </h2>
              <div className="hidden sm:flex items-center gap-2 text-[10px] font-black text-indigo-600 uppercase tracking-widest bg-indigo-50 px-3 py-1 rounded-full">
                当前匹配: {filteredData.length} 行记录
              </div>
            </div>
            <div className="flex items-center gap-4 text-xs font-bold">
               <button onClick={initializeFilters} className="text-slate-400 hover:text-red-500 transition-colors uppercase tracking-widest">重置所有条件</button>
            </div>
          </div>

          <div className="p-6">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-6 pt-2">
              <MultiSelect label="月份" options={dynamicFilterData.months.options} counts={dynamicFilterData.months.counts} selectedValues={filters.months} onChange={(v) => setFilters({...filters, months: v})} />
              <MultiSelect label="客户" options={dynamicFilterData.customers.options} counts={dynamicFilterData.customers.counts} selectedValues={filters.customers} onChange={(v) => setFilters({...filters, customers: v})} />
              <MultiSelect label="销售员" options={dynamicFilterData.salespeople.options} counts={dynamicFilterData.salespeople.counts} selectedValues={filters.salespeople} onChange={(v) => setFilters({...filters, salespeople: v})} />
              <MultiSelect label="品类" options={dynamicFilterData.categories.options} counts={dynamicFilterData.categories.counts} selectedValues={filters.categories} onChange={(v) => setFilters({...filters, categories: v})} />
              <MultiSelect label="物料名称" options={dynamicFilterData.itemNames.options} counts={dynamicFilterData.itemNames.counts} selectedValues={filters.itemNames} onChange={(v) => setFilters({...filters, itemNames: v})} />
              <div className="space-y-1.5">
                <label className="block text-xs font-black text-slate-500 mb-1.5 uppercase tracking-wider">业务日期范围</label>
                <div className="flex items-center gap-1 bg-slate-50 border-2 border-slate-200 rounded-xl px-2 py-1.5 hover:bg-white hover:border-indigo-400 transition-all focus-within:ring-4 focus-within:ring-indigo-50 focus-within:border-indigo-600 h-[42px]">
                  <input type="date" value={filters.dateRange[0]} onChange={(e) => setFilters({...filters, dateRange: [e.target.value, filters.dateRange[1]]})} className="bg-transparent text-[10px] font-bold text-slate-600 outline-none w-full cursor-pointer" />
                  <span className="text-slate-300 font-bold">-</span>
                  <input type="date" value={filters.dateRange[1]} onChange={(e) => setFilters({...filters, dateRange: [filters.dateRange[0], e.target.value]})} className="bg-transparent text-[10px] font-bold text-slate-600 outline-none w-full cursor-pointer" />
                </div>
              </div>
            </div>
          </div>
        </section>

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-32 space-y-4">
            <div className="w-12 h-12 border-4 border-slate-200 border-t-indigo-600 rounded-full animate-spin"></div>
            <p className="text-slate-400 font-bold tracking-widest uppercase text-xs">正在刷新数据...</p>
          </div>
        ) : (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
            {filteredData.length > 0 ? (
              activeTab === 'dashboard' ? (
                <Dashboard summary={summary} filteredData={filteredData} onSelectOrderId={setSelectedOrderId} />
              ) : (
                <DataTable data={filteredData} onSelectOrderId={setSelectedOrderId} />
              )
            ) : (
              <div className="py-32 bg-white rounded-3xl border border-dashed border-slate-200 text-center">
                <div className="text-5xl mb-4">🔎</div>
                <h3 className="text-xl font-bold text-slate-800">未检索到数据</h3>
                <p className="text-slate-500 mt-2">级联筛选已自动排除了无结果组合，请尝试重置或调整条件</p>
                <button onClick={initializeFilters} className="mt-6 px-6 py-2 bg-indigo-600 text-white rounded-xl text-sm font-bold shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all">重置所有筛选</button>
              </div>
            )}
          </div>
        )}
      </main>

      {selectedOrderId && (
        <OrderDetailModal orderId={selectedOrderId} records={cloudData.filter(d => d.id === selectedOrderId)} onClose={() => setSelectedOrderId(null)} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7', '#fb7185', '#2dd4bf', '#fbbf24'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  // 版块折叠状态
  const [sections, setSections] = useState({
    trend: true,
    composition: true,
    ranking: true
  });

  // 全局展示状态
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [customerMetric, setCustomerMetric] = useState<'sales' | 'quantity'>('sales');
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');

  // 深度分析联动状态
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<string | null>(null);
  const [drillMetric, setDrillMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [localTableFilters, setLocalTableFilters] = useState({
    customer: '', 
    category: '',
    month: '' 
  });

  // 明细表内部表头多选筛选状态
  const [columnFilters, setColumnFilters] = useState<Record<string, string[]>>({
    id: [],
    customer: [],
    salesperson: [],
    itemName: []
  });

  const [activeFilterMenu, setActiveFilterMenu] = useState<string | null>(null);
  const [activeMetrics, setActiveMetrics] = useState({ amount: true, quantity: true });
  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  // 切换折叠
  const toggleSection = (key: keyof typeof sections) => {
    setSections(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- 响应式计算链 (双向联动逻辑) ---
  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : (selectedCustomer ? 'customer' : null));
    const value = selectedCategory || selectedItem || selectedCustomer;

    if (!dimension || !value) return {
      baseRecords: [], totalSales: 0, totalQty: 0, secondaryDistribution: [], monthlyTrend: [], filterOptions: { id: [], customer: [], salesperson: [], itemName: [] }, tableRecords: [], contextTitle: ''
    };

    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);
    const totalSales = baseRecords.reduce((s, r) => s + r.totalAmount, 0);
    const totalQty = baseRecords.reduce((s, r) => s + r.quantity, 0);

    // 计算次级排行分布 (受月份过滤影响)
    const recordsForDist = localTableFilters.month 
      ? baseRecords.filter(r => r.month === localTableFilters.month) 
      : baseRecords;

    const secondaryDim = selectedCustomer ? 'category' : 'customer';
    const distMap = new Map<string, { sales: number; qty: number }>();
    recordsForDist.forEach(r => {
      const key = r[secondaryDim] as string;
      const e = distMap.get(key) || { sales: 0, qty: 0 };
      distMap.set(key, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });
    const secondaryDistribution = Array.from(distMap.entries())
      .map(([name, v]) => ({ name, sales: v.sales, qty: v.qty }))
      .sort((a, b) => drillMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    // 计算月度趋势 (受排行维度过滤影响)
    let recordsForTrend = baseRecords;
    if (localTableFilters.customer && !selectedCustomer) recordsForTrend = recordsForTrend.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.category && selectedCustomer) recordsForTrend = recordsForTrend.filter(r => r.category === localTableFilters.category);

    const monthlyMap = new Map<string, { sales: number; qty: number }>();
    recordsForTrend.forEach(r => {
      const e = monthlyMap.get(r.month) || { sales: 0, qty: 0 };
      monthlyMap.set(r.month, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });
    const allMonths = Array.from(new Set<string>(baseRecords.map(r => r.month))).sort();
    const monthlyTrend = allMonths.map(m => {
      const v = monthlyMap.get(m) || { sales: 0, qty: 0 };
      return { name: m, sales: v.sales, qty: v.qty };
    });

    const getOptionsForField = (field: string) => {
      let subset = baseRecords;
      if (localTableFilters.month) subset = subset.filter(r => r.month === localTableFilters.month);
      if (localTableFilters.customer && !selectedCustomer) subset = subset.filter(r => r.customer === localTableFilters.customer);
      if (localTableFilters.category && selectedCustomer) subset = subset.filter(r => r.category === localTableFilters.category);

      Object.entries(columnFilters).forEach(([f, vals]) => {
        const castedVals = vals as string[];
        if (f !== field && castedVals.length > 0) {
          subset = subset.filter(r => castedVals.includes(String(r[f as keyof SalesRecord])));
        }
      });
      return Array.from(new Set<string>(subset.map(r => String(r[field as keyof SalesRecord])))).sort();
    };

    const filterOptions = {
      id: getOptionsForField('id'),
      customer: getOptionsForField('customer'),
      salesperson: getOptionsForField('salesperson'),
      itemName: getOptionsForField('itemName')
    };

    let finalRecords = baseRecords;
    if (localTableFilters.month) finalRecords = finalRecords.filter(r => r.month === localTableFilters.month);
    if (localTableFilters.customer && !selectedCustomer) finalRecords = finalRecords.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.category && selectedCustomer) finalRecords = finalRecords.filter(r => r.category === localTableFilters.category);

    Object.entries(columnFilters).forEach(([field, selectedValues]) => {
      const castedValues = selectedValues as string[];
      if (castedValues.length > 0) {
        finalRecords = finalRecords.filter(r => castedValues.includes(String(r[field as keyof SalesRecord])));
      }
    });

    return {
      baseRecords,
      totalSales,
      totalQty,
      secondaryDistribution,
      monthlyTrend,
      filterOptions,
      tableRecords: finalRecords.sort((a, b) => b.date.localeCompare(a.date)),
      contextTitle: selectedCustomer ? '品类贡献偏好' : '关联客户贡献排行'
    };
  }, [selectedCategory, selectedItem, selectedCustomer, filteredData, localTableFilters, columnFilters, drillMetric]);

  const handleBarChartClick = (state: any) => {
    if (state && state.activeLabel) {
      const label = state.activeLabel;
      if (selectedCustomer) {
        setLocalTableFilters(prev => ({ ...prev, category: prev.category === label ? '' : label }));
      } else {
        setLocalTableFilters(prev => ({ ...prev, customer: prev.customer === label ? '' : label }));
      }
    }
  };

  const handleTrendClick = (state: any) => {
    if (state && state.activeLabel) {
      const clickedMonth = state.activeLabel;
      setLocalTableFilters(prev => ({ ...prev, month: prev.month === clickedMonth ? '' : clickedMonth }));
    }
  };

  const openCategoryDrillDown = (name: string) => {
    setDrillMetric(pieMetric); 
    setSelectedCategory(name);
    setSelectedItem(null);
    setSelectedCustomer(null);
    setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] });
    setLocalTableFilters({ customer: '', category: '', month: '' });
  };

  const openItemDrillDown = (name: string) => {
    setDrillMetric(itemPieMetric); 
    setSelectedItem(name);
    setSelectedCategory(null);
    setSelectedCustomer(null);
    setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] });
    setLocalTableFilters({ customer: '', category: '', month: '' });
  };

  const openCustomerDrillDown = (name: string) => {
    setDrillMetric(customerMetric);
    setSelectedCustomer(name);
    setSelectedCategory(null);
    setSelectedItem(null);
    setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] });
    setLocalTableFilters({ customer: '', category: '', month: '' });
  };

  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set<string>(filteredData.map(d => d.month))).sort();
    const metrics = !activeMetrics.amount && !activeMetrics.quantity ? { amount: true, quantity: true } : activeMetrics;

    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return {
          name: month,
          amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0),
          quantity: monthRecords.reduce((s, r) => s + r.quantity, 0)
        };
      });
      const series: any[] = [];
      if (metrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (metrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }

    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set<string>(filteredData.map(d => String(d[dimKey])))).slice(0, 8);
    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (metrics.amount) series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor });
      if (metrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
    });

    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });
    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  const customerAnalysisData = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.customer) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.customer, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => customerMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, customerMetric]);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, itemPieMetric]);

  const formatMetricDisplay = (value: number, metric: 'sales' | 'quantity') => {
    if (metric === 'sales') return `${(value / 1000000).toFixed(2)}M CFA`;
    return `${value.toLocaleString()} UNIT`;
  };

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-RADIAN * midAngle);
    const cos = Math.cos(-RADIAN * midAngle);
    const sx = cx + (outerRadius + 5) * cos;
    const sy = cy + (outerRadius + 5) * sin;
    const mx = cx + (outerRadius + 25) * cos;
    const my = cy + (outerRadius + 25) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 22;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={2} opacity={0.6} />
        <circle cx={ex} cy={ey} r={3} fill={fill} />
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} textAnchor={textAnchor} fill="#0f172a" style={{ fontSize: '12px', fontWeight: 800 }}>{name}</text>
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} dy={14} textAnchor={textAnchor} fill="#64748b" style={{ fontSize: '11px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  const TableDropdownFilter = ({ field, label }: { field: string, label: string }) => {
    const options = (drillDownAnalysis.filterOptions as Record<string, string[]>)?.[field] || [];
    const selected = columnFilters[field] || [];
    const isActive = selected.length > 0;
    const menuRef = useRef<HTMLDivElement>(null);
    const [localSearch, setLocalSearch] = useState('');

    useEffect(() => {
      const handleClickOutside = (e: MouseEvent) => {
        if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
          setActiveFilterMenu(null);
        }
      };
      if (activeFilterMenu === field) {
        document.addEventListener('mousedown', handleClickOutside);
      }
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [activeFilterMenu, field]);

    const toggleValue = (val: string) => {
      const next = selected.includes(val) ? selected.filter(v => v !== val) : [...selected, val];
      setColumnFilters(prev => ({ ...prev, [field]: next }));
    };

    const filteredOptions = options.filter(opt => opt.toLowerCase().includes(localSearch.toLowerCase()));

    return (
      <div className="relative inline-block text-left" ref={menuRef}>
        <button 
          onClick={() => {
            setActiveFilterMenu(activeFilterMenu === field ? null : field);
            setLocalSearch('');
          }}
          className={`flex items-center gap-2 px-2 py-1.5 rounded-lg transition-all group ${isActive ? 'bg-indigo-50 text-indigo-700' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100'}`}
        >
          <span className={`text-[10px] font-black uppercase tracking-widest`}>{label}</span>
          <svg className={`w-3 h-3 transition-transform ${activeFilterMenu === field ? 'rotate-180 text-indigo-500' : 'text-slate-300'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
             <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" />
          </svg>
        </button>
        {activeFilterMenu === field && (
          <div className="absolute top-full left-0 mt-2 w-64 bg-white border border-slate-200 shadow-2xl rounded-2xl z-[6000] overflow-hidden animate-in fade-in zoom-in-95 duration-150 origin-top-left">
             <div className="p-3 bg-slate-50 border-b border-slate-100">
                <input 
                  type="text" autoFocus placeholder={`搜索...`} value={localSearch}
                  onChange={(e) => setLocalSearch(e.target.value)}
                  className="w-full px-3 py-2 bg-white border border-slate-200 rounded-xl text-xs outline-none focus:ring-2 focus:ring-indigo-100 font-bold"
                />
             </div>
             <div className="max-h-64 overflow-y-auto p-1.5 custom-scrollbar bg-white">
                <button onClick={() => { setColumnFilters(prev => ({ ...prev, [field]: [] })); setActiveFilterMenu(null); }} className="w-full text-left px-3 py-2.5 text-[10px] font-black text-red-500 hover:bg-red-50 rounded-xl mb-1">重置该列筛选</button>
                {filteredOptions.map(opt => {
                  const isSelected = selected.includes(opt);
                  return (
                    <button key={opt} onClick={() => toggleValue(opt)} className={`w-full text-left px-3 py-2.5 rounded-xl mb-0.5 flex items-center justify-between group ${isSelected ? 'bg-indigo-600 text-white shadow-lg' : 'hover:bg-indigo-50 text-slate-700'}`}>
                      <span className="text-[12px] font-bold truncate pr-2">{opt}</span>
                      {isSelected && <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7" /></svg>}
                    </button>
                  );
                })}
             </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-10 pb-16 relative">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col overflow-hidden">
           <div className="p-6 flex items-center justify-between bg-white border-b border-slate-100">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
                <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">单据总数</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div>
              </div>
              <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2 bg-slate-100 rounded-xl hover:bg-slate-200 transition-all">
                <svg className={`w-5 h-5 transition-transform ${isOrdersExpanded ? 'rotate-180 text-indigo-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
              </button>
           </div>
           {isOrdersExpanded && (
              <div className="px-5 py-5 bg-slate-50/50 border-t border-slate-100 space-y-4 animate-in fade-in slide-in-from-top-2 duration-300">
                <input type="text" placeholder="检索单号..." value={orderSearchTerm} onChange={(e) => setOrderSearchTerm(e.target.value)} className="w-full bg-white border border-slate-300 rounded-lg px-3 py-1.5 text-xs outline-none focus:border-indigo-500 font-bold" />
                <div className="max-h-40 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar pr-1">
                  {summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase())).map(id => (<button key={id} onClick={() => onSelectOrderId(id)} className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-bold hover:border-indigo-500 transition-colors">{id}</button>))}
                </div>
              </div>
           )}
        </div>
      </div>

      {/* 业绩趋势版块 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div 
          onClick={() => toggleSection('trend')}
          className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors"
        >
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 shrink-0">
            <span className="p-2 bg-indigo-50 text-indigo-600 rounded-xl text-lg">📈</span> 业绩增长趋势
          </h3>
          <div className="flex items-center gap-6" onClick={(e) => e.stopPropagation()}>
            {sections.trend && (
              <div className="hidden md:flex flex-wrap items-center gap-4">
                <div className="flex bg-slate-100 p-1 rounded-2xl border border-slate-200 shadow-inner">
                   <button onClick={() => setActiveMetrics({ amount: true, quantity: false })} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${activeMetrics.amount && !activeMetrics.quantity ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>金额</button>
                   <button onClick={() => setActiveMetrics({ amount: false, quantity: true })} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${!activeMetrics.amount && activeMetrics.quantity ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量</button>
                   <button onClick={() => setActiveMetrics({ amount: true, quantity: true })} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${activeMetrics.amount && activeMetrics.quantity ? 'bg-white shadow-md text-slate-900' : 'text-slate-500'}`}>双轴</button>
                </div>
                <div className="flex bg-slate-100 p-1 rounded-2xl border border-slate-200 shadow-inner">
                  <button onClick={() => setTrendMode('total')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'total' ? 'bg-white shadow-md text-slate-900' : 'text-slate-500'}`}>汇总</button>
                  <button onClick={() => setTrendMode('customer')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'customer' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>客户</button>
                  <button onClick={() => setTrendMode('salesperson')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'salesperson' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>销售</button>
                </div>
              </div>
            )}
            <button className="p-2 bg-slate-100 rounded-xl">
              <svg className={`w-5 h-5 transition-transform duration-300 ${sections.trend ? 'rotate-180 text-indigo-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
            </button>
          </div>
        </div>
        {sections.trend && (
          <div className="px-8 pb-8 animate-in fade-in duration-500">
            <div className="h-[450px] w-full mt-4">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={trendAnalysis.data}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11}} />
                  {activeMetrics.amount && <YAxis yAxisId="amount" axisLine={false} tickLine={false} tick={{fill: '#6366f1', fontSize: 10, fontWeight: 700}} tickFormatter={(v) => `${(v / 1000000).toFixed(1)}M`} />}
                  {activeMetrics.quantity && <YAxis yAxisId="quantity" orientation="right" axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 10, fontWeight: 700}} tickFormatter={(v) => v.toLocaleString()} />}
                  <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }} formatter={(value: any, name: string) => [value.toLocaleString(), name]} />
                  <Legend iconType="circle" />
                  {trendAnalysis.series.map((s, i) => (
                    <Area key={s.key} yAxisId={s.type} type="monotone" dataKey={s.key} name={s.name} stroke={s.color} strokeWidth={s.dashed ? 2 : 3} strokeDasharray={s.dashed ? "5 5" : "0"} fill={s.color} fillOpacity={s.dashed ? 0 : 0.08} activeDot={{ r: 6, strokeWidth: 0 }} />
                  ))}
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}
      </section>

      {/* 构成分析版块 - 优化为横向并列布局 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div 
          onClick={() => toggleSection('composition')}
          className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors"
        >
          <div className="flex flex-col gap-1">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 shrink-0">
              <span className="p-2 bg-emerald-50 text-emerald-600 rounded-xl text-lg">🧩</span> 业务构成分析
            </h3>
            {!sections.composition && (
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest pl-12">横向对比品类与物料明细构成</p>
            )}
          </div>
          <button className="p-2 bg-slate-100 rounded-xl">
            <svg className={`w-5 h-5 transition-transform duration-300 ${sections.composition ? 'rotate-180 text-emerald-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
          </button>
        </div>
        {sections.composition && (
          <div className="px-8 pb-10 animate-in fade-in duration-500">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-x-12 gap-y-16">
              {/* 品类分析 */}
              <div className="flex flex-col">
                <div className="flex justify-between items-start mb-6 px-2">
                  <div className="flex flex-col">
                    <h4 className="text-base font-black text-slate-800 tracking-tight">品类核心构成</h4>
                    <span className={`text-lg font-black mt-1 ${pieMetric === 'sales' ? 'text-indigo-600' : 'text-emerald-600'}`}>
                      {formatMetricDisplay(sortedCategorySummary.reduce((acc, curr) => acc + (pieMetric === 'sales' ? curr.sales : curr.quantity), 0), pieMetric)}
                    </span>
                  </div>
                  <div className="flex bg-slate-100 p-1 rounded-xl shadow-inner scale-90 origin-right">
                    <button onClick={(e) => { e.stopPropagation(); setPieMetric('sales'); }} className={`px-3 py-1.5 rounded-lg text-[10px] font-black transition-all ${pieMetric === 'sales' ? 'bg-white shadow-sm text-indigo-700' : 'text-slate-500'}`}>金额</button>
                    <button onClick={(e) => { e.stopPropagation(); setPieMetric('quantity'); }} className={`px-3 py-1.5 rounded-lg text-[10px] font-black transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-500'}`}>数量</button>
                  </div>
                </div>
                <div className="h-[480px] w-full relative">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie data={sortedCategorySummary} cx="50%" cy="50%" innerRadius={80} outerRadius={120} paddingAngle={4} dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} stroke="#fff" strokeWidth={4} label={renderCustomizedLabel} labelLine={false} onClick={(d) => openCategoryDrillDown(d.name)}>
                        {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} className="cursor-pointer hover:opacity-85 transition-opacity" />)}
                      </Pie>
                      <Tooltip formatter={(v: any) => v.toLocaleString()} />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              </div>

              {/* 物料分析 */}
              <div className="flex flex-col">
                <div className="flex justify-between items-start mb-6 px-2">
                  <div className="flex flex-col">
                    <h4 className="text-base font-black text-slate-800 tracking-tight">物料贡献排行 (TOP 15)</h4>
                    <span className={`text-lg font-black mt-1 ${itemPieMetric === 'sales' ? 'text-indigo-600' : 'text-emerald-600'}`}>
                      {formatMetricDisplay(sortedItemSummary.slice(0, 15).reduce((acc, curr) => acc + (itemPieMetric === 'sales' ? curr.sales : curr.quantity), 0), itemPieMetric)}
                    </span>
                  </div>
                  <div className="flex bg-slate-100 p-1 rounded-xl shadow-inner scale-90 origin-right">
                    <button onClick={(e) => { e.stopPropagation(); setItemPieMetric('sales'); }} className={`px-3 py-1.5 rounded-lg text-[10px] font-black transition-all ${itemPieMetric === 'sales' ? 'bg-white shadow-sm text-indigo-700' : 'text-slate-500'}`}>金额</button>
                    <button onClick={(e) => { e.stopPropagation(); setItemPieMetric('quantity'); }} className={`px-3 py-1.5 rounded-lg text-[10px] font-black transition-all ${itemPieMetric === 'quantity' ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-500'}`}>数量</button>
                  </div>
                </div>
                <div className="h-[480px] w-full relative">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie data={sortedItemSummary.slice(0, 15)} cx="50%" cy="50%" innerRadius={80} outerRadius={120} paddingAngle={2} dataKey={itemPieMetric === 'sales' ? 'sales' : 'quantity'} stroke="#fff" strokeWidth={4} label={renderCustomizedLabel} labelLine={false} onClick={(d) => openItemDrillDown(d.name)}>
                        {sortedItemSummary.slice(0, 15).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} className="cursor-pointer hover:opacity-85 transition-opacity" />)}
                      </Pie>
                      <Tooltip formatter={(v: any) => v.toLocaleString()} />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              </div>
            </div>
          </div>
        )}
      </section>

      {/* 客户排行版块 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div 
          onClick={() => toggleSection('ranking')}
          className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors"
        >
          <div className="flex flex-col gap-1">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 shrink-0">
              <span className="p-2 bg-amber-50 text-amber-600 rounded-xl text-lg">👥</span> 客户采购排行
            </h3>
            {!sections.ranking && (
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest pl-12">共分析 {customerAnalysisData.length} 家客户</p>
            )}
          </div>
          <div className="flex items-center gap-6" onClick={(e) => e.stopPropagation()}>
            {sections.ranking && (
              <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200">
                <button onClick={() => setCustomerMetric('sales')} className={`px-6 py-1.5 rounded-xl text-xs font-black transition-all ${customerMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>金额</button>
                <button onClick={() => setCustomerMetric('quantity')} className={`px-6 py-1.5 rounded-xl text-xs font-black transition-all ${customerMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量</button>
              </div>
            )}
            <button className="p-2 bg-slate-100 rounded-xl">
              <svg className={`w-5 h-5 transition-transform duration-300 ${sections.ranking ? 'rotate-180 text-amber-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
            </button>
          </div>
        </div>
        {sections.ranking && (
          <div className="px-8 pb-10 animate-in fade-in duration-500">
            <div className="w-full" style={{ height: `${Math.max(400, customerAnalysisData.length * 48)}px` }}>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={customerAnalysisData} layout="vertical" margin={{ left: 20, right: 120 }}>
                  <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#e2e8f0" />
                  <XAxis type="number" hide />
                  <YAxis type="category" dataKey="name" width={150} axisLine={false} tickLine={false} tick={(props) => (
                      <text {...props} className="fill-slate-600 font-black text-[12px] hover:fill-indigo-600 hover:underline cursor-pointer transition-colors" onClick={() => openCustomerDrillDown(props.payload.value)}>
                        {props.payload.value}
                      </text>
                    )} 
                  />
                  <Tooltip cursor={{ fill: '#f1f5f9', opacity: 0.5 }} contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} />
                  <Bar dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} radius={[0, 10, 10, 0]} barSize={30} onClick={(d) => openCustomerDrillDown(d.name)} className="cursor-pointer">
                    {customerAnalysisData.map((_, index) => <RechartsCell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                    <LabelList dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} position="right" formatter={(v: any) => customerMetric === 'sales' ? `${(v / 1000000).toFixed(2)}M` : v.toLocaleString()} style={{ fill: '#475569', fontSize: '11px', fontWeight: 900, fontFamily: 'monospace' }} />
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}
      </section>

      {/* 深度下钻模态面板保持不变，确保分析深度 */}
      {(selectedCategory || selectedItem || selectedCustomer) && (
        <div className="fixed inset-0 bg-white z-[5000] flex flex-col animate-in slide-in-from-bottom-10 duration-500 overflow-hidden">
           <div className="px-10 py-6 border-b border-slate-200 bg-white flex items-center justify-between shadow-sm z-10">
              <div className="flex items-center gap-4 text-left">
                <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-indigo-100">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                </div>
                <div>
                  <h3 className="text-2xl font-black text-slate-900 tracking-tight flex items-center gap-3">
                    {selectedCategory || selectedItem || selectedCustomer} <span className="text-slate-300 font-normal">|</span> <span className="text-indigo-600">深度穿透分析</span>
                  </h3>
                  <p className="text-[10px] font-bold text-slate-400 italic mt-1 uppercase tracking-widest">
                    维度：{selectedCategory ? '业务品类' : (selectedItem ? '物料明细' : '关联客户')} · 全周期联动监测
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-6">
                <div className="flex bg-slate-100 p-1.5 rounded-xl">
                  <button onClick={() => setDrillMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${drillMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-50'}`}>金额</button>
                  <button onClick={() => setDrillMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${drillMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-50'}`}>数量</button>
                </div>
                <button onClick={() => { setSelectedCategory(null); setSelectedItem(null); setSelectedCustomer(null); setLocalTableFilters({ customer: '', category: '', month: '' }); setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] }); }} className="px-10 py-3 bg-slate-900 text-white rounded-2xl text-xs font-black hover:bg-slate-800 transition-all">关闭分析面板</button>
              </div>
           </div>

           <div className="flex-1 overflow-y-auto custom-scrollbar p-10 bg-slate-50/30 space-y-10">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm text-left">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">累计销售 (CFA)</p>
                  <p className="text-3xl font-black text-indigo-600">{formatMetricDisplay(drillDownAnalysis.totalSales, 'sales')}</p>
                </div>
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm text-left">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">累计出库 (UNIT)</p>
                  <p className="text-3xl font-black text-emerald-600">{(drillDownAnalysis.totalQty || 0).toLocaleString()}</p>
                </div>
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm text-left">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">关联交易行数</p>
                  <p className="text-3xl font-black text-slate-900">{drillDownAnalysis.baseRecords.length} <span className="text-sm font-bold text-slate-400 uppercase">Lines</span></p>
                </div>
              </div>

              <div className="flex flex-col gap-10">
                {/* 贡献排行图 */}
                <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm flex flex-col h-[400px]">
                   <h5 className="text-xs font-black text-slate-500 uppercase tracking-widest mb-6 flex items-center justify-between">
                     <span>{localTableFilters.month ? `${localTableFilters.month} - ` : ''}{drillDownAnalysis.contextTitle}</span>
                     {(localTableFilters.customer || localTableFilters.category) && <span className="px-2 py-0.5 bg-indigo-100 text-indigo-600 rounded text-[9px]">已锁定维度</span>}
                   </h5>
                   <div className="flex-1">
                      <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={drillDownAnalysis.secondaryDistribution.slice(0, 15)} onClick={handleBarChartClick}>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                          <XAxis dataKey="name" tick={{ fontSize: 10, fill: '#64748b' }} axisLine={false} tickLine={false} />
                          <YAxis axisLine={false} tickLine={false} tickFormatter={(v) => drillMetric === 'sales' ? `${(v/1000000).toFixed(1)}M` : v.toLocaleString()} />
                          <Tooltip cursor={{ fill: '#f8fafc' }} />
                          <Bar dataKey={drillMetric === 'sales' ? 'sales' : 'qty'} radius={[8, 8, 0, 0]} barSize={40} cursor="pointer">
                            {drillDownAnalysis.secondaryDistribution.slice(0, 15).map((entry, idx) => {
                               const isTarget = selectedCustomer ? localTableFilters.category === entry.name : localTableFilters.customer === entry.name;
                               const hasFilter = selectedCustomer ? !!localTableFilters.category : !!localTableFilters.customer;
                               return <RechartsCell key={`cell-${idx}`} fill={isTarget ? '#6366f1' : COLORS[idx % COLORS.length]} fillOpacity={!hasFilter || isTarget ? 1 : 0.2} />;
                            })}
                          </Bar>
                        </BarChart>
                      </ResponsiveContainer>
                   </div>
                </div>

                {/* 趋势图 */}
                <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm flex flex-col h-[400px]">
                   <h5 className="text-xs font-black text-slate-500 uppercase tracking-widest mb-6 flex items-center justify-between">
                     <span>{localTableFilters.customer || localTableFilters.category ? `${localTableFilters.customer || localTableFilters.category} - ` : ''}月度趋势</span>
                     {localTableFilters.month && <span className="px-2 py-0.5 bg-emerald-100 text-emerald-600 rounded text-[9px]">已锁定月份: {localTableFilters.month}</span>}
                   </h5>
                   <div className="flex-1">
                      <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={drillDownAnalysis.monthlyTrend} onClick={handleTrendClick}>
                          <defs>
                            <linearGradient id="drillGrad" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor={drillMetric === 'sales' ? '#6366f1' : '#10b981'} stopOpacity={0.3}/><stop offset="95%" stopColor={drillMetric === 'sales' ? '#6366f1' : '#10b981'} stopOpacity={0}/></linearGradient>
                          </defs>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                          <XAxis dataKey="name" tick={{ fontSize: 10, fill: '#64748b' }} axisLine={false} tickLine={false} />
                          <YAxis axisLine={false} tickLine={false} tickFormatter={(v) => drillMetric === 'sales' ? `${(v/1000000).toFixed(1)}M` : v.toLocaleString()} />
                          <Tooltip />
                          <Area type="monotone" dataKey={drillMetric === 'sales' ? 'sales' : 'qty'} stroke={drillMetric === 'sales' ? '#6366f1' : '#10b981'} fill="url(#drillGrad)" strokeWidth={3} cursor="pointer" />
                        </AreaChart>
                      </ResponsiveContainer>
                   </div>
                </div>
              </div>

              {/* 联动明细表 */}
              <div className="bg-white rounded-3xl border border-slate-200 shadow-xl overflow-hidden mb-12">
                 <div className="px-8 py-5 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">双向联动明细清单</span>
                      {(Object.values(columnFilters) as string[][]).some(v => v.length > 0 || localTableFilters.month !== '' || localTableFilters.customer !== '' || localTableFilters.category !== '') && (
                        <button onClick={() => { setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] }); setLocalTableFilters({ month: '', customer: '', category: '' }); }} className="text-[10px] font-black text-red-500 bg-red-50 px-3 py-1 rounded border border-red-100 hover:bg-red-100 transition-all">重置所有条件</button>
                      )}
                    </div>
                    <div className="flex items-center gap-3">
                       {localTableFilters.month && <span className="text-[9px] font-black bg-emerald-100 text-emerald-700 px-2 py-0.5 rounded-full uppercase">月度: {localTableFilters.month}</span>}
                       {(localTableFilters.customer || localTableFilters.category) && <span className="text-[9px] font-black bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded-full uppercase">锁定: {localTableFilters.customer || localTableFilters.category}</span>}
                       <span className="text-xs font-black text-slate-400 italic ml-2">已匹配: {drillDownAnalysis.tableRecords.length} / {drillDownAnalysis.baseRecords.length}</span>
                    </div>
                 </div>
                 <div className="overflow-x-auto max-h-[600px] custom-scrollbar">
                    <table className="min-w-full divide-y divide-slate-100">
                       <thead className="bg-white sticky top-0 z-[500] shadow-sm">
                          <tr>
                            <th className="px-8 py-4 text-left"><TableDropdownFilter field="id" label="单号" /></th>
                            <th className="px-8 py-4 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">日期</th>
                            <th className="px-8 py-4 text-left"><TableDropdownFilter field="customer" label="客户" /></th>
                            <th className="px-8 py-4 text-left"><TableDropdownFilter field="salesperson" label="销售员" /></th>
                            <th className="px-8 py-4 text-left"><TableDropdownFilter field="itemName" label="物料名称" /></th>
                            <th className="px-8 py-4 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">数量</th>
                            <th className="px-8 py-4 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">单价</th>
                            <th className="px-8 py-4 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">合计(CFA)</th>
                          </tr>
                       </thead>
                       <tbody className="bg-white divide-y divide-slate-50 text-[12px]">
                          {drillDownAnalysis.tableRecords.map((r, i) => (
                            <tr key={`${r.id}-${i}`} className="hover:bg-slate-50 transition-colors">
                               <td className="px-8 py-4 whitespace-nowrap font-mono font-bold text-indigo-600"><button onClick={() => onSelectOrderId(r.id)} className="hover:underline">{r.id}</button></td>
                               <td className="px-8 py-4 whitespace-nowrap font-bold text-slate-500">{r.date}</td>
                               <td className="px-8 py-4 whitespace-nowrap font-black text-slate-900">{r.customer}</td>
                               <td className="px-8 py-4 whitespace-nowrap font-bold text-slate-500">{r.salesperson}</td>
                               <td className="px-8 py-4 whitespace-nowrap font-black text-slate-700 truncate max-w-[150px]">{r.itemName}</td>
                               <td className="px-8 py-4 whitespace-nowrap text-right font-mono font-black text-indigo-700">{r.quantity}</td>
                               <td className="px-8 py-4 whitespace-nowrap text-right font-mono font-bold text-slate-400">{r.unitPrice.toLocaleString()}</td>
                               <td className="px-8 py-4 whitespace-nowrap text-right font-mono font-black text-slate-900">{r.totalAmount.toLocaleString()}</td>
                            </tr>
                          ))}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7', '#fb7185', '#2dd4bf', '#fbbf24'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  // 版块折叠状态
  const [sections, setSections] = useState({
    trend: true,
    composition: true,
    ranking: true
  });

  // 全局展示状态
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [customerMetric, setCustomerMetric] = useState<'sales' | 'quantity'>('sales');
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');

  // 深度分析联动状态
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<string | null>(null);
  const [drillMetric, setDrillMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [localTableFilters, setLocalTableFilters] = useState({
    customer: '', 
    category: '',
    month: '' 
  });

  // 明细表内部表头多选筛选状态
  const [columnFilters, setColumnFilters] = useState<Record<string, string[]>>({
    id: [],
    customer: [],
    salesperson: [],
    itemName: []
  });

  const [activeFilterMenu, setActiveFilterMenu] = useState<string | null>(null);
  const [activeMetrics, setActiveMetrics] = useState({ amount: true, quantity: true });
  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  // 切换折叠
  const toggleSection = (key: keyof typeof sections) => {
    setSections(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- 响应式计算链 (双向联动逻辑) ---
  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : (selectedCustomer ? 'customer' : null));
    const value = selectedCategory || selectedItem || selectedCustomer;

    if (!dimension || !value) return {
      baseRecords: [], totalSales: 0, totalQty: 0, secondaryDistribution: [], monthlyTrend: [], filterOptions: { id: [], customer: [], salesperson: [], itemName: [] }, tableRecords: [], contextTitle: ''
    };

    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);
    const totalSales = baseRecords.reduce((s, r) => s + r.totalAmount, 0);
    const totalQty = baseRecords.reduce((s, r) => s + r.quantity, 0);

    const recordsForDist = localTableFilters.month 
      ? baseRecords.filter(r => r.month === localTableFilters.month) 
      : baseRecords;

    const secondaryDim = selectedCustomer ? 'category' : 'customer';
    const distMap = new Map<string, { sales: number; qty: number }>();
    recordsForDist.forEach(r => {
      const key = r[secondaryDim] as string;
      const e = distMap.get(key) || { sales: 0, qty: 0 };
      distMap.set(key, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });
    const secondaryDistribution = Array.from(distMap.entries())
      .map(([name, v]) => ({ name, sales: v.sales, qty: v.qty }))
      .sort((a, b) => drillMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    let recordsForTrend = baseRecords;
    if (localTableFilters.customer && !selectedCustomer) recordsForTrend = recordsForTrend.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.category && selectedCustomer) recordsForTrend = recordsForTrend.filter(r => r.category === localTableFilters.category);

    const monthlyMap = new Map<string, { sales: number; qty: number }>();
    recordsForTrend.forEach(r => {
      const e = monthlyMap.get(r.month) || { sales: 0, qty: 0 };
      monthlyMap.set(r.month, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });
    const allMonths = Array.from(new Set<string>(baseRecords.map(r => r.month))).sort();
    const monthlyTrend = allMonths.map(m => {
      const v = monthlyMap.get(m) || { sales: 0, qty: 0 };
      return { name: m, sales: v.sales, qty: v.qty };
    });

    const getOptionsForField = (field: string) => {
      let subset = baseRecords;
      if (localTableFilters.month) subset = subset.filter(r => r.month === localTableFilters.month);
      if (localTableFilters.customer && !selectedCustomer) subset = subset.filter(r => r.customer === localTableFilters.customer);
      if (localTableFilters.category && selectedCustomer) subset = subset.filter(r => r.category === localTableFilters.category);

      Object.entries(columnFilters).forEach(([f, vals]) => {
        const castedVals = vals as string[];
        if (f !== field && castedVals.length > 0) {
          subset = subset.filter(r => castedVals.includes(String(r[f as keyof SalesRecord])));
        }
      });
      return Array.from(new Set<string>(subset.map(r => String(r[field as keyof SalesRecord])))).sort();
    };

    const filterOptions = {
      id: getOptionsForField('id'),
      customer: getOptionsForField('customer'),
      salesperson: getOptionsForField('salesperson'),
      itemName: getOptionsForField('itemName')
    };

    let finalRecords = baseRecords;
    if (localTableFilters.month) finalRecords = finalRecords.filter(r => r.month === localTableFilters.month);
    if (localTableFilters.customer && !selectedCustomer) finalRecords = finalRecords.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.category && selectedCustomer) finalRecords = finalRecords.filter(r => r.category === localTableFilters.category);

    Object.entries(columnFilters).forEach(([field, selectedValues]) => {
      const castedValues = selectedValues as string[];
      if (castedValues.length > 0) {
        finalRecords = finalRecords.filter(r => castedValues.includes(String(r[field as keyof SalesRecord])));
      }
    });

    return {
      baseRecords,
      totalSales,
      totalQty,
      secondaryDistribution,
      monthlyTrend,
      filterOptions,
      tableRecords: finalRecords.sort((a, b) => b.date.localeCompare(a.date)),
      contextTitle: selectedCustomer ? '品类贡献偏好' : '关联客户贡献排行'
    };
  }, [selectedCategory, selectedItem, selectedCustomer, filteredData, localTableFilters, columnFilters, drillMetric]);

  const handleBarChartClick = (state: any) => {
    if (state && state.activeLabel) {
      const label = state.activeLabel;
      if (selectedCustomer) {
        setLocalTableFilters(prev => ({ ...prev, category: prev.category === label ? '' : label }));
      } else {
        setLocalTableFilters(prev => ({ ...prev, customer: prev.customer === label ? '' : label }));
      }
    }
  };

  const handleTrendClick = (state: any) => {
    if (state && state.activeLabel) {
      const clickedMonth = state.activeLabel;
      setLocalTableFilters(prev => ({ ...prev, month: prev.month === clickedMonth ? '' : clickedMonth }));
    }
  };

  const openCategoryDrillDown = (name: string) => {
    setDrillMetric(pieMetric); 
    setSelectedCategory(name);
    setSelectedItem(null);
    setSelectedCustomer(null);
    setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] });
    setLocalTableFilters({ customer: '', category: '', month: '' });
  };

  const openItemDrillDown = (name: string) => {
    setDrillMetric(itemPieMetric); 
    setSelectedItem(name);
    setSelectedCategory(null);
    setSelectedCustomer(null);
    setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] });
    setLocalTableFilters({ customer: '', category: '', month: '' });
  };

  const openCustomerDrillDown = (name: string) => {
    setDrillMetric(customerMetric);
    setSelectedCustomer(name);
    setSelectedCategory(null);
    setSelectedItem(null);
    setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] });
    setLocalTableFilters({ customer: '', category: '', month: '' });
  };

  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set<string>(filteredData.map(d => d.month))).sort();
    const metrics = !activeMetrics.amount && !activeMetrics.quantity ? { amount: true, quantity: true } : activeMetrics;

    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return {
          name: month,
          amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0),
          quantity: monthRecords.reduce((s, r) => s + r.quantity, 0)
        };
      });
      const series: any[] = [];
      if (metrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (metrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }

    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set<string>(filteredData.map(d => String(d[dimKey])))).slice(0, 8);
    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (metrics.amount) series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor });
      if (metrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
    });

    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });
    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  const customerAnalysisData = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.customer) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.customer, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => customerMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, customerMetric]);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, itemPieMetric]);

  const formatMetricDisplay = (value: number, metric: 'sales' | 'quantity') => {
    if (metric === 'sales') return `${(value / 1000000).toFixed(2)}M CFA`;
    return `${value.toLocaleString()} UNIT`;
  };

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-RADIAN * midAngle);
    const cos = Math.cos(-RADIAN * midAngle);
    const sx = cx + (outerRadius + 5) * cos;
    const sy = cy + (outerRadius + 5) * sin;
    const mx = cx + (outerRadius + 25) * cos;
    const my = cy + (outerRadius + 25) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 22;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={2} opacity={0.6} />
        <circle cx={ex} cy={ey} r={3} fill={fill} />
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} textAnchor={textAnchor} fill="#0f172a" style={{ fontSize: '12px', fontWeight: 800 }}>{name}</text>
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} dy={14} textAnchor={textAnchor} fill="#64748b" style={{ fontSize: '11px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  const TableDropdownFilter = ({ field, label }: { field: string, label: string }) => {
    const options = (drillDownAnalysis.filterOptions as Record<string, string[]>)?.[field] || [];
    const selected = columnFilters[field] || [];
    const isActive = selected.length > 0;
    const menuRef = useRef<HTMLDivElement>(null);
    const [localSearch, setLocalSearch] = useState('');

    useEffect(() => {
      const handleClickOutside = (e: MouseEvent) => {
        if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
          setActiveFilterMenu(null);
        }
      };
      if (activeFilterMenu === field) {
        document.addEventListener('mousedown', handleClickOutside);
      }
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [activeFilterMenu, field]);

    const toggleValue = (val: string) => {
      const next = selected.includes(val) ? selected.filter(v => v !== val) : [...selected, val];
      setColumnFilters(prev => ({ ...prev, [field]: next }));
    };

    const filteredOptions = options.filter(opt => opt.toLowerCase().includes(localSearch.toLowerCase()));

    return (
      <div className="relative inline-block text-left" ref={menuRef}>
        <button 
          onClick={() => {
            setActiveFilterMenu(activeFilterMenu === field ? null : field);
            setLocalSearch('');
          }}
          className={`flex items-center gap-2 px-2 py-1.5 rounded-lg transition-all group ${isActive ? 'bg-indigo-50 text-indigo-700' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100'}`}
        >
          <span className={`text-[10px] font-black uppercase tracking-widest`}>{label}</span>
          <svg className={`w-3 h-3 transition-transform ${activeFilterMenu === field ? 'rotate-180 text-indigo-500' : 'text-slate-300'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
             <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" />
          </svg>
        </button>
        {activeFilterMenu === field && (
          <div className="absolute top-full left-0 mt-2 w-64 bg-white border border-slate-200 shadow-2xl rounded-2xl z-[6000] overflow-hidden animate-in fade-in zoom-in-95 duration-150 origin-top-left">
             <div className="p-3 bg-slate-50 border-b border-slate-100">
                <input 
                  type="text" autoFocus placeholder={`搜索...`} value={localSearch}
                  onChange={(e) => setLocalSearch(e.target.value)}
                  className="w-full px-3 py-2 bg-white border border-slate-200 rounded-xl text-xs outline-none focus:ring-2 focus:ring-indigo-100 font-bold"
                />
             </div>
             <div className="max-h-64 overflow-y-auto p-1.5 custom-scrollbar bg-white">
                <button onClick={() => { setColumnFilters(prev => ({ ...prev, [field]: [] })); setActiveFilterMenu(null); }} className="w-full text-left px-3 py-2.5 text-[10px] font-black text-red-500 hover:bg-red-50 rounded-xl mb-1">重置该列筛选</button>
                {filteredOptions.map(opt => {
                  const isSelected = selected.includes(opt);
                  return (
                    <button key={opt} onClick={() => toggleValue(opt)} className={`w-full text-left px-3 py-2.5 rounded-xl mb-0.5 flex items-center justify-between group ${isSelected ? 'bg-indigo-600 text-white shadow-lg' : 'hover:bg-indigo-50 text-slate-700'}`}>
                      <span className="text-[12px] font-bold truncate pr-2">{opt}</span>
                      {isSelected && <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7" /></svg>}
                    </button>
                  );
                })}
             </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-10 pb-16 relative">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col overflow-hidden">
           <div className="p-6 flex items-center justify-between bg-white border-b border-slate-100">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
                <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">单据总数</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div>
              </div>
              <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2 bg-slate-100 rounded-xl hover:bg-slate-200 transition-all">
                <svg className={`w-5 h-5 transition-transform ${isOrdersExpanded ? 'rotate-180 text-indigo-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
              </button>
           </div>
           {isOrdersExpanded && (
              <div className="px-5 py-5 bg-slate-50/50 border-t border-slate-100 space-y-4 animate-in fade-in slide-in-from-top-2 duration-300">
                <input type="text" placeholder="检索单号..." value={orderSearchTerm} onChange={(e) => setOrderSearchTerm(e.target.value)} className="w-full bg-white border border-slate-300 rounded-lg px-3 py-1.5 text-xs outline-none focus:border-indigo-500 font-bold" />
                <div className="max-h-40 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar pr-1">
                  {summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase())).map(id => (<button key={id} onClick={() => onSelectOrderId(id)} className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-bold hover:border-indigo-500 transition-colors">{id}</button>))}
                </div>
              </div>
           )}
        </div>
      </div>

      {/* 业绩趋势版块 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div 
          onClick={() => toggleSection('trend')}
          className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors"
        >
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 shrink-0">
            <span className="p-2 bg-indigo-50 text-indigo-600 rounded-xl text-lg">📈</span> 业绩增长趋势
          </h3>
          <div className="flex items-center gap-6" onClick={(e) => e.stopPropagation()}>
            {sections.trend && (
              <div className="hidden md:flex flex-wrap items-center gap-4">
                <div className="flex bg-slate-100 p-1 rounded-2xl border border-slate-200 shadow-inner">
                   <button onClick={() => setActiveMetrics({ amount: true, quantity: false })} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${activeMetrics.amount && !activeMetrics.quantity ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>金额</button>
                   <button onClick={() => setActiveMetrics({ amount: false, quantity: true })} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${!activeMetrics.amount && activeMetrics.quantity ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量</button>
                   <button onClick={() => setActiveMetrics({ amount: true, quantity: true })} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${activeMetrics.amount && activeMetrics.quantity ? 'bg-white shadow-md text-slate-900' : 'text-slate-500'}`}>双轴</button>
                </div>
                <div className="flex bg-slate-100 p-1 rounded-2xl border border-slate-200 shadow-inner">
                  <button onClick={() => setTrendMode('total')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'total' ? 'bg-white shadow-md text-slate-900' : 'text-slate-500'}`}>汇总</button>
                  <button onClick={() => setTrendMode('customer')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'customer' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>客户</button>
                  <button onClick={() => setTrendMode('salesperson')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'salesperson' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>销售</button>
                </div>
              </div>
            )}
            <button className="p-2 bg-slate-100 rounded-xl">
              <svg className={`w-5 h-5 transition-transform duration-300 ${sections.trend ? 'rotate-180 text-indigo-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
            </button>
          </div>
        </div>
        {sections.trend && (
          <div className="px-8 pb-8 animate-in fade-in duration-500">
            <div className="h-[450px] w-full mt-4">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={trendAnalysis.data}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11}} />
                  {activeMetrics.amount && <YAxis yAxisId="amount" axisLine={false} tickLine={false} tick={{fill: '#6366f1', fontSize: 10, fontWeight: 700}} tickFormatter={(v) => `${(v / 1000000).toFixed(1)}M`} />}
                  {activeMetrics.quantity && <YAxis yAxisId="quantity" orientation="right" axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 10, fontWeight: 700}} tickFormatter={(v) => v.toLocaleString()} />}
                  <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }} formatter={(value: any, name: string) => [value.toLocaleString(), name]} />
                  <Legend iconType="circle" />
                  {trendAnalysis.series.map((s, i) => (
                    <Area key={s.key} yAxisId={s.type} type="monotone" dataKey={s.key} name={s.name} stroke={s.color} strokeWidth={s.dashed ? 2 : 3} strokeDasharray={s.dashed ? "5 5" : "0"} fill={s.color} fillOpacity={s.dashed ? 0 : 0.08} activeDot={{ r: 6, strokeWidth: 0 }} />
                  ))}
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}
      </section>

      {/* 构成分析版块 - 优化为纵向上下排列布局 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div 
          onClick={() => toggleSection('composition')}
          className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors"
        >
          <div className="flex flex-col gap-1">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 shrink-0">
              <span className="p-2 bg-emerald-50 text-emerald-600 rounded-xl text-lg">🧩</span> 业务构成分析
            </h3>
            {!sections.composition && (
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest pl-12">纵向对比品类与物料明细构成</p>
            )}
          </div>
          <button className="p-2 bg-slate-100 rounded-xl">
            <svg className={`w-5 h-5 transition-transform duration-300 ${sections.composition ? 'rotate-180 text-emerald-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
          </button>
        </div>
        {sections.composition && (
          <div className="px-8 pb-10 animate-in fade-in duration-500">
            {/* 改为单列布局 (flex flex-col)，使子模块上下排列 */}
            <div className="flex flex-col gap-y-20">
              {/* 品类分析 */}
              <div className="flex flex-col w-full">
                <div className="flex justify-between items-start mb-6 px-2">
                  <div className="flex flex-col">
                    <h4 className="text-base font-black text-slate-800 tracking-tight">品类核心构成</h4>
                    <span className={`text-lg font-black mt-1 ${pieMetric === 'sales' ? 'text-indigo-600' : 'text-emerald-600'}`}>
                      {formatMetricDisplay(sortedCategorySummary.reduce((acc, curr) => acc + (pieMetric === 'sales' ? curr.sales : curr.quantity), 0), pieMetric)}
                    </span>
                  </div>
                  <div className="flex bg-slate-100 p-1 rounded-xl shadow-inner scale-90 origin-right">
                    <button onClick={(e) => { e.stopPropagation(); setPieMetric('sales'); }} className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${pieMetric === 'sales' ? 'bg-white shadow-sm text-indigo-700' : 'text-slate-500'}`}>金额</button>
                    <button onClick={(e) => { e.stopPropagation(); setPieMetric('quantity'); }} className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-500'}`}>数量</button>
                  </div>
                </div>
                <div className="h-[480px] w-full relative">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie data={sortedCategorySummary} cx="50%" cy="50%" innerRadius={80} outerRadius={120} paddingAngle={4} dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} stroke="#fff" strokeWidth={4} label={renderCustomizedLabel} labelLine={false} onClick={(d) => openCategoryDrillDown(d.name)}>
                        {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} className="cursor-pointer hover:opacity-85 transition-opacity" />)}
                      </Pie>
                      <Tooltip formatter={(v: any) => v.toLocaleString()} />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              </div>

              {/* 物料分析 */}
              <div className="flex flex-col w-full">
                <div className="flex justify-between items-start mb-6 px-2 border-t border-slate-50 pt-16">
                  <div className="flex flex-col">
                    <h4 className="text-base font-black text-slate-800 tracking-tight">物料贡献排行 (TOP 15)</h4>
                    <span className={`text-lg font-black mt-1 ${itemPieMetric === 'sales' ? 'text-indigo-600' : 'text-emerald-600'}`}>
                      {formatMetricDisplay(sortedItemSummary.slice(0, 15).reduce((acc, curr) => acc + (itemPieMetric === 'sales' ? curr.sales : curr.quantity), 0), itemPieMetric)}
                    </span>
                  </div>
                  <div className="flex bg-slate-100 p-1 rounded-xl shadow-inner scale-90 origin-right">
                    <button onClick={(e) => { e.stopPropagation(); setItemPieMetric('sales'); }} className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${itemPieMetric === 'sales' ? 'bg-white shadow-sm text-indigo-700' : 'text-slate-500'}`}>金额</button>
                    <button onClick={(e) => { e.stopPropagation(); setItemPieMetric('quantity'); }} className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${itemPieMetric === 'quantity' ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-500'}`}>数量</button>
                  </div>
                </div>
                <div className="h-[480px] w-full relative">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie data={sortedItemSummary.slice(0, 15)} cx="50%" cy="50%" innerRadius={80} outerRadius={120} paddingAngle={2} dataKey={itemPieMetric === 'sales' ? 'sales' : 'quantity'} stroke="#fff" strokeWidth={4} label={renderCustomizedLabel} labelLine={false} onClick={(d) => openItemDrillDown(d.name)}>
                        {sortedItemSummary.slice(0, 15).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} className="cursor-pointer hover:opacity-85 transition-opacity" />)}
                      </Pie>
                      <Tooltip formatter={(v: any) => v.toLocaleString()} />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              </div>
            </div>
          </div>
        )}
      </section>

      {/* 客户排行版块 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div 
          onClick={() => toggleSection('ranking')}
          className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors"
        >
          <div className="flex flex-col gap-1">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 shrink-0">
              <span className="p-2 bg-amber-50 text-amber-600 rounded-xl text-lg">👥</span> 客户采购排行
            </h3>
            {!sections.ranking && (
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest pl-12">共分析 {customerAnalysisData.length} 家客户</p>
            )}
          </div>
          <div className="flex items-center gap-6" onClick={(e) => e.stopPropagation()}>
            {sections.ranking && (
              <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200">
                <button onClick={() => setCustomerMetric('sales')} className={`px-6 py-1.5 rounded-xl text-xs font-black transition-all ${customerMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>金额</button>
                <button onClick={() => setCustomerMetric('quantity')} className={`px-6 py-1.5 rounded-xl text-xs font-black transition-all ${customerMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量</button>
              </div>
            )}
            <button className="p-2 bg-slate-100 rounded-xl">
              <svg className={`w-5 h-5 transition-transform duration-300 ${sections.ranking ? 'rotate-180 text-amber-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
            </button>
          </div>
        </div>
        {sections.ranking && (
          <div className="px-8 pb-10 animate-in fade-in duration-500">
            <div className="w-full" style={{ height: `${Math.max(400, customerAnalysisData.length * 48)}px` }}>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={customerAnalysisData} layout="vertical" margin={{ left: 20, right: 120 }}>
                  <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#e2e8f0" />
                  <XAxis type="number" hide />
                  <YAxis type="category" dataKey="name" width={150} axisLine={false} tickLine={false} tick={(props) => (
                      <text {...props} className="fill-slate-600 font-black text-[12px] hover:fill-indigo-600 hover:underline cursor-pointer transition-colors" onClick={() => openCustomerDrillDown(props.payload.value)}>
                        {props.payload.value}
                      </text>
                    )} 
                  />
                  <Tooltip cursor={{ fill: '#f1f5f9', opacity: 0.5 }} contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} />
                  <Bar dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} radius={[0, 10, 10, 0]} barSize={30} onClick={(d) => openCustomerDrillDown(d.name)} className="cursor-pointer">
                    {customerAnalysisData.map((_, index) => <RechartsCell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                    <LabelList dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} position="right" formatter={(v: any) => customerMetric === 'sales' ? `${(v / 1000000).toFixed(2)}M` : v.toLocaleString()} style={{ fill: '#475569', fontSize: '11px', fontWeight: 900, fontFamily: 'monospace' }} />
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}
      </section>

      {/* 深度下钻模态面板保持不变 */}
      {(selectedCategory || selectedItem || selectedCustomer) && (
        <div className="fixed inset-0 bg-white z-[5000] flex flex-col animate-in slide-in-from-bottom-10 duration-500 overflow-hidden">
           <div className="px-10 py-6 border-b border-slate-200 bg-white flex items-center justify-between shadow-sm z-10">
              <div className="flex items-center gap-4 text-left">
                <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-indigo-100">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                </div>
                <div>
                  <h3 className="text-2xl font-black text-slate-900 tracking-tight flex items-center gap-3">
                    {selectedCategory || selectedItem || selectedCustomer} <span className="text-slate-300 font-normal">|</span> <span className="text-indigo-600">深度穿透分析</span>
                  </h3>
                  <p className="text-[10px] font-bold text-slate-400 italic mt-1 uppercase tracking-widest">
                    维度：{selectedCategory ? '业务品类' : (selectedItem ? '物料明细' : '关联客户')} · 全周期联动监测
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-6">
                <div className="flex bg-slate-100 p-1.5 rounded-xl">
                  <button onClick={() => setDrillMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${drillMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-50'}`}>金额</button>
                  <button onClick={() => setDrillMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${drillMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-50'}`}>数量</button>
                </div>
                <button onClick={() => { setSelectedCategory(null); setSelectedItem(null); setSelectedCustomer(null); setLocalTableFilters({ customer: '', category: '', month: '' }); setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] }); }} className="px-10 py-3 bg-slate-900 text-white rounded-2xl text-xs font-black hover:bg-slate-800 transition-all">关闭分析面板</button>
              </div>
           </div>

           <div className="flex-1 overflow-y-auto custom-scrollbar p-10 bg-slate-50/30 space-y-10">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm text-left">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">累计销售 (CFA)</p>
                  <p className="text-3xl font-black text-indigo-600">{formatMetricDisplay(drillDownAnalysis.totalSales, 'sales')}</p>
                </div>
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm text-left">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">累计出库 (UNIT)</p>
                  <p className="text-3xl font-black text-emerald-600">{(drillDownAnalysis.totalQty || 0).toLocaleString()}</p>
                </div>
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm text-left">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">关联交易行数</p>
                  <p className="text-3xl font-black text-slate-900">{drillDownAnalysis.baseRecords.length} <span className="text-sm font-bold text-slate-400 uppercase">Lines</span></p>
                </div>
              </div>

              <div className="flex flex-col gap-10">
                <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm flex flex-col h-[400px]">
                   <h5 className="text-xs font-black text-slate-500 uppercase tracking-widest mb-6 flex items-center justify-between">
                     <span>{localTableFilters.month ? `${localTableFilters.month} - ` : ''}{drillDownAnalysis.contextTitle}</span>
                     {(localTableFilters.customer || localTableFilters.category) && <span className="px-2 py-0.5 bg-indigo-100 text-indigo-600 rounded text-[9px]">已锁定维度</span>}
                   </h5>
                   <div className="flex-1">
                      <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={drillDownAnalysis.secondaryDistribution.slice(0, 15)} onClick={handleBarChartClick}>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                          <XAxis dataKey="name" tick={{ fontSize: 10, fill: '#64748b' }} axisLine={false} tickLine={false} />
                          <YAxis axisLine={false} tickLine={false} tickFormatter={(v) => drillMetric === 'sales' ? `${(v/1000000).toFixed(1)}M` : v.toLocaleString()} />
                          <Tooltip cursor={{ fill: '#f8fafc' }} />
                          <Bar dataKey={drillMetric === 'sales' ? 'sales' : 'qty'} radius={[8, 8, 0, 0]} barSize={40} cursor="pointer">
                            {drillDownAnalysis.secondaryDistribution.slice(0, 15).map((entry, idx) => {
                               const isTarget = selectedCustomer ? localTableFilters.category === entry.name : localTableFilters.customer === entry.name;
                               const hasFilter = selectedCustomer ? !!localTableFilters.category : !!localTableFilters.customer;
                               return <RechartsCell key={`cell-${idx}`} fill={isTarget ? '#6366f1' : COLORS[idx % COLORS.length]} fillOpacity={!hasFilter || isTarget ? 1 : 0.2} />;
                            })}
                          </Bar>
                        </BarChart>
                      </ResponsiveContainer>
                   </div>
                </div>

                <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm flex flex-col h-[400px]">
                   <h5 className="text-xs font-black text-slate-500 uppercase tracking-widest mb-6 flex items-center justify-between">
                     <span>{localTableFilters.customer || localTableFilters.category ? `${localTableFilters.customer || localTableFilters.category} - ` : ''}月度趋势</span>
                     {localTableFilters.month && <span className="px-2 py-0.5 bg-emerald-100 text-emerald-600 rounded text-[9px]">已锁定月份: {localTableFilters.month}</span>}
                   </h5>
                   <div className="flex-1">
                      <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={drillDownAnalysis.monthlyTrend} onClick={handleTrendClick}>
                          <defs>
                            <linearGradient id="drillGrad" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor={drillMetric === 'sales' ? '#6366f1' : '#10b981'} stopOpacity={0.3}/><stop offset="95%" stopColor={drillMetric === 'sales' ? '#6366f1' : '#10b981'} stopOpacity={0}/></linearGradient>
                          </defs>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                          <XAxis dataKey="name" tick={{ fontSize: 10, fill: '#64748b' }} axisLine={false} tickLine={false} />
                          <YAxis axisLine={false} tickLine={false} tickFormatter={(v) => drillMetric === 'sales' ? `${(v/1000000).toFixed(1)}M` : v.toLocaleString()} />
                          <Tooltip />
                          <Area type="monotone" dataKey={drillMetric === 'sales' ? 'sales' : 'qty'} stroke={drillMetric === 'sales' ? '#6366f1' : '#10b981'} fill="url(#drillGrad)" strokeWidth={3} cursor="pointer" />
                        </AreaChart>
                      </ResponsiveContainer>
                   </div>
                </div>
              </div>

              <div className="bg-white rounded-3xl border border-slate-200 shadow-xl overflow-hidden mb-12">
                 <div className="px-8 py-5 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">双向联动明细清单</span>
                      {(Object.values(columnFilters) as string[][]).some(v => v.length > 0 || localTableFilters.month !== '' || localTableFilters.customer !== '' || localTableFilters.category !== '') && (
                        <button onClick={() => { setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] }); setLocalTableFilters({ month: '', customer: '', category: '' }); }} className="text-[10px] font-black text-red-500 bg-red-50 px-3 py-1 rounded border border-red-100 hover:bg-red-100 transition-all">重置所有条件</button>
                      )}
                    </div>
                    <div className="flex items-center gap-3">
                       {localTableFilters.month && <span className="text-[9px] font-black bg-emerald-100 text-emerald-700 px-2 py-0.5 rounded-full uppercase">月度: {localTableFilters.month}</span>}
                       {(localTableFilters.customer || localTableFilters.category) && <span className="text-[9px] font-black bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded-full uppercase">锁定: {localTableFilters.customer || localTableFilters.category}</span>}
                       <span className="text-xs font-black text-slate-400 italic ml-2">已匹配: {drillDownAnalysis.tableRecords.length} / {drillDownAnalysis.baseRecords.length}</span>
                    </div>
                 </div>
                 <div className="overflow-x-auto max-h-[600px] custom-scrollbar">
                    <table className="min-w-full divide-y divide-slate-100">
                       <thead className="bg-white sticky top-0 z-[500] shadow-sm">
                          <tr>
                            <th className="px-8 py-4 text-left"><TableDropdownFilter field="id" label="单号" /></th>
                            <th className="px-8 py-4 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">日期</th>
                            <th className="px-8 py-4 text-left"><TableDropdownFilter field="customer" label="客户" /></th>
                            <th className="px-8 py-4 text-left"><TableDropdownFilter field="salesperson" label="销售员" /></th>
                            <th className="px-8 py-4 text-left"><TableDropdownFilter field="itemName" label="物料名称" /></th>
                            <th className="px-8 py-4 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">数量</th>
                            <th className="px-8 py-4 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">单价</th>
                            <th className="px-8 py-4 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">合计(CFA)</th>
                          </tr>
                       </thead>
                       <tbody className="bg-white divide-y divide-slate-50 text-[12px]">
                          {drillDownAnalysis.tableRecords.map((r, i) => (
                            <tr key={`${r.id}-${i}`} className="hover:bg-slate-50 transition-colors">
                               <td className="px-8 py-4 whitespace-nowrap font-mono font-bold text-indigo-600"><button onClick={() => onSelectOrderId(r.id)} className="hover:underline">{r.id}</button></td>
                               <td className="px-8 py-4 whitespace-nowrap font-bold text-slate-500">{r.date}</td>
                               <td className="px-8 py-4 whitespace-nowrap font-black text-slate-900">{r.customer}</td>
                               <td className="px-8 py-4 whitespace-nowrap font-bold text-slate-500">{r.salesperson}</td>
                               <td className="px-8 py-4 whitespace-nowrap font-black text-slate-700 truncate max-w-[150px]">{r.itemName}</td>
                               <td className="px-8 py-4 whitespace-nowrap text-right font-mono font-black text-indigo-700">{r.quantity}</td>
                               <td className="px-8 py-4 whitespace-nowrap text-right font-mono font-bold text-slate-400">{r.unitPrice.toLocaleString()}</td>
                               <td className="px-8 py-4 whitespace-nowrap text-right font-mono font-black text-slate-900">{r.totalAmount.toLocaleString()}</td>
                            </tr>
                          ))}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7', '#fb7185', '#2dd4bf', '#fbbf24'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  // 版块折叠状态
  const [sections, setSections] = useState({
    trend: true,
    composition: true,
    ranking: true
  });

  // 全局展示状态
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [customerMetric, setCustomerMetric] = useState<'sales' | 'quantity'>('sales');
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');

  // 深度分析联动状态
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<string | null>(null);
  const [drillMetric, setDrillMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [localTableFilters, setLocalTableFilters] = useState({
    customer: '', 
    category: '',
    month: '' 
  });

  // 明细表内部表头多选筛选状态
  const [columnFilters, setColumnFilters] = useState<Record<string, string[]>>({
    id: [],
    customer: [],
    salesperson: [],
    itemName: []
  });

  const [activeFilterMenu, setActiveFilterMenu] = useState<string | null>(null);
  const [activeMetrics, setActiveMetrics] = useState({ amount: true, quantity: true });
  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  // 切换折叠
  const toggleSection = (key: keyof typeof sections) => {
    setSections(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- 响应式计算链 (双向联动逻辑) ---
  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : (selectedCustomer ? 'customer' : null));
    const value = selectedCategory || selectedItem || selectedCustomer;

    if (!dimension || !value) return {
      baseRecords: [], totalSales: 0, totalQty: 0, secondaryDistribution: [], monthlyTrend: [], filterOptions: { id: [], customer: [], salesperson: [], itemName: [] }, tableRecords: [], contextTitle: ''
    };

    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);
    const totalSales = baseRecords.reduce((s, r) => s + r.totalAmount, 0);
    const totalQty = baseRecords.reduce((s, r) => s + r.quantity, 0);

    const recordsForDist = localTableFilters.month 
      ? baseRecords.filter(r => r.month === localTableFilters.month) 
      : baseRecords;

    const secondaryDim = selectedCustomer ? 'category' : 'customer';
    const distMap = new Map<string, { sales: number; qty: number }>();
    recordsForDist.forEach(r => {
      const key = r[secondaryDim] as string;
      const e = distMap.get(key) || { sales: 0, qty: 0 };
      distMap.set(key, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });
    const secondaryDistribution = Array.from(distMap.entries())
      .map(([name, v]) => ({ name, sales: v.sales, qty: v.qty }))
      .sort((a, b) => drillMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    let recordsForTrend = baseRecords;
    if (localTableFilters.customer && !selectedCustomer) recordsForTrend = recordsForTrend.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.category && selectedCustomer) recordsForTrend = recordsForTrend.filter(r => r.category === localTableFilters.category);

    const monthlyMap = new Map<string, { sales: number; qty: number }>();
    recordsForTrend.forEach(r => {
      const e = monthlyMap.get(r.month) || { sales: 0, qty: 0 };
      monthlyMap.set(r.month, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });
    const allMonths = Array.from(new Set<string>(baseRecords.map(r => r.month))).sort();
    const monthlyTrend = allMonths.map(m => {
      const v = monthlyMap.get(m) || { sales: 0, qty: 0 };
      return { name: m, sales: v.sales, qty: v.qty };
    });

    const getOptionsForField = (field: string) => {
      let subset = baseRecords;
      if (localTableFilters.month) subset = subset.filter(r => r.month === localTableFilters.month);
      if (localTableFilters.customer && !selectedCustomer) subset = subset.filter(r => r.customer === localTableFilters.customer);
      if (localTableFilters.category && selectedCustomer) subset = subset.filter(r => r.category === localTableFilters.category);

      Object.entries(columnFilters).forEach(([f, vals]) => {
        const castedVals = vals as string[];
        if (f !== field && castedVals.length > 0) {
          subset = subset.filter(r => castedVals.includes(String(r[f as keyof SalesRecord])));
        }
      });
      return Array.from(new Set<string>(subset.map(r => String(r[field as keyof SalesRecord])))).sort();
    };

    const filterOptions = {
      id: getOptionsForField('id'),
      customer: getOptionsForField('customer'),
      salesperson: getOptionsForField('salesperson'),
      itemName: getOptionsForField('itemName')
    };

    let finalRecords = baseRecords;
    if (localTableFilters.month) finalRecords = finalRecords.filter(r => r.month === localTableFilters.month);
    if (localTableFilters.customer && !selectedCustomer) finalRecords = finalRecords.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.category && selectedCustomer) finalRecords = finalRecords.filter(r => r.category === localTableFilters.category);

    Object.entries(columnFilters).forEach(([field, selectedValues]) => {
      const castedValues = selectedValues as string[];
      if (castedValues.length > 0) {
        finalRecords = finalRecords.filter(r => castedValues.includes(String(r[field as keyof SalesRecord])));
      }
    });

    return {
      baseRecords,
      totalSales,
      totalQty,
      secondaryDistribution,
      monthlyTrend,
      filterOptions,
      tableRecords: finalRecords.sort((a, b) => b.date.localeCompare(a.date)),
      contextTitle: selectedCustomer ? '品类贡献偏好' : '关联客户贡献排行'
    };
  }, [selectedCategory, selectedItem, selectedCustomer, filteredData, localTableFilters, columnFilters, drillMetric]);

  const handleBarChartClick = (state: any) => {
    if (state && state.activeLabel) {
      const label = state.activeLabel;
      if (selectedCustomer) {
        setLocalTableFilters(prev => ({ ...prev, category: prev.category === label ? '' : label }));
      } else {
        setLocalTableFilters(prev => ({ ...prev, customer: prev.customer === label ? '' : label }));
      }
    }
  };

  const handleTrendClick = (state: any) => {
    if (state && state.activeLabel) {
      const clickedMonth = state.activeLabel;
      setLocalTableFilters(prev => ({ ...prev, month: prev.month === clickedMonth ? '' : clickedMonth }));
    }
  };

  const openCategoryDrillDown = (name: string) => {
    setDrillMetric(pieMetric); 
    setSelectedCategory(name);
    setSelectedItem(null);
    setSelectedCustomer(null);
    setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] });
    setLocalTableFilters({ customer: '', category: '', month: '' });
  };

  const openItemDrillDown = (name: string) => {
    setDrillMetric(itemPieMetric); 
    setSelectedItem(name);
    setSelectedCategory(null);
    setSelectedCustomer(null);
    setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] });
    setLocalTableFilters({ customer: '', category: '', month: '' });
  };

  const openCustomerDrillDown = (name: string) => {
    setDrillMetric(customerMetric);
    setSelectedCustomer(name);
    setSelectedCategory(null);
    setSelectedItem(null);
    setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] });
    setLocalTableFilters({ customer: '', category: '', month: '' });
  };

  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set<string>(filteredData.map(d => d.month))).sort();
    const metrics = !activeMetrics.amount && !activeMetrics.quantity ? { amount: true, quantity: true } : activeMetrics;

    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return {
          name: month,
          amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0),
          quantity: monthRecords.reduce((s, r) => s + r.quantity, 0)
        };
      });
      const series: any[] = [];
      if (metrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (metrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }

    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set<string>(filteredData.map(d => String(d[dimKey])))).slice(0, 8);
    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (metrics.amount) series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor });
      if (metrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
    });

    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });
    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  const customerAnalysisData = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.customer) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.customer, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => customerMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, customerMetric]);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount;
      entry.quantity += d.quantity;
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, itemPieMetric]);

  const formatMetricDisplay = (value: number, metric: 'sales' | 'quantity') => {
    if (metric === 'sales') return `${(value / 1000000).toFixed(2)}M CFA`;
    return `${value.toLocaleString()} UNIT`;
  };

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-RADIAN * midAngle);
    const cos = Math.cos(-RADIAN * midAngle);
    // 增加引导线长度以匹配更大的外径
    const sx = cx + (outerRadius + 10) * cos;
    const sy = cy + (outerRadius + 10) * sin;
    const mx = cx + (outerRadius + 45) * cos;
    const my = cy + (outerRadius + 45) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 22;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={2.5} opacity={0.7} />
        <circle cx={ex} cy={ey} r={4} fill={fill} />
        <text x={ex + (cos >= 0 ? 1 : -1) * 15} y={ey} textAnchor={textAnchor} fill="#0f172a" style={{ fontSize: '14px', fontWeight: 900 }}>{name}</text>
        <text x={ex + (cos >= 0 ? 1 : -1) * 15} y={ey} dy={18} textAnchor={textAnchor} fill="#64748b" style={{ fontSize: '12px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  const TableDropdownFilter = ({ field, label }: { field: string, label: string }) => {
    const options = (drillDownAnalysis.filterOptions as Record<string, string[]>)?.[field] || [];
    const selected = columnFilters[field] || [];
    const isActive = selected.length > 0;
    const menuRef = useRef<HTMLDivElement>(null);
    const [localSearch, setLocalSearch] = useState('');

    useEffect(() => {
      const handleClickOutside = (e: MouseEvent) => {
        if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
          setActiveFilterMenu(null);
        }
      };
      if (activeFilterMenu === field) {
        document.addEventListener('mousedown', handleClickOutside);
      }
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [activeFilterMenu, field]);

    const toggleValue = (val: string) => {
      const next = selected.includes(val) ? selected.filter(v => v !== val) : [...selected, val];
      setColumnFilters(prev => ({ ...prev, [field]: next }));
    };

    const filteredOptions = options.filter(opt => opt.toLowerCase().includes(localSearch.toLowerCase()));

    return (
      <div className="relative inline-block text-left" ref={menuRef}>
        <button 
          onClick={() => {
            setActiveFilterMenu(activeFilterMenu === field ? null : field);
            setLocalSearch('');
          }}
          className={`flex items-center gap-2 px-2 py-1.5 rounded-lg transition-all group ${isActive ? 'bg-indigo-50 text-indigo-700' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100'}`}
        >
          <span className={`text-[10px] font-black uppercase tracking-widest`}>{label}</span>
          <svg className={`w-3 h-3 transition-transform ${activeFilterMenu === field ? 'rotate-180 text-indigo-500' : 'text-slate-300'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
             <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" />
          </svg>
        </button>
        {activeFilterMenu === field && (
          <div className="absolute top-full left-0 mt-2 w-64 bg-white border border-slate-200 shadow-2xl rounded-2xl z-[6000] overflow-hidden animate-in fade-in zoom-in-95 duration-150 origin-top-left">
             <div className="p-3 bg-slate-50 border-b border-slate-100">
                <input 
                  type="text" autoFocus placeholder={`搜索...`} value={localSearch}
                  onChange={(e) => setLocalSearch(e.target.value)}
                  className="w-full px-3 py-2 bg-white border border-slate-200 rounded-xl text-xs outline-none focus:ring-2 focus:ring-indigo-100 font-bold"
                />
             </div>
             <div className="max-h-64 overflow-y-auto p-1.5 custom-scrollbar bg-white">
                <button onClick={() => { setColumnFilters(prev => ({ ...prev, [field]: [] })); setActiveFilterMenu(null); }} className="w-full text-left px-3 py-2.5 text-[10px] font-black text-red-500 hover:bg-red-50 rounded-xl mb-1">重置该列筛选</button>
                {filteredOptions.map(opt => {
                  const isSelected = selected.includes(opt);
                  return (
                    <button key={opt} onClick={() => toggleValue(opt)} className={`w-full text-left px-3 py-2.5 rounded-xl mb-0.5 flex items-center justify-between group ${isSelected ? 'bg-indigo-600 text-white shadow-lg' : 'hover:bg-indigo-50 text-slate-700'}`}>
                      <span className="text-[12px] font-bold truncate pr-2">{opt}</span>
                      {isSelected && <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7" /></svg>}
                    </button>
                  );
                })}
             </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-10 pb-16 relative">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col overflow-hidden">
           <div className="p-6 flex items-center justify-between bg-white border-b border-slate-100">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
                <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">单据总数</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div>
              </div>
              <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2 bg-slate-100 rounded-xl hover:bg-slate-200 transition-all">
                <svg className={`w-5 h-5 transition-transform ${isOrdersExpanded ? 'rotate-180 text-indigo-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
              </button>
           </div>
           {isOrdersExpanded && (
              <div className="px-5 py-5 bg-slate-50/50 border-t border-slate-100 space-y-4 animate-in fade-in slide-in-from-top-2 duration-300">
                <input type="text" placeholder="检索单号..." value={orderSearchTerm} onChange={(e) => setOrderSearchTerm(e.target.value)} className="w-full bg-white border border-slate-300 rounded-lg px-3 py-1.5 text-xs outline-none focus:border-indigo-500 font-bold" />
                <div className="max-h-40 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar pr-1">
                  {summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase())).map(id => (<button key={id} onClick={() => onSelectOrderId(id)} className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-bold hover:border-indigo-500 transition-colors">{id}</button>))}
                </div>
              </div>
           )}
        </div>
      </div>

      {/* 业绩趋势版块 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div 
          onClick={() => toggleSection('trend')}
          className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors"
        >
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 shrink-0">
            <span className="p-2 bg-indigo-50 text-indigo-600 rounded-xl text-lg">📈</span> 业绩增长趋势
          </h3>
          <div className="flex items-center gap-6" onClick={(e) => e.stopPropagation()}>
            {sections.trend && (
              <div className="hidden md:flex flex-wrap items-center gap-4">
                <div className="flex bg-slate-100 p-1 rounded-2xl border border-slate-200 shadow-inner">
                   <button onClick={() => setActiveMetrics({ amount: true, quantity: false })} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${activeMetrics.amount && !activeMetrics.quantity ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>金额</button>
                   <button onClick={() => setActiveMetrics({ amount: false, quantity: true })} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${!activeMetrics.amount && activeMetrics.quantity ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量</button>
                   <button onClick={() => setActiveMetrics({ amount: true, quantity: true })} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${activeMetrics.amount && activeMetrics.quantity ? 'bg-white shadow-md text-slate-900' : 'text-slate-500'}`}>双轴</button>
                </div>
                <div className="flex bg-slate-100 p-1 rounded-2xl border border-slate-200 shadow-inner">
                  <button onClick={() => setTrendMode('total')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'total' ? 'bg-white shadow-md text-slate-900' : 'text-slate-500'}`}>汇总</button>
                  <button onClick={() => setTrendMode('customer')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'customer' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>客户</button>
                  <button onClick={() => setTrendMode('salesperson')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'salesperson' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>销售</button>
                </div>
              </div>
            )}
            <button className="p-2 bg-slate-100 rounded-xl">
              <svg className={`w-5 h-5 transition-transform duration-300 ${sections.trend ? 'rotate-180 text-indigo-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
            </button>
          </div>
        </div>
        {sections.trend && (
          <div className="px-8 pb-8 animate-in fade-in duration-500">
            <div className="h-[450px] w-full mt-4">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={trendAnalysis.data}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11}} />
                  {activeMetrics.amount && <YAxis yAxisId="amount" axisLine={false} tickLine={false} tick={{fill: '#6366f1', fontSize: 10, fontWeight: 700}} tickFormatter={(v) => `${(v / 1000000).toFixed(1)}M`} />}
                  {activeMetrics.quantity && <YAxis yAxisId="quantity" orientation="right" axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 10, fontWeight: 700}} tickFormatter={(v) => v.toLocaleString()} />}
                  <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }} formatter={(value: any, name: string) => [value.toLocaleString(), name]} />
                  <Legend iconType="circle" />
                  {trendAnalysis.series.map((s, i) => (
                    <Area key={s.key} yAxisId={s.type} type="monotone" dataKey={s.key} name={s.name} stroke={s.color} strokeWidth={s.dashed ? 2 : 3} strokeDasharray={s.dashed ? "5 5" : "0"} fill={s.color} fillOpacity={s.dashed ? 0 : 0.08} activeDot={{ r: 6, strokeWidth: 0 }} />
                  ))}
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}
      </section>

      {/* 构成分析版块 - 深度空间优化 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div 
          onClick={() => toggleSection('composition')}
          className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors"
        >
          <div className="flex flex-col gap-1">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 shrink-0">
              <span className="p-2 bg-emerald-50 text-emerald-600 rounded-xl text-lg">🧩</span> 业务构成分析
            </h3>
            {!sections.composition && (
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest pl-12">纵向对比品类与物料明细构成</p>
            )}
          </div>
          <button className="p-2 bg-slate-100 rounded-xl">
            <svg className={`w-5 h-5 transition-transform duration-300 ${sections.composition ? 'rotate-180 text-emerald-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
          </button>
        </div>
        {sections.composition && (
          <div className="px-8 pb-10 animate-in fade-in duration-500">
            <div className="flex flex-col gap-y-32">
              {/* 品类分析 - 空间拉满 */}
              <div className="flex flex-col w-full bg-slate-50/30 p-8 rounded-[40px] border border-slate-100 shadow-inner">
                <div className="flex justify-between items-start mb-8 px-4">
                  <div className="flex flex-col">
                    <h4 className="text-lg font-black text-slate-800 tracking-tight">品类核心构成</h4>
                    <span className={`text-2xl font-black mt-2 ${pieMetric === 'sales' ? 'text-indigo-600' : 'text-emerald-600'}`}>
                      {formatMetricDisplay(sortedCategorySummary.reduce((acc, curr) => acc + (pieMetric === 'sales' ? curr.sales : curr.quantity), 0), pieMetric)}
                    </span>
                  </div>
                  <div className="flex bg-slate-200/50 p-1.5 rounded-2xl shadow-inner">
                    <button onClick={(e) => { e.stopPropagation(); setPieMetric('sales'); }} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${pieMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>金额维度</button>
                    <button onClick={(e) => { e.stopPropagation(); setPieMetric('quantity'); }} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量维度</button>
                  </div>
                </div>
                <div className="h-[600px] w-full relative">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie 
                        data={sortedCategorySummary} 
                        cx="50%" cy="50%" 
                        innerRadius={120} 
                        outerRadius={180} 
                        paddingAngle={5} 
                        dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} 
                        stroke="#fff" 
                        strokeWidth={6} 
                        label={renderCustomizedLabel} 
                        labelLine={false} 
                        onClick={(d) => openCategoryDrillDown(d.name)}
                      >
                        {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} className="cursor-pointer hover:opacity-85 transition-opacity" />)}
                      </Pie>
                      <Tooltip formatter={(v: any) => v.toLocaleString()} contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 25px 50px -12px rgb(0 0 0 / 0.1)' }} />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              </div>

              {/* 物料分析 - 空间拉满 */}
              <div className="flex flex-col w-full bg-slate-50/30 p-8 rounded-[40px] border border-slate-100 shadow-inner">
                <div className="flex justify-between items-start mb-8 px-4">
                  <div className="flex flex-col">
                    <h4 className="text-lg font-black text-slate-800 tracking-tight">物料贡献排行 (TOP 15)</h4>
                    <span className={`text-2xl font-black mt-2 ${itemPieMetric === 'sales' ? 'text-indigo-600' : 'text-emerald-600'}`}>
                      {formatMetricDisplay(sortedItemSummary.slice(0, 15).reduce((acc, curr) => acc + (itemPieMetric === 'sales' ? curr.sales : curr.quantity), 0), itemPieMetric)}
                    </span>
                  </div>
                  <div className="flex bg-slate-200/50 p-1.5 rounded-2xl shadow-inner">
                    <button onClick={(e) => { e.stopPropagation(); setItemPieMetric('sales'); }} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${itemPieMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>金额维度</button>
                    <button onClick={(e) => { e.stopPropagation(); setItemPieMetric('quantity'); }} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${itemPieMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量维度</button>
                  </div>
                </div>
                <div className="h-[600px] w-full relative">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie 
                        data={sortedItemSummary.slice(0, 15)} 
                        cx="50%" cy="50%" 
                        innerRadius={120} 
                        outerRadius={180} 
                        paddingAngle={3} 
                        dataKey={itemPieMetric === 'sales' ? 'sales' : 'quantity'} 
                        stroke="#fff" 
                        strokeWidth={6} 
                        label={renderCustomizedLabel} 
                        labelLine={false} 
                        onClick={(d) => openItemDrillDown(d.name)}
                      >
                        {sortedItemSummary.slice(0, 15).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} className="cursor-pointer hover:opacity-85 transition-opacity" />)}
                      </Pie>
                      <Tooltip formatter={(v: any) => v.toLocaleString()} contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 25px 50px -12px rgb(0 0 0 / 0.1)' }} />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              </div>
            </div>
          </div>
        )}
      </section>

      {/* 客户排行版块 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div 
          onClick={() => toggleSection('ranking')}
          className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors"
        >
          <div className="flex flex-col gap-1">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 shrink-0">
              <span className="p-2 bg-amber-50 text-amber-600 rounded-xl text-lg">👥</span> 客户采购排行
            </h3>
            {!sections.ranking && (
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest pl-12">共分析 {customerAnalysisData.length} 家客户</p>
            )}
          </div>
          <div className="flex items-center gap-6" onClick={(e) => e.stopPropagation()}>
            {sections.ranking && (
              <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200">
                <button onClick={() => setCustomerMetric('sales')} className={`px-6 py-1.5 rounded-xl text-xs font-black transition-all ${customerMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>金额</button>
                <button onClick={() => setCustomerMetric('quantity')} className={`px-6 py-1.5 rounded-xl text-xs font-black transition-all ${customerMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量</button>
              </div>
            )}
            <button className="p-2 bg-slate-100 rounded-xl">
              <svg className={`w-5 h-5 transition-transform duration-300 ${sections.ranking ? 'rotate-180 text-amber-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
            </button>
          </div>
        </div>
        {sections.ranking && (
          <div className="px-8 pb-10 animate-in fade-in duration-500">
            <div className="w-full" style={{ height: `${Math.max(400, customerAnalysisData.length * 48)}px` }}>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={customerAnalysisData} layout="vertical" margin={{ left: 20, right: 120 }}>
                  <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#e2e8f0" />
                  <XAxis type="number" hide />
                  <YAxis type="category" dataKey="name" width={150} axisLine={false} tickLine={false} tick={(props) => (
                      <text {...props} className="fill-slate-600 font-black text-[12px] hover:fill-indigo-600 hover:underline cursor-pointer transition-colors" onClick={() => openCustomerDrillDown(props.payload.value)}>
                        {props.payload.value}
                      </text>
                    )} 
                  />
                  <Tooltip cursor={{ fill: '#f1f5f9', opacity: 0.5 }} contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} />
                  <Bar dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} radius={[0, 10, 10, 0]} barSize={30} onClick={(d) => openCustomerDrillDown(d.name)} className="cursor-pointer">
                    {customerAnalysisData.map((_, index) => <RechartsCell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                    <LabelList dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} position="right" formatter={(v: any) => customerMetric === 'sales' ? `${(v / 1000000).toFixed(2)}M` : v.toLocaleString()} style={{ fill: '#475569', fontSize: '11px', fontWeight: 900, fontFamily: 'monospace' }} />
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}
      </section>

      {/* 深度下钻模态面板保持不变 */}
