                <button onClick={() => { setColumnFilters(prev => ({ ...prev, [field]: [] })); setActiveFilterMenu(null); }} className="w-full text-left px-3 py-2.5 text-[10px] font-black text-red-500 hover:bg-red-50 rounded-xl mb-1">重置该列筛选</button>
