                  <p className={`text-3xl font-black ${isDebtMode ? 'text-rose-600' : 'text-indigo-600'}`}>{isDebtMode ? (drillDownAnalysis.tableTotalUnsettled).toLocaleString() : (drillDownAnalysis.totalSales).toLocaleString()}</p>
                </div>
