                    </div>
                 </div>
                 <div className="overflow-x-auto max-h-[600px] custom-scrollbar">
                    <table className="min-w-full divide-y divide-slate-100">
                       <thead className="bg-white sticky top-0 z-[500] shadow-sm">
                          <tr>
                            <th className="px-8 py-4 text-left"><TableDropdownFilter field="id" label="单号" /></th>
                            <th className="px-8 py-4 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">业务日期</th>
                            {!selectedCustomer && <th className="px-8 py-4 text-left"><TableDropdownFilter field="customer" label="客户" /></th>}
                            <th className="px-8 py-4 text-left"><TableDropdownFilter field="itemName" label="物料" /></th>
