                            <th className="px-8 py-4 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">到期日</th>
                          </tr>
                       </thead>
                       <tbody className="bg-white divide-y divide-slate-50 text-[12px]">
                          {drillDownAnalysis.tableRecords.map((r, i) => {
                            const today = new Date();
                            const dueDate = new Date(r.dueDate);
                            const isOverdue = r.unsettledAmount > 0 && today > dueDate;
                            return (
                              <tr key={`${r.id}-${i}`} className="hover:bg-slate-50 transition-colors">
                                 <td className="px-8 py-4 whitespace-nowrap font-mono font-bold text-indigo-600"><button onClick={() => onSelectOrderId(r.id)} className="hover:underline">{r.id}</button></td>
                                 <td className="px-8 py-4 whitespace-nowrap font-bold text-slate-500">{r.date}</td>
                                 {!selectedCustomer && <td className="px-8 py-4 whitespace-nowrap font-black text-slate-900">{r.customer}</td>}
                                 <td className="px-8 py-4 whitespace-nowrap font-black text-slate-700 truncate max-w-[150px]">{r.itemName}</td>
                                 <td className="px-8 py-4 whitespace-nowrap text-right font-mono font-bold text-slate-400">{r.totalAmount.toLocaleString()}</td>
                                 <td className="px-8 py-4 whitespace-nowrap text-right font-mono font-black text-rose-600">{r.unsettledAmount.toLocaleString()}</td>
                                 <td className={`px-8 py-4 whitespace-nowrap font-bold ${isOverdue ? 'text-rose-500 animate-pulse' : 'text-emerald-500'}`}>
                                    {r.dueDate} {isOverdue && '(逾期)'}
                                 </td>
