                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">涉及业务行数</p>
                  <p className="text-2xl font-black text-slate-900">{drillDownAnalysis.baseRecords.length} Lines</p>
                </div>
