                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">逾期单据数</p>
                  <p className="text-2xl font-black text-rose-600">
                    {drillDownAnalysis.baseRecords.filter(r => {
                      const today = new Date();
                      today.setHours(0,0,0,0);
                      return r.unsettledAmount > 0 && new Date(r.dueDate) < today;
                    }).length}
                  </p>
                </div>
              </div>

              <div className="bg-white rounded-3xl border border-slate-200 shadow-xl overflow-hidden mb-12">
                 <div className={`px-8 py-5 border-b border-slate-100 flex items-center justify-between ${isDebtMode ? 'bg-rose-50' : 'bg-slate-50'}`}>
                    <div className="flex items-center gap-4">
                      <span className={`text-[10px] font-black uppercase tracking-[0.2em] ${isDebtMode ? 'text-rose-600' : 'text-slate-500'}`}>全量穿透清单 (三色预警生效中)</span>
                    </div>
                    <div className="flex items-center gap-2">
                       <div className="flex items-center gap-4 mr-4">
                          <div className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-rose-500 animate-pulse"></div><span className="text-[9px] font-bold text-slate-400 uppercase">红色: 逾期</span></div>
                          <div className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-amber-400"></div><span className="text-[9px] font-bold text-slate-400 uppercase">黄色: 临期7天</span></div>
                          <div className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-emerald-500"></div><span className="text-[9px] font-bold text-slate-400 uppercase">绿色: 安全/结清</span></div>
                       </div>
                       <span className={`text-[10px] font-black px-3 py-1 rounded-lg shadow-sm ${isDebtMode ? 'bg-rose-600 text-white' : 'bg-indigo-600 text-white'}`}>总匹配金额: {drillDownAnalysis.tableTotalSales.toLocaleString()} CFA</span>
                    </div>
                 </div>
                 <div className="overflow-x-auto max-h-[600px] custom-scrollbar">
                    <table className="min-w-full divide-y divide-slate-100">
                       <thead className="bg-white sticky top-0 z-[500] shadow-sm">
                          <tr>
                            <th className="px-8 py-4 text-left"><TableDropdownFilter field="id" label="单号" /></th>
                            <th className="px-8 py-4 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">业务日期</th>
                            {!selectedCustomer && <th className="px-8 py-4 text-left"><TableDropdownFilter field="customer" label="客户" /></th>}
                            <th className="px-8 py-4 text-left"><TableDropdownFilter field="itemName" label="物料" /></th>
                            <th className="px-8 py-4 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">单据总额</th>
                            <th className="px-8 py-4 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">待结算金额</th>
                            <th className="px-8 py-4 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">到期日/状态</th>
                          </tr>
                       </thead>
                       <tbody className="bg-white divide-y divide-slate-50 text-[12px]">
                          {drillDownAnalysis.tableRecords.map((r, i) => {
                            const today = new Date();
                            today.setHours(0, 0, 0, 0);
                            const dueDate = new Date(r.dueDate);
                            const diffTime = dueDate.getTime() - today.getTime();
                            const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

                            let statusColorClass = "text-emerald-500"; // 默认绿色
                            let rowBgClass = "";
                            let statusText = "安全 / 已结清";

                            if (r.unsettledAmount > 0) {
                              if (diffDays < 0) {
                                // 超过到期日 - 红色
                                statusColorClass = "text-rose-600 font-black animate-pulse";
                                rowBgClass = "bg-rose-50/30";
                                statusText = `逾期 ${Math.abs(diffDays)} 天`;
                              } else if (diffDays <= 7) {
                                // 临期7天 - 黄色
                                statusColorClass = "text-amber-500 font-black";
                                rowBgClass = "bg-amber-50/20";
                                statusText = `临期 ${diffDays} 天`;
                              } else {
                                // 大于7天 - 绿色
                                statusColorClass = "text-emerald-600 font-bold";
                                statusText = `剩余 ${diffDays} 天`;
                              }
                            } else {
                              statusText = "已结清";
                            }

                            return (
                              <tr key={`${r.id}-${i}`} className={`hover:bg-slate-50 transition-colors ${rowBgClass}`}>
                                 <td className="px-8 py-4 whitespace-nowrap font-mono font-bold text-indigo-600"><button onClick={() => onSelectOrderId(r.id)} className="hover:underline">{r.id}</button></td>
                                 <td className="px-8 py-4 whitespace-nowrap font-bold text-slate-500">{r.date}</td>
                                 {!selectedCustomer && <td className="px-8 py-4 whitespace-nowrap font-black text-slate-900">{r.customer}</td>}
                                 <td className="px-8 py-4 whitespace-nowrap font-black text-slate-700 truncate max-w-[150px]">{r.itemName}</td>
                                 <td className="px-8 py-4 whitespace-nowrap text-right font-mono font-bold text-slate-400">{r.totalAmount.toLocaleString()}</td>
                                 <td className={`px-8 py-4 whitespace-nowrap text-right font-mono font-black ${r.unsettledAmount > 0 ? 'text-rose-600' : 'text-slate-300'}`}>
                                    {r.unsettledAmount.toLocaleString()}
                                 </td>
                                 <td className={`px-8 py-4 whitespace-nowrap font-bold ${statusColorClass}`}>
                                    <div className="flex flex-col">
                                       <span>{r.dueDate}</span>
                                       <span className="text-[10px] uppercase opacity-70">{statusText}</span>
                                    </div>
                                 </td>
                              </tr>
                            );
                          })}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7', '#fb7185', '#2dd4bf', '#fbbf24'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  const [sections, setSections] = useState({
    trend: true,
    composition: true,
    ranking: true,
    receivables: true
  });

  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [customerMetric, setCustomerMetric] = useState<'sales' | 'quantity'>('sales');
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');

  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<string | null>(null);
  const [drillMetric, setDrillMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [isDebtMode, setIsDebtMode] = useState(false);

  const [localTableFilters, setLocalTableFilters] = useState({
    customer: '', 
    category: '',
    month: '' 
  });

  const [columnFilters, setColumnFilters] = useState<Record<string, string[]>>({
    id: [],
    customer: [],
    salesperson: [],
    itemName: []
  });

  const [activeFilterMenu, setActiveFilterMenu] = useState<string | null>(null);
  const [activeMetrics, setActiveMetrics] = useState({ amount: true, quantity: true });
  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  const toggleSection = (key: keyof typeof sections) => {
    setSections(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- 核心：应付未付情况统计（列出所有欠款客户） ---
  const receivablesAnalysis = useMemo(() => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    let totalSettled = 0;
    let totalUnsettled = 0;

    const agingBuckets = [
      { name: '未到期', value: 0, color: '#10b981' },
      { name: '逾期1-30天', value: 0, color: '#f59e0b' },
      { name: '逾期31-60天', value: 0, color: '#f97316' },
      { name: '逾期60天+', value: 0, color: '#ef4444' }
    ];

    const customerDebtsMap = new Map<string, { settled: number; unsettled: number }>();

    filteredData.forEach(r => {
      totalSettled += r.settledAmount || 0;
      totalUnsettled += r.unsettledAmount || 0;

      const curDebt = customerDebtsMap.get(r.customer) || { settled: 0, unsettled: 0 };
      customerDebtsMap.set(r.customer, {
        settled: curDebt.settled + (r.settledAmount || 0),
        unsettled: curDebt.unsettled + (r.unsettledAmount || 0)
      });

      if (r.unsettledAmount > 0 && r.dueDate) {
        const dueDate = new Date(r.dueDate);
        const diffTime = today.getTime() - dueDate.getTime();
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        if (diffDays <= 0) agingBuckets[0].value += r.unsettledAmount;
        else if (diffDays <= 30) agingBuckets[1].value += r.unsettledAmount;
        else if (diffDays <= 60) agingBuckets[2].value += r.unsettledAmount;
        else agingBuckets[3].value += r.unsettledAmount;
      }
    });

    // 这里移除 .slice(0, 10)，确保列出所有有欠款的客户
    const allDebtors = Array.from(customerDebtsMap.entries())
      .map(([name, val]) => ({ name, settled: val.settled, unsettled: val.unsettled, total: val.settled + val.unsettled }))
      .filter(d => d.unsettled > 0) 
      .sort((a, b) => b.unsettled - a.unsettled);

    return {
      totalSettled,
      totalUnsettled,
      agingBuckets,
      allDebtors,
      composition: [
        { name: '已结算', value: totalSettled, color: '#10b981' },
        { name: '待回款', value: totalUnsettled, color: '#fb7185' }
      ]
    };
  }, [filteredData]);

  // --- 深度下钻分析逻辑 ---
  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : (selectedCustomer ? 'customer' : null));
    const value = selectedCategory || selectedItem || selectedCustomer;

    if (!dimension || !value) return {
      baseRecords: [], totalSales: 0, totalQty: 0, secondaryDistribution: [], monthlyTrend: [], filterOptions: { id: [], customer: [], salesperson: [], itemName: [] }, tableRecords: [], contextTitle: '', tableTotalSales: 0, tableTotalQty: 0, tableTotalUnsettled: 0
    };

    // 此处列出选定维度的所有数据（包括已结清的单据）
    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);

    const totalSales = baseRecords.reduce((s, r) => s + r.totalAmount, 0);
    const totalQty = baseRecords.reduce((s, r) => s + r.quantity, 0);

    const recordsForDist = localTableFilters.month 
      ? baseRecords.filter(r => r.month === localTableFilters.month) 
      : baseRecords;

    const secondaryDim = selectedCustomer ? 'category' : 'customer';
    const distMap = new Map<string, { sales: number; qty: number }>();
    recordsForDist.forEach(r => {
      const key = r[secondaryDim] as string;
      const e = distMap.get(key) || { sales: 0, qty: 0 };
      distMap.set(key, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });
    const secondaryDistribution = Array.from(distMap.entries())
      .map(([name, v]) => ({ name, sales: v.sales, qty: v.qty }))
      .sort((a, b) => drillMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const filterOptions = {
      id: Array.from(new Set(baseRecords.map(r => r.id))).sort(),
      customer: Array.from(new Set(baseRecords.map(r => r.customer))).sort(),
      salesperson: Array.from(new Set(baseRecords.map(r => r.salesperson))).sort(),
      itemName: Array.from(new Set(baseRecords.map(r => r.itemName))).sort()
    };

    let finalRecords = baseRecords;
    if (localTableFilters.month) finalRecords = finalRecords.filter(r => r.month === localTableFilters.month);

    Object.entries(columnFilters).forEach(([field, selectedValues]) => {
      const castedValues = selectedValues as string[];
      if (castedValues.length > 0) {
        finalRecords = finalRecords.filter(r => castedValues.includes(String(r[field as keyof SalesRecord])));
      }
    });

    const tableTotalSales = finalRecords.reduce((acc, cur) => acc + cur.totalAmount, 0);
    const tableTotalUnsettled = finalRecords.reduce((acc, cur) => acc + cur.unsettledAmount, 0);

    return {
      baseRecords,
      totalSales,
      secondaryDistribution,
      filterOptions,
      tableRecords: finalRecords.sort((a, b) => b.date.localeCompare(a.date)),
      tableTotalSales,
      tableTotalUnsettled
    };
  }, [selectedCategory, selectedItem, selectedCustomer, filteredData, localTableFilters, columnFilters, drillMetric]);

  const openCategoryDrillDown = (name: string) => {
    setDrillMetric(pieMetric); 
    setIsDebtMode(false);
    setSelectedCategory(name);
    setSelectedItem(null);
    setSelectedCustomer(null);
    setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] });
    setLocalTableFilters({ customer: '', category: '', month: '' });
  };

  const openItemDrillDown = (name: string) => {
    setDrillMetric(itemPieMetric); 
    setIsDebtMode(false);
    setSelectedItem(name);
    setSelectedCategory(null);
    setSelectedCustomer(null);
    setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] });
    setLocalTableFilters({ customer: '', category: '', month: '' });
  };

  const openCustomerDrillDown = (name: string, debtOnly: boolean = false) => {
    setDrillMetric(customerMetric);
    setIsDebtMode(debtOnly);
    setSelectedCustomer(name);
    setSelectedCategory(null);
    setSelectedItem(null);
    setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] });
    setLocalTableFilters({ customer: '', category: '', month: '' });
  };

  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set<string>(filteredData.map(d => d.month))).sort();
    const metrics = activeMetrics;
    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return {
          name: month,
          amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0),
          quantity: monthRecords.reduce((s, r) => s + r.quantity, 0)
        };
      });
      const series: any[] = [];
      if (metrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (metrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }
    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set<string>(filteredData.map(d => String(d[dimKey])))).slice(0, 8);
    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (metrics.amount) series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor });
      if (metrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
    });
    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });
    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  const customerAnalysisData = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.customer) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount; entry.quantity += d.quantity;
      map.set(d.customer, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => customerMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, customerMetric]);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount; entry.quantity += d.quantity;
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, itemPieMetric]);

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const sx = cx + (outerRadius + 10) * Math.cos(-RADIAN * midAngle);
    const sy = cy + (outerRadius + 10) * Math.sin(-RADIAN * midAngle);
    const mx = cx + (outerRadius + 45) * Math.cos(-RADIAN * midAngle);
    const my = cy + (outerRadius + 45) * Math.sin(-RADIAN * midAngle);
    const ex = mx + (Math.cos(-RADIAN * midAngle) >= 0 ? 1 : -1) * 22;
    const ey = my;
    const textAnchor = Math.cos(-RADIAN * midAngle) >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={2.5} opacity={0.7} />
        <circle cx={ex} cy={ey} r={4} fill={fill} />
        <text x={ex + (Math.cos(-RADIAN * midAngle) >= 0 ? 1 : -1) * 15} y={ey} textAnchor={textAnchor} fill="#0f172a" style={{ fontSize: '14px', fontWeight: 900 }}>{name}</text>
        <text x={ex + (Math.cos(-RADIAN * midAngle) >= 0 ? 1 : -1) * 15} y={ey} dy={18} textAnchor={textAnchor} fill="#64748b" style={{ fontSize: '12px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  const TableDropdownFilter = ({ field, label }: { field: string, label: string }) => {
    const options = (drillDownAnalysis.filterOptions as Record<string, string[]>)?.[field] || [];
    const selected = columnFilters[field] || [];
    const menuRef = useRef<HTMLDivElement>(null);
    const [localSearch, setLocalSearch] = useState('');

    useEffect(() => {
      const handleClickOutside = (e: MouseEvent) => {
        if (menuRef.current && !menuRef.current.contains(e.target as Node)) setActiveFilterMenu(null);
      };
      if (activeFilterMenu === field) document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [activeFilterMenu, field]);

    return (
      <div className="relative inline-block text-left" ref={menuRef}>
        <button onClick={() => { setActiveFilterMenu(activeFilterMenu === field ? null : field); setLocalSearch(''); }} className={`flex items-center gap-2 px-2 py-1.5 rounded-lg transition-all group ${selected.length > 0 ? 'bg-indigo-50 text-indigo-700' : 'text-slate-400 hover:text-slate-600'}`}>
          <span className="text-[10px] font-black uppercase tracking-widest">{label}</span>
          <svg className={`w-3 h-3 ${activeFilterMenu === field ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg>
        </button>
        {activeFilterMenu === field && (
          <div className="absolute top-full left-0 mt-2 w-64 bg-white border border-slate-200 shadow-2xl rounded-2xl z-[6000] overflow-hidden animate-in fade-in zoom-in-95 duration-150 origin-top-left">
             <div className="p-3 bg-slate-50 border-b border-slate-100">
                <input type="text" autoFocus placeholder="搜索..." value={localSearch} onChange={(e) => setLocalSearch(e.target.value)} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-xl text-xs outline-none focus:ring-2 focus:ring-indigo-100 font-bold" />
             </div>
             <div className="max-h-64 overflow-y-auto p-1.5 custom-scrollbar bg-white">
                <button onClick={() => setColumnFilters(prev => ({ ...prev, [field]: [] }))} className="w-full text-left px-3 py-2.5 text-[10px] font-black text-red-500 hover:bg-red-50 rounded-xl mb-1">重置该列</button>
                {options.filter(opt => opt.toLowerCase().includes(localSearch.toLowerCase())).map(opt => {
                  const isSelected = selected.includes(opt);
                  return (
                    <button key={opt} onClick={() => setColumnFilters(prev => ({ ...prev, [field]: isSelected ? selected.filter(v => v !== opt) : [...selected, opt] }))} className={`w-full text-left px-3 py-2.5 rounded-xl mb-0.5 flex items-center justify-between ${isSelected ? 'bg-indigo-600 text-white' : 'hover:bg-indigo-50 text-slate-700'}`}>
                      <span className="text-[12px] font-bold truncate">{opt}</span>
                      {isSelected && <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7" /></svg>}
                    </button>
                  );
                })}
             </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-10 pb-16 relative text-left">
      {/* 顶部指标卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col overflow-hidden">
           <div className="p-6 flex items-center justify-between bg-white border-b border-slate-100">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
                <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">单据总数</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div>
              </div>
              <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${isOrdersExpanded ? 'rotate-180 text-indigo-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
           </div>
           {isOrdersExpanded && (
              <div className="px-5 py-5 bg-slate-50/50 border-t border-slate-100 space-y-4 animate-in fade-in duration-300">
                <input type="text" placeholder="检索单号..." value={orderSearchTerm} onChange={(e) => setOrderSearchTerm(e.target.value)} className="w-full bg-white border border-slate-300 rounded-lg px-3 py-1.5 text-xs outline-none focus:border-indigo-500 font-bold" />
                <div className="max-h-40 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar">
                  {summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase())).map(id => (<button key={id} onClick={() => onSelectOrderId(id)} className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-bold hover:border-indigo-500">{id}</button>))}
                </div>
              </div>
           )}
        </div>
      </div>

      {/* 业绩趋势图表 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div onClick={() => toggleSection('trend')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3">
            <span className="p-2 bg-indigo-50 text-indigo-600 rounded-xl text-lg">📈</span> 业绩增长趋势
          </h3>
          <div className="flex items-center gap-4" onClick={(e) => e.stopPropagation()}>
            <div className="flex bg-slate-100 p-1 rounded-2xl border border-slate-200">
              <button onClick={() => setTrendMode('total')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'total' ? 'bg-white shadow-md text-slate-900' : 'text-slate-500'}`}>汇总</button>
              <button onClick={() => setTrendMode('customer')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'customer' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>客户</button>
              <button onClick={() => setTrendMode('salesperson')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'salesperson' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>销售员</button>
            </div>
          </div>
        </div>
        {sections.trend && (
          <div className="px-8 pb-8 animate-in fade-in duration-500 h-[450px]">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendAnalysis.data}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11}} />
                {activeMetrics.amount && <YAxis yAxisId="amount" axisLine={false} tickLine={false} tick={{fill: '#6366f1', fontSize: 10, fontWeight: 700}} tickFormatter={(v) => `${(v / 1000000).toFixed(1)}M`} />}
                {activeMetrics.quantity && <YAxis yAxisId="quantity" orientation="right" axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 10, fontWeight: 700}} />}
                <Tooltip />
                <Legend />
                {trendAnalysis.series.map((s) => (
                  <Area key={s.key} yAxisId={s.type} type="monotone" dataKey={s.key} name={s.name} stroke={s.color} strokeWidth={3} fill={s.color} fillOpacity={0.08} />
                ))}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        )}
      </section>

      {/* 构成分析 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div onClick={() => toggleSection('composition')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3">
            <span className="p-2 bg-emerald-50 text-emerald-600 rounded-xl text-lg">🧩</span> 业务构成分析
          </h3>
          <button className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform duration-300 ${sections.composition ? 'rotate-180 text-emerald-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
        </div>
        {sections.composition && (
          <div className="px-8 pb-10 space-y-24">
             <div className="bg-slate-50/30 p-8 rounded-[40px] border border-slate-100">
                <div className="flex justify-between items-start mb-8 px-4">
                  <div>
                    <h4 className="text-lg font-black text-slate-800">品类构成</h4>
                    <span className="text-2xl font-black mt-2 text-indigo-600">{(sortedCategorySummary.reduce((acc, c) => acc + (pieMetric === 'sales' ? c.sales : c.quantity), 0) / 1000000).toFixed(2)}M CFA</span>
                  </div>
                  <div className="flex bg-slate-200/50 p-1.5 rounded-2xl shadow-inner">
                    <button onClick={() => setPieMetric('sales')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${pieMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>金额</button>
                    <button onClick={() => setPieMetric('quantity')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量</button>
                  </div>
                </div>
                <div className="h-[500px] w-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie data={sortedCategorySummary} cx="50%" cy="50%" innerRadius={100} outerRadius={160} paddingAngle={5} dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} stroke="#fff" strokeWidth={6} label={renderCustomizedLabel} labelLine={false} onClick={(d) => openCategoryDrillDown(d.name)}>
                        {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                      </Pie>
                      <Tooltip />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
             </div>
          </div>
        )}
      </section>

      {/* 应付未付情况统计 - 修改为列出所有客户 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden border-l-8 border-l-rose-500">
        <div onClick={() => toggleSection('receivables')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors">
          <div className="flex flex-col gap-1">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-3">
              <span className="p-2 bg-rose-50 text-rose-600 rounded-xl text-lg">📅</span> 应付未付情况统计
            </h3>
            {sections.receivables && <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest pl-12">当前欠款客户总数: {receivablesAnalysis.allDebtors.length} 个</p>}
          </div>
          <button className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform duration-300 ${sections.receivables ? 'rotate-180 text-rose-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
        </div>
        {sections.receivables && (
          <div className="px-8 pb-10 space-y-12 animate-in fade-in duration-500">
             <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                <div className="bg-slate-50/50 p-8 rounded-[32px] border border-slate-100 flex items-center gap-10">
                   <div className="w-48 h-48 flex-shrink-0">
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie data={receivablesAnalysis.composition} innerRadius={60} outerRadius={80} paddingAngle={10} dataKey="value" stroke="none">
                            {receivablesAnalysis.composition.map((entry, i) => <RechartsCell key={i} fill={entry.color} />)}
                          </Pie>
                          <Tooltip />
                        </PieChart>
                      </ResponsiveContainer>
                   </div>
                   <div className="flex-1 space-y-6">
                      <div><h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">已结算累计</h4><p className="text-2xl font-black text-emerald-600">{receivablesAnalysis.totalSettled.toLocaleString()} CFA</p></div>
                      <div><h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">待结算合计</h4><p className="text-2xl font-black text-rose-600">{receivablesAnalysis.totalUnsettled.toLocaleString()} CFA</p></div>
                   </div>
                </div>
                <div className="bg-slate-50/50 p-8 rounded-[32px] border border-slate-100 h-60">
                   <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">账期分布情况</h4>
                   <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={receivablesAnalysis.agingBuckets}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700}} />
                        <YAxis hide />
                        <Tooltip />
                        <Bar dataKey="value" radius={[8, 8, 0, 0]} barSize={40}>
                           {receivablesAnalysis.agingBuckets.map((entry, i) => <RechartsCell key={i} fill={entry.color} />)}
                           <LabelList dataKey="value" position="top" formatter={(v: any) => `${(v/1000000).toFixed(1)}M`} style={{fontSize: 10, fontWeight: 900, fill: '#64748b'}} />
                        </Bar>
                      </BarChart>
                   </ResponsiveContainer>
                </div>
             </div>

             <div className="bg-white rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
                <div className="px-8 py-5 bg-slate-50 border-b border-slate-100 flex items-center justify-between">
                   <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">所有欠款客户明细表 (共 {receivablesAnalysis.allDebtors.length} 户)</span>
                </div>
                <div className="overflow-x-auto max-h-[500px] custom-scrollbar">
                   <table className="min-w-full divide-y divide-slate-100">
                      <thead className="bg-slate-50 sticky top-0 z-[10]">
                         <tr>
                            <th className="px-8 py-4 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">客户名称</th>
                            <th className="px-8 py-4 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">待结算金额 (CFA)</th>
                            <th className="px-8 py-4 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">结算进度</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                         {receivablesAnalysis.allDebtors.map((debtor) => {
                           const ratio = (debtor.settled / debtor.total) * 100;
                           return (
                             <tr key={debtor.name} className="hover:bg-slate-50 transition-colors cursor-pointer group" onClick={() => openCustomerDrillDown(debtor.name, true)}>
                               <td className="px-8 py-4 text-sm font-black text-slate-800">{debtor.name}</td>
                               <td className="px-8 py-4 text-sm font-mono font-black text-rose-600 text-right">{debtor.unsettled.toLocaleString()}</td>
                               <td className="px-8 py-4">
                                  <div className="flex items-center gap-3">
                                    <div className="flex-1 h-2 bg-slate-100 rounded-full overflow-hidden">
                                      <div className="h-full bg-emerald-500" style={{ width: `${ratio}%` }}></div>
                                    </div>
                                    <span className="text-[10px] font-black text-slate-500 font-mono">{ratio.toFixed(0)}%</span>
                                  </div>
                               </td>
                             </tr>
                           );
                         })}
                      </tbody>
                   </table>
                </div>
             </div>
          </div>
        )}
      </section>

      {/* 深度下钻分析模态面板 */}
      {(selectedCategory || selectedItem || selectedCustomer) && (
        <div className="fixed inset-0 bg-white z-[5000] flex flex-col animate-in slide-in-from-bottom-10 duration-500 overflow-hidden text-left">
           <div className={`px-10 py-6 border-b border-slate-200 bg-white flex items-center justify-between shadow-sm z-10 ${isDebtMode ? 'border-t-8 border-t-rose-500' : ''}`}>
              <div className="flex items-center gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-white shadow-xl ${isDebtMode ? 'bg-rose-600' : 'bg-indigo-600'}`}>
                  {isDebtMode ? <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg> : <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>}
                </div>
                <div>
                  <h3 className="text-2xl font-black text-slate-900 tracking-tight">{selectedCategory || selectedItem || selectedCustomer} <span className="text-slate-300">|</span> <span className={isDebtMode ? 'text-rose-600' : 'text-indigo-600'}>{isDebtMode ? '应付未付深度分析' : '业务明细分析'}</span></h3>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">包含所有历史记录，并启用红黄绿三色账期预警</p>
                </div>
              </div>
              <button onClick={() => { setSelectedCategory(null); setSelectedItem(null); setSelectedCustomer(null); setIsDebtMode(false); setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] }); }} className="px-10 py-3 bg-slate-900 text-white rounded-2xl text-xs font-black hover:bg-slate-800 transition-all">关闭面板</button>
           </div>

           <div className="flex-1 overflow-y-auto custom-scrollbar p-10 bg-slate-50/30 space-y-10">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">累计成交总额</p>
                  <p className="text-2xl font-black text-indigo-600">{drillDownAnalysis.totalSales.toLocaleString()} CFA</p>
                </div>
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                  <p className="text-[10px] font-black text-rose-500 uppercase tracking-widest mb-1">待结算合计 (风险)</p>
                  <p className="text-2xl font-black text-rose-600">{drillDownAnalysis.tableTotalUnsettled.toLocaleString()} CFA</p>
                </div>
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                   <div className="flex items-center gap-4 mb-3">
                      <div className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-rose-500 animate-pulse"></div><span className="text-[9px] font-bold text-slate-400 uppercase">红色: 逾期</span></div>
                      <div className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-amber-400"></div><span className="text-[9px] font-bold text-slate-400 uppercase">黄色: 临期7天</span></div>
                      <div className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-emerald-500"></div><span className="text-[9px] font-bold text-slate-400 uppercase">绿色: 安全</span></div>
                   </div>
                   <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">预警系统说明</p>
                </div>
              </div>

              <div className="bg-white rounded-3xl border border-slate-200 shadow-xl overflow-hidden">
                 <div className="px-8 py-5 border-b border-slate-100 flex items-center justify-between bg-slate-50">
                    <span className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500">全量穿透列表 (含已结清单据)</span>
                 </div>
                 <div className="overflow-x-auto max-h-[600px] custom-scrollbar">
                    <table className="min-w-full divide-y divide-slate-100">
                       <thead className="bg-white sticky top-0 z-[100] shadow-sm">
                          <tr>
                            <th className="px-8 py-4 text-left"><TableDropdownFilter field="id" label="单号" /></th>
                            <th className="px-8 py-4 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">业务日期</th>
                            {!selectedCustomer && <th className="px-8 py-4 text-left"><TableDropdownFilter field="customer" label="客户" /></th>}
                            <th className="px-8 py-4 text-left"><TableDropdownFilter field="itemName" label="物料" /></th>
                            <th className="px-8 py-4 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">单据金额</th>
                            <th className="px-8 py-4 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">待结金额</th>
                            <th className="px-8 py-4 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">状态预警</th>
                          </tr>
                       </thead>
                       <tbody className="bg-white divide-y divide-slate-50 text-[12px]">
                          {drillDownAnalysis.tableRecords.map((r, i) => {
                            const today = new Date(); today.setHours(0, 0, 0, 0);
                            const dueDate = new Date(r.dueDate);
                            const diffDays = Math.ceil((dueDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));

                            let colorClass = "text-emerald-500";
                            let statusText = "已结清";
                            let dotColor = "bg-emerald-500";

                            if (r.unsettledAmount > 0) {
                              if (diffDays < 0) {
                                colorClass = "text-rose-600 font-black";
                                statusText = `已逾期 ${Math.abs(diffDays)} 天`;
                                dotColor = "bg-rose-500 animate-pulse";
                              } else if (diffDays <= 7) {
                                colorClass = "text-amber-500 font-black";
                                statusText = `临期 ${diffDays} 天`;
                                dotColor = "bg-amber-400";
                              } else {
                                colorClass = "text-emerald-600 font-bold";
                                statusText = `剩余 ${diffDays} 天`;
                                dotColor = "bg-emerald-500";
                              }
                            }

                            return (
                              <tr key={`${r.id}-${i}`} className="hover:bg-slate-50 transition-colors">
                                 <td className="px-8 py-4 whitespace-nowrap font-mono font-bold text-indigo-600"><button onClick={() => onSelectOrderId(r.id)} className="hover:underline">{r.id}</button></td>
                                 <td className="px-8 py-4 whitespace-nowrap font-bold text-slate-500">{r.date}</td>
                                 {!selectedCustomer && <td className="px-8 py-4 whitespace-nowrap font-black text-slate-900">{r.customer}</td>}
                                 <td className="px-8 py-4 whitespace-nowrap font-black text-slate-700 truncate max-w-[150px]">{r.itemName}</td>
                                 <td className="px-8 py-4 whitespace-nowrap text-right font-mono font-bold text-slate-400">{r.totalAmount.toLocaleString()}</td>
                                 <td className={`px-8 py-4 whitespace-nowrap text-right font-mono font-black ${r.unsettledAmount > 0 ? 'text-rose-600' : 'text-slate-300'}`}>{r.unsettledAmount.toLocaleString()}</td>
                                 <td className={`px-8 py-4 whitespace-nowrap ${colorClass}`}>
                                    <div className="flex items-center gap-2">
                                       <div className={`w-2 h-2 rounded-full ${dotColor}`}></div>
                                       <div className="flex flex-col">
                                          <span className="font-bold">{statusText}</span>
                                          <span className="text-[10px] opacity-60">到期: {r.dueDate}</span>
                                       </div>
                                    </div>
                                 </td>
                              </tr>
                            );
                          })}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7', '#fb7185', '#2dd4bf', '#fbbf24'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  // 版块折叠状态
  const [sections, setSections] = useState({
    trend: true,
    composition: true,
    ranking: true,
    receivables: true
  });

  // 全局展示状态
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [customerMetric, setCustomerMetric] = useState<'sales' | 'quantity'>('sales');
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');

  // 深度分析联动状态
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<string | null>(null);
  const [drillMetric, setDrillMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [isDebtMode, setIsDebtMode] = useState(false); // 是否处于债务审计模式

  const [localTableFilters, setLocalTableFilters] = useState({
    customer: '', 
    category: '',
    month: '' 
  });

  // 明细表内部表头多选筛选状态
  const [columnFilters, setColumnFilters] = useState<Record<string, string[]>>({
    id: [],
    customer: [],
    salesperson: [],
    itemName: []
  });

  const [activeFilterMenu, setActiveFilterMenu] = useState<string | null>(null);
  const [activeMetrics, setActiveMetrics] = useState({ amount: true, quantity: true });
  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  // 切换折叠
  const toggleSection = (key: keyof typeof sections) => {
    setSections(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- 应付未付情况统计数据计算 (展示所有欠款客户) ---
  const receivablesAnalysis = useMemo(() => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    let totalSettled = 0;
    let totalUnsettled = 0;

    const agingBuckets = [
      { name: '未到期', value: 0, color: '#10b981' },
      { name: '逾期1-30天', value: 0, color: '#f59e0b' },
      { name: '逾期31-60天', value: 0, color: '#f97316' },
      { name: '逾期60天+', value: 0, color: '#ef4444' }
    ];

    const customerDebtsMap = new Map<string, { settled: number; unsettled: number }>();

    filteredData.forEach(r => {
      totalSettled += r.settledAmount || 0;
      totalUnsettled += r.unsettledAmount || 0;

      const curDebt = customerDebtsMap.get(r.customer) || { settled: 0, unsettled: 0 };
      customerDebtsMap.set(r.customer, {
        settled: curDebt.settled + (r.settledAmount || 0),
        unsettled: curDebt.unsettled + (r.unsettledAmount || 0)
      });

      if (r.unsettledAmount > 0 && r.dueDate) {
        const dueDate = new Date(r.dueDate);
        const diffTime = today.getTime() - dueDate.getTime();
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        if (diffDays <= 0) agingBuckets[0].value += r.unsettledAmount;
        else if (diffDays <= 30) agingBuckets[1].value += r.unsettledAmount;
        else if (diffDays <= 60) agingBuckets[2].value += r.unsettledAmount;
        else agingBuckets[3].value += r.unsettledAmount;
      }
    });

    const allDebtors = Array.from(customerDebtsMap.entries())
      .map(([name, val]) => ({ name, settled: val.settled, unsettled: val.unsettled, total: val.settled + val.unsettled }))
      .filter(d => d.unsettled > 0) 
      .sort((a, b) => b.unsettled - a.unsettled);

    return {
      totalSettled,
      totalUnsettled,
      agingBuckets,
      allDebtors,
      composition: [
        { name: '已结算', value: totalSettled, color: '#10b981' },
        { name: '待回款', value: totalUnsettled, color: '#fb7185' }
      ]
    };
  }, [filteredData]);

  // --- 响应式计算链 (双向联动逻辑) ---
  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : (selectedCustomer ? 'customer' : null));
    const value = selectedCategory || selectedItem || selectedCustomer;

    if (!dimension || !value) return {
      baseRecords: [], totalSales: 0, totalQty: 0, secondaryDistribution: [], monthlyTrend: [], filterOptions: { id: [], customer: [], salesperson: [], itemName: [] }, tableRecords: [], contextTitle: '', tableTotalSales: 0, tableTotalQty: 0, tableTotalUnsettled: 0
    };

    // 显示该维度下的所有数据，含已结清单据
    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);

    const totalSales = baseRecords.reduce((s, r) => s + r.totalAmount, 0);
    const totalQty = baseRecords.reduce((s, r) => s + r.quantity, 0);

    const recordsForDist = localTableFilters.month 
      ? baseRecords.filter(r => r.month === localTableFilters.month) 
      : baseRecords;

    const secondaryDim = selectedCustomer ? 'category' : 'customer';
    const distMap = new Map<string, { sales: number; qty: number }>();
    recordsForDist.forEach(r => {
      const key = r[secondaryDim] as string;
      const e = distMap.get(key) || { sales: 0, qty: 0 };
      distMap.set(key, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });
    const secondaryDistribution = Array.from(distMap.entries())
      .map(([name, v]) => ({ name, sales: v.sales, qty: v.qty }))
      .sort((a, b) => drillMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    const filterOptions = {
      id: Array.from(new Set(baseRecords.map(r => r.id))).sort(),
      customer: Array.from(new Set(baseRecords.map(r => r.customer))).sort(),
      salesperson: Array.from(new Set(baseRecords.map(r => r.salesperson))).sort(),
      itemName: Array.from(new Set(baseRecords.map(r => r.itemName))).sort()
    };

    let finalRecords = baseRecords;
    if (localTableFilters.month) finalRecords = finalRecords.filter(r => r.month === localTableFilters.month);

    Object.entries(columnFilters).forEach(([field, selectedValues]) => {
      const castedValues = selectedValues as string[];
      if (castedValues.length > 0) {
        finalRecords = finalRecords.filter(r => castedValues.includes(String(r[field as keyof SalesRecord])));
      }
    });

    const tableTotalSales = finalRecords.reduce((acc, cur) => acc + cur.totalAmount, 0);
    const tableTotalUnsettled = finalRecords.reduce((acc, cur) => acc + cur.unsettledAmount, 0);

    return {
      baseRecords,
      totalSales,
      secondaryDistribution,
      filterOptions,
      tableRecords: finalRecords.sort((a, b) => b.date.localeCompare(a.date)),
      tableTotalSales,
      tableTotalUnsettled
    };
  }, [selectedCategory, selectedItem, selectedCustomer, filteredData, localTableFilters, columnFilters, drillMetric]);

  const openCategoryDrillDown = (name: string) => {
    setDrillMetric(pieMetric); 
    setIsDebtMode(false);
    setSelectedCategory(name);
    setSelectedItem(null);
    setSelectedCustomer(null);
    setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] });
    setLocalTableFilters({ customer: '', category: '', month: '' });
  };

  const openItemDrillDown = (name: string) => {
    setDrillMetric(itemPieMetric); 
    setIsDebtMode(false);
    setSelectedItem(name);
    setSelectedCategory(null);
    setSelectedCustomer(null);
    setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] });
    setLocalTableFilters({ customer: '', category: '', month: '' });
  };

  const openCustomerDrillDown = (name: string, debtOnly: boolean = false) => {
    setDrillMetric(customerMetric);
    setIsDebtMode(debtOnly);
    setSelectedCustomer(name);
    setSelectedCategory(null);
    setSelectedItem(null);
    setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] });
    setLocalTableFilters({ customer: '', category: '', month: '' });
  };

  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set<string>(filteredData.map(d => d.month))).sort();
    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return {
          name: month,
          amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0),
          quantity: monthRecords.reduce((s, r) => s + r.quantity, 0)
        };
      });
      const series: any[] = [];
      if (activeMetrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (activeMetrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }
    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set<string>(filteredData.map(d => String(d[dimKey])))).slice(0, 8);
    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (activeMetrics.amount) series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor });
      if (activeMetrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
    });
    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });
    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  const customerAnalysisData = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.customer) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount; entry.quantity += d.quantity;
      map.set(d.customer, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => customerMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, customerMetric]);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const sx = cx + (outerRadius + 10) * Math.cos(-RADIAN * midAngle);
    const sy = cy + (outerRadius + 10) * Math.sin(-RADIAN * midAngle);
    const mx = cx + (outerRadius + 45) * Math.cos(-RADIAN * midAngle);
    const my = cy + (outerRadius + 45) * Math.sin(-RADIAN * midAngle);
    const ex = mx + (Math.cos(-RADIAN * midAngle) >= 0 ? 1 : -1) * 22;
    const ey = my;
    const textAnchor = Math.cos(-RADIAN * midAngle) >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={2.5} opacity={0.7} />
        <circle cx={ex} cy={ey} r={4} fill={fill} />
        <text x={ex + (Math.cos(-RADIAN * midAngle) >= 0 ? 1 : -1) * 15} y={ey} textAnchor={textAnchor} fill="#0f172a" style={{ fontSize: '14px', fontWeight: 900 }}>{name}</text>
        <text x={ex + (Math.cos(-RADIAN * midAngle) >= 0 ? 1 : -1) * 15} y={ey} dy={18} textAnchor={textAnchor} fill="#64748b" style={{ fontSize: '12px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  const TableDropdownFilter = ({ field, label }: { field: string, label: string }) => {
    const options = (drillDownAnalysis.filterOptions as Record<string, string[]>)?.[field] || [];
    const selected = columnFilters[field] || [];
    const menuRef = useRef<HTMLDivElement>(null);
    const [localSearch, setLocalSearch] = useState('');

    useEffect(() => {
      const handleClickOutside = (e: MouseEvent) => {
        if (menuRef.current && !menuRef.current.contains(e.target as Node)) setActiveFilterMenu(null);
      };
      if (activeFilterMenu === field) document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [activeFilterMenu, field]);

    return (
      <div className="relative inline-block text-left" ref={menuRef}>
        <button onClick={() => { setActiveFilterMenu(activeFilterMenu === field ? null : field); setLocalSearch(''); }} className={`flex items-center gap-2 px-2 py-1.5 rounded-lg transition-all group ${selected.length > 0 ? 'bg-indigo-50 text-indigo-700' : 'text-slate-400 hover:text-slate-600'}`}>
          <span className="text-[10px] font-black uppercase tracking-widest">{label}</span>
          <svg className={`w-3 h-3 ${activeFilterMenu === field ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg>
        </button>
        {activeFilterMenu === field && (
          <div className="absolute top-full left-0 mt-2 w-64 bg-white border border-slate-200 shadow-2xl rounded-2xl z-[6000] overflow-hidden animate-in fade-in zoom-in-95 duration-150 origin-top-left">
             <div className="p-3 bg-slate-50 border-b border-slate-100">
                <input type="text" autoFocus placeholder="搜索..." value={localSearch} onChange={(e) => setLocalSearch(e.target.value)} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-xl text-xs outline-none focus:ring-2 focus:ring-indigo-100 font-bold" />
             </div>
             <div className="max-h-64 overflow-y-auto p-1.5 custom-scrollbar bg-white">
                <button onClick={() => setColumnFilters(prev => ({ ...prev, [field]: [] }))} className="w-full text-left px-3 py-2.5 text-[10px] font-black text-red-500 hover:bg-red-50 rounded-xl mb-1">重置该列</button>
                {options.filter(opt => opt.toLowerCase().includes(localSearch.toLowerCase())).map(opt => {
                  const isSelected = selected.includes(opt);
                  return (
                    <button key={opt} onClick={() => setColumnFilters(prev => ({ ...prev, [field]: isSelected ? selected.filter(v => v !== opt) : [...selected, opt] }))} className={`w-full text-left px-3 py-2.5 rounded-xl mb-0.5 flex items-center justify-between ${isSelected ? 'bg-indigo-600 text-white' : 'hover:bg-indigo-50 text-slate-700'}`}>
                      <span className="text-[12px] font-bold truncate">{opt}</span>
                      {isSelected && <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7" /></svg>}
                    </button>
                  );
                })}
             </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-10 pb-16 relative text-left">
