              <span className="p-2 bg-rose-50 text-rose-600 rounded-xl text-lg">📅</span> 应付未付情况统计
            </h3>
            {sections.receivables && <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest pl-12">实时审计：当前共有 {receivablesAnalysis.allDebtors.length} 户存在待收账款</p>}
          </div>
