        </div>
        {sections.receivables && (
          <div className="px-8 pb-10 space-y-12 animate-in fade-in duration-500">
             <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                <div className="bg-slate-50/50 p-8 rounded-[32px] border border-slate-100 flex items-center gap-10">
                   <div className="w-44 h-44 flex-shrink-0">
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie data={receivablesAnalysis.composition} innerRadius={60} outerRadius={80} paddingAngle={10} dataKey="value" stroke="none">
