                      </ResponsiveContainer>
                   </div>
                   <div className="flex-1 space-y-6">
                      <div><h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">已结算累计</h4><p className="text-2xl font-black text-emerald-600">{receivablesAnalysis.totalSettled.toLocaleString()} CFA</p></div>
                      <div><h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">待结算总额 (风险)</h4><p className="text-2xl font-black text-rose-600">{receivablesAnalysis.totalUnsettled.toLocaleString()} CFA</p></div>
                   </div>
                </div>
                <div className="bg-slate-50/50 p-8 rounded-[32px] border border-slate-100 h-64">
                   <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">待收账款账期分布</h4>
                   <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={receivablesAnalysis.agingBuckets}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700}} />
