                        <Tooltip />
                        <Bar dataKey="value" radius={[8, 8, 0, 0]} barSize={40}>
                           {receivablesAnalysis.agingBuckets.map((entry, i) => <RechartsCell key={i} fill={entry.color} />)}
                           <LabelList dataKey="value" position="top" formatter={(v: any) => `${(v/1000000).toFixed(1)}M`} style={{fontSize: 10, fontWeight: 900, fill: '#64748b'}} />
                        </Bar>
                      </BarChart>
                   </ResponsiveContainer>
                </div>
             </div>

             <div className="bg-white rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
                <div className="px-8 py-5 bg-slate-50 border-b border-slate-100 flex items-center justify-between">
                   <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">所有欠款客户明细表 (点击查看穿透账单)</span>
