              <button onClick={() => { setSelectedCategory(null); setSelectedItem(null); setSelectedCustomer(null); setIsDebtMode(false); setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] }); }} className="px-10 py-3 bg-slate-900 text-white rounded-2xl text-xs font-black hover:bg-slate-800 transition-all shadow-lg">关闭面板</button>
           </div>

           <div className="flex-1 overflow-y-auto custom-scrollbar p-10 bg-slate-50/30 space-y-10">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">累计成交金额</p>
                  <p className="text-2xl font-black text-indigo-600">{drillDownAnalysis.totalSales.toLocaleString()} CFA</p>
                </div>
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                  <p className="text-[10px] font-black text-rose-500 uppercase tracking-widest mb-1">待结算总额 (风险点)</p>
                  <p className="text-2xl font-black text-rose-600">{drillDownAnalysis.tableTotalUnsettled.toLocaleString()} CFA</p>
                </div>
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm col-span-2">
                   <div className="flex items-center gap-8 h-full">
                      <div className="flex items-center gap-2"><div className="w-3 h-3 rounded-full bg-rose-500 animate-pulse"></div><span className="text-[11px] font-black text-slate-500 uppercase">红色: 已逾期</span></div>
                      <div className="flex items-center gap-2"><div className="w-3 h-3 rounded-full bg-amber-400"></div><span className="text-[11px] font-black text-slate-500 uppercase">黄色: 7天内到期</span></div>
                      <div className="flex items-center gap-2"><div className="w-3 h-3 rounded-full bg-emerald-500"></div><span className="text-[11px] font-black text-slate-500 uppercase">绿色: 安全/结清</span></div>
                   </div>
                </div>
              </div>

              <div className="bg-white rounded-3xl border border-slate-200 shadow-xl overflow-hidden">
                 <div className="px-8 py-5 border-b border-slate-100 flex items-center justify-between bg-slate-50">
                    <span className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500">业务明细清单 (全量展示 & 状态预警)</span>
                 </div>
                 <div className="overflow-x-auto max-h-[650px] custom-scrollbar relative">
                    <table className="min-w-full divide-y divide-slate-100">
                       <thead className="bg-white sticky top-0 z-[100] shadow-sm">
                          <tr>
                            <th className="px-8 py-4 text-left"><TableDropdownFilter field="id" label="单号" /></th>
                            <th className="px-8 py-4 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">日期</th>
                            {!selectedCustomer && <th className="px-8 py-4 text-left"><TableDropdownFilter field="customer" label="客户" /></th>}
                            <th className="px-8 py-4 text-left"><TableDropdownFilter field="itemName" label="物料" /></th>
                            <th className="px-8 py-4 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">单据金额</th>
                            <th className="px-8 py-4 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">待结算金额</th>
                            <th className="px-8 py-4 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">到期分析</th>
                          </tr>
                       </thead>
                       <tbody className="bg-white divide-y divide-slate-50 text-[12px]">
                          {drillDownAnalysis.tableRecords.map((r, i) => {
                            const today = new Date(); today.setHours(0, 0, 0, 0);
                            const dueDate = new Date(r.dueDate);
                            const diffDays = Math.ceil((dueDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));

                            let colorClass = "text-emerald-500";
                            let statusText = "已结清 / 安全";
                            let dotColor = "bg-emerald-500";

                            if (r.unsettledAmount > 0) {
                              if (diffDays < 0) {
                                colorClass = "text-rose-600 font-black";
                                statusText = `已逾期 ${Math.abs(diffDays)} 天`;
                                dotColor = "bg-rose-500 animate-pulse";
                              } else if (diffDays <= 7) {
                                colorClass = "text-amber-500 font-black";
                                statusText = `临期 ${diffDays} 天`;
                                dotColor = "bg-amber-400";
                              } else {
                                colorClass = "text-emerald-600 font-bold";
                                statusText = `剩余 ${diffDays} 天`;
                                dotColor = "bg-emerald-500";
                              }
                            } else {
                              statusText = "款项已结清";
                            }

                            return (
                              <tr key={`${r.id}-${i}`} className="hover:bg-slate-50 transition-colors">
                                 <td className="px-8 py-4 whitespace-nowrap font-mono font-bold text-indigo-600"><button onClick={() => onSelectOrderId(r.id)} className="hover:underline">{r.id}</button></td>
                                 <td className="px-8 py-4 whitespace-nowrap font-bold text-slate-500">{r.date}</td>
                                 {!selectedCustomer && <td className="px-8 py-4 whitespace-nowrap font-black text-slate-900">{r.customer}</td>}
                                 <td className="px-8 py-4 whitespace-nowrap font-black text-slate-700 truncate max-w-[180px]">{r.itemName}</td>
                                 <td className="px-8 py-4 whitespace-nowrap text-right font-mono font-bold text-slate-400">{r.totalAmount.toLocaleString()}</td>
                                 <td className={`px-8 py-4 whitespace-nowrap text-right font-mono font-black ${r.unsettledAmount > 0 ? 'text-rose-600' : 'text-slate-300'}`}>{r.unsettledAmount.toLocaleString()}</td>
                                 <td className={`px-8 py-4 whitespace-nowrap ${colorClass}`}>
                                    <div className="flex items-center gap-2">
                                       <div className={`w-2 h-2 rounded-full ${dotColor}`}></div>
                                       <div className="flex flex-col">
                                          <span className="font-bold">{statusText}</span>
                                          <span className="text-[10px] opacity-60">到期日: {r.dueDate}</span>
                                       </div>
                                    </div>
                                 </td>
                              </tr>
                            );
                          })}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7', '#fb7185', '#2dd4bf', '#fbbf24'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  // 版块折叠状态
  const [sections, setSections] = useState({
    trend: true,
    composition: true,
    ranking: true,
    receivables: true
  });

  // 全局展示状态
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [customerMetric, setCustomerMetric] = useState<'sales' | 'quantity'>('sales');
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');

  // 深度分析联动状态
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<string | null>(null);
  const [drillMetric, setDrillMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [isDebtMode, setIsDebtMode] = useState(false); 

  const [localTableFilters, setLocalTableFilters] = useState({
    customer: '', 
    category: '',
    month: '' 
  });

  const [columnFilters, setColumnFilters] = useState<Record<string, string[]>>({
    id: [],
    customer: [],
    salesperson: [],
    itemName: []
  });

  const [activeFilterMenu, setActiveFilterMenu] = useState<string | null>(null);
  const [activeMetrics, setActiveMetrics] = useState({ amount: true, quantity: true });
  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  const toggleSection = (key: keyof typeof sections) => {
    setSections(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- 应付未付情况统计数据计算 (列出所有欠款客户) ---
  const receivablesAnalysis = useMemo(() => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    let totalSettled = 0;
    let totalUnsettled = 0;

    const agingBuckets = [
      { name: '未到期', value: 0, color: '#10b981' },
      { name: '逾期1-30天', value: 0, color: '#f59e0b' },
      { name: '逾期31-60天', value: 0, color: '#f97316' },
      { name: '逾期60天+', value: 0, color: '#ef4444' }
    ];

    const customerDebtsMap = new Map<string, { settled: number; unsettled: number }>();

    filteredData.forEach(r => {
      totalSettled += r.settledAmount || 0;
      totalUnsettled += r.unsettledAmount || 0;

      const curDebt = customerDebtsMap.get(r.customer) || { settled: 0, unsettled: 0 };
      customerDebtsMap.set(r.customer, {
        settled: curDebt.settled + (r.settledAmount || 0),
        unsettled: curDebt.unsettled + (r.unsettledAmount || 0)
      });

      if (r.unsettledAmount > 0 && r.dueDate) {
        const dueDate = new Date(r.dueDate);
        const diffTime = today.getTime() - dueDate.getTime();
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        if (diffDays <= 0) agingBuckets[0].value += r.unsettledAmount;
        else if (diffDays <= 30) agingBuckets[1].value += r.unsettledAmount;
        else if (diffDays <= 60) agingBuckets[2].value += r.unsettledAmount;
        else agingBuckets[3].value += r.unsettledAmount;
      }
    });

    const allDebtors = Array.from(customerDebtsMap.entries())
      .map(([name, val]) => ({ name, settled: val.settled, unsettled: val.unsettled, total: val.settled + val.unsettled }))
      .filter(d => d.unsettled > 0) 
      .sort((a, b) => b.unsettled - a.unsettled);

    return {
      totalSettled,
      totalUnsettled,
      agingBuckets,
      allDebtors,
      composition: [
        { name: '已结算', value: totalSettled, color: '#10b981' },
        { name: '待回款', value: totalUnsettled, color: '#fb7185' }
      ]
    };
  }, [filteredData]);

  // --- 深度分析穿透逻辑 (全量数据 + 三色预警) ---
  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : (selectedCustomer ? 'customer' : null));
    const value = selectedCategory || selectedItem || selectedCustomer;

    if (!dimension || !value) return {
      baseRecords: [], totalSales: 0, secondaryDistribution: [], filterOptions: { id: [], customer: [], salesperson: [], itemName: [] }, tableRecords: [], tableTotalSales: 0, tableTotalUnsettled: 0
    };

    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);
    const totalSales = baseRecords.reduce((s, r) => s + r.totalAmount, 0);

    const filterOptions = {
      id: Array.from(new Set(baseRecords.map(r => r.id))).sort(),
      customer: Array.from(new Set(baseRecords.map(r => r.customer))).sort(),
      salesperson: Array.from(new Set(baseRecords.map(r => r.salesperson))).sort(),
      itemName: Array.from(new Set(baseRecords.map(r => r.itemName))).sort()
    };

    let finalRecords = baseRecords;
    if (localTableFilters.month) finalRecords = finalRecords.filter(r => r.month === localTableFilters.month);

    Object.entries(columnFilters).forEach(([field, selectedValues]) => {
      const castedValues = selectedValues as string[];
      if (castedValues.length > 0) {
        finalRecords = finalRecords.filter(r => castedValues.includes(String(r[field as keyof SalesRecord])));
      }
    });

    const tableTotalSales = finalRecords.reduce((acc, cur) => acc + cur.totalAmount, 0);
    const tableTotalUnsettled = finalRecords.reduce((acc, cur) => acc + cur.unsettledAmount, 0);

    return {
      baseRecords,
      totalSales,
      filterOptions,
      tableRecords: finalRecords.sort((a, b) => b.date.localeCompare(a.date)),
      tableTotalSales,
      tableTotalUnsettled
    };
  }, [selectedCategory, selectedItem, selectedCustomer, filteredData, localTableFilters, columnFilters]);

  // --- 其他模块数据计算 ---
  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set<string>(filteredData.map(d => d.month))).sort();
    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return { name: month, amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0), quantity: monthRecords.reduce((s, r) => s + r.quantity, 0) };
      });
      const series: any[] = [];
      if (activeMetrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (activeMetrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }
    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set<string>(filteredData.map(d => String(d[dimKey])))).slice(0, 8);
    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (activeMetrics.amount) series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor });
      if (activeMetrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor });
    });
    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });
    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  const customerRankingData = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.customer) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount; entry.quantity += d.quantity;
      map.set(d.customer, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => customerMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, customerMetric]);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  // --- 打开分析面板的快捷函数 ---
  const openCategoryDrillDown = (name: string) => { setDrillMetric(pieMetric); setIsDebtMode(false); setSelectedCategory(name); setSelectedItem(null); setSelectedCustomer(null); setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] }); setLocalTableFilters({ customer: '', category: '', month: '' }); };
  const openItemDrillDown = (name: string) => { setDrillMetric(itemPieMetric); setIsDebtMode(false); setSelectedItem(name); setSelectedCategory(null); setSelectedCustomer(null); setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] }); setLocalTableFilters({ customer: '', category: '', month: '' }); };
  const openCustomerDrillDown = (name: string, debtOnly: boolean = false) => { setDrillMetric(customerMetric); setIsDebtMode(debtOnly); setSelectedCustomer(name); setSelectedCategory(null); setSelectedItem(null); setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] }); setLocalTableFilters({ customer: '', category: '', month: '' }); };

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const sx = cx + (outerRadius + 10) * Math.cos(-RADIAN * midAngle);
    const sy = cy + (outerRadius + 10) * Math.sin(-RADIAN * midAngle);
    const mx = cx + (outerRadius + 45) * Math.cos(-RADIAN * midAngle);
    const my = cy + (outerRadius + 45) * Math.sin(-RADIAN * midAngle);
    const ex = mx + (Math.cos(-RADIAN * midAngle) >= 0 ? 1 : -1) * 22;
    const textAnchor = Math.cos(-RADIAN * midAngle) >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${my}`} stroke={fill} fill="none" strokeWidth={2} opacity={0.6} />
        <circle cx={ex} cy={my} r={3} fill={fill} />
        <text x={ex + (Math.cos(-RADIAN * midAngle) >= 0 ? 1 : -1) * 12} y={my} textAnchor={textAnchor} fill="#1e293b" style={{ fontSize: '13px', fontWeight: 800 }}>{name}</text>
        <text x={ex + (Math.cos(-RADIAN * midAngle) >= 0 ? 1 : -1) * 12} y={my} dy={16} textAnchor={textAnchor} fill="#94a3b8" style={{ fontSize: '11px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  const TableDropdownFilter = ({ field, label }: { field: string, label: string }) => {
    const options = (drillDownAnalysis.filterOptions as Record<string, string[]>)?.[field] || [];
    const selected = columnFilters[field] || [];
    const menuRef = useRef<HTMLDivElement>(null);
    const [localSearch, setLocalSearch] = useState('');

    useEffect(() => {
      const handleClickOutside = (e: MouseEvent) => {
        if (menuRef.current && !menuRef.current.contains(e.target as Node)) setActiveFilterMenu(null);
      };
      if (activeFilterMenu === field) document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [activeFilterMenu, field]);

    return (
      <div className="relative inline-block text-left" ref={menuRef}>
        <button onClick={() => { setActiveFilterMenu(activeFilterMenu === field ? null : field); setLocalSearch(''); }} className={`flex items-center gap-2 px-2 py-1.5 rounded-lg transition-all ${selected.length > 0 ? 'bg-indigo-50 text-indigo-700' : 'text-slate-400 hover:text-slate-600'}`}>
          <span className="text-[10px] font-black uppercase tracking-widest">{label}</span>
          <svg className={`w-3 h-3 ${activeFilterMenu === field ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg>
        </button>
        {activeFilterMenu === field && (
          <div className="absolute top-full left-0 mt-2 w-64 bg-white border border-slate-200 shadow-2xl rounded-2xl z-[6000] overflow-hidden animate-in fade-in zoom-in-95 duration-150">
             <div className="p-3 bg-slate-50 border-b border-slate-100">
                <input type="text" autoFocus placeholder="过滤..." value={localSearch} onChange={(e) => setLocalSearch(e.target.value)} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-xl text-xs outline-none font-bold" />
             </div>
             <div className="max-h-64 overflow-y-auto p-1.5 custom-scrollbar bg-white">
                <button onClick={() => setColumnFilters(prev => ({ ...prev, [field]: [] }))} className="w-full text-left px-3 py-2 text-[10px] font-black text-red-500 hover:bg-red-50 rounded-lg mb-1">清除所选</button>
                {options.filter(opt => opt.toLowerCase().includes(localSearch.toLowerCase())).map(opt => {
                  const isSelected = selected.includes(opt);
                  return (
                    <button key={opt} onClick={() => setColumnFilters(prev => ({ ...prev, [field]: isSelected ? selected.filter(v => v !== opt) : [...selected, opt] }))} className={`w-full text-left px-3 py-2.5 rounded-xl mb-0.5 flex items-center justify-between ${isSelected ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-700'}`}>
                      <span className="text-[12px] font-bold truncate">{opt}</span>
                      {isSelected && <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7" /></svg>}
                    </button>
                  );
                })}
             </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-10 pb-16 relative text-left">
      {/* 1. 顶部总览 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">出库总量</p><p className="text-2xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col overflow-hidden">
           <div className="p-6 flex items-center justify-between border-b border-slate-100">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
                <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">单据总数</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div>
              </div>
              <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2 bg-slate-100 rounded-xl hover:bg-slate-200"><svg className={`w-5 h-5 transition-transform ${isOrdersExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
           </div>
           {isOrdersExpanded && (
              <div className="px-5 py-5 bg-slate-50/50 border-t border-slate-100 space-y-4 animate-in fade-in duration-300">
                <input type="text" placeholder="检索单号..." value={orderSearchTerm} onChange={(e) => setOrderSearchTerm(e.target.value)} className="w-full bg-white border border-slate-300 rounded-lg px-3 py-1.5 text-xs outline-none focus:border-indigo-500 font-bold" />
                <div className="max-h-40 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar pr-1">
                  {summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase())).map(id => (<button key={id} onClick={() => onSelectOrderId(id)} className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-bold hover:border-indigo-500">{id}</button>))}
                </div>
              </div>
           )}
        </div>
      </div>

      {/* 2. 业绩趋势 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div onClick={() => toggleSection('trend')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50">
