              <button onClick={() => setTrendMode('salesperson')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'salesperson' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>销售员</button>
