            <button className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${sections.trend ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
          </div>
        </div>
        {sections.trend && (
