                    <button onClick={() => setPieMetric('quantity')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量</button>
                  </div>
                </div>
                <div className="h-[450px] w-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie data={sortedCategorySummary} cx="50%" cy="50%" innerRadius={100} outerRadius={160} paddingAngle={5} dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} stroke="#fff" strokeWidth={6} label={renderCustomizedLabel} labelLine={false} onClick={(d) => openCategoryDrillDown(d.name)}>
                        {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                      </Pie>
                      <Tooltip />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
             </div>
          </div>
        )}
      </section>

      {/* 4. 客户采购排行 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div onClick={() => toggleSection('ranking')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3">
            <span className="p-2 bg-amber-50 text-amber-600 rounded-xl text-lg">🏆</span> 客户采购排行
          </h3>
          <div className="flex items-center gap-4" onClick={(e) => e.stopPropagation()}>
            <div className="flex bg-slate-100 p-1.5 rounded-xl border border-slate-200">
              <button onClick={() => setCustomerMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-black transition-all ${customerMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>按金额</button>
              <button onClick={() => setCustomerMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-black transition-all ${customerMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>按数量</button>
            </div>
            <button className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${sections.ranking ? 'rotate-180 text-amber-600' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
          </div>
        </div>
        {sections.ranking && (
          <div className="px-8 pb-10 h-[400px] animate-in fade-in duration-500">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={customerRankingData.slice(0, 10)} layout="vertical" margin={{ left: 20, right: 80 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#e2e8f0" />
                <XAxis type="number" hide />
                <YAxis type="category" dataKey="name" width={120} axisLine={false} tickLine={false} tick={{fontSize: 12, fontWeight: 700}} />
                <Tooltip cursor={{fill: 'transparent'}} />
                <Bar dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} radius={[0, 8, 8, 0]} barSize={30} onClick={(d) => openCustomerDrillDown(d.name)}>
                  {customerRankingData.slice(0, 10).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                  <LabelList dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} position="right" formatter={(v: any) => customerMetric === 'sales' ? `${(v/1000000).toFixed(1)}M` : v} style={{fontSize: 10, fontWeight: 900, fill: '#64748b'}} />
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        )}
