        <div onClick={() => toggleSection('receivables')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors">
          <div className="flex flex-col gap-1">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-3">
              <span className="p-2 bg-rose-50 text-rose-600 rounded-xl text-lg">📅</span> 应付未付情况统计
            </h3>
            {sections.receivables && <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest pl-12">实时账期审计：共有 {receivablesAnalysis.allDebtors.length} 户存在待回笼款项</p>}
          </div>
          <button className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${sections.receivables ? 'rotate-180 text-rose-600' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
        </div>
