const SHEET_ID = '190CYOeWCVB68eCOszi7VwADf3N3jHwN7msmI1jmgzlg';
const GID = '1447308255';
const CSV_URL = `https://docs.google.com/spreadsheets/d/${SHEET_ID}/gviz/tq?tqx=out:csv&gid=${GID}`;

const formatDateString = (dateStr: string): string => {
  if (!dateStr) return '';
  try {
    const normalized = dateStr.replace(/\//g, '-');
    const date = new Date(normalized);
    if (isNaN(date.getTime())) {
      const parts = normalized.split('-');
      if (parts.length === 3) {
        return `${parts[0]}-${parts[1].padStart(2, '0')}-${parts[2].padStart(2, '0')}`;
      }
      return dateStr;
    }
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  } catch (e) {
    return dateStr;
  }
};

export const processCsvText = (csvText: string): SalesRecord[] => {
  const rows = csvText.split(/\r?\n/).filter(line => line.trim() !== '');
  const parsedRows = rows.map(line => {
    const result: string[] = [];
    let currentField = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') inQuotes = !inQuotes;
      else if (char === ',' && !inQuotes) {
        result.push(currentField.replace(/^"|"$/g, '').trim());
        currentField = '';
      } else currentField += char;
    }
    result.push(currentField.replace(/^"|"$/g, '').trim());
    return result;
  });

  const dataRows = parsedRows.slice(1);
  return dataRows.map((cols, index) => {
    const rawDate = cols[2] || '';
    const standardizedDate = formatDateString(rawDate);
    const rawDueDate = cols[12] || standardizedDate; // 如果没填到期日，默认业务日期

    return {
      id: cols[0] || `ID-${index}`,
      month: cols[1] || '',
      date: standardizedDate,
      customer: cols[3] || '',
      salesperson: cols[4] || '',
      category: cols[5] || '',
      itemName: cols[6] || '',
      quantity: parseFloat(cols[7]) || 0,
      unitPrice: parseFloat(cols[8]) || 0,
      totalAmount: parseFloat(cols[9]) || 0,
      settledAmount: parseFloat(cols[10]) || 0,
      unsettledAmount: parseFloat(cols[11]) || 0,
      dueDate: formatDateString(rawDueDate)
    };
  });
};

export const fetchSalesData = async (): Promise<SalesRecord[]> => {
  try {
    const response = await fetch(CSV_URL);
    if (!response.ok) throw new Error('表格连接受阻');
    const csvText = await response.text();
    return processCsvText(csvText);
  } catch (error) {
    console.error('Fetch Error:', error);
    throw error;
  }
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7', '#fb7185', '#2dd4bf', '#fbbf24'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  // 版块折叠状态 - 保留原有的并增加 receivables
  const [sections, setSections] = useState({
    trend: true,
    composition: true,
    ranking: true,
    receivables: true
  });

  // 展示度量切换
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [customerMetric, setCustomerMetric] = useState<'sales' | 'quantity'>('sales');
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');
  const [activeMetrics, setActiveMetrics] = useState({ amount: true, quantity: true });

  // 深度分析面板状态
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<string | null>(null);
  const [drillMetric, setDrillMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [isDebtMode, setIsDebtMode] = useState(false); 

  const [localTableFilters, setLocalTableFilters] = useState({ month: '', customer: '', category: '' });
  const [columnFilters, setColumnFilters] = useState<Record<string, string[]>>({ id: [], customer: [], salesperson: [], itemName: [] });
  const [activeFilterMenu, setActiveFilterMenu] = useState<string | null>(null);
  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  const toggleSection = (key: keyof typeof sections) => {
    setSections(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- 1. 原有的业绩趋势计算 ---
  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set<string>(filteredData.map(d => d.month))).sort();
    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return { name: month, amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0), quantity: monthRecords.reduce((s, r) => s + r.quantity, 0) };
      });
      const series: any[] = [];
      if (activeMetrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (activeMetrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }
    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set<string>(filteredData.map(d => String(d[dimKey])))).slice(0, 8);
    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (activeMetrics.amount) series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor });
      if (activeMetrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
    });
    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });
    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  // --- 2. 原有的构成分析计算 ---
  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount; entry.quantity += d.quantity;
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries()).map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity })).sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, itemPieMetric]);

  // --- 3. 原有的客户排行计算 ---
  const customerRankingData = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.customer) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount; entry.quantity += d.quantity;
      map.set(d.customer, entry);
    });
    return Array.from(map.entries()).map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity })).sort((a, b) => customerMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, customerMetric]);

  // --- 4. 新增的应付未付情况计算 ---
  const receivablesAnalysis = useMemo(() => {
    const today = new Date(); today.setHours(0, 0, 0, 0);
    let totalSettled = 0; let totalUnsettled = 0;
    const agingBuckets = [
      { name: '未到期', value: 0, color: '#10b981' },
      { name: '逾期1-30天', value: 0, color: '#f59e0b' },
      { name: '逾期31-60天', value: 0, color: '#f97316' },
      { name: '逾期60天+', value: 0, color: '#ef4444' }
    ];
    const customerDebtsMap = new Map<string, { settled: number; unsettled: number }>();
    filteredData.forEach(r => {
      totalSettled += r.settledAmount || 0; totalUnsettled += r.unsettledAmount || 0;
      const curDebt = customerDebtsMap.get(r.customer) || { settled: 0, unsettled: 0 };
      customerDebtsMap.set(r.customer, { settled: curDebt.settled + (r.settledAmount || 0), unsettled: curDebt.unsettled + (r.unsettledAmount || 0) });
      if (r.unsettledAmount > 0 && r.dueDate) {
        const dueDate = new Date(r.dueDate);
        const diffDays = Math.ceil((today.getTime() - dueDate.getTime()) / (1000 * 60 * 60 * 24));
        if (diffDays <= 0) agingBuckets[0].value += r.unsettledAmount;
        else if (diffDays <= 30) agingBuckets[1].value += r.unsettledAmount;
        else if (diffDays <= 60) agingBuckets[2].value += r.unsettledAmount;
        else agingBuckets[3].value += r.unsettledAmount;
      }
    });
    const allDebtors = Array.from(customerDebtsMap.entries()).map(([name, val]) => ({ name, settled: val.settled, unsettled: val.unsettled, total: val.settled + val.unsettled })).filter(d => d.unsettled > 0).sort((a, b) => b.unsettled - a.unsettled);
    return { totalSettled, totalUnsettled, agingBuckets, allDebtors, composition: [{ name: '已结算', value: totalSettled, color: '#10b981' }, { name: '待回款', value: totalUnsettled, color: '#fb7185' }] };
  }, [filteredData]);

  // --- 深度分析核心逻辑 (全量数据 + 三色预警) ---
  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : (selectedCustomer ? 'customer' : null));
    const value = selectedCategory || selectedItem || selectedCustomer;
    if (!dimension || !value) return { tableRecords: [], totalSales: 0, tableTotalUnsettled: 0, filterOptions: { id: [], customer: [], salesperson: [], itemName: [] } };

    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);
    const filterOptions = { id: Array.from(new Set(baseRecords.map(r => r.id))).sort(), customer: Array.from(new Set(baseRecords.map(r => r.customer))).sort(), salesperson: Array.from(new Set(baseRecords.map(r => r.salesperson))).sort(), itemName: Array.from(new Set(baseRecords.map(r => r.itemName))).sort() };

    let finalRecords = baseRecords;
    Object.entries(columnFilters).forEach(([field, selectedValues]) => {
      const castedValues = selectedValues as string[];
      if (castedValues.length > 0) finalRecords = finalRecords.filter(r => castedValues.includes(String(r[field as keyof SalesRecord])));
    });

    return {
      tableRecords: finalRecords.sort((a, b) => b.date.localeCompare(a.date)),
      totalSales: baseRecords.reduce((s, r) => s + r.totalAmount, 0),
      tableTotalUnsettled: finalRecords.reduce((acc, cur) => acc + cur.unsettledAmount, 0),
      filterOptions
    };
  }, [selectedCategory, selectedItem, selectedCustomer, filteredData, columnFilters]);

  // --- 辅助渲染函数 ---
  const openCategoryDrillDown = (name: string) => { setDrillMetric(pieMetric); setIsDebtMode(false); setSelectedCategory(name); setSelectedItem(null); setSelectedCustomer(null); };
  const openCustomerDrillDown = (name: string, debtOnly: boolean = false) => { setDrillMetric(customerMetric); setIsDebtMode(debtOnly); setSelectedCustomer(name); setSelectedCategory(null); setSelectedItem(null); };

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const cos = Math.cos(-RADIAN * midAngle);
    const ex = cx + (outerRadius + 45) * cos + (cos >= 0 ? 1 : -1) * 22;
    const ey = cy + (outerRadius + 45) * Math.sin(-RADIAN * midAngle);
    return (
      <g>
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} textAnchor={cos >= 0 ? 'start' : 'end'} fill="#0f172a" style={{ fontSize: '13px', fontWeight: 900 }}>{name}</text>
        <text x={ex + (cos >= 0 ? 1 : -1) * 12} y={ey} dy={16} textAnchor={cos >= 0 ? 'start' : 'end'} fill="#64748b" style={{ fontSize: '11px' }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  const TableDropdownFilter = ({ field, label }: { field: string, label: string }) => {
    const options = (drillDownAnalysis.filterOptions as Record<string, string[]>)?.[field] || [];
    const selected = columnFilters[field] || [];
    const menuRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
      const handleClickOutside = (e: MouseEvent) => { if (menuRef.current && !menuRef.current.contains(e.target as Node)) setActiveFilterMenu(null); };
      if (activeFilterMenu === field) document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [activeFilterMenu, field]);

    return (
      <div className="relative inline-block text-left" ref={menuRef}>
        <button onClick={() => setActiveFilterMenu(activeFilterMenu === field ? null : field)} className={`flex items-center gap-2 px-2 py-1 rounded group ${selected.length > 0 ? 'text-indigo-600' : 'text-slate-400'}`}>
          <span className="text-[10px] font-black uppercase tracking-widest">{label}</span>
          <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg>
        </button>
        {activeFilterMenu === field && (
          <div className="absolute top-full left-0 mt-1 w-56 bg-white border border-slate-200 shadow-xl rounded-xl z-[6000] p-1">
            <div className="max-h-48 overflow-y-auto custom-scrollbar">
              {options.map(opt => (
                <button key={opt} onClick={() => setColumnFilters(p => ({ ...p, [field]: selected.includes(opt) ? selected.filter(v => v !== opt) : [...selected, opt] }))} className={`w-full text-left px-3 py-2 text-xs rounded-lg mb-0.5 ${selected.includes(opt) ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-700'}`}>{opt}</button>
              ))}
            </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-10 pb-16 relative text-left">
      {/* 顶部指标 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
