          <div className="flex bg-slate-100 p-1.5 rounded-xl" onClick={(e) => e.stopPropagation()}>
            <button onClick={() => setCustomerMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-black ${customerMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>金额</button>
            <button onClick={() => setCustomerMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-black ${customerMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量</button>
          </div>
        </div>
        {sections.ranking && (
          <div className="px-8 pb-10 h-[400px] animate-in fade-in">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={customerRankingData.slice(0, 10)} layout="vertical" margin={{ left: 20, right: 80 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#e2e8f0" />
                <XAxis type="number" hide /><YAxis type="category" dataKey="name" width={120} axisLine={false} tickLine={false} tick={{fontSize: 12, fontWeight: 700}} />
