      {/* 增强型深度下钻面板 (三色预警系统) */}
      {(selectedCategory || selectedItem || selectedCustomer) && (
        <div className="fixed inset-0 bg-white z-[5000] flex flex-col animate-in slide-in-from-bottom-10 duration-500 overflow-hidden text-left">
