                       <button onClick={() => setPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-500'}`}>数量</button>
