                     <h4 className="text-sm font-black text-slate-700 uppercase tracking-widest">物料明细 Top 10</h4>
                     <div className="flex bg-slate-200/50 p-1 rounded-xl">
                       <button onClick={() => setItemPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${itemPieMetric === 'sales' ? 'bg-white shadow-sm text-indigo-700' : 'text-slate-500'}`}>金额</button>
                       <button onClick={() => setItemPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${itemPieMetric === 'quantity' ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-500'}`}>数量</button>
                     </div>
                   </div>
                   <div className="h-[350px] w-full">
                     <ResponsiveContainer width="100%" height="100%">
                       <PieChart>
                         <Pie data={sortedItemSummary} cx="50%" cy="50%" innerRadius={70} outerRadius={110} paddingAngle={3} dataKey={itemPieMetric === 'sales' ? 'sales' : 'quantity'} label={renderCustomizedLabel} labelLine={false} onClick={(d) => openItemDrillDown(d.name)}>
                           {sortedItemSummary.map((_, i) => <RechartsCell key={i} fill={COLORS[(i + 5) % COLORS.length]} />)}
                         </Pie>
                         <Tooltip />
                       </PieChart>
                     </ResponsiveContainer>
                   </div>
                </div>
             </div>
          </div>
        )}
      </section>

      {/* 模块3: 客户采购排行 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div onClick={() => toggleSection('ranking')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3"><span className="p-2 bg-amber-50 text-amber-600 rounded-xl text-lg">👥</span> 客户采购排行分析</h3>
          <div className="flex bg-slate-100 p-1.5 rounded-xl" onClick={(e) => e.stopPropagation()}>
            <button onClick={() => setCustomerMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-black ${customerMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>金额</button>
            <button onClick={() => setCustomerMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-black ${customerMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量</button>
          </div>
        </div>
        {sections.ranking && (
          <div className="px-8 pb-10 h-[400px] animate-in fade-in">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={customerRankingData.slice(0, 10)} layout="vertical" margin={{ left: 20, right: 80 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#e2e8f0" />
                <XAxis type="number" hide /><YAxis type="category" dataKey="name" width={120} axisLine={false} tickLine={false} tick={{fontSize: 12, fontWeight: 700}} />
                <Tooltip cursor={{fill: 'transparent'}} /><Bar dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} radius={[0, 8, 8, 0]} barSize={30} onClick={(d) => openCustomerDrillDown(d.name)}>{customerRankingData.slice(0, 10).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}<LabelList dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} position="right" formatter={(v: any) => customerMetric === 'sales' ? `${(v/1000000).toFixed(1)}M` : v} style={{fontSize: 10, fontWeight: 900, fill: '#64748b'}} /></Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        )}
      </section>

      {/* 模块4: 应付未付情况统计 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden border-l-8 border-l-rose-500">
        <div onClick={() => toggleSection('receivables')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors">
          <div className="flex flex-col gap-1">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-3"><span className="p-2 bg-rose-50 text-rose-600 rounded-xl text-lg">📅</span> 应付未付情况统计</h3>
            {sections.receivables && <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest pl-12">当前欠款客户总数: {receivablesAnalysis.allDebtors.length} 个</p>}
          </div>
          <button className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${sections.receivables ? 'rotate-180 text-rose-600' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
        </div>
        {sections.receivables && (
          <div className="px-8 pb-10 space-y-12 animate-in fade-in">
             <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                <div className="bg-slate-50/50 p-8 rounded-[32px] border border-slate-100 flex items-center gap-10">
                   <div className="w-40 h-40 flex-shrink-0"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={receivablesAnalysis.composition} innerRadius={60} outerRadius={80} paddingAngle={10} dataKey="value" stroke="none">{receivablesAnalysis.composition.map((entry, i) => <RechartsCell key={i} fill={entry.color} />)}</Pie><Tooltip /></PieChart></ResponsiveContainer></div>
                   <div className="flex-1 space-y-6">
                      <div><h4 className="text-[10px] font-black text-slate-400 uppercase mb-1">已结算累计</h4><p className="text-2xl font-black text-emerald-600">{receivablesAnalysis.totalSettled.toLocaleString()} CFA</p></div>
                      <div><h4 className="text-[10px] font-black text-slate-400 uppercase mb-1">待结算总额</h4><p className="text-2xl font-black text-rose-600">{receivablesAnalysis.totalUnsettled.toLocaleString()} CFA</p></div>
                   </div>
                </div>
                <div className="bg-slate-50/50 p-8 rounded-[32px] border border-slate-100 h-60">
                   <h4 className="text-[10px] font-black text-slate-400 uppercase mb-6">账期风险分布</h4>
                   <ResponsiveContainer width="100%" height="100%"><BarChart data={receivablesAnalysis.agingBuckets}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" /><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700}} /><YAxis hide /><Tooltip /><Bar dataKey="value" radius={[8, 8, 0, 0]} barSize={40}>{receivablesAnalysis.agingBuckets.map((entry, i) => <RechartsCell key={i} fill={entry.color} />)}<LabelList dataKey="value" position="top" formatter={(v: any) => `${(v/1000000).toFixed(1)}M`} style={{fontSize: 10, fontWeight: 900, fill: '#64748b'}} /></Bar></BarChart></ResponsiveContainer>
                </div>
             </div>
             <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="px-8 py-5 bg-slate-50 border-b border-slate-100 flex items-center justify-between"><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">欠款客户深度审计表</span></div>
                <div className="overflow-x-auto max-h-[500px] custom-scrollbar">
                   <table className="min-w-full divide-y divide-slate-100">
                      <thead className="bg-slate-50 sticky top-0 z-10"><tr><th className="px-8 py-4 text-left text-[10px] font-black text-slate-400 uppercase">客户名称</th><th className="px-8 py-4 text-right text-[10px] font-black text-slate-400 uppercase">待结金额 (CFA)</th><th className="px-8 py-4 text-left text-[10px] font-black text-slate-400 uppercase pl-12">回款进度</th></tr></thead>
                      <tbody className="divide-y divide-slate-50">{receivablesAnalysis.allDebtors.map((debtor) => { const ratio = (debtor.settled / debtor.total) * 100; return (<tr key={debtor.name} className="hover:bg-slate-50 cursor-pointer" onClick={() => openCustomerDrillDown(debtor.name, true)}><td className="px-8 py-4 text-sm font-black text-slate-800">{debtor.name}</td><td className="px-8 py-4 text-sm font-mono font-black text-rose-600 text-right">{debtor.unsettled.toLocaleString()}</td><td className="px-8 py-4 pl-12"><div className="flex items-center gap-3"><div className="flex-1 h-2 bg-slate-100 rounded-full overflow-hidden"><div className="h-full bg-emerald-500" style={{ width: `${ratio}%` }}></div></div><span className="text-[10px] font-black text-slate-500 w-10 text-right">{ratio.toFixed(0)}%</span></div></td></tr>); })}</tbody>
                   </table>
                </div>
             </div>
          </div>
        )}
      </section>

      {/* 增强型深度下钻面板 */}
      {(selectedCategory || selectedItem || selectedCustomer) && (
        <div className="fixed inset-0 bg-white z-[5000] flex flex-col animate-in slide-in-from-bottom-10 duration-500 overflow-hidden text-left">
           <div className={`px-10 py-6 border-b border-slate-200 bg-white flex items-center justify-between shadow-sm z-10 ${isDebtMode ? 'border-t-8 border-t-rose-500' : ''}`}>
              <div className="flex items-center gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-white shadow-xl ${isDebtMode ? 'bg-rose-600' : 'bg-indigo-600'}`}>{isDebtMode ? '⚠️' : '🔍'}</div>
                <div><h3 className="text-2xl font-black text-slate-900">{selectedCategory || selectedItem || selectedCustomer} <span className="text-slate-300 font-normal">|</span> <span className={isDebtMode ? 'text-rose-600' : 'text-indigo-600'}>{isDebtMode ? '应收账单审计' : '深度明细分析'}</span></h3><p className="text-[10px] font-bold text-slate-400 mt-1 uppercase">包含所有历史记录 · 实时风险等级分析</p></div>
              </div>
              <button onClick={() => { setSelectedCategory(null); setSelectedItem(null); setSelectedCustomer(null); setIsDebtMode(false); setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] }); }} className="px-10 py-3 bg-slate-900 text-white rounded-2xl text-xs font-black hover:bg-slate-800 transition-all shadow-lg">关闭面板</button>
           </div>

           <div className="flex-1 overflow-y-auto custom-scrollbar p-10 bg-slate-50/30 space-y-10">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-6 text-left">
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm"><p className="text-[10px] font-black text-slate-400 uppercase mb-1">成交总额 (穿透)</p><p className="text-2xl font-black text-indigo-600">{drillDownAnalysis.totalSales.toLocaleString()} CFA</p></div>
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm"><p className="text-[10px] font-black text-rose-500 uppercase mb-1">待结算总额 (风险点)</p><p className="text-2xl font-black text-rose-600">{drillDownAnalysis.tableTotalUnsettled.toLocaleString()} CFA</p></div>
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm col-span-2 flex items-center gap-8"><div className="flex items-center gap-2"><div className="w-3 h-3 rounded-full bg-rose-500 animate-pulse"></div><span className="text-[11px] font-bold text-slate-500">红色: 已逾期</span></div><div className="flex items-center gap-2"><div className="w-3 h-3 rounded-full bg-amber-400"></div><span className="text-[11px] font-bold text-slate-500">黄色: 7天内到期</span></div><div className="flex items-center gap-2"><div className="w-3 h-3 rounded-full bg-emerald-500"></div><span className="text-[11px] font-bold text-slate-500">绿色: 安全/已结清</span></div></div>
              </div>

              <div className="bg-white rounded-3xl border border-slate-200 shadow-xl overflow-hidden">
                 <div className="px-8 py-5 border-b border-slate-100 bg-slate-50 flex items-center justify-between"><span className="text-[10px] font-black uppercase text-slate-500">业务明细审计清单 (全量历史数据)</span></div>
                 <div className="overflow-x-auto max-h-[600px] custom-scrollbar">
                    <table className="min-w-full divide-y divide-slate-100 text-left">
                       <thead className="bg-white sticky top-0 z-[100] shadow-sm">
                          <tr><th className="px-8 py-4 text-left"><TableDropdownFilter field="id" label="单号" /></th><th className="px-8 py-4 text-left text-[10px] font-black text-slate-400 uppercase">日期</th>{!selectedCustomer && <th className="px-8 py-4 text-left"><TableDropdownFilter field="customer" label="客户" /></th>}<th className="px-8 py-4 text-left"><TableDropdownFilter field="itemName" label="物料" /></th><th className="px-8 py-4 text-right text-[10px] font-black text-slate-400 uppercase">成交额</th><th className="px-8 py-4 text-right text-[10px] font-black text-slate-400 uppercase">待结金额</th><th className="px-8 py-4 text-left text-[10px] font-black text-slate-400 uppercase">审计状态</th></tr>
                       </thead>
                       <tbody className="bg-white divide-y divide-slate-50 text-[12px]">
                          {drillDownAnalysis.tableRecords.map((r, i) => {
                            const today = new Date(); today.setHours(0, 0, 0, 0);
                            const dueDate = new Date(r.dueDate);
                            const diffDays = Math.ceil((dueDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
                            let colorClass = "text-emerald-500"; let statusText = "已结清"; let dotColor = "bg-emerald-500";
                            if (r.unsettledAmount > 0) {
                              if (diffDays < 0) { colorClass = "text-rose-600 font-black"; statusText = `已逾期 ${Math.abs(diffDays)} 天`; dotColor = "bg-rose-500 animate-pulse"; }
                              else if (diffDays <= 7) { colorClass = "text-amber-500 font-black"; statusText = `临期 ${diffDays} 天`; dotColor = "bg-amber-400"; }
                              else { colorClass = "text-emerald-600 font-bold"; statusText = `安全 (剩 ${diffDays} 天)`; dotColor = "bg-emerald-500"; }
                            }
                            return (
                              <tr key={`${r.id}-${i}`} className="hover:bg-slate-50 transition-colors">
                                 <td className="px-8 py-4 whitespace-nowrap font-mono font-bold text-indigo-600"><button onClick={() => onSelectOrderId(r.id)} className="hover:underline">{r.id}</button></td>
                                 <td className="px-8 py-4 whitespace-nowrap font-bold text-slate-500">{r.date}</td>
                                 {!selectedCustomer && <td className="px-8 py-4 whitespace-nowrap font-black text-slate-900">{r.customer}</td>}
                                 <td className="px-8 py-4 whitespace-nowrap font-black text-slate-700 truncate max-w-[150px]">{r.itemName}</td>
                                 <td className="px-8 py-4 whitespace-nowrap text-right font-mono text-slate-400">{r.totalAmount.toLocaleString()}</td>
                                 <td className={`px-8 py-4 whitespace-nowrap text-right font-mono font-black ${r.unsettledAmount > 0 ? 'text-rose-600' : 'text-slate-300'}`}>{r.unsettledAmount.toLocaleString()}</td>
                                 <td className={`px-8 py-4 whitespace-nowrap ${colorClass}`}><div className="flex items-center gap-2"><div className={`w-2 h-2 rounded-full ${dotColor}`}></div><div className="flex flex-col"><span className="font-bold">{statusText}</span><span className="text-[10px] opacity-60">账期至: {r.dueDate}</span></div></div></td>
                              </tr>
                            );
                          })}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7', '#fb7185', '#2dd4bf', '#fbbf24'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  // 1. 各模块折叠状态
  const [sections, setSections] = useState({
    trend: true,
    composition: true,
    ranking: true,
    receivables: true
  });

  // 2. 展示维度切换状态
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [customerMetric, setCustomerMetric] = useState<'sales' | 'quantity'>('sales');
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');
  const [activeMetrics, setActiveMetrics] = useState({ amount: true, quantity: true });

  // 3. 深度分析面板（穿透分析）状态
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<string | null>(null);
  const [isDebtMode, setIsDebtMode] = useState(false); 

  // 4. 下钻列表过滤状态
  const [columnFilters, setColumnFilters] = useState<Record<string, string[]>>({ 
    id: [], customer: [], salesperson: [], itemName: [] 
  });
  const [activeFilterMenu, setActiveFilterMenu] = useState<string | null>(null);
  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  const toggleSection = (key: keyof typeof sections) => {
    setSections(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- 模块 1 数据计算：业绩增长趋势 ---
  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set<string>(filteredData.map(d => d.month))).sort();
    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return { 
          name: month, 
          amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0), 
          quantity: monthRecords.reduce((s, r) => s + r.quantity, 0) 
        };
      });
      const series: any[] = [];
      if (activeMetrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (activeMetrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }
    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set<string>(filteredData.map(d => String(d[dimKey])))).slice(0, 8);
    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (activeMetrics.amount) series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor });
      if (activeMetrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
    });
    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });
    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  // --- 模块 2 数据计算：业务构成分析 (品类 + 物料) ---
  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount; entry.quantity += d.quantity;
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity)
      .slice(0, 10);
  }, [filteredData, itemPieMetric]);

  // --- 模块 3 数据计算：客户采购排行 ---
  const customerRankingData = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.customer) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount; entry.quantity += d.quantity;
      map.set(d.customer, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => customerMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, customerMetric]);

  // --- 模块 4 数据计算：应付未付情况统计 ---
  const receivablesAnalysis = useMemo(() => {
    const today = new Date(); today.setHours(0, 0, 0, 0);
    let totalSettled = 0; let totalUnsettled = 0;
    const agingBuckets = [
      { name: '未到期', value: 0, color: '#10b981' },
      { name: '逾期1-30天', value: 0, color: '#f59e0b' },
      { name: '逾期31-60天', value: 0, color: '#f97316' },
      { name: '逾期60天+', value: 0, color: '#ef4444' }
    ];
    const customerDebtsMap = new Map<string, { settled: number; unsettled: number }>();
    filteredData.forEach(r => {
      totalSettled += r.settledAmount || 0; totalUnsettled += r.unsettledAmount || 0;
      const curDebt = customerDebtsMap.get(r.customer) || { settled: 0, unsettled: 0 };
      customerDebtsMap.set(r.customer, { 
        settled: curDebt.settled + (r.settledAmount || 0), 
        unsettled: curDebt.unsettled + (r.unsettledAmount || 0) 
      });
      if (r.unsettledAmount > 0 && r.dueDate) {
        const dueDate = new Date(r.dueDate);
        const diffDays = Math.ceil((today.getTime() - dueDate.getTime()) / (1000 * 60 * 60 * 24));
        if (diffDays <= 0) agingBuckets[0].value += r.unsettledAmount;
        else if (diffDays <= 30) agingBuckets[1].value += r.unsettledAmount;
        else if (diffDays <= 60) agingBuckets[2].value += r.unsettledAmount;
        else agingBuckets[3].value += r.unsettledAmount;
      }
    });
    const allDebtors = Array.from(customerDebtsMap.entries())
      .map(([name, val]) => ({ 
        name, settled: val.settled, unsettled: val.unsettled, total: val.settled + val.unsettled 
      }))
      .filter(d => d.unsettled > 0)
      .sort((a, b) => b.unsettled - a.unsettled);
    return { 
      totalSettled, totalUnsettled, agingBuckets, allDebtors, 
      composition: [
        { name: '已结算', value: totalSettled, color: '#10b981' }, 
        { name: '待回款', value: totalUnsettled, color: '#fb7185' }
      ] 
    };
  }, [filteredData]);

  // --- 穿透分析穿透逻辑 ---
  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : (selectedCustomer ? 'customer' : null));
    const value = selectedCategory || selectedItem || selectedCustomer;
    if (!dimension || !value) return { tableRecords: [], totalSales: 0, tableTotalUnsettled: 0, filterOptions: { id: [], customer: [], salesperson: [], itemName: [] } };

    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);
    const filterOptions = { 
      id: Array.from(new Set(baseRecords.map(r => r.id))).sort(), 
      customer: Array.from(new Set(baseRecords.map(r => r.customer))).sort(), 
      salesperson: Array.from(new Set(baseRecords.map(r => r.salesperson))).sort(), 
      itemName: Array.from(new Set(baseRecords.map(r => r.itemName))).sort() 
    };

    let finalRecords = baseRecords;
    Object.entries(columnFilters).forEach(([field, selectedValues]) => {
      const castedValues = selectedValues as string[];
      if (castedValues.length > 0) finalRecords = finalRecords.filter(r => castedValues.includes(String(r[field as keyof SalesRecord])));
    });

    return {
      tableRecords: finalRecords.sort((a, b) => b.date.localeCompare(a.date)),
      totalSales: baseRecords.reduce((s, r) => s + r.totalAmount, 0),
      tableTotalUnsettled: finalRecords.reduce((acc, cur) => acc + cur.unsettledAmount, 0),
      filterOptions
    };
  }, [selectedCategory, selectedItem, selectedCustomer, filteredData, columnFilters]);

  // --- 辅助点击与渲染函数 ---
  const openCategoryDrillDown = (name: string) => { setIsDebtMode(false); setSelectedCategory(name); setSelectedItem(null); setSelectedCustomer(null); };
  const openItemDrillDown = (name: string) => { setIsDebtMode(false); setSelectedItem(name); setSelectedCategory(null); setSelectedCustomer(null); };
  const openCustomerDrillDown = (name: string, debtOnly: boolean = false) => { setIsDebtMode(debtOnly); setSelectedCustomer(name); setSelectedCategory(null); setSelectedItem(null); };

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const cos = Math.cos(-RADIAN * midAngle);
    const ex = cx + (outerRadius + 30) * cos;
    const ey = cy + (outerRadius + 30) * Math.sin(-RADIAN * midAngle);
    return (
      <g>
        <text x={ex} y={ey} textAnchor={cos >= 0 ? 'start' : 'end'} fill="#475569" style={{ fontSize: '10px', fontWeight: 900 }}>
          {name} ({(percent * 100).toFixed(0)}%)
        </text>
      </g>
    );
  };

  const TableDropdownFilter = ({ field, label }: { field: string, label: string }) => {
    const options = (drillDownAnalysis.filterOptions as Record<string, string[]>)?.[field] || [];
    const selected = columnFilters[field] || [];
    const menuRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
      const handleClickOutside = (e: MouseEvent) => { if (menuRef.current && !menuRef.current.contains(e.target as Node)) setActiveFilterMenu(null); };
      if (activeFilterMenu === field) document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [activeFilterMenu, field]);

    return (
      <div className="relative inline-block text-left" ref={menuRef}>
        <button onClick={() => setActiveFilterMenu(activeFilterMenu === field ? null : field)} className={`flex items-center gap-2 px-2 py-1 rounded group transition-colors ${selected.length > 0 ? 'text-indigo-600 bg-indigo-50' : 'text-slate-400 hover:bg-slate-50'}`}>
          <span className="text-[10px] font-black uppercase tracking-widest">{label}</span>
          <svg className={`w-3 h-3 transition-transform ${activeFilterMenu === field ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg>
        </button>
        {activeFilterMenu === field && (
          <div className="absolute top-full left-0 mt-2 w-56 bg-white border border-slate-200 shadow-2xl rounded-2xl z-[6000] p-1 animate-in fade-in zoom-in-95 duration-150">
            <div className="max-h-48 overflow-y-auto custom-scrollbar p-1">
              <button onClick={() => setColumnFilters(p => ({...p, [field]: []}))} className="w-full text-left px-3 py-1.5 text-[10px] font-black text-red-500 hover:bg-red-50 rounded-lg mb-1 uppercase">清除选择</button>
              {options.map(opt => (
                <button key={opt} onClick={() => setColumnFilters(p => ({ ...p, [field]: selected.includes(opt) ? selected.filter(v => v !== opt) : [...selected, opt] }))} className={`w-full text-left px-3 py-2 text-xs rounded-lg mb-0.5 flex justify-between items-center ${selected.includes(opt) ? 'bg-indigo-600 text-white shadow-md' : 'hover:bg-slate-50 text-slate-700'}`}>
                  <span className="truncate">{opt}</span>
                  {selected.includes(opt) && <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7" /></svg>}
                </button>
              ))}
            </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-10 pb-16 relative text-left">
      {/* 顶部总计指标栏 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-6 h-[110px] hover:shadow-md transition-shadow">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600 shadow-inner">💰</div>
           <div><p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-1">总计销售金额 (CFA)</p><p className="text-3xl font-black text-slate-900 tracking-tighter">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-6 h-[110px] hover:shadow-md transition-shadow">
