           <div><p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-1">出库物料总量</p><p className="text-3xl font-black text-slate-900 tracking-tighter">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-3xl border border-slate-200 shadow-sm flex flex-col overflow-hidden h-[110px] hover:shadow-md transition-shadow group relative">
