                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11, fontWeight: 700}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 800}} tickFormatter={(v) => `${(v / 1000000).toFixed(1)}M`} />
                <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.1)', padding: '12px' }} />
                <Legend iconType="circle" wrapperStyle={{ paddingTop: '20px', fontWeight: 900, fontSize: '11px', textTransform: 'uppercase' }} />
                {trendAnalysis.series.map((s) => (<Area key={s.key} type="monotone" dataKey={s.key} name={s.name} stroke={s.color} strokeWidth={4} fill={`url(#grad-${s.key})`} animationDuration={1000} />))}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        )}
      </section>

      {/* 模块2: 业务构成分析 (双扇形图展示) */}
