        <div onClick={() => toggleSection('composition')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3"><span className="p-2.5 bg-emerald-50 text-emerald-600 rounded-2xl text-xl shadow-inner">🧩</span> 核心业务构成深度分析</h3>
          <button className="p-2.5 bg-slate-50 border border-slate-100 rounded-xl hover:bg-slate-200 transition-colors"><svg className={`w-5 h-5 transition-transform ${sections.composition ? 'rotate-180 text-emerald-600' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg></button>
        </div>
        {sections.composition && (
          <div className="px-8 pb-10 space-y-10 animate-in fade-in duration-500">
             <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* 扇形图 A: 品类分布 */}
                <div className="bg-slate-50/40 p-8 rounded-[40px] border border-slate-100 relative group">
                   <div className="flex justify-between items-start mb-8">
                     <div>
                       <h4 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-1">主营品类贡献度</h4>
                       <p className="text-[10px] font-bold text-slate-400">点击扇区穿透查看明细</p>
                     </div>
                     <div className="flex bg-slate-200/50 p-1.5 rounded-2xl shadow-inner">
                       <button onClick={() => setPieMetric('sales')} className={`px-5 py-2 rounded-xl text-[10px] font-black transition-all ${pieMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500 hover:text-slate-800'}`}>金额</button>
                       <button onClick={() => setPieMetric('quantity')} className={`px-5 py-2 rounded-xl text-[10px] font-black transition-all ${pieMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500 hover:text-slate-800'}`}>数量</button>
                     </div>
