                   <div className="h-[400px] w-full">
                     <ResponsiveContainer width="100%" height="100%">
                       <PieChart>
                         <Pie data={sortedCategorySummary} cx="50%" cy="50%" innerRadius={80} outerRadius={120} paddingAngle={6} dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} label={renderCustomizedLabel} labelLine={false} onClick={(d) => openCategoryDrillDown(d.name)} stroke="none" animationBegin={200} animationDuration={1000}>
                           {sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} className="hover:opacity-80 cursor-pointer transition-opacity" />)}
                         </Pie>
