                       </PieChart>
                     </ResponsiveContainer>
                   </div>
                </div>

                {/* 扇形图 B: 物料明细分布 */}
                <div className="bg-slate-50/40 p-8 rounded-[40px] border border-slate-100 relative group">
                   <div className="flex justify-between items-start mb-8">
                     <div>
                       <h4 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-1">具体物料 Top 10</h4>
