                       <button onClick={() => setItemPieMetric('sales')} className={`px-5 py-2 rounded-xl text-[10px] font-black transition-all ${itemPieMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500 hover:text-slate-800'}`}>金额</button>
                       <button onClick={() => setItemPieMetric('quantity')} className={`px-5 py-2 rounded-xl text-[10px] font-black transition-all ${itemPieMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500 hover:text-slate-800'}`}>数量</button>
                     </div>
