                   <div className="h-[400px] w-full">
                     <ResponsiveContainer width="100%" height="100%">
                       <PieChart>
                         <Pie data={sortedItemSummary} cx="50%" cy="50%" innerRadius={80} outerRadius={120} paddingAngle={4} dataKey={itemPieMetric === 'sales' ? 'sales' : 'quantity'} label={renderCustomizedLabel} labelLine={false} onClick={(d) => openItemDrillDown(d.name)} stroke="none" animationBegin={400} animationDuration={1200}>
                           {sortedItemSummary.map((_, i) => <RechartsCell key={i} fill={COLORS[(i + 3) % COLORS.length]} className="hover:opacity-80 cursor-pointer transition-opacity" />)}
                         </Pie>
                         <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.1)' }} />
                       </PieChart>
                     </ResponsiveContainer>
                   </div>
                </div>
             </div>
          </div>
        )}
      </section>

      {/* 模块3: 客户采购排行分析 */}
      <section className="bg-white rounded-[32px] shadow-sm border border-slate-200 overflow-hidden">
        <div onClick={() => toggleSection('ranking')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3"><span className="p-2.5 bg-amber-50 text-amber-600 rounded-2xl text-xl shadow-inner">👥</span> 客户采购活跃度排行</h3>
          <div className="flex bg-slate-100 p-1.5 rounded-2xl shadow-inner" onClick={(e) => e.stopPropagation()}>
            <button onClick={() => setCustomerMetric('sales')} className={`px-5 py-2 rounded-xl text-[10px] font-black transition-all ${customerMetric === 'sales' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>金额排行</button>
            <button onClick={() => setCustomerMetric('quantity')} className={`px-5 py-2 rounded-xl text-[10px] font-black transition-all ${customerMetric === 'quantity' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量排行</button>
          </div>
