                <Bar dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} radius={[0, 12, 12, 0]} barSize={34} onClick={(d) => openCustomerDrillDown(d.name)} animationDuration={1500}>
                  {customerRankingData.slice(0, 10).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}
                  <LabelList dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} position="right" formatter={(v: any) => customerMetric === 'sales' ? `${(v/1000000).toFixed(1)}M` : v} style={{fontSize: 10, fontWeight: 900, fill: '#64748b'}} offset={15} />
