                      </ResponsiveContainer>
                   </div>
                </div>
              </div>

              <div className="bg-white rounded-[44px] border border-slate-200 shadow-2xl overflow-hidden mb-12">
                 <div className="px-10 py-6 border-b border-slate-100 bg-slate-50 flex items-center justify-between text-left">
                    <span className="text-[11px] font-black uppercase tracking-widest text-slate-500">穿透业务审计清单 (实时风险标记)</span>
                    <div className="flex items-center gap-6">
