                       <span className="text-[11px] font-black bg-rose-600 text-white px-3 py-1 rounded-lg">合计待结: {drillDownAnalysis.tableTotalUnsettled.toLocaleString()} CFA</span>
                    </div>
                 </div>
                 <div className="overflow-x-auto max-h-[700px] custom-scrollbar">
                    <table className="min-w-full divide-y divide-slate-100 text-left">
                       <thead className="bg-white sticky top-0 z-[100] shadow-sm">
                          <tr>
                            <th className="px-10 py-5 text-left"><TableDropdownFilter field="id" label="单号" /></th>
                            <th className="px-10 py-5 text-left text-[11px] font-black text-slate-400 uppercase">业务日期</th>
                            {!selectedCustomer && <th className="px-10 py-5 text-left"><TableDropdownFilter field="customer" label="客户" /></th>}
                            <th className="px-10 py-5 text-left"><TableDropdownFilter field="itemName" label="物料品类" /></th>
                            <th className="px-10 py-5 text-right text-[11px] font-black text-slate-400 uppercase">成交额</th>
                            <th className="px-10 py-5 text-right text-[11px] font-black text-slate-400 uppercase">待结金额</th>
                            <th className="px-10 py-5 text-left text-[11px] font-black text-slate-400 uppercase">风险状态</th>
                          </tr>
                       </thead>
                       <tbody className="bg-white divide-y divide-slate-50 text-[13px]">
                          {drillDownAnalysis.tableRecords.map((r, i) => {
                            const today = new Date(); today.setHours(0, 0, 0, 0);
                            const dueDate = new Date(r.dueDate);
                            const diffDays = Math.ceil((dueDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
                            let colorClass = "text-emerald-600"; let statusText = "已结清"; let dotColor = "bg-emerald-500";
                            if (r.unsettledAmount > 0) {
                              if (diffDays < 0) {
                                colorClass = "text-rose-600 font-black"; statusText = `逾期 ${Math.abs(diffDays)} 天`; dotColor = "bg-rose-500 animate-pulse";
                              } else if (diffDays <= 7) {
                                colorClass = "text-amber-600 font-black"; statusText = `临期 ${diffDays} 天`; dotColor = "bg-amber-400";
                              } else {
                                colorClass = "text-emerald-700 font-bold"; statusText = `安全 (剩 ${diffDays} 天)`; dotColor = "bg-emerald-500";
                              }
                            }
                            return (
                              <tr key={`${r.id}-${i}`} className="hover:bg-slate-50 transition-colors">
                                 <td className="px-10 py-5 whitespace-nowrap font-mono font-black text-indigo-600"><button onClick={() => onSelectOrderId(r.id)} className="hover:underline">{r.id}</button></td>
                                 <td className="px-10 py-5 whitespace-nowrap font-bold text-slate-500">{r.date}</td>
                                 {!selectedCustomer && <td className="px-10 py-5 whitespace-nowrap font-black text-slate-900">{r.customer}</td>}
                                 <td className="px-10 py-5 whitespace-nowrap font-black text-slate-700 truncate max-w-[200px]">{r.itemName}</td>
                                 <td className="px-10 py-5 whitespace-nowrap text-right font-mono font-bold text-slate-400">{r.totalAmount.toLocaleString()}</td>
                                 <td className={`px-10 py-5 whitespace-nowrap text-right font-mono font-black ${r.unsettledAmount > 0 ? 'text-rose-600' : 'text-slate-300'}`}>{r.unsettledAmount.toLocaleString()}</td>
                                 <td className={`px-10 py-5 whitespace-nowrap ${colorClass}`}>
                                    <div className="flex items-center gap-3">
                                       <div className={`w-2.5 h-2.5 rounded-full ${dotColor}`}></div>
                                       <div className="flex flex-col leading-tight">
                                          <span className="font-black text-[12px]">{statusText}</span>
                                          <span className="text-[10px] opacity-60">账期至: {r.dueDate}</span>
                                       </div>
                                    </div>
                                 </td>
                              </tr>
                            );
                          })}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

