export const MOCK_SALES_DATA: SalesRecord[] = Array.from({ length: 150 }).map((_, i) => {
  const category = categories[Math.floor(Math.random() * categories.length)];
  const itemName = items[category][Math.floor(Math.random() * items[category].length)];
  const quantity = Math.floor(Math.random() * 50) + 1;
  const unitPrice = Math.floor(Math.random() * 2000) + 100;
  const totalAmount = quantity * unitPrice;
  const date = new Date(2024, Math.floor(Math.random() * 12), Math.floor(Math.random() * 28) + 1);

  // 添加缺失的财务属性
  // 随机模拟已结和未结金额
  const settledAmount = Math.random() > 0.3 ? totalAmount : Math.floor(Math.random() * totalAmount);
  const unsettledAmount = totalAmount - settledAmount;
  // 模拟 30 天账期
  const dueDate = new Date(date);
  dueDate.setDate(dueDate.getDate() + 30);

  return {
    id: `CK-${2024000 + i}`,
    month: `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`,
    date: date.toISOString().split('T')[0],
    customer: customers[Math.floor(Math.random() * customers.length)],
    salesperson: salespeople[Math.floor(Math.random() * salespeople.length)],
    category,
    itemName,
    quantity,
    unitPrice,
    totalAmount,
    settledAmount,
    unsettledAmount,
    dueDate: dueDate.toISOString().split('T')[0]
  };
}).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7', '#fb7185', '#2dd4bf', '#fbbf24'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  // 1. 各模块折叠状态
  const [sections, setSections] = useState({
    trend: true,
    composition: true,
    ranking: true,
    receivables: true
  });

  // 2. 展示维度切换状态
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [customerMetric, setCustomerMetric] = useState<'sales' | 'quantity'>('sales');
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');
  const [activeMetrics, setActiveMetrics] = useState({ amount: true, quantity: true });

  // 3. 深度分析面板（穿透分析）状态
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<string | null>(null);
  const [drillMetric, setDrillMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [isDebtMode, setIsDebtMode] = useState(false); 

  // 4. 穿透面板内部的联动过滤状态 (点击面板内图表时触发)
  const [localTableFilters, setLocalTableFilters] = useState({
    customer: '', 
    category: '',
    month: '' 
  });

  // 5. 穿透表格表头多选筛选状态
  const [columnFilters, setColumnFilters] = useState<Record<string, string[]>>({ 
    id: [], customer: [], salesperson: [], itemName: [] 
  });

  const [activeFilterMenu, setActiveFilterMenu] = useState<string | null>(null);
  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  const toggleSection = (key: keyof typeof sections) => {
    setSections(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- 核心计算 1: 业绩趋势 ---
  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set<string>(filteredData.map(d => d.month))).sort();
    const metrics = !activeMetrics.amount && !activeMetrics.quantity ? { amount: true, quantity: true } : activeMetrics;

    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return { name: month, amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0), quantity: monthRecords.reduce((s, r) => s + r.quantity, 0) };
      });
      const series: any[] = [];
      if (metrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (metrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }
    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set<string>(filteredData.map(d => String(d[dimKey])))).slice(0, 8);
    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (metrics.amount) series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor });
      if (metrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
    });
    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });
    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  // --- 核心计算 2: 业务构成 (双扇形图) ---
  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount; entry.quantity += d.quantity;
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries()).map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity })).sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity).slice(0, 15);
  }, [filteredData, itemPieMetric]);

  // --- 核心计算 3: 客户排行 ---
  const customerRankingData = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.customer) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount; entry.quantity += d.quantity;
      map.set(d.customer, entry);
    });
    return Array.from(map.entries()).map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity })).sort((a, b) => customerMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, customerMetric]);

  // --- 核心计算 4: 应付未付情况统计 ---
  const receivablesAnalysis = useMemo(() => {
    const today = new Date(); today.setHours(0, 0, 0, 0);
    let totalSettled = 0; let totalUnsettled = 0;
    const agingBuckets = [
      { name: '未到期', value: 0, color: '#10b981' },
      { name: '逾期1-30天', value: 0, color: '#f59e0b' },
      { name: '逾期31-60天', value: 0, color: '#f97316' },
      { name: '逾期60天+', value: 0, color: '#ef4444' }
    ];
    const customerDebtsMap = new Map<string, { settled: number; unsettled: number }>();
    filteredData.forEach(r => {
      totalSettled += r.settledAmount || 0; totalUnsettled += r.unsettledAmount || 0;
      const curDebt = customerDebtsMap.get(r.customer) || { settled: 0, unsettled: 0 };
      customerDebtsMap.set(r.customer, { settled: curDebt.settled + (r.settledAmount || 0), unsettled: curDebt.unsettled + (r.unsettledAmount || 0) });
      if (r.unsettledAmount > 0 && r.dueDate) {
        const dueDate = new Date(r.dueDate);
        const diffDays = Math.ceil((today.getTime() - dueDate.getTime()) / (1000 * 60 * 60 * 24));
        if (diffDays <= 0) agingBuckets[0].value += r.unsettledAmount;
        else if (diffDays <= 30) agingBuckets[1].value += r.unsettledAmount;
        else if (diffDays <= 60) agingBuckets[2].value += r.unsettledAmount;
        else agingBuckets[3].value += r.unsettledAmount;
      }
    });
    const allDebtors = Array.from(customerDebtsMap.entries()).map(([name, val]) => ({ name, settled: val.settled, unsettled: val.unsettled, total: val.settled + val.unsettled })).filter(d => d.unsettled > 0).sort((a, b) => b.unsettled - a.unsettled);
    return { totalSettled, totalUnsettled, agingBuckets, allDebtors, composition: [{ name: '已结算', value: totalSettled, color: '#10b981' }, { name: '待回款', value: totalUnsettled, color: '#fb7185' }] };
  }, [filteredData]);

  // --- 核心计算 5: 穿透分析面板的深度逻辑 (完整恢复) ---
  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : (selectedCustomer ? 'customer' : null));
    const value = selectedCategory || selectedItem || selectedCustomer;
    if (!dimension || !value) return { baseRecords: [], tableRecords: [], secondaryDistribution: [], monthlyTrend: [], tableTotalSales: 0, tableTotalUnsettled: 0, filterOptions: { id: [], customer: [], salesperson: [], itemName: [] } };

    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);

    // 计算二级分布 (柱状图)
    const recordsForDist = localTableFilters.month ? baseRecords.filter(r => r.month === localTableFilters.month) : baseRecords;
    const secondaryDim = selectedCustomer ? 'category' : 'customer';
    const distMap = new Map<string, { sales: number; qty: number }>();
    recordsForDist.forEach(r => {
      const key = r[secondaryDim] as string;
      const e = distMap.get(key) || { sales: 0, qty: 0 };
      distMap.set(key, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });
    const secondaryDistribution = Array.from(distMap.entries()).map(([name, v]) => ({ name, sales: v.sales, qty: v.qty })).sort((a, b) => drillMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);

    // 计算趋势 (面积图)
    let recordsForTrend = baseRecords;
    if (localTableFilters.customer && !selectedCustomer) recordsForTrend = recordsForTrend.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.category && selectedCustomer) recordsForTrend = recordsForTrend.filter(r => r.category === localTableFilters.category);
    const monthlyMap = new Map<string, { sales: number; qty: number }>();
    recordsForTrend.forEach(r => {
      const e = monthlyMap.get(r.month) || { sales: 0, qty: 0 };
      monthlyMap.set(r.month, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity });
    });
    const monthlyTrend = Array.from(new Set<string>(baseRecords.map(r => r.month))).sort().map(m => {
      const v = monthlyMap.get(m) || { sales: 0, qty: 0 };
      return { name: m, sales: v.sales, qty: v.qty };
    });

    // 计算表格数据及过滤选项
    let finalRecords = baseRecords;
    if (localTableFilters.month) finalRecords = finalRecords.filter(r => r.month === localTableFilters.month);
    if (localTableFilters.customer && !selectedCustomer) finalRecords = finalRecords.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.category && selectedCustomer) finalRecords = finalRecords.filter(r => r.category === localTableFilters.category);

    Object.entries(columnFilters).forEach(([field, selectedValues]) => {
      const castedValues = selectedValues as string[];
      if (castedValues.length > 0) finalRecords = finalRecords.filter(r => castedValues.includes(String(r[field as keyof SalesRecord])));
    });

    const filterOptions = {
      id: Array.from(new Set(baseRecords.map(r => r.id))).sort(),
      customer: Array.from(new Set(baseRecords.map(r => r.customer))).sort(),
      salesperson: Array.from(new Set(baseRecords.map(r => r.salesperson))).sort(),
      itemName: Array.from(new Set(baseRecords.map(r => r.itemName))).sort()
    };

    return {
      baseRecords,
      tableRecords: finalRecords.sort((a, b) => b.date.localeCompare(a.date)),
      secondaryDistribution,
      monthlyTrend,
      tableTotalSales: finalRecords.reduce((s, r) => s + r.totalAmount, 0),
      tableTotalUnsettled: finalRecords.reduce((acc, cur) => acc + cur.unsettledAmount, 0),
      filterOptions,
      contextTitle: selectedCustomer ? '品类偏好分析' : '关联客户分布'
    };
  }, [selectedCategory, selectedItem, selectedCustomer, filteredData, localTableFilters, columnFilters, drillMetric]);

  // --- 辅助功能 ---
  const openCategoryDrillDown = (name: string) => { setDrillMetric(pieMetric); setSelectedCategory(name); setSelectedItem(null); setSelectedCustomer(null); setIsDebtMode(false); clearDrillFilters(); };
  const openItemDrillDown = (name: string) => { setDrillMetric(itemPieMetric); setSelectedItem(name); setSelectedCategory(null); setSelectedCustomer(null); setIsDebtMode(false); clearDrillFilters(); };
  const openCustomerDrillDown = (name: string, debtOnly = false) => { setDrillMetric(customerMetric); setSelectedCustomer(name); setSelectedCategory(null); setSelectedItem(null); setIsDebtMode(debtOnly); clearDrillFilters(); };
  const clearDrillFilters = () => { setLocalTableFilters({ customer: '', category: '', month: '' }); setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] }); };

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const cos = Math.cos(-RADIAN * midAngle);
    const ex = cx + (outerRadius + 30) * cos;
    const ey = cy + (outerRadius + 30) * Math.sin(-RADIAN * midAngle);
    return <g><text x={ex} y={ey} textAnchor={cos >= 0 ? 'start' : 'end'} fill="#475569" style={{ fontSize: '10px', fontWeight: 900 }}>{name} ({(percent * 100).toFixed(0)}%)</text></g>;
  };

  const TableDropdownFilter = ({ field, label }: { field: string, label: string }) => {
    const options = (drillDownAnalysis.filterOptions as Record<string, string[]>)?.[field] || [];
    const selected = columnFilters[field] || [];
    const menuRef = useRef<HTMLDivElement>(null);
    useEffect(() => {
      const handleClickOutside = (e: MouseEvent) => { if (menuRef.current && !menuRef.current.contains(e.target as Node)) setActiveFilterMenu(null); };
      if (activeFilterMenu === field) document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [activeFilterMenu, field]);

    return (
      <div className="relative inline-block text-left" ref={menuRef}>
        <button onClick={() => setActiveFilterMenu(activeFilterMenu === field ? null : field)} className={`flex items-center gap-2 px-2 py-1 rounded transition-colors ${selected.length > 0 ? 'text-indigo-600 bg-indigo-50' : 'text-slate-400'}`}>
          <span className="text-[10px] font-black uppercase tracking-widest">{label}</span>
          <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg>
        </button>
        {activeFilterMenu === field && (
          <div className="absolute top-full left-0 mt-2 w-56 bg-white border border-slate-200 shadow-2xl rounded-2xl z-[6000] p-1 animate-in fade-in zoom-in-95 duration-150">
            <div className="max-h-48 overflow-y-auto custom-scrollbar p-1">
              {options.map(opt => (
                <button key={opt} onClick={() => setColumnFilters(p => ({ ...p, [field]: selected.includes(opt) ? selected.filter(v => v !== opt) : [...selected, opt] }))} className={`w-full text-left px-3 py-2 text-xs rounded-lg mb-0.5 flex justify-between items-center ${selected.includes(opt) ? 'bg-indigo-600 text-white shadow-md' : 'hover:bg-slate-50 text-slate-700'}`}>
                  <span className="truncate">{opt}</span>{selected.includes(opt) && <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7" /></svg>}
                </button>
              ))}
            </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-10 pb-16 relative text-left">
      {/* 顶部指标 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-6 h-[110px]">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
           <div><p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-1">销售总额 (CFA)</p><p className="text-3xl font-black text-slate-900">{summary.totalSales.toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-6 h-[110px]">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
           <div><p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-1">出库总量</p><p className="text-3xl font-black text-slate-900">{summary.totalQuantity.toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-3xl border border-slate-200 shadow-sm h-[110px] overflow-hidden group">
           <div className="p-6 flex items-center justify-between">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div>
                <div><p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-1">单据总数</p><p className="text-3xl font-black text-slate-900">{summary.orderCount}</p></div>
              </div>
              <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2.5 bg-slate-50 border border-slate-100 rounded-xl hover:bg-slate-200"><svg className={`w-5 h-5 transition-transform ${isOrdersExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg></button>
           </div>
           {isOrdersExpanded && (
              <div className="absolute top-[110px] left-0 right-0 bg-white border border-slate-200 p-6 z-[200] shadow-2xl rounded-b-3xl animate-in fade-in duration-300">
                <input type="text" placeholder="搜索出库单号..." value={orderSearchTerm} onChange={(e) => setOrderSearchTerm(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs outline-none mb-4 font-bold" />
                <div className="max-h-56 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar">{summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase())).map(id => (<button key={id} onClick={() => onSelectOrderId(id)} className="px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-bold hover:border-indigo-500 hover:text-indigo-600 transition-all">{id}</button>))}</div>
              </div>
           )}
        </div>
      </div>

      {/* 模块1: 业绩趋势 */}
      <section className="bg-white rounded-[32px] shadow-sm border border-slate-200 overflow-hidden">
        <div onClick={() => toggleSection('trend')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3"><span className="p-2.5 bg-indigo-50 text-indigo-600 rounded-2xl text-xl">📈</span> 业绩增长趋势分析</h3>
          <div className="flex items-center gap-4" onClick={(e) => e.stopPropagation()}>
            <div className="flex bg-slate-100 p-1 rounded-2xl border border-slate-200">
              <button onClick={() => setTrendMode('total')} className={`px-5 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'total' ? 'bg-white shadow-md text-slate-900' : 'text-slate-500'}`}>汇总</button>
              <button onClick={() => setTrendMode('customer')} className={`px-5 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'customer' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>按客户</button>
              <button onClick={() => setTrendMode('salesperson')} className={`px-5 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'salesperson' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>按销售</button>
            </div>
            <button className="p-2.5 bg-slate-50 border border-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${sections.trend ? 'rotate-180 text-indigo-600' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg></button>
          </div>
        </div>
        {sections.trend && (
          <div className="px-8 pb-10 h-[450px] animate-in fade-in">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendAnalysis.data}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11, fontWeight: 700}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 800}} tickFormatter={(v) => `${(v / 1000000).toFixed(1)}M`} />
                <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.1)' }} />
                <Legend iconType="circle" />
                {trendAnalysis.series.map((s) => (<Area key={s.key} type="monotone" dataKey={s.key} name={s.name} stroke={s.color} strokeWidth={4} fill={s.color} fillOpacity={0.05} />))}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        )}
      </section>

      {/* 模块2: 核心业务构成 (恢复完整双扇形图) */}
      <section className="bg-white rounded-[32px] shadow-sm border border-slate-200 overflow-hidden">
        <div onClick={() => toggleSection('composition')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3"><span className="p-2.5 bg-emerald-50 text-emerald-600 rounded-2xl text-xl">🧩</span> 核心业务构成深度分析</h3>
          <button className="p-2.5 bg-slate-50 border border-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${sections.composition ? 'rotate-180 text-emerald-600' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg></button>
        </div>
        {sections.composition && (
