/**
 * 标准化日期字符串为 YYYY-MM-DD
 */
const formatDateString = (dateStr: string): string => {
  if (!dateStr) return '';
  try {
    const normalized = dateStr.replace(/\//g, '-');
    const date = new Date(normalized);
    if (isNaN(date.getTime())) {
      const parts = normalized.split('-');
      if (parts.length === 3) {
        return `${parts[0]}-${parts[1].padStart(2, '0')}-${parts[2].padStart(2, '0')}`;
      }
      return dateStr;
    }
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  } catch (e) {
    return dateStr;
  }
};

/**
 * 解析 CSV 文本
 */
export const processCsvText = (csvText: string): SalesRecord[] => {
  const rows = csvText.split(/\r?\n/).filter(line => line.trim() !== '');
  const parsedRows = rows.map(line => {
    const result: string[] = [];
    let currentField = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') inQuotes = !inQuotes;
      else if (char === ',' && !inQuotes) {
        result.push(currentField.replace(/^"|"$/g, '').trim());
        currentField = '';
      } else currentField += char;
    }
    result.push(currentField.replace(/^"|"$/g, '').trim());
    return result;
  });

  const dataRows = parsedRows.slice(1);
  return dataRows.map((cols, index) => {
    const rawDate = cols[2] || '';
    const standardizedDate = formatDateString(rawDate);

    // 提取财务结算数据（假设在第11, 12, 13列）
    const settledAmount = parseFloat(cols[10]) || 0;
    const unsettledAmount = parseFloat(cols[11]) || 0;
    const rawDueDate = cols[12] || rawDate;

    return {
      id: cols[0] || `ID-${index}`,
      month: cols[1] || '',
      date: standardizedDate,
      customer: cols[3] || '',
      salesperson: cols[4] || '',
      category: cols[5] || '',
      itemName: cols[6] || '',
      quantity: parseFloat(cols[7]) || 0,
      unitPrice: parseFloat(cols[8]) || 0,
      totalAmount: parseFloat(cols[9]) || 0,
      settledAmount: settledAmount,
      unsettledAmount: unsettledAmount,
      dueDate: formatDateString(rawDueDate)
    };
  });
};

