import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7', '#fb7185', '#2dd4bf', '#fbbf24'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  // 1. 各模块折叠状态
  const [sections, setSections] = useState({
    trend: true,
    composition: true,
    ranking: true,
    receivables: true
  });

  // 2. 展示维度切换状态
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [customerMetric, setCustomerMetric] = useState<'sales' | 'quantity'>('sales');
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');
  const [activeMetrics, setActiveMetrics] = useState({ amount: true, quantity: true });

  // 3. 深度分析面板（穿透分析）状态
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<string | null>(null);
  const [isDebtMode, setIsDebtMode] = useState(false); 

  // 4. 下钻列表过滤状态
  const [columnFilters, setColumnFilters] = useState<Record<string, string[]>>({ 
    id: [], customer: [], salesperson: [], itemName: [] 
  });
  const [activeFilterMenu, setActiveFilterMenu] = useState<string | null>(null);
  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  const toggleSection = (key: keyof typeof sections) => {
    setSections(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- 模块 1 数据计算：业绩增长趋势 ---
  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set<string>(filteredData.map(d => d.month))).sort();
    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return { 
          name: month, 
          amount: monthRecords.reduce((s, r) => s + r.totalAmount, 0), 
          quantity: monthRecords.reduce((s, r) => s + r.quantity, 0) 
        };
      });
      const series: any[] = [];
      if (activeMetrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (activeMetrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }
    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set<string>(filteredData.map(d => String(d[dimKey])))).slice(0, 8);
    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (activeMetrics.amount) series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor });
      if (activeMetrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
    });
    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + r.totalAmount, 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + r.quantity, 0);
      });
      return row;
    });
    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  // --- 模块 2 数据计算：业务构成分析 (品类 + 物料) ---
  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount; entry.quantity += d.quantity;
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity)
      .slice(0, 10);
  }, [filteredData, itemPieMetric]);

  // --- 模块 3 数据计算：客户采购排行 ---
  const customerRankingData = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.customer) || { sales: 0, quantity: 0 };
      entry.sales += d.totalAmount; entry.quantity += d.quantity;
      map.set(d.customer, entry);
    });
    return Array.from(map.entries())
      .map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity }))
      .sort((a, b) => customerMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, customerMetric]);

  // --- 模块 4 数据计算：应付未付情况统计 ---
  const receivablesAnalysis = useMemo(() => {
    const today = new Date(); today.setHours(0, 0, 0, 0);
    let totalSettled = 0; let totalUnsettled = 0;
    const agingBuckets = [
      { name: '未到期', value: 0, color: '#10b981' },
      { name: '逾期1-30天', value: 0, color: '#f59e0b' },
      { name: '逾期31-60天', value: 0, color: '#f97316' },
      { name: '逾期60天+', value: 0, color: '#ef4444' }
    ];
    const customerDebtsMap = new Map<string, { settled: number; unsettled: number }>();
    filteredData.forEach(r => {
      totalSettled += r.settledAmount || 0; totalUnsettled += r.unsettledAmount || 0;
      const curDebt = customerDebtsMap.get(r.customer) || { settled: 0, unsettled: 0 };
      customerDebtsMap.set(r.customer, { 
        settled: curDebt.settled + (r.settledAmount || 0), 
        unsettled: curDebt.unsettled + (r.unsettledAmount || 0) 
      });
      if ((r.unsettledAmount || 0) > 0 && r.dueDate) {
        const dueDate = new Date(r.dueDate);
        const diffDays = Math.ceil((today.getTime() - dueDate.getTime()) / (1000 * 60 * 60 * 24));
        if (diffDays <= 0) agingBuckets[0].value += (r.unsettledAmount || 0);
        else if (diffDays <= 30) agingBuckets[1].value += (r.unsettledAmount || 0);
        else if (diffDays <= 60) agingBuckets[2].value += (r.unsettledAmount || 0);
        else agingBuckets[3].value += (r.unsettledAmount || 0);
      }
    });
    const allDebtors = Array.from(customerDebtsMap.entries())
      .map(([name, val]) => ({ 
        name, settled: val.settled, unsettled: val.unsettled, total: val.settled + val.unsettled 
      }))
      .filter(d => d.unsettled > 0)
      .sort((a, b) => b.unsettled - a.unsettled);
    return { 
      totalSettled, totalUnsettled, agingBuckets, allDebtors, 
      composition: [
        { name: '已结算', value: totalSettled, color: '#10b981' }, 
        { name: '待回款', value: totalUnsettled, color: '#fb7185' }
      ] 
    };
  }, [filteredData]);

  // --- 穿透分析穿透逻辑 ---
  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : (selectedCustomer ? 'customer' : null));
    const value = selectedCategory || selectedItem || selectedCustomer;
    if (!dimension || !value) return { tableRecords: [], totalSales: 0, tableTotalUnsettled: 0, filterOptions: { id: [], customer: [], salesperson: [], itemName: [] } };

    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);
    const filterOptions = { 
      id: Array.from(new Set(baseRecords.map(r => r.id))).sort(), 
      customer: Array.from(new Set(baseRecords.map(r => r.customer))).sort(), 
      salesperson: Array.from(new Set(baseRecords.map(r => r.salesperson))).sort(), 
      itemName: Array.from(new Set(baseRecords.map(r => r.itemName))).sort() 
    };

    let finalRecords = baseRecords;
    Object.entries(columnFilters).forEach(([field, selectedValues]) => {
      const castedValues = selectedValues as string[];
      if (castedValues.length > 0) finalRecords = finalRecords.filter(r => castedValues.includes(String(r[field as keyof SalesRecord])));
    });

    return {
      tableRecords: finalRecords.sort((a, b) => b.date.localeCompare(a.date)),
      totalSales: baseRecords.reduce((s, r) => s + (r.totalAmount || 0), 0),
      tableTotalUnsettled: finalRecords.reduce((acc, cur) => acc + (cur.unsettledAmount || 0), 0),
      filterOptions
    };
  }, [selectedCategory, selectedItem, selectedCustomer, filteredData, columnFilters]);

  // --- 辅助点击与渲染函数 ---
  const openCategoryDrillDown = (name: string) => { setIsDebtMode(false); setSelectedCategory(name); setSelectedItem(null); setSelectedCustomer(null); };
  const openItemDrillDown = (name: string) => { setIsDebtMode(false); setSelectedItem(name); setSelectedCategory(null); setSelectedCustomer(null); };
  const openCustomerDrillDown = (name: string, debtOnly: boolean = false) => { setIsDebtMode(debtOnly); setSelectedCustomer(name); setSelectedCategory(null); setSelectedItem(null); };

  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const cos = Math.cos(-RADIAN * midAngle);
    const ex = cx + (outerRadius + 30) * cos;
    const ey = cy + (outerRadius + 30) * Math.sin(-RADIAN * midAngle);
    return (
      <g>
        <text x={ex} y={ey} textAnchor={cos >= 0 ? 'start' : 'end'} fill="#475569" style={{ fontSize: '10px', fontWeight: 900 }}>
          {name} ({(percent * 100).toFixed(0)}%)
        </text>
      </g>
    );
  };

  const TableDropdownFilter = ({ field, label }: { field: string, label: string }) => {
    const options = (drillDownAnalysis.filterOptions as Record<string, string[]>)?.[field] || [];
    const selected = columnFilters[field] || [];
    const menuRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
      const handleClickOutside = (e: MouseEvent) => { if (menuRef.current && !menuRef.current.contains(e.target as Node)) setActiveFilterMenu(null); };
      if (activeFilterMenu === field) document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [activeFilterMenu, field]);

    return (
      <div className="relative inline-block text-left" ref={menuRef}>
        <button onClick={() => setActiveFilterMenu(activeFilterMenu === field ? null : field)} className={`flex items-center gap-2 px-2 py-1 rounded group transition-colors ${selected.length > 0 ? 'text-indigo-600 bg-indigo-50' : 'text-slate-400 hover:bg-slate-50'}`}>
          <span className="text-[10px] font-black uppercase tracking-widest">{label}</span>
          <svg className={`w-3 h-3 transition-transform ${activeFilterMenu === field ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg>
        </button>
        {activeFilterMenu === field && (
          <div className="absolute top-full left-0 mt-2 w-56 bg-white border border-slate-200 shadow-2xl rounded-2xl z-[6000] p-1 animate-in fade-in zoom-in-95 duration-150">
            <div className="max-h-48 overflow-y-auto custom-scrollbar p-1">
              <button onClick={() => setColumnFilters(p => ({...p, [field]: []}))} className="w-full text-left px-3 py-1.5 text-[10px] font-black text-red-500 hover:bg-red-50 rounded-lg mb-1 uppercase">清除选择</button>
              {options.map(opt => (
                <button key={opt} onClick={() => setColumnFilters(p => ({ ...p, [field]: selected.includes(opt) ? selected.filter(v => v !== opt) : [...selected, opt] }))} className={`w-full text-left px-3 py-2 text-xs rounded-lg mb-0.5 flex justify-between items-center ${selected.includes(opt) ? 'bg-indigo-600 text-white shadow-md' : 'hover:bg-slate-50 text-slate-700'}`}>
                  <span className="truncate">{opt}</span>
                  {selected.includes(opt) && <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7" /></svg>}
                </button>
              ))}
            </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-10 pb-16 relative text-left">
      {/* 顶部总计指标栏 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-6 h-[110px] hover:shadow-md transition-shadow">
           <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600 shadow-inner">💰</div>
           <div><p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-1">总计销售金额 (CFA)</p><p className="text-3xl font-black text-slate-900 tracking-tighter">{(summary.totalSales || 0).toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm flex items-center gap-6 h-[110px] hover:shadow-md transition-shadow">
           <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600 shadow-inner">📦</div>
           <div><p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-1">出库物料总量</p><p className="text-3xl font-black text-slate-900 tracking-tighter">{(summary.totalQuantity || 0).toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-3xl border border-slate-200 shadow-sm flex flex-col overflow-hidden h-[110px] hover:shadow-md transition-shadow group relative">
           <div className="p-6 flex items-center justify-between">
              <div className="flex items-center gap-6">
                <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600 shadow-inner">📑</div>
                <div><p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-1">成交单据总数</p><p className="text-3xl font-black text-slate-900 tracking-tighter">{(summary.orderCount || 0)}</p></div>
              </div>
              <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2.5 bg-slate-50 border border-slate-100 rounded-xl hover:bg-slate-200 transition-colors"><svg className={`w-5 h-5 transition-transform ${isOrdersExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg></button>
           </div>
           {isOrdersExpanded && (
              <div className="absolute top-full left-0 right-0 bg-white border border-slate-200 p-6 z-[200] shadow-2xl rounded-b-3xl animate-in fade-in slide-in-from-top-2 duration-300">
                <div className="relative mb-4">
                  <input type="text" placeholder="搜索出库单号..." value={orderSearchTerm} onChange={(e) => setOrderSearchTerm(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-xs outline-none focus:ring-2 focus:ring-indigo-100 font-bold" />
                  <svg className="w-4 h-4 absolute right-4 top-2.5 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                </div>
                <div className="max-h-56 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar pr-2">
                  {summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase())).map(id => (<button key={id} onClick={() => onSelectOrderId(id)} className="px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-bold hover:border-indigo-500 hover:text-indigo-600 hover:bg-indigo-50 transition-all">{id}</button>))}
                </div>
              </div>
           )}
        </div>
      </div>

      {/* 模块1: 业绩趋势分析 */}
      <section className="bg-white rounded-[32px] shadow-sm border border-slate-200 overflow-hidden">
        <div onClick={() => toggleSection('trend')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3"><span className="p-2.5 bg-indigo-50 text-indigo-600 rounded-2xl text-xl shadow-inner">📈</span> 销售业绩增长趋势</h3>
          <div className="flex items-center gap-4" onClick={(e) => e.stopPropagation()}>
            <div className="flex bg-slate-100 p-1 rounded-2xl border border-slate-200 shadow-inner">
              <button onClick={() => setTrendMode('total')} className={`px-5 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'total' ? 'bg-white shadow-md text-slate-900' : 'text-slate-500 hover:text-slate-700'}`}>汇总</button>
              <button onClick={() => setTrendMode('customer')} className={`px-5 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'customer' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500 hover:text-slate-700'}`}>按客户</button>
              <button onClick={() => setTrendMode('salesperson')} className={`px-5 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'salesperson' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500 hover:text-slate-700'}`}>按销售</button>
            </div>
            <button className="p-2.5 bg-slate-50 border border-slate-100 rounded-xl hover:bg-slate-200"><svg className={`w-5 h-5 transition-transform ${sections.trend ? 'rotate-180 text-indigo-600' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg></button>
          </div>
        </div>
        {sections.trend && (
          <div className="px-8 pb-10 h-[450px] animate-in fade-in duration-500">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendAnalysis.data} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  {trendAnalysis.series.map(s => (
                    <linearGradient key={`grad-${s.key}`} id={`grad-${s.key}`} x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor={s.color} stopOpacity={0.15}/>
                      <stop offset="95%" stopColor={s.color} stopOpacity={0.01}/>
                    </linearGradient>
                  ))}
