        <div onClick={() => toggleSection('receivables')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors">
          <div className="flex flex-col gap-1">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-3"><span className="p-2.5 bg-rose-50 text-rose-600 rounded-2xl text-xl shadow-inner">📅</span> 应付未付情况与风险审计</h3>
            {sections.receivables && <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-[58px]">共有 {receivablesAnalysis.allDebtors.length} 名客户存在待回笼资金</p>}
          </div>
          <button className="p-2.5 bg-slate-50 border border-slate-100 rounded-xl hover:bg-slate-200 transition-colors"><svg className={`w-5 h-5 transition-transform ${sections.receivables ? 'rotate-180 text-rose-600' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg></button>
        </div>
        {sections.receivables && (
          <div className="px-8 pb-12 space-y-12 animate-in fade-in duration-600">
             <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                {/* 结算构成图 */}
                <div className="bg-slate-50/50 p-10 rounded-[44px] border border-slate-100 flex items-center gap-12">
                   <div className="w-44 h-44 flex-shrink-0">
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie data={receivablesAnalysis.composition} innerRadius={65} outerRadius={85} paddingAngle={12} dataKey="value" stroke="none">
                            {receivablesAnalysis.composition.map((entry, i) => <RechartsCell key={i} fill={entry.color} />)}
                          </Pie>
                          <Tooltip />
                        </PieChart>
                      </ResponsiveContainer>
                   </div>
                   <div className="flex-1 space-y-8">
                      <div><h4 className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-1.5">已结清回款</h4><p className="text-3xl font-black text-emerald-600 tabular-nums tracking-tighter">{(receivablesAnalysis.totalSettled || 0).toLocaleString()} CFA</p></div>
                      <div><h4 className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-1.5">待收回款 (风险暴露)</h4><p className="text-3xl font-black text-rose-600 tabular-nums tracking-tighter">{(receivablesAnalysis.totalUnsettled || 0).toLocaleString()} CFA</p></div>
                   </div>
                </div>
                {/* 账期风险分布图 */}
                <div className="bg-slate-50/50 p-10 rounded-[44px] border border-slate-100 h-[280px]">
                   <h4 className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-8 text-center">账期逾期风险金额分布 (到期日审计)</h4>
                   <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={receivablesAnalysis.agingBuckets}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontStyle: 'normal', fontWeight: 900, fill: '#64748b'}} />
                        <YAxis hide />
                        <Tooltip cursor={{fill: 'transparent'}} />
                        <Bar dataKey="value" radius={[10, 10, 0, 0]} barSize={48}>
                           {receivablesAnalysis.agingBuckets.map((entry, i) => <RechartsCell key={i} fill={entry.color} />)}
                           <LabelList dataKey="value" position="top" formatter={(v: any) => `${((v || 0)/1000000).toFixed(1)}M`} style={{fontSize: 10, fontWeight: 900, fill: '#64748b'}} offset={10} />
                        </Bar>
                      </BarChart>
                   </ResponsiveContainer>
                </div>
             </div>

             {/* 欠款客户全量明细表 */}
             <div className="bg-white rounded-[40px] border border-slate-200 shadow-xl overflow-hidden">
                <div className="px-10 py-6 bg-slate-50 border-b border-slate-100 flex items-center justify-between">
                   <span className="text-[11px] font-black text-slate-500 uppercase tracking-[0.25em]">所有未结清客户明细看板 (点击单行穿透审计)</span>
                </div>
                <div className="overflow-x-auto max-h-[500px] custom-scrollbar">
                   <table className="min-w-full divide-y divide-slate-100">
                      <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm">
                         <tr>
                            <th className="px-10 py-5 text-left text-[11px] font-black text-slate-400 uppercase tracking-widest">欠款客户名称</th>
                            <th className="px-10 py-5 text-right text-[11px] font-black text-slate-400 uppercase tracking-widest">待结余额 (CFA)</th>
                            <th className="px-10 py-5 text-left text-[11px] font-black text-slate-400 uppercase tracking-widest pl-16">整体资金回笼进度</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                         {receivablesAnalysis.allDebtors.map((debtor) => {
                           const ratio = (debtor.settled / (debtor.total || 1)) * 100;
                           return (
                             <tr key={debtor.name} className="hover:bg-slate-50 transition-colors cursor-pointer group" onClick={() => openCustomerDrillDown(debtor.name, true)}>
                               <td className="px-10 py-5 text-base font-black text-slate-900 group-hover:text-indigo-600 transition-colors">{debtor.name}</td>
                               <td className="px-10 py-5 text-base font-mono font-black text-rose-600 text-right">{(debtor.unsettled || 0).toLocaleString()}</td>
                               <td className="px-10 py-5 pl-16">
                                  <div className="flex items-center gap-5">
                                    <div className="flex-1 h-2.5 bg-slate-100 rounded-full overflow-hidden shadow-inner">
                                      <div className={`h-full transition-all duration-1000 ${ratio > 70 ? 'bg-emerald-500' : ratio > 30 ? 'bg-amber-400' : 'bg-rose-500'}`} style={{ width: `${ratio}%` }}></div>
                                    </div>
                                    <span className="text-xs font-black text-slate-500 font-mono w-12 text-right">{ratio.toFixed(0)}%</span>
                                  </div>
                               </td>
                             </tr>
                           );
                         })}
                      </tbody>
                   </table>
                </div>
             </div>
          </div>
        )}
      </section>

      {/* 增强型深度下钻审计面板 (全屏 Modal) */}
      {(selectedCategory || selectedItem || selectedCustomer) && (
        <div className="fixed inset-0 bg-white z-[5000] flex flex-col animate-in slide-in-from-bottom-12 duration-600 overflow-hidden text-left">
           {/* 面板头部 */}
           <div className={`px-12 py-8 border-b border-slate-200 bg-white flex items-center justify-between shadow-sm z-50 ${isDebtMode ? 'border-t-[12px] border-t-rose-500' : 'border-t-[12px] border-t-indigo-600'}`}>
              <div className="flex items-center gap-6">
                <div className={`w-16 h-16 rounded-[22px] flex items-center justify-center text-white text-2xl shadow-2xl ${isDebtMode ? 'bg-rose-600' : 'bg-indigo-600'}`}>
                  {isDebtMode ? '🚨' : '🧪'}
                </div>
                <div>
                  <h3 className="text-3xl font-black text-slate-900 tracking-tight">
                    {selectedCategory || selectedItem || selectedCustomer} 
                    <span className="mx-4 text-slate-200 font-light">|</span> 
                    <span className={isDebtMode ? 'text-rose-600' : 'text-indigo-600'}>
                      {isDebtMode ? '应收账单实时风险审计' : '多维业务明细穿透分析'}
                    </span>
                  </h3>
                  <p className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em] mt-2">
                    系统已自动聚合所有历史关联交易数据 · 状态：三色风险等级同步
                  </p>
                </div>
              </div>
              <button onClick={() => { setSelectedCategory(null); setSelectedItem(null); setSelectedCustomer(null); setIsDebtMode(false); setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] }); }} className="px-14 py-4 bg-slate-900 text-white rounded-[24px] text-sm font-black hover:bg-slate-800 transition-all shadow-2xl hover:-translate-y-1">关闭分析面板</button>
           </div>

           {/* 面板主体 */}
           <div className="flex-1 overflow-y-auto custom-scrollbar p-12 bg-slate-50/50 space-y-12">
              {/* 指标卡片 */}
              <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm">
                  <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-2">成交总额 (全量审计)</p>
                  <p className="text-3xl font-black text-indigo-600 tabular-nums">{(drillDownAnalysis.totalSales || 0).toLocaleString()} <span className="text-xs">CFA</span></p>
                </div>
                <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm">
                  <p className="text-[11px] font-black text-rose-500 uppercase tracking-widest mb-2">待结算金额 (当前存续)</p>
                  <p className="text-3xl font-black text-rose-600 tabular-nums">{(drillDownAnalysis.tableTotalUnsettled || 0).toLocaleString()} <span className="text-xs">CFA</span></p>
                </div>
                <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm col-span-2 flex items-center justify-around">
                   <div className="flex items-center gap-3">
                     <div className="w-3.5 h-3.5 rounded-full bg-rose-500 animate-pulse"></div>
                     <span className="text-[12px] font-black text-slate-500 uppercase">红色: 已逾期/呆账</span>
                   </div>
                   <div className="flex items-center gap-3">
                     <div className="w-3.5 h-3.5 rounded-full bg-amber-400"></div>
                     <span className="text-[12px] font-black text-slate-500 uppercase">黄色: 7天内到期</span>
                   </div>
                   <div className="flex items-center gap-3">
                     <div className="w-3.5 h-3.5 rounded-full bg-emerald-500"></div>
                     <span className="text-[12px] font-black text-slate-500 uppercase">绿色: 款项结清/安全</span>
                   </div>
                </div>
              </div>

              {/* 明细表格 */}
              <div className="bg-white rounded-[44px] border border-slate-200 shadow-2xl overflow-hidden mb-12">
                 <div className="px-10 py-6 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
                    <span className="text-[11px] font-black uppercase tracking-[0.3em] text-slate-500">穿透业务明细数据清单 (已启用实时表头过滤)</span>
                 </div>
                 <div className="overflow-x-auto max-h-[700px] custom-scrollbar">
                    <table className="min-w-full divide-y divide-slate-100">
                       <thead className="bg-white sticky top-0 z-[100] shadow-sm">
                          <tr>
                            <th className="px-10 py-5 text-left"><TableDropdownFilter field="id" label="出库单号" /></th>
                            <th className="px-10 py-5 text-left text-[11px] font-black text-slate-400 uppercase tracking-widest">业务日期</th>
                            {!selectedCustomer && <th className="px-10 py-5 text-left"><TableDropdownFilter field="customer" label="客户" /></th>}
                            <th className="px-10 py-5 text-left"><TableDropdownFilter field="itemName" label="物料品类" /></th>
                            <th className="px-10 py-5 text-right text-[11px] font-black text-slate-400 uppercase tracking-widest">单据总额</th>
                            <th className="px-10 py-5 text-right text-[11px] font-black text-slate-400 uppercase tracking-widest">待结金额</th>
                            <th className="px-10 py-5 text-left text-[11px] font-black text-slate-400 uppercase tracking-widest">风险审计状态</th>
                          </tr>
                       </thead>
                       <tbody className="bg-white divide-y divide-slate-50 text-[13px]">
                          {drillDownAnalysis.tableRecords.map((r, i) => {
                            const today = new Date(); today.setHours(0, 0, 0, 0);
                            const dueDate = new Date(r.dueDate);
                            const diffDays = Math.ceil((dueDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));

                            let colorClass = "text-emerald-600";
                            let statusText = "已结清";
                            let dotColor = "bg-emerald-500";

                            if ((r.unsettledAmount || 0) > 0) {
                              if (diffDays < 0) {
                                colorClass = "text-rose-600 font-black";
                                statusText = `逾期 ${Math.abs(diffDays)} 天`;
                                dotColor = "bg-rose-500 animate-pulse";
                              } else if (diffDays <= 7) {
                                colorClass = "text-amber-600 font-black";
                                statusText = `临期 ${diffDays} 天`;
                                dotColor = "bg-amber-400";
                              } else {
                                colorClass = "text-emerald-700 font-bold";
                                statusText = `安全 (剩 ${diffDays} 天)`;
                                dotColor = "bg-emerald-500";
                              }
                            }

                            return (
                              <tr key={`${r.id}-${i}`} className="hover:bg-slate-50/80 transition-colors group">
                                 <td className="px-10 py-5 whitespace-nowrap font-mono font-black text-indigo-600"><button onClick={() => onSelectOrderId(r.id)} className="hover:underline">{r.id}</button></td>
                                 <td className="px-10 py-5 whitespace-nowrap font-bold text-slate-500 tracking-tight">{r.date}</td>
                                 {!selectedCustomer && <td className="px-10 py-5 whitespace-nowrap font-black text-slate-900 truncate max-w-[200px]">{r.customer}</td>}
                                 <td className="px-10 py-5 whitespace-nowrap font-black text-slate-700 truncate max-w-[220px]">{r.itemName}</td>
                                 <td className="px-10 py-5 whitespace-nowrap text-right font-mono font-bold text-slate-400 tabular-nums">{(r.totalAmount || 0).toLocaleString()}</td>
                                 <td className={`px-10 py-5 whitespace-nowrap text-right font-mono font-black tabular-nums ${(r.unsettledAmount || 0) > 0 ? 'text-rose-600' : 'text-slate-300'}`}>{(r.unsettledAmount || 0).toLocaleString()}</td>
                                 <td className={`px-10 py-5 whitespace-nowrap ${colorClass}`}>
                                    <div className="flex items-center gap-3">
                                       <div className={`w-2.5 h-2.5 rounded-full ${dotColor} shadow-sm`}></div>
                                       <div className="flex flex-col leading-tight">
                                          <span className="font-black text-[12px]">{statusText}</span>
                                          <span className="text-[10px] opacity-60 font-bold">账期截止: {r.dueDate}</span>
                                       </div>
                                    </div>
                                 </td>
                              </tr>
                            );
                          })}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

export interface SalesRecord {
  id: string; // 出库单号
  month: string; // 月份
