    const monthlyTrend = Array.from(new Set<string>(baseRecords.map(r => r.month))).sort().map(m => { const v = monthlyMap.get(m) || { sales: 0, qty: 0 }; return { name: m, sales: v.sales, qty: v.qty }; });
    let finalRecords = baseRecords;
