erRadius={120} outerRadius={180} paddingAngle={3} dataKey={itemPieMetric === 'sales' ? 'sales' : 'quantity'} stroke="#fff" strokeWidth={6} label={renderCustomizedLabel} labelLine={false} onClick={(d) => openItemDrillDown(d.name)}>{sortedItemSummary.slice(0, 15).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} className="cursor-pointer hover:opacity-85 transition-opacity" />)}</Pie><Tooltip /></PieChart></ResponsiveContainer></div></div></div>}</section>

