      {/* 原有的深度下钻面板：逻辑分叉保护 */}
      {(selectedCategory || selectedItem || selectedCustomer) && (
        <div className="fixed inset-0 bg-white z-[5000] flex flex-col animate-in slide-in-from-bottom-12 duration-500 overflow-hidden text-left"><div className="px-12 py-8 border-b border-slate-200 bg-white flex items-center justify-between shadow-sm z-50 border-t-[12px] border-t-indigo-600"><div><h3 className="text-3xl font-black text-slate-900 tracking-tight">{selectedCategory || selectedItem || selectedCustomer} <span className="mx-4 text-slate-200 font-light">|</span> <span className="text-indigo-600">业务深度穿透分析</span></h3><p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mt-2">实时关联交易数据监测系统</p></div><button onClick={() => { setSelectedCategory(null); setSelectedItem(null); setSelectedCustomer(null); setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] }); setLocalTableFilters({ month: '', customer: '', category: '' }); }} className="px-14 py-4 bg-slate-900 text-white rounded-[24px] text-sm font-black hover:bg-slate-800 transition-all shadow-xl">关闭面板</button></div><div className="flex-1 overflow-y-auto custom-scrollbar p-12 bg-slate-50/50 space-y-12"><div className="grid grid-cols-1 md:grid-cols-3 gap-8"><div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm"><p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-2">累计成交额</p><p className="text-3xl font-black text-indigo-600">{drillDownAnalysis.tableTotalSales.toLocaleString()} CFA</p></div><div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm"><p className="text-[11px] font-black text-emerald-500 uppercase tracking-widest mb-2">累计单据数</p><p className="text-3xl font-black text-emerald-600">{drillDownAnalysis.tableRecords.length}</p></div><div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm"><p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-2">成交物料总量</p><p className="text-3xl font-black text-slate-900">{drillDownAnalysis.tableTotalQty.toLocaleString()} UNIT</p></div></div><div className="bg-white rounded-[44px] border border-slate-200 shadow-2xl overflow-hidden mb-12"><div className="px-10 py-6 border-b border-slate-100 bg-slate-50 flex items-center justify-between"><span className="text-[11px] font-black uppercase tracking-widest text-slate-500">穿透业务清单</span></div><div className="overflow-x-auto max-h-[700px] custom-scrollbar"><table className="min-w-full divide-y divide-slate-100 text-[13px] text-left"><thead className="bg-white sticky top-0 z-[100] shadow-sm"><tr><th className="px-10 py-5">单号</th><th className="px-10 py-5">业务日期</th>{!selectedCustomer && <th className="px-10 py-5">客户</th>}<th className="px-10 py-5">物料名称</th><th className="px-10 py-5 text-right">成交额</th></tr></thead><tbody className="bg-white divide-y divide-slate-50">{drillDownAnalysis.tableRecords.map((r, i) => (<tr key={`${r.id}-${i}`} className="hover:bg-slate-50 transition-colors"><td className="px-10 py-5 font-mono font-black text-indigo-600">{r.id}</td><td className="px-10 py-5 font-bold text-slate-500">{r.date}</td>{!selectedCustomer && <td className="px-10 py-5 font-black text-slate-900">{r.customer}</td>}<td className="px-10 py-5 font-black text-slate-700 truncate max-w-[200px]">{r.itemName}</td><td className="px-10 py-5 text-right font-mono font-black">{(r.totalAmount ?? 0).toLocaleString()}</td></tr>))}</tbody></table></div></div></div></div>
