                 <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm"><p className="text-[11px] font-black text-rose-500 uppercase tracking-widest mb-2">未清偿单据数</p><p className="text-3xl font-black text-slate-900">{debtAuditAnalysis.records.length} <span className="text-xs">Orders</span></p></div>
