                    <div className="flex items-center gap-3"><div className="w-4 h-4 rounded-full bg-amber-400"></div><span className="text-xs font-black text-slate-500 uppercase tracking-widest">黄色: 7天内临期</span></div>
                    <div className="flex items-center gap-3"><div className="w-4 h-4 rounded-full bg-emerald-500"></div><span className="text-xs font-black text-slate-500 uppercase tracking-widest">绿色: 安全账期</span></div>
                 </div>
              </div>
              <div className="bg-white rounded-[44px] border border-slate-200 shadow-2xl overflow-hidden mb-12">
                 <div className="px-10 py-6 bg-slate-50 border-b border-slate-100"><span className="text-[11px] font-black uppercase tracking-widest text-slate-500">欠款审计清单</span></div>
                 <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-slate-100">
                       <thead className="bg-white sticky top-0 z-10 shadow-sm"><tr><th className="px-10 py-5 text-left text-[11px] font-black text-slate-400 uppercase">单号</th><th className="px-10 py-5 text-left text-[11px] font-black text-slate-400 uppercase">账期截止日</th><th className="px-10 py-5 text-left text-[11px] font-black text-slate-400 uppercase">物料明细</th><th className="px-10 py-5 text-right text-[11px] font-black text-slate-400 uppercase">待结余额</th><th className="px-10 py-5 text-left text-[11px] font-black text-slate-400 uppercase">风险预警</th></tr></thead>
                       <tbody className="bg-white divide-y divide-slate-50">
                          {debtAuditAnalysis.records.map((r, i) => {
                            const today = new Date(); today.setHours(0, 0, 0, 0);
                            const dueDate = new Date(r.dueDate);
                            const diffDays = Math.ceil((dueDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
                            let colorClass = "text-emerald-600"; let statusText = "安全"; let dotColor = "bg-emerald-500";
                            if (diffDays < 0) { colorClass = "text-rose-600 font-black"; statusText = `逾期 ${Math.abs(diffDays)} 天`; dotColor = "bg-rose-500 animate-pulse"; }
                            else if (diffDays <= 7) { colorClass = "text-amber-600 font-black"; statusText = `临期 ${diffDays} 天`; dotColor = "bg-amber-400"; }
                            return (<tr key={`${r.id}-${i}`} className="hover:bg-slate-50"><td className="px-10 py-5 font-mono font-black text-indigo-600">{r.id}</td><td className="px-10 py-5 font-bold text-slate-500">{r.dueDate}</td><td className="px-10 py-5 font-black text-slate-700 truncate max-w-[200px]">{r.itemName}</td><td className="px-10 py-5 text-right font-mono font-black text-rose-600">{(r.unsettledAmount ?? 0).toLocaleString()}</td><td className={`px-10 py-5 ${colorClass}`}><div className="flex items-center gap-3"><div className={`w-3 h-3 rounded-full ${dotColor}`}></div><span className="font-black text-xs">{statusText}</span></div></td></tr>);
                          })}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
