  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');
  const [activeMetrics, setActiveMetrics] = useState({ amount: true, quantity: true });
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<string | null>(null);
  const [drillMetric, setDrillMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [localTableFilters, setLocalTableFilters] = useState({ customer: '', category: '', month: '' });
  const [columnFilters, setColumnFilters] = useState<Record<string, string[]>>({ id: [], customer: [], salesperson: [], itemName: [] });
  const [activeFilterMenu, setActiveFilterMenu] = useState<string | null>(null);
  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  // --- 状态管理：新增审计模块专用 ---
  const [selectedDebtCustomer, setSelectedDebtCustomer] = useState<string | null>(null);

  const toggleSection = (key: keyof typeof sections) => {
    setSections(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- Fix: Define missing drill-down handler functions ---
  const openCategoryDrillDown = (name: string) => {
    setSelectedCategory(name);
    setSelectedItem(null);
    setSelectedCustomer(null);
  };

  const openItemDrillDown = (name: string) => {
    setSelectedCategory(null);
    setSelectedItem(name);
    setSelectedCustomer(null);
  };

  const openCustomerDrillDown = (name: string) => {
    setSelectedCategory(null);
    setSelectedItem(null);
    setSelectedCustomer(name);
  };

  // --- 原有计算逻辑：严禁改动 ---
  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : (selectedCustomer ? 'customer' : null));
    const value = selectedCategory || selectedItem || selectedCustomer;
    if (!dimension || !value) return { baseRecords: [], tableRecords: [], secondaryDistribution: [], monthlyTrend: [], tableTotalSales: 0, tableTotalQty: 0, filterOptions: { id: [], customer: [], salesperson: [], itemName: [] }, contextTitle: '' };
    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);
    const recordsForDist = localTableFilters.month ? baseRecords.filter(r => r.month === localTableFilters.month) : baseRecords;
    const secondaryDim = selectedCustomer ? 'category' : 'customer';
    const distMap = new Map<string, { sales: number; qty: number }>();
    recordsForDist.forEach(r => { const key = r[secondaryDim] as string; const e = distMap.get(key) || { sales: 0, qty: 0 }; distMap.set(key, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity }); });
    const secondaryDistribution = Array.from(distMap.entries()).map(([name, v]) => ({ name, sales: v.sales, qty: v.qty })).sort((a, b) => drillMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);
    let recordsForTrend = baseRecords;
    if (localTableFilters.customer && !selectedCustomer) recordsForTrend = recordsForTrend.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.category && selectedCustomer) recordsForTrend = recordsForTrend.filter(r => r.category === localTableFilters.category);
    const monthlyMap = new Map<string, { sales: number; qty: number }>();
    recordsForTrend.forEach(r => { const e = monthlyMap.get(r.month) || { sales: 0, qty: 0 }; monthlyMap.set(r.month, { sales: e.sales + r.totalAmount, qty: e.qty + r.quantity }); });
    const monthlyTrend = Array.from(new Set<string>(baseRecords.map(r => r.month))).sort().map(m => { const v = monthlyMap.get(m) || { sales: 0, qty: 0 }; return { name: m, sales: v.sales, qty: v.qty }; });
    let finalRecords = baseRecords;
    if (localTableFilters.month) finalRecords = finalRecords.filter(r => r.month === localTableFilters.month);
    if (localTableFilters.customer && !selectedCustomer) finalRecords = finalRecords.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.category && selectedCustomer) finalRecords = finalRecords.filter(r => r.category === localTableFilters.category);
    Object.entries(columnFilters).forEach(([field, selectedValues]) => { const castedValues = selectedValues as string[]; if (castedValues.length > 0) finalRecords = finalRecords.filter(r => castedValues.includes(String(r[field as keyof SalesRecord]))); });
    return { baseRecords, tableRecords: finalRecords.sort((a, b) => b.date.localeCompare(a.date)), secondaryDistribution, monthlyTrend, tableTotalSales: finalRecords.reduce((acc, cur) => acc + (cur.totalAmount ?? 0), 0), tableTotalQty: finalRecords.reduce((acc, cur) => acc + (cur.quantity ?? 0), 0), filterOptions: { id: Array.from(new Set(baseRecords.map(r => r.id))).sort(), customer: Array.from(new Set(baseRecords.map(r => r.customer))).sort(), salesperson: Array.from(new Set(baseRecords.map(r => r.salesperson))).sort(), itemName: Array.from(new Set(baseRecords.map(r => r.itemName))).sort() }, contextTitle: selectedCustomer ? '品类贡献偏好' : '关联客户贡献排行' };
  }, [selectedCategory, selectedItem, selectedCustomer, filteredData, localTableFilters, columnFilters, drillMetric]);

  // --- 新增计算逻辑：应收账款审计模块专用 (解耦) ---
  const receivablesAnalysis = useMemo(() => {
    const today = new Date(); today.setHours(0, 0, 0, 0);
    let totalSettled = 0; let totalUnsettled = 0;
    const agingBuckets = [
      { name: '未到期', value: 0, color: '#10b981' },
      { name: '逾期1-30天', value: 0, color: '#f59e0b' },
      { name: '逾期31-60天', value: 0, color: '#f97316' },
      { name: '逾期60天+', value: 0, color: '#ef4444' }
    ];
    const customerDebtsMap = new Map<string, { settled: number; unsettled: number }>();
    filteredData.forEach(r => {
      totalSettled += (r.settledAmount ?? 0);
      totalUnsettled += (r.unsettledAmount ?? 0);
      const curDebt = customerDebtsMap.get(r.customer) || { settled: 0, unsettled: 0 };
      customerDebtsMap.set(r.customer, { settled: curDebt.settled + (r.settledAmount ?? 0), unsettled: curDebt.unsettled + (r.unsettledAmount ?? 0) });
      if ((r.unsettledAmount ?? 0) > 0 && r.dueDate) {
        const dueDate = new Date(r.dueDate);
        const diffDays = Math.ceil((today.getTime() - dueDate.getTime()) / (1000 * 60 * 60 * 24));
        if (diffDays <= 0) agingBuckets[0].value += (r.unsettledAmount ?? 0);
        else if (diffDays <= 30) agingBuckets[1].value += (r.unsettledAmount ?? 0);
        else if (diffDays <= 60) agingBuckets[2].value += (r.unsettledAmount ?? 0);
        else agingBuckets[3].value += (r.unsettledAmount ?? 0);
      }
    });
    const debtors = Array.from(customerDebtsMap.entries())
      .map(([name, val]) => ({ name, settled: val.settled, unsettled: val.unsettled, total: val.settled + val.unsettled }))
      .filter(d => d.unsettled > 0)
      .sort((a, b) => b.unsettled - a.unsettled);
    return { totalSettled, totalUnsettled, agingBuckets, debtors, composition: [{ name: '已结算', value: totalSettled, color: '#10b981' }, { name: '待回款', value: totalUnsettled, color: '#fb7185' }] };
  }, [filteredData]);

  const debtAuditAnalysis = useMemo(() => {
    if (!selectedDebtCustomer) return { records: [], totalUnsettled: 0 };
    const records = filteredData.filter(r => r.customer === selectedDebtCustomer && (r.unsettledAmount ?? 0) > 0);
    return { records: records.sort((a, b) => a.dueDate.localeCompare(b.dueDate)), totalUnsettled: records.reduce((s, r) => s + (r.unsettledAmount ?? 0), 0) };
  }, [selectedDebtCustomer, filteredData]);

  // --- 原有辅助渲染函数 ---
  const formatMetricDisplay = (value: number, metric: 'sales' | 'quantity') => { if (metric === 'sales') return `${((value ?? 0) / 1000000).toFixed(2)}M CFA`; return `${(value ?? 0).toLocaleString()} UNIT`; };
  const renderCustomizedLabel = (props: any) => { const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props; const RADIAN = Math.PI / 180; const cos = Math.cos(-RADIAN * midAngle); const sin = Math.sin(-RADIAN * midAngle); const ex = cx + (outerRadius + 45) * cos; const ey = cy + (outerRadius + 45) * sin; return (<g><path d={`M${cx + (outerRadius + 10) * cos},${cy + (outerRadius + 10) * sin}L${cx + (outerRadius + 45) * cos},${cy + (outerRadius + 45) * sin}L${ex + (cos >= 0 ? 1 : -1) * 22},${ey}`} stroke={fill} fill="none" strokeWidth={2.5} opacity={0.7} /><circle cx={ex + (cos >= 0 ? 1 : -1) * 22} cy={ey} r={4} fill={fill} /><text x={ex + (cos >= 0 ? 1 : -1) * 35} y={ey} textAnchor={cos >= 0 ? 'start' : 'end'} fill="#0f172a" style={{ fontSize: '14px', fontWeight: 900 }}>{name}</text><text x={ex + (cos >= 0 ? 1 : -1) * 35} y={ey} dy={18} textAnchor={cos >= 0 ? 'start' : 'end'} fill="#64748b" style={{ fontSize: '12px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text></g>); };

  // --- 原有模块渲染片段：趋势、构成、排行 (保持原样) ---
  const trendAnalysis = useMemo(() => { const months = Array.from(new Set<string>(filteredData.map(d => d.month))).sort(); if (trendMode === 'total') { const data = months.map(month => { const monthRecords = filteredData.filter(d => d.month === month); return { name: month, amount: monthRecords.reduce((s, r) => s + (r.totalAmount ?? 0), 0), quantity: monthRecords.reduce((s, r) => s + (r.quantity ?? 0), 0) }; }); const series: any[] = []; if (activeMetrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' }); if (activeMetrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' }); return { data, series }; } const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson'; const topEntities = Array.from(new Set<string>(filteredData.map(d => String(d[dimKey])))).slice(0, 8); const series: any[] = []; topEntities.forEach((entity, idx) => { const baseColor = COLORS[idx % COLORS.length]; if (activeMetrics.amount) series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor }); if (activeMetrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true }); }); const data = months.map(month => { const row: any = { name: month }; topEntities.forEach(entity => { const records = filteredData.filter(d => d.month === month && d[dimKey] === entity); row[`${entity}_amt`] = records.reduce((s, r) => s + (r.totalAmount ?? 0), 0); row[`${entity}_qty`] = records.reduce((s, r) => s + (r.quantity ?? 0), 0); }); return row; }); return { data, series }; }, [filteredData, trendMode, activeMetrics]);
  const sortedCategorySummary = useMemo(() => { const merged = summary.categoryDistribution.map(cat => { const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name); return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 }; }); return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity); }, [summary, pieMetric]);
  const sortedItemSummary = useMemo(() => { const map = new Map<string, { sales: number; quantity: number }>(); filteredData.forEach(d => { const entry = map.get(d.itemName) || { sales: 0, quantity: 0 }; entry.sales += (d.totalAmount ?? 0); entry.quantity += (d.quantity ?? 0); map.set(d.itemName, entry); }); return Array.from(map.entries()).map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity })).sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity); }, [filteredData, itemPieMetric]);
  const customerAnalysisData = useMemo(() => { const map = new Map<string, { sales: number; quantity: number }>(); filteredData.forEach(d => { const entry = map.get(d.customer) || { sales: 0, quantity: 0 }; entry.sales += (d.totalAmount ?? 0); entry.quantity += (d.quantity ?? 0); map.set(d.customer, entry); }); return Array.from(map.entries()).map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity })).sort((a, b) => customerMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity); }, [filteredData, customerMetric]);

  return (
    <div className="space-y-10 pb-16 relative">
      {/* 顶部总计卡片：恢复原样并增加金额保护 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-start">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]"><div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div><div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{(summary.totalSales ?? 0).toLocaleString()}</p></div></div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]"><div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div><div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">出库总量</p><p className="text-2xl font-black text-slate-900">{(summary.totalQuantity ?? 0).toLocaleString()}</p></div></div>
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col overflow-hidden h-[100px]"><div className="p-6 flex items-center justify-between"><div className="flex items-center gap-6"><div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div><div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">单据总数</p><p className="text-2xl font-black text-slate-900">{(summary.orderCount ?? 0)}</p></div></div><button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2 bg-slate-100 rounded-xl hover:bg-slate-200"><svg className={`w-5 h-5 transition-transform ${isOrdersExpanded ? 'rotate-180 text-indigo-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button></div>{isOrdersExpanded && <div className="absolute top-[100px] left-0 right-0 z-50 p-5 bg-white border border-slate-200 shadow-2xl rounded-b-2xl animate-in fade-in slide-in-from-top-2 duration-300"><input type="text" placeholder="检索单号..." value={orderSearchTerm} onChange={(e) => setOrderSearchTerm(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-xs outline-none focus:border-indigo-500 font-bold mb-4" /><div className="max-h-40 overflow-y-auto flex flex-wrap gap-2 custom-scrollbar">{summary.orderIds.filter(id => id.toLowerCase().includes(orderSearchTerm.toLowerCase())).map(id => (<button key={id} onClick={() => onSelectOrderId(id)} className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-[10px] font-mono font-bold hover:border-indigo-500 transition-colors">{id}</button>))}</div></div>}</div>
      </div>

      {/* 原有模块：增长趋势 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden text-left"><div onClick={() => toggleSection('trend')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors"><h3 className="text-xl font-black text-slate-900 flex items-center gap-3 shrink-0"><span className="p-2 bg-indigo-50 text-indigo-600 rounded-xl text-lg">📈</span> 业绩增长趋势</h3><button className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${sections.trend ? 'rotate-180 text-indigo-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button></div>{sections.trend && <div className="px-8 pb-8 animate-in fade-in duration-500"><div className="h-[450px] w-full"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trendAnalysis.data}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" /><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11}} />{activeMetrics.amount && <YAxis yAxisId="amount" axisLine={false} tickLine={false} tick={{fill: '#6366f1', fontSize: 10, fontWeight: 700}} tickFormatter={(v) => `${(v / 1000000).toFixed(1)}M`} />}{activeMetrics.quantity && <YAxis yAxisId="quantity" orientation="right" axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 10, fontWeight: 700}} tickFormatter={(v) => (v ?? 0).toLocaleString()} />}<Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }} formatter={(value: any) => [(value ?? 0).toLocaleString(), '数值']} /><Legend iconType="circle" />{trendAnalysis.series.map((s, i) => (<Area key={s.key} yAxisId={s.type} type="monotone" dataKey={s.key} name={s.name} stroke={s.color} strokeWidth={s.dashed ? 2 : 3} strokeDasharray={s.dashed ? "5 5" : "0"} fill={s.color} fillOpacity={s.dashed ? 0 : 0.08} activeDot={{ r: 6, strokeWidth: 0 }} />))}</AreaChart></ResponsiveContainer></div></div>}</section>

      {/* 原有模块：业务构成 (双扇形图) */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden text-left"><div onClick={() => toggleSection('composition')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors"><h3 className="text-xl font-black text-slate-900 flex items-center gap-3 shrink-0"><span className="p-2 bg-emerald-50 text-emerald-600 rounded-xl text-lg">🧩</span> 业务构成分析</h3><button className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${sections.composition ? 'rotate-180 text-emerald-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button></div>{sections.composition && <div className="px-8 pb-10 animate-in fade-in duration-500 space-y-32"><div className="flex flex-col w-full bg-slate-50/30 p-8 rounded-[40px] border border-slate-100 shadow-inner"><h4 className="text-lg font-black text-slate-800 mb-8">品类核心构成</h4><div className="h-[550px] w-full relative"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={sortedCategorySummary} cx="50%" cy="50%" innerRadius={120} outerRadius={180} paddingAngle={5} dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} stroke="#fff" strokeWidth={6} label={renderCustomizedLabel} labelLine={false} onClick={(d) => openCategoryDrillDown(d.name)}>{sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} className="cursor-pointer hover:opacity-85 transition-opacity" />)}</Pie><Tooltip /></PieChart></ResponsiveContainer></div></div><div className="flex flex-col w-full bg-slate-50/30 p-8 rounded-[40px] border border-slate-100 shadow-inner"><h4 className="text-lg font-black text-slate-800 mb-8">物料贡献排行 (TOP 15)</h4><div className="h-[550px] w-full relative"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={sortedItemSummary.slice(0, 15)} cx="50%" cy="50%" innerRadius={120} outerRadius={180} paddingAngle={3} dataKey={itemPieMetric === 'sales' ? 'sales' : 'quantity'} stroke="#fff" strokeWidth={6} label={renderCustomizedLabel} labelLine={false} onClick={(d) => openItemDrillDown(d.name)}>{sortedItemSummary.slice(0, 15).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} className="cursor-pointer hover:opacity-85 transition-opacity" />)}</Pie><Tooltip /></PieChart></ResponsiveContainer></div></div></div>}</section>

      {/* 原有模块：客户排行 (带原销售穿透) */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden text-left"><div onClick={() => toggleSection('ranking')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors"><h3 className="text-xl font-black text-slate-900 flex items-center gap-3 shrink-0"><span className="p-2 bg-amber-50 text-amber-600 rounded-xl text-lg">👥</span> 客户采购排行</h3><button className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${sections.ranking ? 'rotate-180 text-amber-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button></div>{sections.ranking && <div className="px-8 pb-10 animate-in fade-in duration-500"><div className="w-full" style={{ height: `${Math.max(400, customerAnalysisData.length * 48)}px` }}><ResponsiveContainer width="100%" height="100%"><BarChart data={customerAnalysisData} layout="vertical" margin={{ left: 20, right: 120 }}><CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#e2e8f0" /><XAxis type="number" hide /><YAxis type="category" dataKey="name" width={150} axisLine={false} tickLine={false} tick={(props) => (<text {...props} className="fill-slate-600 font-black text-[12px] hover:fill-indigo-600 hover:underline cursor-pointer transition-colors" onClick={() => openCustomerDrillDown(props.payload.value)}>{props.payload.value}</text>)} /><Tooltip cursor={{ fill: '#f1f5f9', opacity: 0.5 }} /><Bar dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} radius={[0, 10, 10, 0]} barSize={30} onClick={(d) => openCustomerDrillDown(d.name)}>{customerAnalysisData.map((_, index) => <RechartsCell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}<LabelList dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} position="right" formatter={(v: any) => customerMetric === 'sales' ? `${((v ?? 0) / 1000000).toFixed(2)}M` : (v ?? 0).toLocaleString()} style={{ fill: '#475569', fontSize: '11px', fontWeight: 900 }} /></Bar></BarChart></ResponsiveContainer></div></div>}</section>

      {/* 新增模块：应收账款审计 (解耦式开发) */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden text-left border-l-[10px] border-l-rose-500">
        <div onClick={() => toggleSection('receivables')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50 transition-colors">
          <div className="flex flex-col gap-1">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 shrink-0"><span className="p-2 bg-rose-50 text-rose-600 rounded-xl text-lg">📅</span> 应付未付情况审计</h3>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-12">分析当前筛选范围内所有客户的存续欠款</p>
          </div>
          <button className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${sections.receivables ? 'rotate-180 text-rose-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
        </div>
        {sections.receivables && (
          <div className="px-8 pb-12 animate-in fade-in duration-500 space-y-12">
             <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                <div className="bg-slate-50/50 p-10 rounded-[44px] border border-slate-100 flex items-center gap-12">
                   <div className="w-44 h-44 flex-shrink-0"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={receivablesAnalysis.composition} innerRadius={65} outerRadius={85} paddingAngle={12} dataKey="value" stroke="none">{receivablesAnalysis.composition.map((entry, i) => <RechartsCell key={i} fill={entry.color} />)}</Pie><Tooltip formatter={(v) => (v ?? 0).toLocaleString()} /></PieChart></ResponsiveContainer></div>
                   <div className="flex-1 space-y-6 text-left">
                      <div><h4 className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-1">已结清回款</h4><p className="text-3xl font-black text-emerald-600">{(receivablesAnalysis.totalSettled ?? 0).toLocaleString()} <span className="text-xs">CFA</span></p></div>
                      <div><h4 className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-1">待回款 (风险暴露)</h4><p className="text-3xl font-black text-rose-600">{(receivablesAnalysis.totalUnsettled ?? 0).toLocaleString()} <span className="text-xs">CFA</span></p></div>
                   </div>
                </div>
