  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);
  const [orderSearchTerm, setOrderSearchTerm] = useState('');

  // 新增独立状态：应收账款审计专用
  const [selectedDebtCustomer, setSelectedDebtCustomer] = useState<string | null>(null);

  const toggleSection = (key: keyof typeof sections) => {
    setSections(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- 原有计算逻辑：严禁改动 ---
  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : (selectedCustomer ? 'customer' : null));
    const value = selectedCategory || selectedItem || selectedCustomer;
    if (!dimension || !value) return { baseRecords: [], totalSales: 0, totalQty: 0, secondaryDistribution: [], monthlyTrend: [], filterOptions: { id: [], customer: [], salesperson: [], itemName: [] }, tableRecords: [], contextTitle: '', tableTotalSales: 0, tableTotalQty: 0 };
    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);
    const totalSales = baseRecords.reduce((s, r) => s + (r.totalAmount || 0), 0);
    const totalQty = baseRecords.reduce((s, r) => s + (r.quantity || 0), 0);
    const recordsForDist = localTableFilters.month ? baseRecords.filter(r => r.month === localTableFilters.month) : baseRecords;
    const secondaryDim = selectedCustomer ? 'category' : 'customer';
    const distMap = new Map<string, { sales: number; qty: number }>();
    recordsForDist.forEach(r => { const key = r[secondaryDim] as string; const e = distMap.get(key) || { sales: 0, qty: 0 }; distMap.set(key, { sales: e.sales + (r.totalAmount || 0), qty: e.qty + (r.quantity || 0) }); });
    const secondaryDistribution = Array.from(distMap.entries()).map(([name, v]) => ({ name, sales: v.sales, qty: v.qty })).sort((a, b) => drillMetric === 'sales' ? b.sales - a.sales : b.qty - a.qty);
    let recordsForTrend = baseRecords;
    if (localTableFilters.customer && !selectedCustomer) recordsForTrend = recordsForTrend.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.category && selectedCustomer) recordsForTrend = recordsForTrend.filter(r => r.category === localTableFilters.category);
    const monthlyMap = new Map<string, { sales: number; qty: number }>();
    recordsForTrend.forEach(r => { const e = monthlyMap.get(r.month) || { sales: 0, qty: 0 }; monthlyMap.set(r.month, { sales: e.sales + (r.totalAmount || 0), qty: e.qty + (r.quantity || 0) }); });
    const allMonths = Array.from(new Set<string>(baseRecords.map(r => r.month))).sort();
    const monthlyTrend = allMonths.map(m => { const v = monthlyMap.get(m) || { sales: 0, qty: 0 }; return { name: m, sales: v.sales, qty: v.qty }; });
    let finalRecords = baseRecords;
    if (localTableFilters.month) finalRecords = finalRecords.filter(r => r.month === localTableFilters.month);
    if (localTableFilters.customer && !selectedCustomer) finalRecords = finalRecords.filter(r => r.customer === localTableFilters.customer);
    if (localTableFilters.category && selectedCustomer) finalRecords = finalRecords.filter(r => r.category === localTableFilters.category);
    Object.entries(columnFilters).forEach(([field, selectedValues]) => { const castedValues = selectedValues as string[]; if (castedValues.length > 0) finalRecords = finalRecords.filter(r => castedValues.includes(String(r[field as keyof SalesRecord]))); });
    return { baseRecords, totalSales, totalQty, secondaryDistribution, monthlyTrend, filterOptions: { id: Array.from(new Set(baseRecords.map(r => r.id))).sort(), customer: Array.from(new Set(baseRecords.map(r => r.customer))).sort(), salesperson: Array.from(new Set(baseRecords.map(r => r.salesperson))).sort(), itemName: Array.from(new Set(baseRecords.map(r => r.itemName))).sort() }, tableRecords: finalRecords.sort((a, b) => b.date.localeCompare(a.date)), contextTitle: selectedCustomer ? '品类贡献偏好' : '关联客户贡献排行', tableTotalSales: finalRecords.reduce((acc, cur) => acc + (cur.totalAmount || 0), 0), tableTotalQty: finalRecords.reduce((acc, cur) => acc + (cur.quantity || 0), 0) };
  }, [selectedCategory, selectedItem, selectedCustomer, filteredData, localTableFilters, columnFilters, drillMetric]);

  // --- 新增计算逻辑：独立用于“应付未付”模块 ---
  const receivablesAnalysis = useMemo(() => {
    const today = new Date(); today.setHours(0, 0, 0, 0);
    let totalSettled = 0; let totalUnsettled = 0;
    const agingBuckets = [
      { name: '未到期', value: 0, color: '#10b981' },
      { name: '逾期1-30天', value: 0, color: '#f59e0b' },
      { name: '逾期31-60天', value: 0, color: '#f97316' },
      { name: '逾期60天+', value: 0, color: '#ef4444' }
    ];
    const customerDebtsMap = new Map<string, { settled: number; unsettled: number }>();
    filteredData.forEach(r => {
      totalSettled += (r.settledAmount ?? 0);
      totalUnsettled += (r.unsettledAmount ?? 0);
      const curDebt = customerDebtsMap.get(r.customer) || { settled: 0, unsettled: 0 };
      customerDebtsMap.set(r.customer, { settled: curDebt.settled + (r.settledAmount ?? 0), unsettled: curDebt.unsettled + (r.unsettledAmount ?? 0) });
      if ((r.unsettledAmount ?? 0) > 0 && r.dueDate) {
        const dueDate = new Date(r.dueDate);
        const diffDays = Math.ceil((today.getTime() - dueDate.getTime()) / (1000 * 60 * 60 * 24));
        if (diffDays <= 0) agingBuckets[0].value += (r.unsettledAmount ?? 0);
        else if (diffDays <= 30) agingBuckets[1].value += (r.unsettledAmount ?? 0);
        else if (diffDays <= 60) agingBuckets[2].value += (r.unsettledAmount ?? 0);
        else agingBuckets[3].value += (r.unsettledAmount ?? 0);
      }
    });
    const debtorsList = Array.from(customerDebtsMap.entries())
      .map(([name, val]) => ({ name, settled: val.settled, unsettled: val.unsettled, total: val.settled + val.unsettled }))
      .filter(d => d.unsettled > 0)
      .sort((a, b) => b.unsettled - a.unsettled);
    return { totalSettled, totalUnsettled, agingBuckets, debtorsList, composition: [{ name: '已结算', value: totalSettled, color: '#10b981' }, { name: '待回款', value: totalUnsettled, color: '#fb7185' }] };
  }, [filteredData]);

  const debtAuditDetails = useMemo(() => {
    if (!selectedDebtCustomer) return { records: [], total: 0 };
    const records = filteredData.filter(r => r.customer === selectedDebtCustomer && (r.unsettledAmount ?? 0) > 0);
    return { records: records.sort((a, b) => a.dueDate.localeCompare(b.dueDate)), total: records.reduce((s, r) => s + (r.unsettledAmount ?? 0), 0) };
  }, [selectedDebtCustomer, filteredData]);

  // 原有辅助函数
  const openCategoryDrillDown = (name: string) => { setDrillMetric(pieMetric); setSelectedCategory(name); setSelectedItem(null); setSelectedCustomer(null); setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] }); setLocalTableFilters({ customer: '', category: '', month: '' }); };
  const openItemDrillDown = (name: string) => { setDrillMetric(itemPieMetric); setSelectedItem(name); setSelectedCategory(null); setSelectedCustomer(null); setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] }); setLocalTableFilters({ customer: '', category: '', month: '' }); };
  const openCustomerDrillDown = (name: string) => { setDrillMetric(customerMetric); setSelectedCustomer(name); setSelectedCategory(null); setSelectedItem(null); setColumnFilters({ id: [], customer: [], salesperson: [], itemName: [] }); setLocalTableFilters({ customer: '', category: '', month: '' }); };
  const renderCustomizedLabel = (props: any) => { const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props; const RADIAN = Math.PI / 180; const sin = Math.sin(-RADIAN * midAngle); const cos = Math.cos(-RADIAN * midAngle); const sx = cx + (outerRadius + 10) * cos; const sy = cy + (outerRadius + 10) * sin; const mx = cx + (outerRadius + 45) * cos; const my = cy + (outerRadius + 45) * sin; const ex = mx + (cos >= 0 ? 1 : -1) * 22; const ey = my; const textAnchor = cos >= 0 ? 'start' : 'end'; return (<g><path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={2.5} opacity={0.7} /><circle cx={ex} cy={ey} r={4} fill={fill} /><text x={ex + (cos >= 0 ? 1 : -1) * 15} y={ey} textAnchor={textAnchor} fill="#0f172a" style={{ fontSize: '14px', fontWeight: 900 }}>{name}</text><text x={ex + (cos >= 0 ? 1 : -1) * 15} y={ey} dy={18} textAnchor={textAnchor} fill="#64748b" style={{ fontSize: '12px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text></g>); };

  // 渲染逻辑开始
  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set<string>(filteredData.map(d => d.month))).sort();
    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return { name: month, amount: monthRecords.reduce((s, r) => s + (r.totalAmount || 0), 0), quantity: monthRecords.reduce((s, r) => s + (r.quantity || 0), 0) };
      });
      const series: any[] = [];
      if (activeMetrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (activeMetrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }
    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const topEntities = Array.from(new Set<string>(filteredData.map(d => String(d[dimKey])))).slice(0, 8);
    const series: any[] = [];
    topEntities.forEach((entity, idx) => {
      const baseColor = COLORS[idx % COLORS.length];
      if (activeMetrics.amount) series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color: baseColor });
      if (activeMetrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color: baseColor, dashed: true });
    });
    const data = months.map(month => {
      const row: any = { name: month };
      topEntities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + (r.totalAmount || 0), 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + (r.quantity || 0), 0);
      });
      return row;
    });
    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  const customerAnalysisData = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.customer) || { sales: 0, quantity: 0 };
