            <div className="bg-slate-50/30 p-8 rounded-[40px] border border-slate-100 shadow-inner"><h4 className="text-lg font-black text-slate-800 mb-8">物料贡献排行 (TOP 15)</h4><div className="h-[550px] w-full"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={sortedItemSummary.slice(0, 15)} cx="50%" cy="50%" innerRadius={120} outerRadius={180} paddingAngle={3} dataKey={itemPieMetric === 'sales' ? 'sales' : 'quantity'} stroke="#fff" strokeWidth={6} label={renderCustomizedLabel} labelLine={false} onClick={(d) => openItemDrillDown(d.name)}>{sortedItemSummary.slice(0, 15).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} className="cursor-pointer hover:opacity-80 transition-opacity" />)}</Pie><Tooltip formatter={(v: any) => (v ?? 0).toLocaleString()} /></PieChart></ResponsiveContainer></div></div>
          </div>
