          <button className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${sections.ranking ? 'rotate-180 text-amber-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
        </div>
        {sections.ranking && (
          <div className="px-8 pb-10 animate-in fade-in">
            <div className="w-full" style={{ height: `${Math.max(400, customerAnalysisData.length * 48)}px` }}><ResponsiveContainer width="100%" height="100%"><BarChart data={customerAnalysisData} layout="vertical" margin={{ left: 20, right: 120 }}><CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#e2e8f0" /><XAxis type="number" hide /><YAxis type="category" dataKey="name" width={150} axisLine={false} tickLine={false} tick={(props) => (<text {...props} className="fill-slate-600 font-black text-[12px] hover:fill-indigo-600 hover:underline cursor-pointer" onClick={() => openCustomerDrillDown(props.payload.value)}>{props.payload.value}</text>)} /><Tooltip cursor={{ fill: '#f1f5f9', opacity: 0.5 }} /><Bar dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} radius={[0, 10, 10, 0]} barSize={30} onClick={(d) => openCustomerDrillDown(d.name)}>{customerAnalysisData.map((_, index) => <RechartsCell key={index} fill={COLORS[index % COLORS.length]} />)}<LabelList dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} position="right" formatter={(v: any) => customerMetric === 'sales' ? `${((v ?? 0) / 1000000).toFixed(2)}M` : (v ?? 0).toLocaleString()} style={{ fill: '#475569', fontSize: '11px', fontWeight: 900 }} /></Bar></BarChart></ResponsiveContainer></div>
