                   <div className="w-44 h-44 shrink-0"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={receivablesAnalysis.composition} innerRadius={65} outerRadius={85} paddingAngle={12} dataKey="value" stroke="none">{receivablesAnalysis.composition.map((entry, i) => <RechartsCell key={i} fill={entry.color} />)}</Pie><Tooltip formatter={(v: any) => (v ?? 0).toLocaleString()} /></PieChart></ResponsiveContainer></div>
