      totalSettled += (r.settledAmount ?? 0);
      totalUnsettled += (r.unsettledAmount ?? 0);
      const cur = debtorMap.get(r.customer) || { settled: 0, unsettled: 0 };
      debtorMap.set(r.customer, { settled: cur.settled + (r.settledAmount ?? 0), unsettled: cur.unsettled + (r.unsettledAmount ?? 0) });
      if ((r.unsettledAmount ?? 0) > 0 && r.dueDate) {
        const dueDate = new Date(r.dueDate);
        const diff = Math.ceil((today.getTime() - dueDate.getTime()) / (1000 * 60 * 60 * 24));
        if (diff <= 0) agingBuckets[0].value += (r.unsettledAmount ?? 0);
        else if (diff <= 30) agingBuckets[1].value += (r.unsettledAmount ?? 0);
        else agingBuckets[2].value += (r.unsettledAmount ?? 0);
      }
    });
    const debtorsList = Array.from(debtorMap.entries()).map(([name, val]) => ({ name, ...val, total: val.settled + val.unsettled })).filter(d => d.unsettled > 0).sort((a, b) => b.unsettled - a.unsettled);
    return { totalSettled, totalUnsettled, agingBuckets, debtorsList };
  }, [filteredData]);

  const debtAuditDetails = useMemo(() => {
    if (!selectedDebtCustomer) return { records: [], total: 0 };
    const records = filteredData.filter(r => r.customer === selectedDebtCustomer && (r.unsettledAmount ?? 0) > 0);
    return { records: records.sort((a, b) => a.dueDate.localeCompare(b.dueDate)), total: records.reduce((s, r) => s + (r.unsettledAmount ?? 0), 0) };
  }, [selectedDebtCustomer, filteredData]);

  // 原有渲染逻辑保持不变... (以下为 Dashboard 渲染部分，仅在末尾添加新模块)
  const openCategoryDrillDown = (name: string) => { setDrillMetric(pieMetric); setSelectedCategory(name); setSelectedItem(null); setSelectedCustomer(null); };
  const openItemDrillDown = (name: string) => { setDrillMetric(itemPieMetric); setSelectedItem(name); setSelectedCategory(null); setSelectedCustomer(null); };
  const openCustomerDrillDown = (name: string) => { setDrillMetric(customerMetric); setSelectedCustomer(name); setSelectedCategory(null); setSelectedItem(null); };

  const trendAnalysisData = useMemo(() => {
    const months = Array.from(new Set<string>(filteredData.map(d => d.month))).sort();
    return months.map(m => {
      const records = filteredData.filter(d => d.month === m);
      return { name: m, amount: records.reduce((s, r) => s + (r.totalAmount ?? 0), 0), quantity: records.reduce((s, r) => s + (r.quantity ?? 0), 0) };
    });
  }, [filteredData]);

  const customerRankingData = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const e = map.get(d.customer) || { sales: 0, quantity: 0 };
      map.set(d.customer, { sales: e.sales + (d.totalAmount ?? 0), quantity: e.quantity + (d.quantity ?? 0) });
    });
    return Array.from(map.entries()).map(([name, val]) => ({ name, ...val })).sort((a, b) => customerMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, customerMetric]);

  return (
    <div className="space-y-10 pb-16 relative">
      {/* 顶部指标卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
          <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
          <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{(summary.totalSales ?? 0).toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
          <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
          <div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">出库总量</p><p className="text-2xl font-black text-slate-900">{(summary.totalQuantity ?? 0).toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col h-[100px] overflow-hidden">
          <div className="p-6 flex items-center justify-between">
            <div className="flex items-center gap-6"><div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div><div><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">单据总数</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div></div>
            <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2 bg-slate-100 rounded-xl hover:bg-slate-200 transition-all"><svg className={`w-5 h-5 ${isOrdersExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
          </div>
          {isOrdersExpanded && <div className="absolute top-[100px] right-0 w-64 bg-white border border-slate-200 shadow-2xl p-4 rounded-b-xl z-[100] max-h-60 overflow-y-auto custom-scrollbar">
            {summary.orderIds.map(id => <button key={id} onClick={() => onSelectOrderId(id)} className="w-full text-left px-3 py-1.5 text-[10px] font-mono hover:bg-slate-50 border-b border-slate-50 last:border-none">{id}</button>)}
