        </div>
        {sections.trend && <div className="px-8 pb-8 h-[400px] animate-in fade-in"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trendAnalysisData}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" /><XAxis dataKey="name" axisLine={false} tick={{fontSize: 10}} /><YAxis axisLine={false} tick={{fontSize: 10}} tickFormatter={(v) => `${(v/1000000).toFixed(1)}M`} /><Tooltip /><Area type="monotone" dataKey="amount" stroke="#6366f1" strokeWidth={3} fill="#6366f1" fillOpacity={0.05} /></AreaChart></ResponsiveContainer></div>}
      </section>

      {/* 原有模块：业务构成分析 */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden text-left">
        <div onClick={() => toggleSection('composition')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50">
