      </section>

      {/* 新增独立模块：应付未付情况审计 (仅响应筛选中心数据) */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden text-left border-l-[12px] border-l-rose-500">
        <div onClick={() => toggleSection('receivables')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50">
          <div className="flex flex-col gap-1">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 shrink-0"><span className="p-2 bg-rose-50 text-rose-600 rounded-xl text-lg">📅</span> 应付未付情况审计</h3>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-12">分析当前筛选范围内的财务合规风险</p>
          </div>
          <button className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${sections.receivables ? 'rotate-180 text-rose-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
        </div>
        {sections.receivables && (
          <div className="px-8 pb-12 animate-in fade-in duration-500 space-y-12">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
              <div className="bg-slate-50 p-8 rounded-[40px] flex items-center gap-10 border border-slate-100">
                <div className="w-40 h-40 shrink-0"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={[{name:'已结', value: receivablesAnalysis.totalSettled}, {name:'未结', value: receivablesAnalysis.totalUnsettled}]} innerRadius={60} outerRadius={80} paddingAngle={10} dataKey="value" stroke="none"><RechartsCell fill="#10b981"/><RechartsCell fill="#fb7185"/></Pie></PieChart></ResponsiveContainer></div>
                <div className="space-y-4">
                  <div><p className="text-[10px] font-black text-slate-400 uppercase mb-1">已结清总额</p><p className="text-2xl font-black text-emerald-600">{(receivablesAnalysis.totalSettled ?? 0).toLocaleString()} CFA</p></div>
                  <div><p className="text-[10px] font-black text-slate-400 uppercase mb-1">待回款总额 (风险点)</p><p className="text-2xl font-black text-rose-600">{(receivablesAnalysis.totalUnsettled ?? 0).toLocaleString()} CFA</p></div>
                </div>
              </div>
              <div className="bg-slate-50 p-8 rounded-[40px] border border-slate-100 h-[260px]">
                <h4 className="text-[10px] font-black text-slate-400 uppercase mb-6 text-center tracking-widest">欠款账期风险分布</h4>
                <ResponsiveContainer width="100%" height="100%"><BarChart data={receivablesAnalysis.agingBuckets}><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 900}} /><Tooltip /><Bar dataKey="value" radius={[8, 8, 0, 0]} barSize={40}>{receivablesAnalysis.agingBuckets.map((e, i) => <RechartsCell key={i} fill={e.color}/>)}</Bar></BarChart></ResponsiveContainer>
              </div>
            </div>
            <div className="bg-white rounded-[40px] border border-slate-200 shadow-xl overflow-hidden">
              <div className="px-10 py-5 bg-slate-50 border-b border-slate-100"><span className="text-[11px] font-black text-slate-500 uppercase tracking-widest">欠款客户清单 (点击开启审计)</span></div>
              <div className="overflow-x-auto max-h-[400px] custom-scrollbar">
                <table className="min-w-full divide-y divide-slate-100">
                  <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm"><tr><th className="px-10 py-4 text-left text-[11px] font-black text-slate-400 uppercase">客户名称</th><th className="px-10 py-4 text-right text-[11px] font-black text-slate-400 uppercase">待结余额 (CFA)</th><th className="px-10 py-4 text-left text-[11px] font-black text-slate-400 uppercase pl-16">回款进度</th></tr></thead>
                  <tbody className="divide-y divide-slate-50">{receivablesAnalysis.debtorsList.map(d => { const ratio = (d.settled / (d.total || 1)) * 100; return (<tr key={d.name} className="hover:bg-slate-50 transition-colors cursor-pointer" onClick={() => setSelectedDebtCustomer(d.name)}><td className="px-10 py-4 text-sm font-black text-slate-900">{d.name}</td><td className="px-10 py-4 text-sm font-mono font-black text-rose-600 text-right">{(d.unsettled ?? 0).toLocaleString()}</td><td className="px-10 py-4 pl-16"><div className="flex items-center gap-4"><div className="flex-1 h-2 bg-slate-100 rounded-full overflow-hidden"><div className={`h-full ${ratio > 70 ? 'bg-emerald-500' : 'bg-rose-500'}`} style={{width: `${ratio}%`}}></div></div><span className="text-[10px] font-black text-slate-500">{ratio.toFixed(0)}%</span></div></td></tr>)})}</tbody>
                </table>
              </div>
            </div>
          </div>
        )}
      </section>

      {/* 原有的深度下钻面板 */}
      {(selectedCategory || selectedItem || selectedCustomer) && (
        <div className="fixed inset-0 bg-white z-[5000] flex flex-col animate-in slide-in-from-bottom-12 duration-500 overflow-hidden text-left border-t-[12px] border-indigo-600">
