        </div>
      )}

      {/* 新增独立审计面板：完全隔离 */}
      {selectedDebtCustomer && (
        <div className="fixed inset-0 bg-white z-[6000] flex flex-col animate-in slide-in-from-right duration-500 overflow-hidden text-left border-l-[16px] border-l-rose-600">
           <div className="px-12 py-10 border-b border-slate-200 bg-white flex items-center justify-between shadow-sm">
              <div className="flex items-center gap-6">
                <div className="w-20 h-20 bg-rose-600 rounded-3xl flex items-center justify-center text-white text-3xl shadow-2xl">🚨</div>
                <div>
                  <h3 className="text-4xl font-black text-slate-900 tracking-tight">{selectedDebtCustomer} <span className="mx-4 text-slate-200 font-light">|</span> <span className="text-rose-600">应收风险审计</span></h3>
                  <p className="text-[12px] font-black text-slate-400 uppercase tracking-[0.3em] mt-2">已启用全量未结清穿透 · 风险分级预警系统</p>
                </div>
              </div>
              <button onClick={() => setSelectedDebtCustomer(null)} className="px-16 py-5 bg-slate-900 text-white rounded-3xl text-sm font-black hover:bg-slate-800 transition-all shadow-2xl">退出审计</button>
           </div>
           <div className="flex-1 overflow-y-auto custom-scrollbar p-12 bg-slate-50/50 space-y-12">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                 <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm"><p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-2">待结余额 (风险敞口)</p><p className="text-3xl font-black text-rose-600">{(debtAuditDetails.total ?? 0).toLocaleString()} <span className="text-xs">CFA</span></p></div>
                 <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm"><p className="text-[11px] font-black text-rose-500 uppercase tracking-widest mb-2">未结清单据数</p><p className="text-3xl font-black text-slate-900">{debtAuditDetails.records.length} <span className="text-xs">Orders</span></p></div>
                 <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm col-span-2 flex items-center justify-around">
