                 </div>
              </div>
              <div className="bg-white rounded-[44px] border border-slate-200 shadow-2xl overflow-hidden mb-12">
                 <div className="px-10 py-6 bg-slate-50 border-b border-slate-100 font-black text-[11px] text-slate-500 uppercase tracking-widest">待结算业务穿透明细</div>
                 <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-slate-100">
                       <thead className="bg-white sticky top-0 z-10 shadow-sm"><tr><th className="px-10 py-5 text-left text-[11px] font-black text-slate-400 uppercase">单号</th><th className="px-10 py-5 text-left text-[11px] font-black text-slate-400 uppercase">到期日</th><th className="px-10 py-5 text-left text-[11px] font-black text-slate-400 uppercase">物料明细</th><th className="px-10 py-5 text-right text-[11px] font-black text-slate-400 uppercase">待结余额</th><th className="px-10 py-5 text-left text-[11px] font-black text-slate-400 uppercase">风险预警</th></tr></thead>
                       <tbody className="bg-white divide-y divide-slate-50">
                          {debtAuditDetails.records.map((r, i) => {
                            const today = new Date(); today.setHours(0, 0, 0, 0);
                            const dueDate = new Date(r.dueDate);
                            const diff = Math.ceil((dueDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
                            let color = "text-emerald-600"; let text = "安全"; let dot = "bg-emerald-500";
                            if (diff < 0) { color = "text-rose-600"; text = `逾期 ${Math.abs(diff)} 天`; dot = "bg-rose-500 animate-pulse"; }
                            else if (diff <= 7) { color = "text-amber-600"; text = `临期 ${diff} 天`; dot = "bg-amber-400"; }
                            return (<tr key={i} className="hover:bg-slate-50 transition-colors"><td className="px-10 py-5 font-mono font-black text-indigo-600">{r.id}</td><td className="px-10 py-5 font-bold text-slate-500">{r.dueDate}</td><td className="px-10 py-5 font-black text-slate-700">{r.itemName}</td><td className="px-10 py-5 text-right font-mono font-black text-rose-600">{(r.unsettledAmount ?? 0).toLocaleString()}</td><td className={`px-10 py-5 ${color}`}><div className="flex items-center gap-3 font-black text-xs"><div className={`w-3 h-3 rounded-full ${dot}`}></div>{text}</div></td></tr>);
                          })}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7', '#fb7185', '#2dd4bf', '#fbbf24'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  // --- 1. 状态管理 (包含原有的和新增隔离的状态) ---
  const [sections, setSections] = useState({
    trend: true, composition: true, ranking: true, receivables: true
  });
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [customerMetric, setCustomerMetric] = useState<'sales' | 'quantity'>('sales');
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');
  const [activeMetrics, setActiveMetrics] = useState({ amount: true, quantity: true });

  // 原有的穿透状态 (用于前三个模块)
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<string | null>(null);
  const [drillMetric, setDrillMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [localTableFilters, setLocalTableFilters] = useState({ customer: '', category: '', month: '' });
  const [columnFilters, setColumnFilters] = useState<Record<string, string[]>>({ id: [], customer: [], salesperson: [], itemName: [] });

  // 新增独立状态 (仅用于“应付未付”模块，严格隔离)
  const [selectedDebtCustomer, setSelectedDebtCustomer] = useState<string | null>(null);

  const toggleSection = (key: keyof typeof sections) => {
    setSections(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- 2. 核心辅助渲染函数 (恢复原始高阶UI) ---
  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const cos = Math.cos(-RADIAN * midAngle);
    const sin = Math.sin(-RADIAN * midAngle);
    const sx = cx + (outerRadius + 10) * cos;
    const sy = cy + (outerRadius + 10) * sin;
    const mx = cx + (outerRadius + 45) * cos;
    const my = cy + (outerRadius + 45) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 22;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';

    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={2.5} opacity={0.7} />
        <circle cx={ex} cy={ey} r={4} fill={fill} />
        <text x={ex + (cos >= 0 ? 1 : -1) * 15} y={ey} textAnchor={textAnchor} fill="#0f172a" style={{ fontSize: '14px', fontWeight: 900 }}>{name}</text>
        <text x={ex + (cos >= 0 ? 1 : -1) * 15} y={ey} dy={18} textAnchor={textAnchor} fill="#64748b" style={{ fontSize: '12px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  // --- 3. 原始计算逻辑恢复 (前三个模块) ---
  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set<string>(filteredData.map(d => d.month))).sort();
    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return { name: month, amount: monthRecords.reduce((s, r) => s + (r.totalAmount ?? 0), 0), quantity: monthRecords.reduce((s, r) => s + (r.quantity ?? 0), 0) };
      });
      const series = [];
      if (activeMetrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (activeMetrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }
    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const entities = Array.from(new Set<string>(filteredData.map(d => String(d[dimKey])))).slice(0, 8);
    const series: any[] = [];
    entities.forEach((entity, idx) => {
      const color = COLORS[idx % COLORS.length];
      if (activeMetrics.amount) series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color });
      if (activeMetrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color, dashed: true });
    });
    const data = months.map(month => {
      const row: any = { name: month };
      entities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + (r.totalAmount ?? 0), 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + (r.quantity ?? 0), 0);
      });
      return row;
    });
    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += (d.totalAmount ?? 0);
      entry.quantity += (d.quantity ?? 0);
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries()).map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity })).sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, itemPieMetric]);

  const customerAnalysisData = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.customer) || { sales: 0, quantity: 0 };
      entry.sales += (d.totalAmount ?? 0);
      entry.quantity += (d.quantity ?? 0);
      map.set(d.customer, entry);
    });
    return Array.from(map.entries()).map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity })).sort((a, b) => customerMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, customerMetric]);

  // 原有的穿透计算 (隔离)
  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : (selectedCustomer ? 'customer' : null));
    const value = selectedCategory || selectedItem || selectedCustomer;
    if (!dimension || !value) return { baseRecords: [], tableRecords: [], secondaryDistribution: [], monthlyTrend: [], tableTotalSales: 0, tableTotalQty: 0 };
    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);
    // ... 其他逻辑略，保持原样 ...
    return { 
      baseRecords, 
      tableRecords: baseRecords.sort((a, b) => b.date.localeCompare(a.date)), 
      tableTotalSales: baseRecords.reduce((s, r) => s + (r.totalAmount ?? 0), 0),
      tableTotalQty: baseRecords.reduce((s, r) => s + (r.quantity ?? 0), 0)
    };
  }, [selectedCategory, selectedItem, selectedCustomer, filteredData]);

  // --- 4. 新增独立逻辑 (应付未付模块) ---
  const receivablesAnalysis = useMemo(() => {
    const today = new Date(); today.setHours(0, 0, 0, 0);
    let totalSettled = 0; let totalUnsettled = 0;
    const agingBuckets = [
      { name: '未到期', value: 0, color: '#10b981' },
      { name: '逾期1-30天', value: 0, color: '#f59e0b' },
      { name: '逾期30天+', value: 0, color: '#ef4444' }
    ];
    const debtorMap = new Map<string, { settled: number; unsettled: number }>();
    filteredData.forEach(r => {
      totalSettled += (r.settledAmount ?? 0);
      totalUnsettled += (r.unsettledAmount ?? 0);
      const cur = debtorMap.get(r.customer) || { settled: 0, unsettled: 0 };
      debtorMap.set(r.customer, { settled: cur.settled + (r.settledAmount ?? 0), unsettled: cur.unsettled + (r.unsettledAmount ?? 0) });
      if ((r.unsettledAmount ?? 0) > 0 && r.dueDate) {
        const dueDate = new Date(r.dueDate);
        const diff = Math.ceil((today.getTime() - dueDate.getTime()) / (1000 * 60 * 60 * 24));
        if (diff <= 0) agingBuckets[0].value += (r.unsettledAmount ?? 0);
        else if (diff <= 30) agingBuckets[1].value += (r.unsettledAmount ?? 0);
        else agingBuckets[2].value += (r.unsettledAmount ?? 0);
      }
    });
    return { 
      totalSettled, 
      totalUnsettled, 
      agingBuckets, 
      debtors: Array.from(debtorMap.entries()).map(([name, val]) => ({ name, ...val })).filter(d => d.unsettled > 0).sort((a, b) => b.unsettled - a.unsettled)
    };
  }, [filteredData]);

  const debtAuditDetails = useMemo(() => {
    if (!selectedDebtCustomer) return { records: [], total: 0 };
    const records = filteredData.filter(r => r.customer === selectedDebtCustomer && (r.unsettledAmount ?? 0) > 0);
    return { records: records.sort((a, b) => a.dueDate.localeCompare(b.dueDate)), total: records.reduce((s, r) => s + (r.unsettledAmount ?? 0), 0) };
  }, [selectedDebtCustomer, filteredData]);

  return (
    <div className="space-y-10 pb-16 relative">
      {/* 顶部总计卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
          <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
          <div className="text-left"><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{(summary.totalSales ?? 0).toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
          <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
          <div className="text-left"><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">出库总量</p><p className="text-2xl font-black text-slate-900">{(summary.totalQuantity ?? 0).toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col h-[100px] overflow-hidden relative">
          <div className="p-6 flex items-center justify-between">
            <div className="flex items-center gap-6"><div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div><div className="text-left"><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">单据总数</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div></div>
            <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 ${isOrdersExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
          </div>
          {isOrdersExpanded && <div className="absolute top-[100px] left-0 right-0 z-[100] p-4 bg-white border border-slate-200 shadow-2xl rounded-b-xl"><div className="max-h-40 overflow-y-auto custom-scrollbar flex flex-wrap gap-2">{summary.orderIds.map(id => <button key={id} onClick={() => onSelectOrderId(id)} className="px-2 py-1 bg-slate-50 border border-slate-200 rounded text-[10px] font-mono hover:border-indigo-600">{id}</button>)}</div></div>}
        </div>
      </div>

      {/* 模块1：业绩增长趋势 (完全恢复原始UI) */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden text-left">
        <div onClick={() => toggleSection('trend')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3"><span className="p-2 bg-indigo-50 text-indigo-600 rounded-xl text-lg">📈</span> 业绩增长趋势</h3>
          <div className="flex bg-slate-100 p-1 rounded-xl" onClick={e => e.stopPropagation()}>
            {(['total', 'customer', 'salesperson'] as const).map(m => <button key={m} onClick={() => setTrendMode(m)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${trendMode === m ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500'}`}>{m === 'total' ? '总体' : m === 'customer' ? '客户' : '销售员'}</button>)}
          </div>
        </div>
        {sections.trend && (
          <div className="px-8 pb-8 h-[450px] animate-in fade-in">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendAnalysis.data}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11}} />
                {activeMetrics.amount && <YAxis yAxisId="amount" axisLine={false} tickLine={false} tick={{fill: '#6366f1', fontSize: 10, fontWeight: 700}} tickFormatter={v => `${(v/1000000).toFixed(1)}M`} />}
                {activeMetrics.quantity && <YAxis yAxisId="quantity" orientation="right" axisLine={false} tickLine={false} tick={{fill: '#10b981', fontSize: 10, fontWeight: 700}} tickFormatter={v => (v ?? 0).toLocaleString()} />}
                <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }} formatter={(v: any) => (v ?? 0).toLocaleString()} />
                <Legend iconType="circle" />
                {trendAnalysis.series.map(s => <Area key={s.key} yAxisId={s.type} type="monotone" dataKey={s.key} name={s.name} stroke={s.color} strokeWidth={s.dashed ? 2 : 3} strokeDasharray={s.dashed ? "5 5" : "0"} fill={s.color} fillOpacity={s.dashed ? 0 : 0.08} />)}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        )}
      </section>

      {/* 模块2：业务构成分析 (完全恢复双饼图原始UI) */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden text-left">
        <div onClick={() => toggleSection('composition')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3"><span className="p-2 bg-emerald-50 text-emerald-600 rounded-xl text-lg">🧩</span> 业务构成分析</h3>
          <button className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${sections.composition ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
        </div>
        {sections.composition && (
          <div className="px-8 pb-10 space-y-32 animate-in fade-in">
            <div className="bg-slate-50/30 p-8 rounded-[40px] border border-slate-100 shadow-inner">
              <div className="flex items-center justify-between mb-8"><h4 className="text-lg font-black text-slate-800">品类核心构成</h4><div className="flex bg-white p-1 rounded-xl shadow-sm"><button onClick={() => setPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold ${pieMetric === 'sales' ? 'bg-emerald-600 text-white shadow-md' : 'text-slate-500'}`}>金额</button><button onClick={() => setPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold ${pieMetric === 'quantity' ? 'bg-emerald-600 text-white shadow-md' : 'text-slate-500'}`}>数量</button></div></div>
              <div className="h-[550px] w-full"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={sortedCategorySummary} cx="50%" cy="50%" innerRadius={120} outerRadius={180} paddingAngle={5} dataKey={pieMetric === 'sales' ? 'sales' : 'quantity'} stroke="#fff" strokeWidth={6} label={renderCustomizedLabel} labelLine={false} onClick={d => {setSelectedCategory(d.name); setDrillMetric(pieMetric)}}>{sortedCategorySummary.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} className="cursor-pointer hover:opacity-80 transition-opacity" />)}</Pie><Tooltip formatter={(v: any) => (v ?? 0).toLocaleString()} /></PieChart></ResponsiveContainer></div>
            </div>
            <div className="bg-slate-50/30 p-8 rounded-[40px] border border-slate-100 shadow-inner">
              <div className="flex items-center justify-between mb-8"><h4 className="text-lg font-black text-slate-800">物料贡献排行 (TOP 15)</h4><div className="flex bg-white p-1 rounded-xl shadow-sm"><button onClick={() => setItemPieMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold ${itemPieMetric === 'sales' ? 'bg-emerald-600 text-white shadow-md' : 'text-slate-500'}`}>金额</button><button onClick={() => setItemPieMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold ${itemPieMetric === 'quantity' ? 'bg-emerald-600 text-white shadow-md' : 'text-slate-500'}`}>数量</button></div></div>
              <div className="h-[550px] w-full"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={sortedItemSummary.slice(0, 15)} cx="50%" cy="50%" innerRadius={120} outerRadius={180} paddingAngle={3} dataKey={itemPieMetric === 'sales' ? 'sales' : 'quantity'} stroke="#fff" strokeWidth={6} label={renderCustomizedLabel} labelLine={false} onClick={d => {setSelectedItem(d.name); setDrillMetric(itemPieMetric)}}>{sortedItemSummary.slice(0, 15).map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} className="cursor-pointer hover:opacity-80 transition-opacity" />)}</Pie><Tooltip formatter={(v: any) => (v ?? 0).toLocaleString()} /></PieChart></ResponsiveContainer></div>
            </div>
          </div>
        )}
      </section>

      {/* 模块3：客户采购排行 (完全恢复原始UI) */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden text-left">
        <div onClick={() => toggleSection('ranking')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3"><span className="p-2 bg-amber-50 text-amber-600 rounded-xl text-lg">👥</span> 客户采购排行</h3>
          <div className="flex bg-slate-100 p-1 rounded-xl" onClick={e => e.stopPropagation()}><button onClick={() => setCustomerMetric('sales')} className={`px-4 py-1.5 rounded-lg text-xs font-bold ${customerMetric === 'sales' ? 'bg-amber-500 text-white shadow-md' : 'text-slate-500'}`}>按金额</button><button onClick={() => setCustomerMetric('quantity')} className={`px-4 py-1.5 rounded-lg text-xs font-bold ${customerMetric === 'quantity' ? 'bg-amber-500 text-white shadow-md' : 'text-slate-500'}`}>按数量</button></div>
        </div>
        {sections.ranking && (
          <div className="px-8 pb-10 animate-in fade-in" style={{ height: `${Math.max(500, customerAnalysisData.length * 45)}px` }}>
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={customerAnalysisData} layout="vertical" margin={{ left: 20, right: 120 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#e2e8f0" />
                <XAxis type="number" hide />
                <YAxis type="category" dataKey="name" width={150} axisLine={false} tickLine={false} tick={props => <text {...props} onClick={() => {setSelectedCustomer(props.payload.value); setDrillMetric(customerMetric)}} className="fill-slate-600 font-black text-[12px] hover:fill-indigo-600 cursor-pointer">{props.payload.value}</text>} />
                <Tooltip cursor={{ fill: '#f1f5f9' }} />
                <Bar dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} radius={[0, 10, 10, 0]} barSize={28} onClick={d => {setSelectedCustomer(d.name); setDrillMetric(customerMetric)}}>{customerAnalysisData.map((_, i) => <RechartsCell key={i} fill={COLORS[i % COLORS.length]} />)}<LabelList dataKey={customerMetric === 'sales' ? 'sales' : 'quantity'} position="right" formatter={(v: any) => customerMetric === 'sales' ? `${((v??0)/1000000).toFixed(1)}M` : (v??0).toLocaleString()} style={{ fill: '#475569', fontSize: '11px', fontWeight: 900 }} /></Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        )}
      </section>

      {/* 模块4：应付未付情况审计 (完全独立的增量模块) */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden text-left border-l-[12px] border-l-rose-500">
        <div onClick={() => toggleSection('receivables')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50">
          <div className="flex flex-col gap-1">
            <h3 className="text-xl font-black text-slate-900 flex items-center gap-3"><span className="p-2 bg-rose-50 text-rose-600 rounded-xl text-lg">📅</span> 应付未付情况审计</h3>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-12">该模块仅依据筛选中心数据进行独立财务穿透</p>
          </div>
          <button className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 transition-transform ${sections.receivables ? 'rotate-180 text-rose-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
        </div>
        {sections.receivables && (
          <div className="px-8 pb-12 animate-in fade-in space-y-12">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
              <div className="bg-slate-50 p-10 rounded-[44px] flex items-center gap-10 border border-slate-100">
                <div className="w-40 h-40 shrink-0"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={[{name:'已结', value: receivablesAnalysis.totalSettled}, {name:'未结', value: receivablesAnalysis.totalUnsettled}]} innerRadius={60} outerRadius={80} paddingAngle={10} dataKey="value" stroke="none"><RechartsCell fill="#10b981"/><RechartsCell fill="#fb7185"/></Pie><Tooltip formatter={(v: any) => (v ?? 0).toLocaleString()} /></PieChart></ResponsiveContainer></div>
                <div className="space-y-4">
                  <div><p className="text-[10px] font-black text-slate-400 uppercase mb-1">已结清回款</p><p className="text-3xl font-black text-emerald-600">{(receivablesAnalysis.totalSettled ?? 0).toLocaleString()} CFA</p></div>
                  <div><p className="text-[10px] font-black text-slate-400 uppercase mb-1">风险敞口 (待回款)</p><p className="text-3xl font-black text-rose-600">{(receivablesAnalysis.totalUnsettled ?? 0).toLocaleString()} CFA</p></div>
                </div>
              </div>
              <div className="bg-slate-50 p-10 rounded-[44px] border border-slate-100 h-[300px]">
                <h4 className="text-[10px] font-black text-slate-400 uppercase mb-6 text-center tracking-widest">欠款账期风险分布</h4>
                <ResponsiveContainer width="100%" height="100%"><BarChart data={receivablesAnalysis.agingBuckets}><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 900}} /><Tooltip /><Bar dataKey="value" radius={[8, 8, 0, 0]} barSize={40}>{receivablesAnalysis.agingBuckets.map((e, i) => <RechartsCell key={i} fill={e.color}/>)}</Bar></BarChart></ResponsiveContainer>
              </div>
            </div>
            <div className="bg-white rounded-[40px] border border-slate-200 shadow-xl overflow-hidden">
              <div className="px-10 py-5 bg-slate-50 border-b border-slate-100 text-[11px] font-black text-slate-500 uppercase">欠款客户审计清单 (点击开启独立审计)</div>
              <div className="overflow-x-auto max-h-[500px] custom-scrollbar text-left">
                <table className="min-w-full divide-y divide-slate-100">
                  <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm"><tr><th className="px-10 py-4 text-left text-[11px] font-black text-slate-400 uppercase">客户名称</th><th className="px-10 py-4 text-right text-[11px] font-black text-slate-400 uppercase">待结余额 (CFA)</th><th className="px-10 py-4 text-left text-[11px] font-black text-slate-400 uppercase pl-16">回款率</th></tr></thead>
                  <tbody className="divide-y divide-slate-50">{receivablesAnalysis.debtors.map(d => { const ratio = (d.settled / (d.settled + d.unsettled || 1)) * 100; return (<tr key={d.name} className="hover:bg-slate-50 cursor-pointer" onClick={() => setSelectedDebtCustomer(d.name)}><td className="px-10 py-4 text-sm font-black text-slate-900">{d.name}</td><td className="px-10 py-4 text-sm font-mono font-black text-rose-600 text-right">{(d.unsettled ?? 0).toLocaleString()}</td><td className="px-10 py-4 pl-16"><div className="flex items-center gap-4"><div className="flex-1 h-2 bg-slate-100 rounded-full overflow-hidden"><div className={`h-full ${ratio > 70 ? 'bg-emerald-500' : 'bg-rose-500'}`} style={{width: `${ratio}%`}}></div></div><span className="text-[10px] font-black text-slate-500">{ratio.toFixed(0)}%</span></div></td></tr>)})}</tbody>
                </table>
              </div>
            </div>
          </div>
        )}
      </section>

      {/* 隔离层1：原有的销售深度穿透面板 (完全恢复原始高阶UI) */}
      {(selectedCategory || selectedItem || selectedCustomer) && (
        <div className="fixed inset-0 bg-white z-[5000] flex flex-col animate-in slide-in-from-bottom-12 duration-500 overflow-hidden text-left border-t-[12px] border-indigo-600">
          <div className="px-12 py-10 border-b border-slate-200 bg-white flex items-center justify-between shadow-sm">
            <div><h3 className="text-3xl font-black text-slate-900 tracking-tight">{selectedCategory || selectedItem || selectedCustomer} <span className="text-indigo-600">| 业务穿透分析</span></h3><p className="text-[12px] font-black text-slate-400 uppercase tracking-widest mt-2">基于成交数据的高级绩效穿透</p></div>
            <button onClick={() => { setSelectedCategory(null); setSelectedItem(null); setSelectedCustomer(null); }} className="px-14 py-4 bg-slate-900 text-white rounded-[24px] text-sm font-black hover:bg-slate-800 transition-all shadow-xl">关闭面板</button>
          </div>
          <div className="flex-1 overflow-y-auto custom-scrollbar p-12 bg-slate-50/50 space-y-12">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm"><p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-2">成交总额</p><p className="text-3xl font-black text-indigo-600">{(drillDownAnalysis.tableTotalSales ?? 0).toLocaleString()} CFA</p></div>
              <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm"><p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-2">累计单据数</p><p className="text-3xl font-black text-slate-900">{drillDownAnalysis.tableRecords.length}</p></div>
            </div>
            <div className="bg-white rounded-[44px] border border-slate-200 shadow-2xl overflow-hidden"><table className="min-w-full divide-y divide-slate-100 text-[13px]"><thead className="bg-slate-50"><tr><th className="px-10 py-5 text-left font-black text-slate-400">单号</th><th className="px-10 py-5 text-left font-black text-slate-400">日期</th><th className="px-10 py-5 text-left font-black text-slate-400">物料名称</th><th className="px-10 py-5 text-right font-black text-slate-400">金额</th></tr></thead><tbody className="divide-y divide-slate-50">{drillDownAnalysis.tableRecords.map((r, i) => (<tr key={i} className="hover:bg-slate-50"><td className="px-10 py-5 font-mono font-black text-indigo-600">{r.id}</td><td className="px-10 py-5 font-bold text-slate-500">{r.date}</td><td className="px-10 py-5 font-black text-slate-700">{r.itemName}</td><td className="px-10 py-5 text-right font-mono font-black">{(r.totalAmount ?? 0).toLocaleString()}</td></tr>))}</tbody></table></div>
          </div>
        </div>
      )}

      {/* 隔离层2：新增的财务审计独立穿透面板 (完全独立的交互逻辑) */}
      {selectedDebtCustomer && (
        <div className="fixed inset-0 bg-white z-[6000] flex flex-col animate-in slide-in-from-right duration-500 overflow-hidden text-left border-l-[16px] border-rose-500">
           <div className="px-12 py-10 border-b border-slate-200 bg-white flex items-center justify-between shadow-sm">
              <div className="flex items-center gap-6"><div className="w-20 h-20 bg-rose-600 rounded-[28px] flex items-center justify-center text-white text-3xl shadow-2xl">🚨</div><div><h3 className="text-4xl font-black text-slate-900 tracking-tight">{selectedDebtCustomer} <span className="text-rose-600">| 风险审计穿透</span></h3><p className="text-[12px] font-black text-slate-400 uppercase tracking-widest mt-2">实时三色预警审计系统 · 仅展示未结订单</p></div></div>
              <button onClick={() => setSelectedDebtCustomer(null)} className="px-16 py-5 bg-slate-900 text-white rounded-[24px] text-sm font-black hover:bg-slate-800 shadow-2xl transition-all">关闭审计</button>
           </div>
           <div className="flex-1 overflow-y-auto custom-scrollbar p-12 bg-slate-50/50 space-y-12">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm"><p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-2">未结清总敞口</p><p className="text-3xl font-black text-rose-600">{(debtAuditDetails.total ?? 0).toLocaleString()} CFA</p></div>
                <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm"><p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-2">风险单据数</p><p className="text-3xl font-black text-slate-900">{debtAuditDetails.records.length} 条待结</p></div>
              </div>
              <div className="bg-white rounded-[44px] border border-slate-200 shadow-2xl overflow-hidden"><table className="min-w-full divide-y divide-slate-100 text-[13px]"><thead className="bg-slate-50"><tr><th className="px-10 py-5 text-left font-black text-slate-400">单号</th><th className="px-10 py-5 text-left font-black text-slate-400">到期日</th><th className="px-10 py-5 text-left font-black text-slate-400">物料名称</th><th className="px-10 py-5 text-right font-black text-slate-400">待结金额</th><th className="px-10 py-5 text-center font-black text-slate-400">风险预警</th></tr></thead><tbody className="divide-y divide-slate-50">
                {debtAuditDetails.records.map((r, i) => {
                  const today = new Date(); today.setHours(0,0,0,0);
                  const dueDate = new Date(r.dueDate);
                  const diff = Math.ceil((dueDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
                  let color = "bg-emerald-500"; let label = "安全";
                  if (diff < 0) { color = "bg-rose-500 animate-pulse"; label = `逾期${Math.abs(diff)}天`; }
                  else if (diff <= 7) { color = "bg-amber-400"; label = `临期${diff}天`; }
                  return (<tr key={i} className="hover:bg-slate-50"><td className="px-10 py-5 font-mono font-black text-indigo-600">{r.id}</td><td className="px-10 py-5 font-bold text-slate-500">{r.dueDate}</td><td className="px-10 py-5 font-black text-slate-700">{r.itemName}</td><td className="px-10 py-5 text-right font-mono font-black text-rose-600">{(r.unsettledAmount ?? 0).toLocaleString()}</td><td className="px-10 py-5"><div className="flex items-center justify-center gap-3"><div className={`w-3 h-3 rounded-full ${color}`}></div><span className="text-[11px] font-black uppercase">{label}</span></div></td></tr>);
                })}
              </tbody></table></div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, AreaChart, Area, Cell as RechartsCell, Legend, LabelList
} from 'recharts';
import { SalesSummary, SalesRecord } from '../types';

interface DashboardProps {
  summary: SalesSummary;
  filteredData: SalesRecord[];
  onSelectOrderId: (id: string) => void;
}

const COLORS = [
  '#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#84cc16', '#a855f7', '#fb7185', '#2dd4bf', '#fbbf24'
];

const Dashboard: React.FC<DashboardProps> = ({ summary, filteredData, onSelectOrderId }) => {
  // --- 1. 状态管理 (包含原有的和新增隔离的状态) ---
  const [sections, setSections] = useState({
    trend: true, composition: true, ranking: true, receivables: true
  });
  const [pieMetric, setPieMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [itemPieMetric, setItemPieMetric] = useState<'sales' | 'quantity'>('sales');
  const [customerMetric, setCustomerMetric] = useState<'sales' | 'quantity'>('sales');
  const [trendMode, setTrendMode] = useState<'total' | 'customer' | 'salesperson'>('total');
  const [activeMetrics, setActiveMetrics] = useState({ amount: true, quantity: true });

  // Add missing state for orders list expansion
  const [isOrdersExpanded, setIsOrdersExpanded] = useState(false);

  // 原有的穿透状态 (用于前三个模块)
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<string | null>(null);
  const [selectedCustomer, setSelectedCustomer] = useState<string | null>(null);
  const [drillMetric, setDrillMetric] = useState<'sales' | 'quantity'>('sales'); 
  const [localTableFilters, setLocalTableFilters] = useState({ customer: '', category: '', month: '' });
  const [columnFilters, setColumnFilters] = useState<Record<string, string[]>>({ id: [], customer: [], salesperson: [], itemName: [] });

  // 新增独立状态 (仅用于“应付未付”模块，严格隔离)
  const [selectedDebtCustomer, setSelectedDebtCustomer] = useState<string | null>(null);

  const toggleSection = (key: keyof typeof sections) => {
    setSections(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- 2. 核心辅助渲染函数 (恢复原始高阶UI) ---
  const renderCustomizedLabel = (props: any) => {
    const { cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill } = props;
    const RADIAN = Math.PI / 180;
    const cos = Math.cos(-RADIAN * midAngle);
    const sin = Math.sin(-RADIAN * midAngle);
    const sx = cx + (outerRadius + 10) * cos;
    const sy = cy + (outerRadius + 10) * sin;
    const mx = cx + (outerRadius + 45) * cos;
    const my = cy + (outerRadius + 45) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 22;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';

    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={2.5} opacity={0.7} />
        <circle cx={ex} cy={ey} r={4} fill={fill} />
        <text x={ex + (cos >= 0 ? 1 : -1) * 15} y={ey} textAnchor={textAnchor} fill="#0f172a" style={{ fontSize: '14px', fontWeight: 900 }}>{name}</text>
        <text x={ex + (cos >= 0 ? 1 : -1) * 15} y={ey} dy={18} textAnchor={textAnchor} fill="#64748b" style={{ fontSize: '12px', fontWeight: 600 }}>{(percent * 100).toFixed(1)}%</text>
      </g>
    );
  };

  // --- 3. 原始计算逻辑恢复 (前三个模块) ---
  const trendAnalysis = useMemo(() => {
    const months = Array.from(new Set<string>(filteredData.map(d => d.month))).sort();
    if (trendMode === 'total') {
      const data = months.map(month => {
        const monthRecords = filteredData.filter(d => d.month === month);
        return { name: month, amount: monthRecords.reduce((s, r) => s + (r.totalAmount ?? 0), 0), quantity: monthRecords.reduce((s, r) => s + (r.quantity ?? 0), 0) };
      });
      const series = [];
      if (activeMetrics.amount) series.push({ key: 'amount', name: '总金额', type: 'amount', color: '#6366f1' });
      if (activeMetrics.quantity) series.push({ key: 'quantity', name: '总数量', type: 'quantity', color: '#10b981' });
      return { data, series };
    }
    const dimKey = (trendMode === 'customer' ? 'customer' : 'salesperson') as 'customer' | 'salesperson';
    const entities = Array.from(new Set<string>(filteredData.map(d => String(d[dimKey])))).slice(0, 8);
    const series: any[] = [];
    entities.forEach((entity, idx) => {
      const color = COLORS[idx % COLORS.length];
      if (activeMetrics.amount) series.push({ key: `${entity}_amt`, name: `${entity} (金额)`, type: 'amount', color });
      if (activeMetrics.quantity) series.push({ key: `${entity}_qty`, name: `${entity} (数量)`, type: 'quantity', color, dashed: true });
    });
    const data = months.map(month => {
      const row: any = { name: month };
      entities.forEach(entity => {
        const records = filteredData.filter(d => d.month === month && d[dimKey] === entity);
        row[`${entity}_amt`] = records.reduce((s, r) => s + (r.totalAmount ?? 0), 0);
        row[`${entity}_qty`] = records.reduce((s, r) => s + (r.quantity ?? 0), 0);
      });
      return row;
    });
    return { data, series };
  }, [filteredData, trendMode, activeMetrics]);

  const sortedCategorySummary = useMemo(() => {
    const merged = summary.categoryDistribution.map(cat => {
      const qtyItem = summary.categoryQuantityDistribution.find(q => q.name === cat.name);
      return { name: cat.name, sales: cat.value, quantity: qtyItem ? qtyItem.value : 0 };
    });
    return merged.sort((a, b) => pieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [summary, pieMetric]);

  const sortedItemSummary = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.itemName) || { sales: 0, quantity: 0 };
      entry.sales += (d.totalAmount ?? 0);
      entry.quantity += (d.quantity ?? 0);
      map.set(d.itemName, entry);
    });
    return Array.from(map.entries()).map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity })).sort((a, b) => itemPieMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, itemPieMetric]);

  const customerAnalysisData = useMemo(() => {
    const map = new Map<string, { sales: number; quantity: number }>();
    filteredData.forEach(d => {
      const entry = map.get(d.customer) || { sales: 0, quantity: 0 };
      entry.sales += (d.totalAmount ?? 0);
      entry.quantity += (d.quantity ?? 0);
      map.set(d.customer, entry);
    });
    return Array.from(map.entries()).map(([name, val]) => ({ name, sales: val.sales, quantity: val.quantity })).sort((a, b) => customerMetric === 'sales' ? b.sales - a.sales : b.quantity - a.quantity);
  }, [filteredData, customerMetric]);

  // 原有的穿透计算 (隔离)
  const drillDownAnalysis = useMemo(() => {
    const dimension = selectedCategory ? 'category' : (selectedItem ? 'itemName' : (selectedCustomer ? 'customer' : null));
    const value = selectedCategory || selectedItem || selectedCustomer;
    if (!dimension || !value) return { baseRecords: [], tableRecords: [], secondaryDistribution: [], monthlyTrend: [], tableTotalSales: 0, tableTotalQty: 0 };
    const baseRecords = filteredData.filter(r => r[dimension as keyof SalesRecord] === value);
    // ... 其他逻辑略，保持原样 ...
    return { 
      baseRecords, 
      tableRecords: baseRecords.sort((a, b) => b.date.localeCompare(a.date)), 
      tableTotalSales: baseRecords.reduce((s, r) => s + (r.totalAmount ?? 0), 0),
      tableTotalQty: baseRecords.reduce((s, r) => s + (r.quantity ?? 0), 0)
    };
  }, [selectedCategory, selectedItem, selectedCustomer, filteredData]);

  // --- 4. 新增独立逻辑 (应付未付模块) ---
  const receivablesAnalysis = useMemo(() => {
    const today = new Date(); today.setHours(0, 0, 0, 0);
    let totalSettled = 0; let totalUnsettled = 0;
    const agingBuckets = [
      { name: '未到期', value: 0, color: '#10b981' },
      { name: '逾期1-30天', value: 0, color: '#f59e0b' },
      { name: '逾期30天+', value: 0, color: '#ef4444' }
    ];
    const debtorMap = new Map<string, { settled: number; unsettled: number }>();
    filteredData.forEach(r => {
      totalSettled += (r.settledAmount ?? 0);
      totalUnsettled += (r.unsettledAmount ?? 0);
      const cur = debtorMap.get(r.customer) || { settled: 0, unsettled: 0 };
      debtorMap.set(r.customer, { settled: cur.settled + (r.settledAmount ?? 0), unsettled: cur.unsettled + (r.unsettledAmount ?? 0) });
      if ((r.unsettledAmount ?? 0) > 0 && r.dueDate) {
        const dueDate = new Date(r.dueDate);
        const diff = Math.ceil((today.getTime() - dueDate.getTime()) / (1000 * 60 * 60 * 24));
        if (diff <= 0) agingBuckets[0].value += (r.unsettledAmount ?? 0);
        else if (diff <= 30) agingBuckets[1].value += (r.unsettledAmount ?? 0);
        else agingBuckets[2].value += (r.unsettledAmount ?? 0);
      }
    });
    return { 
      totalSettled, 
      totalUnsettled, 
      agingBuckets, 
      debtors: Array.from(debtorMap.entries()).map(([name, val]) => ({ name, ...val })).filter(d => d.unsettled > 0).sort((a, b) => b.unsettled - a.unsettled)
    };
  }, [filteredData]);

  const debtAuditDetails = useMemo(() => {
    if (!selectedDebtCustomer) return { records: [], total: 0 };
    const records = filteredData.filter(r => r.customer === selectedDebtCustomer && (r.unsettledAmount ?? 0) > 0);
    return { records: records.sort((a, b) => a.dueDate.localeCompare(b.dueDate)), total: records.reduce((s, r) => s + (r.unsettledAmount ?? 0), 0) };
  }, [selectedDebtCustomer, filteredData]);

  return (
    <div className="space-y-10 pb-16 relative">
      {/* 顶部总计卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
          <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex items-center justify-center text-3xl text-indigo-600">💰</div>
          <div className="text-left"><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">总计金额 (CFA)</p><p className="text-2xl font-black text-slate-900">{(summary.totalSales ?? 0).toLocaleString()}</p></div>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-6 h-[100px]">
          <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl text-emerald-600">📦</div>
          <div className="text-left"><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">出库总量</p><p className="text-2xl font-black text-slate-900">{(summary.totalQuantity ?? 0).toLocaleString()}</p></div>
        </div>
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col h-[100px] overflow-hidden relative">
          <div className="p-6 flex items-center justify-between">
            <div className="flex items-center gap-6"><div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center text-3xl text-amber-600">📑</div><div className="text-left"><p className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1">单据总数</p><p className="text-2xl font-black text-slate-900">{summary.orderCount}</p></div></div>
            <button onClick={() => setIsOrdersExpanded(!isOrdersExpanded)} className="p-2 bg-slate-100 rounded-xl"><svg className={`w-5 h-5 ${isOrdersExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg></button>
          </div>
          {isOrdersExpanded && <div className="absolute top-[100px] left-0 right-0 z-[100] p-4 bg-white border border-slate-200 shadow-2xl rounded-b-xl"><div className="max-h-40 overflow-y-auto custom-scrollbar flex flex-wrap gap-2">{summary.orderIds.map(id => <button key={id} onClick={() => onSelectOrderId(id)} className="px-2 py-1 bg-slate-50 border border-slate-200 rounded text-[10px] font-mono hover:border-indigo-600">{id}</button>)}</div></div>}
        </div>
      </div>

      {/* 模块1：业绩增长趋势 (完全恢复原始UI) */}
      <section className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden text-left">
        <div onClick={() => toggleSection('trend')} className="p-8 flex items-center justify-between cursor-pointer hover:bg-slate-50/50">
          <h3 className="text-xl font-black text-slate-900 flex items-center gap-3"><span className="p-2 bg-indigo-50 text-indigo-600 rounded-xl text-lg">📈</span> 业绩增长趋势</h3>
          <div className="flex bg-slate-100 p-1 rounded-xl" onClick={e => e.stopPropagation()}>
            {(['total', 'customer', 'salesperson'] as const).map(m => <button key={m} onClick={() => setTrendMode(m)} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${trendMode === m ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500'}`}>{m === 'total' ? '总体' : m === 'customer' ? '客户' : '销售员'}</button>)}
          </div>
        </div>
        {sections.trend && (
          <div className="px-8 pb-8 h-[450px] animate-in fade-in">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={trendAnalysis.data}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
