            <span className="p-2 bg-indigo-50 text-indigo-600 rounded-xl text-lg">📈</span> 业绩增长趋势
          </h3>
          <div className="flex items-center gap-6" onClick={(e) => e.stopPropagation()}>
            {sections.trend && (
              <div className="hidden md:flex flex-wrap items-center gap-4">
                <div className="flex bg-slate-100 p-1 rounded-2xl border border-slate-200 shadow-inner">
                   <button onClick={() => setActiveMetrics({ amount: true, quantity: false })} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${activeMetrics.amount && !activeMetrics.quantity ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>金额</button>
                   <button onClick={() => setActiveMetrics({ amount: false, quantity: true })} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${!activeMetrics.amount && activeMetrics.quantity ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>数量</button>
                   <button onClick={() => setActiveMetrics({ amount: true, quantity: true })} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${activeMetrics.amount && activeMetrics.quantity ? 'bg-white shadow-md text-slate-900' : 'text-slate-500'}`}>双轴</button>
                </div>
                <div className="flex bg-slate-100 p-1 rounded-2xl border border-slate-200 shadow-inner">
                  <button onClick={() => setTrendMode('total')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'total' ? 'bg-white shadow-md text-slate-900' : 'text-slate-500'}`}>汇总</button>
                  <button onClick={() => setTrendMode('customer')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'customer' ? 'bg-white shadow-md text-indigo-700' : 'text-slate-500'}`}>客户</button>
                  <button onClick={() => setTrendMode('salesperson')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${trendMode === 'salesperson' ? 'bg-white shadow-md text-emerald-700' : 'text-slate-500'}`}>销售</button>
