    // 仅计算未结总额用于Header展示
    const totalUnsettled = records.reduce((s, r) => s + (r.unsettledAmount ?? 0), 0);

    return {
      records: records.sort((a, b) => (a.dueDate || '').localeCompare(b.dueDate || '')),
