                {debtAuditDetails.records.map((r, i) => {
                  const unsettled = r.unsettledAmount ?? 0;
                  const today = new Date(); today.setHours(0,0,0,0);
                  const dueDate = r.dueDate ? new Date(r.dueDate) : today;
                  const diff = Math.ceil((dueDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));

                  let statusNode;
                  if (unsettled <= 0) {
                     statusNode = <div className="flex items-center justify-center gap-2"><div className="w-2.5 h-2.5 rounded-full bg-slate-300"></div><span className="text-[11px] font-bold text-slate-400">已结清</span></div>;
                  } else if (diff < 0) {
                     statusNode = <div className="flex items-center justify-center gap-2"><div className="w-2.5 h-2.5 rounded-full bg-rose-500 animate-pulse"></div><span className="text-[11px] font-black text-rose-600">逾期 {Math.abs(diff)} 天</span></div>;
                  } else if (diff <= 7) {
                     statusNode = <div className="flex items-center justify-center gap-2"><div className="w-2.5 h-2.5 rounded-full bg-amber-400"></div><span className="text-[11px] font-black text-amber-600">临期 {diff} 天</span></div>;
                  } else {
                     statusNode = <div className="flex items-center justify-center gap-2"><div className="w-2.5 h-2.5 rounded-full bg-emerald-500"></div><span className="text-[11px] font-black text-emerald-600">安全期内</span></div>;
                  }

                  return (<tr key={i} className="hover:bg-slate-50"><td className="px-10 py-5 font-mono font-black text-indigo-600">{r.id}</td><td className="px-10 py-5 font-bold text-slate-500">{r.dueDate}</td><td className="px-10 py-5 font-black text-slate-700">{r.itemName}</td><td className={`px-10 py-5 text-right font-mono font-black ${unsettled > 0 ? 'text-rose-600' : 'text-slate-300'}`}>{(unsettled).toLocaleString()}</td><td className="px-10 py-5">{statusNode}</td></tr>);
                })}
              </tbody></table></div>
