      {debtAuditDetails && (
        <div className={`fixed inset-0 bg-white z-[6000] flex flex-col animate-in slide-in-from-right duration-500 overflow-hidden text-left border-l-[16px] border-${debtAuditDetails.themeColor}-500`}>
